P.entries["npc:eleanor-shackleton"] = {n="Елеанор Шеклтон",s="Елеанор Шеклтон — мандрівниця з Відступників, що отаборилася на південний захід від Брілла на Галявинах Тірісфалю. Замість сидіти в місті чи в Андерсіті, вона допомагає мандрівникам опановувати виживання в дикій природі й похідні ремесла. Її прізвище носять й інші Відступники, що вціліли в цьому краї, — натяк на зв'язки, збережені з життя до чуми.",h="Елеанор Шеклтон — мандрівниця з Відступників, що отаборилася на південний захід від Брілла на Галявинах...",kw={"елеанор шеклтон","виживання","табір","похідна кухня","брілл","тірісфаль"},ang={["profession:Cooking"]="Уроки Елеанор охоплюють розпалювання похідного багаття й приготування їжі далеко від цивілізованих вогнищ, тож її табір — важлива зупинка для мандрівних кухарів.",["race:Undead"]="Для Відступників життєво важливо вміти виживати в дикій природі без вигод живих, і Елеанор дбає, щоб щойно підняті побратими швидко звикли до суворого побуту в Тірісфалі."},sec={{t="Провідниця Галявинами",b="Поки багато щойно пробуджених Відступників прямують просто до Брілла чи спускаються в Андерсіті, Елеанор Шеклтон розбиває табір у примарних лісах на південному заході. Виживання в Тірісфалі вимагає практичної самостійності, і Елеанор навчає шукачів пригод-початківців жити з ураженої землі. У своїх польових уроках вона показує мандрівникам, як облаштовувати табір, збирати хмиз і не занедбувати ремесла далеко від кузень і кухонь цивілізації."},{t="Зв'язки з минулого життя",b="У розтрощених рештках Лордерону родинні імена часто лишаються єдиною ниткою, що пов'язує мерця з його смертним минулим. Елеанор носить прізвище Шеклтон — як і Пірс Шеклтон у Бріллі та Саманта Шеклтон деінде в Тірісфалі. Чи підтримують ці троє тісні узи, чи лише мають спільне коріння зі смертних днів, кожен із них знайшов власну роль у служінні справі Відступників по всьому ураженому королівству."}},faq={{q="Де знайти Елеанор Шеклтон?",a="Елеанор Шеклтон отаборилася на південний захід від Брілла, у лісах Галявин Тірісфалю, подалі від головного брукованого шляху.",al={"місце елеанор шеклтон","де елеанор","місце шеклтон"}},{q="Чого Елеанор Шеклтон навчає шукачів пригод?",a="Елеанор навчає мандрівників основ виживання в дикій природі: як ставати табором, добувати їжу й займатися ремеслами просто неба.",al={"завдання елеанор","що робить елеанор","завдання кемпінгу тирисфаль"}},{q="Чи родичка Елеанор інших Шеклтонів у Лордероні?",a="Вона має те саме прізвище, що й Пірс Шеклтон із Брілла та Саманта Шеклтон, а це натякає на можливу спорідненість з часів, коли королівство ще не впало під ударами Погибелі.",al={"пірс шеклтон родич","саманта шеклтон","лор родини шеклтон"}},{q="Чому вона стає табором за Бріллом, а не живе в містечку?",a="Елеанор зосереджена на польових навичках і виживанні в дикій природі. Табір у лісі дає їй змогу зустрічати мандрівників і навчати їх просто там, де ці навички потрібні.",al={"чому табір за бріллом","табір елеанор шеклтон"}}},fp="18,356,21.516.0,21.435.0,36.125.0,47.154.0,53.169.0,60.171.0"}
P.entries["npc:electrocutioner-6000"] = {n="Електрокутор 6000",s="Електрокутор 6000 — смертоносний, надзаряджений павукоподібний танк, що обороняє Стартовий відсік в опромінених залах Гномреґана. Ним керує горезвісний гном-прокажений лейтенант Том «Шкварчоштан» Кренкл, і ця машина втілює безрозсудне прагнення Мехінженера Термаплаґа перетворити струм високої напруги на зброю.",h="Електрокутор 6000 — смертоносний, надзаряджений павукоподібний танк, що обороняє Стартовий відсік в...",kw={"електрокутор 6000","павукоподібний танк","шкварчоштан","термаплаґ","стартовий відсік","гномреґан"},ang={["faction:Alliance"]="Прорватися до Стартового відсіку й знищити Кренкла конче потрібно, щоб здобути Ключ від Майстерні й обійти небезпечні передні коридори під час визволення Гномреґана.",["profession:Engineering"]="Інженери дивуються сирій потужності струму високої напруги, яку вдалося приборкати в шасі, хоча безрозсудна відмова Термаплаґа від заземлення робить машину смертельно небезпечною для власного екіпажу.",["race:Gnome"]="Для гномів-вигнанців в Айронфорджі Електрокутор 6000 — образа для їхнього ремесла: небезпечна неперевірена потвора, що відображає спотворену зневагу Термаплаґа до інженерної етики й до життя гномів."},sec={{t="Приголомшливий прототип Термаплаґа",b="Мехінженер Термаплаґ ніколи не славився ретельними випробуваннями на безпеку. Гнаний манією величі й поспіхом, він раз у раз кидає неперевірені бойові машини просто з креслярської дошки в бій. Електрокутор 6000 став його першою спробою приборкати сирий електричний струм як наступальну систему на броньованому павукоподібному шасі. Замість налагодити смертельні стрибки напруги в лабораторії, Термаплаґ одразу послав машину стерегти верхні яруси Стартового відсіку Гномреґана."},{t="Лейтенант «Шкварчоштан»",b="Керувати експериментальними машинами часто означає підписати собі смертний вирок, особливо коли йдеться про смертельну напругу. Перші випробувачі загинули в болісних аваріях, але лейтенант Том Кренкл зумів витримати смертельні розряди й вижив за важелями. Здобувши похмуре прізвисько «Шкварчоштан», він став кумиром стійкості серед опромінених гномів-прокажених, вірних Термаплаґові, і люто стереже шлях до внутрішніх майстерень."}},faq={{q="Де знайти Електрокутора 6000?",a="Електрокутор 6000 стоїть на піднятому містку над Стартовим відсіком у занепалому Гномреґані.",al={"місце електрокутора 6000","де електрокутор","знайти електрокутора 6000"}},{q="Хто керує Електрокутором 6000?",a="Ним керує Лейтенант Том Кранкл, відоміший як «Смаленоштан». Це божевільний гном-прокажений офіцер, що прославився серед сил Термаплаґа як єдиний пілот, який пережив небезпечні внутрішні електричні розряди цього танка.",al={"хто керує електрокутором 6000","сіззлпентс","том сіззлпентс кренкл","пілот електрокутора"}},{q="Чому машина така нестійка?",a="Мехінженер Термаплаґ не хоче марнувати час на належні перевірки безпеки й поспіхом пускає винаходи в діло. Електрокутор 6000 став його першою спробою створити електрифікований павукоподібний танк, тож його смертоносні силові лінії лишилися нестійкими й небезпечними навіть для власного пілота.",al={"чому б'є струмом","прототип електрокутора","конструкція термаплаґа"}},{q="Чому для дослідників важливо здолати Електрокутора 6000?",a="Пілот має Ключ від Майстерні — важливий пристрій, що відмикає чорний хід до глибших інженерних секторів Гномреґану й дає загонам швидший шлях крізь відвойовані приміщення.",al={"ключ майстерні","чому вбивати електрокутора","здобич електрокутора 6000"}},{q="Електрокутор — автоматон чи машина?",a="Це видозмінений павукоподібний танк — броньована механічна машина, якою пілот керує вручну з внутрішньої кабіни, а не самостійний робот.",al={"чи електрокутор робот","тип павука-танка"}}},fp="20,310,32.492.0,24.433.0,44.135.0,36.234.0,31.294.0,66.206.0,49.171.0"}
P.entries["npc:elling-trias"] = {n="Еллінг Тріас",s="Еллінг Тріас тримає крамничку «Сири Тріаса» в гомінкому Торговому Кварталі Стормвінда. Він видає себе за веселого й завзятого торговця сирами, але потай є одним із найобізнаніших посередників у торгівлі відомостями в королівстві. За сирними головками й привітними балачками Тріас тримає вухо при землі, і його слух сягає через континенти.",h="Еллінг Тріас тримає крамничку «Сири Тріаса» в гомінкому Торговому Кварталі Стормвінда.",kw={"еллінг тріас","сири","торговий квартал","інформатор","si:7","стормвінд"},ang={["class:Rogue"]="Кожен майстер тонкої справи розуміє, що сирна крамниця Еллінга — ідеальний тайник. Поруч Старе Місто, а тісні зв'язки з Матіасом Шоу роблять його невіддільною частиною підпільного світу Стормвінда.",["faction:Alliance"]="Еллінг — неоспівана опора розвідки Альянсу: він тихо просіює чутки від Терамора до Гартглена, щоб захистити королівство від внутрішньої гнилі."},sec={{t="Майстер сирної справи",b="Для випадкового покупця, що прогулюється Торговим Кварталом, Еллінг Тріас — просто майстер, відданий добірним сирам, який веде крамницю разом із дружиною Елейн і сином Беном. Він завзято розхвалює сирні головки й привітно балакає з містянами. Та обізнані люди знають: «Сири Тріаса» — одне з найнадійніших прикриттів у Стормвінді. Невпинний гомін міської торгівлі ідеально приховує агентів, придворних і шукачів пригод, яким треба перекинутися тихим словом, не привертаючи уваги міської варти."},{t="Мережа шепотів",b="Мережа інформаторів і союзників Еллінга вражає як на крамаря. Він підтримує зв'язок із Майстром Матіасом Шоу з SI:7, співпрацює з церковними знайомими на кшталт Єпископа ДеЛаве й листується з агентами аж у Даркширі, на Острові Терамор і в далеких Чумних Землях біля Гартглена. Коли спливають дивні чутки — про розбійників на дорогах чи тихі рухи в провінції, — Тріас часто складає мозаїку задовго до того, як королівський двір щось помітить."},{t="Зниклий дипломат",b="Коли високопоставлений дипломат зникає під час подорожі до Терамора, Еллінг Тріас стає важливою опорою в розплутуванні змови. Скеровуючи слідчих до своїх знайомих — зокрема до відчуженого агента на ім'я Йорґен і давнього друга Тиріона, — Тріас допомагає викрити руку Братства Дефіас у викраденні. Попри гострий розум і цинічні жарти, Еллінг розуміє, що змова сягає самого серця аристократії Стормвінда."}},faq={{q="Хто такий Еллінг Тріас?",a="З вигляду Еллінг Тріас — продавець сиру, що разом із родиною тримає крамницю «Сири Тріаса» в Торговому Кварталі Стормвінда. Під цим прикриттям він — досвідчений торговець відомостями, пов'язаний із SI:7, Церквою та віддаленими заставами по всьому Азероту.",al={"хто такий еллінг","особа еллінга тріаса","сирний чоловік тріас"}},{q="Де його сирна крамниця?",a="«Сири Тріаса» можна знайти в Торговому Кварталі Стормвінда, у ряду крамниць уздовж зовнішньої стіни каналу, біля межі зі Старим Містом.",al={"сирна крамниця тріаса","де еллінг тріас","крамниця тріаса стормвінд"}},{q="Що пов'язує його з Братством Дефіас?",a="Тріас не член Братства Дефіас — навпаки, він стежить за його діями через свою мережу інформаторів. Він допомагає шукачам пригод з Альянсу простежити причетність Дефіасу до підривних змов, зокрема до викрадення королівського дипломата.",al={"тріас дефіас","чи тріас у дефіас"}},{q="Звідки він знає Матіаса Шоу?",a="Еллінг тісно співпрацює з Майстром Матіасом Шоу та розвідувальною службою SI:7. Його крамниця — неофіційний пост підслуховування, звідки можна непомітно починати розслідування поза офіційними королівськими каналами.",al={"тріас і шоу","тріас сі7","чи тріас сі7"}},{q="Хто тримає крамницю разом із ним?",a="Еллінг тримає «Сири Тріаса» разом із дружиною, Елейн Тріас, і сином, Беном Тріасом. Разом вони підтримують вигляд гамірної звичайної родинної крамниці.",al={"родина тріасів","дружина еллінга тріаса"}},{q="Яка його роль у розслідуванні зникнення дипломата?",a="Слідчі, яких до Тріаса посилає Єпископ ДеЛаве, користуються широкою мережею зв'язків Еллінга, зокрема його давніми знайомими Йорґеном і Тиріоном, щоб простежити дії Дефіасу й з'ясувати, хто захопив дипломата, що прямував до Терамора.",al={"зниклий дипломат тріас","чому відвідати сирну крамницю"}}},fp="12,377,23.523.0,17.478.0,20.442.1,20.243.0,33.161.0,49.235.1,30.211.0,27.163.0,62.220.1"}
P.entries["npc:elu"] = {n="Елу",s="Елу — учень вершника вітрокрилів на Заставі Вільного Вітру в Тисячі Голок. Він палко мріє почати справжнє навчання й піднятися в небо, тож доручає мандрівникам з Орди роздобути яйця диких віверн із довколишніх гніздовищ.",h="Елу — учень вершника вітрокрилів на Заставі Вільного Вітру в Тисячі Голок.",kw={"елу","вітрокрили","віверни","застава вільного вітру","високосід","яйця віверн"},ang={["faction:Horde"]="Збираючи яйця віверн для Елу, ви прямо зміцнюєте мережу гінців і перевезень Орди, що тримає віддалені застави Калімдору на зв'язку повітрям.",["race:Tauren"]="Для шукачів пригод-тауренів допомога Елу — підтримка одноплемінника, що прагне опанувати давнє й життєво важливе мистецтво приборкання віверн високо над каньйонами предків."},sec={{t="Завзятий учень",b="Високо над солончаками й дном каньйону, на Заставі Вільного Вітру, Елу днями доглядає крилатих їздових звірів поселення й мріє про власний політ. Юний учень-таурен прагне стати в лави досвідчених вершників вітрокрилів, що патрулюють високі столові гори Калімдору. Та перш ніж почати справжнє льотне навчання, він мусить довести свою спроможність — поповнити гніздовище свіжим молодняком віверн. Тож він посилає вправних шукачів пригод по цілі яйця до лютих диких віверн, що гніздяться на Високосіді."}},faq={{q="Хто такий Елу?",a="Елу — таурен, учень господаря вітрокрилів на Заставі Вільного Вітру в Тисячі Голок, що допомагає добувати й вирощувати нових скакунів для повітряної мережі Орди.",al={"елу застава вільного вітру","хто такий елу","таурен-учень елу"}},{q="Навіщо Елу яйця віверн?",a="Елу має поповнити стайню віверн для майстрів-вершників. Вирощуючи звірів зі свіжозібраних яєць, можна як слід навчити їх і зріднити з вершниками, щоб вони стали надійними скакунами Орди.",al={"навіщо яйця виверн","завдання елу виверни","мета завдання елу"}},{q="Куди Елу посилає шукачів пригод по яйця?",a="Він посилає шукачів пригод на Високосід — небезпечну столову гору на заході Тисячі Голок, де колонії диких віверн люто стережуть свої гнізда.",al={"де яйця виверн","де хайперч","місце яєць елу"}}},fp="3,217,19.520.0,11.169.0,30.209.0,45.140.0"}
P.entries["npc:eva-sarkhoff"] = {n="Ева Саркгофф",s="Ева Саркгофф — примарний відгомін колишньої старшої покоївки Дому Баровів; разом зі своїм чоловіком Люсьєном вона блукає неподалік від жахів Сколомансії. Її закатував і вбив Різник під час падіння Каер Дарроу, і тепер її дух шукає відважних смертних, які помстяться за їхню смерть і знищать їхні прокляті останки.",h="Ева Саркгофф — примарний відгомін колишньої старшої покоївки Дому Баровів; разом зі своїм чоловіком Люсьєном...",kw={"ева саркгофф","люсьєн","дім баровів","каер дарроу","сколомансія","різник","привид"},ang={["class:Priest"]="Нескінченні муки Еви й Люсьєна суворо нагадують про жорстокість Погибелі: ті, хто служить святому, мусять дарувати спокій їхнім неупокоєним душам і очистити мерзенну магію, що їх сковує.",["race:Human"]="Ева та її чоловік — звичайні слуги Лордерону, яких зрадила власна зіпсута аристократія, коли Дім Баровів продав Каер Дарроу Кел'Тузадові."},sec={{t="Падіння Дому Баровів",b="Десятиліттями Ева служила заможній родині Баровів старшою покоївкою й разом зі своїм чоловіком Люсьєном, родинним дворецьким, доглядала розлогу твердиню Каер Дарроу. Та що старшими ставали Барови, то дужче їх гризли страх смерті й тривога за свої величезні статки, — і вони уклали згубну угоду з Кел'Тузадом. Маєток поступово перейшов до рук молодого Культу Проклятих, і пишна садиба перетворилася на Сколомансію — таємну академію некромантії. Півроку Ева з Люсьєном ховалися в коридорах твердині, добуваючи собі їжу й безсило дивлячись, як культисти й потвори крок за кроком захоплюють їхній дім."},{t="Скальпель Різника",b="Зрештою Погибель їх виявила, і Еву з Люсьєном віддали в руки Доктора Теолена Крастінова, відомого як Різник. Тижнями Крастінов катував їх своїми дослідами, темною магією продовжуючи їм життя далеко за межу смертної витривалості. Навіть по смерті їхні тіла згодували гулям, а неспокійні духи прикували до Каер Дарроу, — і тепер Ева благає мандрівних шукачів пригод убити Крастінова й спалити їхні останки."}},faq={{q="Ким була Ева Саркгофф до смерті?",a="Ева Саркгофф була старшою покоївкою шляхетної родини Баровів і десятиліттями жила й працювала у фортеці Каер Дарроу разом із чоловіком, Люсьєном, що служив дворецьким.",al={"історія еви саркгофф","хто така ева саркгофф","лор еви"}},{q="Як загинула Ева?",a="Після місяців переховування від Культу Проклятих Еву й Люсьєна знайшли й віддали Докторові Теолену Крастінову. Крастінов тижнями нещадно катував їх, підтримуючи в них життя темною магією, доки вони зрештою не померли, а їхні тіла згодували гулям.",al={"як ева померла","смерть еви саркгофф","хто вбив еву"}},{q="Чому привид Еви досі в Каер Дарроу?",a="Муки Еви були такі жахливі й неприродні, що її дух лишається прикутим до смертного світу. Вона не зможе відійти у вічність, доки Доктора Крастінова не вб'ють, а її тілесні рештки в Сколомансії не спалять.",al={"чому ева привид","дух еви","чому ева лишилася"}}},fp="12,310,23.585.0,21.483.1,37.171.0,16.272.0,40.211.0"}
P.entries["npc:executor-arren"] = {n="Екзекутор Аррен",s="Екзекутор Аррен — високопоставлений офіцер Відступників в Похоронному Подзвоні. Він наглядає за безпосередньою обороною й зміцненням поселення, поки щойно пробуджені мерці виходять зі своїх могил. Аррен керує місцевою кампанією проти безтямних зомбі Погибелі, здичавілих звірів і фанатиків Багряного Хрестового Походу, що насуваються.",h="Екзекутор Аррен — високопоставлений офіцер Відступників в Похоронному Подзвоні.",kw={"екзекутор аррен","похоронний подзвін","командир","багряний хрестовий похід","погибель","відступники","тірісфаль"},ang={["faction:Horde"]="Передові накази Аррена в Похоронному Подзвоні — це перший плацдарм Орди в північному Лордероні, що забезпечує виживання серед ворожого оточення.",["race:Undead"]="Екзекутор Аррен — один із перших командирів, яких зустрічає кожен Відступник, вийшовши в Тірісфаль; він дає перший смак обов'язку на службі Темної Леді."},sec={{t="Командир Похоронного Подзвону",b="Непохитно стоячи одразу біля каплиці в Похоронному Подзвоні, Екзекутор Аррен — головний військовий голос молодих Відступників на землях їхнього пробудження. Поки доглядачі в склепах виводять щойно воскреслих мерців із заціпеніння, Аррен спрямовує їхню увагу назовні — на виживання. Під прапором Королеви Сильвани Віндраннер він організовує місцеві операції, щоб вимести безтямних зомбі, які загрожують межам села, і закріпити безпечну землю в тіні падіння Лордерона."},{t="Убезпечення прикордоння",b="Похоронний Подзвін оточують небезпеки куди смертоносніші за розгублених новачків. За наказом Аррена розвідники й посвячувані б'ють лютих павуків, що населяють Лощину Нічної Павутини, і знищують небезпечних хижаків на лісових узліссях. Вимагаючи рішучих дій від кожної здібної руки, Аррен випробовує стійкість новоприбулих, аби на службі Темної Леді лишалися тільки ті, хто здатен захистити свій другий шанс на існування."},{t="Багряна загроза",b="Найбільша стратегічна турбота Аррена — Багряний Хрестовий Похід. Фанатики вважають усю нежить чудовиськами, які належить винищити повністю, не вміючи чи не бажаючи відрізняти Погибель від вільних Відступників. Аррен організовує точкові удари по багряних патрулях, що отаборилися в нетрях Тірісфалю, перехоплює гінців і вивчає викрадені депеші, щоб уберегти Похоронний Подзвін від очищення святим вогнем."}},faq={{q="Хто такий Екзекутор Аррен?",a="Екзекутор Аррен — військовий командир, що керує Похоронним Подзвоном на Галявинах Тірісфалю. Він гуртує новопіднятих Відступників у боєздатне військо, щоб боронити селище й наводити лад у довколишніх землях.",al={"роль аррена","хто такий аррен","екзекутор смертельного дзвону"}},{q="Яке звання має екзекутор серед Відступників?",a="Екзекутори — довірені військові й адміністративні командири в ієрархії Відступників. Вони керують місцевими гарнізонами, ведуть операції в полі й втілюють волю та закон Королеви Сильвани Віндраннер.",al={"титул екзекутора","що таке екзекутор","ранг екзекутора відступників"}},{q="Чому Аррен посилає новобранців проти зомбі?",a="Зомбі, що никають біля Похоронного Подзвону, — бездумні рештки Погибелі, що лишилися після того, як чума спустошила Лордерон. Аррен наказує їх винищити, щоб щойно пробуджену нежить не розірвали на шматки, щойно вона вийде зі склепів.",al={"чому вбивати зомбі","завдання проклятих","безмозка погибель"}},{q="Що Багряний Хрестовий Похід робить на Галявинах Тірісфалю?",a="Багряний Хрестовий Похід — радикальне людське угруповання, що прагне винищити всю нежить. Вони тримають застави по всіх руїнах Лордерону й завзято намагаються знищити Відступників, вважаючи їх нічим не кращими за Погибель.",al={"багряний хрестовий похід тирисфаль","чому хрестовий похід тут","хрестоносці смертельного дзвону"}},{q="Що таке Лощина Нічної Павутини?",a="Лощина Нічної Павутини — печера на північ від Похоронного Подзвону, де аж кишить павуками. Аррен посилає новобранців вичистити агресивних павуків, щоб усунути велику місцеву небезпеку й показати бойову вправність.",al={"печера павуків смертельного дзвону","лощина нічної павутини","павуче завдання аррена"}},{q="Куди Аррен посилає новобранців, коли ті виконають його доручення?",a="Коли безпосередні загрози Похоронному Подзвону усунено, Аррен посилає вправних новобранців далі, до Брілла, щоб з'явитися до Екзекутора Зиґанда й допомогти ширшим зусиллям Відступників по всіх Галявинах Тірісфалю.",al={"що після смертельного дзвону","куди йти після аррена","екзекутор у полі"}}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.196.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="Екзекутор Зиґанд",s="Екзекутор Зиґанд — старший командир Відступників в ратуші Брілла, що керує оборонними й військовими операціями по центральних Галявинах Тірісфалю. Підпорядкований безпосередньо верховному командуванню Андерсіті, він координує зачистку сил Багряного Хрестового Походу, що тиснуть на землі Відступників.",h="Екзекутор Зиґанд — старший командир Відступників в ратуші Брілла, що керує оборонними й військовими...",kw={"екзекутор зиґанд","брілл","ратуша","командир","багряний хрестовий похід","андерсіті","відступники"},ang={["faction:Horde"]="Мандрівники з Калімдору, що відвідують Галявини Тірісфалю, бачать у Зиґанді зібране, дисципліноване військове керівництво, що рухає боротьбу Відступників за Лордерон.",["race:Undead"]="Для Відступників, що виходять із Похоронного Подзвону, Екзекутор Зиґанд утілює ширшу військову владу Андерсіті, яка вітає нових громадян на дійсній службі проти їхніх найзапекліших ворогів."},sec={{t="Командування в Бріллі",b="З адміністративного серця Брілла Екзекутор Зиґанд координує оборону краю для Відступників після їхнього пробудження в Похоронному Подзвоні. Безпосередній начальник таких місцевих офіцерів, як Екзекутор Аррен, і польових вартівників, як Вартова Смерті Ліннея, Зиґанд зводить докупи донесення розвідки й висилає здібних новобранців боронити кордони Лордерона від зазіхань."},{t="Війна з Хрестовим Походом",b="Головна військова турбота Зиґанда — фанатична присутність Багряного Хрестового Походу, застави якого всіяли Галявини Тірісфалю. Під його орудою агентів планомірно висилають бити розвідників, табори й передові бази хрестоносців, щоб фанатики ніколи не зібрали достатньо сил загрожувати підступам до Андерсіті."}},faq={{q="Хто такий Екзекутор Зиґанд?",a="Екзекутор Зиґанд — старший офіцер Відступників, що діє з Брілла на Галявинах Тірісфалю. Він командує місцевими гарнізонами Вартових Смерті, отримує тактичні звіти від нижчих офіцерів і керує воєнними походами проти місцевих загроз.",al={"зиґанд","хто такий екзекутор зиґанд","роль зиґанда"}},{q="Де знайти Екзекутора Зиґанда?",a="Він перебуває в головній ратуші Брілла чи біля неї — у центральному поселенні Відступників на Галявинах Тірісфалю, трохи на північ від Андерсіті.",al={"місце зиґанда","де зиґанд","екзекутор зиґанд на мапі"}},{q="Яка головна мета Зиґанда на Галявинах Тірісфалю?",a="Передусім він керує війною проти Багряного Хрестового Походу в краї. Він стежить за пересуваннями фанатиків по всьому Тірісфалю й наказує нищити їхні табори та командирів, перш ніж вони рушать на Андерсіті.",al={"мета зиґанда","чому воювати з хрестовим походом","призначення зиґанда"}},{q="Хто підзвітний Екзекуторові Зиґанду?",a="Зиґанд — старший командир для Екзекутора Аррена, що веде новобранців у Похоронному Подзвоні, а також для польових вартових, як-от Вартова Смерті Ліннея, що патрулює головне роздоріжжя Галявин Тірісфалю.",al={"підлеглі зиґанда","хто служить зиґанду","начальник аррена"}},{q="Чи має Екзекутор Зиґанд справу із загрозами від здичавілої нежиті?",a="Так. Окрім боротьби з Багряним Хрестовим Походом, Зиґанд оголошує в краї нагороди за знищення здичавілої нежиті й небезпечних мародерів, як-от гнол-трупокрад Червиве Око, що загрожують мандрівникам на галявинах.",al={"червиве око","нагороди зиґанда","розшукові завдання"}},{q="Яке звання має екзекутор серед Відступників?",a="Екзекутор — намісник краю й воєначальник в ієрархії Відступників. Екзекутори керують поселеннями, командують місцевими загонами Вартових Смерті й утверджують владу Королеви Сильвани в спірних краях Лордерону.",al={"що таке екзекутор","ранг екзекутора","екзекутор відступників"}}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:falfindel-waywarder"] = {n="Фалфіндел Вейвордер",kw={"фалфіндел вейвордер","таланаар","фералас","обвуглена долина","вогники","нічні ельфи","рейзорфен краул"},ang={["class:Druid"]="Його зусилля послати духів лісу й вогники, щоб зцілити спалену землю Гір Кам'яного Кігтя, відбивають священну друїдську місію відновлення.",["faction:Alliance"]="Для мандрівників Альянсу, що долають довгий шлях на південь із Пусток чи Гір Кам'яного Кігтя, Фалфіндел і варта Таланаара — гостинний притулок.",["race:NightElf"]="Фалфіндел уособлює пильність вашого народу на порубіжжі Калімдору: він прагне загоїти шрами природи й остерігає від небезпек дикої місцини, що наступають."},sec={{t="Варта на південному кордоні",b="Таланаар позначає ворота, де пишні ліси Фераласу спускаються до височенних столових гір і сухих солончаків Тисячі Голок. Фалфіндел Вейвордер стоїть на варті на цій віддаленій заставі й вітає втомлених мандрівників, що пройшли далекий шлях через континент. Оточений природною величчю й прихованими небезпеками, він — зв'язковий для нічних ельфів, які стежать і за місцевими загрозами, і за ширшими природними лихами по всьому Калімдору."},{t="Зцілення Обвугленої Долини",b="Попри свій південний пост, Фалфіндела глибоко тривожить спустошення далеко на півночі, у Горах Кам'яного Кігтя. Обвуглена Долина, сплюндрована темним чаклунством і вогняною руїною, — болісний шрам на дикій природі Калімдору. Коли шукачі пригод приносять Фалфінделові допомогу для її відродження, він кличе духів лісу. Викликавши рої вогників, він велить їм поспішати на північ, до Гір Кам'яного Кігтя, щоб почати гоїти спалену землю."},{t="Око на шипогривів і пустки",b="Окрім налагодження відновлення, Фалфіндел пильно стежить за навколишнім краєм, зокрема за лігвами шипогривів у Рейзорфен Краулі. Вивчаючи знайдені щоденники й збираючи відомості про ватажків шипогривів, Фалфіндел дбає, щоб Альянс розумів, які небезпеки зростають на перевалах між Фераласом і центральними пустелями."}},faq={{q="Де перебуває Фалфіндел Вейвордер?",a="Фалфіндел служить у Таланаарі — заставі нічних ельфів на кордоні між Фераласом і Тисячею Голок.",al={"місце фалфіндела","де фалфіндел","фалфіндел вейвордер на мапі"}},{q="Яка роль Фалфіндела в Таланаарі?",a="He serves as a druid and guide at the outpost, monitoring regional threats such as the quilboar in Thousand Needles and coordinating restoration efforts for ruined lands like the Charred Vale.",al={"що робить фалфіндел","призначення фалфіндела","завдання фалфіндела"}},{q="Як Фалфіндел допомагає Обвугленій Долині?",a="Коли шукачі пригод допомагають відвоювати Обвуглену Долину, Фалфіндел промовляє заклинання, що кличе лісових вогників, і посилає їх на північ, до Гір Кам'яного Кігтя, щоб зцілити отруєну землю.",al={"фалфіндел стоунталон","фалфіндел обвуглена долина","відвоювання обвугленої долини фалфіндел"}},{q="Чому Фалфіндела цікавить Рейзорфен Краул?",a="Він вивчає загрозу від шипогривів Краулу й оглядає такі речі, як щоденник Лоунброу, щоб простежити вплив їхніх ватажків, як-от Старої Відьми Краулу.",al={"відьма краулів фалфіндел","щоденник лоунброу фалфіндел","фалфіндел квілборги"}},{q="Фалфіндел на боці Альянсу чи нейтральний?",a="Falfindel is a night elf druid allied with Darnassus and the Alliance. Horde travelers approaching Thalanaar will find the outpost hostile.",al={"чи фалфіндел альянс","фракція фалфіндела"}},{q="Що Фалфіндел каже мандрівникам?",a="Він тепло вітає дружніх гостей, зважаючи на їхній довгий шлях: «Схоже, ви прийшли здалеку».",al={"плітки фалфіндела","цитата фалфіндела"}}},fp="19,367,28.456.0,24.471.0,36.366.0,37.119.0,38.192.0,41.185.0,46.172.0,50.139.0,37.132.0"}
P.entries["npc:falla-sagewind"] = {n="Фалла Сейджвінд",s="Фалла Сейджвінд — відлюдна містикиня-тауренка, що оселилася високо на скелястій вершині над центральними Пустками. Між Перехрестям і Оазою Буйних Вод вона вивчає природні й містичні аномалії, що тривожать навколишні землі. Шукачі пригод, які досліджують покручену скверну, що просочується з сусідніх Печер Стогонів, нерідко звертаються до неї по пораду.",h="Фалла Сейджвінд — відлюдна містикиня-тауренка, що оселилася високо на скелястій вершині над центральними...",kw={"фалла сейджвінд","пустки","печери стогонів","смарагдовий сон","жахіття","наралекс","друїди ікла"},ang={["class:Druid"]="Друїди побачать у Фаллі важливу союзницю, яка допомагає з'ясувати трагічне падіння Наралекса й Друїдів Ікла в Печерах Стогонів.",["faction:Horde"]="Фалла допомагає Орді, тлумачачи дивні знамення й осквернені реліквії, які розвідники приносять зі спірних саван Пусток.",["race:Tauren"]="Фалла Сейджвінд утілює обов'язок тауренів тихо оберігати землю: вона стежить із висоти, чи не з'явилася духовна гниль, поки її родичі захищають шляхи внизу."},sec={{t="Вартова високої кручі",b="Фалла Сейджвінд отаборилася високо над пилом і метушнею шляхів Пусток — на відлюдній вершині трохи на південний захід від Перехрестя. Звідти вона пильно стежить за вразливою саваною внизу, помічаючи раптові зміни в поведінці звірів і скверну, що підступає з підземних розколин Печер Стогонів. Самотня варта відокремлює її від щоденної торгівлі Перехрестя: вона — уважна самітниця, налаштована на духів і на мовчазні рани землі."},{t="Жахіття наяву",b="Коли з мутованих звірів Пусток добувають дивні пульсуючі уламки, мудрих мандрівників скеровують видертися на кручі до Фалли. Вона допомагає тлумачити покручену магію, що руйнує природний лад оаз. Розпізнавши похмурі ознаки того, що Смарагдовий Сон під землею загниває, вона посилає героїв до мудрих друїдів Кола Кенарія по глибші відповіді про жахіття, що пускає коріння в цьому краї."}},faq={{q="Хто така Фалла Сейджвінд?",a="Фалла Сейджвінд — самотня тауренка-містикиня, що живе на високій кручі на південний захід від Перехрестя в Пустках. Вона пильнує землю й допомагає мандрівникам, що прагнуть зрозуміти дивні магічні недуги, які ширяться краєм.",al={"хто така фалла сейджвінд","хто така фалла","лор фалли сейджвінд"}},{q="Де знайти Фаллу Сейджвінд?",a="Вона перебуває на крутій гірській вершині просто на південний захід від Перехрестя й на північ від Оази Буйних Вод. Щоб дістатися до її табору, треба піднятися звивистими кам'янистими стежками з довколишньої савани.",al={"де фалла сейджвінд","де фалла","як дійти до фалли сейджвінд"}},{q="Чому Фаллу Сейджвінд цікавлять Печери Стогонів?",a="Falla helps investigate the strange magic found in a glowing shard recovered from the Wailing Caverns. She directs travelers toward experienced druids for further counsel.",al={"фалла печери стогонів","чому фалла цікавиться оазою","фалла сяючий уламок"}},{q="Чи пов'язана Фалла Сейджвінд із якимось кланом чи родиною?",a="She shares the Sagewind surname with other tauren, but no family connection is confirmed.",al={"рід сейджвінд","хто такі сейджвінди","чи фалла родичка таху"}},{q="Які завдання пов'язані з Фаллою Сейджвінд?",a="Фалла пов'язана з розслідуваннями щодо Печер Стогонів: у неї здають або продовжують завдання «Сяйлива Скалка» та «У жахіттях», що розкривають темний сон, який псує місцеві оази.",al={"завдання фалли сейджвінд","завдання від фалли","завдання в кошмарах"}},{q="Чи можуть гравці Альянсу мати справу з Фаллою Сейджвінд?",a="Так. Зі Сяйливою Скалкою Фалла допомагає мандрівникам обох фракцій: шукачів пригод з Альянсу посилає до Матренґіла Берволкера в Дарнасус, а з Орди — до Гамуула Рунтотема в Тандер Блаф.",al={"чи фалла сейджвінд ворожа","фалла дружня до альянсу"}}},fp="14,352,24.528.0,20.438.1,22.242.0,32.209.0,56.171.0,53.89.0,35.214.0,50.194.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="Палий Герой Орди",s="Палий Герой Орди — неприкаяний дух орка-воїна, що стоїть на варті при південній дорозі з Болота Скорботи. Скутий жалем і безчестям, він застерігає мандрівників від жахів, що чекають на них у Спустошених Землях, і шукає поборників, готових визволити його закатованих воїнів із демонічного полону.",h="Палий Герой Орди — неприкаяний дух орка-воїна, що стоїть на варті при південній дорозі з Болота Скорботи.",kw={"палий герой орди","спустошені землі","разеліх осквернитель","болото скорботи","привид","орки"},ang={["class:Warrior"]="Цей привид прославленого полеглого воїна викликає особливу спорідненість у бійців, які знають, як пече — вижити, коли побратими полягли.",["faction:Horde"]="Герой уособлює муку воїна, якого демонічна жорстокість позбавила честі, і закликає шукачів пригод з Орди помститися за його загиблий загін і змити пляму поразки з їхньої спадщини."},sec={{t="Трагічний наказ",b="За життя цей воїн був прославленим поборником, якого разом із добірним загоном вояків послали розвідати Спустошені Землі й доповісти, чи є там Палаючий Легіон. Його донесення так і не дійшло: гінця, якого він відправив на північ до Стонарда, підстерегли й убили Болотний Мовець і його мурлоки. Залишившись без наказів і підкріплення, командир зрештою повів своїх воїнів на південь, у понівечені землі, щоб дати відсіч темряві, яка дедалі густішала. Це була фатальна помилка. Демонічні сили розгромили його військо: воїнів розпорошили, захопили в полон і віддали на страхітливі муки жахолордові Разеліху Осквернителю."},{t="Ціна поразки",b="Разом зі своїм лейтенантом Кірітом командир потрапив у полон і зазнав жорстоких тортур у Кільцях Змія, а тим часом кати виривали душі з його вцілілих воїнів. Він утік, але помер від смертельних ран біля межі болота, і дух героя досі прикутий до порога Спустошених Земель. Його воїнів спіткала ще темніша доля: їхні бездушні оболонки прив'язали до містичних каменів, і тепер вони — безсмертні раби, поділені між Разеліхом і його поплічниками: Архімагом Аллістаржем, Леді Севін і Ґролом Руйнівником. Доки камені, що тримають їхні душі, не розіб'ють, а муки воїнів не скінчаться, його неприкаяний дух не знайде спочинку."}},faq={{q="Ким був Палий Герой за життя?",a="Він був досвідченим орком-воїном, якого обрали очолити розвідувальний загін у Спустошені Землі, щоб оцінити демонічну загрозу. Він помер від тяжких ран, утікши з катівень Разеліха Осквернителя, і його дух лишився при дорозі, що веде з Болота Скорботи.",al={"хто такий палий герой","ім'я палого героя","хто цей палий герой"}},{q="Чому він блукає на межі Спустошених Земель?",a="Його тримає сором за те, що він утратив свій загін і провалив завдання. Він не відійде, доки відважні шукачі пригод не вирушать на південь і не знищать камені зв'язування, що тримають його вояків у вічному рабстві Палаючого Легіону.",al={"чому він привид","палий герой привид","чому він тут блукає"}},{q="Що сталося з донесенням, яке він надіслав до Стонарда?",a="Розвідника, що ніс його термінове донесення назад до застави Стонард, у болоті підстерегли й убили мурлоки під проводом Болотного Мовця. Донесення загубилося, підкріплення так і не прибуло, і герой сам рушив у Спустошені Землі.",al={"зниклий наказ","що сталося з його наказом","посильний болотний мовець"}},{q="Що сталося з його поручником Кірітом?",a="Над Лейтенантом Кірітом у Кільцях Змія проводили демонічні досліди. Його душу спотворили й скрутили, а тіло перетворили на жахливого мисливця Скверни, що чатує в глибині печери.",al={"поручник кірит","хто такий кірит","що сталося з кіритом"}},{q="Чому його вояки невразливі?",a="Разеліх і його поручники відокремили душі полонених вояків від їхньої плоті. Без душі їхні тіла не можуть по-справжньому померти. Звільнити їх можна, лише побивши тіла майже до розпаду: тоді сусідні камені зв'язування душ ненадовго стають вразливими.",al={"невразливі вояки","камені зв'язування","слуги разеліха"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {n="Фандрал Стаґгелм",s="Архідруїд Фандрал Стаґгелм очолює друїдів Кола Кенарія з Ценаріонського Анклаву в Дарнасусі. Прийшовши до влади після того, як Малфуріон Стормрейдж зник у Смарагдовому Сні, він став головним поборником насадження нового Світового Дерева — Тельдрассила. Гордий, різкий і невгамовно честолюбний, Фандрал обстоює рішуче відродження калдореїв, що раз у раз зіштовхує його з Верховною Жрицею Тірандою Віспервінд.",h="Архідруїд Фандрал Стаґгелм очолює друїдів Кола Кенарія з Ценаріонського Анклаву в Дарнасусі.",kw={"фандрал стаґгелм","архідруїд","тельдрассил","коло кенарія","дарнасус","валстанн","силітус","гординя"},ang={["class:Druid"]="Стаґгелм командує дарнаськими друїдами, штовхаючи Коло Кенарія до прямої влади над світом і сперечаючись із традиційним ученням сплячого Малфуріона Стормрейджа.",["faction:Alliance"]="Хоч Тельдрассил і править за бастіон Альянсу в північному Калімдорі, Стаґгелм дивиться на молодші раси з ледь прихованою зневагою й терпить їхню присутність лише з політичної доцільності.",["race:NightElf"]="Один із головних проводирів Дарнасуса, Фандрал утілює гордість і лють калдореїв: він рухає заселення Тельдрассила, навіть коли прості мешканці відчувають розкол між його анклавом і Храмом Місяця."},sec={{t="Архітектор Тельдрассила",b="Після Третьої війни й жертви Нордрассила на Горі Гіджал нічні ельфи втратили безсмертя та своє священне святилище. Поки Малфуріон Стормрейдж закликав до терпіння й застерігав від марнославства, Фандрал обстоював зухвалий задум — виростити нове Світове Дерево біля узбережжя Калімдору. Коли ж Малфуріон упав у кому в Смарагдовому Сні, Фандрал перехопив ініціативу й повів друїдів вирощувати Тельдрассил. У велетенському дереві він бачив пам'ятник витривалості калдореїв і засіб повернути втрачену велич — навіть попри те, що Аспекти драконів демонстративно відмовили несхваленому задуму в благословенні."},{t="Трагедія Рухливих Пісків",b="За тисячу років до Першої війни Фандрал був польовим командиром калдореїв у Силітусі під час Війни Рухливих Пісків. Комахоподібні кіраджі знали його як «Кар'сіса» — Руку Землі; він тримав передову пліч-о-пліч зі своїм улюбленим єдиним сином Валстанном. Скориставшись батьківською відданістю Фандрала, кіраджійський Генерал Раджакс улаштував оманливий напад на Село Південного Вітру, захопив Валстанна й безжально стратив його просто на очах у враженого жахом Архідруїда. Ця втрата зламала дух Фандрала, спричинила нищівний відступ і закарбувала в його гордовитій вдачі незгасну, гірку ненависть до рою."},{t="Суперництво й гординя",b="Серед мармурового гілля Дарнасуса Фандрал править справами калдореїв зверхньою, непоступливою рукою. На відміну від Верховної Жриці Тіранди Віспервінд, яка віддає перевагу духовному збереженню й обережній дипломатії, Фандрал уважає військове розширення та рішучу силу найголовнішими для виживання свого народу."}},faq={{q="Хто такий Фандрал Стаґгелм?",a="Фандрал Стаґгелм — виконувач обов'язків Верховного друїда Кола Кенарія в Дарнасусі, що очолює друїдів-калдореїв за відсутності Малфуріона Стормрейджа. Відомий палкою вдачею й імперськими амбіціями, він — головний натхненник створення Тельдрассила.",al={"лор фандрала","хто такий верховний друїд","верховний друїд дарнасу"}},{q="Чому Фандрал не ладнає з Тірандою?",a="Фандрал обстоює воєнне відродження калдореїв, агресивне розширення й повернення втраченого безсмертя. Тіранда Віспервінд дотримується обережного духовного проводу через Елуну. Їхні суперечливі бачення майбутнього нічних ельфів після Гіджалу породжують запеклі політичні тертя в Дарнасусі.",al={"фандрал і тіранда","чому друїди й жриці не ладнають","стаґгелм проти віспервінд"}},{q="Чому Тельдрассил посадили всупереч волі Малфуріона?",a="Малфуріон вважав, що посадити заміну Нордрассилу — пиха, якої природа не схвалить. Коли Малфуріон поринув у свій сон-кому, Фандрал згуртував решту друїдів і таки посадив Тельдрассил, прагнучи повернути калдореям силу й утрачене безсмертя.",al={"хто створив тельдрассил","чому фандрал посадив тельдрассил","походження тельдрассила"}},{q="Що сталося із сином Фандрала?",a="Під час Війни Мінливих Пісків у Силітусі сина Фандрала, Валстанна, заманили в засідку біля Села Південного Вітру. Кіраджі Генерал Раджакс схопив Валстанна й убив його на очах у Фандрала, і Верховний друїд, убитий горем, назавжди озлобився.",al={"син фандрала","хто був валстанн","валстанн стаґгелм"}},{q="Де знайти Фандрала Стаґгелма?",a="Фандрал стоїть на вершині Ценаріонського Анклаву в Дарнасусі в оточенні вірних друїдів, звідки наглядає за справами столиці калдореїв.",al={"де фандрал","де знайти фандрала","керівник анклаву ценарія"}}},fp="16,417,23.647.0,29.638.0,18.306.0,24.261.0,43.290.0,54.286.0,31.269.0,36.135.0"}
P.entries["npc:farmer-furlbrow"] = {n="Фермер Фурлброу",s="Фермер Теодор Фурлброу — вигнаний зі своєї землі гарбузівник із Вестфолу, що застряг разом із дружиною Верною на дорозі біля Садиби Дженсенів. Братство Дефіас вигнало подружжя з дому, і тепер вони намагаються полагодити зламаний віз і втекти до Лісу Елвінн.",h="Фермер Теодор Фурлброу — вигнаний зі своєї землі гарбузівник із Вестфолу, що застряг разом із дружиною Верною...",kw={"фермер фурлброу","теодор фурлброу","верна фурлброу","стара білявка","братство дефіас","вестфол"},ang={["faction:Alliance"]="Лихо Теодора Фурлброу уособлює повний крах цивільної влади у Вестфолі, де вірні піддані королівства мусять покидати домівки, бо жоден королівський солдат їх не захищає."},sec={{t="Усе життя на одному возі",b="Колись Теодор Фурлброу вирощував гарбузи на півночі Вестфолу, але хвиля злочинності, що наростала, змусила його з дружиною Верною покинути все, що вони мали. Зібравши те, що вдалося врятувати, вони вирушили до безпечного Лісу Елвінн і закликали сусідів, як-от Фермера Салдіна, зробити те саме. Біда спіткала їх на дорозі біля Садиби Дженсенів: віз зламався, і подружжя застрягло на видноті в розбійників і диких звірів. Поки Верна доглядає їхню улюблену конячку Стару Білявку, Теодор з дедалі більшим відчаєм пильнує дорогу: він мріє повернути дорогі серцю речі — як-от кишеньковий годинник, який батько Верни подарував йому в день весілля, — і сподівається попередити Сентінел Гілл про розбійників, що підступають."},{t="Докази загарбання землі",b="Тікаючи з ферми, Фурлброу залишив важливі документи, зокрема грамоту на свою землю. Шукачі пригод, що досліджують захоплені ферми, часто знаходять ці покинуті папери — відчутний доказ того, як Братство Дефіас зганяло чесних трудівників з їхньої землі. Ґраян Стаутмантл і Народне ополчення покладаються на такі докази, щоб скласти повну картину злодійського повстання в краї."}},faq={{q="Хто такий Фермер Фурлброу?",a="Теодор Фурлброу — вигнаний зі своєї землі гарбузовий фермер із півночі Вестфолу. Братство Дефіас вигнало його з дружиною Верною з обійстя, і тепер вони застрягли біля свого зламаного воза неподалік від Садиби Джансена.",al={"фермер фурлброу","теодор фурлброу","хто такий фурлброу"}},{q="Чому Фермер Фурлброу застряг на дорозі?",a="Коли вони тікали з Вестфолу в безпечний Ліс Елвінн, віз зламався. Доки фермер не полагодить його чи не знайде допомоги, вони з дружиною мусять тулитися при дорозі разом зі старою кобилою Білявкою.",al={"чому зламаний його віз","чому фурлброу на дорозі","зламаний віз вестфол"}},{q="Яку реліквію загубив Фермер Фурлброу?",a="Поспіхом тікаючи з ферми, Теодор забув дорогий йому кишеньковий годинник, який батько Верни подарував йому в день весілля. Він просить мандрівників, досить відважних, щоб пробратися фермами, де аж кишить бандитами, повернути його.",al={"забута реліквія годинник","годинник фурлброу","кишеньковий годинник"}},{q="Чи має Фермер Фурлброу родину поза Вестфолом?",a="У Теодора є брат, що працює конюхом далеко на півночі, у Таррен Міллі в Передгір'ї Гілсбреда.",al={"родина фурлброу","брат фурлброу"}}},fp="15,260,24.743.0,24.424.1,23.227.0,44.214.0,39.239.0,54.108.0"}
P.entries["npc:farmer-saldean"] = {n="Фермер Салдін",s="Фермер Салдін — витривалий людський господар, що живе на Фермі Салдина в центрі Вестфолу разом із дружиною Салмою. На відміну від багатьох сусідів, які втекли чи опустили руки, Салдін уперто доглядає свої неспокійні поля попри здичавілих жнивних големів і дедалі більший розбій.",h="Фермер Салдін — витривалий людський господар, що живе на Фермі Салдина в центрі Вестфолу разом із дружиною...",kw={"фермер салдін","ферма салдина","салма салдін","жнивні големи","вестфол","фермерство"},ang={["faction:Alliance"]="Салдін — приклад упертої рішучості останніх вірних короні жителів Вестфолу, які тримаються землі королівства навіть тоді, коли королівських солдатів ніде не видно.",["profession:Cooking"]="Фермери на кшталт Салдіна — хребет продовольчого постачання Стормвінда, що вже тріщить; збережений урожай означає хліб на столах по всьому королівству."},sec={{t="Не випускаючи плуга",b="Фермер Салдін пам'ятає часи, коли Вестфол вважали найродючішою житницею по цей бік Долини Стренглторну. Ті заможні роки розсипалися на порох. Довкола — зарослі поля, механічні жнивні вартові, що трощать усе на своєму шляху, і хижі розбійники, але Салдін не поступається своєю землею. Поки інші господарі покинули свої акри або взялися до злодійства, він і його дружина Салма вперто збирають те небагате зерно, яке ще можна зібрати. Доведений до відчаю, він по-господарськи наймає мандрівних шукачів пригод, щоб ті розібрали здичавілих жнивних големів, які нишпорять його полями, — тоді він зможе забрати їхні деталі й розчистити ґрунт для посіву."},{t="Коса Вестфолу",b="Уперта оборона свого господарства робить Салдіна однією з небагатьох уцілілих опор мирного життя між Сентінел Гіллом і північним мостом. Попри тяжкі обставини, він підтримує зв'язок із Народним ополченням і, щойно владнає власні нагальні клопоти, відсилає дужих мандрівників до Ґраяна Стаутмантла. Салдін добре знає: знищення здичавілих жнивних косарів дасть його фермі лише тимчасовий перепочинок, якщо не впоратися з ширшим беззаконням, що душить сільські землі."}},faq={{q="Хто такий Фермер Салдін?",a="Салдін — досвідчений фермер-людина, що живе на Фермі Салдина у Вестфолі з дружиною Салмою. Він один із небагатьох місцевих поселенців, які вперто не хочуть покидати свою землю попри голод, здичавілих жнивних големів і дедалі більший розбій у краї.",al={"салдін","хто такий салдін","салдін нпс"}},{q="Чому Ферма Фермера Салдіна в біді?",a="Автоматичні жнивні големи Вестфолу зламалися й здичавіли: вони никають полями й нападають на кожного, кого побачать. Салдінові потрібні шукачі пригод, щоб вполювати механічних вартових і зібрати їхні деталі, аби він міг повернути собі пшеничні лани.",al={"чому напали жнивні големи","біда на фермі салдіна"}},{q="Де знайти Фермера Салдіна?",a="Він стоїть біля свого будинку на Фермі Салдина, просто біля головної дороги в центрі Вестфолу, трохи на північ від Сентінел Гілл.",al={"де салдін","де знайти салдіна","де ферма салдіна"}},{q="Чи підтримує Салдін Народне ополчення?",a="Так. Хоч Салдін цілком зосереджений на захисті своїх посівів і дому, вправних шукачів пригод він посилає дорогою до Ґраяна Стаутмантла в Сентінел Гілл, щоб допомогти Народному ополченню боронити край.",al={"салдін ґріан стаутмантл","салдін ополчення"}},{q="Які особливі товари продає Салдін?",a="Салдін продає звичайний хліб і передусім Особливий Курячий Корм — дивне зерно, яке шукають мандрівники, що хочуть заприятелювати з місцевими курми, які блукають Вестфолом.",al={"салдін торговець","торговець особливим кормом для курей"}}},fp="14,278,16.624.0,22.511.0,22.249.0,40.242.0,34.137.0,42.207.0,36.175.0"}
P.entries["npc:farthing"] = {n="Фартінґ",s="Єпископ Фартінґ — людина-священнослужитель, що служить у Соборі Світла в Стормвінді. Відвідувачам і вірянам він постає відданим слугою Святого Світла, що наставляє парафіян і спрямовує допомогу до знесилених поселень по всьому королівству.",h="Єпископ Фартінґ — людина-священнослужитель, що служить у Соборі Світла в Стормвінді.",kw={"єпископ фартінґ","собор світла","духовенство","святе світло","стормвінд","сутінколісся"},ang={["class:Priest"]="Для жерців, що відвідують Собор Світла, Фартінґ уособлює усталену ієрархію та вчену мудрість людського духовенства Стормвінда.",["faction:Alliance"]="Шукачі пригод, що борються з повзучою скверною на південних землях Альянсу, як-от у Сутінколіссі, звертаються до Фартінґа та його побратимів-священників по божественне прозріння й духовну стійкість."},sec={{t="Єпископ у Стормвінді",b="У тихих мармурових залах Собору Світла Єпископ Фартінґ — одна з чільних постатей, що дбають про духовні потреби Стормвінда. Разом з Архієпископом Бенедиктусом і зібраним духовенством він радить мандрівникам, допомагає тим, хто опановує святі мистецтва, і виконує громадські та пастирські обов'язки Церкви Святого Світла."},{t="Допомога сплюндрованим землям",b="Хоча Фартінґ лишається в столиці, він скеровує щирих мандрівників до темніших куточків королівства, що відчайдушно потребують святої допомоги. Коли надходять тривожні звістки про некроманта Морбента Фела й повзучу скверну нежиті, що охоплює Сутінколісся, Фартінґ радить, як подолати темне чаклунство й очистити сплюндроване прикордоння."}},faq={{q="Де знайти Єпископа Фартінґа?",a="Єпископ Фартінґ перебуває в Соборі Світла в центрі Соборної Площі Стормвінда.",al={"де фартінґ","де єпископ фартінґ","карта фартінґа"}},{q="Яку роль Фартінґ відіграє в Соборі?",a="Він висвячений єпископ Церкви Святого Світла: наставляє вірян, що приходять до собору, жерців, які навчаються, і шукачів пригод, що шукають святої мудрості для далеких поселень.",al={"що робить фартінґ","хто такий фартінґ"}},{q="Як Фартінґ пов'язаний із Сутінколіссям?",a="До Фартінґа звертаються шукачі пригод, що борються з нежиттю в Сутінколіссі: він дає поради щодо темних мистецтв, які підтримують некроманта Морбента Фела, і скеровує душі до очищення.",al={"фартінґ сутінколісся","фартінґ морбент фел"}},{q="Чи родич Фартінґ інших людей із тим самим прізвищем?",a="Прізвище Фартінґ мають ще кілька людей у людських землях, зокрема Коулмен та Іветт Фартінґ, але сам він не говорить про якісь прямі родинні зв'язки.",al={"родич коулмен фартінґ","родина фартінґ"}}},fp="8,272,21.374.0,24.390.0,35.119.0,46.199.0,39.187.0,60.172.0"}
P.entries["npc:feegly-the-exiled"] = {n="Фіґлі Вигнанець",s="Фіґлі Вигнанець — дворф-вигнанець, що тиняється поблизу дворфійських розкопок у Бель Модані на півдні Пусток. Колись його хвалили як одного з найкращих копачів експедиції, але через одержимість відкопаною реліквією Генерал Твінбрейд його прогнав.",h="Фіґлі Вигнанець — дворф-вигнанець, що тиняється поблизу дворфійських розкопок у Бель Модані на півдні Пусток.",kw={"фіґлі вигнанець","сльоза місяців","бель модан","генерал твінбрейд","дворфи","троги"},ang={["faction:Horde"]="Затята ворожнеча Фіґлі до копачів Бель Модану робить його несподіваним союзником для мандрівників з Орди, які хочуть підірвати дворфійську експедицію в Пустках.",["race:Dwarf"]="Для дворфів Фіґлі — трагічне й моторошне застереження: вправний копач, якому одержимість відкопаною реліквією коштувала місця серед рідних."},sec={{t="Загибель копача",b="До вигнання Фіґлі вважали одним із найкращих копачів Бель Модану. Сльоза Місяців стала першою великою знахідкою розкопок, і Фіґлі привласнив собі її силу. Генерал Твінбрейд назвав самоцвіт проклятим, замкнув його у Фортеці Бел'дун, а Фіґлі прогнав геть. Тепер той похмуро тиняється на самоті, відчайдушно прагнучи повернути саме той камінь, що його й занапастить: щойно Фіґлі знову візьме його в руки, Сльоза розколеться, а сам він скоцюрбиться в огидного згорбленого трога."}},faq={{q="Хто такий Фіґлі Вигнанець?",a="Фіґлі — дворф, вигнаний копач із розкопок Бель Модану, що жадає реліквії, відомої як Сльоза Місяців.",al={"хто такий фіґлі","лор фіґлі","фіґлі вигнанець"}},{q="Чому Фіґлі вигнали з Бель Модану?",a="Фіґлі став одержимий Сльозою Місяців — першою великою знахідкою в Бель Модані. Генерал Твінбрейд назвав самоцвіт проклятим, замкнув його у Фортеці Бел'дун і прогнав Фіґлі геть.",al={"чому вигнали","що накоїв фіґлі","вигнання фіґлі"}},{q="Чому Фіґлі готовий говорити з шукачами пригод з Орди?",a="Зраджений і вигнаний товаришами-дворфами, Фіґлі не відчуває жодної вірності експедиції Альянсу. Він у такому відчаї, що просить допомоги в мандрівників з Орди, аби повернути реліквію, якої так жадає.",al={"чому фіґлі дружній до орди","фіґлі дружній до орди"}},{q="Що таке Сльоза Місяців?",a="Сльоза Місяців — самоцвіт, який копачі відкопали в Бель Модані, їхня перша велика знахідка там. Фіґлі запевняє, що він дав йому силу, але Генерал Твінбрейд визнав його проклятим і замкнув у Фортеці Бел'дун.",al={"сльоза місяців","самоцвіт фіґлі","артефакт фіґлі"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {n="Фіро Айронгенд",s="Фіро Айронгенд — людина-воїн, що несе службу на Посту Маестри в західних краях Ашенвалю. Він стереже межу між Темним Узбережжям і лісом і пліч-о-пліч із Делґреном Очищувачем бореться з похмурим Культом Темного Берега.",h="Фіро Айронгенд — людина-воїн, що несе службу на Посту Маестри в західних краях Ашенвалю.",kw={"фіро айронгенд","пост маестри","делґрен очищувач","культ темного берега","темне узбережжя","ашенваль"},ang={["faction:Alliance"]="Фіро дає важливу опору мандрівникам Альянсу, що спускаються з Темного Узбережжя в небезпечну спірну глушину Ашенвалю.",["race:Human"]="Побачити людину, що стоїть на варті в прадавніх ельфійських лісах Ашенвалю, — приємний знак того, як далеко сягає співпраця всередині Альянсу."},sec={{t="Оплот на Посту Маестри",b="Пост Маестри, що стоїть при дорозі з Темного Узбережжя на південь до Ашенвалю, — важливий сторожовий пункт і для мандрівників, і для захисників Альянсу. Фіро Айронгенд діє з цієї застави: він підтримує зв'язок і торгові шляхи з Обердайном і пильно стежить за довколишніми лісами. Разом із Делґреном Очищувачем Фіро спрямовує свої зусилля проти зловісного Культу Темного Берега, щоб сектанти й лісові хижаки не перерізали шлях між постачанням Дарнасуса та передовою в Ашенвалі."}},faq={{q="Хто такий Фіро Айронгенд?",a="Фіро Айронгенд — воїн-людина з Альянсу, що служить на Посту Маестри на заході Ашенвалю. Він допомагає мандрівникам, що ходять між Темним Узбережжям і Ашенвалем, і налагоджує постачання з Обердайном.",al={"фіро айронгенд","хто такий фіро","фіро нпс"}},{q="Яка мета Фіро на Посту Маестри?",a="Фіро допомагає утримувати заставу від місцевих загроз, підтримуючи Делґрена Очищувача в боротьбі з Культом Темного Берега, і водночас пильнує, щоб важливі шляхи гінців і постачання до Темного Узбережжя діяли.",al={"чому фіро тут","роль фіро","людина на посту маестри"}},{q="Що таке Культ Темного Берега?",a="Культ Темного Берега — зловісне угруповання, що діє на півночі Ашенвалю, балуючись темною магією й мерзенними ритуалами. Сили Альянсу на Посту Маестри завзято зривають і руйнують його справи.",al={"культ темного берега","темний берег"}},{q="Чи пов'язаний Фіро зі Срібним Світанком?",a="Так. Фіро пов'язаний зі Срібним світанком і тісно співпрацює з Делґреном Очищувачем — паладином Срібного Світанку, що бореться з темними силами в лісі.",al={"фіро срібний світанок","чи фіро зі срібного світанку"}}},fp="14,254,27.562.0,22.199.0,42.193.0,36.216.0,47.160.0"}
P.entries["npc:fel-zerul"] = {n="Фел'зерул",s="Фел'зерул — орк-чорнокнижник, що служить у Стонарді, серед похмурих нетрів Болота Скорботи. Виконуючи прямий наказ Вождя Тралла, він розслідує зловісну присутність, що причаїлася в затонулому Храмі Атал'Гаккара.",h="Фел'зерул — орк-чорнокнижник, що служить у Стонарді, серед похмурих нетрів Болота Скорботи.",kw={"фел'зерул","чорнокнижник","стонард","затонулий храм","тралл","болото скорботи"},ang={["class:Warlock"]="Фел'зерул — приклад того, як Тралл офіційно доручає справу чорнокнижникові: нова Орда часом покладається на знавців темних мистецтв, щоб протистояти незбагненним, таємничим загрозам.",["faction:Horde"]="Фел'зерул у Стонарді — передовий вартовий: він має вчасно попередити, щоб темна магія, яка гноїться на болоті, не захопила зненацька опорний пункт Орди в цьому краї."},sec={{t="Очі, звернені до Затонулого Храму",b="Хоча Орда Тралла загалом ставиться до темних мистецтв з підозрою, Вождь розуміє: щоб збагнути зловісні сили, потрібні ті, хто їх вивчає. Фел'зерула відрядили до Стонарда саме для того, щоб розплутати клубок скверни довкола Ставка Сліз і затопленого Храму Атал'Гаккара. Відсилаючи шукачів пригод по артефакти й розпитуючи про вигнаних тролів Атал'аї, чорнокнижник прагне з'ясувати, яке зло ворушиться під каламутними водами, перш ніж воно загрозить південній заставі Орди."}},faq={{q="Хто такий Фел'зерул?",a="Фел'зерул — орк-чорнокнижник зі Стонарда, твердині Орди в Болоті Скорботи. Він досліджує темні ритуали, що відбуваються в сусідньому Храмі Атал'Гаккара.",al={"фел'зерул","хто такий фел'зерул","чорнокнижник стонарда"}},{q="Чому Тралл послав чорнокнижника до Стонарда?",a="Вождь Тралл відрядив Фел'зерула, бо щоб мати справу з давніми прокляттями й кривавими ритуалами, потрібне знання темніших чар. Фел'зерул має стежити за тривожними подіями довкола затонулого храму й захищати інтереси Орди на болоті.",al={"тралл фел'зерул","чому фел'зерул тут","місія фел'зерула"}},{q="Що розслідує Фел'зерул?",a="Фел'зерул розслідує діяльність тролів Атал'аї та їхні нечестиві обряди в Храмі Атал'Гаккара біля Ставка Сліз. Він залучає розвідників і шукачів пригод, щоб добувати артефакти й вистежувати вигнаних жерців, які можуть знати важливі перекази.",al={"лор завдання фел'зерула","чого хоче фел'зерул","розслідування озера сліз"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="Фелґур Тукатс",s="Фелґур Тукатс — прямолінійний орк-розвідник, що несе службу на Заставі Духоходів у Пустограї. Він керує діями Орди проти місцевих кланів кентаврів.",h="Фелґур Тукатс — прямолінійний орк-розвідник, що несе службу на Заставі Духоходів у Пустограї.",kw={"фелґур тукатс","застава духоходів","пустограй","орк","розвідник","кентаври","колкар"},ang={["faction:Horde"]="Фелґур — незамінний зв'язковий на Заставі Духоходів: він допомагає Орді відкидати войовничі племена кентаврів у Пустограї.",["race:Orc"]="Як і личить оркові на небезпечному порубіжжі, Фелґур прагматичний: сила, швидкість і негайний результат важать для нього більше, ніж пусті балачки."},sec={{t="Суворий розвідник застави",b="Фелґур Тукатс стоїть на варті серед похмурих просторів Застави Духоходів у центрі Пустограю і не має терпіння до люб'язностей. Як передовий розвідник Орди, він оцінює загрози для мандрівників і поселенців, що прямують на захід через гори, — насамперед від місцевих кентаврів Колкар."},{t="Війна з кентаврами",b="Фелґур посилає чемпіонів Орди знищувати вождів місцевих кентаврів і збирати нагороди за голови ворожих племен, які загрожують заполонити край. До нього звертається кожен, хто хоче зміцнити позиції Орди в Пустограї."}},faq={{q="Хто такий Фелґур Тукатс?",a="Фелґур Тукатс — орк-розвідник, що дає завдання на Заставі Духоходів, передовому таборі Орди в Пустограї.",al={"хто такий фелґур тукатс","хто такий фелґур"}},{q="Де знайти Фелґура Тукатса?",a="Він перебуває на Заставі Духоходів, трохи на північ від центральної дороги через Пустограй.",al={"де фелґур тукатс","де фелґур","де знайти фелґура тукатса"}},{q="Які доручення дає Фелґур Тукатс?",a="Фелґур посилає шукачів пригод з Орди вдарити по місцевих кентаврах Колкар, вполювати Хана Дез'гепу й отримувати нагороди за ворожих кентаврів.",al={"завдання фелґура","чого хоче фелґур"}},{q="Чому Фелґур такий небагатослівний із гостями?",a="Пустограй — небезпечна й безжальна пустка, оточена ворожими кланами кентаврів. Служачи на відлюдній заставі, Фелґур не має часу на пусті балачки й воліє думати лише про виживання й бойовий обов'язок.",al={"чому фелґур грубий","швидше фелґур"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="Фелікс Віндлболт",s="Фелікс Віндлболт — переселений гном-біженець, що знайшов прихисток в Анвілмарі в Долині Холодного Хребта. Поспіхом утікаючи від радіації, яка затопила Гномреґан, він загубив свої пожитки, а ворожі тролі Морозогриви їх поцупили.",h="Фелікс Віндлболт — переселений гном-біженець, що знайшов прихисток в Анвілмарі в Долині Холодного Хребта.",kw={"фелікс віндлболт","гном","біженець","гномреґан","морозогриви","тролі","анвілмар"},ang={["race:Dwarf"]="Місцеві тролі Морозогриви посміливішали по всій Долині Холодного Хребта й нападають на беззахисних гномів-біженців, що блукають біля Анвілмара.",["race:Gnome"]="Фелікс утілює триваючу біду ваших переселених родичів, витіснених у безжальний холод Дун Мороґу після катастрофи в Гномреґані."},sec={{t="Переселений мандрівник",b="Після трагічного падіння Гномреґану тисячі гномів опинилися серед крижаних просторів Дун Мороґу в пошуках безпеки. Фелікс Віндлболт тікав з опроміненого міста так поспішно, що втратив усі особисті речі й інструменти. На додачу до лиха, крижані тролі Морозогриви віднесли його скриню, скриньку й відро болтів до своїх таборів на південний захід від Анвілмара, лишивши його безпорадним, без копійки й залежним від співчутливих мандрівників, які повернуть його вкрадене добро."}},faq={{q="Хто такий Фелікс Віндлболт?",a="Фелікс Віндлболт — гном-біженець, що нині знайшов притулок в Анвілмарі в Долині Холодного Хребта. Тікаючи з Гномреґану, він загубив свої речі, і їх забрали місцеві тролі-Морозогриви.",al={"хто такий фелікс","лор фелікса віндлболта","гном у таборі білобородих"}},{q="Куди Фелікс намагався дістатися?",a="Фелікс тікав від радіації, що заполонила Гномреґан, коли спроба гномів вигнати трогів жахливо провалилася. Він опинився в Анвілмарі, дворфській заставі в Долині Холодного Хребта, хоча вважає, що гномові тут не надто затишно.",al={"куди прямував фелікс","призначення фелікса","чому фелікс у долині колдрідж"}},{q="Що сталося з його речами?",a="Поспіхом тікаючи з Гномреґану, Фелікс загубив свою скриню, ящик і відро болтів. Крижані тролі-Морозогриви потягли їх до своїх таборів на південний захід від Анвілмара, і він лишився без припасів.",al={"хто вкрав речі фелікса","украдене спорядження фелікса","тролі фростмейн фелікс"}},{q="Що Фелікс продає шукачам пригод?",a="Нічого. Фелікс не торговець: він утратив усе своє майно, тікаючи з Гномреґану, і в Анвілмарі може запропонувати лише подяку тому, хто поверне його скриню, ящик і відро болтів.",al={"торговець фелікс","що пропонує фелікс","крам фелікса"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="Фенрус Пожирач",s="Фенрус Пожирач — величезний ворг, що никає у верхньому святилищі Фортеці Шадовфенг. Архімаг Аруґал тримає цього ненажерливого звіра як особистого улюбленця й охоронця, і звір роздувся від неприродної магії. Кожен, хто наважиться вдертися до особистого кабінету архімага, мусить зійтися з цим диким жахіттям і господарем, що за ним наглядає.",h="Фенрус Пожирач — величезний ворг, що никає у верхньому святилищі Фортеці Шадовфенг.",kw={"фенрус пожирач","ворг","аруґал","фортеця шадовфенг","блукачі порожнечі"},ang={["class:Hunter"]="Не гайте часу на спроби зачарувати Фенруса. Розум звіра безповоротно спотворили темні мистецтва Шадовфенга, і дика природа над ним уже не владна.",["class:Mage"]="Фенрус — похмуре нагадування про те, як низько впав Архімаг Аруґал, використовуючи таємні мистецтва, щоб спотворювати диких звірів на потворних домашніх охоронців.",["class:Warlock"]="Те, що Архімаг Аруґал може викликати блукачів Порожнечі на допомогу своєму псові, показує, як глибоко колишній маг Даларана занурився в тіньові, заборонені виклики."},sec={{t="Звір у кабінеті господаря",b="Глибоко у Фортеці Шадовфенг, просто біля особистих покоїв Архімага Аруґала, чатує жахливий ворг, відомий як Фенрус Пожирач. На відміну від вовкоподібних воргенів, що никають мурами, Фенрус — справжній ворг, роздутий до велетенських розмірів. Никаючи між полицями, сувоями й таємними приладами в приватному кабінеті Аруґала, звір править і за улюбленця, і за лютого вартового, що не підпускає жодного загарбника, який полює на голову божевільного мага."},{t="Спотворена міць",b="Неприродна статура Фенруса свідчить, що він зазнав впливу темної магії, яка просочує фортецю від часу загибелі Барона Сільверлейна. Архімаг Аруґал чи випущені ним воргени явно спотворили це створіння таємними чи тіньовими дослідами, перетворивши місцевого хижака на ненажерливого велетня. Фенрус такий дикий і так міцно скутий магією, що жоден мисливець не здатен зачарувати чи приручити його розум."},{t="Пильне око Аруґала",b="Потривожити Фенруса — для необачних це смертний вирок. Помітивши загарбника, звір видає оглушливе виття, що лунає всією фортецею й привертає увагу самого Аруґала. Не лишаючи свого улюбленця беззахисним, архімаг спрямовує в залу свою темну волю й викликає блукачів Порожнечі, щоб ті допомогли Фенрусові здолати й пожерти загарбників."}},faq={{q="Що за створіння Фенрус?",a="Фенрус — надзвичайно великий варг, природний вовкоподібний хижак, родом із Лордерону, а не двоногий ворген. Його неприродна маса й люта жорстокість — прямий наслідок тривалого впливу темної магії, яку практикують у Фортеці Шадовфенг.",al={"чи фенрус ворґен","вид фенруса","вовк фенрус"}},{q="Де знайти Фенруса?",a="Фенрус никає кабінетами високо у Фортеці Шадовфенг у Срібноліссі. Його лігво — просто на підступах до внутрішнього сховку Архімага Аруґала.",al={"де фенрус","місце фенруса","кімната фенруса"}},{q="Чи можуть мисливці приборкати Фенруса?",a="Ні. Хоч формально він звичайний звір, Фенруса не приборкати. Його розум цілком зламаний, здичавілий і прикутий до темної волі Архімага Аруґала.",al={"чи можна приборкати фенруса","чи приборкується фенрус","приборкання фенруса"}},{q="Чому Аруґал викликає демонів, коли на Фенруса нападають?",a="Аруґал вважає Фенруса своїм дорогоцінним улюбленцем і останнім рубежем оборони перед своїм святилищем. Коли Фенрус ревом вступає в бій, Аруґал втручається особисто й викликає до зали блукачів Порожнечі, щоб здолати тих, хто загрожує його звірові.",al={"духи порожнечі аруґала","чому аруґал допомагає фенрусові","фенрус дух порожнечі"}},{q="Чому Фенрус набагато більший за звичайних варгів?",a="Вважають, що величезні розміри Фенруса — наслідок темних магічних дослідів Архімага Аруґала або магічних відлунь навали воргенів, що заполонила фортецю.",al={"чому фенрус величезний","розмір фенруса лор","гігантський варг"}},{q="Що стається в усьому підземеллі, коли починається бій із Фенрусом?",a="Вступаючи в бій, Фенрус видає громовий рев, такий гучний, що його чути будь-де у Фортеці Шадовфенг: усі знають, що під дверима Аруґала триває битва.",al={"рев фенруса","виття фенруса в підземеллі","гучний рев у фортеці"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="Фельдмаршал Сноуфолл",s="Фельдмаршал Сноуфолл — дворфійський воєначальник у Військовому Кварталі Айронфорджа, що координує воєнні зусилля Альянсу проти дедалі більшої загрози силітидів. Перед лицем давнього зла, що ворушиться в південних пісках Силітусу, він керує величезною справою постачання, потрібною, щоб спорядити союзні армії. Сноуфолл веде облік пожертвуваної сировини й винагороджує тих, хто допомагає королівству готуватися до війни.",h="Фельдмаршал Сноуфолл — дворфійський воєначальник у Військовому Кварталі Айронфорджа, що координує воєнні...",kw={"фельдмаршал сноуфолл","ан'кіраж","силітус","силітиди","військовий квартал","воєнні припаси","цитадель кенаріуса"},ang={["faction:Alliance"]="Сноуфолл уособлює єдину промислову й військову волю Альянсу: він закликає кожну расу — від Стормвінда до Дарнасуса — спорожнити комори й готуватися до битви.",["race:Dwarf"]="Сноуфолл, що стоїть на варті у військовому кварталі неподалік Великої Кузні, з гордістю говорить про захист творінь титанів від давньої, глибоко вкоріненої мерзоти."},sec={{t="Інтендант походу на Ан'Кіраж",b="Несучи варту у Військовому Кварталі Айронфорджа, Фельдмаршал Сноуфолл є головним координатором мобілізації Альянсу проти Ан'Кіража. Він бачить у конфлікті, що назріває, не просто прикордонну сутичку, а вирішальну битву з давнім ворогом, ворожим до всіх творінь титанів. Сноуфолл наглядає за приголомшливими запасами — мільйонами бинтів, тоннами металевих злитків, шкірою, травами й харчами, які зібрали шукачі пригод, — щоб війська Альянсу були озброєні, вдягнені в броню й нагодовані, коли почнеться похід на південь, до Силітусу."},{t="Шлях до Силітусу",b="Щоб підняти на ноги цілу фракцію, потрібна злагоджена праця ковалів, збирачів, кухарів і солдатів на всіх землях Альянсу. Сноуфолл стежить за кожним етапом цієї величезної операції: приймає почесні печатки й видає добровольцям накази на постачання. Щойно обидві фракції зберуть усі потрібні воєнні припаси, запаси пакують і везуть на південь, до Цитаделі Кенаріуса, готуючи великий наступ на рої комах і Древнього Бога, що причаївся за Стіною Скарабея."}},faq={{q="Хто такий Фельдмаршал Сноуфолл?",a="Фельдмаршал Сноуфолл — високопоставлений дворф-командувач із Військового Кварталу Айронфорджа. Йому доручено наглядати за величезним збором припасів Альянсу для неминучої війни з кіраджі в Силітусі й вести їм лік.",al={"роль сноуфолла","хто такий сноуфолл","лор фельдмаршала сноуфолла"}},{q="Навіщо Альянс збирає стільки припасів?",a="Давня сила загрожує Калімдору з-за брами Ан'Кіража. Щоб успішно провести похід через суворі пустелі Силітусу, Альянс мусить нагромадити величезні запаси обладунків, металевих злитків, бинтів, харчів і трав, перш ніж його війська зможуть вирушити.",al={"навіщо здавати тканину","мета воєнних зусиль","навіщо воєнні припаси"}},{q="Куди йдуть зібрані матеріали?",a="Щойно і Альянс, і Орда виконають свої норми збору, каравани й вантажні кораблі везуть величезні запаси до Цитаделі Кенаріуса в Силітусі, де об'єднані сили облаштовують передові бази.",al={"куди йдуть припаси","що буде з припасами"}},{q="Для чого потрібні Печатки воєнних припасів?",a="Печатки отримують ті, хто жертвує на воєнні потреби потрібну зброю й матеріали. Фельдмаршал Сноуфолл приймає ці печатки пачками й нагороджує сумлінних громадян Альянсу ящиками з припасами та спорядженням за їхню службу.",al={"здача печаток","для чого печатки"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="Польовий Маршал Стоунбрідж",s="Польовий Маршал Стоунбрідж — високопоставлена офіцерка Альянсу, що стоїть біля входу до Стормвінда. Розташувавшись біля Брами Стормвінда в Долині Героїв, вона разом із Генералом Маркусом Джонатаном наглядає за обороною міста й засвідчує великі бойові перемоги.",h="Польовий Маршал Стоунбрідж — високопоставлена офіцерка Альянсу, що стоїть біля входу до Стормвінда.",kw={"польовий маршал стоунбрідж","долина героїв","генерал маркус джонатан","брама стормвінда","гора блекрок","альянс"},ang={["class:Warrior"]="Як одна з верховних командувачок біля міської брами, Польовий Маршал Стоунбрідж користується повагою воїнів передової, що прагнуть здобути високе бойове становище в Альянсі.",["faction:Alliance"]="Стоячи пліч-о-пліч із Генералом Маркусом Джонатаном, Стоунбрідж уособлює незмінну пильність війська Альянсу, що береже Стормвінд від зовнішнього вторгнення."},sec={{t="Оплот біля брами",b="Розташувавшись одразу за височенним входом у Долину Героїв, Польовий Маршал Стоунбрідж несе варту під східною аркою біля головної брами. Високий ранг у війську Великого Альянсу ставить її серед найвищих щаблів стратегічного проводу Стормвінда, і вона діє в тісній співпраці з Генералом Маркусом Джонатаном. З цього помітного місця вона стежить за потоком захисників, мандрівників і звитяжців, що повертаються до столиці, готова зорганізувати гарнізон, якщо загроза прорве зовнішні рубежі."},{t="Та, що приймає трофеї",b="Окрім урочистих і оборонних обов'язків біля міської брами, Польовий Маршал Стоунбрідж приймає важливі донесення й трофеї з походів проти найгрізніших ворогів королівства. Високі командувачі покладаються на офіцерів на кшталт Стоунбрідж, щоб перевіряти важливі відомості й відзначати визначні перемоги в полі — зокрема над воєводами й чудовиськами, що гніздяться серед скель Гори Блекрок."}},faq={{q="Де перебуває Польовий Маршал Стоунбрідж?",a="Вона стоїть під аркою в північно-східній частині Долини Героїв у Стормвінді, праворуч від Генерала Маркуса Джонатана, коли входиш через міську браму.",al={"де стоунбрідж","де польовий маршал стоунбрідж","знайти стоунбрідж"}},{q="Яка роль Польового Маршала Стоунбрідж у Стормвінді?",a="Вона високопоставлена офіцерка Альянсу, що допомагає Генералові Маркусу Джонатану обороняти головну браму Стормвінда, а ще приймає важливі військові донесення й трофеї великих перемог, які приносять звитяжці Альянсу.",al={"що робить стоунбрідж","мета стоунбрідж","хто такий польовий маршал стоунбрідж"}},{q="Яке місце посідає звання польового маршала в Альянсі?",a="Польовий маршал — одне з найвищих офіцерських звань у військовому командуванні Великого Альянсу, одразу після Великого Маршала. Офіцери цього звання керують великими тактичними операціями, ділянками оборони міст і стратегічними гарнізонами.",al={"звання польового маршала альянсу","яке звання в стоунбрідж"}},{q="Які важливі завдання пов'язані з Польовим Маршалом Стоунбрідж?",a="Саме вона приймає донесення й трофей у завданні «Володар Блекрока», засвідчуючи падіння Нефаріана, коли шукачі пригод з Альянсу притягають голову дракона до брами Стормвінда.",al={"завдання стоунбрідж","завдання володар чорної скелі"}}},fp="25,285,22.552.0,18.432.0,43.180.0,54.251.0,45.239.0,52.195.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="Перший Помічник Фіцсіммонс",s="Перший Помічник Фіцсіммонс — обдертий, смердючий моряк, що днями п'є біля Таверни «Глибока Вода» в Гавані Менетіл. Колись він був першим помічником на «Володарці Хвиль» із Третього флоту Кул Тіраса, а тепер — єдиний відомий живий свідок загибелі флоту в Другій війні. Переслідуваний спогадами про ту трагедію, він шукає сміливців, готових вийти проти неспокійних духів його потонулих товаришів.",h="Перший Помічник Фіцсіммонс — обдертий, смердючий моряк, що днями п'є біля Таверни «Глибока Вода» в Гавані...",kw={"фіцсіммонс","гавань менетіл","кул тірас","загублений флот","друга війна","драконяча паща"},ang={["faction:Alliance"]="Фіцсіммонс уособлює трагічну сторінку морської історії Альянсу й нагадує героям про катастрофічні втрати в боротьбі з армадою поневолених драконів Орди.",["race:Human"]="Як ветеран Кул Тіраса, Фіцсіммонс глибоко пов'язаний із мореплавним людським королівством, яке багато чим пожертвувало, обороняючи Лордерон у Другій війні."},sec={{t="Зламаний моряк",b="Перший Помічник Фіцсіммонс, що вилежується біля Таверни «Глибока Вода» у вологому солоному повітрі Гавані Менетіл, — людина, яку легко не помітити, а то й узагалі обійти десятою дорогою, зважаючи на його немитий сморід. Для більшості відвідувачів він лише ще один зламаний старий морський вовк, що топить спогади в чарці. Та хто сяде поруч і вислухає, почує моторошні оповіді про гордий флот, знищений вогнем і пазурами."},{t="Загибель Третього флоту",b="Під час Другої війни Фіцсіммонс служив першим помічником на «Володарці Хвиль», що входила до Третього флоту Кул Тіраса, посланого битися з Ордою. Біля узбережжя Багнокраю флот потрапив у засідку: його спалили поневолені червоні дракони, якими правили орки Драконячої Пащі. Кораблі розтрощило й пустило на дно, і лише Фіцсіммонс зумів живим виповзти на берег."},{t="Прокляття, що не відпускає",b="Уціліти в драконячому полум'ї не означало знайти спокій. Рештки кораблів, які тепер звуть Загубленим Флотом, населяють його колишні товариші по команді — вони повстали проклятою нежиттю й не можуть спочити у своїх водяних могилах. Гнаний провиною і жахом, Фіцсіммонс наймає мандрівників, щоб упокоїти неживих моряків і дістати прадавні реліквії, які, можливо, нарешті знімуть зло, що сковує їхні душі."}},faq={{q="Хто такий Перший Помічник Фіцсіммонс?",a="Це старий моряк із Кул Тірасу, колишній перший помічник на «Володарці Хвиль». Він пережив загибель Третього флоту Кул Тірасу під час Другої війни, а тепер пропиває свої дні біля Таверни «Глибока Вода» в Гавані Менетіл.",al={"лор фіцсіммонса","хто такий фіцсіммонс","перший помічник фіцсіммонс"}},{q="Що сталося з його кораблем?",a="Під час Другої війни на «Володарку Хвиль» і решту Третього флоту напали поневолені червоні дракони, на яких сиділи вершники клану Драконячої Пащі. Кораблі спалили й розтрощили об риф біля узбережжя Багнокраю.",al={"що сталося з хвилею господинею","знищення третього флоту","чому потонув його корабель"}},{q="Де лежить Загублений Флот?",a="Розбиті корпуси флоту лежать під водою вздовж скелястого узбережжя на північ від Гавані Менетіл у Багнокраї; тепер їх стережуть мурлоки й неспокійні духи потонулих моряків.",al={"де загублений флот","де потонулі кораблі","де корабель фіцсіммонса"}},{q="Чому він хоче, щоб шукачі пригод билися з його колишньою командою?",a="Потонулі моряки Третього флоту не відійшли, а повстали проклятою, змученою нежиттю. Фіцсіммонс шукає відважних мандрівників, щоб упокоїти їх і забрати артефакти, які тримають їхні душі в кайданах.",al={"лор завдання проклятої команди","навіщо вбивати його команду"}},{q="Що таке Око Палета?",a="Це давній могутній артефакт, що був на борту Третього флоту. Його темна сила пов'язана з прокляттям, яке тяжіє над потонулими моряками, тож повернути його вкрай важливо, щоб дарувати потонулому флотові спокій.",al={"око палета","реліквія палета"}},{q="Чому від Фіцсіммонса так тхне?",a="Утративши все, коли його флот пішов на дно, Фіцсіммонс роками живе в п'яному занедбанні біля Таверни «Глибока Вода», носить просолене морем лахміття й рідко миється.",al={"чому фіцсіммонс смердить","сморід фіцсіммонса"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {n="Фіззл Брассболтс",s="Фіззл Брассболтс — знаний гномський інженер, що отаборився на розпечених солончаках Перегонів Міражу в Тисячі Голок. Разом зі своїм суперником, гобліном Поззіком, Фіззл заснував ці перегони, щоб у швидкісних заїздах ракетних автомобілів звести гномську точну інженерію з безрозсудною гоблінською винахідливістю. Він повсякчас шукає деталі, пальне й дивні пустельні реагенти, щоб його гоночна команда не зупинялася.",h="Фіззл Брассболтс — знаний гномський інженер, що отаборився на розпечених солончаках Перегонів Міражу в Тисячі...",kw={"фіззл брассболтс","перегони міражу","поззік","ракетні автомобілі","гноми-інженери","мерехтливі низини"},ang={["faction:Alliance"]="Хоч він працює в нейтральній зоні швидкості, Фіззл — привітне обличчя й джерело механічної роботи для мандрівників Альянсу, що прямують на південь, до Танарісу.",["profession:Engineering"]="Колеги-інженери оцінять відданість Фіззла вдосконаленню ракетної тяги й розробці новітніх автомобільних конструкцій у суворих пустельних умовах.",["race:Gnome"]="Фіззл несе в пустелю честь усього Гномреґану й понад усе прагне довести, що гномська точність переважить гоблінську безрозсудність."},sec={{t="Справа принципу й поршнів",b="У тремтливому жарі Мерехтливих Низин політичні союзи й давні образи поступаються ревінню моторів. Фіззл Брассболтс прибув сюди з однією метою: раз і назавжди довести, що гномська майстерність незрівнянно вища за грубе гоблінське майстрування. Разом зі своїм гоблінським колегою Поззіком він допоміг розмітити Перегони Міражу, привівши гоночні автомобілі, механіків і глядачів у цю безлюдну улоговину."},{t="Майстрування на солончаках",b="Шалені перегони по сухих соляних руслах вимагають постійної імпровізації. Як завзятий член Гільдії інженерів-механіків Азероту, Фіззл не цурається незвичних експериментів. Чи то випробовує нестійкі суміші з отрути місцевих істот, чи наймає мандрівників по запасні механічні деталі, Фіззл сповнений рішучості зробити так, щоб колеса його водія крутилися швидше за будь-яку вибухову гоблінську вигадку."}},faq={{q="Хто такий Фіззл Брассболтс?",a="Фіззл Брассболтс — гном, майстер-інженер і головний організатор гномської команди перегонників на Перегонах Міражу в Тисячі Голок.",al={"хто такий фіззл","лор фіззла брассболтса","гном на трасі"}},{q="Чому Фіззл прибув на Мерехтливі Низини?",a="Він прибув, щоб розв'язати технічну суперечку з гоблінським інженером Поззіком про те, чия раса має кращу інженерію. Разом вони заснували Перегони Міражу, щоб випробовувати свої ракетні машини віч-на-віч на рівній солончаковій рівнині.",al={"чому фіззл тут","навіщо траса","чому збудували трасу"}},{q="Що таке MEGA?",a="MEGA — це Механічна Гільдія Інженерів Азероту. Фіззл — її відданий член і втілює прагнення гільдії до ретельного конструювання й технічної досконалості.",al={"гільдія фіззла","гільдія інженерів-механіків","що таке мега"}},{q="Навіщо Фіззлові отрута створінь для перегонових машин?",a="Фіззл постійно експериментує з місцевими реагентами, щоб створювати потужні рідини для двигунів, присадки й прискорювачі, які дадуть його ракетним машинам перевагу над машинами Поззіка.",al={"завдання отрути соляних рівнин","отрута як пальне","навіщо йому отрута"}},{q="Чи воює Фіззл із гоблінами?",a="Не зброєю. Хоч між ними й панує глибока професійна заздрість, Фіззл і Поззік дотримуються на перегонах хиткого нейтрального перемир'я, щоб зосередитися лише на змаганні у швидкості.",al={"чи фіззл ворогує з гоблінами","фіззл і поззік"}},{q="Хто такий Пілот Лонґбірд?",a="Пілот Лонґбірд — дворф-льотчик і особистий друг родини Брассболтсів, що теж любить небезпечні машини й пустельні траси.",al={"зв'язок із пілотом лонґбірдом","друг фіззла пілот"}}},fp="17,397,33.444.0,22.443.0,25.146.0,44.222.0,13.172.0,50.179.0,38.181.0,23.146.0"}
P.entries["npc:fleet-master-seahorn"] = {n="Флотоводець Сігорн",s="Флотоводець Сігорн — досвідчений мореплавець-таурен, морський командувач Нападників Чорної Води в Буті Беї. Разом із Бароном Ревілґазом він стоїть на верхньому балконі таверни «Солоний моряк» і пильнує морську оборону гоблінського порту. Його головний обов'язок — захищати гавань від загрози, яку несуть закляті вороги порту, Буканіри Кривавого Вітрила.",h="Флотоводець Сігорн — досвідчений мореплавець-таурен, морський командувач Нападників Чорної Води в Буті Беї.",kw={"флотоводець сігорн","буті бей","нападники чорної води","буканіри кривавого вітрила","таурен","флот"},ang={["class:Rogue"]="Розбійники, що діють у Буті Беї, знайдуть Сігорна в самому серці прибережного шпигунства: він організовує потаємні напади на бойові кораблі Кривавого Вітрила й перехоплення ворожих наказів.",["faction:Horde"]="Хоча Сігорн — таурен, служить він лише картелю Стімвідл і Нападникам Чорної Води, тож однаково нейтральний і до мандрівників з Орди, і до мандрівників з Альянсу.",["race:Tauren"]="Сігорн — один із надзвичайно рідкісних тауренів, що покинули внутрішні рівнини Калімдору, щоб підкорити відкритий океан, і тепер служить флотоводцем нейтрального гоблінського порту."},sec={{t="Бик у відкритому морі",b="Таурени славляться на весь Калімдор як мешканці рівнин, але Флотоводець Сігорн обрав зовсім інше життя — на морі. У піратському вбранні він командує флотом Нападників Чорної Води — приватними морськими силами, якими картель Стімвідл підкріплює свої справи в Долині Стренглторну. Зі свого місця нагорі таверни «Солоний моряк» Сігорн пліч-о-пліч із Бароном Ревілґазом керує морськими шляхами, розподілом команд і обороною узбережжя беззаконного, проте суворо керованого порту Буті Бей."},{t="Оборона бухти",b="Найбільший постійний клопіт Сігорна — Буканіри Кривавого Вітрила, які облаштували укріплені табори вздовж південного Дикого Берега й поставили на якір бойові кораблі біля узбережжя. Коли донесення показують, що Флотоводець Фіраллон і верхівка Кривавого Вітрила збираються напасти просто на Буті Бей і пограбувати його, Сігорн діє рішуче. Він посилає найманців захопити ворожі листи й знешкодити Фіраллона, Кілгола та Стіллвотера на борту їхнього флагмана — і так рятує порт від цілковитого спустошення."},{t="Очі за морями",b="Окрім відбиття піратських нападів, Сігорн веде різноманітні торговельні й рятувальні справи по всіх Східних Королівствах. Він організовує пошуки затонулих скарбів біля аратійського узбережжя поблизу Бухти Фалдіра, працюючи з водолазами-рятувальниками, щоб здобути ельфійські реліквії. А ще він повідомляє Ревілґазові про вигідні нагоди, що трапляються в місті, — як-от рибальські змагання чи місцеву торгівлю, — щоб флот Чорної Води мав досить грошей і випереджав суперників."}},faq={{q="Де перебуває Флотоводець Сігорн?",a="Він перебуває на верхньому поверсі й балконі Таверни «Солоний Моряк» у Буті Бей — стоїть поряд із Бароном Ревілґазом, звідки видно причали.",al={"де сігорн","місце сігорна","знайти сігорна"}},{q="Чому таурен служить флотоводцем піратів?",a="Хоча більшість тауренів тісно пов'язані з рівнинами й духовними традиціями Малгору, Сігорн обрав життя мореплавця й морського найманця. Морська майстерність і владна вдача принесли йому провід над Нападниками Чорної Води під началом Барона Ревілґаза.",al={"таурен пірат","чому сігорн пірат","таурен у затоці здобичі"}},{q="Які в Сігорна стосунки з Бароном Ревілґазом?",a="Сігорн — заступник Барона Ревілґаза й морський командувач його Нападників Чорної Води. Ревілґаз займається політикою, торгівлею й грошима, а Сігорн керує флотом, тактичною розвідкою й обороною Буті Бей.",al={"сігорн і ревілґаз","чи сігорн охоронець ревілґаза","хто працює на ревілґаза"}},{q="Хто такі Нападники Чорної Води?",a="Нападники Чорної Води — приватний флот корсарів, вірних картелю Стімвідл, із базою в Буті Бей. На відміну від розбійників, що грабують без розбору, вони — визнаний флот, що захищає інтереси гоблінських торговців і підтримує лад у південних морях.",al={"нападники чорної води","якої фракції сігорн","пірати затоки здобичі"}},{q="Чому Сігорн хоче зупинити Буканірів Кривавого Вітрила?",a="Буканіри Кривавого Вітрила — запеклі суперники Нападників Чорної Води. Під проводом Флотоводця Фіраллона вони отаборилися вздовж Дикого Берега й мають намір захопити сам Буті Бей. Сігорн постійно працює, щоб випередити їхні задуми вторгнення.",al={"сігорн проти кривавого вітрила","конфлікт із кривавим вітрилом","чому воювати з кривавим вітрилом"}},{q="Чи має Сігорн справи поза Долиною Стренглторну?",a="Так. Сігорн співпрацює з рятувальниками затонулого майна, як-от Доктор Дракслґейдж і Шейкс О'Брін, щоб піднімати загублені вантажі й ельфійські скарби, що затонули біля Бухти Фалдіра біля Аратійського нагір'я, і доставляти цінні артефакти до свого посту в Буті Бей.",al={"затока фалдіра сігорн","затонулі скарби сігорна","завдання араті сігорн"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="Фоґґі Маккріл",s="Фоґґі Маккріл — відважний дворф, що опинився в небезпечній пастці на зруйнованій нижній кладці Мосту Тандол. Попри розтрощене каміння під ногами й запаморочливу прірву внизу, його по-справжньому турбує лише одне — доставити свій самогон на північ, до Саутшора.",h="Фоґґі Маккріл — відважний дворф, що опинився в небезпечній пастці на зруйнованій нижній кладці Мосту Тандол.",kw={"фоґґі маккріл","міст тандол","самогон","саутшор","темне залізо","багнокрай"},ang={["faction:Alliance"]="Гінці Альянсу, що мандрують між Айронфорджем і північною заставою Саутшор, часто зустрічають Фоґґі й забирають його застряглий вантаж, щоб допомогти іншому підданому Альянсу.",["race:Dwarf"]="Маккріл утілює вперту стійкість — і дивні пріоритети — дворфійського роду: вчасна доставка міцного трунку для нього важить куди більше за такі дрібниці, як те, що він застряг над смертельною прірвою."},sec={{t="У пастці на мосту",b="Сидячи на розбитих опорах під зруйнованим Мостом Тандол, Фоґґі Маккріл, здається, анітрохи не переймається своїм небезпечним становищем. Хоч диверсії Темного Заліза й воєнні руйнування розкололи величний міст між Багнокраєм і Аратійським нагір'ям, Маккріл вважає хиткий ґрунт під ногами дрібною незручністю. Він думає не про власний порятунок, а про недоставлену партію міцного самогону для відвідувачів шинку в Саутшорі, що в Передгір'ї Гілсбреда. Він охоче наймає мандрівних шукачів пригод, досить спритних, щоб дістатися його виступу, аби вони довершили доставку замість нього."}},faq={{q="Хто такий Фоґґі Маккріл?",a="Фоґґі Маккріл — дивакуватий дворф-посланець, що застряг на зруйнованих кам'яних опорах під розваленим Мостом Тандол. Попри висоту, він зовсім спокійний і думає лише про те, щоб доставити свій самогон.",al={"фоґґі маккріл","хто такий фоґґі","маккріл нпс"}},{q="Де знайти Фоґґі Маккріла?",a="Він стоїть на кам'яному майданчику посередині зруйнованого центрального прольоту Мосту Тандол: туди можна обережно зістрибнути з конструкції мосту з боку Аратійського нагір'я.",al={"де фоґґі маккріл","місце фоґґі маккріла","як знайти маккріла"}},{q="Що Фоґґі Маккріл робить там, унизу?",a="Мандруючи, Фоґґі застряг серед уламків Мосту Тандол. Але замість шукати порятунку, він найбільше переймається тим, щоб знайти когось, хто донесе його самогон рештою шляху до Саутшору.",al={"чому фоґґі застряг","як маккріл туди потрапив","чому він на мосту"}},{q="Яке завдання дає Фоґґі Маккріл?",a="Він дає завдання «Самогон МакКрила», просячи мандрівників доставити глек його міцного трунку до таверни в Саутшорі через Аратійське нагір'я.",al={"завдання фоґґі","завдання самогон маккріла","яке завдання дає фоґґі"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {n="Бригадир Ослоу",s="Бригадир Ослоу — знесилений головний будівничий Лейкшира, якому доручили відновити зруйнований міст через Озеро Незрушне в серці Гір Редріджу. Під обстрілом катапульт орків Блекрок і нападами гнолів відбудова застрягла: вантажі загублено, а знаряддя пішло на дно. Ослоу покладається на мандрівних шукачів пригод, щоб повернути своє спорядження й роздобути матеріали, аби Лейкшир знову відкрив свій життєво важливий торговий шлях.",h="Бригадир Ослоу — знесилений головний будівничий Лейкшира, якому доручили відновити зруйнований міст через...",kw={"бригадир ослоу","міст","лейкшир","озеро незрушне","гори редріджу","будівництво"},ang={["faction:Alliance"]="Зруйнований міст Лейкшира лишає східний рубіж відкритим, тож відбудова, яку веде Ослоу, — стратегічна необхідність для захисту кордону Альянсу.",["profession:Mining"]="Ослоу потребує сировини, металевих виробів і каменю з каменоломень, щоб відновити зруйновану кладку, тож він тісно пов'язаний із місцевими постачаннями руди й каменю."},sec={{t="Місто, розірване надвоє",b="Стоячи біля потрощеної кладки зруйнованого мосту, Бригадир Ослоу веде важку боротьбу. Міст — життєва артерія Лейкшира: він перетинає Озеро Незрушне й з'єднує західні дороги до Елвінна зі східними берегами. Орки Блекрок, що спускаються з круч Кам'яної Варти, вдарили по переправі, щоб паралізувати постачання й пересування військ, і поселення опинилося розколотим і вразливим."},{t="Затоплена сталь і вкрадений камінь",b="Кожна спроба Ослоу відбудувати міст ніби проклята. Коли міст упав, нове знаряддя привезли суходолом із Ґолдшира й навантажили на озерний пором. Обслуга орочих катапульт узяла судно на приціл, і важка залізна скриня з інструментами пішла просто на мулисте дно Озера Незрушного. Ніби цього було мало, місцеві гноли Редріджу влаштували засідку на його вози з припасами й поцупили колоди та будівельні заклепки, потрібні, щоб звести арки."}},faq={{q="Хто такий Бригадир Ослоу?",a="Бригадир Ослоу — каменяр і будівничий-людина з Лейкширу. Він головний майстер, що відповідає за ремонт і відбудову Незрушного Мосту.",al={"бригадир ослоу","хто такий ослоу","будівельник лейкшира"}},{q="Чому Незрушний Міст зруйновано?",a="Незрушний Міст зруйнували орки Блекрок із Гір Редріджу. Обваливши проліт, вони перерізали головний шлях Лейкширу, тяжко послабивши оборону містечка й ускладнивши сполучення між східним і західним берегами.",al={"чому зламаний міст","хто зламав міст лейкшира","незрушний міст зруйновано"}},{q="Де загублені інструменти Ослоу?",a="Важкий ящик з інструментами Ослоу лежить на дні Озера Незрушне. Човен, що віз їх із Ґолдширу, потопив обстріл із катапульт Блекрок.",al={"де інструменти","де загублені інструменти","скринька ослоу"}},{q="Чому міст досі не полагоджено?",a="Катапульти орків потопили його інструменти в озері, а гноли крадуть будівельні припаси з вантажів, що надходять, тож Ослоу без сторонньої допомоги не має ні матеріалів, ні знарядь, щоб продовжити будівництво.",al={"чому міст не полагодили","затримка мосту лейкшира"}},{q="Звідки спершу були припаси Ослоу?",a="Нові інструменти спершу привезли возом із Ґолдширу в Лісі Елвінн, а тоді перевантажили на озерний пором, щоб оминути зруйнований проліт.",al={"звідки віз із припасами","звідки взялися інструменти"}},{q="З якими загрозами стикається Ослоу?",a="Ослоу постійно дошкуляють із двох боків: орки клану Блекрок, що окопалися на сусідніх висотах і обстрілюють озеро з облогових машин, і гноли, що нишпорять довкола й нападають на обози з припасами.",al={"вороги ослоу","хто нападає на міст"}}},fp="13,413,17.430.0,29.449.0,21.172.0,35.246.0,29.155.0,40.213.0,48.158.0,35.193.0"}
P.entries["npc:foreman-stonebrow"] = {n="Наглядач Стоунброу",s="Наглядач Стоунброу — дворфійський наглядач, що представляє Лігу Шахтарів у Кар'єрі Гол'Болар на сході Дун Мороґу. Коли зі скелі вирвалися люті троги й захопили розкопки, йому довелося організувати оборону й наймати шукачів пригод, щоб розчистити ями.",h="Наглядач Стоунброу — дворфійський наглядач, що представляє Лігу Шахтарів у Кар'єрі Гол'Болар на сході Дун...",kw={"наглядач стоунброу","ліга шахтарів","кар'єр гол'болар","троги","шахтарі","дун мороґ","харанос"},ang={["profession:Mining"]="Шахтарі мають професійний інтерес допомогти Стоунброу: повернути багаті поклади каменю й руди в кар'єрі життєво важливо для гільдійських робіт Каз Модану.",["race:Dwarf"]="Для дворфів навала трогів на Кар'єр Гол'Болар — прямий удар по каменярській промисловості Айронфорджа й похмуре нагадування про прадавні загрози, що чаяться під рідною землею."},sec={{t="Криза в Гол'Боларі",b="Наглядачу Стоунброу доручили керувати роботами в Кар'єрі Гол'Болар — важливих дворфійських розкопках у горах на схід від Хараноса. Коли глибоке копання пробилося до прихованих нір трогів, підземні тварюки заполонили ями й відігнали шахтарів від їхнього обладнання. Не бажаючи зовсім кидати місце, Стоунброу лишається на краю кар'єру, щоб залучити будь-яких здатних мандрівників, готових відтіснити трогів."}},faq={{q="Хто такий Наглядач Стоунброу?",a="Наглядач Стоунброу — дворф із Ліги Шахтарів, що наглядає за роботами в Кар'єрі Гол'Болар у Дун Мороґу. Він координує роботу й намагається вберегти кар'єр.",al={"стоунброу","хто такий стоунброу","лор наглядача стоунброу"}},{q="Чому Наглядач Стоунброу просить допомоги?",a="Розкопки в Кар'єрі Гол'Болар ненароком пробили підземні печери трогів. Троги заполонили нижні тераси, вбили робітників і змусили вцілілих шахтарів відступити до табору на краю кар'єру.",al={"проблема трогів ґол'болара","навіщо потрібна допомога","завдання в кар'єрі"}},{q="Що таке Ліга Шахтарів?",a="Ліга Шахтарів — дворфська гільдія й торгова організація з осередком в Айронфорджі, що наглядає за гірничими експедиціями, видобутком ресурсів і роботою кар'єрів по всьому Каз Модану.",al={"ліга шахтарів","що таке ліга шахтарів"}},{q="Де знайти Наглядача Стоунброу?",a="Він стоїть у таборі на краю Кар'єру Гол'Болар, серед східних пагорбів Дун Мороґу, просто біля дороги на Лох Модан.",al={"місце стоунброу","де наглядач стоунброу"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Наглядач Тазз'ріл",s="Наглядач Тазз'ріл — орк-наглядач за працею в Долині Випробувань у Дуроторі. Його справа — тримати пеонів у графіку й підтримувати базову інфраструктуру для молодих воїнів, і його невпинно дратують ліниві робітники та діяльність культистів поблизу.",h="Наглядач Тазз'ріл — орк-наглядач за працею в Долині Випробувань у Дуроторі.",kw={"тазз'ріл","наглядач","пеони","кирка","долина випробувань","ковен палаючого клинка","дуротар"},ang={["profession:Mining"]="Тазз'ріл цінує якісне гірниче знаряддя — досить згадати, як відчайдушно він хоче повернути свою зачаровану кирку з темних закутків Ковену Палаючого Клинка.",["race:Orc"]="Для молодих орків, що входять у дорослий вік, Тазз'ріл — ранній урок про суспільство Орди: сила на полі бою можлива лише тоді, коли її підпирає невдячна, дисциплінована праця."},sec={{t="Тримати пеонів у шорах",b="Збудувати новий дім у суворому червоному камені Дуротару — означає безкінечну фізичну працю. У Долині Випробувань Наглядач Тазз'ріл керує пеонами, що рубають ліс і збирають матеріали, потрібні і для табору, і для ширших воєнних зусиль Орди. На біду Тазз'ріла, пеони відомі схильністю байдикувати й дрімати під пустельним сонцем. Щоб будівництво не спинялося, він регулярно залучає новоприбулих новобранців добряче огріти заснулих робітників своїм надійним кийком, прищеплюючи послух тупою переконливістю."},{t="Загублена кирка в небезпечних руках",b="Обов'язки Тазз'ріла включають і розвідку мінеральних ресурсів долини, хоч саме цей обов'язок призвів до прикрої невдачі. Оглядаючи печеру, відому як Ковен Палаючого Клинка, він мусив тікати від темних культистів, що причаїлися всередині, і ненароком покинув свою дорогоцінну зачаровану кирку. Надто обережний, щоб самому забрати її серед чорнокнижників, що збираються там, і їхніх демонічних прислужників, він покладається на молодих кандидатів Орди, аби ті спустилися в глибини й повернули його знаряддя."}},faq={{q="Хто такий Наглядач Тазз'ріл?",a="Наглядач Тазз'ріл — орк, наглядач за роботами в Долині Випробувань у Дуротарі. Він керує робітниками, рубанням лісу й розвідує край у пошуках корисних ресурсів для поселень Орди.",al={"хто такий тазз'ріл","тазз'ріл долина випробувань","лор наглядача тазз'ріла"}},{q="Чому Тазз'ріл дає гравцям кийок?",a="Пеони під його наглядом раз у раз засинають під деревами замість рубати ліс. Тазз'ріл дає зачарований дерев'яний кийок, щоб вбити в них трохи дисципліни й змусити хутко повернутися до роботи.",al={"навіщо бити ледачих пеонів","кийок тазз'ріла","лор завдання ледачих пеонів"}},{q="Чому кайло Тазз'ріла опинилося в печері Палаючого Клинка?",a="Розвідуючи місцеві печери в пошуках рудних жил, Тазз'ріл натрапив на Ковен Палаючого Клинка. Наляканий культистами, що ховалися в тіні, він хутко відступив і лишив там своє цінне зачароване кайло.",al={"кайло тазз'ріла","чому кайло в лігві","кайло палаючого клинка"}},{q="Яка його роль в Орді?",a="Тазз'ріл не воїн передової й не шаман, а цивільний наглядач. Його обов'язки — господарський хребет Дуротару: наглядати за ручною працею, дбати про будівельні припаси й пильнувати, щоб пеони працювали.",al={"чи тазз'ріл вояк","звання тазз'ріла"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="Наглядач Тистлнеттл",s="Наглядач Тистлнеттл колись був дворфом-наглядачем, що представляв і Лігу Шахтарів, і Лігу Дослідників у глибинах Вестфолу. Після катастрофічного обвалу, який замкнув його бригаду в підземних тунелях Мертвих Копалень, він загинув разом зі своїми робітниками й повстав знову як гуль-нежить. Тепер він блукає темними, засипаними коридорами, і впізнати його можна хіба що за знаком гільдії, який він досі носить.",h="Наглядач Тистлнеттл колись був дворфом-наглядачем, що представляв і Лігу Шахтарів, і Лігу Дослідників у...",kw={"наглядач тистлнеттл","мертві копальні","ліга шахтарів","ліга дослідників","вайлдер тістлнетл","гуль"},ang={["profession:Mining"]="Доля Тистлнеттла — сумне нагадування всім шахтарям про постійну небезпеку обвалів і ворожих підземних глибин.",["race:Dwarf"]="Трагічна загибель наглядача з Ліги Дослідників і цілої дворфійської бригади показує, які небезпеки досі чаяться під людськими королівствами."},sec={{t="Трагедія в Мертвих Копальнях",b="Перш ніж Братство Дефіас цілком захопило Мертві Копальні, у їхні багаті жили заглиблювалися законні гірничі експедиції. Наглядач Тистлнеттл очолював одну з них від імені Ліги Шахтарів і Ліги Дослідників. Глибоко в тунелях під Мунбруком сталася біда: потужний обвал відрізав його загін від поверхні. Замкнені шахтарі загинули в темряві, але спочивали недовго — зловісна некротична скверна підняла Тистлнеттла та його бригаду ненажерливими гулями, що блукають темними проходами."},{t="Горе брата",b="У Стормвінді його брат Вайлдер Тістлнетл місяцями не знаходив собі місця, гадаючи про долю зниклої бригади. Із захоплених тунелів не долинало жодної звістки, аж поки не поповзли чутки, що загиблий наглядач досі блукає серед мерців. Шукачів пригод, які наважуються зазирнути на околиці Мертвих Копалень, просять знайти наглядача-нежить, покласти край його мукам і принести його знак, щоб скорботна рідня нарешті знайшла спокій."}},faq={{q="Ким був Наглядач Тистлнеттл до смерті?",a="Він був дворфом-наглядачем, пов'язаним і з Лігою Шахтарів, і з Лігою Дослідників. Він повів загін шахтарів у Мертві Копальні ще до того, як розбійники остаточно їх укріпили, щоб розкопувати й обстежувати підземні жили.",al={"лор тистлнеттла","хто такий наглядач тистлнеттл","минуле тистлнеттла"}},{q="Чому Наглядач Тистлнеттл став неживим гулем?",a="Нищівний обвал завалив тунелі довкола Тистлнеттла та його загону шахтарів і вбив їх. Згодом темні підземні сили чи залишки некромантії в лабіринті копалень оживили їхні рештки, перетворивши дворфів на неспокійних гулів.",al={"чому він гуль","як помер тистлнеттл","тистлнеттл нежить"}},{q="Де перебуває Наглядач Тистлнеттл?",a="Він блукає глухим заваленим тунелем у зовнішньому лабіринті Мертвих Копалень, ще перед порталом до самого підземелля, в оточенні своїх оживлених колишніх шахтарів.",al={"де знайти тистлнеттла","місце тистлнеттла","наглядач у мертвих копальнях"}},{q="Хто шукає Наглядача Тистлнеттла?",a="Його брат, Вайлдер Тістлнетл, що живе в Дворфійському Кварталі Стормвінда. Вайлдер хоче мати доказ того, що сталося з його братом, і просить мандрівників принести Відзнаку Тислнетла.",al={"хто хоче смерті тистлнеттла","брат вайлдера","хто дає завдання про тистлнеттла"}}},fp="21,416,24.530.0,17.419.1,45.237.0,45.261.0,39.181.0,41.186.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Фрагун Шейдвіспер",s="Фрагун Шейдвіспер — наставник розбійників, нічний ельф, що перебуває в Алдрассилі в Тінедолі. Він дає щойно посвяченим розвідникам і розбійникам — нічним ельфам основи скрадання, спритності й прихованих ударів. Він носить те саме родове ім'я, що й Еріон Шейдвіспер, інший наставник його ремесла в Дарнасусі.",h="Фрагун Шейдвіспер — наставник розбійників, нічний ельф, що перебуває в Алдрассилі в Тінедолі.",kw={"фрагун шейдвіспер","розбійник","наставник","алдрассил","тінедол","скрадання","еріон шейдвіспер"},ang={["class:Rogue"]="Фрагун Шейдвіспер — найперший класовий наставник розбійників — нічних ельфів, що дає початкове знайомство зі скраданням, тактикою засідок і тонкощами володіння зброєю.",["race:NightElf"]="Фрагун показує, як нічні ельфи обертають природну нічну вдачу й невловимість на смертоносні, практичні бойові навички для захисту Тельдрассила."},sec={{t="Наставник у тінях",b="У безпечному прихистку Алдрассила, в серці Тельдрассила, Фрагун Шейдвіспер навчає майбутніх розбійників тихого мистецтва маскування й володіння клинком. Хоч суспільство нічних ельфів частіше вшановує жерців, вартових і друїдів, особливе ремесло розвідників і лазутчиків лишається неодмінним для захисту віття Світового Дерева. Фрагун приймає новобранців, які приходять із зашифрованим сигілом, оцінює їхній потенціал і спрямовує їхній ранній розвиток."}},faq={{q="Хто такий Фрагун Шейдвіспер?",a="Фрагун Шейдвіспер — наставник розбійників із нічних ельфів в Алдрассилі на Тельдрассилі. Він навчає розбійників-початківців основ скритності, точного бою й таємної тактики.",al={"лор фрагуна","хто такий фрагун","роль фрагуна шейдвіспера"}},{q="Де знайти Фрагуна Шейдвіспера?",a="Він перебуває в Алдрассилі — головній твердині початкового краю Тінедол на Тельдрассилі.",al={"місце фрагуна","де фрагун","знайти фрагуна шейдвіспера"}},{q="Чи родич Фрагун Еріонові Шейдвісперу?",a="Через спільне прізвище й спільну відданість навчанню розбійників на Тельдрассилі Фрагуна загалом вважають родичем Еріона Шейдвіспера, що навчає розбійників у Дарнасусі.",al={"еріон шейдвіспер брат","фрагун і еріон родичі","рід шейдвіспер"}},{q="Яку роль відіграє Зашифрований Сигіл?",a="Розбійники-початківці з нічних ельфів починають свій шлях, приносячи зашифрований сигіл просто Фрагунові: це знак, що вони готові до справжнього навчання розбійницького ремесла.",al={"здача зашифрованого сигіла","сигіл фрагуна","початкове завдання розбійника"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {n="Фурен Лонґбірд",s="Фурен Лонґбірд — дворф, майстер-бронник, що працює в гомінкому Дворфійському Кварталі Стормвінда. Учень славетного коваля Ґріманда Елмора, він спеціалізується на важкому захисному спорядженні й міцних кольчугах для досвідчених захисників Альянсу. Воїни з усього королівства шукають його знань у металургії, щоб викувати особливі бойові обладунки.",h="Фурен Лонґбірд — дворф, майстер-бронник, що працює в гомінкому Дворфійському Кварталі Стормвінда.",kw={"фурен лонґбірд","бронник","дворф","ковальство","дворфійський квартал","обладунки"},ang={["class:Warrior"]="Для воїнів Альянсу, що мужніють у боях, Фурен Лонґбірд — ключовий знайомий, який перетворює бойову рішучість і зібрані реагенти на надійні, загартовані вогнем обладунки.",["profession:Blacksmithing"]="Фурен утілює високі стандарти дворфійського ковальства в Стормвінді й показує передові прийоми, що дісталися йому від Ґріманда Елмора.",["race:Dwarf"]="Навіть далеко від Айронфорджа Фурен Лонґбірд береже традиції дворфійської металургії в самому серці людської столиці."},sec={{t="Дворфійський коваль у людській столиці",b="Фурен Лонґбірд займається своїм ремеслом далеко від великих горнів Айронфорджа — він оселився серед бруківки й кіптяви Дворфійського Кварталу Стормвінда. Як і багато його родичів, Фурен приніс на південь традиційну дворфійську металургію, щоб підтримати відбудову й оборону королівства. Працюючи серед палаючих горнів і дзвінких ковадел, він підтримує міцні зв'язки з іншими майстрами міста й не лише."},{t="Майстерність загартованої кольчуги",b="Навчений шановним майстром Ґрімандом Елмором, Фурен удосконалив прийоми обробки важких кольчуг і лат, щоб ті витримували найжорстокіші удари на полі бою. Перспективні молоді воїни, що шукають надійного захисту, часто звертаються до Фурена, а той вимагає рідкісних руд, особливих складників і екзотичних реагентів із далеких куточків світу, щоб викувати свої фірмові загартовані вогнем обладунки."}},faq={{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворф, майстер обладунків із Дворфійського Кварталу Стормвінда. Він важливий зв'язковий і наставник для воїнів Альянсу, що прагнуть здобути майстерно викувану кольчугу.",al={"хто такий фурен","лор фурена лонґбірда","дворф бронник стормвінда"}},{q="Де знайти Фурена Лонґбірда?",a="Він перебуває в Дворфійському Кварталі Стормвінда, біля гамірних кузень і ковальських майстерень, якими славиться цей квартал.",al={"де фурен лонґбірд","місце фурена лонґбірда","фурен стормвінд"}},{q="Хто навчив Фурена ковальського ремесла?",a="Обладункової справи й металургії Фурена навчив Ґріманд Елмор — шанований досвідчений майстер, що теж живе в Дворфійському Кварталі.",al={"вчитель фурена","наставник фурена","хто навчав фурена"}},{q="Якими обладунками славиться Фурен?",a="Він славиться Загартованою Вогнем Кольчугою — міцним обладунком, який виготовляють за складною металургійною технологією з рідкісних складників, зібраних по всьому континенту.",al={"гартована кольчуга","завдання фурена про броню","завдання воїна на кольчугу в стормвінді"}},{q="Чи родич Фурен Лонґбірд інших Лонґбірдів?",a="Він має спільне клан-ім'я з кількома іншими відомими дворфами Східних Королівств, як-от досвідчений Пілот Лонґбірд, проте сам зосереджений лише на ковальстві.",al={"родина фурена","клан лонґбірд","родич пілота лонґбірда"}},{q="Чому воїни шукають Фурена Лонґбірда?",a="Воїнів, що довели свою основну бойову вправність, посилають до Фурена, щоб отримати важкі, міцні обладунки, здатні витримати бої на передовій із небезпечнішими ворогами.",al={"чому воїни навідують фурена","завдання воїна в дворфійському кварталі","тренер воїнів фурен"}}},fp="15,369,36.416.0,29.380.0,23.205.0,35.145.0,36.130.0,40.180.0,47.179.0,41.169.0"}
P.entries["npc:furl-scornbrow"] = {n="Фурл Скорнброу",s="Фурл Скорнброу — літній орк-дозорець на сторожовій вежі на північний захід від Гострого Пагорба. Через похилі роки він уже не може битися на передовій, тож пильнує червоні каньйони Дуротару й шиє міцні торби для молодих мандрівників, що вирушають краєм.",h="Фурл Скорнброу — літній орк-дозорець на сторожовій вежі на північний захід від Гострого Пагорба.",kw={"фурл скорнброу","дозорець","сторожова вежа","гострий пагорб","торби","ветеран","дуротар"},ang={["faction:Horde"]="Розташований на хребтах за Гострим Пагорбом, Фурл утілює пильність, потрібну, щоб захистити молоді поселення Дуротару від загроз, які нікуди не поділися.",["race:Orc"]="Фурл утілює орче переконання: навіть коли вік відбирає у воїна бойову силу, гідне життя означає знайти інший спосіб служити клану й Орді."},sec={{t="Дозорець на хребті",b="Високо на дерев'яній сторожовій вежі одразу на північний захід від Гострого Пагорба Фурл Скорнброу несе тиху варту над центральними рівнинами Дуротару. У напружені перші дні після заснування Оргріммара вартові на кшталт Фурла були життєво важливі: саме вони сурмили в сигнальні роги проти ворожих шипогривів, кентаврів і зайд із Кул Тірасу. Відколи Дуротар устабілізувався, а Гострий Пагорб зміцнив кордони, тривоги стали рідшими, і у Фурла на посту вдосталь тихих годин."},{t="Корисна пара рук",b="Фурл відверто визнає, що старі кістки й згасла сила роблять його непотрібним у бою, та орк нелегко зрікається свого призначення. Замість сидіти без діла, він береться шити парусинові мішки й торби для нових новобранців, яким треба носити припаси. В обмін на грубу нитку й практичні матеріали він споряджає зелених шукачів пригод, що вирушають довести свою цінність Орді."}},faq={{q="Хто такий Фурл Скорнброу?",a="Фурл Скорнброу — старий орк-вартовий, що стоїть на дозорній вежі на скелях на північний захід від Гострого Пагорба. Через вік він уже не може битися на передовій, тож пильнує обрій і шиє торби для молодих мандрівників.",al={"хто такий фурл","лор фурла скорнброу","фурл у гострому пагорбі"}},{q="Яка роль Фурла в Дуротарі?",a="Він стоїть на вежі із сигнальним рогом і пильнує, чи не підходять загарбники до Гострого Пагорба. Відтоді як Дуротар під владою Орди став безпечнішим, він б'є на сполох куди рідше, а вільний час присвячує тому, щоб допомагати новобранцям лаштувати спорядження.",al={"що робить фурл","мета фурла"}},{q="Чому Фурл просить у мандрівників матеріали?",a="Фурл вірить, що кожен член Орди мусить робити свій внесок, хоч би що. Битися він уже не може, тож шиє практичні похідні торби для молодших воїнів і просить лише простих матеріалів, як-от грубої нитки, щоб завершити роботу.",al={"лор завдання про внесок","навіщо фурлу нитки"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Ґеролас Талветрен",s="Ґеролас Талветрен — вартовий, нічний ельф, що стоїть на сторожі руїн Села Зоряного Вітерця в Тельдрассилі. Призначений захисником Сплячих друїдів, він шукає допомоги проти напасливих фурболгів і темної скверни, що збурює віття.",h="Ґеролас Талветрен — вартовий, нічний ельф, що стоїть на сторожі руїн Села Зоряного Вітерця в Тельдрассилі.",kw={"ґеролас талветрен","вартовий","сплячі друїди","село зоряного вітерця","вузлошкіри","фурболги","смарагдовий сон"},ang={["class:Druid"]="Обов'язок Ґероласа як охоронця сплячих друїдів робить допомогу йому особистою справою захисту побратимів із Кола Кенарія.",["race:NightElf"]="Для молодих нічних ельфів, що покидають Доланаар, допомога Ґероласу дає тверезий погляд на те, як глибоко скверна проникла у священне віття Тельдрассила."},sec={{t="Охоронець Сплячих",b="Посеред стривоженого поселення Зоряного Вітерця Ґеролас Талветрен несе урочистий обов'язок захищати Сплячих друїдів, що спочивають у єднанні зі Смарагдовим Сном. Його варта стала тривожною, відколи неприродна скверна повзе лісом, порушуючи рівновагу Тельдрассила."},{t="Загроза Вузлошкірів",b="Ґеролас спрямовує мандрівників дати відсіч племені фурболгів Вузлошкірів, чий розум обернувся на безумство й дикість. Досліджуючи скверну, що шириться від їхніх шаманів, і шукаючи корені їхнього лиха, він сподівається зберегти рештки святості у східному Тельдрассилі."}},faq={{q="Хто такий Ґеролас Талветрен?",a="Він нічний ельф-захисник із Села Зоряного Вітерця, якому доручено оберігати сплячих друїдів і розслідувати дивну скверну, що вразила край.",al={"ґеролас","хто такий ґеролас","роль ґероласа"}},{q="Де знайти Ґероласа Талветрена?",a="Він перебуває в Селі Зоряного Вітерця на східних гілках Тельдрассила, на схід від Доланаара.",al={"місце ґероласа","де ґеролас талветрен","знайти ґероласа"}},{q="Хто такі «Сплячі», яких оберігає Ґеролас?",a="Сплячими звуть друїдів нічних ельфів, що поринули в довгий сон у курганах і святилищах, щоб мандрувати Смарагдовим Сном, і залишили свої тіла вразливими до фізичної шкоди.",al={"сплячі","хто такі сплячі","сплячі друїди"}},{q="Які загрози непокоять Ґероласа?",a="Його глибоко тривожить скверна, що вразила місцевих звірів, і раптова шалена ворожість племені фурболгів-Вузлошкірів.",al={"загрози старбриз","завдання ґероласа","біда гнарлпайнів"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="Ґакін Зв'язувач Темряви",s="Ґакін Зв'язувач Темряви — майстер-чорнокнижник, що таємно діє глибоко під таверною «Зарізане Ягня» в Кварталі магів Стормвінда. Він навчає охочих чаклунів Альянсу темних мистецтв, випробовуючи їхню рішучість, перш ніж допустити до обрядів виклику й підкорення потойбічних демонів.",h="Ґакін Зв'язувач Темряви — майстер-чорнокнижник, що таємно діє глибоко під таверною «Зарізане Ягня» в Кварталі...",kw={"ґакін","чорнокнижник","зарізане ягня","демони","блукач порожнечі","сукуб"},ang={["class:Warlock"]="Ґакін — важливий наставник для чорнокнижників-людей і гномів: він дає ключові класові завдання, щоб опанувати обряди підкорення блукача Порожнечі й сукуба в склепах Стормвінда.",["faction:Alliance"]="Таємний ковен Ґакіна під столицею показує прагматичні, оповиті тінню компроміси, на які йдуть у самому серці Альянсу."},sec={{t="Таємне місце збору",b="Маги Стормвінда відкрито практикують у своїх височенних святилищах, а от адептам тіні й скверни доводиться жити там, куди не сягають цікаві очі. Під шинком таверни «Зарізане Ягня» сховано вогкий льох, схожий на склеп, із колами виклику й похмурими фоліантами. Ґакін — осердя цього таємного кола: він дбає, щоб молоді чорнокнижники навчилися дисципліни й стриманості, перш ніж випускати жахіття, яких не зможуть контролювати."},{t="Повелитель демонів",b="Ґакін — знавець демонології та обрядів підкорення. Посвячених, які заслужили його увагу, він розсилає по всьому королівству по рідкісні реліквії й складники — від викрадених амулетів із кровавика до зіпсованої деревини з темних лісів. Щойно реагенти зібрано, Ґакін наглядає за обрядами в колі виклику в склепі, змушуючи новачків підкорювати блукачів Порожнечі й сукубів у випробуваннях волі на життя і смерть."},{t="Зради й незавершені справи",b="Не всі учні Ґакіна лишаються слухняними. Одна з колишніх учениць, Сурена Каледон, утекла в дикі краї з цінним Намистом Кровавика. Такі внутрішні зради загрожують виказати коло чорнокнижників міській варті, тож Ґакін посилає вірних послідовників повернути втрачені артефакти й прибрати свідків, перш ніж влада щось помітить."}},faq={{q="Де знайти Ґакіна Зв'язувача Темряви?",a="Ґакін перебуває глибоко під таверною «Зарізане Ягня» в Кварталі магів Стормвінда. Зайдіть у таверну, знайдіть у глибині спуск і пройдіть кам'яними тунелями вниз, доки не дійдете до кола виклику в найнижчому склепі.",al={"де ґакін","місце ґакіна","підвал зарізаного ягняти"}},{q="Що робить Ґакін Зв'язувач Темряви?",a="Він відомий наставник чорнокнижників Альянсу, що дає їм завдання. Він випробовує новачків, посилаючи їх на випробування по всьому Азероту, і навчає викликати й підкоряти демонів, як-от Блукача порожнечі й Сукуба.",al={"що робить ґакін","роль ґакіна","завдання ґакіна"}},{q="Чому чорнокнижникам дозволено бути під «Зарізаним Ягням»?",a="Демонічна магія в Стормвінді заборонена й викликає глибоку недовіру. Чорнокнижники під «Зарізаним Ягням» діють у суворій таємниці: їх терплять лише як небезпечний прихований ресурс і ховають від міської варти й містян.",al={"чому чорнокнижникам дозволено","чи чорнокнижники легальні в стормвінді","лор зарізаного ягняти"}},{q="Хто така Сурена Каледон?",a="Сурена Каледон — колишня учениця Ґакіна, що викрала в нього могутнє Намисто Кровавика. Її зрада загрожує їхньому прихованому ордену, тож Ґакін доручає чорнокнижникам її вистежити.",al={"сурена каледон","учениця ґакіна","хто крав у ґакіна"}},{q="Яких демонів Ґакін допомагає викликати?",a="Ґакін наглядає за ритуалами підкорення і блукачів Порожнечі, і сукубів: він навчає чорнокнижників заманювати цих створінь у підземне коло й приборкувати їх.",al={"демони ґакіна","ґакін дух порожнечі","ґакін суккуба"}},{q="Хто такий Страгад і чому Ґакін про нього згадує?",a="Страгад Фарсан — досвідчений чорнокнижник, що живе на пагорбах біля Раджета в Калімдорі. Коли учень опанує основні ритуали підкорення Ґакіна, той посилає його за море, щоб продовжити темніше навчання в Страгада.",al={"страгад","пошук страгада","куди ґакін посилає далі"}}},fp="20,297,24.429.0,16.411.0,24.365.1,38.247.0,34.223.0,52.230.0,22.201.0,36.153.0,46.232.0"}
P.entries["npc:galgar"] = {n="Ґалґар",s="Ґалґар — орк-кухар у Долині Випробувань у Дуроторі. Він готує харчі для молодих новобранців, що роблять перші кроки на службі Орді. Щоб навчити новачків основ збиральництва в суворій пустелі, він доручає їм збирати дикі кактусові яблука для своєї фірмової страви.",h="Ґалґар — орк-кухар у Долині Випробувань у Дуроторі.",kw={"ґалґар","кухар","кактусове яблуко","долина випробувань","їжа","новобранці","дуротар"},ang={["profession:Cooking"]="Ґалґар утілює практичну, просту кухню Орди: він використовує мізерні природні ресурси Дуротару, щоб новобранці були нагодовані й готові до бою.",["race:Orc"]="Для молодих орків, що роблять перші кроки в Долині Випробувань, доручення Ґалґара — звичний обряд переходу перед зустріччю з лютішими загрозами нетрів."},sec={{t="Кухар у долині",b="Ґалґар, що розташувався біля кухонного вогнища Лігва в Долині Випробувань, годує молодих орків і тролів, які проходять перші обряди переходу. Дуротар — суха, безжальна червона пустка, де кожну крихту поживи треба вирвати в землі. Відправляючи воїнів-новачків збирати стиглі кактусові плоди, Ґалґар перевіряє їхню уважність і стійкість і водночас поповнює запаси своєї кухні."},{t="Сюрприз із Кактусових Яблук",b="Фірмовий рецепт Ґалґара відомий як Сюрприз із Кактусових Яблук. Хоч він відверто визнає, що пошук колючих пустельних плодів — навмисне просте завдання, аби м'яко ввести новобранців у життя шукачів пригод, кінцевий продукт лишається основним харчем для голодних учнів. Навіть найзагартованіший воїн Орди має з чогось починати, і під пильним оком Ґалґара цей шлях починається з пустельного збиральництва."}},faq={{q="Де знайти Ґалґара?",a="Ґалґар перебуває в Долині Випробувань — початковому каньйоні орків і тролів на південному заході Дуротару. Він стоїть біля центрального вогнища й кухні перед Лігвом.",al={"місце ґалґара","де ґалґар","координати ґалґара"}},{q="Що Ґалґар просить у шукачів пригод?",a="Він просить новачків зібрати стиглі кактусові яблука з диких кактусів, розкиданих по Долині Випробувань, щоб приготувати свій Сюрприз із Кактусових Яблук.",al={"завдання ґалґара","чого хоче ґалґар"}},{q="Чому Ґалґар посилає новобранців збирати плоди?",a="Ґалґар визнає, що доручення навмисно просте. Це легка перша справа для молодих бійців, щоб вони вивчили долину й навчилися покладатися на себе в суворій глушині Дуротару.",al={"чому кактусові яблука","випробування ґалґара"}},{q="Що таке Сюрприз із Кактусових Яблук?",a="Це фірмовий рецепт Ґалґара зі свіжих кактусових яблук, зібраних серед місцевої пустельної рослинності Дуротару, щоб нагодувати новобранців.",al={"що таке сюрприз із кактусових яблук","їжа ґалґара"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="Ґан'рул Бладай",s="Ґан'рул Бладай — досвідчений орк-наставник чорнокнижників, що мешкає глибоко в темній печері Тіньової Розколини в Оргріммарі. Подалі від пильних очей міста нагорі він посвячує чорнокнижників Орди в темніші демонічні обряди. Під його проводом новачки вчаться підкоряти своїй волі потойбічних істот, як-от блукачів Порожнечі та сукубів.",h="Ґан'рул Бладай — досвідчений орк-наставник чорнокнижників, що мешкає глибоко в темній печері Тіньової...",kw={"ґан'рул","бладай","чорнокнижник","тіньова розколина","оргріммар","демони","сукуб"},ang={["class:Warlock"]="Для чорнокнижників, що шукають забороненого знання, Ґан'рул — важливий наставник у Калімдорі: він дає знання й випробування, потрібні, щоб підкорити блукачів Порожнечі й сукубів.",["faction:Horde"]="Ґан'рул уособлює хитке становище магії скверни в Орді Тралла: її використовують заради військової сили, але тримають у підземних закапелках столиці."},sec={{t="Майстер у тінях",b="Вождь Тралл терпить чорнокнижників у Новій Орді, та їхнім темним мистецтвам не місце під відкритим сонцем Дуротару. Ґан'рул Бладай живе в Тіньовій Розколині — підземному прихистку під Оргріммаром, де ткачі тіней, розбійники й заклиначі скверни можуть навчатися без перешкод. Звідси, зі свого підземного гнізда, Ґан'рул навчає тих, хто лише починає опановувати магію скверни."},{t="Підкорення Нижнього Світу",b="Головний обов'язок Ґан'рула — наглядати за небезпечними обрядами прикликання, яких вимагають від честолюбних чорнокнижників. Ті, хто прагне підкорити могутніших демонів — як-от витривалого блукача Порожнечі чи звабливого сукуба, — мусять звернутися до Ґан'рула, щоб здобути складники для обряду й вивчити точні заклинання, потрібні, аби приборкати прикликану істоту, перш ніж вона пожере свого господаря."}},faq={{q="Хто такий Ґан'рул Бладай?",a="Ґан'рул Бладай — орк, наставник чорнокнижників в Оргріммарі. Він наставляє чорнокнижників Орди — новачків і досвідченіших — і навчає їх викликати й підкоряти демонів із Викривленого Нижнього Світу.",al={"ґан'рул бладай","хто такий ґан'рул","роль ґан'рула бладая"}},{q="Де знайти Ґан'рула Бладая?",a="Він перебуває в Тіньовій Розколині — мережі підземних печер, схованих під Оргріммаром. Він стоїть поряд з іншими знавцями темних мистецтв, подалі від головних вулиць міста.",al={"місце ґан'рула","де ґан'рул бладай","де тренер тіньової розколини"}},{q="Чому чорнокнижники ховаються в Тіньовій Розколині?",a="Після колишнього поневолення орків Вождь Тралл і шаманське суспільство нової Орди глибоко не довіряють магії скверни й демонічному зіпсуттю. Чорнокнижників в Орді терплять лише заради користі, а їхнє ремесло відсунуто в тінь, щоб не сіяти неспокою в місті.",al={"чому в печерах","чому чорнокнижники ховаються","лор тіньової розколини"}},{q="Яких демонів Ґан'рул допомагає викликати?",a="Ґан'рул веде чорнокнижників крізь ритуали, потрібні, щоб викликати й підкорити і блукача Порожнечі, і сукуба. Виконавши його доручення, закликач доводить, що має досить сили волі, щоб керувати цими потворами.",al={"яких демонів навчає ґан'рул","завдання ґан'рула з демонами","тренер духа порожнечі й суккуби"}},{q="Чи має Ґан'рул відомих родичів?",a="Він має спільне прізвище з Галґою Бладай, але яка між ними спорідненість, ніде прямо не сказано.",al={"родичі ґан'рула","родичка гальга бладай"}},{q="Хто такий Страгад, якого згадує Ґан'рул?",a="Страгад Фарсан — вправний чорнокнижник, що живе в Пустках на пагорбах біля Раджета. Згодом Ґан'рул посилає до Страгада перспективних учнів для глибшого навчання й складніших випробувань.",al={"пошук страгада","хто такий страгад","завдання страгада"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="Ґанн Стоунспайр",s="Ґанн Стоунспайр — скривджений таурен-кочівник, що блукає дорогами південних Пусток поблизу Бель Модана. Дворфи-копачі вигнали його плем'я з прадавніх мисливських угідь, і тепер він шукає відплати проти розкопок, що наступають на його землю.",h="Ґанн Стоунспайр — скривджений таурен-кочівник, що блукає дорогами південних Пусток поблизу Бель Модана.",kw={"ґанн стоунспайр","бель модан","дворфи","таурени","шукач хазґорм","пустки"},ang={["faction:Horde"]="Допомога Ґаннові дає Орді важливу тактичну нагоду приборкати експансію Альянсу, який закріпився на півдні Пусток.",["race:Tauren"]="Біда Ґанна — частина ширшої боротьби кочових тауренів, чиї прадавні пасовища й священну землю знову й знову оскверняють чужоземні експедиції Альянсу."},sec={{t="Вигнанець із Бель Модана",b="Перш ніж з Айронфорджа прибула дворфійська експедиція й заклала фортецю Бель Модан, довколишня земля була прадавньою територією та мисливськими угіддями племені Ґанна Стоунспайра. Дворфи-рудокопи прогнали корінних тауренів з їхньої землі кайлами, рушницями й важкими машинами, відкинувши всі мирні пропозиції. Тепер Ґанн отаборився при запорошеній дорозі на півдні Пусток і не збирається мовчки зректися своєї спадщини: він скликає мандрівників, щоб дати відсіч копачам."},{t="Відплата й диверсія",b="Зрозумівши, що мирна дипломатія зазнала цілковитої поразки, Ґанн посилає бійців Орди зламати владу дворфів над розкопками. Його відплата спрямована передусім на ключових ватажків експедиції, насамперед на Шукача Хазґорма, а потім — на те, щоб перетворити дворфійський вибуховий порох і боєприпаси на потужний заряд. Підірвавши цей пристрій просто під дворфійською літальною машиною, Ґанн прагне позбавити їх технічної переваги й повернути честь своєму вигнаному народові."}},faq={{q="Хто такий Ґанн Стоунспайр?",a="Ґанн Стоунспайр — таурен-воїн, чиє плем'я колись жило на землях, які тепер займає дворфська фортеця Бель Модан. Вигнаний, коли дворфи заклали свої розкопки, він тепер чекає при дорозі на півдні Пусток, прагнучи помсти й повернення батьківщини свого народу.",al={"хто такий ґанн","лор ґанна стоунспайра","таурен біля бель модану"}},{q="Чому Ґанн воює з дворфами Бель Модану?",a="Дворфська експедиція Бел'дуну прибула на південь Пусток і силою вигнала місцевих тауренів з їхніх родових мисливських угідь, щоб збудувати свою фортецю розкопок. Коли дворфи відкинули всі спроби домовитися, Ґанн вирішив зруйнувати їхню справу силою.",al={"чому ґанн ненавидить дворфів","чому нападати на бель модан","конфлікт ґанна з бель моданом"}},{q="Який план Ґанна проти розкопок?",a="Спершу Ґанн доручає вбити дворфських наглядачів, зокрема Шукача Хазґорма, щоб захопити записи розкопок. А тоді з украденої дворфської вибухівки й підривних матеріалів організовує складання бомби, щоб знищити літальну машину експедиції й підірвати її технічну перевагу.",al={"план помсти ґанна","що робить ґанн","бомба для бель модану"}},{q="Де стоїть табором Ґанн Стоунспайр?",a="Його можна знайти на дорозі трохи на захід від Бель Модану на півдні Пусток, одразу за межами розкопок.",al={"де ґанн","місце ґанна стоунспайра"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {n="Ґар'Ток",s="Ґар'Ток — ветеран-орк, воїн і командир застави в Гострому Пагорбі в Дуроторі. Він бився на Горі Гіджал і пережив перші висадки Кул Тірасу на узбережжі Дуротару, а нині керує місцевою обороною від людських зайд і тутешніх загроз. Він спрямовує молодих новобранців Орди, що виходять із Долини Випробувань, убезпечувати червоні пустки нової батьківщини.",h="Ґар'Ток — ветеран-орк, воїн і командир застави в Гострому Пагорбі в Дуроторі.",kw={"ґар'ток","гострий пагорб","ветеран","кул тірас","гора гіджал","командир","дуротар"},ang={["class:Warrior"]="Як командир передової, що пережив і демонічні легіони, і жорстокі морські засідки, Ґар'Ток чекає від побратимів-воїнів бойової стійкості й беззастережного послуху.",["faction:Horde"]="Ґар'Ток дбає, щоб нові новобранці всіх народів Орди розуміли хиткість своєї нової землі, і спрямовує їх відбивати рештки загарбників з Альянсу.",["race:Orc"]="Для молодих орків, що покидають Долину Випробувань, Ґар'Ток утілює сувору, непохитну дисципліну покоління ветеранів, яке стікало кров'ю на Горі Гіджал, щоб здобути Дуротар."},sec={{t="Ветеран червоних пусток",b="Перш ніж осісти в Гострому Пагорбі, Ґар'Ток боронив орчий табір під час апокаліптичної Битви за Гору Гіджал. Після Третьої війни він рушив у Дуротар під проводом Вождя Тралла і служив лейтенантом під командою Назґрела в найперші дні будівництва нової батьківщини. Коли мандрівник-мок'натал Рекссар уперше прибув у Дуротар, саме Ґар'Ток попередив його про агресивних шипогривів, що нападали на їхній периметр, і залучив володаря звірів до захисту крихкого нового поселення."},{t="Пережити вторгнення адмірала",b="Рішучість Ґар'Тока випробувало те, що флот Кул Тірасу Великого адмірала Дейліна Праудмура висадився на східних берегах Дуротару. Стоячи на віддаленому сторожовому посту, Ґар'Ток бачив, як його гарнізон здолали й жорстоко вирізали морські піхотинці. Хоч його сили було знищено, Ґар'Ток пережив той наступ. Пам'ять про раптовий напад закріпила його пильність щодо вцілілих піхотинців, які й досі тримають Фортецю Тіраґард і прибережні кораблетрощі."},{t="Оборона Гострого Пагорба",b="Нині Ґар'Ток керує військовою обороною центрального Дуротару з казарм Гострого Пагорба. Він не марнує часу на люб'язності й одразу доручає молодим воїнам, шаманам і розвідникам Орди вичищати ворожі рештки Кул Тірасу, забирати врятовані припаси й повертати військові накази, покинуті в прибережних руїнах. Для нього безпека Дуротару далеко не гарантована і потребує постійного тиску на всіх, хто ставить під сумнів право Орди на цю землю."}},faq={{q="Хто такий Ґар'Ток?",a="Ґар'Ток — орк-офіцер із Гострого Пагорба, що організовує місцеву військову відсіч ворожим силам у Дуротарі. Він ветеран Третьої війни, що служив під началом Назґрела, коли засновували Оргріммар.",al={"лор ґар'тока","хто такий ґар'ток","командир гострого пагорба"}},{q="Де бився Ґар'Ток, перш ніж прийти до Гострого Пагорба?",a="Він бився в Битві на Горі Гіджал, обороняючи орківські укріплення від Палаючого Легіону й Погибелі. Згодом служив на прикордонній заставі в Дуротарі, де разом із Рекссаром приборкував перші набіги шипогривів.",al={"минуле ґар'тока","ґар'ток гора хіджал","історія ґар'тока"}},{q="Чому Ґар'Ток так ненавидить людей у Дуротарі?",a="Під час вторгнення, яке очолив Великий Адмірал Даелін Праудмур, моряки з Кул Тірасу підстерегли заставу Ґар'Тока на узбережжі й вирізали його вояків. Він пережив напад і нині відданий тому, щоб викорінити табори морської піхоти, що ще лишилися.",al={"чому ґар'ток ненавидить кул-тірас","ґар'ток і люди","цитадель тірагард ґар'ток"}},{q="З якими загрозами Ґар'Ток посилає битися шукачів пригод?",a="Ґар'Ток посилає новобранців битися з ворожими моряками Кул Тірасу, що окопалися у Фортеці Тіраґард, повертати припаси з прибережних уламків кораблів, відкидати шипогривів-загарбників і шукати накази, які лишили людські командири.",al={"завдання ґар'тока","чого хоче ґар'ток","завдання гострого пагорба"}},{q="Що пов'язує його з Назґрелом і Траллом?",a="Ґар'Ток був довіреним поручником Назґрела під час перших поселенських походів у Дуротар і діяв безпосередньо з волі Вождя Тралла, щоб убезпечити кордони щойно здобутих земель.",al={"ґар'ток і назґрел","ґар'ток і тралл","звання ґар'тока"}},{q="Де знайти Ґар'Тока?",a="Ґар'Ток стоїть біля головної дозорної вежі й казарм у Гострому Пагорбі — центральному поселенні Дуротару на південь від Оргріммара.",al={"місце ґар'тока","де ґар'ток","знайти ґар'тока"}}},fp="8,378,27.491.0,32.468.0,21.473.0,16.219.0,53.217.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="Ґарт Містраннер",s="Ґарт Містраннер — наставник друїдів, що працює в Таборі Нарачі на Плато Червоної Хмари. Він вітає новачків-тауренів, яких покликала Мати-Земля, і веде їх крізь перші обряди магії природи.",h="Ґарт Містраннер — наставник друїдів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"ґарт містраннер","друїд","наставник","табір нарачі","плато червоної хмари","му'ша"},ang={["class:Druid"]="Для друїдів-тауренів Ґарт Містраннер — найперший учитель, що формує їхнє єднання з дикою природою й дарами Матері-Землі.",["race:Tauren"]="Ґарт уособлює відродження стародавніх друїдичних традицій шу'гало й передає мудрість предків молоді Табору Нарачі."},sec={{t="Наставник Плато Червоної Хмари",b="Табір Нарачі — місце, де чатує Ґарт Містраннер, уособлення стародавнього друїдичного шляху, відродженого серед шу'гало. Нових друїдів-тауренів направляють просто до Ґарта, щойно вони роблять перші кроки на Плато Червоної Хмари, і часто вони несуть зелену записку, що доручає їх його опіці. Під його терплячим проводом молоді адепти вчаться єднатися зі світом природи й черпати відновлювальні сили природи та місячне сяйво Му'ші, щоб зцілювати союзників і нищити загрози землі."}},faq={{q="Хто такий Ґарт Містраннер?",a="Ґарт Містраннер — таурен, наставник друїдів у Таборі Нарачі на Плато Червоної Хмари в Малгорі. Він навчає тауренів — друїдів-початківців перших заклять і обрядів.",al={"хто такий ґарт","лор ґарта містраннера","ґарт містраннер"}},{q="Яких заклять він навчає щойно пробуджених друїдів?",a="Ґарт знайомить новачків з основними вміннями природи: навчає перших цілющих заклять, як-от Цілющий Дотик, і бойової магії природи на кшталт Місячного Вогню.",al={"чого навчає ґарт","навчання ґарта містраннера","закляття друїдів табір нараче"}},{q="Що пов'язує його з кланом Містраннер?",a="Містраннер — просто родове ім'я Ґарта. Жодні перекази не згадують племені Містраннер і нічого більше не кажуть про його родичів: він відомий лише як наставник друїдів Табору Нарачі.",al={"клан містраннер","хто такі містраннери"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="Ґат'Ілзоґґ",s="Ґат'Ілзоґґ — грізний воєвода орків Блекрок, що очолює загарбницьке військо, яке захопило Фортецю Кам'яної Варти в Горах Редріджу. Під його жорстоким проводом орки взяли фортецю й почали спустошливі набіги на Лейкшир, тож доведений до відчаю магістрат містечка терміново оголосив нагороду за його голову.",h="Ґат'Ілзоґґ — грізний воєвода орків Блекрок, що очолює загарбницьке військо, яке захопило Фортецю Кам'яної...",kw={"ґат'ілзоґґ","блекрок","фортеця кам'яної варти","морґант","опік","магістрат соломон","редрідж"},ang={["faction:Alliance"]="Убивши Ґат'Ілзоґґа, ви ламаєте хребет наступу Блекрок, що загрожує Лейкширу, і відповідаєте на відчайдушний заклик Магістрата Соломона.",["race:Orc"]="Ґат'Ілзоґґ уособлює старі войовничі звичаї клану Блекрок за часів Темної Орди — зовсім не те, чим живе нова Орда Тралла в Калімдорі."},sec={{t="Гроза Кам'яної Варти",b="Ґат'Ілзоґґ рушив на північ із Палаючих Степів із наказом підкорити Редрідж для клану Блекрок. Спираючись на лихе чаклунство людини-чорнокнижника, ренегата Морґанта, загін Ґат'Ілзоґґа розбив захисників Фортеці Кам'яної Варти й захопив висоту, з якої видно весь край. Із цього укріпленого редуту він спрямовує запеклі набіги в долини й аж до мосту Лейкширу, поволі душачи людське поселення. Сам він б'ється рідко: поруч завжди добірна варта Блекрок і лютий чорний дракончик на ім'я Опік."},{t="Хитка влада",b="Хоч Ґат'Ілзоґґ і захопив Кам'яну Варту, перемога принесла йому нові клопоти. Морґант швидко обернувся проти колишніх союзників-орків і зібрав військо гнолів Тіньової Шкури під проводом Лейтенанта Фанґора, яке полює і на патрулі Блекрок, і на людей-подорожніх. Тим часом Магістрат Соломон відкрито оголосив нагороду за голову воєводи, благаючи найманців і шукачів пригод Альянсу здертися на мури Фортеці Кам'яної Варти й покласти край терору Ґат'Ілзоґґа, доки містечко не впало остаточно."}},faq={{q="Хто такий Ґат'Ілзоґґ?",a="Ґат'Ілзоґґ — орк-воєначальник із клану Блекрок. Він очолює передовий загін, що вдерся до Редріджу й відбив у Альянсу Фортецю Кам'яної Варти.",al={"лор ґат'ілзоґґа","хто такий ґат'ілзоґґ","бос чорної скелі в редріджі"}},{q="Де знайти Ґат'Ілзоґґа?",a="Він засів на самій вершині Фортеці Кам'яної Варти серед східних скель Гір Редріджу.",al={"місце ґат'ілзоґґа","де ґат'ілзоґґ","знайти ґат'ілзоґґа"}},{q="Звідки в Ґат'Ілзоґґа дракончик?",a="Ґат'Ілзоґґа супроводжує чорний дракончик на ім'я Опік — як вважають, дарунок Лорда Віктора Нефаріуса воєначальникові за успішне захоплення Фортеці Кам'яної Варти.",al={"чому дракончик біля ґат'ілзоґґа","сінж дракон","чорний дракончик ґат'ілзоґґа"}},{q="Чому за його голову призначено нагороду?",a="Магістрат Соломон із Лейкширу призначив велику нагороду за голову Ґат'Ілзоґґа, бо безупинні набіги воєначальника й захоплення Кам'яної Варти безпосередньо загрожують Лейкширу цілковитою загибеллю.",al={"розшукується ґат'ілзоґґ","хто хоче смерті ґат'ілзоґґа","нагорода від магістрата соломона"}},{q="Що сталося між Ґат'Ілзоґґом і Морґантом?",a="Спершу чорнокнижник-людина Морґант допоміг Ґат'Ілзоґґу темною магією захопити Кам'яну Варту. Але щойно фортеця впала, Морґант зрадив орків і зібрав військо з гнолів Тіньової Шкури, щоб нападати і на людей, і на клан Блекрок.",al={"союз морґанта й ґат'ілзоґґа","чому гноли нападають на орків","зрада морґанта"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="Ґаксим Растфіззл",s="Ґаксим Растфіззл — честолюбний гном-учений і майстер, що несе службу в невеликому таборі Альянсу на Стежці Павутинника в Горах Кам'яного Кігтя. Представник Просвітленої Асамблеї Таємнознавства, Алхімії й Інженерії, він прагне довести скептичним нічним ельфам, що досконала механіка й алхімія можуть зберегти їхні лісові володіння. Його наукова допитливість не поступається запеклій ворожнечі з руйнівними роботами Венчурної Компанії.",h="Ґаксим Растфіззл — честолюбний гном-учений і майстер, що несе службу в невеликому таборі Альянсу на Стежці...",kw={"ґаксим растфіззл","гном","інженерія","венчурна компанія","стежка павутинника","гори кам'яного кігтя"},ang={["faction:Alliance"]="Ґаксим, що засів на небезпечній Стежці Павутинника, дає важливі доручення з розвідки й диверсій, щоб стримувати агресивну промислову навалу в Горах Кам'яного Кігтя.",["profession:Engineering"]="Ґаксим застосовує інженерні принципи в польових умовах, розробляючи таємні операції й тактичні пристрої, спеціально налаштовані, щоб ламати грубі машини Венчурної Компанії.",["race:Gnome"]="Ґаксим утілює найкращу гномську академічну гордість, показуючи давнім культурам Калімдору, що шестерні й реактиви можуть урятувати ліс не гірше за магію природи.",["race:NightElf"]="Хоч прихильники традицій і кепкують з його дзижчливих пристроїв і булькотливих колб, Ґаксим — вірний союзник, що боронить кордони Ашенвалю й Гір Кам'яного Кігтя від гоблінської промисловості."},sec={{t="Посланець науки",b="Нічні ельфи здавна покладаються на давнє друїдство й магію природи, а Ґаксим Растфіззл прибув на скелясті перевали Гір Кам'яного Кігтя, щоб показати зовсім інший погляд. Представляючи Просвітлену Асамблею Таємнознавства, Алхімії й Інженерії, він щиро вірить, що розраховані механізми й хімічні рішення можуть захищати й відновлювати дику природу Калімдору не гірше за молитви до Елуни. Отаборившись поруч із вартовою Каелою Шедовспір на Стежці Павутинника, він невтомно переконує своїх високих, відлюдних союзників у користі інженерії для природи."},{t="Диверсії проти пилок",b="Більшість сил Ґаксим спрямовує проти Венчурної Компанії, чиї суцільні вирубки й промислова жадібність оскверняють сусідню Кручу Вітрорізу. Переконаний, що грубі гоблінські машини не заслуговують ні поваги, ні жалю, Ґаксим організовує таємні операції й вибухові хімічні диверсії проти їхніх лісорубень. Для нього вивести з ладу їхні подрібнювачі й викрасти креслення — не просто тактика: це наочний доказ того, що вищий гномський розум завжди бере гору над недбалим корпоративним грабунком."}},faq={{q="Хто такий Ґаксим Растфіззл?",a="Ґаксим Растфіззл — гном-учений і винахідник, що стоїть на дозорному пункті Альянсу на Стежці Павутинника в Горах Кам'яного Кігтя. Він посланець Просвітленої Асамблеї Арканології, Алхімії та Інженерії.",al={"хто такий ґаксим","лор ґаксима растфіззла","гном у стоунталоні"}},{q="Що таке Просвітлена Асамблея Арканології, Алхімії та Інженерії?",a="Це наукове товариство гномів, що прагне поєднати тайну магію, алхімічні суміші й механічну інженерію. Ґаксим втілює його ідеали за кордоном, у Калімдорі.",al={"просвітлена асамблея","фракція ґаксима","група ґаксима"}},{q="Чому Ґаксим працює з нічними ельфами?",a="Ґаксим хоче показати нічним ельфам, що гномська наука й алхімія можуть діяльно захищати й зцілювати природні ліси, пропонуючи сучасну відповідь Альянсу на охорону лісів поряд із традиційним друїдством.",al={"чому ґаксим тут","ґаксим і нічні ельфи","мета ґаксима"}},{q="Чому Ґаксим ненавидить Венчурну Компанію?",a="Венчурна Компанія безжально вирубує Кручу Вітрорізу грубими машинами й отруйними викидами. Ґаксим зневажає їхнє безрозсудне хижацтво й із насолодою обертає проти їхніх робіт нестійкі хімікати й диверсії.",al={"ґаксим і венчурна компанія","ґаксим проти венчурної компанії","чому воювати з венчурною компанією"}},{q="Хто отаборився разом із Ґаксимом на Стежці Павутинника?",a="Він ділить свою невелику заставу з Каелою Шедовспір — вартовою з нічних ельфів, що пильнує стежки до Кручі Вітрорізу.",al={"супутник ґаксима","хто з ґаксимом","ґаксим і кейла"}},{q="Де знайти Ґаксима Растфіззла?",a="Він перебуває в скромному таборі Альянсу на Стежці Павутинника, трохи на південний захід від промислових лісорубних ям Кручі Вітрорізу в Горах Кам'яного Кігтя.",al={"місце ґаксима","де ґаксим","карта ґаксима растфіззла"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazrog"] = {n="Ґазроґ",s="Ґазроґ — орк-воїн, що несе службу на Перехресті в серці Пусток. Йому доручено дбати про постачання й безпеку на небезпечних дорогах савани, тож він наймає вправних мандрівників з Орди, щоб упоратися з місцевими загрозами й розшукати зниклі патрулі.",h="Ґазроґ — орк-воїн, що несе службу на Перехресті в серці Пусток.",kw={"ґазроґ","перехрестя","орк","шипогриви","піхотинець доґран","пустки"},ang={["faction:Horde"]="Ґазроґ — один із перших, до кого звертаються шукачі пригод з Орди, вирушивши з Дуротара чи Малгору: він дає важливу роботу, що допомагає прокласти безпечні шляхи через Калімдор.",["race:Orc"]="Як ветеран-орк, що втримує Перехрестя, Ґазроґ утілює ту вперту, тверезу хватку, без якої не приборкати безжальне прикордоння Калімдору."},sec={{t="Вартовий Перехрестя",b="Перехрестя — життєво важливий вузол для всіх шляхів Орди через Калімдор, але його відокремленість робить шляхи постачання вразливими і для грабіжників, і для звірів. Ґазроґ стоїть на варті разом із захисниками поселення, дбаючи, щоб вантажі, гроші й гінці діставалися місця призначення. Підтримувати лад у безкраїх нетрях можна лише за постійної пильності, тож Ґазроґ дуже покладається на мандрівних шукачів пригод, які розв'язують кризи, що назрівають за частоколом застави."},{t="Небезпеки савани",b="Між хижими рапторами, що полюють на стежках, і агресивними кланами шипогривів, які влаштовують засідки на розвідників, Ґазроґові ніколи не бракує роботи. Він часто організовує відповідь на розбій на шляхах — скажімо, повернення викрадених вантажів Орди — і стежить за долею зниклих вояків, як-от піхотинця Доґрана, що пораненим потрапив у полон до шипогривів."}},faq={{q="Де знайти Ґазроґа?",a="Ґазроґ перебуває на Перехресті — центральному поселенні, що сполучає північний, південний і східний шляхи Пусток.",al={"місце ґазроґа","де ґазроґ","ґазроґ перехрестя"}},{q="Яку роль Ґазроґ відіграє для Орди?",a="Він координатор і вартовий на Перехресті: роздає доручення, щоб берегти шляхи постачання краю, повертати перехоплені вантажі й шукати зниклих людей Орди.",al={"робота ґазроґа","хто такий ґазроґ","що робить ґазроґ"}},{q="Що сталося з украденим сріблом, про яке питає Ґазроґ?",a="На валки Орди з монетами часто полюють кмітливі раптори савани й пройдисвіти, що никають стежками Пусток, тож Ґазроґ посилає звитяжців вполювати звірів і повернути вантаж.",al={"завдання про украдене срібло","хто вкрав срібло","украдена партія в пустках"}},{q="Хто такий Доґран?",a="Доґран — піхотинець Орди, якого відрядили на Перехрестя працювати з Ґазроґом. Він так і не повернувся зі служби: Ґазроґ чув, що він живий, але поранений і в полоні в шипогривів, і воліє не казати цього подрузі Доґрана, Занкаджі.",al={"новини про доґрана","де доґран","ґазроґ доґран"}},{q="Чи пов'язаний Ґазроґ із Раджетом чи гоблінами?",a="Ні. Ґазроґ служить безпосередньо Орді на Перехресті, оберігаючи інтереси орків, тауренів і тролів по всіх центральних Пустках.",al={"чи ґазроґ з раджета","фракція ґазроґа","ґазроґ гоблін"}},{q="Чому раптори в Пустках крадуть припаси?",a="Ніхто напевно не знає. Раптори сховали вкрадене срібло у своїх гніздах на Угіддях Рапторів на південь від Раджета, і Ґазроґ замислюється, чи не ближчі до правди історії про їхній розум, ніж він думав.",al={"чому раптори-злодії","чи раптори крадуть речі","раптори блискуче"}}},fp="6,258,28.475.0,16.330.0,26.129.0,41.187.0,53.196.0,14.237.0,49.145.0,49.211.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Ґелбін Меккаторк",s="Ґелбін Меккаторк — Великий Тінкер гномів, що нині живе у вигнанні в Містечку Майстрів в Айронфорджі. Цей далекоглядний інженер, автор механоступа й Глибинного трамвая, несе тепер тяжкий тягар падіння Гномреґана й очолює зусилля, щоб повернути прадавню домівку свого народу.",h="Ґелбін Меккаторк — Великий Тінкер гномів, що нині живе у вигнанні в Містечку Майстрів в Айронфорджі.",kw={"меккаторк","ґелбін","великий тінкер","гноми","гномреґан","інженерія","містечко майстрів"},ang={["profession:Engineering"]="Стояти перед Великим Тінкером — означає стояти перед автором механоступа, гіроматичного мікрорегулятора й Глибинного трамвая. Його майстерня в Містечку Майстрів — передній край технічного поступу.",["race:Gnome"]="Меккаторк — серце вашого народу у вигнанні. Хоч провина за отруєння Гномреґана тяжіє над ним, його геній і відданість визволенню вашої прадавньої домівки здобули йому беззастережну вірність у Містечку Майстрів."},sec={{t="Великий Тінкер і геніальний винахідник",b="Провід у гномів здобувають розумом і заслугами, а не родоводом, і Ґелбін Меккаторк став Великим Тінкером завдяки чистому винахідницькому генію. Випускник Університету Ґіршафт, він здійснив переворот у пересуванні, створивши перший робочий механоступ. За десятиліття винаходів Меккаторк сконструював гіроматичний мікрорегулятор і автоматичних роботів-ремонтників, а разом із дворфами Бронзбірдами розробив їхні грізні облогові машини. Коли після Другої війни Стормвінду знадобилося швидке сполучення з Айронфорджем, Король Маґні Бронзбірд звернувся до Меккаторка, і той власноруч розробив креслення й наглядав за будівництвом підземного Глибинного трамвая."},{t="Зрада й вигнання в Айронфорджі",b="Найбільша трагедія Меккаторка сталася, коли з глибин до Гномреґана вдерлися троги. За порадою свого вірного друга й головного радника Сікко Термаплаґґа Меккаторк наказав випустити радіоактивні відходи в нижні коридори, щоб знищити нападників. Натомість отруйний газ убив тисячі безневинних гномів і спотворив тих, хто вижив, а Термаплаґґ захопив зруйноване місто. Розчавлений провиною, але сповнений рішучості виправити свою помилку, Меккаторк повів уцілілих біженців через Дун Мороґ до Айронфорджа. Діючи з Містечка Майстрів завдяки гостинності Короля Маґні, Великий Тінкер спрямовує всю військову й наукову снагу гномів до однієї незмінної мети — визволення Гномреґана."}},faq={{q="Хто такий Ґелбін Меккаторк?",a="Ґелбін Меккаторк — обраний Великий Тінкер і провідник гномів. Він майстер-інженер, що створив ключові гномські винаходи, зокрема механоступа, ремонтних ботів і Глибинний трамвай.",al={"великий тінкер","лідер гномів","хто король гномів"}},{q="Чому Меккаторк в Айронфорджі, а не в Гномреґані?",a="Гномреґан заполонила люта навала трогів, а тоді його спіткало нищівне радіоактивне зараження. Меккаторк вивів свій народ через Дун Мороґ до Айронфорджа, де Король Маґні Бронзбірд дав їм притулок у Містечку Майстрів, поки вони готують плани повернути місто.",al={"чому меккаторк в айронфорджі","чому гноми в айронфорджі","падіння гномреґана"}},{q="Що спричинило катастрофу в Гномреґані?",a="Під натиском нескінченних хвиль трогів Меккаторк дав довіреному радникові переконати себе випустити отруйний радіоактивний охолоджувач у нижні зали, щоб зупинити звірів. На жаль, газ не зупинив трогів, а натомість опромінив місто й убив тисячі гномів.",al={"що сталося з гномреґаном","чому гномреґан радіоактивний","зрада термаплаґа"}},{q="Що Меккаторк винайшов, перш ніж стати Великим Тінкером?",a="Меккаторк винайшов механоступа, давши гномам власного спритного скакуна. Він також сконструював гіроматичний мікрорегулятор і ремонтних ботів, розробив креслення Глибинного трамваю між Айронфорджем і Стормвіндом і разом з іншими створив дворфську облогову машину.",al={"винаходи меккаторка","що збудував ґелбін"}},{q="Чи Меккаторк — справжній король?",a="У гномів немає спадкової монархії: їхній провідник — обраний Великий Тінкер, якого обирають за заслуги й розумові здобутки. Його звання й влада походять від того, що його обрали Великим Тінкером.",al={"чи меккаторк король","король гномів"}}},fp="18,326,35.716.0,31.706.1,26.203.0,54.282.0,42.264.0,56.249.0,30.191.0"}
P.entries["npc:gelihast"] = {n="Ґелігаст",s="Ґелігаст — лютий мурлок-ватажок із двома клинками, що живе в Ставку Аск'ар у Чорноглибинних Печерах. Приваблений темним шепотом Древніх Богів, він прорубав собі шлях до затонулих руїн храму, а згодом здобув неохочу повагу культистів Молота Присмерку.",h="Ґелігаст — лютий мурлок-ватажок із двома клинками, що живе в Ставку Аск'ар у Чорноглибинних Печерах.",kw={"ґелігаст","мурлок","ставок аск'ар","молот присмерку","чорноглибинні печери","сліпосвіти"},ang={["class:Warrior"]="Ґелігаст атакує зі сліпучою швидкістю меча; досвідчені воїни, що вміють устояти, можуть цілком обернути його шалений натиск двома клинками проти нього самого.",["faction:Alliance"]="Для сил Альянсу, що прагнуть очистити скверну, яка просочується в Ашенваль, усунення Ґелігаста — запорука безпеки північних проходів затонулого храму.",["faction:Horde"]="Шукачі пригод з Орди, яких посилають прочесати Чорноглибинні Печери, мають знищити Ґелігаста, щоб зруйнувати союз культистів, який визріває під Зорамським Узмор'ям."},sec={{t="Смертоносний поклик",b="Більшість мурлоків тримається прибережних мілин, але Ґелігаст відчув темний, зловісний поклик Древніх Богів глибоко під Ашенвалем. Гнаний цим первісним шепотом, він силоміць пробився до затонулого храму Чорноглибинних Печер. Коли культисти Молота Присмерку спробували заступити йому дорогу, він власноруч порубав своїми двома мечами майже дюжину з них."},{t="Володар Сліпого Світла",b="Замість мститися, культисти захопилися дикою лютістю Ґелігаста й віддали йому владу над Ставком Аск'ар. Там, оточений своїм виводком Сліпого Світла, кровожерливий мурлок звів грубий вівтар. На ньому він приносить моторошні жертви й отримує темні дари просто від мерзенної сили, що дрімає в безодні."}},faq={{q="Хто такий Ґелігаст?",a="Ґелігаст — лютий ватажок мурлоків, що командує племенем Сліпого Світла в Ставку Аск'ар у Чорноглибинних Печерах. Він б'ється двома клинками й служить темній присутності, що засіла в руїнах.",al={"хто такий ґелігаст","лор ґелігаста","минуле ґелігаста"}},{q="Що Ґелігаст робить у Чорноглибинних Печерах?",a="Його привабив шепіт Древніх Богів. Прагнучи дістатися джерела темного поклику, він вдерся до руїн і прорубав собі кривавий шлях крізь місцевих культистів, щоб захопити власні володіння.",al={"чому мурлок у чорноглибинних печерах","чому ґелігаст у храмі"}},{q="Як Молот Присмерку поставився до нього?",a="Хоча, ввійшовши до храму, Ґелігаст вирізав мало не дюжину культистів Молота Присмерку, уцілілих так вразили його лютість і жорстокість, що вони дозволили йому лишитися й поклонятися поряд із ними.",al={"ґелігаст і молот присмерку","чи культисти люблять ґелігаста"}},{q="Що за вівтар за Ґелігастом?",a="Ґелігаст спорудив цю святиню, щоб приносити криваві жертви лиховісній присутності в руїнах. Мандрівники, що здолають його, можуть торкнутися вівтаря й отримати Благословення Блекфатому.",al={"вівтар глибин","вівтар ґелігаста","благословення чорноглибини вівтар"}},{q="Яке плем'я мурлоків він очолює?",a="Він очолює мурлоків Сліпого Світла — агресивне плем'я, що заполонило Ставок Аск'ар у печерах.",al={"плем'я ґелігаста","які мурлоки в чорноглибинних печерах"}},{q="Що буде, якщо Ґелігаста не зупинити?",a="Він і далі приноситиме жертви на своєму вівтарі в Ставку Аск'ар, лишаючись лютим поплічником і фанатичним слугою темних жахіть, що заполонили руїни.",al={"доля ґелігаста","хто вбиває ґелігаста"}}},fp="8,284,16.355.0,24.334.0,16.204.0,41.193.0,43.217.0,34.177.0,35.104.0,49.163.0"}
P.entries["npc:gelkak-gyromast"] = {n="Ґелкак Джайромаст",s="Ґелкак Джайромаст — гном, що розмовляє, як піратський капітан, і застряг на туманному березі Краю Імли на півночі Темного Узбережжя. Його корабель біля берега потопили трешадони, і тепер він хоче полагодити свого механічного першого помічника — Трешвакінатор 4100.",h="Ґелкак Джайромаст — гном, що розмовляє, як піратський капітан, і застряг на туманному березі Краю Імли на...",kw={"ґелкак джайромаст","трешвакінатор 4100","край імли","руїни матістри","трешадони","гном-пірат"},ang={["profession:Engineering"]="Халепа Ґелкака — класична історія гнома далеко від дому, який покладає надії на помсту на такий вражаючий пристрій, як Трешвакінатор 4100.",["race:Gnome"]="Побратим-гном, що застряг на краю Калімдору, — суворе нагадування, як далеко від дому можуть занести гнома його пригоди."},sec={{t="Викинутий морем на Край Імли",b="Ґелкак Джайромаст, що отаборився на безлюдному північному березі Темного Узбережжя трохи на захід від давніх Руїн Матістри, — незвичне видовище серед похмурих берегів нічних ельфів. Самопроголошений капітан, що розмовляє, як старий морський вовк, утратив корабель через трешадонів просто біля берега. Коли його викинуло на імлистий пісок, ключ від його механічного першого помічника, Трешвакінатора 4100, розбився об каміння, а уламки розтягли повзуни, лісові довгоступи й мурлоки, що нишпорили серед решток корабля."},{t="Збій Трешвакінатора",b="Щойно шукачі пригод повертають ключ, Джайромаст посилає їх увімкнути першого помічника й привести його до капітана — йому кортить нацькувати механізм на мурлоків і звірів узбережжя. Трешвакінатор 4100 слухняно йде слідом, але, щойно дістається свого капітана, дає збій і стає ворожим, тож шукачам пригод доводиться його знищити."}},faq={{q="Хто такий Ґелкак Джайромаст?",a="Ґелкак Джайромаст — дивакуватий гном, що говорить, як піратський капітан. Він застряг на північному пляжі Темного Узбережжя, відомому як Край Імли, трохи на захід від Руїн Матістри.",al={"ґелкак","хто такий ґелкак","джайромаст"}},{q="Чому Ґелкак застряг на Темному Узбережжі?",a="Його корабель потопили трешадони просто біля берега, і його викинуло на пустельне північне узбережжя зі зламаним ключем від механічного першого помічника.",al={"чому ґелкак тут","ґелкак темне узбережжя"}},{q="Що таке Трешвакінатор 4100?",a="Трешвакінатор 4100 — механічне творіння Ґелкака і, за його ж словами, перший помічник. Він хоче знову запустити його, щоб той помстився мурлокам і звірам узбережжя.",al={"трешвакінатор","машина ґелкака","робот"}},{q="Якої допомоги Ґелкак потребує від мандрівників?",a="Ґелкак просить вправних шукачів пригод повернути три частини його зламаного ключа в повзунів, лісових довгоступів і мурлоків узбережжя, а тоді запустити ним Трешвакінатора 4100 і привести його назад.",al={"завдання ґелкака","завдання джайромаста"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:gerard-tiller"] = {n="Джерард Тіллер",s="Джерард Тіллер — спраглий людський наймит, що працює біля клуні на Виноградниках Маклюрів у Лісі Елвінн. Доглядаючи виноградники під теплим сонцем, він завжди радий обміняти хрустке блискуче червоне яблуко на бурдюк свіжої джерельної води від будь-якого подорожнього.",h="Джерард Тіллер — спраглий людський наймит, що працює біля клуні на Виноградниках Маклюрів у Лісі Елвінн.",kw={"джерард тіллер","яблука","джерельна вода","виноградники маклюрів","наймит","ґолдшир"},ang={["profession:Cooking"]="Готовність Джерарда міняти свіжі яблука на просту джерельну воду робить його зручним джерелом фруктів для мандрівних кухарів, що шукають простих інгредієнтів."},sec={{t="Спраглий наймит",b="Джерард Тіллер проводить дні, працюючи в полі й порядкуючи біля клуні на Виноградниках Маклюрів. Виноградник одразу на південь від Ґолдширу родить один із найвідоміших сортів винограду Елвінну, та підтримувати врожай — тяжка праця. Тіллера від роботи постійно мучить спрага, тож він охоче торгується з перехожими шукачами пригод. Якщо хтось запропонує йому свіжий бурдюк прохолодної джерельної води, він радо віддячить свіжими блискучими червоними яблуками просто з тутешніх садів."}},faq={{q="Хто такий Джерард Тіллер?",a="Джерард Тіллер — наймит-людина, що стоїть біля стодоли на Виноградниках Маклюрів на півдні Лісу Елвінн.",al={"хто такий джерард тіллер","хто такий джерард","тіллер елвінн"}},{q="Де знайти Джерарда Тіллера?",a="Він стоїть просто біля великої дерев'яної стодоли на Виноградниках Маклюрів, на південь від Ґолдширу й на схід від Ферми Стоунфілдів.",al={"місце джерарда тіллера","де джерард","знайти джерарда в елвінні"}},{q="Чим торгує Джерард Тіллер?",a="Джерард віддає Блискуче Червоне Яблуко кожному мандрівникові, що принесе йому бурдюк Освіжаючої Джерельної Води, щоб угамувати спрагу.",al={"джерард торгує яблуками","вода джерарда тіллера","чого хоче джерард"}},{q="Чи втручається Джерард у ворожнечу Маклурів і Стоунфілдів?",a="Ні. Хоч він і працює на Виноградниках Маклюрів, Джерард зосереджений на своїй роботі й на тому, щоб не страждати від спраги, а не на родинному суперництві Маклурів і Стоунфілдів.",al={"ворожнеча джерарда тіллера","ворожнеча маклурів і джерард"}}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gerrig-bonegrip"] = {n="Ґерріґ Боунґріп",s="Ґерріґ Боунґріп — непримітний дворф-крамар, що ховається в похмурих коридорах Покинутої Печери Айронфорджа. За прилавком крамниці «Руни й Пророцтва Боунґріпа» він тихо купує й продає таємні тексти про темні обряди й забуті прадавні сили.",h="Ґерріґ Боунґріп — непримітний дворф-крамар, що ховається в похмурих коридорах Покинутої Печери Айронфорджа.",kw={"ґерріґ боунґріп","молот присмерку","покинута печера","айронфордж","рукопис лорґаліса","древні боги"},ang={["class:Warlock"]="Для чорнокнижників, що навідуються в темні закутки Покинутої Печери, зібрання таємних обрядів і темних фоліантів Боунґріпа — зручне джерело небезпечних знань."},sec={{t="Руни й Пророцтва Боунґріпа",b="Торгуючи в темних закутках Покинутої Печери, Ґерріґ Боунґріп здається більшості городян просто дивакуватим продавцем химерних реліквій і заборонених знань. Проте його скромна крамничка має куди темніше призначення. Боунґріп — діяльний член нігілістичного культу Молота Присмерку, і свою крамницю він використовує, щоб збирати небезпечні рукописи й маловідомі тексти про Древніх Богів просто під носом у Сенату Айронфорджа й Високого Престолу."},{t="Збирання заборонених знань",b="Ґерріґ залучає необізнаних шукачів пригод з Альянсу, щоб ті здобували прадавні артефакти, як-от Рукопис Лорґаліса, загублений глибоко в Чорноглибинних Печерах. Щойно ці реліквії потрапляють до нього, він переписує блюзнірські знання й розсилає їх своїм братам по культу по всьому Азероту. Через приховані зв'язки з темними спільниками на кшталт Скуерто й постатями, що мають справу з прадавніми первісними сутностями, як-от Мізраель, Боунґріп невтомно наближає апокаліптичні задуми культу."}},faq={{q="Хто такий Ґерріґ Боунґріп?",a="Ґерріґ Боунґріп — дворф, що тримає крамницю «Руни й Долі Боунґріпа» в Покинутій Печері Айронфорджа. Він торгує химерними дивовижами й маловідомими текстами про прадавні ритуали.",al={"хто такий боунґріп","лор ґерріґа боунґріпа","боунґріп айронфордж"}},{q="Що він робить із Рукописом Лорґаліса?",a="Він шукає Рукопис Лорґаліса з Чорноглибинних Печер для своєї збірки рідкісних текстів. Подальше розслідування може відкрити більше про те, навіщо він йому.",al={"навіщо боунґріпу рукопис лорґаліса","здача знання в глибинах","використання рукопису лорґаліса"}},{q="Як Ґерріґ діє в Айронфорджі?",a="Ґерріґ тримається непомітно — як дивакуватий учений і торговець із Покинутої Печери, де купує й продає маловідомі тексти.",al={"чи знає айронфордж що боунґріп культист","чому боунґріпа не чіпають в айронфорджі"}},{q="Що пов'язує його з Мізраель?",a="Ґерріґ — давній знайомий дворфа Скуерто, що досліджує ув'язнену елементаль землі Мізраель на Аратійському нагір'ї. Через ці зв'язки Ґерріґ допомагає організовувати доручення, пов'язані з давніми ритуалами ув'язнення й первісними силами.",al={"ґерріґ боунґріп і мізраель","скуерто й ґерріґ"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="Ґершала Найтвіспер",s="Ґершала Найтвіспер — нічний ельф-дослідник, що живе в прибережному поселенні Обердайн на Темному Узбережжі. Глибоко стурбований шляхом, яким пішли високі ельфи Кель'Таласу, він вивчає зразки проклятих морських і демонічних істот, щоб зрозуміти, як магічна скверна спотворює і розум, і тіло.",h="Ґершала Найтвіспер — нічний ельф-дослідник, що живе в прибережному поселенні Обердайн на Темному Узбережжі.",kw={"ґершала найтвіспер","обердайн","темне узбережжя","ельфи крові","наги","сатири"},ang={["faction:Alliance"]="Ґершала — один із головних покровителів, що посилає експедиції Альянсу назустріч небезпекам Чорноглибинних Печер і дбає, щоб їхні вилазки приносили цінні магічні знання.",["race:NightElf"]="Для нічних ельфів похмурі дослідження Ґершали — болюче нагадування про давній Розкол і страшну ціну магічної залежності, що колись перетворила їхніх родичів на жахіття."},sec={{t="Вивчення перетворення",b="Мирно живучи в Обердайні, Ґершала Найтвіспер дивиться далі за нагальні прибережні клопоти Темного Узбережжя — на ширшу небезпеку, що підкрадається. З тривогою спостерігаючи, як рештки високих ельфів удаються до небезпечних магічних практик і називають себе ельфами крові, Ґершала прагне зрозуміти тілесне й духовне падіння, що настає за неприборканою магією. Щоб розкрити ці таємниці, він посилає досвідчених шукачів пригод з Альянсу в затоплені зали Чорноглибинних Печер по зіпсуті стовбури мозку наг і сатирів, що там живуть."},{t="Протиотрута від загибелі",b="Похмуре зацікавлення Ґершали стовбурами мозку наг і сатирів пояснюється їхнім спільним родоводом: обидва народи колись були нічними ельфами, доки не схилилися перед Королевою Азшарою й демонічними угодами. Розтинаючи сліди, які тисячоліття демонічних і безодніх енергій лишили на їхній нервовій системі, він сподівається знайти застереження чи запобіжники, що вберегли б інших ельфійських родичів від подібного потворного каліцтва."}},faq={{q="Де знайти Ґершалу Найтвіспера?",a="Ґершалу Найтвіспера можна знайти в Обердайні — головному портовому містечку Альянсу на узбережжі Темного Узбережжя.",al={"місце ґершали","де ґершала","знайти ґершалу найтвіспера"}},{q="Навіщо Ґершалі довгасті мізки наг і сатирів?",a="Ґершала вивчає зіпсовані довгасті мізки, щоб дослідити, як глибоке магічне й демонічне перетворення змінює будову тіла колишніх нічних ельфів. І наги, і сатири колись були ельфами, і він прагне зрозуміти фізичні механізми їхнього зіпсуття.",al={"навіщо мізки","лор дослідження скверни","що вивчає ґершала"}},{q="Чого Ґершала сподівається досягти своїми дослідженнями?",a="Ґершала сподівається, що його дослідження допоможуть уберегти кривавих ельфів від того, щоб через небезпечну залежність від скверни й неприборканої тайної сили вони не скотилися до зла й жахливого каліцтва.",al={"мета ґершали","чому допомагати кривавим ельфам","мета досліджень ґершали"}},{q="Де шукати зразки, потрібні Ґершалі?",a="Він посилає шукачів пригод до Чорноглибинних Печер — давніх затоплених руїн храму на узбережжі Ашенвалю, де аж кишить і нагами, і сатирами.",al={"де мізки","мізки в чорноглибинних печерах","де знайти речі для ґершали"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="Ґаму-Ра",s="Ґаму-Ра — давній велетень, морська черепаха, що живе в Ставку Аск'ар у Чорноглибинних Печерах. Колись мирний мешканець затонулого храму Елуни, він потрапив до рук культу Молота Присмерку, який закатував його й довів до божевілля, щоб зробити лютим охоронцем.",h="Ґаму-Ра — давній велетень, морська черепаха, що живе в Ставку Аск'ар у Чорноглибинних Печерах.",kw={"ґаму-ра","черепаха","ставок аск'ар","молот присмерку","чорноглибинні печери"},ang={["class:Druid"]="Друїди бачать у муках Ґаму-Ра і його вимушеній люті трагічне осквернення дикої природи слугами Древніх Богів.",["class:Hunter"]="Мисливці, що спускаються в Чорноглибинні Печери, можуть пожаліти Ґаму-Ра — шляхетного давнього звіра, зламаного темною неволею; утім, терплячий мисливець ще може його приручити.",["race:NightElf"]="Для нічних ельфів біда Ґаму-Ра — гірке нагадування про те, як мерзенний Молот Присмерку осквернив священний храм Елуни."},sec={{t="Змучений лагідний звір",b="До осквернення Чорноглибинних Печер Ґаму-Ра був одним з останніх мирних природних мешканців затоплених руїн храму нічних ельфів, присвяченого Елуні. Коли нігілістичний культ Молота Присмерку захопив святилище, культисти вирвали давнього звіра з його тихого життя й замкнули в неволі. Його не вбили — роками його систематично мучили, і він зазнавав і душевних, і тілесних катувань від рук культистів."},{t="Охоронець глибин",b="Зламаний тривалою жорстокістю, велетенський звір зрештою збожеволів. Давши знівеченій істоті ім'я Ґаму-Ра, культисти вишколили його на лютого вартового звіра. Тепер він патрулює острівець у Ставку Аск'ар, оточений меншими черепахами, і наосліп нападає на кожного, хто ввійде до печер, — служачи тому самому культу, що зламав його розум."}},faq={{q="Хто такий Ґаму-Ра?",a="Ґаму-Ра — велетенська черепаха, що живе в Ставку Аск'ар у Чорноглибинних Печерах. Колись мирний мешканець храму Елуни, він потрапив у полон до культу Молота Присмерку, який катуваннями зламав його й перетворив на лютого звіра-охоронця.",al={"лор ґаму-ра","гігантська черепаха в чорноглибинних печерах","хто такий ґаму ра"}},{q="Чому Ґаму-Ра ворожий до чужинців?",a="Культ Молота Присмерку ув'язнив черепаху й роками катував, зламавши його дух і довівши до цілковитого божевілля. Вони привчили його кидатися на кожного чужинця, що наближається до внутрішніх святинь.",al={"чому черепаха сердита","чому черепаха нападає","безумство ґаму-ра"}},{q="Чи може мисливець приборкати Ґаму-Ра?",a="Так. Попри розміри й роки мук, Ґаму-Ра може приборкати вправний мисливець.",al={"приборкати ґаму-ра","чи мисливець приборкає черепаху"}},{q="Що таке Ставок Аск'ар?",a="Ставок Аск'ар — затоплена підземна печера в Чорноглибинних Печерах. Ґаму-Ра блукає посеред невеликого острівця там, в оточенні сумирних місцевих черепах.",al={"ставок аск'ар","де ґаму ра"}},{q="Що пов'язує його з Древніми Богами?",a="Сам Ґаму-Ра не створіння Порожнечі, але його розум спотворили культисти Молота Присмерку, що поклоняються Древнім Богам. Вони перетворили давню істоту на мимовільного охоронця своїх темних ритуальних місць.",al={"ґаму-ра древні боги","чи черепаха зіпсована"}}},fp="9,251,24.464.0,21.379.0,17.233.0,38.222.0,28.87.0,27.161.0,45.220.0"}
P.entries["npc:gilnid"] = {n="Ґілнід",s="Ґілнід на прізвисько Плавильник — гоблін, головний інженер, що керує горнами в глибинах Мертвих Копалень. Він наглядає, як сиру руду переплавляють на чистий метал і боєприпаси для потаємного броненосця Едвіна Венкліфа. Без його вогняного ремесла Братство Дефіас не мало б важких гармат для нападу на Стормвінд.",h="Ґілнід на прізвисько Плавильник — гоблін, головний інженер, що керує горнами в глибинах Мертвих Копалень.",kw={"ґілнід","гоблін","ливарня","плавильник","гармати","мертві копальні"},ang={["faction:Alliance"]="Зупинивши Ґілніда, ви зупините збройовий конвеєр Дефіас, і корабель Венкліфа так і не дістане повного озброєння, перш ніж загрожувати Гавані Стормвінда.",["profession:Engineering"]="Ливарня Ґілніда — взірець гоблінської важкої промисловості: у пекельних умовах тут пачками виробляють корабельні гармати, боєприпаси й обшивку.",["profession:Mining"]="Велетенські доменні печі й плавильні казани в майстерні Ґілніда показують, як Братство Дефіас перетворює сирі надра Вестфолу на чисте залізо й зброю."},sec={{t="Господар ливарні",b="Глибоко в Мертвих Копальнях Братство Дефіас покладається на промислову майстерність, щоб кувати зброю. Ґілнід — головний плавильник Венкліфа: він командує цілим невеликим військом гоблінів-робітників, майстрів і ковалів у центральній ливарні. Вищий за більшість родичів, він безжально жене команду крізь дим і шлак, вигукує накази й не дає перепочинку, аби сира залізна руда ставала важкою обшивкою та смертоносними снарядами."},{t="Озброєння броненосця",b="Плавильня — серце великих задумів Братства. Ґілнід особисто відповідає за відливання важких гармат і боєприпасів для велетенського броненосця, що стоїть у підземній бухті за його майстернею. Доки ливарня не видасть кожну гармату, кожен ствол і кожне ядро, корабель Дефіас не готовий до задуманого удару по Стормвінду."}},faq={{q="Хто такий Ґілнід?",a="Ґілнід — гоблін-інженер і головний ливар Едвіна Венкліфа в Мертвих Копальнях. Він наглядає за кузнями Братства й очолює промислове виготовлення гармат і боєприпасів для їхньої воєнної машини.",al={"ґілнід мертві копальні","хто такий ґілнід","плавильник"}},{q="Що Ґілнід робить у Мертвих Копальнях?",a="Братство Дефіас найняло гоблінів-інженерів, щоб збудувати й спорядити свій прихований бойовий корабель. Ґілніда поставили керувати плавильнею, де видобуту залізну руду перетворюють на готові деталі, обладунки й гармати.",al={"чому гоблін у мертвих копальнях","лор ґілніда дефіас","що робить ґілнід"}},{q="Над чим працює Ґілнід?",a="Ґілнід відповідає за виготовлення величезних гармат, корабельних деталей і ядер, потрібних, щоб озброїти корабель, захований на причалах глибше в копальнях.",al={"гармата ґілніда","що будує ґілнід","мета кузні мертвих копалень"}},{q="Чому Ґілніда треба здолати?",a="Ґілнід контролює ливарню, що перекриває шлях до бухти. Важкі броньовані двері, які ведуть глибше до корабля Дефіасу, лишаються замкненими, доки плавильню не захоплено.",al={"чому вбивати ґілніда","двері за ґілнідом"}},{q="Чи працює Ґілнід безпосередньо на Едвіна Венкліфа?",a="Так. Він не з давніх каменярів, а найманий гоблін-фахівець, що служить безпосередньо Венкліфові, займаючись важкою металургією й виробництвом зброї.",al={"венкліф і ґілнід","чи ґілнід вожак дефіас"}},{q="Чому довкола нього стільки гоблінів?",a="Ґілнід очолює загін гоблінів-інженерів у ливарні. Вони працюють біля доменних печей, розливають розплавлене залізо й збирають боєприпаси під його суворим, невтомним наглядом.",al={"гобліни ґілніда","команда кузні мертвих копалень"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Ґілшалан Віндвокер",s="Ґілшалан Віндвокер — дослідник, нічний ельф, що відпочиває біля підніжжя великого дерева Алдрассил у Тінедолі. Стривожений раптовою скверною, що вкорінюється в Тельдрассилі, він вивчає тутешню звірину, щоб зрозуміти неприродну лють, яка вразила віття. Його дослідження павуків Вебвуда дають перші підказки про гниль, що точить Світове Дерево.",h="Ґілшалан Віндвокер — дослідник, нічний ельф, що відпочиває біля підніжжя великого дерева Алдрассил у Тінедолі.",kw={"ґілшалан віндвокер","дослідник","павуки вебвуда","алдрассил","тінедол","печера тіньової нитки","тенарон стормґріп"},ang={["class:Druid"]="Його дослідження прямо підтримують спроби Кола Кенарія розпізнати порушення природної рівноваги, що ятриться у вітті Тінедолу.",["race:NightElf"]="Ґілшалан уособлює перші зусилля вашого народу зрозуміти, чому новопостале Світове Дерево вже породжує уражену, несамовиту звірину."},sec={{t="Учений біля коріння",b="Спокійно сидячи на кам'яних сходах, що ведуть в Алдрассил, Ґілшалан Віндвокер із дедалі більшою тривогою спостерігає за тихим шатром Тінедолу. Тельдрассил посадили, щоб повернути нічним ельфам утрачений прихисток і злагоду з природою, та ознаки глибокої духовної недуги з'явилися майже одразу. Ґілшалан присвятив себе вивченню того, як ця скверна проявляється в тутешніх звірах, починаючи з отруйних павуків, що плетуть павутиння неподалік."},{t="Загроза Вебвуда",b="Головна увага Ґілшалана зосереджена на павуках Вебвуда, що чигають у Печері Тіньової Нитки на півночі. Ці створіння, колись урівноважена частина лісового живого світу, стали неприродно ворожими й споганеними. Посилаючи молодих новачків збирати отруйні мішки й цілі павучі яйця, Ґілшалан працює над аналізом зміненої сили отрути і намагається розрізнити, чи передається скверна з покоління в покоління, чи шириться ззовні, через ґрунт Тельдрассила."},{t="Звістка Архідруїдові",b="Маючи отруту і яйце, Ґілшалан вважає, що отрута павуків виявить властивості, пов'язані з нещодавнім зростанням нового Світового Дерева. Він улаштовує відправлення зразків до Дарнасуса, де продовжить свої дослідження. А ще він переказує перспективним захисникам, що Тенарон Стормґріп питав про них у найвищій кімнаті Алдрассила, звідки друїдський провід пильнує молоде Світове Дерево."}},faq={{q="Хто такий Ґілшалан Віндвокер?",a="Ґілшалан Віндвокер — нічний ельф-учений, що сидить біля підніжжя Алдрассила в Тінедолі. Він досліджує таємничу скверну, що закрадається до живності Тельдрассила.",al={"ґілшалан","хто такий ґілшалан","віндвокер нічний ельф"}},{q="Навіщо Ґілшаланові отрута павуків Вебвуда?",a="Ґілшалан хоче вивчити хімічні й духовні властивості отрути, щоб зрозуміти, чому лісові павуки стали такими агресивними й зміненими.",al={"навіщо отрута вебвуда","завдання отрути вебвуда","павучна отрута ґілшалана"}},{q="Що він робить з яйцем павука Вебвуда?",a="Йому потрібні живі зразки для дослідження, але дорослого велетенського павука спіймати надто небезпечно. Невилуплене яйце куди легше перевезти, тож він відсилає його разом з отрутою до Дарнасуса, де павученят можна буде утримувати й вивчати.",al={"завдання яйця вебвуда","навіщо павучі яйця","яйце вебвуда"}},{q="Куди Ґілшалан посилає шукачів пригод далі?",a="Коли яйце доставлено, він каже шукачам пригод, що про них питав Тенарон Стормґріп, і посилає їх нагору, до найвищої кімнати на вершині Алдрассила.",al={"виклик тенарона","до кого йти після ґілшалана","після яйця вебвуда"}},{q="Де перебуває Ґілшалан Віндвокер?",a="Він сидить на кам'яній стежці біля північного підніжжя Алдрассила, просто біля входу в порожнину центрального дерева Тінедолу.",al={"місце ґілшалана","де віндвокер","знайти ґілшалана"}},{q="Чому живність Тельдрассила агресивна?",a="Невідома пошесть почала просочуватися корінням і ґрунтом Тельдрассила, спотворюючи розум і природу його створінь і непокоячи вчених мешканців на кшталт Ґілшалана.",al={"чому павуки скажені","скверна тельдрассила","зіпсовані звірі тіньової долини"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:glorin-steelbrow"] = {n="Ґлорін Стілброу",s="Ґлорін Стілброу — дворф-агент, якого можна застати за кухлем у Таверні «Глибока Вода» в Гавані Менетіл. Як соратник Єпископа Фартінґа із Собору Світла в Стормвінді, він допомагає шукачам пригод розслідувати загибель Третього Флоту й повертати священні реліквії та матеріали, розкидані узбережжям Багнокраю. Завдяки йому похмурі хащі Сутінколісся пов'язані просто з затонулими кораблями на півночі.",h="Ґлорін Стілброу — дворф-агент, якого можна застати за кухлем у Таверні «Глибока Вода» в Гавані Менетіл.",kw={"ґлорін стілброу","дворф","гавань менетіл","третій флот","багнокрай","фартінґ"},ang={["class:Paladin"]="Паладини, що виконують доручення Фартінґа, побачать, що без Ґлоріна не обійтися, коли треба добути загартоване Світлом залізо — священний метал для зброї, благословенної Святим Світлом.",["faction:Alliance"]="Ґлорін відіграє ключову роль у поверненні важливих воєнних реліквій Альянсу й освячених матеріалів, утрачених під час морських катастроф біля Багнокраю.",["race:Dwarf"]="Ґлорін — утілення дворфійської підприємливості й згуртованості: з морського вузла Гавані Менетіл він підтримує союзників по всьому Каз Модану та в людських королівствах півдня."},sec={{t="Зв'язок у гавані",b="Єпископ Фартінґ із Собору Світла в Стормвінді допомагає людям Сутінколісся боротися з повзучими жахами, але має зв'язки й далеко на півночі, у Гавані Менетіл. Ґлорін Стілброу, що сидить у гомінкій Таверні «Глибока Вода», — очі й руки Фартінґа на узбережжі. Він допомагає й підказує дорогу мандрівникам, яких відіслали на північ шукати священні метали й забуті реліквії, і стає важливим містком між бідами південного лісу та затонулими уламками Багнокраю."},{t="Приречений флот і втрачені реліквії",b="Стілброу добре знає трагедію Третього Флоту, кораблі якого розбило й затягло під хвилі біля берегів Багнокраю. Він направляє шукачів пригод обнишпорити примарні уламки в пошуках загублених зливків загартованого Світлом заліза й могутнього проклятого артефакту, відомого як Око Палета. Ґлорін знає: повернути такі святі матеріали — життєво важливо, щоб викувати зброю, здатну стримати темні сили, які загрожують Альянсу."}},faq={{q="Хто такий Ґлорін Стілброу?",a="Ґлорін Стілброу — дворф із Таверни «Глибока Вода» в Гавані Менетіл. Він працює разом з Єпископом Фартінґом зі Стормвінда й допомагає шукачам пригод, що вирушають на північ піднімати затонулі вантажі й реліквії біля узбережжя Багнокраю.",al={"хто такий ґлорін","лор ґлоріна стілброу","що робить ґлорін"}},{q="Де знайти Ґлоріна Стілброу?",a="Ґлорін перебуває на першому поверсі Таверни «Глибока Вода» в Гавані Менетіл на західному узбережжі Багнокраю.",al={"місце ґлоріна","де ґлорін стілброу","ґлорін таверна глибоководдя"}},{q="Чому дворф із Гавані Менетіл пов'язаний із Сутінколіссям?",a="Єпископ Фартінґ із Собору Світла в Стормвінді шукає могутні святі реліквії й освячені метали, щоб боротися з темрявою, що насувається на Сутінколісся. Він посилає довірених посланців до Ґлоріна Стілброу, який знає узбережжя Багнокраю й може підказати рятувальникам, де лежать рештки Третього флоту.",al={"чому завдання сутінколісся у мокрих землях","зв'язок із фартінґом","чому посилати у мокрі землі"}},{q="Що за Третій флот, про який говорить Ґлорін?",a="Третій флот — морська експедиція Альянсу, що загинула біля узбережжя Багнокраю. Її розбиті корпуси тепер лежать на морському дні, де блукають потонулі моряки й ховаються цінні вантажі на кшталт заліза Світлокузні та давніх артефактів.",al={"що таке приречений флот","третій флот мокрі землі","завдання приреченого флоту"}},{q="Що таке Око Палета?",a="Око Палета — давня релігійна реліквія, що була на борту затонулого флоту. Коли її з допомогою Ґлоріна піднімають з морського дна, жерцям доводиться її очищати через темну скверну, що досі витає довкола уламків.",al={"око палета","реліквія палета","що таке око палета"}},{q="Для чого потрібне залізо Світлокузні?",a="Залізо Світлокузні — рідкісний освячений метал, з якого кують благословенну зброю, здатну здолати могутню нежить і демонічні сили. Ґлорін допомагає піднімати загублені злитки з уламків кораблів, щоб підтримати захисників Сутінколісся.",al={"залізо світлокузні","загублені зливки","благословенна рука"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.0,33.221.0"}
P.entries["npc:gnoarn"] = {n="Ґноарн",s="Ґноарн — гном-вигнанець, що живе в Містечку Майстрів у дворфійському гірському місті Айронфорджі. Утративши дім після нищівного падіння Гномреґану, він допомагає своєму розпорошеному народу: скеровує шукачів пригод на допомогу іншим гномам-інженерам і вцілілим.",h="Ґноарн — гном-вигнанець, що живе в Містечку Майстрів у дворфійському гірському місті Айронфорджі.",kw={"ґноарн","містечко майстрів","гномреґан","гноми-біженці","бінґлз бластенгаймер","шоні тихий","айронфордж"},ang={["faction:Alliance"]="Герої Альянсу, що проходять через Айронфордж, можуть поговорити з Ґноарном і дізнатися про важливі гномські інженерні справи в Дун Мороґу, Лох Модані та Стормвінді.",["race:Gnome"]="Для інших гномів Ґноарн утілює стійкість громади біженців у Містечку Майстрів: завдяки йому інженери, що втратили дім, підтримують зв'язок по всіх Східних Королівствах."},sec={{t="Вигнанець із Гномреґану",b="Як і більшість побратимів, Ґноарн мусив тікати з глибин Гномреґану, коли туди вдерлися троги, а згубна радіація зробила величну підземну столицю непридатною для життя. Знайшовши прихисток у Містечку Майстрів в Айронфорджі завдяки гостинності дворфів Бронзбірдів, Ґноарн проводить дні, стежачи за долею інших уцілілих. Він став неофіційним координатором серед біженців і скеровує вправних мандрівників до гномів у далеких краях, яким терміново потрібна допомога, — як-от до пілота Бінґлза Бластенгаймера, що застряг у Лох Модані, чи до честолюбного інженера на ім'я Шоні Тихий у Стормвінді."}},faq={{q="Хто такий Ґноарн?",a="Ґноарн — гном, який уцілів і тепер живе серед біженців у Містечку Майстрів, гномському кварталі Айронфорджа. Він спрямовує мандрівників на допомогу іншим гномам-вигнанцям, що працюють над різними задумами по всіх землях Альянсу.",al={"хто цей гном","лор ґноарна","ґноарн нпс"}},{q="Де знайти Ґноарна?",a="Він у Містечку Майстрів, у північно-східній частині Айронфорджа, серед гудіння механізмів, шестерень і верстаків своїх родичів-вигнанців.",al={"місце ґноарна","де ґноарн","знайти ґноарна"}},{q="Які завдання дає Ґноарн?",a="Ґноарн просить шукачів пригод допомогти іншим розкиданим по світу гномам. Зокрема, він посилає їх до Лох Модану дізнатися, що сталося зі зниклим пілотом Бінґлзом Бластенгаймером, а також відправляє мандрівників до Стормвінда поговорити з винахідницею Шоні Тихий про її гіробуроматичні екскаваціонатори.",al={"завдання ґноарна","чого хоче ґноарн"}},{q="Що сталося з волоссям Ґноарна?",a="До падіння Гномреґана Ґноарн славився ексцентричною зачіскою «гномоафро». На жаль, він утратив свою знамениту чуприну після катастрофічного зараження й радіоактивних викидів, що спустошили його рідне місто.",al={"ґноарн афро-зачіска","волосся ґноарна"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="Ґодрік Фарсан",kw={"ґодрік фарсан","карендін галґар","чорнокнижник","магічний квартал","сукуб","андерсіті"},ang={["class:Warlock"]="Чорнокнижники-Відступники, які прагнуть опанувати виклик сукуба, мусять звернутися до Ґодріка, щоб підготувати потрібні приманки й зрозуміти ненаситну природу демонічних слуг.",["race:Undead"]="Ґодрік утілює філософію чорнокнижників-Відступників: прийняти тілесний занепад і сліпоту, відточуючи натомість темне магічне чуття, що заступає смертні вади."},sec={{t="Очі в темряві",b="Situated amidst the summoning circles of the Magic Quarter, Godrick Farsan aids Master Carendin Halgar in guiding aspiring Forsaken warlocks. Though he lacks physical sight, Godrick says he can still see in a different way, without explaining the means. He tests practitioners seeking to bind greater demonic entities, dispatching them to gather pure hearts and essences needed for intricate summoning rituals."}},faq={{q="Хто такий Ґодрік Фарсан?",a="Ґодрік Фарсан — чорнокнижник із Відступників, що служить у Магічному Кварталі Андерсіті. Він допомагає майстрові Карендіну Галґару навчати молодих чорнокнижників і проводити їхні ритуали.",al={"ґодрік фарсан","хто такий ґодрік"}},{q="Як Ґодрік бачить, якщо він сліпий?",a="Godrick says that he sees in a different way despite his blindness. The precise means are not explained.",al={"чи ґодрік сліпий","як ґодрік бачить"}},{q="Чи Ґодрік родич Страгада Фарсана?",a="They share a surname, but no family connection is confirmed.",al={"страгад фарсан родич","страгад фарсан брат","чи ґодрік і страгад родичі"}},{q="Яку роль він відіграє в навчанні чорнокнижників?",a="Ґодрік наглядає за обрядами підкорення в чорнокнижників і, зокрема, проводить їх через завдання на кшталт здобуття чистих сердець, щоб приманити й підкорити сукуба.",al={"завдання чорнокнижників ґодріка","завдання сердець чистих"}}},fp="14,198,16.410.0,22.199.0,35.104.0,37.60.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="Ґолнір Болдерто",s="Ґолнір Болдерто — дворфійський торговець гірницьким приладдям, що стоїть біля гомінкого Великої Кузні в Айронфорджі. Він продає все потрібне рудокопам і шукачам руди, а також приймає депеші від місцевих гінців і мандрівників.",h="Ґолнір Болдерто — дворфійський торговець гірницьким приладдям, що стоїть біля гомінкого Великої Кузні в...",kw={"ґолнір болдерто","крамар","велике горно","гірництво","кайла","айронфордж"},ang={["profession:Mining"]="Рудокопи, що навідуються до Великої Кузні, покладаються на Ґолніра в усьому, що стосується ремесла, — від запасних кайл до флюсів, потрібних, щоб переплавити сиру руду на чисті злитки.",["race:Dwarf"]="Для дворфів, що повертаються з перших мандрів у Долині Холодного Хребта чи Хараносі, Ґолнір — один із перших знайомих у столиці: він вітає мандрівників просто біля вогняного серця гори."},sec={{t="Крамар біля Великої Кузні",b="У ревучому жарі Великої Кузні Айронфорджа Ґолнір Болдерто споряджає шукачів руди й ремісників усім необхідним для їхнього ремесла. Від міцних кайл до флюсів і вугілля — його товари живлять невтомні плавильні вогні й кузні, без яких не уявити дворфійської столиці. Ґолнір, родич Джеофрама Болдертоу, — той, до кого насамперед звертаються робітники, що прибувають до міста: він часто скеровує новачків або приймає листи щодо постачання з ближніх застав."}},faq={{q="Де знайти Ґолніра Болдерто?",a="Ґолнір Болдерто стоїть біля Великої Кузні в Айронфорджі, неподалік від центральних плавилень і ковальських майстерень, поруч з іншими торговцями ремісничим товаром.",al={"місце ґолніра","де ґолнір","ґолнір болдерто айронфордж"}},{q="Що продає Ґолнір?",a="Він постачає все для гірництва: продає кайла, вугілля, флюси та інше необхідне спорядження, щоб старателям було чим добувати й очищати руду.",al={"крам ґолніра","що продає ґолнір","товари ґолніра"}},{q="Чи пов'язаний Ґолнір Болдерто з якимись завданнями?",a="Так. Кур'єрські завдання, що пов'язують дворфські поселення довкола зі столицею, — як-от доручення від Ґріта Турдена чи рейси з застав на кшталт Телсамара, — велять мандрівникам доставити послання просто в руки Ґолніра.",al={"завдання ґолніра","їзда до айронфорджа ґолнір"}},{q="Чи Ґолнір родич когось іще в Дун Мороґу?",a="Ґолнір носить те саме родове ім'я, що й Джеофрам Болдертоу — наставник гірників, який працює поруч із ним біля Великої Кузні Айронфорджа.",al={"родина болдерто","джефрам болдерто родич"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="Ґорболд Стілгенд",s="Ґорболд Стілгенд — дворфський торговець, що працює в Обердайні на імлистих берегах Темного Узбережжя. Далеко від засніжених зал Каз Модану він постачає мандрівникам, ремісникам і місцевим нічним ельфам усілякі товари й торговельні припаси.",h="Ґорболд Стілгенд — дворфський торговець, що працює в Обердайні на імлистих берегах Темного Узбережжя.",kw={"ґорболд стілгенд","обердайн","торговець","дворфи","затонулі кораблі","темне узбережжя"},ang={["faction:Alliance"]="Ґорболд показує практичну співпрацю східних народів Альянсу з нічними ельфами, завдяки якій торгівля не спиняється через Велике Море.",["race:Dwarf"]="Знайоме айронфордзьке обличчя на кшталт Ґорболдового серед імлистих нічних краєвидів Темного Узбережжя — приємне нагадування дворфам-мандрівникам про дім."},sec={{t="Дворфський торговець у Калімдорі",b="Хоча більшу частину півночі Калімдору заселяють потайні нічні ельфи, застави Альянсу на кшталт Обердайна покладаються на торговців з-за Великого Моря, щоб торгівля не спинялася. Ґорболд Стілгенд — свідчення того, як далеко сягає торгівля Айронфорджа. Працюючи пліч-о-пліч із калдореями, він продає товари, реагенти, ремісниче приладдя й інструменти шукачам пригод, які готуються досліджувати підступні береги й ліси Темного Узбережжя."},{t="Морські справи",b="Окрім щоденних товарів, Ґорболд пильно стежить за небезпечними прибережними водами біля Обердайна. Води Темного Узбережжя, всіяні рифами, славляться тим, що поглинають кораблі Альянсу, тож торговці на кшталт Ґорболда мають прямий інтерес до вантажів, що пішли на дно. Мандрівники, готові пірнати в морські глибини, часто знайдуть у ньому охочого до врятованого добра й загублених журналів із затонулих кораблів."}},faq={{q="Хто такий Ґорболд Стілгенд?",a="Ґорболд Стілгенд — дворф-торговець ремісничим товаром у прибережному порту Обердайн на Темному Узбережжі.",al={"ґорболд","хто такий ґорболд стілгенд","дворф в оберіні"}},{q="Що продає Ґорболд Стілгенд?",a="У нього є звичайне ремісниче приладдя, складники для виготовлення речей, інструменти для збирання та реагенти — пляшечки й нитки, які знадобляться ремісникам, що проходять через Обердайн.",al={"що продає ґорболд","товари ґорболда","список торговця ґорболда"}},{q="Чому дворф з Айронфорджа живе на Темному Узбережжі?",a="Обердайн — важливий перевалочний пункт Альянсу між Калімдором і Східними Королівствами. Дворфи часто бувають тут заради торгівлі, досліджень і підтримки союзників — нічних ельфів.",al={"чому тут дворф","чому ґорболд на темному узбережжі","айронфордж в оберіні"}},{q="Чи дає Ґорболд якісь завдання?",a="Так, у завданні «Глибокий океан, безмежне море» він посилає шукачів пригод до затонулих уламків біля берегів Темного Узбережжя, щоб підняти втрачений корабельний вантаж.",al={"завдання ґорболда","хто дає завдання про глибокий океан"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="Ґордон Вендгем",s="Ґордон Вендгем — зброяр і торговець із Відступників, що тримає крамницю в гамірному Торговому Кварталі Андерсіті. Він озброює новоприбулих героїв і місцевих захисників Темної Леді надійною сталлю, клинками й булавами. Окрім торгівлі звичайною зброєю, він часто стає зв'язковим для гінців, що прибувають із поверхні.",h="Ґордон Вендгем — зброяр і торговець із Відступників, що тримає крамницю в гамірному Торговому Кварталі...",kw={"ґордон вендгем","зброяр","торговий квартал","андерсіті","зброя","гінці"},ang={["class:Warrior"]="Ґордон пропонує надійні прості клинки й дробильну зброю для бійців передової, які хочуть відточити володіння зброєю в столиці.",["race:Undead"]="Для щойно визволених Відступників, що виходять із Похоронного Подзвону, торговці на кшталт Ґордона Вендгема з Торгового Кварталу — практична опора воєнних зусиль їхнього молодого народу."},sec={{t="Зброя Торгового Кварталу",b="Серед вогкого каміння й хімічних каналів Торгового Кварталу Андерсіті Ґордон Вендгем постачає необхідну зброю тим, хто бере її до рук заради Відступників. Від простих кинджалів і ручних сокир до міцних палашів і булав — його товар розрахований на молодих бійців, яким потрібне надійне залізо, перш ніж вирушити в спірні землі Лордерона."},{t="Куди прямують гінці",b="Окрім торгівлі, Вендгем вплетений у жваву мережу постачання столиці. Мандрівників, що виконують доручення розпорядників польотів і гінців, — як-от тих, що прибувають від доглядачів кажанів на руїнах, — часто скеровують просто до його прилавка. Завдяки місцю в самому серці Торгового Кварталу він — доступна й упізнавана постать, через яку йдуть прості поставки й доручення в усьому підземному місті."}},faq={{q="Хто такий Ґордон Вендгем?",a="Ґордон Вендгем — торговець-нежить у Торговому Кварталі Андерсіті. Він продає звичайну бойову зброю і приймає кур'єрів, що прибувають до столиці.",al={"лор ґордона вендгема","хто такий вендгем","ґордон андерсіті"}},{q="Де знайти Ґордона Вендгема?",a="Ви знайдете його біля зброярської крамнички в Торговому Кварталі — торговому кільці посеред підземних залів Андерсіті.",al={"місце ґордона вендгема","де ґордон в андерсіті","торговець зброєю торгового кварталу"}},{q="Що він продає?",a="Він пропонує широкий вибір простої зброї звичайної якості: мечі, кинджали, булави, палиці, сокири й різноманітну метальну зброю — саме те, що треба шукачам пригод, які набираються досвіду.",al={"крам вендгема","що продає ґордон","зброя ґордона вендгема"}},{q="Які завдання з ним пов'язані?",a="Він бере участь у перших доставках між кажанячими сідалами на поверхні та нутрощами Андерсіті, зокрема в пересилках між ним і доглядачем кажанів Майклом Гарреттом.",al={"завдання ґордона вендгема","поїздка до андерсіті","завдання майкла ґарретта"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {n="Ґорнек",s="Ґорнек — орк-наглядач у Долині Випробувань у Дуротарі. Саме він першим приймає нових орків і тролів Темного Списа, які готуються довести свою цінність Новій Орді.",h="Ґорнек — орк-наглядач у Долині Випробувань у Дуротарі.",kw={"ґорнек","наглядач","орк","долина випробувань","новобранці","дуротар","нова орда"},ang={["race:Orc"]="Для молодих орків з'явитися до Ґорнека — найперший крок до того, щоб скинути дитинство й заслужити почесне місце в Дуротарі.",["race:Troll"]="Як союзники під захистом Тралла, тролі Темного Списа показують Ґорнекові свої вірчі знаки, щоб довести: вони — гідні рівні поруч зі своїми братами-орками."},sec={{t="Зустріч неперевірених",b="Стоячи в самому серці Долини Випробувань, Ґорнек — перше випробування дисципліни для майбутніх воїнів, розвідників і чаклунів Орди. За наказом Вождя Тралла кожен юнак і кожен новоприбулий має заслужити своє місце завзяттям і наполегливістю, а не правом народження. Ґорнек оцінює тих, хто ступає в долину, читає їхні супровідні накази й скеровує до наставників по всьому табору. Чи приніс посвячуваний зашифровану писульку, гліфічний пергамент чи просту табличку — саме Ґорнек приймає його вірчі знаки й ставить на суворий шлях виживання."},{t="Життя на службі Дуротару",b="Посушливі каньйони долини випробовують не лише бойову вправність — вони прищеплюють дух спільноти Нової Орди. Ґорнек стежить, щоб новачки не тинялися без діла, і спрямовує їх до випробувань у сусідніх норах скорпідів, лігвах диких вепрів і під пильним оком бувалих наставників. Тим, хто переживе тренувальні угіддя й знищить загрози, що чаяться в червоних скелястих балках, Ґорнек дає останнє визнання, перш ніж відіслати їх у широкий і небезпечний Дуротар."}},faq={{q="Хто такий Ґорнек?",a="Ґорнек — орк, який зустрічає новачків і роздає їм доручення в Долині Випробувань. Він наглядає за новобранцями Орди, читає їхні вступні документи й направляє кожного до наставника його класу.",al={"ґорнек","хто цей орк","хто такий ґорнек"}},{q="Де знайти Ґорнека?",a="Він стоїть майже в самому центрі Долини Випробувань, на південному заході Дуротару, просто біля Лігва, звідки починають свій шлях молоді орки й тролі Темного Спису.",al={"місце ґорнека","де ґорнек","карта ґорнека"}},{q="Чому новобранці звітують саме йому?",a="Новачки приносять навчальні сувої й таблички, на яких зазначено обране ними ремесло. Ґорнек вивчає ці рекомендаційні листи, переконується, що новобранець підходить, і відправляє його до відповідного наставника в долині.",al={"навіщо йти до ґорнека","завдання зі сувоєм","завдання зі скрижаллю"}},{q="Яка його роль у Новій Орді?",a="Він приймає новоприбулих до Нової Орди Тралла. Його обов'язок — простежити, щоб жоден новобранець не вирушив у широкі простори Дуротару, не засвоївши спершу основ честі, виживання й бойової готовності.",al={"роль ґорнека в орді","що робить ґорнек"}}},fp="6,204,22.613.0,28.513.0,14.190.0,24.155.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="Бабуся Стоунфілд",s="Бабуся Стоунфілд, на ім'я Мілдред, — літня матріарх родини Стоунфілдів, що живе на їхній фермі в Лісі Елвінн. На відміну від своєї сварливої рідні, вона втомилася від гіркої ворожнечі з сусідами Маклурами, що тягнеться поколіннями. Тихо діючи за спиною родини, вона робить усе можливе, щоб допомогти онукові Томмі Джо в його забороненому коханні до Мейбелл Маклур.",h="Бабуся Стоунфілд, на ім'я Мілдред, — літня матріарх родини Стоунфілдів, що живе на їхній фермі в Лісі Елвінн.",kw={"бабуся стоунфілд","мілдред","томмі джо","мейбелл маклур","ворожнеча","закохані"},ang={["faction:Alliance"]="Бабуся Стоунфілд — лагідне нагадування про те, що навіть у серці Альянсу місцеві конфлікти часто потребують тихої дипломатії й простого співчуття, а не сталі."},sec={{t="Таємна миротвориця",b="Як найстарша з живих у роді Стоунфілдів, Мілдред Стоунфілд десятиліттями спостерігала дріб'язкові чвари між своїм домом і Маклурами через дорогу. Замість роздмухувати ворожнечу, вона вважає це тривале суперництво безглуздим і руйнівним. Коли її онук Томмі Джо Стоунфілд закохується в Мейбелл Маклур, Бабуся обирає співчуття замість вірності роду. Покладаючись на давню дружбу з Вільямом Пестлом із Ґолдширу, вона потай задумує допомогти нещасливим закоханим зустрітися таємно, підриваючи вперту ворожнечу, що розділяє дві ферми."}},faq={{q="Хто така Бабуся Стоунфілд?",a="Бабуся Стоунфілд, на ім'я Мілдред, — літня глава родини Стоунфілдів, що живе на своїй фермі в центрі Лісу Елвінн. Вона бабуся Томмі Джо Стоунфілда.",al={"хто така бабуся","мілдред стоунфілд","бабуся стоунфілд"}},{q="Як вона ставиться до ворожнечі з Маклурами?",a="Мілдред зовсім не хоче підтримувати ворожнечу. На відміну від більшості членів обох родин, вона вважає цю образу дурною й шкідливою і воліла б бачити між родинами злагоду, а не нескінченні сварки.",al={"ворожнеча стоунфілдів і маклурів","чи вона ненавидить маклурів"}},{q="Чому вона допомагає Томмі Джо й Мейбелл?",a="Вона любить онука Томмі Джо й хоче, щоб він був щасливий. Оскільки Мілдред не визнає родинної ворожнечі, вона охоче допомагає його забороненому коханню з Мейбелл Маклур і звертається до свого давнього друга Вільяма Пестла, щоб той вигадав для пари якийсь вихід.",al={"навіщо допомагати томмі джо","любовне зілля бабусі","допомога закоханим"}},{q="Ким Вільям Пестл їй доводиться?",a="Вільям Пестл, алхімік, що живе в корчмі «Лев'яча Гордість» у Ґолдширі, — давній і надійний друг Бабусі Стоунфілд. Через перевірених посланців вона просить його приготувати делікатні засоби й зілля для Томмі Джо.",al={"вільям пестл і бабуся","зв'язок вільяма пестла"}}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="Великий Каменяр Марблстен",s="Великий Каменяр Марблстен — шанований дворфійський каменотес у жвавих Торгових Рядах Айронфорджа. Глибоко відданий королівській спадщині Каз Модану, він отримав від Короля Маґні Бронзбірда замовлення спорудити пам'ятник Саллі Баллу — дворфійському воякові, що загинув під час трагедії на Мосту Тандол. Шукачі пригод часто зустрічають його, коли допомагають добути матеріали для цієї скорботної данини.",h="Великий Каменяр Марблстен — шанований дворфійський каменотес у жвавих Торгових Рядах Айронфорджа.",kw={"великий каменяр марблстен","саллі баллу","міст тандол","альтеракський граніт","пагорб дарроу","каменярство","айронфордж"},ang={["faction:Alliance"]="Вшанування жертви Саллі Баллу нагадує Альянсові про кожного солдата, полеглого в його війнах.",["profession:Mining"]="Рудокопи, що добре знають скелі Дун Мороґа й інших країв, оцінять суворі вимоги Марблстена до якості сирого каменю.",["race:Dwarf"]="Для дворфів каменярство — спадщина предків; допомагаючи Марблстенові, ви вшановуєте і ремесло Каз Модану, і пам'ять полеглого вояка Саллі Баллу."},sec={{t="Майстер каменю",b="Дворфійське каменярство — не просто ремесло, а вічне мистецтво, що формує саму душу Айронфорджа. Великий Каменяр Марблстен — серед найкращих майстрів різця в місті; він уособлює багатовікову традицію висікати зали, колони й великі статуї просто з живої гори. У Торгових Рядах він наглядає за міськими спорудами й пам'ятними монументами, що увічнюють історію Бронзбірдів."},{t="Данина короля",b="Найзворушливіша праця Марблстена — пам'ятник, який Король Маґні замовив на честь Саллі Баллу, вояка, що загинув під час трагедії на Мосту Тандол, — як вияв шани до його вдови, що оплакує чоловіка. Прагнучи створити справді довговічний твір, Великий Каменяр наполягає на одному з найкращих каменів — Альтеракському Граніті з Пагорба Дарроу в Гілсбреді."}},faq={{q="Хто такий Великий Каменяр Марблстен?",a="Великий Каменяр Марблстен — досвідчений дворф-каменяр, що працює на Майдані Айронфорджа. Йому доручають міські та королівські скульптурні замовлення, і найвідоміше з них — пам'ятник загиблому воїнові Саллі Баллу, замовлений королем Маґні Бронзбірдом.",al={"хто такий марблстен","роль марблстена","великий каменяр нпс"}},{q="Де знайти Великого Каменяра Марблстена?",a="Він на Майдані Айронфорджа, серед кам'яних брил і архітектурних робіт, неподалік від гамірних крамниць і банків міста.",al={"місце марблстена","де марблстен","марблстен айронфордж"}},{q="Над яким пам'ятником працює Марблстен?",a="Він зводить пам'ятник Саллі Баллу, дворфові-воїну, що загинув під час трагедії на Мосту Тандол. Король Маґні Бронзбірд замовив його на честь Баллу та його вдови, що досі в жалобі.",al={"що він будує","завдання королівської данини","статуя марблстена"}},{q="Навіщо Марблстенові шукачі пригод для збору матеріалів?",a="Марблстен хоче створити справді величну й довговічну роботу, тож береться лише за найкращий камінь. Він посилає мандрівників на Пагорб Дарроу в Гілсбреді по Альтеракський Граніт.",al={"завдання марблстена","навіщо потрібне каміння","матеріали для пам'ятника"}},{q="Що означає титул «Великий Каменяр» у дворфів?",a="У дворфів обробка каменю шанується не менше, ніж ковальство. «Великий Каменяр» — визнаний майстер кам'яної справи, якому довіряють великі державні будівництва, королівські архітектурні задуми й урочисті пам'ятники.",al={"що таке великий каменяр","ранг дворфійського каменяра"}},{q="Марблстен — посадовець Альянсу чи приватний підрядник?",a="Марблстен працює безпосередньо в Айронфорджі й служить королівству Айронфордж та Альянсу, тісно співпрацюючи з двором Короля Маґні Бронзбірда над королівськими замовленнями.",al={"на кого працює марблстен","фракція марблстена"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="Ґраніс Свіфтекс",s="Ґраніс Свіфтекс — дворфійський наставник воїнів, що перебуває в Ґуральні Тандербрю в Хараносі. Відомий прямотою й суворою муштрою, він навчає молодих бійців Альянсу, що спускаються з Перевалу Холодного Кряжа, а досвідчених воїнів скеровує до міста Айронфорджа.",h="Ґраніс Свіфтекс — дворфійський наставник воїнів, що перебуває в Ґуральні Тандербрю в Хараносі.",kw={"ґраніс свіфтекс","наставник воїнів","ґуральня тандербрю","харанос","дун мороґ","мурен стормпайк","воїн"},ang={["class:Warrior"]="Для бійців-дворфів і гномів, що покидають Долину Холодного Хребта, Ґраніс дає важливі перші бойові уроки — просто поруч зі свіжим кухлем у ґуральні.",["race:Dwarf"]="Утілюючи міцний і впертий дух піхотинців Айронфорджа, Ґраніс поєднує бойову дисципліну з утіхами місцевого елю."},sec={{t="Суворий наставник у Хараносі",b="Ґраніс Свіфтекс, що гріється серед барил Ґуральні Тандербрю, — головний бойовий наставник молодих воїнів, які мандрують Дун Мороґом. Він має непохитну гордість, властиву дворфійським бійцям, і відверто кепкує зі всіх, хто не воїн, але намагається привернути його увагу. Щойно учень доведе досить вправності в бою, Ґраніс посилає його гірською стежкою до Айронфорджа — шукати майстра-наставника Мурена Стормпайка у Військовому Кварталі."}},faq={{q="Хто такий Ґраніс Свіфтекс?",a="Ґраніс Свіфтекс — дворф, наставник воїнів, що стоїть на першому поверсі Ґуральні Тандербрю в Хараносі. Він навчає перших бойових прийомів молодих воїнів-дворфів і гномів, які мандрують Дун Мороґом.",al={"ґраніс свіфтекс","хто такий ґраніс","тренер воїнів харанос"}},{q="Чому Ґраніс глузує з мого персонажа?",a="Ґраніс не має терпцю до тих, хто не йде шляхом воїна. Якщо до нього заговорить шукач пригод іншого класу, він лише насміхається: мовляв, такий і дня не протримається під час його суворих тренувань.",al={"грубі слова ґраніса","чому ґраніс сміється наді мною","текст ґраніса для не воїнів"}},{q="Куди Ґраніс посилає воїнів, які зростають?",a="Коли воїн набереться досвіду в Дун Мороґу, Ґраніс радить йому знайти Мурена Стормпайка — старшого наставника воїнів у Військовому Кварталі Айронфорджа.",al={"завдання мюрена стормпайка","ланцюжок завдань ґраніса","до кого ґраніс посилає"}},{q="Чи Ґраніс родич інших Свіфтексів у Каз Модані?",a="He shares the Swiftaxe surname with other dwarves, but no family relationship is confirmed.",al={"рід свіфтекс","родичі ґраніса свіфтекса"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.91.0"}
P.entries["npc:great-father-winter"] = {n="Дід Зима",s="Дід Зима — літній орк, якого торгова компанія Пасовища Димолісся найняла зображати легендарного святкового героя в Оргріммарі. Під час Свята Зимової Завіси він сидить біля Фортеці Ґроммаш у Долині Сили, вислуховує побажання дітей і помітно втомлюється від комерційних веселощів. Навзамін за святкові подарунки й сезонні доручення він раз у раз просить перехожих принести імбирних пряників і крижаного молока.",h="Дід Зима — літній орк, якого торгова компанія Пасовища Димолісся найняла зображати легендарного святкового...",kw={"дід зима","зимова завіса","пасовища димолісся","долина сили","імбирні пряники","оргріммар"},ang={["faction:Horde"]="Він — головне сезонне обличчя свята для Орди в Оргріммарі: від імені Пасовищ Димолісся роздає святкові подарунки й доручення.",["profession:Cooking"]="Кухарі можуть спекти імбирні пряники за святковими рецептами й принести їх разом із молоком просто Дідові Зимі, щоб підбадьорити його.",["race:Orc"]="Хоч орки шанують зміну пір року й стихії, бачити одноплемінника в ролі костюмованого талісмана, що рекламує знижки торговців, — випробування для терпіння прихильників традицій."},sec={{t="Найнятий міф",b="Давні перекази розповідають про Діда Зиму як про величного духа стихій, що мандрує землею й приносить сніг та сезонне оновлення, але постать, яка сидить у Долині Сили, куди буденніша. Це орк-лицедій на платні в Пасовищ Димолісся, найнятий, щоб розкручувати торгівлю, рекламувати товари компанії й розважати молодь Орди. Критики бурчать, що цей комерційний талісман знецінює справжні сезонні традиції, але мало хто заперечить святкове пожвавлення, яке він приносить на вулиці міста."},{t="Зміна в Долині Сили",b="Просто біля Фортеці Ґроммаш, під гілками прикрашених ялин, цей дублер вистоює виснажливу зміну: діти дряпаються йому на коліна, щоб висловити свої вимоги щодо подарунків. Між рекламними вставками про знижки Пасовищ Димолісся й млявими святковими привітаннями його витривалість частенько згасає. Він відверто зізнається, що тримає в торбі пляшку святкового трунку, щоб заглушити гамір, щойно скінчиться зміна, і неабияк покладається на мандрівників, що приносять йому перекуси й підтримують його сили."}},faq={{q="Це справжній Дід Зима?",a="Ні. Це звичайний орк, якого найняли Пасовища Димолісся: він перевдягається, вдає легендарного героя Зимової Завіси й роздає святкові рекламні пропозиції в Оргріммарі.",al={"чи він справжній","хто такий дід зима","чи він актор"}},{q="Де знайти Діда Зиму в Оргріммарі?",a="Він у Долині Сили, просто біля входу до Фортеці Ґроммаш, поруч із ялинкою Свята Зимової Завіси та святковими ятками.",al={"місце діда зими","де дід зима","де знайти зимового орка"}},{q="Що він робить під час Свята Зимової Завіси?",a="Він розважає відвідувачів свята, вислуховує дитячі побажання щодо подарунків, роздає рекламні завдання Пасовищ Димолісся, а в розпал свята — подарунки під ялинкою.",al={"що робить дід зима","мета діда зими","завдання зимової завіси"}},{q="Навіщо йому імбирне печиво й молоко?",a="Гамірні натовпи й нескінченна черга дітей у нього на колінах за день геть виснажують. Тож він просить шукачів пригод принести свіжого імбирного печива й молока, щоб протриматися до кінця зміни.",al={"частування для діда зими","чому молоко й печиво","завдання з імбирним печивом"}},{q="Що він думає про свою роботу?",a="Ця вистава здається йому нудною й виснажливою. Він відкрито бурчить на надто завзятих дітлахів, абияк проказує завчені гасла компанії й нетерпляче рахує хвилини до того, як зможе приголубити пляшечку «святкового настрою», заховану в торбі.",al={"чи йому подобається робота","цитати діда зими","чи він п'яний"}},{q="Чи є подібний персонаж в Альянсу?",a="Так. В Альянсу є свій Дід Зима — літній дворф, найнятий Пасовищами Димолісся, що сидить біля святкової ялинки на Майдані Айронфорджа.",al={"дід зима альянсу","санта в айронфорджі","двійник з альянсу"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="Дід Зима",s="Дід Зима — легендарне уособлення зими й головна постать Свята Зимової Завіси. Давні перекази шанують його як міфічну істоту, що вкриває Азерот снігом, аби земля відпочила й оновилася, але сучасні містяни знають його передусім із комерційного видовища, яке влаштовують гобліни з Пасовищ Димолісся.",h="Дід Зима — легендарне уособлення зими й головна постать Свята Зимової Завіси.",kw={"дід зима","свято зимової завіси","пасовища димолісся","зима","свято","імбирне печиво"},ang={["profession:Cooking"]="Свято тримається на вправних кухарях, що печуть імбирне печиво та інші святкові ласощі для Пасовищ Димолісся й самого Діда Зими.",["race:Dwarf"]="Дворфи бачать у Дідові Зимі одну з подоб титанів, що вирізьбили світ, а засніжені вершини Дун Мороґа вважають живим свідченням його дотику."},sec={{t="Міф і оновлення",b="За давніми переказами, Дід Зима — безтілесний мандрівник, що наприкінці року обходить світ і розкидає над землею свій пишний сніжний плащ, щоб природа заснула й відродилася. Дворфи бачать у ньому втілення чи вісника титанів і вказують на вкриті інеєм скелі Дун Мороґа як на живий доказ його прихильності. Інші традиції, як-от у тауренів, шанують його роль у зміні пір року, але приписують холод і бурі стихійній праці Сонця й Місяця, що дають Земній Матері час відпочити. Куди б не мандрувала легенда, громади вчилися збиратися разом і бенкетувати наперекір холоду, святкуючи обіцянку, що життя повернеться."},{t="Пасовища Димолісся й міські гуляння",b="У великих поселеннях на кшталт Айронфорджа й Оргріммара давнього духа докорінно переробили заповзятливі гобліни з Пасовищ Димолісся. Цей торговий картель поширив образ Діда Зими як веселого старого в червоному вбранні й з білою бородою, що літає на санях і роздає святкові ласощі та іграшки. Пасовища Димолісся наймають місцевих акторів — дворфа в Айронфорджі й орка в Оргріммарі, — щоб ті вислуховували дитячі побажання, приймали дарунки з молока й імбирного печива та рекламували сезонні товари під розкішно прикрашеними ялинками."}},faq={{q="Дід Зима в Айронфорджі — це справжній дух?",a="Ні, Дід Зима, що сидить біля святкової ялинки в Айронфорджі, — актор, найнятий гоблінською торговою компанією «Пасовища Димолісся». Компанія влаштовує ці появи, щоб тішити дітей і продавати сезонні ласощі, хоча справжні легенди розповідають про безтілесну істоту, яка взимку ходить світом.",al={"чи дід зима справжній","хто цей в айронфорджі","чи він актор"}},{q="Чому дворфи шанують Діда Зиму?",a="Дворфи пов'язують Діда Зиму зі своїми творцями, титанами. Снігову ковдру, якою він укриває землю, вони вважають благословенням, а свою вічно скуту морозом батьківщину, Дун Мороґ, — найкращим доказом його прихильності.",al={"зимова завіса дворфів","дворфійський дід зима","дід зима айронфордж"}},{q="Що Дід Зима робить із печивом і молоком, які йому приносять?",a="Згідно зі святковими переказами, які поширили Пасовища Димолісся, Дід Зима любить поласувати святковим імбирним печивом і крижаним молоком, переглядаючи списки побажань і даруючи всім святковий настрій.",al={"частування для діда зими","чому молоко й печиво","завдання з імбирним печивом"}},{q="Як ставиться до Діда Зими Орда?",a="Орда долучається до свята здебільшого завдяки міській рекламній акції Пасовищ Димолісся в Оргріммарі, де Діда Зиму зображає орк. Таурени ж здавна вважають зиму важливою порою сну й оновлення стихій для Земної Матері; вони шанують роль Діда Зими в колообігу пір року, але не поклоняються титанам буквально.",al={"дід зима орди","дід зима оргріммар","зимова завіса таурени"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {n="Прамати Гоквінд",s="Прамати Гоквінд — шанована старійшина тауренів, що відпочиває біля водяної криниці на Плато Червоної Хмари. Мати ватажка Табору Нарачі, Вождя Гоквінда, вона попри поважний вік уособлює незламний дух і спільну відповідальність племені.",h="Прамати Гоквінд — шанована старійшина тауренів, що відпочиває біля водяної криниці на Плато Червоної Хмари.",kw={"прамати гоквінд","старійшина","вождь гоквінд","криниця","смирення","табір нарачі"},ang={["race:Tauren"]="Для молодих тауренів, що починають шлях на Плато Червоної Хмари, Прамати Гоквінд уособлює головні цінності Матері-Землі: шану до старійшин, єдність громади й смирення в служінні."},sec={{t="Старійшина плато",b="Прамати Гоквінд проводить дні біля криниці з прісною водою, що її має Табір Нарачі, і є духовною матріархинею для молодих тауренів, які починають обряди посвяти. Роки сповільнили її ходу, та вона не дозволяє вікові відсторонити її від обов'язку перед селищем. Вона вірить, що кожен член племені, молодий чи старий, має свою роль у підтримці громади, і часто просить молодь допомогти з простими домашніми справами — як-от принести свіжої води."},{t="Материнська настанова",b="Як мати Вождя Гоквінда, ватажка Табору Нарачі, Прамати Гоквінд дає сталу пораду й тиху гідність посеред загроз, що нависли над Плато Червоної Хмари. Поки її син збирає мисливців і воїнів проти шипогривів Щетиноспинних і місцевих хижаків, вона дбає про моральне серце поселення й нагадує щойно пробудженим: сила починається зі смирення й служіння своїм родичам."}},faq={{q="Хто така Прамати Гоквінд?",a="Прамати Гоквінд — літня тауренська матріарх, що живе в Таборі Нарачі на Плато Червоної Хмари. Вона мати вождя табору, Вождя Гоквінда, і мудра порадниця для молодих шукачів пригод.",al={"лор прамати гоквінд","хто така прамати гоквінд","старійшина табору нараче"}},{q="Де її знайти?",a="Вона сидить біля криниці на південний схід від Табору Нарачі, на Плато Червоної Хмари на південному заході Малгору.",al={"місце прамати гоквінд","де прамати гоквінд"}},{q="Які завдання вона дає молодим тауренам?",a="Вона доручає молодим тауренам «Скромне завдання» — набрати води з сільської криниці й рознести її іншим мешканцям табору. Ця робота вчить, що для справжнього слуги племені жодне доручення не буває принизливим.",al={"завдання прамати гоквінд","скромне завдання"}},{q="Ким вона доводиться Вождеві Гоквінду?",a="Вона мати Вождя Гоквінда, який відповідає за оборону Табору Нарачі й навчання молодих воїнів.",al={"мати вождя гоквінда","чи вона родичка вождя гоквінда"}}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="Ґрелін Вайтбірд",s="Ґрелін Вайтбірд — дворфський розвідник, якого королівським наказом відрядили до Долини Холодного Хребта оцінити загрозу від тролів Морозогривів. Він працює з відлюдного табору разом із недолугим учнем і покладається на молодих шукачів пригод, щоб стримувати тролів, поки увагу Айронфорджа цілком поглинула навала трогів.",h="Ґрелін Вайтбірд — дворфський розвідник, якого королівським наказом відрядили до Долини Холодного Хребта...",kw={"ґрелін вайтбірд","розвідник","долина холодного хребта","морозогриви","тролі","дун мороґ","щоденник"},ang={["faction:Alliance"]="Становище Ґреліна показує, як тонко розтягнуті сили Альянсу й Айронфорджа в Дун Мороґу: самотнім розвідникам доводиться вести тихі війни з тролячими анклавами.",["race:Dwarf"]="Служачи безпосередньо Королю Маґні, Ґрелін уособлює тиху вперту наполегливість розвідників Айронфорджа, які тримають кордони Дун Мороґу попри дедалі більші внутрішні загрози.",["race:Gnome"]="Гномські біженці, що тікають від трагедії Гномреґану через Долину Холодного Хребта, застають у віддаленому таборі Ґреліна гнома-мандрівника, який працює пліч-о-пліч з ним."},sec={{t="Королівське доручення",b="Ґреліна Вайтбірда та його брата Сеніра відрядили до Долини Холодного Хребта за прямим наказом Сенату Айронфорджа й самого Короля Маґні Бронзбірда. Завдання було чітке: оцінити й усунути загрозу від тутешніх тролів Морозогривів. Та оскільки регулярне військо Айронфорджа загрузло в боротьбі з трогами по всьому Дун Мороґу, братам дали геть мало засобів. Ґрелінові довелося розбити табір серед засніжених пагорбів і покладатися на місцевих добровольців та новачків, що проходили повз, аби виконати всю потрібну роботу."},{t="Клопоти на півдні",b="Зі свого табору Ґрелін стежить за племенем Морозогривів, що насувається з півдня Долини Холодного Хребта. Тролі стають дедалі зухвалішими й вилазять зі своїх гірських печер на все сміливіші набіги. Під час одного з них розмальований здоровань на ім'я Ґрік'нір Холодний прослизнув у покинутий без нагляду табір і поцупив польовий щоденник Ґреліна з його найважливішими спостереженнями. Не бажаючи підвести Короля, Ґрелін посилає відчайдушних мандрівників углиб печер Морозогривів, щоб повернути вкрадені записи й передати остаточний звіт Сенірові в Харанос."}},faq={{q="Що Ґрелін Вайтбірд робить тут, серед снігів?",a="Сенат Айронфорджа й Король Маґні Бронзбірд офіційно доручили Ґреліну розвідати й придушити загрозу від тролів Морозогривів у Долині Холодного Хребта. Оскільки дворфійське військо зайняте боротьбою з трогами деінде, Ґреліну доводиться покладатися на добровольців.",al={"чому ґрелін тут","мета ґреліна вайтбірда","хто такий ґрелін вайтбірд"}},{q="Хто вкрав щоденник Ґреліна?",a="Троль-морозогрив на ім'я Ґрік'нір Холодний напав на табір Ґреліна, поки той лишався без нагляду. Ґрелін устиг помітити лише здорованя з густими візерунками на тілі, який утікав із його польовими записами до південних тролячих печер.",al={"хто вкрав щоденник","злодій щоденника","щоденник ґреліна"}},{q="Хто брат Ґреліна?",a="Його брат — Сенір Вайтбірдий, розвідник, що служить нижче в горах, у містечку Харанос. Ґрелін зводить свої спостереження за пересуваннями тролів у звіти й передає їх Сенірові через надійних гінців.",al={"брат ґреліна","сенір вайтбірд","хто такий сенір"}},{q="Хто разом із Ґреліном у його таборі?",a="Ґрелін ділить свій невеликий табір із неуважним учнем-дворфом, тож, доки не прийдуть здібні новобранці, путньої допомоги він не має.",al={"табір вайтбірда нпс","хто з ґреліном","супутники ґреліна"}},{q="Чому Айронфордж не пришле йому на допомогу звичайних солдатів?",a="Захисники Айронфорджа й сили Сенату майже цілком зайняті боротьбою з трогами, що розплодилися по всьому Дун Мороґу. Тож розвідникам на кшталт Ґреліна доводиться долати місцеві загрози з допомогою місцевих новобранців.",al={"чому немає дворфійської армії","де варта айронфорджа","чому немає солдатів"}},{q="Що пов'язує Ґреліна з Джоною Айронсток?",a="Джона Айронсток — давній і надійний друг Ґреліна. Вона стоїть неподалік від місця, де новачки починають свій шлях у Долині Холодного Хребта, і направляє молодих дворфів і гномів до табору Ґреліна.",al={"ґрелін і джона","джона айронсток"}}},fp="17,309,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.146.0,56.221.0,46.184.0"}
P.entries["npc:greta-mosshoof"] = {n="Ґрета Моссгуф",s="Ґрета Моссгуф — тауренка-друїдка, союзниця Смарагдового Кола в Смарагдовому Святилищі на півдні Сквернолісся. Разом із нічними ельфами та іншими охоронцями природи вона досліджує мерзенну заразу, що розповзається давнім лісом, і спрямовує розвідників до Джеденару — твердині Ради Тіней.",h="Ґрета Моссгуф — тауренка-друїдка, союзниця Смарагдового Кола в Смарагдовому Святилищі на півдні Сквернолісся.",kw={"ґрета моссгуф","друїд","таурен","смарагдове святилище","рада тіней","джеденар","сквернолісся"},ang={["class:Druid"]="Для друїдів, що прагнуть загоїти шрами Палаючого Легіону, Ґрета Моссгуф уособлює дух співпраці Кола Кенарія, де заради відновлення дикої природи Калімдору відкладають фракційні зв'язки.",["race:Tauren"]="Ґрета показує відданість тауренів зціленню ран Земної Матері — навіть далеко на півночі, у землях, які колись охороняли лише нічні ельфи."},sec={{t="Охоронниця лісу",b="Ґрета Моссгуф, яка служить у Смарагдовому Святилищі на південному кордоні Сквернолісся, разом зі Смарагдовим Колом бореться зі всепроникною скверною, що поглинає давні ліси. Замість того щоб віддати сплюндровані землі демонічній заразі, яка лишилася після Третьої війни, вона координує зусилля, щоб зрозуміти й відтіснити гниль, що розповзається. Її розслідування зосереджені на отруєних водах Сквернолісся та мерзенних культистах, що заховалися в Джеденарі."},{t="Удар по Раді Тіней",b="Ґрета Моссгуф відіграє ключову роль у викритті підступів Ради Тіней, що діє з глибин Джеденару. Розуміючи, що осквернені джерела й мерзенні обереги в ущелині безпосередньо живлять недугу, яка душить землю, вона залучає мандрівників: узяти проби отруєних вод, звернутися по допомогу до шаманів, як-от Іслен Вотерсір на далекому узбережжі, і зруйнувати обрядові жаровні, що захищають демонічну кліку від вторгнення."}},faq={{q="Хто така Ґрета Моссгуф?",a="Ґрета Моссгуф — тауренка зі Смарагдового кола, що несе службу в Смарагдовому Святилищі в Скверноліссі. Вона допомагає мандрівникам і друїдам з'ясувати, звідки береться демонічна скверна, що отруює ліс, і позбутися її.",al={"лор ґрети моссгуф","хто така ґрета моссгуф","ґрета нпс"}},{q="До якої фракції належить Ґрета Моссгуф?",a="Ґрета Моссгуф належить до Смарагдового кола — нейтральної спільноти, що присвятила себе зціленню природи. Тому вона дає поради й завдання шукачам пригод і з Альянсу, і з Орди.",al={"чи ґрета з орди чи альянсу","репутація ґрети моссгуф","фракція ґрети"}},{q="Навіщо Ґрета посилає шукачів пригод до Джеденару?",a="Джеденар — твердиня Ради Тіней у Скверноліссі. Саме звідти в місцеві водойми закачують демонічну жовч і там підтримують захисні чари, під якими ховаються демони. Ґрета спрямовує удари по Джеденару, щоб зірвати їхні ритуали й очистити отруєні джерела.",al={"чому завдання джеденар","ґрета моссгуф джеденар","причина сил джеденару"}},{q="Що пов'язує Ґрету Моссгуф з Іслен Вотерсір?",a="Ґрета дружить з Іслен Вотерсір, мудрою шаманкою, що живе на узбережжі Пусток. Знайшовши в Скверноліссі зразки зіпсованої води, Ґрета посилає шукачів пригод до Іслен: її духовна майстерність допоможе очистити цю рідину, щоб нею можна було зцілити отруєні джерела.",al={"ґрета й іслен","зв'язок з іслен вотерсір"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {n="Ґріф Вайлдгарт",s="Ґріф Вайлдгарт — досвідчений дворфський наставник мисливців, що стоїть біля Ґуральні Тандербрю в Хараносі. Серед місцевих горян він славиться глибоким зв'язком із дикою природою і навчає молодих стрільців вистежувати здобич, влучно стріляти й приборкувати звірів. Для юних мисливців, що виходять із Долини Холодного Хребта, Ґріф — важлива ланка між першим пострілом з рушниці та вірним звіром поруч.",h="Ґріф Вайлдгарт — досвідчений дворфський наставник мисливців, що стоїть біля Ґуральні Тандербрю в Хараносі.",kw={"ґріф вайлдгарт","мисливець","наставник","приборкання звірів","харанос","дун мороґ"},ang={["class:Hunter"]="Ґріф — головний наставник, який долучає мисливців Альянсу до приборкання звірів, даючи вам важливі завдання, що дозволять зріднитися з дикими хижаками Дун Мороґу.",["faction:Alliance"]="Стоячи в Хараносі, Ґріф готує розвідників і стрільців Альянсу до виживання в суворій глушині навколо гірського королівства Айронфордж.",["race:Dwarf"]="Утілюючи традицію дворфських горян, Ґріф показує, як сувора витривалість дворфів робить їх напрочуд придатними до життя пліч-о-пліч із дикими гірськими звірами."},sec={{t="Життя серед дикої природи",b="Поки більшість дворфів Айронфорджа віддають перевагу вогняному теплу кузні чи розміреному дзенькоту кайл, Ґріф Вайлдгарт цілком присвятив своє життя морозній глушині Дун Мороґу. Місцеві горяни напівжартома кажуть, що він надто багато часу проводить із чотирилапими, але ніхто не заперечує його майстерності в дикій природі. Роками вистежуючи здобич на засніжених хребтах пліч-о-пліч із бувалими мисливськими супутниками, Ґріф досконало пізнав хижаків, які блукають тутешніми скелями."},{t="Шлях Звіра",b="Коли молоді дворфи-мисливці завершують перші випробування в Долині Холодного Хребта, їх одразу скеровують до Хараноса по настанови Ґріфа. Він вигострює їхню влучність і вчить виживати в глушині, та справжнє його покликання — ковати зв'язок між мисливцем і звіром. Через низку суворих випробувань Ґріф посилає учнів із жезлом приборкання в крижані пустки, щоб вони випробували себе на знакових хижаках Дун Мороґу: великих скельних вепрах, снігових леопардах та льодокігтих ведмедях."},{t="Шлях до Високого Престолу",b="Щойно мисливець доведе, що має волю й витримку приборкати трьох різних диких звірів, наука Ґріфа в Хараносі добігає кінця. Розуміючи, що мисливець має також навчитися годувати, виховувати й тренувати нового союзника, він відправляє випускників угору схилом до Айронфорджа. Там, під величними склепіннями дворфської столиці, мисливці-новачки звертаються до майстрів-звіролюбів, щоб опанувати глибше мистецтво догляду за своїм довічним супутником."}},faq={{q="Хто такий Ґріф Вайлдгарт?",a="Ґріф Вайлдгарт — дворф, наставник мисливців у Хараносі, що в Дун Мороґу. Він головний учитель для мисливців-новачків Альянсу, які опановують ремесло за межами Долини Холодного Хребта.",al={"хто такий ґріф","хто такий ґріф вайлдгарт","про ґріфа"}},{q="Де знайти Ґріфа Вайлдгарта?",a="Він стоїть надворі біля Ґуральні Тандербрю в селищі Харанос, на засніженій дорозі, що веде від Перевалу Холодного Кряжа до Айронфорджа.",al={"місце ґріфа вайлдгарта","де ґріф","ґріф у харанос"}},{q="Чого Ґріф навчає мисливців-новачків?",a="Окрім загальних мисливських умінь і прийомів бою на відстані, Ґріф проводить молодих мисливців через випробування з приручення звірів і вчить їх заспокоювати й підкоряти диких вепрів, леопардів і ведмедів.",al={"чого навчає ґріф","навчання мисливців ґріфа","навички ґріфа"}},{q="Яких звірів Ґріф посилає приручати?",a="Ґріф доручає учням вистежити й приручити трьох особливих тварин Дун Мороґу: Великого Скелястого Вепра, Снігового Леопарда й Ведмедя Крижаний Кіготь.",al={"завдання приборкання ґріфа","яких тварин приборкувати в дун мороґу","цілі приборкання звіра"}},{q="Куди Ґріф посилає мисливців після випробувань із приручення?",a="Коли мисливці доведуть, що вміють приручати диких тварин, Ґріф відправляє їх до Айронфорджа порадитися з досвідченими наставниками звірів про те, як годувати своїх улюбленців і командувати ними.",al={"куди після ґріфа","наступний крок приборкання","наступне завдання ґріфа"}},{q="Що думають про Ґріфа горяни Айронфорджа?",a="Місцеві горяни Айронфорджа зауважують, що Ґріф проводить забагато часу серед тварин, а не серед людей, але охоче визнають, що мисливське ремесло він знає краще за будь-кого.",al={"що горяни думають про ґріфа","чи ґріфа поважають","репутація ґріфа"}}},fp="14,424,19.495.0,20.507.0,24.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="Ґрімбуз Тандербрю",s="Ґрімбуз Тандербрю — дивакуватий дворф-пивовар із клану Тандербрю, що отаборився в Кинджальних Пагорбах Вестфолу. Він днями вигадує міцні трунки й розмовляє майже виключно віршами.",h="Ґрімбуз Тандербрю — дивакуватий дворф-пивовар із клану Тандербрю, що отаборився в Кинджальних Пагорбах...",kw={"ґрімбуз тандербрю","тандербрю","пивоваріння","кинджальні пагорби","дун мороґ","вестфол"},ang={["profession:Cooking"]="Кулінари й знавці міцних напоїв шанують спадщину Тандербрю, тож зустріч із Ґрімбузом — справжній урок майстерного пивоваріння.",["race:Dwarf"]="Кожен дворф знає ім'я Тандербрю, і натрапити на одного з найшанованіших старійшин цього роду, що варить шалені трунки на пагорбах Вестфолу, — приємний присмак рідного Дун Мороґу."},sec={{t="Пивовар у вигнанні",b="Ґрімбуз походить із прославленої пивоварської родини Тандербрю з Хараносу, але проміняв засніжені вершини Дун Мороґу на обвітрені пагорби Вестфолу. Відомий своєю веселою вдачею й незгасною пристрастю до міцних трунків, він має дивну звичку говорити лише римами — і відповідає на запитання мандрівника тільки тоді, коли той виконає для нього просте доручення. Мандрівники, що проходять небезпечними Кинджальними Пагорбами, можуть застати його біля власних бочок — він завжди радий випробувати смак спраглого гостя."}},faq={{q="Де знайти Ґрімбуза Тандербрю?",a="Ґрімбуз Тандербрю отаборився серед Кинджальних Пагорбів на півдні Вестфолу, разом зі своїм пивоварним знаряддям.",al={"місце ґрімбуза","де ґрімбуз","де знайти ґрімбуза тандербрю"}},{q="Чому Ґрімбуз говорить віршами?",a="Напевно цього ніхто не скаже. Ґрімбуз просто кохається в римах і наполягає, що кожен, хто має до нього запитання, спершу мусить виконати просте доручення.",al={"чому ґрімбуз римує","ґрімбуз віршами","чому він говорить віршами"}},{q="Що пов'язує його з Ґуральнею Тандербрю?",a="Ґрімбуз належить до славетного роду Тандербрю з Хараноса в Дун Мороґу. Поки його родичі, як-от Раґнар Тандербрю, доглядають родинну ґуральню вдома, Ґрімбуз варить своє пиво сам-один на пагорбах Вестфолу.",al={"ґуральня ґрімбуза","чи ґрімбуз родич рагнара","рід тандербрю"}}},fp="21,205,17.528.0,39.144.0,36.149.0,53.204.0"}
P.entries["npc:grish-longrunner"] = {n="Ґріш Лонґраннер",s="Ґріш Лонґраннер — тауренський розвідник і гонець, що стоїть на посту біля Великого Підйомника, важливої механічної переправи між південними Пустками й каньйонами Тисячі Голок. Служачи Орді на цьому жвавому кордоні, він наглядає за мандрівниками й узгоджує пересування військ на рубежі.",h="Ґріш Лонґраннер — тауренський розвідник і гонець, що стоїть на посту біля Великого Підйомника, важливої...",kw={"ґріш лонґраннер","великий підйомник","тисяча голок","таурени","розвідник","пустки"},ang={["faction:Horde"]="Для гінців і воїнів Орди, що прямують на південь до Тисячі Голок чи повертаються на північ у Пустки, Ґріш — важливий спостерігач і посередник біля підйомника.",["race:Tauren"]="Носячи горде ім'я Лонґраннерів, Ґріш уособлює витривалість і пильність шу'гало, які оберігають важливі шляхи на родових землях."},sec={{t="Вартовий біля підйомника",b="Ґріш Лонґраннер стоїть на варті просто біля височенних механізмів Великого Підйомника — одного з найхиткіших прикордонних переходів центрального Калімдору. Платформа-підйомник — рятівна нитка, що поєднує посушливі пустища південних Пусток із продутими вітрами столовими горами Тисячі Голок унизу. Через зграї шипогривів, що никають довкола, та інші загрози подорож цією вертикальною межею небезпечна, тож розвідники на кшталт Ґріша вкрай потрібні: вони тримають Орду в курсі подій і кличуть підкріплення туди, де його найбільше бракує."}},faq={{q="Хто такий Ґріш Лонґраннер?",a="Ґріш Лонґраннер — тауренський розвідник Орди, що несе службу на краю Великого Підйомника, який спускається з Пусток до Тисячі Голок.",al={"хто такий ґріш","хто такий ґріш лонґраннер","що робить ґріш"}},{q="Де знайти Ґріша Лонґраннера?",a="Він на півдні Пусток, просто біля механічного входу до Великого Підйомника, що веде вниз до Тисячі Голок.",al={"місце ґріша лонґраннера","де ґріш","знайти ґріша"}},{q="Яку роль він відіграє в цих краях?",a="Ґріш приймає посланців і мандрівників Орди, а ще допомагає збирати й спрямовувати місцеві підкріплення — зокрема в завданні «Виклик резервів».",al={"мета ґріша","завдання ґріша","завдання виклик резервів"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="Личинка",s="Личинка — заповзятливий орк, що живе в придорожній хатині трохи на схід від Перехрестя в Пустках. Він тримає скромну прикордонну харчевню разом із кухарем і пекарем і славиться — а може, сумно відомий — тим, що знайомить мандрівників із кулінарними можливостями місцевих гризунів.",h="Личинка — заповзятливий орк, що живе в придорожній хатині трохи на схід від Перехрестя в Пустках.",kw={"личинка","рагу з норової щурятини","норові щури","данґ","перехрестя","кулінарія"},ang={["faction:Horde"]="Придорожня кухня Личинки біля самого Перехрестя дає мандрівникам Орди ситну їжу й урок винахідливості для виживання на суворих рівнинах.",["profession:Cooking"]="Личинка — обов'язкова зупинка для кухарів-початківців на рубежі: він охоче ділиться рецептом Рагу з Норової Щурятини з кожним, хто наважиться зібрати складники."},sec={{t="Прикордонний апетит",b="Під скелями трохи на схід від Перехрестя Личинка доглядає просту оселю, яку ділить зі своїм кухарем Данґом і пекарем Тарбаном Гартґрейном. Життя на рівнинах вимагає міцного шлунка, але Личинка доводить прикордонну самодостатність до крайності. Замість того щоб дати пропасти численним норовим щурам Пусток, він зробив їх основним складником і охоче вчить мандрівників тушкувати цих підземних гризунів у смачне, хоч і непоказне, рагу."}},faq={{q="Хто такий Личинка?",a="Личинка — орк, що живе в хижі трохи на схід від Перехрестя в Пустках. Разом зі своїм кухарем Данґом і пекарем Тарбаном Гартґрейном він тримає невеликий заклад, де годують мандрівників, що проходять цим запиленим прикордонням.",al={"личинка","хто такий личинка","орк на схід від перехрестя"}},{q="Де знайти Личинку?",a="Личинка живе трохи на схід від Перехрестя, біля підніжжя гір у Пустках, у невеликій оселі осторонь головного шляху.",al={"місце личинки","де личинка","хатина личинки"}},{q="З чим Личинці потрібна допомога?",a="Личинка просить мандрівників наловити в Пустках норових щурів, з яких він варить своє фірмове Рагу з Норової Щурятини. Натомість він ділиться рецептом із кухарями, які захочуть його приготувати.",al={"завдання личинки","завдання рагу з щурів"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="Ґрулл Гоквінд",s="Ґрулл Гоквінд — молодий сміливець-таурен, що служить у Таборі Нарачі на Плато Червоної Хмари в Малгорі. Син Вождя Гоквінда, він допомагає вести новачків-тауренів, які роблять найперші кроки у світ. Він проводить молодих мисливців і воїнів крізь найперші випробування, щоб перевірити їхню рішучість і вшанувати предків.",h="Ґрулл Гоквінд — молодий сміливець-таурен, що служить у Таборі Нарачі на Плато Червоної Хмари в Малгорі.",kw={"ґрулл гоквінд","сміливець","вождь гоквінд","табір нарачі","випробування","мисливець","малгор"},ang={["class:Hunter"]="Ґрулл дає мисливцям-новачкам засадничі перші завдання, перевіряючи їхнє терпіння й уміння на звірині Малгору.",["race:Tauren"]="Для молодих тауренів, що виходять на Плато Червоної Хмари, Ґрулл Гоквінд часто стає найпершим сміливцем, який випробовує їхню доблесть і знайомить із традиціями шу'гало."},sec={{t="Син вождя",b="Гордо стоячи поруч зі сміливцями й старійшинами, яких зібрав Табір Нарачі, Ґрулл Гоквінд несе і гордий родовід Вождя Гоквінда, і відповідальність за підготовку молоді племені. Він — перший наставник для новоприбулих на Плато Червоної Хмари, який оцінює їхню готовність служити шу'гало. Даючи випробування на витривалість, слідопитство й виживання серед місцевих звірів — степових довгоступів і гірських пум, — Ґрулл дбає, щоб молоді таурени зрозуміли: рівновага й шана до природи — підвалини життя в Малгорі."}},faq={{q="Хто такий Ґрулл Гоквінд?",a="Ґрулл Гоквінд — таурен, що дає завдання в Таборі Нарачі на Плато Червоної Хмари. Він син Вождя Гоквінда, очільника поселення, і один із головних наставників для молодих тауренів, які тільки починають свій шлях.",al={"роль ґрулла гоквінда","хто такий ґрулл","лор ґрулла гоквінда"}},{q="Яку роль Ґрулл Гоквінд відіграє для молодих шукачів пригод?",a="Ґрулл перевіряє початковий вишкіл тауренів-новачків: приймає від старійшин племені рекомендаційні записки й дає молоді перші випробування з полювання та виживання на довколишніх рівнинах.",al={"завдання ґрулла","що робить ґрулл","мета ґрулла гоквінда"}},{q="Чи Ґрулл пов'язаний з очільниками табору?",a="Так, Ґрулл — син Вождя Гоквінда, очільника Табору Нарачі. Він шанує батькові традиції й допомагає готувати захисників табору.",al={"син вождя гоквінда","родина ґрулла гоквінда","чи ґрулл родич вождя"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {n="Піхотинець Доґран",s="Піхотинець Доґран — орк-вояк Орди, якого тримають у полоні глибоко на землях шипогривів у південних Пустках. Спершу його приписали до Перехрестя, згодом — до Табору Тауражо, але під час нападу на Аґама'ґор його дозор спіткала біда.",h="Піхотинець Доґран — орк-вояк Орди, якого тримають у полоні глибоко на землях шипогривів у південних Пустках.",kw={"піхотинець доґран","шипогриви","аґама'ґор","табір тауражо","перехрестя","полон"},ang={["faction:Horde"]="Його полон показує, якою високою ціною гарнізони Орди забезпечують торгові шляхи й кордони Пусток від войовничих племен шипогривів.",["race:Orc"]="Доґран утілює традиційний оркський ідеал: загинути в бою почесніше, ніж вижити безпорадним калікою."},sec={{t="Обов'язок піхотинця",b="Після підвищення у війську Орди Піхотинця Доґрана відрядили з Перехрестя посилити Табір Тауражо. Коли він повів загін піхотинців у наїжачені терени Аґама'ґора, його підрозділ зійшовся в запеклому бою з шипогривами племені Щетиноспинів. Тяжко пораненого й покаліченого в сутичці Доґрана товариші, відступаючи, не змогли винести, і його потягли в полон."},{t="Почесна доля",b="Хоч Доґран опинився в пастці за лінією ворога й покалічений ранами, він зберігає вперту гордість, притаманну оркським воїнам. Замість повернутися додому зламаним і змусити подругу доглядати каліку, він вирішив востаннє стати до бою проти шипогривів і просить лише одного — щоб знак його незмінної відданості повернули тій, яку він кохає."}},faq={{q="Де перебуває Піхотинець Доґран?",a="Доґран у полоні в Аґама'ґорі — густо заселеному таборі шипогривів на півдні Пусток, трохи на північ від Табору Тауражо.",al={"місце доґрана","де доґран","знайти доґрана в пустках"}},{q="Чому шипогриви захопили Доґрана в полон?",a="Доґран вів загін із Табору Тауражо в наліт на шипогривів і в сутичці дістав тяжкі каліцтва. Товариші не встигли винести його, і він опинився на милості цих звірів.",al={"чому доґрана взяли в полон","як доґран потрапив у полон"}},{q="Чому Доґран відмовляється від порятунку?",a="Доґран назавжди скалічений у бою і не хоче повертатися додому тягарем для своєї подруги. Як справжній орк, він воліє загинути по-своєму, у бою з шипогривами, ніж доживати віку калікою.",al={"чому доґран не йде","порятунок доґрана"}},{q="Хто шукає Доґрана?",a="Тривога через його зникнення здіймається на Перехресті й у Таборі Тауражо, де розвідники й солдати по крихтах з'ясовують, що сталося з його зниклим загоном.",al={"хто шукає доґрана","хто дає завдання про доґрана"}}},fp="12,236,14.400.0,17.335.1,30.126.0,40.210.0,37.209.1,26.153.0"}
P.entries["npc:grunt-logmar"] = {n="Піхотинець Лоґмар",s="Піхотинець Лоґмар — орк-воїн Орди, що служить у південних Пустках, у Таборі Тауражо. Сумлінний і пильний, він стежить за загрозами довкола табору й налагоджує пошуки та допомогу зниклим розвідникам Орди в краї.",h="Піхотинець Лоґмар — орк-воїн Орди, що служить у південних Пустках, у Таборі Тауражо.",kw={"піхотинець лоґмар","табір тауражо","орки","пустки","розвідники","шипогриви"},ang={["faction:Horde"]="Лоґмар уособлює військову присутність на передовій, що підтримує тауренів у Пустках, і покладається на поборників Орди, щоб дбати про полеглих і полонених розвідників.",["race:Orc"]="Як орк-піхотинець, що служить далеко від Оргріммара, Лоґмар показує відданість Орди тому, щоб стояти пліч-о-пліч із союзниками-тауренами."},sec={{t="Служба в Таборі Тауражо",b="Піхотинець Лоґмар служить серед тауренів у Таборі Тауражо пильним орком-вартовим на південному порубіжжі Пусток. Поселення лежить поруч із ворожими землями шипогривів і гірськими перевалами до Гір Кам'яного Кігтя й Малгору, тож пильнувати треба постійно. Лоґмар збирає донесення розвідників і звертається до вправних мандрівників з Орди, коли його товариші потрапляють у засідку чи в полон до місцевих ворогів."}},faq={{q="Хто такий Піхотинець Лоґмар?",a="Піхотинець Лоґмар — орк-солдат, що служить Орді в Таборі Тауражо на півдні Пусток: охороняє поселення й відповідає за рятувальні та розвідувальні доручення.",al={"піхотинець лоґмар","хто такий лоґмар","лоґмар пустки"}},{q="Де знайти Піхотинця Лоґмара?",a="Він у Таборі Тауражо — заставі на південних рівнинах Пусток, при дорозі до Великого Підйомника й Тисячі Голок.",al={"де лоґмар","місце лоґмара","знайти піхотинця лоґмара"}},{q="Якими справами опікується Лоґмар?",a="Лоґмар дбає про безпеку зниклих розвідників Орди: зокрема, доручає мандрівникам з'ясувати, як зник і потрапив у полон його товариш, піхотинець Доґран, а також роздобути важливі припаси на кшталт настою Кен'зіґли.",al={"завдання лоґмара","чого хоче лоґмар","порятунок доґрана"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Ґрант",s="Ґрант — непосидючий маленький сирота-орк, що живе під опікою сиротинця Оргріммара на Проході. Під час Тижня Дітей він радо вирушає з поборниками Орди у великі мандри Калімдором і Східними Королівствами, щоб дізнатися, що означає бути героєм.",h="Ґрант — непосидючий маленький сирота-орк, що живе під опікою сиротинця Оргріммара на Проході.",kw={"ґрант","сирота-орк","тиждень дітей","оргріммар","сиротинець","свисток сироти орків"},ang={["faction:Horde"]="Опікуючись Ґрантом під час Тижня Дітей, поборники Орди згадують, що саме вони боронять: нове покоління, народжене вільним, а не в демонічному рабстві.",["race:Orc"]="Ґрант утілює молодь Дуротару, що росте, знаючи племінну честь і боротьбу за виживання, а не темну млявість таборів для інтернованих."},sec={{t="Допитливе дитя Орди",b="Ґрант живе на Проході в Оргріммарі під пильним оком Матрони Сиротинця Баттлвейл і уособлює нове покоління щойно відродженої Орди. Як і багато юних зеленошкірих, що ростуть серед суворих червоних пусток Дуротару, він дивиться на закутих у броню шукачів пригод широко розплющеними очима й засипає їх нескінченними запитаннями: чи справді воїни в обладунках такі страшні, чому блискавка, влучивши у воду, не вбиває всієї риби і чи побачить він колись, як хтось б'ється зі справжнісіньким драконом."},{t="Мандри Тижня Дітей",b="Коли настає пора свята, шукачі пригод дмуть у Свисток Сироти Орків, щоб покликати Ґранта й узяти його в далеку подорож світом. Його список мрій охоплює всі володіння Орди: зустрітися з Верховним Вождем Кайрном Бладгуфом у Малгорі, пробратися до зруйнованої тронної зали Лордерону й навідатися на суворі кордони, де його народ бореться за своє майбутнє."}},faq={{q="Хто такий Ґрант?",a="Ґрант — орченя, що живе в сиротинці Оргріммара на Драґу. Про нього піклується Матрона Сиротинця Баттлвейл, а сам він мріє стати легендарним героєм Орди.",al={"ґрант нпс","орк сирота","сирота оргріммара"}},{q="Де знайти Ґранта?",a="Він живе разом з іншими сиротами на Драґу в Оргріммарі, але під час Тижня Дітей шукач пригод може покликати його будь-куди Свистком Сироти Орків, який дає Матрона Сиротинця Баттлвейл.",al={"місце ґранта","де ґрант","знайти ґранта"}},{q="Які місця хоче побачити Ґрант?",a="Ґрант мріє побачити найвідоміших героїв Орди. Він просить відвести його до Верховного Вождя Кайрна Бладгуфа в Тандер Блафі, показати йому пристань Раджета й навіть вирушити аж до зруйнованої тронної зали Лордерону.",al={"завдання ґранта","чого хоче сирота","екскурсія ґранта"}},{q="Яка вдача в Ґранта?",a="Ґрант галасливий, допитливий і має шалену уяву. Він раз у раз засипає шукачів пригод, які його доглядають, безглуздими загадками й дитячими запитаннями: що насправді означає «зуґ-зуґ», чи можна назвати муху без крил «ходухою», — а між іншим згадує, що запхав собі в носа камінчик.",al={"цитати ґранта","діалог ґранта","що каже ґрант"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {n="Ґраян Стаутмантл",s="Ґраян Стаутмантл — паладин Срібної Длані й командир Народного ополчення, що діє із Сентінел Гілла у Вестфолі. Уродженець Вестфолу, він повернувся зі спустошеного північного королівства Лордерон, щоб захистити рідний край, коли корона Стормвінда кинула його на поталу розбійникам.",h="Ґраян Стаутмантл — паладин Срібної Длані й командир Народного ополчення, що діє із Сентінел Гілла у Вестфолі.",kw={"ґраян стаутмантл","народне ополчення","сентінел гілл","вестфол","паладин","срібна длань"},ang={["class:Paladin"]="Стаутмантл — живий приклад обов'язку Срібної Длані: коли високі ради церкви й корони не помічали бідних, він приніс захист Світла просто тим скромним фермерам, яким він був найпотрібніший.",["faction:Alliance"]="Те, що Ґраян покладається на вільних добровольців, оголює гіркі тріщини в серці Альянсу, де політична бездіяльність Стормвінда змушує вірних громадян самим братися за зброю.",["race:Human"]="Уродженець Вестфолу, Ґраян уособлює стійкість сільського люду Стормвінда, що непохитно стоїть і проти місцевих розбійників, і проти бюрократичної байдужості столиці."},sec={{t="Лицар повертається додому",b="Ґраян Стаутмантл почав службу далеко від тихих нив південного Азероту. Юнаком він подався на північ, до Лордерону, склав обітниці Лицаря Срібної Длані й пережив жахи Третьої війни — навіть став свідком трагічної зачистки Стратгольма принцом Артасом Менетілом. Коли до нього дійшла звістка, що рідний Вестфол поринає в беззаконня, заполонений організованими розбійниками й покинутий короною, Ґраян залишив північні фронти. Він проміняв поля великих битв на оборону чесних фермерів, присягнувшись, що його дім не впаде так, як упала північ."},{t="Народне ополчення",b="Повернувшись, Ґраян побачив, що Вестфол майже беззахисний. Через королівську байдужість і політичний параліч у Домі Вельмож Стормвінд відмовився посилати гарнізонні війська. У відповідь Стаутмантл заснував у Сентінел Гіллі Народне ополчення, згуртувавши місцевих фермерів, вартових і мандрівних найманців у добровільний загін оборони. Його сили тримають хистку лінію проти Братства Дефіас, гнолів Річколапів і ворожих механоїдів і не можуть виділити підкріплення навіть тоді, коли сусідні поселення на кшталт Лейкшира благають про допомогу."},{t="Викриття ватажка",b="Не бажаючи воювати наосліп, Стаутмантл звернувся до розгалуженої мережі розвідників, щоб дізнатися, хто стоїть за руйнуванням Вестфолу. Нагадавши про старий борг тіньовому пройдисвітові Вайлі Чорному з Редріджу й порадившись із Матіасом Шоу з SI:7, Ґраян зірвав завісу: розбійників очолює Едвін Венкліф — скривджений майстер-архітектор Гільдії Каменярів. Коли ополченці схопили розбійника, що намагався пограбувати місцевий віз, Ґраян використав зрадника, щоб точно визначити штаб Братства, захований під Мунбруком у Мертвих Копальнях, і доручив досвідченим поборникам ударити просто по Венкліфу."}},faq={{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — паладин Срібної Длані, засновник і командир Народного ополчення, добровольчого гарнізону зі штабом у Сентінел Гіллі, що обороняє Вестфол.",al={"хто такий ґраян","лор стаутмантла","керівник вестфола"}},{q="Навіщо потрібне Народне ополчення, якщо Вестфол належить Стормвінду?",a="Дім Вельмож Стормвінда відмовився виділити королівських солдатів чи гроші зі скарбниці на захист віддаленої провінції. Покинуті напризволяще перед грабіжниками й гнолами, місцеві селяни під проводом Ґраяна створили власні сили оборони.",al={"навіщо ополчення","де армія стормвінда","чому стормвінд покинув вестфол"}},{q="Що пов'язує Ґраяна зі Срібною Дланню?",a="Замолоду Ґраян вирушив до Лордерону, щоб стати святим паладином Срібної Длані. Він бився на північних полях битв під час Третьої війни й був присутній під час очищення Стратгольма, а потім подався на південь рятувати свою батьківщину, якій загрожувала біда.",al={"ґраян паладин","ґраян срібна длань","ґраян у лордерон"}},{q="Чому Ґраян відмовляється надіслати допомогу Лейкширу?",a="Коли Магістрат Соломон із Лейкшира попросив підкріплення проти гнолів і орків Редріджу, Ґраянові довелося відмовити. Народне ополчення ледве втримує Сентінел Гілл, і якщо відрядити навіть невеликий загін, Вестфол упаде під натиском Дефіас.",al={"прохання магістрата соломона","допомога редріджу","чому немає військ для лейкшира"}},{q="Як Ґраян дізнався, де ховаються Дефіас?",a="Gryan calls on Wiley the Black and Mathias Shaw for intelligence, then asks adventurers to investigate the Brotherhood. The discoveries that follow are described in the spoiler section.",al={"пошук мертвих копалень","хто знайшов венкліфа","історія зрадника дефіас"}},{q="Ким Ґраянові доводиться Вайлі Чорний?",a="Вайлі Чорний — інформатор, що живе в корчмі Лейкшира й завдячує Ґраянові життям. Хоча Стаутмантл не надто симпатизує цьому розбійникові з сумнівною вдачею, він скористався цим боргом життя, щоб здобути важливі відомості про дії Дефіас.",al={"вайлі і ґраян","борг вайлі чорного"}}},fp="17,298,22.599.0,20.546.0,21.617.1,25.178.0,68.259.0,45.247.0,47.290.0,52.185.1,32.245.0"}
P.entries["npc:guard-berton"] = {n="Вартовий Бертон",s="Вартовий Бертон — міський вартовий-людина, що стоїть біля Корчми Лейкшира в Горах Редріджу. Розлючений бюрократичною тяганиною стормвіндського правосуддя, він прагне швидкої розплати з Тарґорром Жахливим, ув'язненим ватажком орків.",h="Вартовий Бертон — міський вартовий-людина, що стоїть біля Корчми Лейкшира в Горах Редріджу.",kw={"вартовий бертон","тарґорр жахливий","в'язниця стормвінда","корчма лейкшира","страта","лейкшир"},ang={["faction:Alliance"]="Бертон уособлює дедалі більше роздратування в сільських поселеннях Альянсу: місцеві захисники бачать, як центральна бюрократія Стормвінда зволікає з правосуддям, поки прикордонні містечка борються за виживання."},sec={{t="Вартовий, що жадає справедливості",b="Поки Гори Редріджу прогинаються під загрозою вторгнення орків Блекрок, Вартовий Бертон не покидає свого посту біля Корчми Лейкшира. Хоч місцева оборона ледве тримається, увага Бертона прикута до полоненого ворога — Тарґорра Жахливого. Тарґорра схопили й замкнули глибоко у В'язниці Стормвінда, засудивши до смерті за злочини проти королівства. Та страту в Стормвінді відкладають на невизначений час, і Бертон не хоче, щоб жорстокий грабіжник сидів у камері, поки Лейкшир спливає кров'ю. Взявши справу у свої руки, він наймає охочих шукачів пригод, щоб ті оминули королівську тяганину й самі стратили орка."}},faq={{q="Хто такий Вартовий Бертон?",a="Вартовий Бертон — вартовий Альянсу, що стоїть біля Корчми Лейкшира в Горах Редріджу. Найбільше він відомий тим, що наймає шукачів пригод, аби звершити правосуддя над сумнозвісним в'язнем-орком.",al={"бертон лейкшир","хто такий бертон"}},{q="Чому Вартовий Бертон хоче смерті Тарґорра Жахливого?",a="Тарґорра Жахливого засудили до страти за його злочини, але очільники Стормвінда відклали виконання вироку. Обурений цим зволіканням, поки Редрідж досі в облозі, Бертон влаштовує так, щоб Тарґорра знищили просто у В'язниці.",al={"чому вбити тарґорра","страта тарґорра","лор завдання що посієш"}},{q="Де тримають Тарґорра Жахливого?",a="Тарґорр сидить у В'язниці — суворо охоронюваному підземеллі у Кварталі Каналів Стормвінда.",al={"місце тарґорра","де тарґорр"}},{q="Де знайти Вартового Бертона?",a="Він вартує просто біля входу до Корчми Лейкшира, звідки видно центр Лейкшира в Редріджі.",al={"де бертон","місце бертона"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="Вартовий Гоу",s="Вартовий Гоу — міський вартовий, що стоїть біля південного підніжжя мосту Лейкширу в Горах Редріджу. Палаючи особистою жагою помсти оркам Блекрок, що підступають до долини, він платить нагороду кожному шукачеві пригод, готовому знищувати загарбників.",h="Вартовий Гоу — міський вартовий, що стоїть біля південного підніжжя мосту Лейкширу в Горах Редріджу.",kw={"вартовий гоу","блекрок","помста","нагорода","міст","лейкшир"},ang={["faction:Alliance"]="Лейкшир майже не отримує прямої допомоги від Стормвінда, тож вартові передової на кшталт Гоу покладаються на звитяжців Альянсу, щоб орки Блекрок не захопили містечко."},sec={{t="Затаєна образа на мосту",b="Стоячи одразу на південь від великого кам'яного мосту через Озеро Незрушне, Вартовий Гоу пильнує серце Лейкширу. Як і багато хто в обложеному містечку, він бачить в орках Блекрок, що підступають дедалі ближче, загрозу самому існуванню Редріджу. Плекаючи гірку жагу помсти цьому кланові, Гоу охоче наймає мандрівних найманців полювати на орків у східних пагорбах і платить за відчутні докази їхньої загибелі."}},faq={{q="Хто такий Вартовий Гоу?",a="Вартовий Гоу — людина, міський вартовий, що стоїть трохи на південь від мосту в Лейкширі, у Горах Редріджу. Він допомагає боронити поселення й спрямовує вмілих бійців у відплатні напади на орків Блекрок, що вдерлися в ці краї.",al={"вартовий гоу","гоу лейкшир","хто такий гоу"}},{q="Чому Вартовий Гоу хоче смерті орків Блекрок?",a="Гоу має особисті рахунки з кланом Блекрок, який глибоко вдерся в Гори Редріджу й не дає Лейкширу перепочинку. Він прагне помсти й платить винагороду кожному, хто прорідить їхні лави.",al={"чому нагорода за блекрок","гоу орки","чому гоу ненавидить орків"}},{q="Чи Вартовий Гоу родич когось іще в цьому краї?",a="Він має те саме прізвище, що й Соломан Гоу, тож вони, можливо, родичі, хоча сам вартовий думає лише про свої обов'язки: охорону міста й боротьбу з орками.",al={"родичі гоу","соломон гоу родич"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="Вартовий Томас",s="Вартовий Томас — відданий солдат армії Стормвінда, що стоїть біля мосту на захід від Лісозаготівельного Табору Східної Долини. Відрізаний на східному порубіжжі Лісу Елвінн, він керує обороною місцевих поселенців від хижої звірини та мурлоків, що насуваються.",h="Вартовий Томас — відданий солдат армії Стормвінда, що стоїть біля мосту на захід від Лісозаготівельного...",kw={"вартовий томас","вартовий","міст","східна долина","мурлоки","ліс елвінн","стормвінд"},ang={["class:Warrior"]="Для молодих воїнів Альянсу Томас — приклад дисципліни передової та непривабливої дійсності оборони кордонів краю.",["faction:Alliance"]="Вартовий Томас утілює перенапружений стан армії Стормвінда: він тримає важливу заставу на порубіжжі з мінімальною підтримкою від корони."},sec={{t="На східному кордоні",b="Поки увага королівства здебільшого звернена всередину, до столиці, або на захід, до Вестфолу, Вартовий Томас тримає один із найтихіших, але найхиткіших постів у Лісі Елвінн. Стоячи біля кам'яного мосту через річку в бік Лісозаготівельного Табору Східної Долини, Томас — тонка лінія оборони між простими лісорубами та войовничими створіннями, що блукають лісом. Оскільки військо Стормвінда розтягнуте до краю, вартовим на кшталт Томаса доводиться чимало покладатися на перехожих шукачів пригод, щоб підтримувати лад і передавати донесення до центрального командування."},{t="Клопоти порубіжжя",b="Східні околиці Елвінну зазнають невпинного тиску. Войовничі ведмеді та хижаки скрадаються узліссям, загрожуючи лісорубам і мандрівникам, а дивні племена мурлоків розбили табори вздовж водойм. Томас стежить за пересуванням цих водяних хижаків і призначає винагороди за їхнє винищення. Ще гірше: розвідувальні патрулі вздовж річки часом зникають безслідно, і Томасові доводиться самотужки з'ясовувати долю товаришів по варті посеред дедалі більшої нестабільності в краї."}},faq={{q="Де знайти Вартового Томаса?",a="Вартовий Томас стоїть на кам'яному мосту через річку, трохи на захід від Лісозаготівельного Табору Східної Долини, при східній дорозі в Лісі Елвінн.",al={"місце вартового томаса","де томас","вартовий томас міст"}},{q="Які обов'язки Вартового Томаса в Лісі Елвінн?",a="Він офіцер армії Стормвінда, якому доручено охороняти східне прикордоння Елвінна. Він стереже торговий міст, захищає робітників поблизу від хижаків і стежить, щоб вороже налаштовані мурлоки не просувалися вздовж берегів річки.",al={"що робить томас","роль вартового томаса","томас іствейл"}},{q="Чому Вартовий Томас просить допомогти знайти зниклих вартових?",a="Звичайні патрулі, вислані вздовж річкових долин, не повернулися зі звітами. Підкріплень, щоб залишити пост, у Томаса немає, тож він просить мандрівних шукачів пригод обшукати річки й з'ясувати, що сталося з його зниклими товаришами.",al={"зниклі вартові елвінн","зниклі розвідники томаса","що сталося з вартовими"}},{q="Чим мурлоки заважають Вартовому Томасу?",a="Племена мурлоків дедалі вище пробираються річками східного Елвінна. Їхня кількість зростає і загрожує і місцевим лісорубам, і суходільним шляхам постачання, тож Томас оголосив винагороду за їхні плавці, щоб очистити річки.",al={"мурлоки іствейл","чому вбивати мурлоків","нагорода за мурлоків"}},{q="Кому звітує Вартовий Томас?",a="Томас служить в армії Стормвінда й звітує за військовою ієрархією регіональному командуванню в Ґолдширі та в столиці. Коли на кордонах стає дедалі гірше, він погоджує свої донесення і з прикордонними очільниками, як-от Ґраяном Стаутмантлом у Вестфолі.",al={"начальник томаса","ланцюг командування армії стормвінда","на кого працює томас"}},{q="Куди Вартовий Томас посилає шукачів пригод, коли їхню роботу в Елвінні завершено?",a="Коли нагальні загрози довкола Східної Долини й на східній річці усунуто, Томас дає досвідченим мандрівникам донесення й направляє їх до Вестфолу на допомогу Ґраянові Стаутмантлу та Народному ополченню, якому ледве вдається триматися.",al={"після вартового томаса","куди йти після іствейла","звіт у вестфол"}}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gubber-blump"] = {n="Ґуббер Бламп",s="Ґуббер Бламп — дворф-рибалка й наставник, що працює на березі Обердайна на Темному Узбережжі. Він стоїть на піску між пристанню та майстром польотів і палко любить рибальське ремесло та морепродукти, особливо свіже крабове м'ясо.",h="Ґуббер Бламп — дворф-рибалка й наставник, що працює на березі Обердайна на Темному Узбережжі.",kw={"ґуббер бламп","рибальство","обердайн","краби","дворфи","темне узбережжя"},ang={["profession:Cooking"]="Ґуббер палко любить прибережну кухню, особливо свіже м'ясо рифових повзунів, тож для кухарів, що шукають інгредієнти у водах Темного Узбережжя, він — споріднена душа.",["race:Dwarf"]="Дворф, що щасливо осів на туманному березі Калімдору, а не в Каз Модані, — рідкісне видовище, хоча його відверті балачки про рідню доводять, що він не забув свого айронфордзького коріння."},sec={{t="Рибалка з Обердайна",b="Більшість дворфів почуваються затишно під камінням чи біля палаючого горна, а от Ґуббер Бламп віддає перевагу імлистим берегам Темного Узбережжя. Розташувавшись на пляжі Обердайна, між майстром польотів і поромною пристанню, Ґуббер навчає мистецтва рибальства й продає мандрівникам просту рибальську снасть. Він щиро цінує смак крабового м'яса, хоча часто покладається на шукачів пригод, щоб добути улов на небезпечному узбережжі, а також повернути дорогу серцю родинну снасть."},{t="Родинні зв'язки й морські послуги",b="Ґуббер охоче й відверто розповідає про свою родину, зокрема про кузена Ґрауна Блампа, в якого, за словами Ґуббера, є і борода, і незвичайний запах. Мандрівники, що допомагають йому з прибережними дорученнями — чи то приносять ноги повзунів, чи повертають родинну вудку, — часто отримують від Ґуббера щирого рукописного листа з подякою, зазвичай разом із блискучою блешнею, щоб наступні закидання були вдалими."}},faq={{q="Хто такий Ґуббер Бламп?",a="Ґуббер Бламп — дворф, наставник рибалок і торговець на березі в Обердайні, просто між сільською пристанню та наглядачем гіпогрифів.",al={"хто такий ґуббер бламп","ґуббер бламп нпс","де ґуббер бламп"}},{q="Чого навчає й що продає Ґуббер Бламп?",a="Він навчає новачків рибальства й торгує простим спорядженням для майбутніх рибалок, зокрема звичайними вудками й блискучими блешнями.",al={"що продає ґуббер","тренер ґуббер бламп","тренер рибальства темного узбережжя"}},{q="Які завдання дає Ґуббер Бламп?",a="Ґуббер просить мандрівників повернути його загублену родинну вудку й наловити на узбережжі добірного крабового м'яса — у завданнях «Родина і вудка» та «Дари моря».",al={"завдання ґуббера бламп","плід моря","родина й вудка"}},{q="Хто така Ґраун Бламп?",a="Ґраун Бламп — двоюрідна сестра Ґуббера, дворфійка. Ґуббер відверто зауважує, що в неї показна борода й доволі незвичний запах.",al={"ґраун бламп","кузен ґуббера бламп"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="Ґунтер Арканус",s="Ґунтер Арканус — надзвичайно могутній некромант, що живе на відлюдному острові посеред Озера Світлої Води. Убитий під час Третьої війни й воскреслий нежиттю, він зумів цілком самотужки розірвати ментальну хватку Короля-Ліча. Довго вважаючи себе єдиним мерцем із вільною волею, він боронив свій притулок від усіх чужинців, аж поки його не знайшли Відступники.",h="Ґунтер Арканус — надзвичайно могутній некромант, що живе на відлюдному острові посеред Озера Світлої Води.",kw={"ґунтер арканус","некромант","озеро світлої води","даларан","кірін-тор","бетор айсшард","король-ліч","відступники"},ang={["class:Mage"]="Навчений у Даларані, Ґунтер утілює тих чарівників Кірін-Тору, що потай бавилися забороненими некромантськими закляттями ще до вторгнення Погибелі в Лордерон.",["class:Warlock"]="Владне опанування Ґунтером темних мистецтв і воскрешення показує, як далеко могла зайти заборонена наука поза пильним оком керівництва Даларана.",["race:Undead"]="Самозвільнення Ґунтера робить його винятком серед Відступників: воно доводить, що лише напружене навчання таємним мистецтвам і залізна воля іноді могли розбити ментальне панування Короля-Ліча."},sec={{t="Учень Даларана",b="До падіння Лордерона Ґунтер був перспективним учнем Кірін-Тору в Даларані. Разом із близькими друзями Бетором Айсшардом і Тулом Рейвенкловом він вивчав таємні мистецтва й потай заглиблювався в некромантію попри сувору заборону Кірін-Тору на темну магію. На пам'ять про своє братерство троє друзів колись сплели свої учнівські жезли в єдину реліквію."},{t="Розірвані кайдани",b="Коли під час Третьої війни Погибель прокотилася північчю, Ґунтер загинув від Чуми Нежиті й був воскрешений для служби. На відміну від більшості, кому знадобилося послаблення влади Короля-Ліча або Леді Сильвана, щоб розірвати ланцюги, Ґунтер завдяки своїй могутній таємній майстерності й незламній волі сам, повністю, скинув ментальне панування Короля-Ліча. Переконаний, що кожен інший ходячий труп лишається безтямним рабом Погибелі, він усамітнився на острові в Галявинах Тірісфалю, оточив себе шкутильгаючими охоронцями й відрізав усі зв'язки і з живими, і з мертвими."},{t="Блудний ліч",b="Шукаючи могутніх союзників проти Погибелі, Відступники послали емісарів здобути книгу заклять таємничого некроманта. Вивчаючи таємничий фоліант в Андерсіті, Бетор Айсшард упізнав неповторний почерк давно втраченого товариша. Зачарувавши повернений гримуар і зажадавши знищення місцевих командирів Погибелі, Ґунтер нарешті збагнув, що не самотній у своїй свободі. Переконаний, що фракція Сильвани — справжнє повстання проти Погибелі, він уклав угоду з колишнім однокашником допомагати Відступникам."}},faq={{q="Хто такий Ґунтер Арканус?",a="Це колишній чарівник Кірін-Тору з Даларану, що загинув під час Третьої війни. Повернутий до нежиття, він сам вирвався з-під влади Короля-Ліча й усамітнився на острові посеред Озера Світлої Води в Галявинах Тірісфалю.",al={"хто такий ґунтер","лор ґунтера","історія ґунтера арканус"}},{q="Чому Ґунтер схожий на звичайного Відступника, а не на кістяного ліча?",a="Звичайні лічі переносять свої душі у філактерії й набувають жахливої ширяючої кістяної подоби. Ґунтер же досяг некромантичної сили, подібної до ліча, не покинувши свого первісного ожилого тіла, тож зберіг тілесний вигляд, який мав за життя.",al={"чому ґунтер схожий на людину","ґунтер не скелет","чому ґунтер ліч"}},{q="Чому Ґунтер жив сам на острові?",a="Вирвавшись з-під влади Короля-Ліча над розумом, Ґунтер вважав, що він єдина нежить у світі, яка має вільну волю. Гадаючи, що всі інші ходячі мерці досі бездумні раби Погибелі, він усамітнився й наказав своїм прислужникам убивати кожного, хто наблизиться.",al={"чому ґунтер сам","ізоляція ґунтера на острові","чому ґунтер ховається"}},{q="Звідки Ґунтер знає Бетора Айсшарда?",a="Вони разом навчалися в Даларані під проводом Кірін-Тору й були близькими друзями, а з ними й третій маг — Тул Рейвенклов. На знак своєї дружби троє друзів навіть сплели разом свої учнівські жезли.",al={"бетор і ґунтер","звідки ґунтер знає бетора","історія бетора айсшарда"}},{q="Чи приєднується Ґунтер до Відступників?",a="Так. Коли шукачі пригод повертають йому зачаровану книгу заклинань і стратять місцеву посланницю Погибелі Лілліт Нефару, довівши свою незалежність від Короля-Ліча, Ґунтер присягає на вірність Бетору й справі Відступників.",al={"чи ґунтер приєднається до орди","фракція ґунтера","чи ґунтер відступник"}},{q="Хто така Лілліт Нефара?",a="Лілліт Нефара — посланниця Погибелі в Галявинах Тірісфалю. Ґунтер вимагає її смерті як доказу, що шукач пригод справді служить ворогові Короля-Ліча, а не самій Погибелі.",al={"лілліт нефара","нефара","ціль ґунтера"}}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="Ґурда Рейджскар",s="Ґурда Рейджскар — оркиня, що служила на невеликій заставі Орди на південний захід від Застави Розщепленого Дерева в Ашенвалі. Разом із Фераном Стронґвіндом вона полягла, захищаючи свій табір від місцевих небезпек похмурого лісу.",h="Ґурда Рейджскар — оркиня, що служила на невеликій заставі Орди на південний захід від Застави Розщепленого...",kw={"ґурда рейджскар","феран стронґвінд","орда","застава розщепленого дерева","засідка","ашенваль"},ang={["faction:Horde"]="Знищений табір — сумне нагадування про високу ціну, яку платить Орда, щоб закріпитися у священних лісах Ашенвалю."},sec={{t="Знищена застава",b="Трохи на південний захід від укріплених мурів Застави Розщепленого Дерева, під густим пологом Ашенвалю, Ґурда Рейджскар тримала скромний табір Орди. Глибоко на землях, за які змагаються захисники нічних ельфів і дикі звірі, утримувати такі відлюдні позиції — небезпечна справа. Ґурду, Ферана Стронґвінда та їхній загін вартових зрештою розгромили й убили на посту, і перехожим союзникам лишилися тільки сліди їхнього останнього бою."},{t="Полеглі розвідники",b="Мандрівники, що проходять біля стежки, можуть натрапити на трагічне місце поразки Ґурди. Навіть після смерті речі й доручення, що лишилися в її таборі, підказують, чим займалася Орда в цих лісах, — серед них зниклі документи й накази, що їх зірвала засідка."}},faq={{q="Хто така Ґурда Рейджскар?",a="Ґурда Рейджскар — орчиха-розвідниця, що давала завдання в невеликому таборі трохи на південний захід від Застави Розщепленого Дерева в Ашенвалі й загинула насильницькою смертю разом зі своїми товаришами із застави.",al={"хто така ґурда","лор ґурди рейджскар"}},{q="Де знайти Ґурду Рейджскар?",a="Її тіло лежить у розгромленому таборі на південний захід від Застави Розщепленого Дерева, неподалік від дороги, що перетинає центральний Ашенваль.",al={"місце ґурди","де ґурда рейджскар"}},{q="Хто загинув разом із нею?",a="Вона полягла поруч із Фераном Стронґвіндом і їхньою охороною, коли на їхній невеликий табір напали.",al={"хто загинув із ґурдою","ферен стронґвінд"}},{q="Яке завдання пов'язане з Ґурдою Рейджскар?",a="Ґурда пов'язана із завданням «Загублені сторінки», у якому треба зібрати розкидані документи в нетрях Ашенвалю.",al={"завдання ґурди","загублені сторінки"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="Ґвенніт Блай'Леґґонд",s="Ґвенніт Блай'Леґґонд — нічна ельфійка з приморського порту Обердайн. Живучи на туманному Темному Узбережжі, вона стежить за припливами й посилає мандрівників дослідити дивні рештки, які викидає на берег. Її непокоять загадкові морські створіння й велетенські черепахи, чиї туші почали всіювати північні пляжі.",h="Ґвенніт Блай'Леґґонд — нічна ельфійка з приморського порту Обердайн.",kw={"ґвенніт блай'леґґонд","обердайн","морські черепахи","узбережжя","кістки","темне узбережжя"},ang={["class:Druid"]="Друїди, віддані збереженню природної гармонії Калімдору, побачать у звістках Ґвенніт про викинутих на берег морських створінь тривожну ознаку збурення прибережної природи.",["faction:Alliance"]="Обердайн — головний прибережний порт Альянсу на півночі Калімдору; уберегти його води й пляжі від прихованих загроз украй важливо для всіх союзних рас, що тут бувають.",["race:NightElf"]="Для калдореїв неприродна загибель великих морських звірів біля берегів Темного Узбережжя — тривожна ознака порушеної рівноваги на землях предків, тож варта Ґвенніт на березі особливо нагальна."},sec={{t="Та, що стежить за мінливими пісками",b="Ґвенніт Блай'Леґґонд живе в Обердайні, гамірному приморському прихистку Темного Узбережжя. Поки багато хто в містечку переймається лісом чи судноплавством через Приховане Море, Ґвенніт не зводить очей з узбережжя. Останнім часом припливи стали похмурими: вони викидають на берег рештки велетенських морських створінь. Щоб зрозуміти, що діється у водах біля берега, вона покладається на охочих шукачів пригод, які прочісують піски, збирають зразки кісток і приносять відповіді."},{t="Викинуті на берег велетні",b="На пляжах на північ і на південь від Обердайна тривожно побільшало викинутих на берег морських створінь і давніх морських черепах. Ґвенніт не дає їхній загибелі минути непоміченою й доручає мандрівникам оглядати цих полеглих велетнів. Вивчаючи кістки й з'ясовуючи, що вигнало звірів на берег чи відібрало в них життя, вона сподівається скласти докупи картину прихованих небезпек, що чатують біля берегів північного Калімдору."}},faq={{q="Хто така Ґвенніт Блай'Леґґонд?",a="Це нічна ельфійка з Обердайна на Темному Узбережжі, яка вивчає недавні порушення природної рівноваги на узбережжі. Вона просить мандрівників оглянути пляж і дослідити дивні речі, які викидає море.",al={"хто така ґвенніт","ґвенніт оберін","лор ґвенніт"}},{q="Де знайти Ґвенніт Блай'Леґґонд?",a="Вона в прибережному поселенні Обердайн, неподалік від пляжу й пристані на оповитому туманом узбережжі Темного Узбережжя.",al={"де ґвенніт","місце ґвенніт","знайти ґвенніт"}},{q="Чому її цікавлять викинуті на берег істоти?",a="Раптова загибель величезних морських черепах і загадкових морських велетнів, яких викидає на берег, свідчить про порушення рівноваги або про невидимого хижака у водах біля Темного Узбережжя. Ґвенніт прагне зрозуміти причину, вивчаючи рештки, знайдені вздовж узбережжя.",al={"чому викинуті черепахи","чому їй кістки","завдання викинуте на берег"}},{q="Які завдання дає Ґвенніт?",a="Вона дає шукачам пригод завдання «Викинуте на берег» і приймає різні знахідки, пов'язані з морськими істотами й черепахами, викинутими на береги Темного Узбережжя.",al={"завдання ґвенніт","що вона дає"}},{q="Вона з Кола Кенарія чи з Вартових?",a="Ні те, ні інше. Вона Жриця Місяця, що служить Сестрам Елуни в Обердайні, а не друїдка Кола Кенарія чи командирка Вартових, але, як і її родичі, глибоко дбає про здоров'я й рівновагу природи Темного Узбережжя.",al={"фракція ґвенніт","чи ґвенніт друїдка"}},{q="Що означає її ім'я?",a="Воно пасує до мелодійних імен калдореїв, але її незвичне прізвище «Блай'Леґґонд» — анаграма англійського «Leggy Blonde», тобто «довгонога білявка»: жартівливий штрих від творців світу.",al={"значення блай'леґґонд","пасхалка імені ґвенніт"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {n="Гаґар Лайтнінггуф",s="Гаґар Лайтнінггуф — розвідник-таурен, що несе варту високо на Заставі Вільного Вітру в Тисячі Голок. Почувши чутки про дивну кладку, заховану в глибинах каньйону, він береться розслідувати звістки про чужорідне яйце, яке люто стережуть місцеві вітряні змії.",h="Гаґар Лайтнінггуф — розвідник-таурен, що несе варту високо на Заставі Вільного Вітру в Тисячі Голок.",kw={"гаґар лайтнінггуф","арікара","чужорідне яйце","вітряні змії","застава вільного вітру","мотеґа фаєрмейн"},ang={["faction:Horde"]="Стоячи на варті високо над дном каньйону на Заставі Вільного Вітру, Гаґар покладається на вправних воїнів Орди, які наважаться вдертися в небезпечні лігва, куди звичайним розвідникам не пройти.",["race:Tauren"]="Для мандрівників-тауренів допомога Гаґарові приводить до хвилюючого відкриття: прадавні легенди про Арікару, крилате втілення помсти, — жива дійсність у каньйонах унизу."},sec={{t="Дивна кладка",b="Несучи службу серед високих круч Застави Вільного Вітру, Гаґар Лайтнінггуф почув чутки про неприродне яйце, заховане глибоко в печері внизу. Місцеві вітряні змії стерегли гніздо з незвичною лютістю й не підпускали цікавих розвідників. Розшукуючи сміливця, який наважиться вдертися до зміїного лігва, Гаґар сподівається власноруч вивчити зразок і збагнути, що це за звір, коли природні хижаки каньйону так завзято його оберігають."},{t="Легенда вилупилася",b="Коли шукач пригод нарешті здобуває яйце й приносить на Заставу Вільного Вітру, воно вилуплюється просто перед Гаґаром, і з нього з'являється молода вітряна зміїця, схожа на легендарну Арікару — шанований дух, якого перекази тауренів знають як утілення помсти. Усвідомивши, яке тяжке значення для культури й віри має повернення цієї істоти, Гаґар не гає часу й відсилає мандрівника порадитися зі старійшиною Мотеґою Фаєрмейном."}},faq={{q="Хто такий Гаґар Лайтнінггуф?",a="Гаґар Лайтнінггуф — таурен, що дає завдання на Заставі Вільного Вітру в Тисячі Голок. Він досліджує незвичайних тварин у каньйонах, особливо дивне яйце вітряного змія, про яке кажуть, що воно лежить глибоко в одній із сусідніх печер.",al={"хто такий гаґар","роль гаґара лайтнінггуфа","лор гаґара"}},{q="Де знайти Гаґара Лайтнінггуфа?",a="Він на вершині Застави Вільного Вітру — головної застави Орди, що височіє на велетенських кам'яних голках у центрі Тисячі Голок.",al={"де гаґар","місце гаґара лайтнінггуфа","гаґар вільний вітер"}},{q="Що це за «чуже яйце», яке шукає Гаґар?",a="Чуже яйце — незвичайне яйце, яке стережуть вітряні змії в підземному лігві. Гаґар просить шукачів пригод принести його, щоб він міг з'ясувати, що це таке.",al={"чуже яйце","що за яйце","яйце вітряного змія"}},{q="З ким Гаґар радиться щодо яйця?",a="Гаґар посилає шукача пригод до Мотеґи Фаєрмейна — старійшини Застави Вільного Вітру, який глибше розуміється на тауренських традиціях.",al={"кому здати дикого змія","наступне завдання гаґара","куди після гаґара"}}},fp="19,239,18.474.0,14.425.1,27.220.0,39.126.0,45.151.1,37.140.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Галаан Гок-Ай",s="Галаан Гок-Ай — дозорець із Небороджених на сторожовій вежі Села Тендаль на Острові Зефрас. Не маючи ні чуття до магії, ні містичного небозору, як його родичі, він покладається на гострий звичайний зір, щоб пильнувати острів довкола. Зі своєї вишки він стежить за далекими якірними пілонами й попереджає гостей, що їхня магічна стійкість слабне.",h="Галаан Гок-Ай — дозорець із Небороджених на сторожовій вежі Села Тендаль на Острові Зефрас.",kw={"галаан гок-ай","село тендаль","небороджені","небозір","якірні пілони","острів зефрас"},ang={["race:Skyborne"]="Галаан уособлює тих Небороджених, хто не має природного хисту до ліній сили чи небозору, — вони служать громаді непохитною пильністю й бойовим обов'язком."},sec={{t="Вартовий без магії",b="Високо над Селом Тендаль Галаан Гок-Ай служить своєму народові без дарів, звичних для багатьох Небороджених. Він не може черпати тайну силу з ліній сили, що течуть під Островом Зефрас, і не може зазирати між світами містичним небозором. Натомість Галаан цілком покладається на свої гострі природні чуття. Зі сторожової вежі він оглядає обрій, стежачи за якірними пілонами острова, і звертає увагу на їхню дедалі мінливішу й непевнішу чародійську силу."}},faq={{q="Хто такий Галаан Гок-Ай?",a="Галаан Гок-Ай — вартовий із Небороджених, що стоїть на сторожовій вежі над Селом Тендаль на Острові Зефрас. Він стежить за довколишніми землями й попереджає шукачів пригод про нестабільну магію, що вразила опорні пілони острова.",al={"галаан гок-ай","хто такий галаан","нпс вежі тендал"}},{q="Чим Галаан відрізняється від інших Небороджених?",a="На відміну від багатьох своїх родичів, Галаан не має ні містичного небесного зору, що проникає крізь завісу між світами, ні вродженого хисту черпати силу з підземних лей-ліній Острова Зефрас. Натомість він покладається на гострий звичайний зір і власну спостережливість.",al={"здібності галаана","чи галаан володіє магією","зір галаана"}},{q="Чому Галаана турбують опорні пілони?",a="Галаан стежить за далекими опорними пілонами й помітив, що їхня магічна сила стала нестабільною й мінливою, а це загрожує невідомо чим для стійкості Острова Зефрас.",al={"що не так з пілонами","проблема якорів зефраса"}},{q="Де знайти Галаана Гок-Ая?",a="Він стоїть на дерев'яній сторожовій вежі в Селі Тендаль на Острові Зефрас і вдивляється в обрій.",al={"де галаан","місце галаана"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hamhock"] = {n="Окіст",s="Окіст — велетенський двоголовий огр, ув'язнений у глибинах В'язниці Стормвінда. Замкнений під столицею разом із загартованими бунтарями Дефіас і головорізами, він — особливо жорстокий і несподіваний в'язень серед тюремного бунту.",h="Окіст — велетенський двоголовий огр, ув'язнений у глибинах В'язниці Стормвінда.",kw={"окіст","огр","двоголовий огр","в'язниця стормвінда","бунт"},ang={["class:Warrior"]="Щоб приборкати Окоста, доведеться зустріти грубу, громіздку силу лицем до лиця в тісних тюремних коридорах.",["faction:Alliance"]="Двоголовий огр, що вільно ходить просто під вулицями столиці, наочно показує, наскільки катастрофічно міська варта втратила контроль над В'язницею."},sec={{t="Громила за ґратами",b="В'язницю Стормвінда збудували для дрібних злодіїв, убивць і політичних бунтарів, тож височенний двоголовий огр серед камер — вражаюче видовище. Коли в'язні повстали й захопили в'язницю, Окіст закріпився посеред хаосу й розчавлює кожного, хто необачно вдереться до його блоку."},{t="Темне походження",b="Влада Стормвінда майже не оприлюднює записів про те, як Окіст потрапив за ґрати. Серед вартових і містян ходять чутки, що його притягли на північ із клану Скалкокулаків з Огрського Кургану Вул'Ґол у Сутінколіссі. Інші підозрюють, що його найняло Братство Дефіас як м'язисту силу, перш ніж він потрапив до рук міської варти."}},faq={{q="Хто такий Окіст?",a="Окіст — двоголовий огр-в'язень, особливо небезпечний супротивник, якого тримають у В'язниці Стормвінда. Під час заколоту, який підняли засуджені з Дефіас, він стає грізною перешкодою глибоко в коридорах в'язниці.",al={"окіст","хто огр у в'язниці","бос-огр в'язниці"}},{q="Як огр потрапив до В'язниці Стормвінда?",a="В офіційних записах про його арешт нічого не сказано, але здебільшого вважають, що він або полонений громило з клану Скалкокулаків, що живе в Сутінколіссі, або найманий вишибала Братства Дефіас, якого спіймали під час темних справ.",al={"чому окіст у в'язниці","як окіста спіймали","чому огр у в'язниці стормвінда"}},{q="Чи Окіст у змові з бунтівниками Дефіас?",a="Уся в'язниця повстала під проводом ватажків Дефіас, але незрозуміло, чи Окіст справді діє з ними заодно, чи просто втішається нестримним хаосом розбитих камер.",al={"чи окіст дефіас","окіст братство дефіас","чи окіст працює на базила"}},{q="Чи Окіст пов'язаний з ограми Сутінколісся?",a="Багато хто вважає, що він родом з Огрського Кургану Вул'Ґол у Сутінколіссі, тобто належав до клану Скалкокулаків на чолі із Ззарк'Вулом, перш ніж його схопили й привезли до Стормвінда.",al={"чи окіст сплінтер-фіст","окіст вул'ґол","огри вул'ґол у в'язниці"}},{q="Чи пов'язаний Окіст з якоюсь винагородою чи завданням?",a="За голову Окоста не оголошено ні офіційних винагород, ні міських ордерів. Він лише випадкова загроза, на яку шукачі пригод натрапляють, очищаючи охоплену бунтом в'язницю.",al={"завдання окіста","чи є завдання про окіста","нагорода за окіста"}},{q="Чим особливі двоголові огри?",a="У двоголових огрів кожна голова має власну вдачу, і вони часто хитріші або обдарованіші в магії, ніж їхні одноголові родичі. Тож для звичайних тюремних вартових Окіст надзвичайно небезпечний.",al={"двоголові огри лор","чому дві голови"}}},fp="7,255,19.324.0,13.366.0,15.192.0,49.243.0,42.197.0,44.185.0,48.179.0,37.209.0"}
P.entries["npc:hana-zua"] = {n="Гана'зуа",s="Гана'зуа — троль-розвідник Темного Списа в Долині Випробувань, що став жертвою отруйних звірів, які нишпорять гребенями каньйону. Уражений і поранений страхітливим скорпідом Саркотом, він лежить і чекає на допомогу молодих посвячуваних Орди, які прагнуть довести свою звитягу.",h="Гана'зуа — троль-розвідник Темного Списа в Долині Випробувань, що став жертвою отруйних звірів, які нишпорять...",kw={"гана'зуа","саркот","скорпід","троль","розвідник","долина випробувань","отрута"},ang={["faction:Horde"]="Виживання й помста Гана'зуа — одне з найперших випробувань вірності та бойової готовності для майбутніх чемпіонів Орди.",["race:Troll"]="Для посвячуваних Темного Списа, що тільки починають шлях у Дуроторі, зустріч із пораненим родичем підкреслює смертоносність тутешньої звірини й потребу захищати новознайдених союзників."},sec={{t="Розвідник, якого здолала отрута",b="Перетинаючи посушливі висоти над Долиною Випробувань, Гана'зуа натрапив на Саркота — надзвичайно лютого й отруйного скорпіда, що нишпорить скелями. Здоланий і вжалений звіром, троль ледве пережив сутичку. Не в змозі рухатися чи сам повернутися до табору, він знемагає в пилу, сподіваючись, що перехожі новобранці доб'ють створіння й передадуть звістку про його біду до Лігва."}},faq={{q="Хто такий Гана'зуа?",a="Гана'зуа — троль Темного Спису, якого знаходять пораненим у Долині Випробувань у Дуротарі. Коли він вистежував звірів на хребтах, на нього напали з засідки й отруїли.",al={"гана'зуа","хто такий гана'зуа","поранений троль долини випробувань"}},{q="Що сталося з Гана'зуа?",a="Його вразив Саркот — великий і смертоносний скорпід, що чатує на скелях над тренувальним майданчиком. Сильна отрута знесилила троля, і він не зміг сам дістатися безпечного місця.",al={"чому гана'зуа поранений","хто отруїв гана'зуа","поранення гана'зуа"}},{q="Про що він просить мандрівників?",a="Гана'зуа просить вправних шукачів пригод помститися за його рану: убити Саркота, принести клешню звіра як доказ і переказати наставникам у Лігві, у якому він стані.",al={"завдання гана'зуа","чого хоче гана'зуа"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Гендс Спрінґспрокет",s="Гендс Спрінґспрокет — працьовитий гном, що стоїть біля входу до Перевалу Холодного Кряжа в Дун Мороґу. Він узгоджує постачання між відлюдними навчальними угіддями Долини Холодного Хребта й містечком Харанос, хоча недавні набіги трогів добряче йому заважають.",h="Гендс Спрінґспрокет — працьовитий гном, що стоїть біля входу до Перевалу Холодного Кряжа в Дун Мороґу.",kw={"гендс спрінґспрокет","гном","постачання","перевал холодного кряжа","троги","харанос","долина холодного хребта"},ang={["faction:Alliance"]="Гендс підтримує рух життєво важливих внутрішніх ліній постачання між дворфійськими новобранцями в Долині Холодного Хребта й поселеннями в глибині Дун Мороґу.",["race:Gnome"]="Для гномів-біженців, переселених із Гномреґану, Гендс утілює тиху рішучість гномів, що вливаються в місцеву торгівлю й постачання Дун Мороґу пліч-о-пліч із дворфійськими союзниками."},sec={{t="Затор на перевалі",b="Біля гирла Перевалу Холодного Кряжа Гендс Спрінґспрокет бачить, що його звичні рейси з припасами геть зірвано. Зазвичай він доправляє харчі до ґуральні Тандербрю й корчми в Хараносі, але ворожі кам'янощелепі троги захопили підземний тунель, що веде з долини. Торгівля й пішохідний рух зупинилися через тварюк, тож Гендс змушений покладатися на вправних мандрівників, які пронесуть необхідні ящики небезпечним гірським коридором."}},faq={{q="Хто такий Гендс Спрінґспрокет?",a="Це гном Альянсу, що стоїть у Долині Холодного Хребта просто біля входу на Перевал Холодного Кряжа й відповідає за доставку припасів у нижні землі Дун Мороґу.",al={"хто такий гендс спрінґспрокет","лор гендса","хто цей гном"}},{q="Чому йому потрібна допомога з перевезенням припасів?",a="Перевал, що з'єднує Долину Холодного Хребта з рештою Дун Мороґу, заполонили люті троги Кам'янощелепих, тож звичайні перевезення без озброєного супроводу чи вправних шукачів пригод стали надто небезпечними.",al={"чому гендсу потрібна допомога","припаси перевалу колдрідж","чому застрягли припаси"}},{q="Куди везуть його припаси?",a="Він організовує постійні поставки до Хараноса, зокрема товари для Таннока Фростгаммера й місцевих корчмарів, які залежать від регулярних припасів із-за засніжених вершин.",al={"куди йдуть припаси","маршрут припасів гендса","хто отримає ящик"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="Гансель Гевіхендс",s="Гансель Гевіхендс — незвично величезний дворф Темного Заліза, що служить у Братстві Торію на Торієвому Мисі в Палючій Ущелині. Наглядачі застави доручають йому небезпечну роботу в полі, але він щоразу перекладає ризиковані справи на мандрівних шукачів пригод, відбуваючись барвистим набором дрібних тілесних нездужань. Його кремезна постать вирізняється навіть серед родичів, хоч запал до польової роботи аж ніяк не відповідає його розмірам.",h="Гансель Гевіхендс — незвично величезний дворф Темного Заліза, що служить у Братстві Торію на Торієвому Мисі в...",kw={"гансель гевіхендс","братство торію","торієвий мис","палюча ущелина","темне залізо","дворфи"},ang={["faction:Alliance"]="Хоч Альянс зазвичай воює з вірними Темному Залізу, Братство Торію радо приймає кожного, хто має міцну руку, — тож Гансель стане зручним джерелом місцевих завдань за винагороду.",["faction:Horde"]="Мандрівникам з Орди велетенська статура Ганселя нагадає орка чи таурена, хоча його небажання вступати в чесний бій, певно, змусить їх здивовано звести брови.",["race:Dwarf"]="Дворфи Бронзбірди й Вайлдгаммери можуть дивуватися — або глузувати — з велетенської статури Ганселя: як дворф Темного Заліза виріс таким велетнем, якщо цілими днями ухиляється від справжньої роботи?"},sec={{t="Велетень серед дворфів",b="Навіть за мірками широкоплечого клану Темного Заліза Гансель Гевіхендс — справжня аномалія. Він височіє над побратимами, а завширшки й заввишки мало не дорівнює оркові, — сама його постать наче створена для різанини на передовій. Та попри грізну статуру й не менш грізне прізвисько, Гансель, здається, зовсім не прагне зайвих фізичних зусиль і віддає перевагу відносній безпеці табору Братства Торію високо над вулканічним попелом."},{t="Майстер відмовок",b="Наглядач Скрейндж і Майстер-коваль Бурнінейт раз у раз доручають Гансельові похмуру роботу — винищувати вогняних звірів, що чатують у шлакових ямах унизу. Коли йому наказують розчистити Казан від хижих інцендозаврів, Гансель відмовляється, бо в нього, бачте, болять ноги. Коли ж велять винищити великих лавових павуків, що заполонили розпечені безплідні землі, він заявляє, що на цьому випаленому вулканічному хребті «холодний клімат», через який він тяжко застудився. Тож кожен найманець, готовий ризикнути серед потоків магми, знайде в Ганселя відкритий контракт."}},faq={{q="Хто такий Гансель Гевіхендс?",a="Гансель Гевіхендс — дворф Темного Заліза, що належить до Братства Торію. Він несе службу на Торієвому Мисі в Палючій Ущелині й відомий своїм разючим велетенським зростом і дивовижним хистом ухилятися від небезпечної роботи.",al={"хто такий гансель","лор ганселя гевіхендса","дворф гансель"}},{q="Чому Гансель набагато більший за інших дворфів?",a="Певного пояснення його статурі немає. Гансель просто незвичайно величезний дворф Темного Заліза — широкоплечий, з товстими руками й ногами, а на зріст майже як орк.",al={"чому гансель такий великий","величезний дворф палаючого ущелини","дворф розміром з орка"}},{q="Які завдання Гансель дає шукачам пригод?",a="Гансель наймає мандрівників виконувати доручення, які йому дає начальство. Зокрема, він платить найманцям за винищення великих лавових павуків у Палючій Ущелині та полювання на інцендозаврів глибоко в Казані.",al={"завдання ганселя гевіхендса","які завдання дає гансель"}},{q="Чому Гансель не виконує свою роботу сам?",a="Щойно запахне небезпекою, Гансель вигадує відмовки. До Казану битися з інцендозаврами він не піде, бо, мовляв, болять ноги, а коли йому наказують полювати на лавових павуків, скаржиться, що в розпеченій Палючій Ущелині так холодно, що можна застудитися.",al={"чому гансель не робить сам","відмовки ганселя"}},{q="Чи Гансель вірний імператорові Темного Заліза?",a="Гансель належить до Братства Торію — відступницької громади дворфів Темного Заліза, що відкололася від Імператора Даґрана Тауріссана й Рагнароса. До мандрівників і з Альянсу, і з Орди, які приходять на Торієвий Мис, він ставиться нейтрально.",al={"чи гансель вірний темному залізу","чи гансель ворог"}},{q="Де знайти Ганселя Гевіхендса?",a="Він на Торієвому Мисі — кам'янистій заставі на північному хребті, звідки видно всю Палючу Ущелину.",al={"місце ганселя","де гансель"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="Гарб Клогуф",s="Гарб Клогуф — таурен, що розводить їздових звірів одразу за Селом Бладгуф у Малгорі. Він доглядає міцних кодо племені й віддає їх гідним вершникам-тауренам і довіреним героям Тандер Блафу.",h="Гарб Клогуф — таурен, що розводить їздових звірів одразу за Селом Бладгуф у Малгорі.",kw={"гарб клогуф","кодо","їздові звірі","село бладгуф","тандер блаф","репутація"},ang={["faction:Horde"]="Для орків, тролів і Відступників отримати кодо від Гарба — найвищий знак честі й дружби, визнаний старійшинами Тандер Блафу.",["race:Tauren"]="Гарб Клогуф дає вам найхарактернішого скакуна вашої спадщини — і практичний транспорт через Малгор, і символ ваших кочових традицій."},sec={{t="Заводчик великих кодо",b="Гарб Клогуф, що влаштувався біля загонів Села Бладгуф, цілими днями доглядає велетенських кодо — опору тауренських мандрів і праці. Створені носити величезну вагу на великі відстані, ці міцні тварини неодмінні для життя на рівнинах. Гарб дбає, щоб кожен звір був доглянутий, вишколений і дістався лише тим вершникам, яких шанує народ тауренів."},{t="Скакуни рівнин",b="Таурени природно здобувають довіру, потрібну, щоб їздити на кодо Гарба, а от чужинців перевіряють суворіше. Через величезний розмір і норов кодо нелегко слухаються тих, хто не знайомий із їхньою вдачею. Союзники не з тауренів, що хочуть поїхати на одному з цінних скакунів Гарба, мусять спершу довести свою вірність і здобути звеличену репутацію в Тандер Блафі."}},faq={{q="Де знайти Гарба Клогуфа?",a="Гарб Клогуф стоїть біля загону для кодо на околиці Села Бладгуф у центрі Малгору, трохи на південь від Тандер Блафа.",al={"місце гарба клогуфа","де гарб клогуф","де торговець кодо"}},{q="Що продає Гарб Клогуф?",a="Гарб продає різних їздових кодо: звичайних бурих і сірих, а також важкоброньованих великих кодо для досвідчених вершників.",al={"що продає гарб","гарб їздові кодо","товари торговця кодо"}},{q="Чи можуть не таурени купити кодо в Гарба?",a="Так, але лише якщо здобули звеличення в Тандер Блафі. Таурени можуть купити їх одразу, а іншим народам Орди треба спершу довести племені свою вірність, і лише тоді Гарб довірить їм кодо.",al={"чи можуть орки купити кодо","чи можуть тролі їздити на кодо","вимога репутації для кодо"}},{q="Чому кодо такі важливі для тауренів?",a="Кодо — могутні й витривалі тварини, створені для кочового життя на відкритих рівнинах центрального Калімдору. Вони незамінні як в'ючні тварини, бойові скакуни й торговий транспорт на цих суворих просторах.",al={"лор кодо тауренів","чому кодо"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Гаркен Віндтотем",s="Гаркен Віндтотем — мисливець-таурен, що мешкає в Селі Бладгуф у Малгорі. Відданий традиціям свого народу, він доручає молодим мисливцям і мандрівникам довести свої вміння слідопита й збирача на золотих рівнинах.",h="Гаркен Віндтотем — мисливець-таурен, що мешкає в Селі Бладгуф у Малгорі.",kw={"гаркен віндтотем","мисливець","стрімкокрили","пера","село бладгуф","малгор"},ang={["class:Hunter"]="Для слідопитів, що проходять через Село Бладгуф, завдання Гаркена збити крилатих стрімкокрилів — важлива рання перевірка влучності й збирання здобичі.",["race:Tauren"]="Гаркен Віндтотем уособлює прабатьківську мисливську філософію тауренів: доводити дисципліну й самостійність на рівнинах, шануючи звірів Матері-Землі."},sec={{t="Мисливець Бладгуфа",b="Гаркен Віндтотем, що оселився біля самого серця Села Бладгуф, — наставник і провідник для тих, хто вчиться мисливських звичаїв тауренів. Життя на рівнинах Малгору вимагає шани до світу природи поряд із практичним умінням годувати своє плем'я. Гаркен оцінює молодих шукачів пригод, посилаючи їх полювати на тутешніх стрімкокрилів, що кружляють над плато, і збирати їхні пера — так він зважує терпіння мисливця, його влучність і вміння брати здобич без марнотратства."}},faq={{q="Хто такий Гаркен Віндтотем?",a="Гаркен — таурен-мисливець, що живе в Селі Бладгуф у центрі Малгору. Він навчає мандрівників і молодих шукачів пригод основ тауренських звичаїв вистежування й полювання.",al={"лор гаркена віндтотема","хто такий гаркен"}},{q="Де знайти Гаркена Віндтотема?",a="Гаркен у Селі Бладгуф — поселенні на південь від Тандер Блафа, у центрі Малгору.",al={"місце гаркена","де гаркен віндтотем"}},{q="Які завдання Гаркен дає шукачам пригод?",a="Він дає завдання «Полювання на стрімкокрилів»: просить мисливців вирушити в степи Малгору, вполювати диких стрімкокрилів і зібрати їхні міцні махові пера.",al={"завдання гаркена віндтотема","завдання полювання на стрибунів"}},{q="Чи Гаркен родич Бована Віндтотема?",a="Обидва належать до роду Віндтотемів, тож, певно, їх пов'язує спорідненість у племені чи в родині, хоча Гаркен зосереджений на полюваннях довкола свого села в Малгорі.",al={"чи гаркен родич бована","бован віндтотем родич"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="Гарлан Беґлі",s="Гарлан Беґлі — броняр і купець із людей, що торгує у Збройні «Левове Серце» в жвавому Торговому Кварталі Стормвінда. Він тримає крамницю на північному боці центру кварталу й дбає про зброю та спорядження для містян і заїжджих шукачів пригод.",h="Гарлан Беґлі — броняр і купець із людей, що торгує у Збройні «Левове Серце» в жвавому Торговому Кварталі...",kw={"гарлан беґлі","левове серце","збройня","торговий квартал","броня","стормвінд"},ang={["faction:Alliance"]="Купці на кшталт Гарлана Беґлі забезпечують головну столицю Альянсу спорядженням і товарами, поки звичним шляхам постачання загрожують небезпеки в довколишніх землях."},sec={{t="Збройня «Левове Серце»",b="Збройня «Левове Серце», що стоїть на північному боці Торгового Кварталу, — незмінна торгова окраса самого серця Стормвінда. З-за свого прилавка Гарлан Беґлі веде облік товару й торгує захисним спорядженням, покладаючись на поставки й місцевих гінців, щоб полиці не порожніли, поки столиця потерпає від далеких прикордонних конфліктів і перебоїв із постачанням."}},faq={{q="Хто такий Гарлан Беґлі?",a="Гарлан Беґлі — крамар і торговець, людина, що тримає «Лев'яче Серце» — крамницю спорядження в Торговому Кварталі Стормвінда.",al={"хто такий гарлан","лор гарлана беґлі","торговець збройовою левиного серця"}},{q="Де знайти Гарлана Беґлі?",a="Він у крамниці «Лев'яче Серце» на північному боці центральної площі Торгового Кварталу Стормвінда.",al={"місце гарлана беґлі","де гарлан","збройова левиного серця"}},{q="Яку роль він відіграє в торгівлі Стормвінда?",a="Як місцевий торговець у столиці королівства, Беґлі постачає обладунки й спорядження, а часом наймає шукачів пригод доставляти замовлення й супроводжувати вантажі, без яких його крамниці не втриматися.",al={"що продає гарлан","бізнес гарлана беґлі"}}},fp="13,269,20.388.0,21.147.0,31.120.0,47.199.0"}
P.entries["npc:harlo-barnaby"] = {n="Гарло Барнабі",s="Гарло Барнабі — поранений біженець-дворф, що живе в Гавані Менетіл. Ледве вирвавшись із різанини, коли клан Темного Заліза захопив Дун Модр, він тепер розповідає мандрівникам про трагедію, що сталася на північних болотах.",h="Гарло Барнабі — поранений біженець-дворф, що живе в Гавані Менетіл.",kw={"гарло барнабі","дун модр","темне залізо","гавань менетіл","біженці","багнокрай"},ang={["faction:Alliance"]="Падіння Дун Модра загрожує важливому суходільному перешийку між болотами й Араті, тож попередження Гарло життєво важливі для сил Альянсу.",["race:Dwarf"]="Гарло — живе нагадування про затяжну й криваву війну кланів із підступним Темним Залізом, яке прагне відрізати Каз Модан від півночі."},sec={{t="Втеча з Дун Модра",b="Гарло Барнабі жив у Дун Модрі, доки ця північна твердиня не впала під раптовим, лютим нападом дворфів Темного Заліза. У метушні засідки Гарло втік на південь, до безпеки, та дістав випадковою сокирою просто в спину. Удар збив його з пам'яті, але він якимось дивом пережив дорогу через болота й прокинувся перебинтованим у Гавані Менетіл. Хоч він і живий, рани та спогади про різанину не дають йому повернутися, тож він закликає шукачів пригод з Альянсу розвідати димні руїни його колишнього дому."}},faq={{q="Хто такий Гарло Барнабі?",a="Гарло Барнабі — дворф з Айронфорджа, що живе в Гавані Менетіл. Він пережив жорстокий напад дворфів Темного Заліза на заставу Дун Модр.",al={"гарло барнабі","хто такий гарло","дворф з гавані менетіл"}},{q="Як Гарло Барнабі опинився в Гавані Менетіл?",a="Коли він тікав від нападників із Дун Модра, йому в спину влучила метальна сокира. Під час відступу він знепритомнів і прокинувся вже в безпеці, у Гавані Менетіл, під наглядом місцевих цілителів.",al={"як гарло потрапив сюди","травма спини гарла барнабі"}},{q="Що сталося з Дун Модром?",a="Дун Модр захопили й сплюндрували ворожі дворфи Темного Заліза, що наступали на південь від Мосту Тандол: вони перебили місцевих захисників-дворфів, а тих, хто вцілів, вигнали в болота.",al={"падіння дун модра","що сталося в дун модрі"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Геґнар Рамблшот",s="Геґнар Рамблшот — дворфійський зброяр, що стоїть біля засніженої дороги від Перевалу Холодного Кряжа до Хараноса. Він тримає жвавий тир і споряджає місцевих мисливців та горян вогнепальною зброєю й набоями.",h="Геґнар Рамблшот — дворфійський зброяр, що стоїть біля засніженої дороги від Перевалу Холодного Кряжа до...",kw={"геґнар рамблшот","зброяр","тир","набої","вогнепальна зброя","лослор радж","харанос"},ang={["class:Hunter"]="Для стрільців, що вирушають із Долини Холодного Хребта до ширших засніжених вершин Дун Мороґу, Геґнар постачає необхідний шріт, сумки для набоїв і запасну вогнепальну зброю.",["race:Dwarf"]="Дворфи пишаються майстерністю й влучністю, тож придорожній тир Геґнара — природне місце зустрічі для мандрівників, які хочуть перевірити свій спуск."},sec={{t="Зброяр при дорозі",b="У невеликому таборі між Перевалом Холодного Кряжа й Хараносом Геґнар Рамблшот обслуговує дворфійських стрільців, мандрівників і місцеве ополчення. У його таборі є популярний тир, де гірський люд відточує влучність проти диких звірів, що никають Дун Мороґом. Постачати стількох завзятих стрільців означає, що Геґнар жваво витрачає набої, тож він постійно залежить від свіжих партій боєприпасів від свого постачальника, дворфа-інженера Лослора Раджа."}},faq={{q="Хто такий Геґнар Рамблшот?",a="Геґнар Рамблшот — дворф-зброяр, що тримає стрільбище під відкритим небом і табір при головній дорозі між Перевалом Холодного Кряжа й Хараносом.",al={"хто такий геґнар","геґнар рамблшот нпс","зброяр у дун мороґу"}},{q="Де Геґнар бере набої?",a="Геґнар покладається на Лослора Раджа, дворфа-постачальника інженерного приладдя з іншого куточка Дун Мороґу, який виготовляє й постачає набої, щоб стрільбище могло працювати.",al={"постачальник геґнара","хто постачає рамблшота","завдання набоїв для рамблшота"}},{q="Що Геґнар робить для місцевих дворфів?",a="Він забезпечує місцевих мисливців і ополченців вогнепальною зброєю та набоями, а влучним стрільцям, що мандрують Дун Мороґом, дає змогу повправлятися на стрільбищі.",al={"чому геґнар тут","стрільбище геґнара","роль рамблшота"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Гензе Фолк",s="Гензе Фолк — дворф-шукач пригод, що лежить при смерті на кам'яному колі біля Дозору Героїв у Лісі Елвінн. Повалений Братством Дефіас, коли затуляв собою товариша, він стає ключовим випробуванням для майбутніх паладинів, що вчаться володіти даром воскресіння.",h="Гензе Фолк — дворф-шукач пригод, що лежить при смерті на кам'яному колі біля Дозору Героїв у Лісі Елвінн.",kw={"гензе фолк","дворф","дозор героїв","паладин","символ життя","воскресіння"},ang={["class:Paladin"]="Гензе Фолк — ваше перше справжнє випробування божественного милосердя. Повернути його з-за межі Символом Життя — означає зрозуміти, що Світло — не просто зброя для бою, а урочиста сила, здатна кинути виклик смерті.",["race:Dwarf"]="Бачити побратима-дворфа поваленим на людських землях — тверезе нагадування, що розбійники Дефіас смертельно небезпечні для подорожніх усіх рас, а не лише для мешканців Стормвінда."},sec={{t="Жертва біля Дозору Героїв",b="Біля давнього кам'яного кола на схід від Стормвінда лежить Дозор Героїв — місце, яке часто навідують бандити Дефіас, що нишпорять лісами Елвінну. Гензе Фолк і його друг Ґазин Тенорм потрапили тут у засідку мародерів Дефіас. Ставши під удар, щоб Ґазин вижив, Гензе впав від клинків бандитів. Його товариш уцілів і покликав на поміч із Собору Світла, а тіло Гензе лишилося на порозі між життям і смертю, чекаючи божественного втручання паладина із Символом Життя."}},faq={{q="Хто такий Гензе Фолк?",a="Гензе Фолк — дворф з Айронфорджа, якого знаходять смертельно пораненим біля кам'яного кола неподалік Дозору Героїв у Лісі Елвінн. На нього напали з засідки й повалили бандити Дефіас, коли він рятував свого друга Ґазина Тенорма.",al={"гензе фолк","дворф біля вартової героїв","вмираючий дворф елвінн"}},{q="Чому Гензе Фолк лежить на землі?",a="На Гензе напало Братство Дефіас, коли він мандрував разом із Ґазином Тенормом. Він прийняв на себе основний удар, щоб Ґазин зміг утекти, і тепер лежить смертельно поранений, чекаючи, доки його воскресить послушник Святого Світла.",al={"чому гензе помирає","чи гензе мертвий","гензе фолк мертвий"}},{q="Що пов'язує Гензе з паладинами?",a="Гензе — головна постать обряду посвяти для молодих паладинів, які проходять випробування Фоліанту Божественності. Паладинам-послушникам довіряють Символ Життя й посилають до Елвінна повернути Гензе з того світу — так вони доводять, що опанували найсвятіше благословення Світла, воскресіння.",al={"завдання паладина гензе","дворф том божественності"}},{q="Хто такий Ґазин Тенорм?",a="Ґазин Тенорм — супутник Гензе Фолка. Коли розбійники Дефіас загнали їх у пастку, Гензе затулив собою Ґазина, і той вижив і зміг попросити допомоги в Церкви Святого Світла.",al={"хто такий ґазин","друг ґазина тенорма"}}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:heralath-fallowbrook"] = {n="Гералат Фелловбрук",s="Гералат Фелловбрук — нічний ельф-друїд при смерті, ув'язнений глибоко в Рейзорфен Краулі. Його послали розслідувати колюче зіпсуття довкола решток Древнього Аґамаґґана, але плем'я Рейзорфен схопило його й жорстоко скатувало. На останньому подиху він прагне передати звістку про свою долю й дорогий серцю амулет дружині в Дарнасус.",h="Гералат Фелловбрук — нічний ельф-друїд при смерті, ув'язнений глибоко в Рейзорфен Краулі.",kw={"гералат фелловбрук","друїд","рейзорфен краул","аґамаґґан","шипогриви","дарнасус","лоунброу"},ang={["class:Druid"]="Побачити побратима-друїда, зламаного дикими хащами Рейзорфен Краулу, — суворе нагадування про дике, невблаганне зіпсуття, що безборонно шириться південними Пустками.",["race:NightElf"]="Віднісши амулет Гералата до Дарнасуса, ви вшановуєте полеглого брата, що віддав життя, намагаючись збагнути й вилікувати поранені землі Калімдору."},sec={{t="Трагічна місія",b="Народ послав Гералата Фелловбрука дослідити давнього бога-вепра Аґамаґґана й колючі хащі, що душать південні Пустки, — він шукав коріння зіпсуття Рейзорфен Краулу. Та замість відповідей нічний ельф потрапив у полон до шипогривів. Замкнений у брудному загоні й безжально битий, Гералат знемагав від тяжких ран і лютої гарячки. Перш ніж згаснути, він розповів усе, що знав, товаришеві по неволі — дворфові Генріґу Лоунброу — і благав його попередити заставу вартових у Таланаарі про ворожість, яку розпалила відьма шипогривів Чарлґа Рейзорфленк."},{t="Останнє бажання",b="Лоунброу вдалося втекти, а Гералат був надто слабкий, щоб тікати. Застигнувши на порозі смерті серед заплутаних загонів Краулу, друїд тримається при тямі лише для того, щоб благати перехожих шукачів пригод. Він просить не порятунку, а щоб амулет його дружини Трешали відібрали в тих, хто його полонив, і віднесли до Дарнасуса — щоб вона дізналася про його долю й знала, що він беріг пам'ять про неї до кінця."}},faq={{q="Хто такий Гералат Фелловбрук?",a="Гералат Фелловбрук — нічний ельф-друїд, якого тримають у полоні в Рейзорфен Краулі. Він прибув до Пусток вивчати, як зіпсувалися терни й що лишилося від спадку полеглого вепра, Прадавнього Аґамаґґана, але шипогриви схопили його й закатували до смерті.",al={"хто такий гералат","гералат фелловбрук","нічний ельф у рейзорфені"}},{q="Що сталося з Гералатом у Рейзорфен Краулі?",a="Шипогриви Рейзорфен узяли Гералата в полон, побили й замкнули в хижі. Через безперервні знущання й хворобу його тіло знесиліло, і коли рятівники нарешті дісталися до нього, він уже був при смерті.",al={"чому гералат помирає","що сталося з гералатом фелловбруком"}},{q="Про що Гералат просить мандрівників?",a="Знаючи, що не виживе, Гералат благає шукачів пригод забрати в шипогривів кулон його дружини й віднести їй до Дарнасуса разом зі сумною звісткою про його смерть.",al={"завдання гералата","завдання смертність слабшає"}},{q="Ким Генріґ Лоунброу доводився Гералатові?",a="Генріґ Лоунброу — дворф, якого тримали в тому самому загоні, що й Гералата. Перш ніж Генріґу вдалося втекти, Гералат розповів йому важливі відомості про Аґамаґґана й попросив переказати на заставу Таланаар звістку про те, що замишляє Чарлґа Рейзорфленк.",al={"генріґ лоунброу гералат","дворф полонений у рейзорфені"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="Герод",s="Герод — уславлений чемпіон і берсерк Багряного Хрестового Походу, що командує Збройнею Багряного Монастиря. Відомий лютою бойовою майстерністю й непохитним запалом, він навчає новобранців жорстокого ближнього бою, без якого не вести святої війни. Його смерті прагнуть і незгодні з орденом люди Альянсу, і правителі Орди в Андерсіті, щоб підірвати військову силу Хрестового Походу.",h="Герод — уславлений чемпіон і берсерк Багряного Хрестового Походу, що командує Збройнею Багряного Монастиря.",kw={"герод","збройня","багряний монастир","берсерк","варіматрас","релі побожний","багряний хрестовий похід"},ang={["class:Warrior"]="Герод — яскравий приклад розлюченого воїна: його шалені вихрові удари й безоглядний натиск зробили його грізним бойовим взірцем для новобранців Багряного Хрестового Походу.",["faction:Alliance"]="Герої Альянсу, які відгукнуться на заклик Релі Побожного, на власні очі побачать, як колись шляхетні захисники Лордерону скотилися в божевільну, фанатичну жагу крові під проводом таких ватажків, як Герод.",["faction:Horde"]="Для Орди, а надто для Відступників, убивство Герода — пряме виконання наказу Варіматраса зламати верхівку, що загрожує кордонам Галявин Тірісфалю."},sec={{t="Чемпіон Збройні",b="В укріплених залах Збройні Багряного Монастиря Герод уособлює бойову агресію Хрестового Походу. На відміну від чародіїв і паладинів, що черпають святу магію в Соборі, Герод покладається на грубу, кровожерну фізичну силу. Закутий у кольчугу, з величезною дворучною сокирою, він особисто муштрує загони багряних новобранців, прищеплюючи їм шалену відданість винищенню всіх, хто не підтримує їхньої фанатичної справи."},{t="Першочергова ціль",b="Герод відає зброєю й бойовою підготовкою передових воїнів Хрестового Походу, тож кожен, хто хоче розвалити орден, мусить його усунути. Релі Побожний, колишній хрестоносець із Саутшора, розчарований безумством ордену, закликає вбити Герода, щоб обезглавити військову верхівку Походу. По той бік Лордерону жахолорд Варіматрас в Андерсіті так само прагне його страти, щоб знищити небезпечний людський оплот на кордоні земель Відступників."}},faq={{q="Хто такий Герод?",a="Герод — людина, вправний воїн і командир Зброярні в Багряному Монастирі. Він один із чотирьох головних очільників Монастиря й відповідає за спорядження та муштру завзятих бійців ближнього бою Хрестового Походу.",al={"лор герода","хто такий герод","герод багряний монастир"}},{q="Де перебуває Герод?",a="Герод — у самому серці крила Зброярні Багряного Монастиря, на північному сході Галявин Тірісфалю. Він чекає суперників на тренувальній арені посередині, оточеній галереями для глядачів.",al={"де герод","місце герода","знайти герода"}},{q="Чому Орда хоче смерті Герода?",a="Жахолорд Варіматрас, що діє від імені Відступників з Андерсіті, прагне знищити головних командирів Монастиря — зокрема й Герода, — щоб покінчити із загрозою від Хрестового Походу просто під боком у столиці Відступників.",al={"варіматрас герод завдання","чому орда вбиває герода","до багряного монастиря"}},{q="Чому Альянс хоче смерті Герода?",a="Релі Побожний, колишній член Багряного Хрестового Походу, що живе в Передгір'ї Гілсбреда, бачить, що орден скотився до фанатизму. Він просить поборників Альянсу знищити Герода, щоб позбавити Хрестовий Похід його жорстокого очільника-воїна.",al={"в ім'я світла","релі побожний герод","чому альянс вбиває герода"}},{q="Що стається, коли Герода переможено?",a="Щойно Герод падає, з довколишніх казарм на арену висипає юрба молодих багряних новобранців, щоб помститися за свого наставника, — і це показує, наскільки віддано його шанували учні.",al={"багряні новобранці","набіг новобранців герода","подія смерті герода"}},{q="Що Герод за боєць?",a="Герод — берсерк і воїн, а не звичайний святий паладин. Він трощить ворогів лютими наскоками й вихорами широких ударів, покладаючись на шалену фізичну міць, а не на заклинання Святого Світла.",al={"стиль бою герода","чи герод паладин"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="Верховний Екзекутор Дарталія",s="Верховний Екзекутор Дарталія — високопоставлена воєначальниця Відступників, що несе службу в Таррен Міллі в Передгір'ї Гілсбреда. Діючи з прямого доручення Леді Сильвани Віндраннер і Варіматраса, вона керує операціями Відступників проти людської твердині Саутшор і місцевих розбійників Синдикату. Її провід — запорука безпеки південного флангу Орди в Лордероні.",h="Верховний Екзекутор Дарталія — високопоставлена воєначальниця Відступників, що несе службу в Таррен Міллі в...",kw={"верховний екзекутор дарталія","відступники","таррен мілл","саутшор","синдикат","гілсбред"},ang={["faction:Alliance"]="Для людей Саутшора та їхніх союзників Дарталія — безжальна натхненниця нескінченних нападів, що загрожують їхньому останньому оплоту в Лордероні.",["faction:Horde"]="Шукачі пригод з Орди звітують Дарталії, щоб стримувати агресію Альянсу й утримувати спірне прикордоння Передгір'я Гілсбреда.",["race:Undead"]="Для Відступників Дарталія уособлює залізну волю Андерсіті, що дбає, аби Лордерон міцно лишався в руках вільної нежиті."},sec={{t="Командувачка Таррен Мілла",b="Верховний Екзекутор Дарталія, що діє з Таррен Мілла, — оперативна командувачка сил Відступників по всьому Передгір'ю Гілсбреда. Її головна стратегічна мета — зупинити поширення людського опору, стримувати сили Альянсу в Саутшорі й вистежувати свавільних розбійників Синдикату, що заполонили околиці. Кожен наступ на південь Гілсбреда йде просто через її командування."},{t="Війна за Гілсбред",b="За прямими наказами найвищого проводу Андерсіті — Королеви Баньші та її заступника-жахолорда Варіматраса — Дарталія керує нещадною війною на виснаження по всьому Гілсбреду. Вона організовує розвідувальні вилазки, точкові удари по людських ватажках і винагороди за голови небезпечних злочинців, що загрожують владі Відступників на півночі Лордерона."}},faq={{q="Хто така Верховний Екзекутор Дарталія?",a="Верховний Екзекутор Дарталія — воєначальниця Відступників у Передгір'ї Гілсбреда. Вона керує воєнними діями Орди й Відступників проти людського міста Саутшор і знищує ворожі загрози в краї.",al={"хто така дарталія","ідентичність дарталії","екзекутор дарталія"}},{q="Де знайти Дарталію?",a="Вона командує силами Відступників із Таррен Мілла: збирає війська й координує удари по всій центральній частині Лордерону.",al={"місце дарталії","де дарталія","карта екзекутора дарталії"}},{q="Кому підпорядковується Дарталія?",a="Дарталія діє в межах прямої військової ієрархії Андерсіті й звітує Леді Сильвані Віндраннер та жахолордові Варіматрасу, які керують обороною й розширенням земель Відступників.",al={"начальник дарталії","фракція дарталії","хто командує дарталією"}},{q="Які завдання Дарталія дає шукачам пригод?",a="Дарталія доручає поборникам Орди бити просто по людських поселеннях, страчувати небезпечних злочинців і полювати на членів Синдикату, що орудують по всьому Передгір'ю Гілсбреда.",al={"завдання дарталії","завдання від дарталії","чого хоче дарталія"}},{q="Чому Дарталія воює з людьми Саутшора?",a="Саутшор — головний воєнний плацдарм Альянсу в Лордероні. Завдання Дарталії — стримувати людей, захищати Таррен Мілл і не дати Альянсу просунутися на північ, до Андерсіті.",al={"чому напад на саутшор","війна саутшора","конфлікт гілсбрада"}},{q="Яке звання в Дарталії у війську Відступників?",a="Як Верховний Екзекутор, Дарталія має одне з найвищих польових звань у військовій ієрархії Відступників, тож вона командує силами, заставами й веде воєнну стратегію в усьому краї.",al={"звання верховного екзекутора","титул дарталії"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="Верховний Кат Деррінґтон",s="Верховний Кат Деррінґтон командує авангардом Відступників біля Оплоту на східному кордоні Галявин Тірісфалю. Суворий військовий офіцер, він керує передовою обороною Орди від загроз Погибелі й Багряного Хрестового Походу, що сунуть із Західних Чумних Земель. З цієї укріпленої перепони він скеровує загартованих звитяжців до спірних руїн на кшталт Андоргала й Сколомансії.",h="Верховний Кат Деррінґтон командує авангардом Відступників біля Оплоту на східному кордоні Галявин Тірісфалю.",kw={"верховний кат деррінґтон","оплот","західні чумні землі","андоргал","сколомансія","орда","погибель"},ang={["class:Warrior"]="Деррінґтон утілює похмуру, практичну твердість фронтового солдата, що цінує бойову вправність і результати на полі бою понад придворні інтриги.",["faction:Horde"]="Для мандрівників Орди, що прибувають до Тірісфалю, Деррінґтон — головний військовий командир, який скеровує сили в небезпечні конфлікти Західних Чумних Земель.",["race:Undead"]="Деррінґтон утілює військовий хребет армії Відступників, зосереджений виключно на тому, щоб уберегти відвойовані землі від повернення Погибелі й багряного фанатизму."},sec={{t="Командир на порозі",b="Стоячи просто перед укріпленими барикадами Оплоту, Верховний Кат Деррінґтон — брамник між примарним спокоєм Галявин Тірісфалю й гнилими жахіттями Західних Чумних Земель. Деррінґтон не має терпіння до політичних ігор в Андерсіті: передову він бачить як горнило чистого виживання. Солдатам і найманцям Орди, що хочуть випробувати себе, Деррінґтон віддає прямі військові накази, посилаючи розвідників і ударні загони вглиб зачумленої землі, щоб притупити ворожі вторгнення, перш ніж вони прорвуться в Тірісфаль."},{t="Війна на два фронти",b="Оборонна позиція Деррінґтона в облозі з кількох боків. На сході — Погибель, що окопалася в розтрощеному містечку Андоргал і розливається околицями через зіпсутні казани. Водночас Багряний Хрестовий Похід зі своїми ревними фанатиками оспорює північні укріплення й невпинно б'ється з патрулями Відступників. Деррінґтон координує точкові контрудари, саботаж проти ліній Багряних і планомірне руйнування полів із казанами Погибелі, щоб уберегти східний кордон."}},faq={{q="Хто такий Верховний Кат Деррінґтон?",a="Верховний Кат Деррінґтон — старший командир Відступників на Заслоні, військовій заставі, що відмежовує Галявини Тірісфалю від Західних Чумних Земель. Він керує стратегічним наступом Орди на схід — і проти Погибелі, і проти Багряного Хрестового Походу.",al={"деррінґтон","хто такий деррінґтон","лор верховного ката деррінґтона"}},{q="Де перебуває Деррінґтон?",a="Він на Заслоні — укріпленій вузькій ділянці на самому східному краї Галявин Тірісфалю, при дорозі до Західних Чумних Земель.",al={"де деррінґтон","місце деррінґтона","знайти верховного ката деррінґтона"}},{q="Яка мета Деррінґтона на Заслоні?",a="Деррінґтон прагне вберегти Відступників: тримати міцну лінію оборони проти Погибелі й завдавати ударів на схід, у Західні Чумні Землі. Він доручає шукачам пригод розвідати Андоргал, вивести з ладу чумні казани й зірвати задуми Багряного Хрестового Походу.",al={"чого хоче деррінґтон","мета заслону","місія деррінґтона"}},{q="Чи цікавить Деррінґтона політика Андерсіті?",a="Ні. Деррінґтон відкрито зневажає придворних інтриганів і політиканів і зауважує, що на передовій, де за виживання щодня доводиться битися, на такі розкоші немає часу.",al={"характер деррінґтона","чи деррінґтон політик"}},{q="Проти яких головних загроз Деррінґтон посилає солдатів?",a="Деррінґтон насамперед б'є по Погибелі, що тримає руїни Андоргала, по темних некромантах у Сколомансії та по довколишніх гарнізонах Багряного Хрестового Походу, які загрожують східним шляхам постачання Орди.",al={"завдання деррінґтона","з ким бореться деррінґтон"}},{q="Чому Заслон так сильно укріплено?",a="Заслон — головний прохід між відносно безпечними Галявинами Тірісфалю й гарячими точками Чумних Земель. Сили Деррінґтона тримають цей прохід, щоб величезні полчища Погибелі чи походи Багряного Хрестового Походу не прорвалися просто до Андерсіті.",al={"чому заслон тут","лор заслону"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="Верховний Екзекутор Гадрек",s="Верховний Екзекутор Гадрек — військовий командир гарнізону Відступників у Гробниці в Срібноліссі. З цієї центральної крипти він керує обороною від загроз краю, зокрема від гнилошкірих гнолів, і розслідує зникнення розвідників по всьому краю. Він — головний офіцер, що спрямовує дії Орди по всьому Срібноліссю.",h="Верховний Екзекутор Гадрек — військовий командир гарнізону Відступників у Гробниці в Срібноліссі.",kw={"верховний екзекутор гадрек","гробниця","відступники","гнилошкірі гноли","острів фенріс","срібнолісся"},ang={["class:Rogue"]="Гадрек дуже покладається на розвідку скрадачів смерті й часто залучає потайних агентів, щоб повернути зниклих товаришів і здобути іхор і документи ворогів.",["faction:Horde"]="Союзники Відступників, що прибувають із Калімдору, звітують Гадрекові й допомагають навести лад у Срібноліссі, на власні очі бачачи, наскільки хиткий плацдарм Орди на півночі Лордерона.",["race:Undead"]="Для Відступників, що йдуть на південь із Похоронного Подзвону, Гадрек — голос найвищого командування Андерсіті, що перетворює щойно пробуджених мерців на організованих захисників Лордерона."},sec={{t="Командир у Гробниці",b="Верховний Екзекутор Гадрек, що несе службу в похмурій Гробниці, керує військовими діями Відступників по всьому Срібноліссю. Галявини Тірісфалю надійно тримають сили Темної Леді, а Срібнолісся досі сповнене небезпек: довкола ворожі маги Даларана, дикі воргени й гноли, що наступають. На Гадрекові лежить похмура відповідальність — зміцнювати землі Відступників і придушувати все, що кидає виклик владі Андерсіті на південь від столиці."},{t="Пошесть гнилошкірих",b="Гадрека найбільше непокоять гнилошкірі гноли й Острів Фенріс. Ці звірі, отруєні дотиком нежиття, заполонили Мертве Поле й береги Озера Лордамер і становлять непередбачувану й жорстоку загрозу для патрулів Відступників. Гадрек посилає агентів прочісувати старі пороми й гнилі хутори в пошуках підказок, з'ясувати, що дає звірам силу, і підготувати відкритий удар по їхній острівній твердині."},{t="Око на Шадовфенг",b="Окрім навали гнолів, Гадрек пильно стежить за розвідданими, які збирають скрадачі смерті — таємна розвідувальна служба розбійників Відступників. Коли таємні агенти зникають біля моторошних шпилів Фортеці Шадовфенг, Гадрек доручає шукачам пригод з'ясувати їхню долю, щоб Темна Леді знала все про темного архімага Аруґала та його проклятих воргенів."}},faq={{q="Хто такий Верховний Екзекутор Гадрек?",a="Гадрек — офіцер Відступників у званні Верховного Екзекутора. Він командує гарнізоном у Гробниці, тож має найвищу владу над усіма діями Відступників у Срібноліссі.",al={"лор гадрека","хто такий гадрек","командир гробниці"}},{q="Де знайти Верховного Екзекутора Гадрека?",a="Він у Гробниці — поселенні Відступників у центрі Срібнолісся, при головній дорозі з півночі на південь.",al={"місце гадрека","де гадрек","знайти гадрека"}},{q="Проти яких загроз Гадрек посилає гравців?",a="Гадрек посилає солдатів і шукачів пригод проти гнилошкірих гнолів, що заполонили Мертві Поля й Острів Фенріс. Він також керує пошуками зниклих шпигунів-скрадачів смерті й з'ясуванням того, що коїться у Фортеці Шадовфенг.",al={"завдання гадрека","що робить гадрек","місії сільверпайну"}},{q="Що робить Верховний Екзекутор у війську Відступників?",a="Верховний Екзекутор — високопоставлений польовий командир у війську Відступників, якому під владою Леді Сильвани Віндраннер довіряють повне стратегічне керівництво цілою заставою в краї чи ділянкою фронту.",al={"відступники верховний екзекутор","звання верховного екзекутора","звання гадрека"}},{q="Чому Гадрека цікавить Острів Фенріс?",a="Острів Фенріс став головним лігвом гнилошкірих гнолів. Щоб убезпечити Озеро Лордамер і довколишні води для постачання Відступників, Гадрек організовує розвідку, а згодом і штурм, щоб знищити ватажків гнолів.",al={"острів фенріс гадрек","чому штурм острова фенріс","гниль-шкура фенріс"}},{q="Що пов'язує Гадрека з Фортецею Шадовфенг?",a="Гадрек співпрацює зі скрадачами смерті — шпигунським орденом Відступників. Коли розвідники, вислані до Фортеці Шадовфенг, не повертаються зі звітами, Гадрек доручає надійним агентам дослідити фортецю й з'ясувати, що з ними сталося.",al={"шадовфенг гадрек","гадрек аруґал","слідопити смерті в шадовфенгу"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-priest-rohan"] = {n="Верховний Жрець Роган",s="Верховний Жрець Роган — найвищий провідник Церкви Святого Світла в Айронфорджі; його можна побачити в Залі Таїнств, де він походжає туди-сюди. Він опікується духовним зростанням молодих жерців усього Альянсу й допомагає тим, хто прагне опанувати Святе Світло. Своїми настановами й священними реліквіями він підтримує духовні зв'язки між гірським королівством, Стормвіндом і далекими союзниками.",h="Верховний Жрець Роган — найвищий провідник Церкви Святого Світла в Айронфорджі; його можна побачити в Залі...",kw={"верховний жрець роган","зала таїнств","церква святого світла","кадило екзорцизму","айронфордж","жрець","паладин"},ang={["class:Paladin"]="Святі лицарі, яких посилає Лорд Ґрейсон Шедовбрейкер, мусять навідатися до Рогана по його славетне Кадило Екзорцизму — в обмін на допомогу бідакам Айронфорджа.",["class:Priest"]="Верховний Жрець Роган дає важливі настанови й перші вміння, а згодом скеровує вас до славетних наставників у Стормвінді чи Дарнасусі, щоб відкрити особливі расові молитви.",["faction:Alliance"]="Завдяки тісній співпраці із Собором Світла, Храмом Місяця й Колом Кенарія Роган міцно вплітає духовенство Айронфорджа в ширший Альянс.",["race:Dwarf"]="Роган утілює відданість дворфів Святому Світлу й показує, що міцний народ Каз Модану має глибоку духовну переконаність поряд зі спадщиною титанів."},sec={{t="Пастир Зали Таїнств",b="Походжаючи тихими плитами Зали Таїнств у Кварталі містиків, Верховний Жрець Роган є найвищим представником Церкви Святого Світла в Айронфорджі. Дворфи здавна шанували титанів, але дворфійські жерці щиро прийняли чесноти Світла — мудрість, співчуття й справедливість. Роган — терплячий учитель для молодих послушників: він навчає їх дисципліни, потрібної, щоб спрямовувати святу магію й гартувати розум проти розпачу."},{t="Мости через увесь Альянс",b="Роган розуміє, що духовне прозріння в Альянсі має багато облич. Коли його учні опановують основи, він посилає їх у світ: людей і дворфів — до Верховної Жриці Лаурени в Стормвінді, а учнів — нічних ельфів — до Жриці Алатеї в Храмі Місяця в Дарнасусі, щоб ті опанували невловимі таїнства на кшталт Грації Елуни. Поза столицями він закликає вірян допомагати всюди, де спіткала біда, і навіть посилає цілителів у далеку Азшару на допомогу друїдам Кола Кенарія."},{t="Кадило Екзорцизму",b="Окрім навчання, Роган береже священні реліквії, важливі для всього жрецтва Альянсу та братств паладинів. Серед його скарбів — благословенне Кадило Екзорцизму, загартоване роками вигнання мерзенних духів. Коли Ордену Срібної Длані та Лордові Ґрейсону Шедовбрейкеру потрібна ця посудина, щоб загартувати святе покликання своїх лицарів, Роган охоче її віддає — просить лише милостині, щоб поповнити скудні харчові запаси Айронфорджа для міських бідаків."}},faq={{q="Де знайти Верховного Жерця Рогана?",a="Верховний Жрець Роган у Залі Таїнств, що в Кварталі містиків на північному боці Айронфорджа. Він походжає туди-сюди між священною бібліотекою й вівтарем.",al={"місце рогана","де тренер жерців айронфорджа","карта рогана","тренер жерців зали таємниць"}},{q="Яку роль Роган відіграє в Айронфорджі?",a="Він старший наставник жерців в Айронфорджі й головний представник дворфів у Церкві Святого Світла в Каз Модані. Він навчає нових жерців, дає духовні поради й спрямовує вірян на поглиблене навчання по всьому Азероту.",al={"хто такий роган","що робить роган","лор рогана"}},{q="Чому Роган посилає жерців до Дарнасуса чи Стормвінда?",a="Роган вважає, що духовне зростання вимагає вчитися в різних традиціях. Людей і дворфів-послушників він посилає до Собору Світла в Стормвінді вивчати особливі молитви на кшталт Відчайдушної Молитви, а нічних ельфів відправляє назад до Храму Місяця в Дарнасусі, щоб вони відчули Благодать Елуни.",al={"завдання жерців рогана","відчайдушна молитва роган","завдання храму місяця"}},{q="Навіщо паладини шукають Рогана?",a="Паладини, яких посилає Лорд Ґрейсон Шедовбрейкер, приходять до Рогана по його освячене кадило для вигнання злих духів. Роган віддає цю реліквію, щоб допомогти Орденові Срібної Длані завершити обряди, а натомість просить скромної пожертви харчами, щоб нагодувати бідняків Айронфорджа.",al={"завдання паладина рогана","кадило екзорцизму","наголос на жертві"}},{q="Чому Роган посилає жерців до Азшари?",a="Керуючись заповідями Світла про милосердя й служіння, Роган відряджає цілителів на допомогу нічним ельфам-друїдам Кола Кенарія, які працюють у диких, суворих землях Азшари.",al={"допомога ценарія роган","роган коло ценарія"}},{q="Чи Роган навчає лише дворфів?",a="Роган наставляє кожного вірянина Альянсу, що ступив на шлях жрецтва, — дворфів, людей і нічних ельфів: дає перші уроки, а потім посилає до наставників, які найкраще знають їхні власні традиції.",al={"чи люди тренуються в рогана","кого навчає роган"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {n="Верховна Жриця Лаурена",s="Верховна Жриця Лаурена — шанована наставниця жерців-людей, що служить за великим вівтарем Собору Світла в Стормвінді. Утікши як біженка з охопленого руйнацією Лордерону під час Третьої війни, нині вона навчає молодих жерців Альянсу духовної відданості й захисних чарів.",h="Верховна Жриця Лаурена — шанована наставниця жерців-людей, що служить за великим вівтарем Собору Світла в...",kw={"лаурена","верховна жриця","жерці","собор світла","лордерон","стормвінд"},ang={["class:Priest"]="Верховна Жриця Лаурена — одна з головних наставниць жерців у Стормвінді: вона веде послушників-людей крізь священні випробування, благословляє їх Відчайдушною молитвою й навчає, як зривати чари ворожих заклиначів.",["faction:Alliance"]="Із Собору Світла Лаурена зміцнює духовний хребет Альянсу, щоб його поборники могли встояти перед темною магією й жахами нежиті.",["race:Human"]="Як і багато людей у Стормвінді, Лаурена несе в серці скорботу за полеглим північним королівством Лордерон, а нове життя збудувала як духовна опора для інших уцілілих."},sec={{t="Біженка з Лордерону",b="Перш ніж посісти місце у височенних залах Собору Світла, Лаурена жила в північному королівстві Лордерон. Коли під час Третьої війни Погибель прокотилася тим краєм, вона й уся її родина мали щастя вижити й утекти на південь, до Стормвінда, як переселенці. Попри безмежне горе й хаос, що зруйнували її батьківщину, Лаурена лишилася непохитною у вірі й зрештою стала Верховною Жрицею на службі Церкви Святого Світла."},{t="Опіка над вірними",b="Стоячи просто за центральним вівтарем святилища, Верховна Жриця Лаурена присвячує себе наставництву молодих жерців. Коли перспективні послушники виявляють досить відданості й побожності, їх скеровують до неї поглибити навчання. Лаурена вчить їх закликати священні дари на кшталт Відчайдушної молитви й навчає захисних мистецтв, зокрема чарів, що обертають ворожу таємну магію проти тих, хто нею володіє. Коли посвячений засвоїть усе, що вона може дати, Лаурена посилає його далі — до інших майстрів-жерців по всьому Альянсу."}},faq={{q="Де знайти Верховну Жрицю Лаурену?",a="Вона стоїть за головним вівтарем у Соборі Світла, що на Соборній Площі в Стормвінді.",al={"місце лаурени","де жриця лаурена","знайти лаурену"}},{q="Чого навчає Верховна Жриця Лаурена?",a="Лаурена — наставниця жерців. Вона дає людям-жерцям основи ремесла й навчає особливих расових молитов, як-от Відчайдушної Молитви, а також захисних чарів на кшталт Арканного Відгуку проти ворожих заклиначів.",al={"закляття лаурени","тренер жерців лаурена","чого навчає лаурена"}},{q="Звідки Лаурена прибула до Стормвінда?",a="Спершу Лаурена жила в королівстві Лордерон. Під час Третьої війни її родині вдалося врятуватися від жахіть Погибелі й утекти біженцями до Стормвінда, де вона й далі служила своєму релігійному покликанню.",al={"минуле лаурени","чи лаурена зі стормвінда","лаурена лордерон"}},{q="Чи вона служить під проводом Архієпископа Бенедиктуса?",a="Так. Архієпископ Бенедиктус — духовний провідник Церкви Святого Світла й очолює Собор Світла, де Лаурена служить Верховною Жрицею.",al={"лаурена й бенедиктус","хто начальник лаурени","бенедиктус лаурена"}},{q="Чому вона посилає мене до інших наставників жерців?",a="Різні культури й народи Альянсу спілкуються з божественним кожен по-своєму. Навчивши учнів основних молитов Святого Світла, Лаурена посилає їх до майстрів інших традицій — до дворфів-наставників в Айронфорджі чи до жриць нічних ельфів у Дарнасусі, — щоб розширити їхні духовні обрії.",al={"лаурена відсилає мене","завдання відсутність страху","завдання благодать елуни"}},{q="Чи Лаурена втратила родину через нежить?",a="На диво, її найближча родина пережила падіння Лордерону. Вони були серед щасливих біженців, яким удалося неушкодженими втекти від Погибелі й здолати довгу путь на південь, до безпечного Стормвінда.",al={"родина лаурени загинула","що сталося з родиною лаурени"}}},fp="22,297,22.515.0,20.585.0,40.123.0,39.227.0,45.214.0,43.166.0,48.338.0,42.203.0"}
P.entries["npc:highlord-demitrian"] = {n="Верховний Лорд Демітріан",s="Верховний Лорд Демітріан — самотній відлюдник-людина, що живе серед дивних кристалів на північному заході Силітусу. Він називає себе вірним слугою принца Тандераана й володіє таємними знаннями, потрібними, щоб пробудити дрімотного володаря стихії. Шукачі пригод, які здобули прадавні стихійні пута, шукають його, щоб вивільнити силу Шукача Вітру.",h="Верховний Лорд Демітріан — самотній відлюдник-людина, що живе серед дивних кристалів на північному заході...",kw={"верховний лорд демітріан","тандераан","громолють","шукач вітру","кришталева долина","силітус"},ang={["class:Rogue"]="Розбійники, що полюють на легендарний клинок Шукача Вітру, мусять домовитися з Демітріаном у Силітусі, щоб відродити розтрощеного принца.",["class:Warrior"]="Воїни, що прагнуть здобути легендарний клинок Громолють, мусять розшукати Демітріана, щоб розпочати випробування: зняти пута й пробудити Шукача Вітру.",["profession:Blacksmithing"]="Щоб виконати вимоги Демітріана для відродження Тандераана, потрібна неабияка ковальська майстерність: Зачаровані злитки елементію доведеться кувати із сирої руди й вогняних есенцій."},sec={{t="Відлюдник Кришталевої Долини",b="Демітріан, якого можна зустріти в покинутому таборі в Кришталевій Долині, здається чужим у безлюдних пустелях Силітусу. Хоча він пов'язаний із Молотом Присмерку, у чиєму сплюндрованому таборі тиняється, понад усе Демітріан — провісник принца Тандераана, Шукача Вітру. До відвідувачів він ставиться відсторонено й байдуже, доки ті не покажуть доказу розтрощеної сутності Шукача Вітру."},{t="Посудина Відродження",b="Уся мета Демітріана — воскресіння Тандераана. Якщо шукач пригод принесе йому Пута Шукача Вітру — реліквії, вирвані у вогняних елементалів у Розплавленому Ядрі, — Демітріан дасть Посудину Відродження. Щоб відновити тілесну подобу свого принца, він вимагає рідкісних стихійних реагентів, зокрема чималої кількості зачарованого елементію та сутності самого Володаря вогню."},{t="Зрада Шукача Вітру",b="Обряд Демітріана викликає принца Тандераана в Кришталеву Долину, і шукачі пригод мусять зійтися в бою з відродженим Шукачем Вітру. Здолавши володаря стихії, вони здобувають Дрімотний Клинок Поцілунку Вітру й приносять його наляканому Демітріанові, який натомість пробуджує Громолють."}},faq={{q="Де знайти Верховного Лорда Демітріана?",a="Він у далекому північно-західному куточку Силітусу, неподалік від Сплюндрованого Сутінкового Табору в Кришталевій Долині.",al={"місце демітріана","де демітріан","демітріан сілітус"}},{q="Чому Демітріан відповідає лише загальними фразами?",a="Демітріан не запропонує свого легендарного ланцюжка завдань, якщо при вас немає хоча б однієї половини Пут Шукача Вітру — рідкісних скарбів, які тримають Барон Геддон і Ґарр у Розплавленому Ядрі.",al={"демітріан не хоче говорити","як отримати завдання демітріана","плітки демітріана"}},{q="Що пов'язує Демітріана з принцом Тандерааном?",a="Демітріан — присяглий смертний слуга принца Тандераана. Він присвятив себе пошукам розірваних пут принца, щоб повернути цього володаря стихій у матеріальний світ.",al={"кому служить демітріан","демітріан тандераан","чи демітріан молот присмерку"}},{q="Що стається, коли приносиш йому всі матеріали для посудини?",a="Демітріан проводить ритуал, що викликає принца Тандераана до Кришталевої Долини й повертає Шукача Вітру в матеріальний світ.",al={"виклик тандераана","що робить демітріан із посудиною","виклик у кришталевій долині"}},{q="Чи Демітріан пов'язаний з культом Молота Присмерку?",a="Він пов'язаний з Молотом Присмерку, живе в їхньому сплюндрованому таборі й говорить про Древніх Богів із благоговінням. Та все ж присягав він на вірність своєму володареві — принцові Тандераану.",al={"чи демітріан культист","табір присмерку демітріан","фракція демітріана"}},{q="Як отримати в нього Громолють?",a="Доручення Демітріана пов'язане з Путами Шукача Вітру й рідкісними матеріалами, що стосуються Тандераана. Воно втягує шукачів пригод у справу, корені якої — в ув'язненні принца стихій.",al={"як отримати громолють","завершення завдання громолюті","клинок демітріана"}}},fp="18,351,26.385.0,21.400.1,26.289.1,36.122.0,48.202.0,54.181.0,65.133.1,56.178.0,36.188.1"}
P.entries["npc:hogger"] = {n="Гоґґер",s="Гоґґер — лютий ватажок гнолів Річколапів, що нишпорять південно-західним Лісом Елвінн. Вищий за своїх родичів і надзвичайно агресивний, він здобув сумну славу нападами на тутешні ферми й убивствами необережних подорожніх. Його криваві безчинства заслужили офіційну винагороду від маршалів Стормвінда.",h="Гоґґер — лютий ватажок гнолів Річколапів, що нишпорять південно-західним Лісом Елвінн.",kw={"гоґґер","гноли","річколапи","винагорода","маршал дуґан","пагорб гоґґера"},ang={["faction:Alliance"]="Набіги Гоґґера показують, як розтягнуте військо Стормвінда: маршалам доводиться покладатися на мандрівних шукачів пригод, щоб підтримувати лад біля столиці.",["race:Human"]="Для молодих захисників Стормвінда зустріч із Гоґґером — раннє випробування вогнем і пряма відповідь на загрози, що розхитують серце Елвінну."},sec={{t="Жах Річколапів",b="Нишпорячи на Пагорбі Гоґґера в південно-західному Лісі Елвінн, Гоґґер командує тутешньою зграєю Річколапів із незрівнянною жорстокістю. У роки після Третьої війни набіги гнолів на місцеві садиби ставали дедалі зухвалішими й злагодженішими. За цим сплеском насильства стоїть тривожний союз: Річколапи почали змовлятися з Братством Дефіас, міняючи сиру лють на зброю, тактичні вказівки й магічну підтримку. Щоб уберегти кордони Елвінну й захистити торгові шляхи від подальшого кровопролиття, Маршал Дуґан оголосив щедру винагороду за голову Гоґґера."}},faq={{q="Хто такий Гоґґер?",a="Гоґґер — величезний і надзвичайно небезпечний гнол, ватажок зграї Річколапів на південному заході Лісу Елвінн. Він славиться нападами на довколишні хутори, і влада Стормвінда розшукує його, щоб покарати смертю за жорстокі напади на людські поселення.",al={"лор гоґґера","хто такий гоґґер","ватажок річколапів"}},{q="Чому за Гоґґера оголошено нагороду?",a="Маршал Дуґан і варта Стормвінда офіційно оголосили нагороду за Гоґґера, бо його напади на сільські хутори й мандрівників ставали дедалі зухвалішими. Кожен, хто наважиться покласти край його бешкетам, має принести до Ґолдшира його величезний пазур як доказ.",al={"розшукується гоґґер","чому вбивати гоґґера","нагорода за гоґґера"}},{q="Чи гноли Річколапів співпрацюють із Братством Дефіас?",a="Так. Братство Дефіас змовилося зі зграєю Річколапів і постачає цим брутальним гнолам добру зброю, тактичні поради й магічну підтримку, щоб іще дужче розхитати владу Стормвінда в краї.",al={"гоґґер дефіас","зв'язок гнолів із дефіас","річколапи дефіас"}},{q="Де Гоґґер отаборився?",a="Гоґґер живе на вершині Пагорба Гоґґера в південно-західному куточку Лісу Елвінн, серед своїх відданих одноплемінників-Річколапів, неподалік від кордону з Вестфолом.",al={"місце гоґґера","де гоґґер","пагорб гоґґера"}}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Голт Тандергорн",s="Голт Тандергорн — наставник мисливців із тауренів, що працює на Узвишші Мисливців у піднесеному місті Тандер Блаф. Він навчає ремесла і новачків, і бувалих майстрів сліду, дає базові бойові настанови й спрямовує змужнілих стрільців на особливі випробування в Малгорі й за його межами.",h="Голт Тандергорн — наставник мисливців із тауренів, що працює на Узвишші Мисливців у піднесеному місті Тандер...",kw={"голт тандергорн","мисливець","наставник","узвишшя мисливців","тандер блаф","малгор"},ang={["class:Hunter"]="Голт Тандергорн — головний наставник у Тандер Блафі: він навчає прийомів зі зброєю, слідопитства й направляє до приборкання звірів.",["race:Tauren"]="Голт на Узвишші Мисливців уособлює традиційну мисливську культуру тауренів, що годувала й захищала кочові племена задовго до того, як вони звели постійний дім на кручах."},sec={{t="Майстер Узвишшя",b="Голт Тандергорн, що влаштувався на Узвишші Мисливців над розлогими рівнинами Малгору, служить Орді як досвідчений наставник далекого бою, слідопитства й виживання. Як і багато старійшин свого ремесла, він веде молодих тауренів, коли ті перетворюються з мандрівних мисливців на дисциплінованих захисників своєї нової столиці."}},faq={{q="Де знайти Голта Тандергорна?",a="Голт Тандергорн стоїть на Узвишші Мисливців — південно-східному піднесеному плато в тауренській столиці Тандер Блаф, що в Малгорі.",al={"місце голта тандергорна","де голт","тренер мисливців тандер блафф"}},{q="Чого навчає Голт Тандергорн?",a="Він наставник мисливців, що навчає гравців основ влучної стрільби, виживання в дикій природі й приручення звірів, а також скеровує новачків на особливі випробування майстерності володіння звірами.",al={"чого навчає голт","голт тандергорн тренер","які вміння в голта"}},{q="Яку роль відіграють мисливці в Тандер Блафі?",a="Мисливці здавна є опорою тауренського суспільства: вони добувають їжу, обходять кордони племінних земель, стережучи їх від набігів кентаврів, і шанують Земну Матір виваженим і шанобливим полюванням.",al={"навіщо мисливці в піднесенні","лор мисливців тауренів"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {n="Псар Локсі",s="Псар Локсі — офіцер, якому доручено розводити й муштрувати грізних бойових псів Багряного Хрестового Походу. Він порядкує псарнями у Збройні Багряного Монастиря й посилає зграї собак полювати на нежить, непроханих гостей і уявних єретиків. Завдяки його нещадній дисципліні звірі Монастиря зажили лихої слави по всіх Галявинах Тірісфалю.",h="Псар Локсі — офіцер, якому доручено розводити й муштрувати грізних бойових псів Багряного Хрестового Походу.",kw={"псар локсі","пси","псарня","збройня","багряний монастир","ловчий леопольд"},ang={["class:Hunter"]="Локсі — приклад жорстокого, агресивного підходу до приборкання звірів: він змушує лютих псів коритися фанатизмові, замість того щоб будувати зв'язок на взаємній повазі.",["race:Undead"]="Відступникам, які проникають сюди, варто стерегтися псів Локсі: їх навчили чути саме запах мертвої плоті й піднімати на сполох гарнізони Хрестового Походу."},sec={{t="Володар псарень",b="За неприступними мурами Багряного Монастиря Псар Локсі керує вишколом лютих собак-слідопитів і бойових псів. Багряний Хрестовий Похід покладається на цих вишколених собак: вони винюхують заражені чумою трупи, викривають прихованих лазутчиків і наздоганяють утікачів від гніву фанатиків. Локсі має необмежену владу над псарнею Збройні й дбає, щоб його вихованці будь-якої миті були готові роздерти непроханих гостей на шматки."},{t="Родинне суперництво",b="Локсі — не єдиний приборкувач звірів у родині, хто служить справі. Його брат, Ловчий Леопольд, представляє Багряний Хрестовий Похід перед Срібним світанком у Каплиці Надії Світла. Леопольд невисокої думки про брата й у приватних розмовах запевняє, що Локсі ледве дає раду власним псам, не кажучи вже про те, щоб представляти орден у відповідальних перемовинах. Та попри зневагу Леопольда, Локсі лишається важливим офіцером у внутрішній ієрархії Монастиря."}},faq={{q="Де знайти Псаря Локсі?",a="Псар Локсі — у крилі Зброярні Багряного Монастиря на північному сході Галявин Тірісфалю, у псарні, серед своїх бойових собак.",al={"місце локсі","де локсі","де псар локсі"}},{q="Яку роль Локсі відіграє в Багряному Хрестовому Поході?",a="Він головний доглядач тварин і псар Багряного Хрестового Походу в Монастирі: розводить, муштрує й веде в бій бойових псів, які винюхують нежить і полюють на чужинців.",al={"що робить локсі","робота локсі","обов'язки псаря"}},{q="Ким Ловчий Леопольд доводиться Локсі?",a="Ловчий Леопольд — брат Локсі. Леопольд представляє Багряний Хрестовий Похід у Каплиці Надії Світла й зверхньо ставиться до Локсі: мовляв, той не вміє як слід упоратися з власними псами, а дипломатичні обов'язки йому й поготів не до снаги.",al={"леопольд брат локсі","хто такий леопольд","брат локсі"}},{q="Навіщо Багряному Хрестовому Походу собаки?",a="Хрестовий Похід навчає лютих псів вистежувати Погибель і Відступників за запахом, а також стерегти землі Монастиря й шматувати ворогів, що тікають.",al={"навіщо собаки","багряні хорти мета","собаки хрестового походу"}},{q="Чи вважають Локсі одним з очільників Багряного Монастиря?",a="Так, Локсі визнано одним із ключових командирів у військовому устрої Багряного Монастиря: він відає надважливою псарнею в Зброярні.",al={"чи локсі бос","звання локсі","наскільки важливий локсі"}},{q="Чи собаки небезпечні й самі по собі?",a="Так. Виведені для люті й вимуштрувані Локсі, бойові пси Монастиря — запеклі хижаки, здатні за лічені миті розірвати на шматки навіть закутого в броню чужинця.",al={"чи собаки сильні","небезпека багряних хортів","улюбленці локсі"}}},fp="18,355,21.443.0,14.441.0,38.160.0,51.205.0,34.214.0,40.167.0,55.170.0,38.165.0"}
P.entries["npc:huldar"] = {n="Гулдар",s="Гулдар — дворфійський візник, що стоїть на південній дорозі Лох Модану, неподалік берега озера. Йому доручили везти важливий вибуховий порох на південні розкопки, але його валку раз у раз шарпають місцеві загрози й диверсанти Темного Заліза.",h="Гулдар — дворфійський візник, що стоїть на південній дорозі Лох Модану, неподалік берега озера.",kw={"гулдар","візник","вибуховий порох","лох модан","розкопки","темне залізо"},ang={["profession:Engineering"]="Кожен інженер знає ціну — і небезпеку — сирого вибухового пороху в дерев'яних бочках, що стоять просто неба посеред дороги.",["race:Dwarf"]="Допомагаючи Гулдарові, ви прямо підтримуєте розкопки Ліги Дослідників, щоб вашим родичам вистачило пороху відкрити давні таємниці титанів."},sec={{t="Небезпечний рейс із порохом",b="Возити вибухівку Лох Моданом — не звичайний торговий рейс. Гулдарові доручили гнати вози з гірничим вибуховим порохом до південних розкопок, де дворфійським археологам і шукачам дуже бракує припасів. Але дороги дикою місциною стають дедалі небезпечніші. Біля південного вигину озера чатують дикі звірі, троги й лазутчики Темного Заліза, тож Гулдар застряг біля свого пошкодженого воза й покладається на мандрівних подорожніх, які вбережуть решту порохових бочок і допоможуть вантажу дістатися розкопок."}},faq={{q="Хто такий Гулдар?",a="Гулдар — дворф-візник, що застряг зі своїм возом на південному березі озера в Лох Модані. Йому доручили доставити вибуховий порох на розкопки неподалік, але в дорозі він натрапив на біду.",al={"хто такий гулдар","гулдар лох модан","дворф з возом"}},{q="Що у возі Гулдара?",a="У його возі — бочки з вибуховим порохом. Ця вибухівка вкрай потрібна дворфам-старателям і археологам, що працюють на розкопках на півдні.",al={"що везе гулдар","вантаж воза гулдара","що в бочках"}},{q="Чому Гулдар застряг на дорозі?",a="Дороги південного Лох Модану стали небезпечними через ворожих звірів, трогів і дворфів-диверсантів Темного Заліза. На вантаж Гулдара напали з засідки, тож він мусив зупинитися й шукати допомоги, щоб уберегти й доставити решту припасів.",al={"чому гулдар застряг","засідка на гулдара"}},{q="Навіщо дворфам Темного Заліза його вантаж?",a="Клан Темного Заліза всіляко прагне підірвати присутність Айронфорджа й історичні дослідження в Лох Модані. Якщо перекрити постачання вибухового пороху, розкопки зупиняться, а дворфи лишаться без запасів для оборони й роботи.",al={"порох темного заліза","чому темне залізо нападає на гулдара"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="Ілліяна",s="Ілліяна — давня дріада, що оберігає ліси південно-західного Ашенвалю від прадавньої скверни. Блукаючи біля Святилища Аессіни, вона скликає героїв Альянсу, щоб дати відсіч лютим сатирам, які нівечать давні гаї. Її пильність — свідчення нерозривного зв'язку між дочками Кенарія та дикими лісами нічних ельфів.",h="Ілліяна — давня дріада, що оберігає ліси південно-західного Ашенвалю від прадавньої скверни.",ang={["class:Druid"]="Друїди глибоко шанують дріад як утілення дикої природи, тож допомога Ілліяні в збереженні освячених галявин цілком відповідає кенарійському обов'язку зцілювати землю.",["faction:Alliance"]="Ілліяна — важлива лісова союзниця в південно-західному Ашенвалі: вона дає притулок і поради загонам Альянсу, які боронять дикі землі від наступу зла.",["race:NightElf"]="Для калдореїв дріади на кшталт Ілліяни — священна рідня Кенарія, шановані захисниці, на чий заклик до бою з демонічними сатирами відгукуються без вагань."},sec={{t="Дочка лісу",b="Як і всі дріади, Ілліяна — одна з дочок напівбога Кенарія. Мирна, але затято віддана захисту дикої природи, вона обходить ліси південно-західного Ашенвалю. Тепер, коли темні сили заворушилися, а ліси потерпають від повзучої скверни, Ілліяна стереже священні реліквії та гаї, оберігаючи первісну святість природи."},{t="Загроза сатирів",b="Найбільше Ілліяну в цих краях турбує давня пошесть — сатири. Ці спотворені демонічні створіння невпинно прагнуть осквернити галявини й загрожують її сестрам-дріадам. Ілліяна часто просить мандрівників винищити цих мерзенних потвор і повернути втрачені реліквії, зокрема Гілку Кенарія, щоб ліси й надалі були захищені від демонічної скверни."}},faq={{q="Хто така Ілліяна?",a="Ілліяна — дріада, що блукає південно-західним Ашенвалем поблизу Святилища Аессіни. Як донька Кенарія, вона присвячує все своє життя тому, щоб пильнувати дикі краї й захищати своїх сестер від демонічних сил.",al={"хто ця дріада","ілліяна верболіс","що таке ілліяна"}},{q="Чому Ілліяна не зупиняється, коли я з нею розмовляю?",a="Ілліяна постійно обходить ліс дозором. На відміну від тих, хто дає завдання, стоячи на місці, вона й далі пильно ходить гаєм, навіть розмовляючи з мандрівниками.",al={"чому ілліяна ходить","чому вона йде геть","завдання ілліяни на ходу"}},{q="Які завдання дає Ілліяна?",a="Вона закликає шукачів пригод полювати на мерзенних сатирів, що загрожують краю, і повертати священні реліквії на кшталт Гілки Кенарія, щоб захистити своїх сестер-дріад.",al={"завдання ілліяни","завдання лісової пісні"}},{q="Де знайти Ілліяну?",a="Вона обходить дозором околиці Святилища Аессіни в південно-західному Ашенвалі, пильнуючи стежки й ближні гаї.",al={"місце ілліяни","де знайти ілліяну","дріада лісової пісні"}},{q="Чому сатири загрожують дріадам?",a="Сатири — стародавні нічні ельфи, спотворені демонічною скверною, які втішаються оскверненням природи й поневоленням дітей Кенарія. Дріади уособлюють чисту, незаплямовану красу лісу, тож саме на них насамперед і спрямована злоба сатирів.",al={"чому сатири ненавидять дріад","дріади й сатири лор"}},{q="Чи допомагає Ілліяна Орді?",a="Ні. Ілліяна — союзниця нічних ельфів і всього Альянсу. Члени Орди, що забредуть до її галявини, побачать, що вона та її союзники налаштовані вороже.",al={"чи ілліяна вороже до орди","чи орда може говорити з ілліяною"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:illiyana-moonblaze"] = {n="Ілліяна Мунблейз",s="Ілліяна Мунблейз — незвичайна розвідниця й інтендантка нічних ельфів у Гаї Срібнокрилих в Ашенвалі. Разом із Вартовими Срібнокрилих вона забезпечує звитяжців Альянсу, що воюють із Дозорцями Пісні Війни. Хоч вона й має офіцерське звання, гостре чуття й розбійницька вдача вирізняють її серед звичних військових лав калдореїв.",h="Ілліяна Мунблейз — незвичайна розвідниця й інтендантка нічних ельфів у Гаї Срібнокрилих в Ашенвалі.",kw={"ілліяна мунблейз","вартові срібнокрилих","гай срібнокрилих","інтендантка","ущелина бойової пісні","розбійниця"},ang={["class:Rogue"]="Ілліяна — рідкісне видовище серед калдореїв: досвідчена тіньова ходачка й слідопитка, що відкрито служить пліч-о-пліч із регулярним військом, попри споконвічну зневагу суспільства.",["faction:Alliance"]="Для бійців Альянсу, що рушають на південь до спірного кордону в Ущелині Бойової Пісні, Ілліяна — головна інтендантка, що постачає зброю, обладунки й пайки.",["race:NightElf"]="Її розбійницька постать разюче контрастує зі звичними жрицями й вартовими й показує, як розвідники калдореїв пристосовують власні методи, щоб берегти Ашенваль."},sec={{t="Розвідниця поза рангами",b="Ілліяна Мунблейз — головна інтендантка Вартових Срібнокрилих, що отаборилися в Гаї Срібнокрилих. Та досить одного погляду, щоб зрозуміти: вона аж ніяк не звичайна вартова. З парою клинків і в темному корсеті, вона тримається радше як розбійниця чи піратка, ніж як дисциплінована воїтелька Елуни. Традиційна ієрархія вартових здавна ставилася до тих, хто має таке ремесло, насторожено, мало не прирівнюючи їх до розбійників поза законом. Проте її неперевершена хитрість і хист слідопитки роблять її безцінною в спірних лісах."},{t="Припаси для передової",b="Окрім незвичної розвідницької служби, Ілліяна видає спорядження добровольцям Альянсу, що готуються зійтися з кланом Бойової Пісні в Ущелині Бойової Пісні. Коли звитяжці здобувають прихильність Вартових Срібнокрилих, вона винагороджує їхню службу особливими пайками, спеціальними зіллями й майстерною зброєю, створеною саме для лісових сутичок. А ще вона лагодить зброю та обладунки втомлених бійців, що повертаються з передової, — і так не дає згаснути воєнним зусиллям вартових."}},faq={{q="Де знайти Ілліяну Мунблейз?",a="Вона в Гаю Срібнокрилих на південному сході Ашенвалю, неподалік від місця збору й порталу до Ущелини Бойової Пісні.",al={"місце ілліяни мунблейз","де ілліяна","інтендант сілверінґ"}},{q="Чи Ілліяна Мунблейз належить до Вартових?",a="Формально вона має офіцерське звання, щоб керувати постачанням, але звичайною Вартовою не є. За походженням вона ближча до калдорейських розвідників і розбійників — покликання, до якого традиційне суспільство Вартових здавна ставилося з підозрою.",al={"чи ілліяна вартова","звання ілліяни","фракція ілліяни"}},{q="Що Ілліяна пропонує поборникам Альянсу?",a="Вона інтендантка Вартових Срібнокрилих і пропонує тим, хто здобув прихильність цієї фракції, пакунки з припасами, бойове озброєння, персні, табарди й витратні засоби, придатні для боротьби в Ущелині Бойової Пісні.",al={"що продає ілліяна","нагороди ущелини співу війни","торговець ілліяна"}},{q="Чому вона схожа на розбійницю й поводиться як розбійниця?",a="Її вміння тримаються на скритності, хитрощах і смертоносному вистежуванні, а не на жрецькій побожності чи бойовій дисципліні Вартових. Хоча суспільство нічних ельфів часто вважало такі розбійницькі шляхи безчесними, мало не піратськими, її практичні навички виживання в дикій природі незамінні в скрутні часи.",al={"чому вона як розбійниця","ілліяна розбійниця лор","чому вона як пірат"}},{q="Чи лагодить вона спорядження?",a="Так, окрім особливого військового спорядження, вона пропонує звичайне лагодження зброї й обладунків захисникам Альянсу, що відпочивають у гаю.",al={"чи ілліяна лагодить","ремонт у сілверінґу","ремонт у гаю сілверінґ"}},{q="Які пакунки з припасами вона роздає?",a="Вона допомагає бійцям Альянсу через завдання з постачання — з Базовими, Стандартними й Поліпшеними пакунками припасів Вартових, — забезпечуючи захисників на передовій найпотрібнішим для бою.",al={"пакунки вартових","завдання ілліяни","пакунки ущелини співу війни"}}},fp="18,371,25.572.0,28.478.0,36.125.0,48.241.0,47.221.0,39.282.0,35.148.0,37.188.0"}
P.entries["npc:ilthalaine"] = {n="Ілталайн",s="Ілталайн — охоронець, нічний ельф, що стоїть на сторожі священної долини Тінедол у Тельдрассилі. Він — перший, хто вітає й наставляє молодих нічних ельфів, що роблять найперші кроки у світ. Пильний і суголосний із дикою природою, він спрямовує новачків підтримувати хистку рівновагу природи на вітті Світового Дерева.",h="Ілталайн — охоронець, нічний ельф, що стоїть на сторожі священної долини Тінедол у Тельдрассилі.",kw={"ілталайн","консерватор","охоронець","тінедол","тельдрассил","сигіл","наставники","алдрассил"},ang={["class:Druid"]="Для майбутніх друїдів наука Ілталайна про вилов і природну рівновагу — найперші практичні уроки засад Кола Кенарія.",["faction:Alliance"]="Він уособлює спокійну, тривку пильність калдореїв і приймає нових звитяжців на службу Дарнасусу й ширшому Альянсу.",["race:NightElf"]="Ілталайн — перший наставник, якого зустрічає кожен молодий нічний ельф; він дає основоположну мудрість про опіку й священну рівновагу їхнього новознайденого дому на Тельдрассилі."},sec={{t="Охоронець долини",b="Стоячи одразу біля серця Тінедолу, Ілталайн часто перший, кого бачить молодий нічний ельф на початку своєї подорожі. Він стежить за лісовими стежками й помічає ледь відчутні зміни в лісі, невидимі для звичайного ока. Його обов'язок — вітати родичів, що повертаються, і дбати, щоб кожен щойно пробуджений захисник був укорінений у традиціях свого народу й готовий до відповідальності, що приходить із доглядом за Тельдрассилом."},{t="Рівновага природи",b="Heavy spring rains have allowed the nightsaber and thistle boar populations in Shadowglen to grow beyond what the glade can feed. Ilthalaine asks young defenders to thin their numbers so that the woodland's other creatures can flourish and nature's balance can be preserved."},{t="Провідник до дисципліни",b="Beyond testing an adventurer's martial prowess against local wildlife, Ilthalaine directs young elves toward their chosen callings. Entrusting each traveler with a class sigil, he points them directly to their mentors within the Aldrassil sanctuary—whether they follow the path of the warrior, druid, rogue, priest, or hunter. Through him, every novice learns where their service to the Kaldorei begins."}},faq={{q="Хто такий Ілталайн?",a="Ілталайн — калдорейський наглядач у Тінедолі, затишному стартовому куточку Тельдрассила. Він першим дає завдання щойно створеним нічним ельфам-шукачам пригод і знайомить їх з обов'язками та станом лісу.",al={"лор ілталайна","хто цей нічний ельф","ілталайн завдання тінеділ"}},{q="Яка роль Ілталайна в Тінедолі?",a="Він пильнує тварин у Тінедолі й дбає, щоб молоді нічні ельфи розуміли, як важлива рівновага природи. Він посилає новачків на перші полювання й направляє їх до наставників їхніх класів у великому дереві Алдрассил.",al={"що робить ілталайн","чому він тут","мета ілталайна"}},{q="Чому Ілталайн хоче, щоб прорідили молодих нічних шаблезубів і вепрів?",a="Heavy spring rains have increased the nightsaber and thistle boar populations beyond what Shadowglen can support. Ilthalaine asks for a cull to preserve nature's balance.",al={"завдання рівноваги природи","навіщо вбивати шаблезубів","навіщо вбивати вепрів"}},{q="Що за знаки він роздає?",a="Ілталайн дає новачкам знаки з написами, різні для кожного класу, і велить їм знайти своїх наставників — жриць, друїдів, воїнів, розбійників, — що мешкають серед коріння Алдрассила.",al={"витравлений сигіл","простий сигіл","зелений сигіл","зашифрований сигіл","освячений сигіл"}},{q="Де знайти Ілталайна?",a="Він стоїть просто на центральній стежці Тінедолу, трохи на південь від величезного дупла Алдрассила в Тельдрассилі.",al={"місце ілталайна","де ілталайн","координати ілталайна"}},{q="Чи Ілталайн пов'язаний із друїдами чи з Вартовими?",a="Ілталайн — загальний доглядач і представник калдореїв у Тінедолі. Хоча він глибоко відчуває природу й поділяє друїдський ідеал гармонії, працює він від імені всіх очільників Дарнасуса й наставляє новачків будь-якого ремесла.",al={"чи ілталайн друїд","якої фракції ілталайн"}}},fp="10,368,20.455.0,21.274.0,21.405.0,18.238.0,40.249.0,64.170.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="Корчмарка Еллісон",s="Корчмарка Еллісон тримає «Позолочену Троянду» — одну з найжвавіших корчем у самому центрі Стормвінда. Корчма стоїть у серці Торгового Кварталу, просто між банком і аукціоном, і Еллісон пропонує втомленим мандрівникам і місцевим купцям прив'язати камінь повернення, освіжні напої й прихисток.",h="Корчмарка Еллісон тримає «Позолочену Троянду» — одну з найжвавіших корчем у самому центрі Стормвінда.",kw={"корчмарка еллісон","позолочена троянда","корчма","торговий квартал","камінь повернення","стормвінд"},ang={["faction:Alliance"]="Як господиня найдоступнішої корчми в торговому серці Стормвінда, Еллісон — одне з найзнайоміших облич для звитяжців Альянсу, що повертаються з передової, щоб відпочити й покласти здобич до банку."},sec={{t="Гостинність у Торговому Кварталі",b="«Позолочена Троянда», що стоїть просто між гамірним аукціоном і головними міськими сховищами, — осередок життя для шукачів пригод, що прибувають до Стормвінда. Корчмарка Еллісон стоїть за головним шинквасом на першому поверсі й тримає лад серед безперервного потоку крамарів, найманців і заїжджих дипломатів. Окрім ночівлі й прив'язки каменя повернення, вона часто бере участь у місцевих святах і дає дрібні доручення мандрівним героям, що шукають перепочинку в столиці."}},faq={{q="Де знайти Корчмарку Еллісон?",a="Корчмарка Еллісон стоїть за шинквасом на першому поверсі «Позолоченої Троянди». Ця корчма — у самому Торговому Кварталі Стормвінда, між центральним банком і аукціоном.",al={"місце еллісон","де корчмарка еллісон","корчмарка позолоченої троянди"}},{q="Які послуги надає Корчмарка Еллісон?",a="Вона надає звичайні послуги корчмарки: гравці можуть прив'язати до «Позолоченої Троянди» свій камінь повернення, купити їжу й напої для відпочинку, а час від часу — поспілкуватися з нею під час сезонних подій і свят у місті.",al={"послуги еллісон","що робить еллісон","чи можна прив'язати камінь повернення"}},{q="Чи дає Корчмарка Еллісон якісь завдання?",a="Так, Еллісон бере участь у різних сезонних святкуваннях упродовж року, а часом пов'язана й з міськими дорученнями для мандрівників, що шукають допомоги по всьому світу.",al={"завдання еллісон","завдання корчмарки еллісон"}}},fp="17,295,33.512.0,35.204.0,43.210.0,40.201.0"}
P.entries["npc:innkeeper-farley"] = {n="Шинкар Фарлі",s="Корчмар Фредрік Фарлі порядкує в корчмі «Лев'яча Гордість» у Ґолдширі, забезпечуючи їжею, ночівлею та каменями повернення подорожніх, що проходять Лісом Елвінн. Усіма шанований і спостережливий, він часто притримує загублену пошту й вислуховує біди шукачів пригод із дороги.",h="Корчмар Фредрік Фарлі порядкує в корчмі «Лев'яча Гордість» у Ґолдширі, забезпечуючи їжею, ночівлею та...",kw={"фарлі","корчмар","лев'яча гордість","ґолдшир","корчма","сталван містмантл"},ang={["faction:Alliance"]="Для новобранців, що вирушають із Долини Нортширу, шинквас Фарлі в «Лев'ячій Гордості» — часто найперше місце, де вони прив'язують свій камінь повернення й купують припаси."},sec={{t="Опора Ґолдширу",b="Родина Фарлі тримає корчму «Лев'яча Гордість» ще з часів правління короля Ллейна Рінна I. Разом із дружиною Веріною та донькою Анною Фредрік веде заклад гостинною рукою й гострим оком. Великими міцними руками, що добре надаються розбороняти бійки в таверні чи виставляти буйних гостей, він тримає лад на одній із найжвавіших стоянок королівства. Хоч його дні минають за наливанням елю й подаванням сиру, він носить у собі тихе горе — втрату брата Франдіса, вартового, що загинув у Лордероні під час чуми Погибелі."},{t="Покинута скриня гінця",b="Оскільки Ґолдшир лежить на перехресті між Стормвіндом, Вестфолом і Сутінколіссям, Фарлі чує чимало чуток і має справу з дивними подорожніми. Так, він якось прихистив гінця, що в жаху вибіг у ніч, покинувши свою сумку. Фарлі надійно сховав залишені послання в скрині нагорі — серед них і недоставлений лист, адресований колишньому шкільному вчителеві Сталвану Містмантлу, який згодом стає важливою зачіпкою для слідчих, що простежують шлях пропащого вчителя."}},faq={{q="Хто такий Шинкар Фарлі?",a="Фредрік Фарлі — власник корчми «Лев'яча Гордість» у Ґолдширі. Його родина тримає корчму вже кілька поколінь, ще з часів Короля Ллейна Рінна Першого. Він веде справу разом зі своєю дружиною Веріною, даючи прихисток і припаси мандрівникам, що перетинають Ліс Елвінн.",al={"шинкар фарлі","фредрік фарлі","хто шинкар ґолдшира"}},{q="Що Фарлі знає про Сталвана Містмантла?",a="Фарлі пам'ятає наляканого кур'єра, який глупої ночі втік із «Лев'ячої Гордості», покинувши кілька доставок. Фарлі сховав покинуті листи в скриню нагорі, і серед них є недоставлений лист Сталванові Містмантлу, який слідчі можуть забрати.",al={"фарлі сталван","лист сталвана ґолдшир","легенда сталвана фарлі"}},{q="Де брат Фарлі?",a="Брат Фредріка, Франдіс Фарлі, подався з півдня до північного королівства Лордерон, щоб найнятися охоронцем караванів. Під час Третьої війни надійшла звістка, що Франдіса вбила чума нежиття, і Фредрік досі не може оговтатися від горя.",al={"брат фарлі","франдіс фарлі","що сталося з братом фарлі"}},{q="Які послуги Фарлі надає в корчмі?",a="Фарлі прив'язує камені повернення мандрівників, здає кімнати й продає багато різних напоїв, соків і сирів з усього Альянсу — від Альтеракського Швейцарського Сиру й Гострого Даларанського Сиру до місцевого Стормвіндського Брі.",al={"послуги гордості лева","їжа й напої фарлі","камінь повернення ґолдшир"}}},fp="16,265,19.550.0,29.508.1,24.280.0,47.282.0,26.219.0,45.209.0"}
P.entries["npc:innkeeper-firebrew"] = {n="Шинкар Файрбрю",s="Шинкар Файрбрю тримає корчму «Кам'яний Вогонь» у жвавих Торгових Рядах Айронфорджа. Привітний господар і для втомлених горян, і для високих гостей, він подає ситні дворфійські страви й дає мандрівникам відпочити під горою.",h="Шинкар Файрбрю тримає корчму «Кам'яний Вогонь» у жвавих Торгових Рядах Айронфорджа.",kw={"шинкар файрбрю","корчма","кам'яний вогонь","майдан","айронфордж","ель"},ang={["faction:Alliance"]="Як головний шинкар біля передньої брами, Файрбрю дає чужоземним мандрівникам Альянсу центральний, безпечний прихисток для відпочинку в столиці Короля Маґні Бронзбірда.",["race:Dwarf"]="Для дворфів, що повертаються з дозорів по Каз Модану, корчма Файрбрю — затишне домашнє тепло й незмінний кухоль дворфійського стауту."},sec={{t="Господар «Кам'яного Вогню»",b="Заклад Шинкаря Файрбрю стоїть у центральному колі Торгових Рядів, і часто це перший прихисток для мандрівників, що входять крізь Велику Браму Айронфорджа. За шинквасом, заставленим кухлями елю, бурдюками стауту й печеними окостами, Файрбрю гостинно приймає шукачів пригод, що прямують до засніжених перевалів Дун Мороґа чи вглиб гірського королівства. Його корчма — жваве перехрестя, де рудокопи, стрільці й посланці збираються, щоб сховатися від протягів у тунелях і обмінятися оповідями біля вогнища."}},faq={{q="Де знайти Шинкаря Файрбрю?",a="Шинкар Файрбрю — у таверні «Кам'яний Вогонь» на південному краю Торгових Рядів Айронфорджа.",al={"місце файрбрю","де шинкар файрбрю","шинкар айронфорджа"}},{q="Що продає Файрбрю?",a="Він пропонує звичайний для корчмаря припас, а насамперед — ситну дворфійську їжу. Мандрівники можуть купити напої від місцевого дворфійського стауту й меду до привізних вин, а також м'ясо й поживні страви, що згодяться в довгій дорозі.",al={"що продає файрбрю","напої файрбрю","їжа таверни стоунфайр"}},{q="Чи Файрбрю належить до якоїсь дворфійської пивоварної родини?",a="Прізвище в нього Файрбрю, але про його родинні зв'язки достеменно нічого не відомо.",al={"родина файрбрю","чий родич файрбрю"}},{q="Які послуги він надає мандрівникам?",a="Як шинкар, Файрбрю дозволяє мандрівникам Альянсу прив'язати свої камені повернення до таверни «Кам'яний Вогонь» і пропонує теплу постіль, щоб відпочити й набратися сил під горою.",al={"чи можна прив'язати камінь повернення","камінь повернення айронфордж"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="Корчмар Ґроск",s="Корчмар Ґроск тримає корчму в Гострому Пагорбі, даючи втомленим мандрівникам їжу, питво й місце для відпочинку в центральному Дуроторі. Розташований на жвавій дорозі між Долиною Випробувань та Оргріммаром, його заклад — головний перепочинок для молодих шукачів пригод Орди, що вирушають у широкий світ.",h="Корчмар Ґроск тримає корчму в Гострому Пагорбі, даючи втомленим мандрівникам їжу, питво й місце для...",kw={"корчмар ґроск","корчма","гострий пагорб","укор","перепочинок","дуротар"},ang={["faction:Horde"]="Для орків, тролів і тауренів-гостей, що щойно пройшли бойове хрещення й мандрують на північ із Долини Випробувань чи Села Сен'джин, корчма Ґроска — перше справжнє містечко й домашнє вогнище на шляху до Оргріммара."},sec={{t="Гостинність у червоних пустках",b="Гострий Пагорб — важливе поселення на перехресті, що єднає південні тренувальні землі Дуротару з високими мурами Оргріммара. У центрі цієї станції стоїть Корчмар Ґроск — орк, якому доручено давати притулок воїнам, розвідникам і пеонам. Його корчма — перепочинок від суворої пустельної спеки, із запасом простих харчів, ситного м'яса й прохолодної води для кожного мандрівника, що проходить під її міцними сволоками."},{t="Перепочинок пеона",b="Окрім мандрівників, Ґроск допомагає й місцевим робітникам, на яких тримається Дуротар. У завданні «Тягар пеона» боязкий робітник Укор, що відніс харчі аж до Долини Випробувань і виявив, що вони там не потрібні, просить мандрівників віднести вантаж назад до корчми Ґроска в Гострому Пагорбі."}},faq={{q="Де перебуває Корчмар Ґроск?",a="Корчмар Ґроск стоїть у корчмі на Гострому Пагорбі, просто в центрі Дуротару, при головній дорозі на північ, до Оргріммара.",al={"місце ґроска","де корчмар ґроск","корчмар гострого пагорба"}},{q="Які послуги надає Корчмар Ґроск?",a="Ґроск — корчмар, у якого шукачі пригод Орди можуть прив'язати свій камінь повернення до Гострого Пагорба. Також він продає просту їжу, воду й м'ясо, щоб між мандрівками відновлювати здоров'я й ману.",al={"що робить ґроск","торговець ґроск","камінь повернення гострий пагорб"}},{q="Чи дає Корчмар Ґроск якісь завдання?",a="Він пов'язаний із завданням «Тягар робітника»: приймає вантаж харчів, який робітник Укор, наляканий звірами Дуротару, не наважився сам донести до Гострого Пагорба.",al={"завдання ґроска","здача тягар пеона"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="Корчмарка Гришка",s="Корчмарка Гришка — орчиха-господиня, що тримає корчму «Зламане Ікло» в Долині Сили Оргріммара. Вона перша зустрічає мандрівників, які входять у міську браму: прив'язує камені повернення, годує й напуває шукачів пригод Орди. Вона підтримує тісні зв'язки з мисливцями й розвідниками по всьому Дуротару й Пустках, щоб у її таверні не переводилися добірні шматки м'яса.",h="Корчмарка Гришка — орчиха-господиня, що тримає корчму «Зламане Ікло» в Долині Сили Оргріммара.",kw={"корчмарка гришка","зламане ікло","корчма","долина сили","камінь повернення","зарг","оргріммар"},ang={["faction:Horde"]="Для кожного мандрівника Орди, що прибуває до Дуротару, корчма Гришки в Долині Сили — найчастіше головне місце, де можна прив'язати камінь повернення й поповнити припаси, перш ніж рушати вглиб Калімдору.",["profession:Cooking"]="Кухарі оцінять вибагливе піднебіння Гришки: вона не шкодує зусиль, щоб діставати добірне м'ясо від мисливців, що стоять аж у Пустках."},sec={{t="Вогнище Долини Сили",b="Стоячи за шинквасом «Зламаного Ікла», Гришка порядкує в одній із найлюдніших корчем Орди. Її заклад, що стоїть одразу за головною брамою Оргріммара в Долині Сили, — перше місце відпочинку для воїнів, гінців і новоприбулих поборників, що шукають притулку під стягом Тралла."},{t="Смак свіжого м'яса",b="Щоб тримати гамірну таверну в посушливому каньйоні, потрібне надійне постачання. Гришка славиться любов'ю до свіжого м'яса й покладається на перевірених мисливців по всіх землях Орди. Такі товариші, як Зарг на Перехресті й Ґрімтак у Дуротарі, раз у раз надсилають до «Зламаного Ікла» свою найкращу дичину, щоб догодити її вимогливому смакові."}},faq={{q="Хто така Корчмарка Гришка?",a="Корчмарка Гришка — орчиха, що тримає таверну «Зламане Ікло» в Долині Сили Оргріммара. Вона вітає мандрівників Орди, прив'язує камені повернення й продає їжу та напої втомленим шукачам пригод.",al={"хто така гришка","гришка оргріммар","корчмарка зламаного бивня"}},{q="Де знайти Корчмарку Гришку?",a="Вона в таверні «Зламане Ікло» в Долині Сили — першому великому районі, куди ви потрапляєте, минувши головну південну браму Оргріммара.",al={"де гришка","місце зламаного бивня","корчмарка долини сили"}},{q="Звідки Гришка бере м'ясо?",a="Гришка покладається на друзів і розвідників по всіх землях Орди, які поповнюють її комору, — зокрема на Зарга з Перехрестя в Пустках і Ґрімтака в Дуротарі, які надсилають їй добірну дичину.",al={"звідки гришка бере їжу","постачання зламаного бивня","доставка м'яса зарґа"}},{q="Які послуги надає Гришка?",a="Гришка може прив'язати ваш камінь повернення до «Зламаного Ікла», щоб ви могли переноситися просто до Оргріммара. Також вона продає різну їжу, хліб і напої, що відновлюють здоров'я й ману.",al={"чи можна прив'язати камінь повернення","камінь повернення зламаний бивень","товари гришки"}},{q="Чи пов'язана Гришка з гніздовищем вітряних вершників?",a="Мандрівники, яких із Пусток посилають із летючими дорученнями, часто передають пакунки просто Гришці, а вже потім їх відправляють нагору до Дораса — наглядача вітряних вершників, що сидить високо на плато над містом.",al={"завдання дораса","майстер вітряних вершників зламаний бивень","поїздка до корчми оргріммара"}},{q="Яка вдача в Гришки?",a="Гришка — практична й гостинна орчиха-господиня, яка цінує добре м'ясо, пряму мову й порядок: у її таверні завжди повно припасів для безперервного потоку воїнів Орди, що проходять через столицю.",al={"чи гришка дружня","яка гришка"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Корчмар Келдамір",s="Корчмар Келдамір порядкує вогнищем і ночівлею в центральній корчмі Доланаара на Тельдрассилі. Він пропонує їжу, питво й місце для відпочинку молодим нічним ельфам, що вирушають із Тінедолу в ширше віття Світового Дерева.",h="Корчмар Келдамір порядкує вогнищем і ночівлею в центральній корчмі Доланаара на Тельдрассилі.",kw={"корчмар келдамір","корчма","доланаар","вогнище","тельдрассил","тінедол","відпочинок"},ang={["race:NightElf"]="Для нічних ельфів, що щойно вирушили з навчальних угідь Тінедолу, корчма Келдаміра — зазвичай найперший дім удалині від дому, де вони прив'язують свої камені повернення."},sec={{t="Вогнище Доланаара",b="Доланаар — перше село, до якого дістаються новачки, покинувши затишну долину Алдрассила. Корчмар Келдамір утримує центральний прихисток громади, пропонуючи хліб, джерельну воду й м'які ліжка під шатром Тельдрассила. Мандрівники, вартові й молоді новачки, що прямують до Дарнасуса, часто зупиняються біля його стійки, щоб перепочити духом, прив'язати камені повернення й запастися харчами на дорогу через віття."},{t="Доставки до села",b="Утримувати корчму високо в гілках означає потребувати сталого постачання з поблизьких поселень і від ремісників. Тутешніх гінців часто посилають просто до стійки Келдаміра скинути товар, і це прямо вплітає його в щоденну торгівлю й постачання, завдяки яким поселення Доланаар живе злагоджено."}},faq={{q="Де знайти Корчмаря Келдаміра?",a="Келдамір — у головній корчмі в самому серці Доланаара, першого великого поселення на південь від Тінедолу на гілках Тельдрассила.",al={"місце келдаміра","де корчмар келдамір","де корчмар доланаара"}},{q="Які послуги надає Корчмар Келдамір?",a="Він місцевий корчмар: у нього можна прив'язати свій камінь повернення до його вогнища, купити найпростіші припаси — воду, молоко, сік і хліб — або вийти з гри відпочилим під його дахом.",al={"товари келдаміра","що продає келдамір","їжа корчми доланаара"}},{q="Які завдання пов'язані з Корчмарем Келдаміром?",a="Він отримувач у місцевому кур'єрському завданні «Посилка для Доланаара» й приймає пакунки, призначені для утримання й постачання корчми поселення.",al={"завдання келдаміра","здача доставки доланаара"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="Корчмар Норман",s="Корчмар Норман доглядає вогнище в головній таверні Торгового Кварталу Андерсіті. Тихий і сумлінний Відступник, він дає мандрівникам Орди відпочинок, прив'язує камені повернення й частує їжею на будь-який смак — і живих, і мертвих.",h="Корчмар Норман доглядає вогнище в головній таверні Торгового Кварталу Андерсіті.",kw={"корчмар норман","таверна","торговий квартал","андерсіті","камінь повернення","переддень усіх святих"},ang={["faction:Horde"]="Для живих союзників Орди, що навідуються до Андерсіті, таверна Нормана — одне з небагатьох місць, де можна безпечно відпочити й набратися сил у цій неприязній підземній твердині.",["race:Undead"]="Норман дає побратимам-Відступникам місце зустрічі в самому серці Торгового Кварталу, де можна дати спочинок кісткам між дорученнями Темної Леді."},sec={{t="Гостинність у підземеллі",b="У гамірному Торговому Кварталі під зруйнованою Столицею Лордерона Корчмар Норман дає притулок посланцям, найманцям і шукачам пригод, що проходять через твердиню Відступників. Попри вогкий холод і алхімічний сморід Андерсіті, таверна Нормана лишається жвавим осередком для мандрівників: тут прив'язують камені повернення, діляться новинами з усього Азероту чи готуються до вилазок у Чумні Землі."},{t="Святкові дивацтва",b="Зазвичай Норман сумлінно продає харчі й порядкує кімнатами, але з приходом Переддня Усіх Святих відкривається його дивніший бік. На свято Норман долучається до веселощів і вимагає від сміливих відвідувачів чудернацьких витівок — скажімо, кудкудакати, як курка, — щоб ті заробили святкові ласощі на кшталт м'ятних цукерок Андерсіті."}},faq={{q="Де знайти Корчмаря Нормана?",a="Корчмар Норман — у головній таверні Торгового Кварталу Андерсіті, на південному вигині внутрішнього кільця.",al={"місце нормана","корчмар андерсіті","де норман"}},{q="Які послуги надає Корчмар Норман?",a="Він один із головних корчмарів Андерсіті. Гравці можуть прив'язати до його таверни свої камені повернення, купити їжу й напої, придатні і для живих, і для нежиті, або безпечно вийти з гри й відпочити.",al={"послуги нормана","камінь повернення андерсіті"}},{q="Чому Норман просить відвідувачів кудкудакати, як курка?",a="Під час свята Переддня Усіх Святих Норман долучається до традиційних святкових витівок. Шукачі пригод, які хочуть отримати особливі святкові м'ятні цукерки, мусять забути про гордість і покудкудакати, як курка, щоб здобути його прихильність.",al={"м'ятні курки","завдання нормана з куркою"}},{q="Чи Норман родич Корчмаря Бейтса?",a="Вони не згадують одне одного ні за життя, ні після смерті, і про спорідненість між ними нічого не відомо. Їхні імена разом — жартівливе посилання творців світу на корчмаря Нормана Бейтса з фільму «Психо».",al={"норман і бейтс","корчмар бейтс і норман"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="Корчмарка Пала",s="Корчмарка Пала порядкує в «Коті й Шамані» — гамірній корчмі на нижньому ярусі Тандер Блафа. Вона пропонує шукачам пригод прив'язати камінь повернення, холодні напої й місце для відпочинку між мандрами Малгором і далі.",h="Корчмарка Пала порядкує в «Коті й Шамані» — гамірній корчмі на нижньому ярусі Тандер Блафа.",kw={"корчмарка пала","кіт і шаман","корчма","камінь повернення","тандер блаф","малгор"},ang={["faction:Horde"]="Орки, тролі й Відступники, що навідуються до Малгору, знаходять у корчмі Пали зручну базу просто біля підйомників.",["race:Tauren"]="Для тауренів, які повертаються додому з рубежів Калімдору, Пала — знайоме привітне обличчя під височенними тотемами центральних столових гір."},sec={{t="Гостинність на нижньому узвишші",b="На нижньому узвишші широких столових гір Тандер Блафа Корчмарка Пала дбає про вогнище в «Коті й Шамані». Цей заклад — одне з головних місць зустрічі для мандрівників, що сходять із центральних підйомників чи прибувають із розлогих рівнин Малгору. Невсипно наглядаючи за загальною залою, Пала дбає, щоб утомлені воїни, мандрівні друїди й гості-союзники Орди знаходили тут надійний притулок, теплий напій і другу домівку."}},faq={{q="Де знайти Корчмарку Палу?",a="Пала — у таверні «Кіт і Шаман», що стоїть на нижньому ярусі Тандер Блафа, неподалік від головних підйомників міста.",al={"місце пали","де пала","карта корчмарки пали"}},{q="Які послуги вона надає мандрівникам?",a="Як і інші корчмарі Калімдору, Пала може прив'язати ваш камінь повернення до «Кота і Шамана», щоб ви могли миттю туди повернутися. Також вона продає просту їжу й напої, що відновлюють здоров'я й ману.",al={"послуги пали","чи можна прив'язати камінь повернення тандер блафф","що продає пала"}},{q="Як називається її таверна?",a="Її таверна зветься «Кіт і Шаман» — це заклад для нескінченного потоку мандрівників Орди, що проходять нижнім ярусом міста.",al={"кіт і шаман","назва нижньої корчми тандер блафа","назва корчми пали"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="Дізнавач Вішас",s="Дізнавач Джеймс Вішас — майстер катувань Багряного Хрестового Походу, що служить у глибині крила Кладовища Багряного Монастиря. Відомий своїм верескливим голосом і неприхованою жорстокістю, він зі збоченою насолодою ламає полонених і випробовує межі смертної плоті. Мало хто з тих, хто потрапляє до його катівні, виходить звідти з цілим розумом чи тілом.",h="Дізнавач Джеймс Вішас — майстер катувань Багряного Хрестового Походу, що служить у глибині крила Кладовища...",kw={"дізнавач вішас","катівня","кладовище","багряний монастир","ненсі вішас","воррел сенґутц"},ang={["class:Priest"]="Бачити, як Вішас прикривається фанатизмом, щоб освятити жахливі каліцтва, — моторошний доказ того, як свята мета може скиснути в покручене безумство.",["faction:Alliance"]="Герої Альянсу, які натрапляють на справи рук Вішаса, швидко розуміють: Багряний Хрестовий Похід більше не розрізняє чудовиськ Погибелі й безневинних живих мандрівників.",["race:Undead"]="Для Відступників Вішас уособлює лицемірну злобу живих фанатиків: він катує полонену нежить із чистої злості, а сам запевняє, що служить Святому Світлу."},sec={{t="Скальпель Великого Інквізитора",b="У темних склепах і на цвинтарі Багряного Монастиря дізнавач Вішас «опікується» полоненими ворогами Хрестового Походу. Поки фанатики назовні марширують у сяйливих обладунках під стягами чистоти, Вішас уособлює похмуру правду, що стоїть за їхнім походом: неприборканий садизм, прикритий праведним релігійним гнівом. Допит для нього — не просто справа розвідки, а улюблене ремесло: він смакує муки полонених Відступників, захоплених прислужників Погибелі й будь-яких живих мандрівників, яких на своє лихо затаврували єретиками."},{t="Тихе родинне життя",b="За закривавленими фартухами й криками катівні Вішас веде дивне подвійне життя примірного сім'янина. За мурами монастиря його родина — дружина Ненсі Вішас і старший родич, Дідусь Вішас, — мирно живе у відлюдній хатині на східному березі Озера Лордамер у Горах Альтерак. Вішас навіть приносить у домашнє життя моторошні трофеї від своїх жертв: він зірвав із пальця полоненого Відступника на ім'я Воррел Сенґутц дорогу його серцю обручку, щоб подарувати її Ненсі."}},faq={{q="Де знайти Дізнавача Вішаса?",a="Дізнавач Вішас — глибоко в крилі Цвинтаря Багряного Монастиря, у Галявинах Тірісфалю. Він порядкує в похмурій катівні, заставленій залізними клітками й закривавленими дибами.",al={"місце вішаса","де дізнавач вішас","кімната вішаса"}},{q="Чому Вішас катує в'язнів?",a="Багряний Хрестовий Похід виправдовує катування полонених тим, що так викорінюють скверну Погибелі й здобувають відомості, але сам Вішас просто насолоджується болем, який завдає. Він страшенно пишається своєю жорстокістю й вважає тортури своїм мистецтвом.",al={"чому вішас катує","мотив вішаса"}},{q="Хто такий Воррел Сенґутц?",a="Воррел Сенґутц — полонений, якого Вішас ув'язнив і жорстоко катує на Цвинтарі Монастиря. Вішас тижнями мучив Воррела й украв його обручку, щоб подарувати своїй дружині.",al={"воррел сенґутц в'язень","хто в'язень у клітці"}},{q="Де живе родина Вішаса?",a="Його родина живе далеко від Монастиря, у непримітній хатині на східному березі Озера Лордамер у Горах Альтерак. Там тихо живуть його дружина Ненсі й Дідусь Вішас, ніби й не знаючи про його звірства.",al={"ненсі вішас місце","дідусь вішас","будинок родини вішаса"}},{q="Кого Вішас тримає в полоні?",a="Багряний Хрестовий Похід вважає нежить ворогом. Серед в'язнів Вішаса — Відступник Воррел Сенґутц, якого він катує вже кілька тижнів.",al={"в'язні вішаса","кого катує вішас","полонений воррел"}},{q="Який у Вішаса голос і манери?",a="Ті, хто з ним стикався, добре пам'ятають його скрипучий пронизливий голос, хихотливий регіт і моторошне збудження, яке охоплює його щоразу, коли випадає нагода вирвати таємниці з непокірної жертви.",al={"голос вішаса","характер вішаса"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:islen-waterseer"] = {n="Іслен Вотерсір",s="Іслен Вотерсір — шанована тауренка-шаманка, що живе біля тихої рибальської хатини на Сходах Тідуса, звідки видно східне море Пусток. Вона в глибокому єднанні з духами води й проводить учнів крізь випробування, потрібні, щоб злагодитися з цією стихією. Шамани-початківці з усієї Орди шукають її мудрості, щоб здобути Тотем Води.",h="Іслен Вотерсір — шанована тауренка-шаманка, що живе біля тихої рибальської хатини на Сходах Тідуса, звідки...",kw={"іслен вотерсір","шаманка","тотем води","водяна сапта","сходи тідуса","пустки"},ang={["class:Shaman"]="Іслен — незамінна наставниця на вашому шляху: вона проводить вас крізь стихійні обряди, потрібні, щоб поєднатися з духами води й здобути Тотем Води.",["faction:Horde"]="Іслен, що живе на узбережжі Пусток, — тиха духовна опора Орди, яка радо приймає мандрівників і з Оргріммара, і з Тандер Блафа.",["race:Tauren"]="Іслен утілює традиційну шану тауренів до дарів Земної Матері: вона обрала самотнє життя біля моря, щоб відчувати найтонші течії дикої природи."},sec={{t="Самітниця зі Сходів Тідуса",b="Далеко від гамірного Перехрестя й таборів Пусток Іслен Вотерсір живе на скелястому узбережжі, відомому як Сходи Тідуса. Тут, де посушливі рівнини розбиваються об Велике Море, присутність духів води відчутна всюди й первісно сильна. Іслен не живе в гримучих залах чи гамірних містах — вона обрала цю тиху заставу й присвячує дні тому, щоб слухати припливи й допомагати шаманам, які прагнуть єднання з плинною стихією."},{t="Майстриня Водяної Сапти",b="Щоб зрозуміти воду, мало просто вчитися: потрібні внутрішня гармонія й духовне чуття. Іслен навчає шукачів готувати Водяну Сапту — священний напій, що прориває завісу між смертними чуттями та проявами стихій. Її науки нагадують шаманам, що вода така ж непохитна й глибока, як і плинна та цілюща, і вимагає безмежної поваги від кожного, хто сподівається покликати її на допомогу."},{t="Зв'язки крізь дикі краї",b="Хоч Іслен живе тихо на узбережжі, її духовний вплив і зв'язки сягають усього Калімдору. Вона давно й міцно дружить із Ґретою Моссгуф — іще однією мудрою тауренкою, обізнаною в цілющих мистецтвах. Завдяки цим зв'язкам знання Іслен про очисну суть води виходять далеко за межі Пусток і навіть дають духовну допомогу землям, ураженим глибокою скверною."}},faq={{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — мудра тауренка-шаманка, що живе на узбережжі Пусток, біля Сходів Тідус. Вона має рідкісний, глибокий зв'язок із духами стихії води й духовно наставляє шаманів, які прагнуть здобути свій Тотем Води.",al={"лор іслен вотерсір","хто така іслен","тидус стейр таурен"}},{q="Чому шамани приходять до неї?",a="Під час випробувань «Поклик Води» наставники з Дуротару, Оргріммара й Тандер Блафа посилають шаманів Орди до Іслен. Вона перевіряє, як вони розуміють стихію, і вчить їх готувати Водяну Сапту, щоб на власні очі побачити водяних елементалів.",al={"чому шамани йдуть до іслен","нпс поклик води","завдання шамана узбережжя пусток"}},{q="Де знайти Іслен Вотерсір?",a="Вона сидить біля невеликої рибальської хижі на Сходах Тідус, на східному узбережжі Пусток, на південь від Узбережжя Крамарів.",al={"місце іслен","де іслен вотерсір","знайти іслен"}},{q="Що таке Водяна Сапта, про яку вона говорить?",a="Водяна Сапта — особливий духовний напій, зварений зі складників стихій. Випивши його, шаман може поглядом проникнути крізь матеріальний світ і побачити приховані духи води, що живуть у священних джерелах і припливах.",al={"значення водяної сапти","що робить сапта"}},{q="Хто така Ґрета Моссгуф, подруга Іслен?",a="Ґрета Моссгуф — давня тауренська товаришка Іслен, що також знається на духовних мистецтвах. Їх пов'язує багаторічна дружба, і вони радяться одна з одною щодо духовного очищення й цілющої сили води.",al={"зв'язок із ґретою моссгуф","подруга іслен"}},{q="Чи належить Іслен до певної фракції чи племені?",a="Іслен — союзниця Орди й Об'єднаних племен тауренів під проводом Кайрна Бладгуфа. Хоча вона живе на узбережжі відлюдницею, охоче допомагає шаманам-оркам, тролям і тауренам, яких посилають старійшини Орди.",al={"фракція іслен","чи іслен з орди"}}},fp="15,354,25.454.0,27.423.0,22.406.0,23.251.0,33.258.0,33.151.0,38.240.0,37.207.0,49.206.0"}
P.entries["npc:iverron"] = {n="Іверрон",s="Іверрон — молодий нічний ельф, якого можна знайти в Тінедолі, захищеному стартовому гіллі Тельдрассила. Уражений отрутою дедалі неспокійніших павуків лісу, він своєю бідою рано попереджає про скверну, що росте в Світовому Дереві.",h="Іверрон — молодий нічний ельф, якого можна знайти в Тінедолі, захищеному стартовому гіллі Тельдрассила.",kw={"іверрон","тінедол","отрута","павуки","протиотрута","тельдрассил","нічний ельф"},ang={["class:Druid"]="Друїди, що навчаються в Тінедолі, бачать в отруєнні Іверрона симптом глибшої недуги, яка охопила природу й потребує ліків, зроблених просто з рослин і тварин долини.",["profession:Herbalism"]="Життя Іверрона залежить від того, як швидко зберуть тутешні рослини Тінедолу, і це підкреслює, наскільки знання трав важливе для порятунку життя.",["race:NightElf"]="Для нічних ельфів-новачків, що роблять перші кроки за межами Алдрассила, лихо Іверрона — ранній урок того, як швидко дика природа Тельдрассила втрачає рівновагу."},sec={{t="Гіркий укус",b="Блукаючи тихими кронами Тінедолу, Іверрон наразився на павуків Вебвуда, що гніздяться в долині. Отруйний укус швидко звалив молодого ельфа, і він лишився безпорадним, не здатним сам повернутися в безпечне місце. Його стан виказує раптову агресію, що охоплює створіння, які колись мирно ділили з ельфами цей гай."},{t="Відчайдушні ліки",b="Порятунок Іверрона залежить від кмітливості його товаришів і місцевих цілителів, яким потрібні сильні лісові складники — гіацинтові гриби, лілеї місячна пелюстка та іхор павуків Вебвуда, — щоб зварити протиотруту. Його зустріч зі смертю — тверезе нагадування всім молодим калдореям Тінедолу: гілля Тельдрассила аж ніяк не бездоганне святилище."}},faq={{q="Хто такий Іверрон?",a="Іверрон — молодий нічний ельф, що живе в Тінедолі на Тельдрассилі. Мандруючи лісом, він став жертвою отруйних створінь, що чатують на гілках, і без негайної допомоги не вижив би.",al={"лор іверрона","хто такий іверрон","іверрон нічний ельф"}},{q="Що отруїло Іверрона?",a="Його вкусили люті павуки-тенетники, що водяться в хащах Тінедолу, і їхня виснажлива отрута не минає від простого відпочинку.",al={"чому іверрон хворий","хто вкусив іверрона","отрута іверрона"}},{q="Як вилікувати Іверрона?",a="Його лікують відваром із місцевих рослин Тельдрассила — гіацинтових грибів і місячних лілій, — змішаних з іхором павуків-тенетників, щоб вийшло дієве протиотрутне зілля.",al={"вилікувати іверрона","протиотрута іверрона","порятунок іверрона"}},{q="Де знайти Іверрона?",a="Він у Тінедолі — відлюдній стартовій галявині у верхівці Тельдрассила, де нічні ельфи-новачки починають навчання.",al={"місце іверрона","де іверрон","знайти іверрона"}},{q="Хто допомагає Іверронові?",a="Іверрон посилає шукачів пригод до своєї подруги Діранії Сілвершайн, яка збирає складники для протиотрути й передає її йому, поки та не втратила сили.",al={"хто рятує іверрона","друзі іверрона","дентарія сілверглейд іверрон"}},{q="Чому павуки в Тінедолі такі ворожі?",a="Раптова лють павуків Тінедолу — частина неприродної недуги, що поволі пронизує Тельдрассил і перетворює зазвичай потайливих звірів на жорстоких хижаків.",al={"чому павуки нападають","скверна павуків тельдрассила"}}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.158.0,45.160.0"}
P.entries["npc:jahan-hawkwing"] = {n="Джахан Гоквінг",s="Джахан Гоквінг — тауренський бронник на Перехресті в Пустках. Він постачає шкіряні й кольчужні обладунки мандрівникам, які наважуються ступити на суворі рівнини, повні хижаків.",h="Джахан Гоквінг — тауренський бронник на Перехресті в Пустках.",kw={"джахан гоквінг","бронник","перехрестя","обладунки","таурени","пустки"},ang={["faction:Horde"]="На перехресті головних шляхів Калімдору Джахан дбає, щоб воїни й розвідники Орди були захищені від невпинних набігів кентаврів і місцевої звірини.",["race:Tauren"]="Джахан уособлює практичну, самостійну вдачу шу'гало: майстерністю зі шкурами й міцними матеріалами він захищає мандрівників на родових землях Пусток."},sec={{t="Бронник Перехрестя",b="Джахан Гоквінг працює в гамірному вузлі Перехрестя й дбає про спорядження мандрівників і оборонців Орди. Пустки — жорстокий край, де міцний обладунок часто відділяє життя від загибелі від рук кентаврів, шипогривів чи диких звірів. Джахан співпрацює з місцевими шкірниками й приймає поставки вичинених шкур, щоб у його крамниці завжди були надійна дублена шкіра й міцні кольчуги."}},faq={{q="Хто такий Джахан Гоквінг?",a="Джахан Гоквінг — таурен-торговець і зброяр, що живе на Перехресті в Пустках. Він постачає мандрівним шукачам пригод і вартовим Орди захисне спорядження зі шкіри й кольчуги.",al={"лор джахана гоквінга","хто такий джахан","торговець бронею перехрестя"}},{q="Що він продає?",a="Джахан продає прості комплекти обладунків із дубленої шкіри й кольчуги — куртки, чоботи, пояси, наручі й рукавиці, придатні для воїнів-новачків, мисливців і розвідників.",al={"що продає джахан","крам джахана гоквінга","броня джахана"}},{q="Які доручення він дає мандрівникам?",a="Джахан залежить від ремісників, що живуть неподалік. Він просить охочих мандрівників доставляти сировину чи оброблені матеріали: відносити в'язки шкур місцевим чинбарям і чекати від них готових виробів.",al={"завдання джахана","завдання зв'язки шкір","доставка шкір на перехресті"}}},fp="14,183,25.437.0,22.183.0,24.165.0,38.206.0"}
P.entries["npc:jaina-proudmoore"] = {n="Джайна Праудмур",s="Леді Джайна Праудмур — правителька Острова Терамор і наймогутніша з живих чародійок-людей. Колись найкраща учениця Кірін-Тору в Даларані, вона повела вцілілих мешканців Лордерону через Велике море й тепер намагається зберегти крихкий мир між Альянсом і Новою Ордою.",h="Леді Джайна Праудмур — правителька Острова Терамор і наймогутніша з живих чародійок-людей.",kw={"джайна праудмур","терамор","кірін-тор","даларан","кул тірас","антонідас","калімдор"},ang={["class:Mage"]="Леді Джайна, учениця самого архімага Антонідаса, по праву вважається наймогутнішою з живих чародійок-людей — вершиною даларанської майстерності в таємній магії.",["faction:Alliance"]="Джайна дає Альянсу вкрай важливий плацдарм на півдні Калімдору. Вона шукає рівноваги між вірністю регентству верховного лорда Болвара в Стормвінді й прагненням уникнути війни з сусідньою Ордою."},sec={{t="Втеча до Калімдору",b="Донька великого адмірала Дейліна Праудмура з Кул Тірасу, Джайна ще змалку виявила неабиякий хист до таємної магії й навчалася в Даларані під проводом архімага Антонідаса. Під час Третьої війни вона разом із принцом Артасом Менетілом розслідувала загадкову Чуму Нежиття і на власні очі бачила трагічне падіння Лордерону. Прислухавшись до застережень Пророка Медіва, вона зібрала вцілілих людей і відплила на захід, до забутого континенту Калімдор. Там її загони уклали небачений союз з Ордою Тралла й нічними ельфами, і разом вони на вершині Гори Гіджал розбили Архімонда й зірвали вторгнення Палаючого Легіону."},{t="Володарка Терамору",b="Після поразки Легіону Джайна заснувала острівну цитадель Терамор біля узбережжя Багна Пилоброду — головний оплот Альянсу на півдні Калімдору. Її відданість дипломатії пройшла найтяжче випробування, коли її батько прибув помститися оркам. Джайна відмовилася підтримати його війну й не стала на заваді, коли війська Тралла вбили великого адмірала, — аби вберегти Калімдор від нової нищівної війни. Нині вона править Терамором як непохитна поборниця співіснування: тісно співпрацює з Вождем Траллом і водночас утримує позиції Альянсу, хоч напруга в краї дедалі зростає."}},faq={{q="Хто така Леді Джайна Праудмур?",a="Джайна — володарка Острова Терамор і, мабуть, найобдарованіша з живих людей-магів. Вона донька покійного Великого Адмірала Дейліна Праудмура з Кул Тірасу й колишня учениця Архімага Антонідаса в Даларані.",al={"хто така джайна","лор джайни праудмур","лідерка терамору"}},{q="Чому Джайна в Калімдорі, а не в Східних Королівствах?",a="Перед падінням Лордерону в Третій війні Пророк Медів застеріг Джайну й велів їй повести за море, до Калімдору, якомога більше людей. Її експедиція пережила подорож, билася біля Гори Гіджал і заснувала портову фортецю Терамор у Багні Пилоброду.",al={"чому джайна покинула лордерон","джайна калімдор","чому терамор тут"}},{q="Які в Джайни стосунки з Ордою?",a="Джайну пов'язує з Вождем Траллом незвична, обережна дружба. Відтоді як вони разом билися з Палаючим Легіоном біля Гори Гіджал, обоє прагнуть зберегти мир між своїми народами, попри запеклий опір непримиренних з обох боків.",al={"чи джайна дружить із траллом","джайна й орда","чи джайна ненавидить орків"}},{q="Що сталося між Джайною та принцом Артасом Менетілом?",a="Джайна й Артас дружили з дитинства, а коли подорослішали, їхня дружба переросла в кохання. Разом вони розслідували чуму, що ширилася Лордероном, але Джайну нажахало, як Артас ставав дедалі безжальнішим, — аж до очищення Стратгольма, де вона відмовилася брати участь у різанині заражених містян.",al={"джайна й артас","чи джайна кохала артаса"}}},fp="16,283,18.679.0,21.631.0,29.218.0,57.265.0,44.259.0,55.332.0"}
P.entries["npc:james-halloran"] = {n="Джеймс Галлоран",s="Джеймс Галлоран — чинбар-людина, що працює в Багнокраї й постачає добірні шкури на східні континенти. Мешкаючи в Гавані Менетіл, він заробляє на життя цупкими, цінованими шкурами місцевих кроколісків. Він покладається на мандрівників і місцеві торгові шляхи, щоб збирати сировину й доставляти вичинену шкіру на ринок.",h="Джеймс Галлоран — чинбар-людина, що працює в Багнокраї й постачає добірні шкури на східні континенти.",kw={"джеймс галлоран","чинбар","кроколіски","гавань менетіл","шкіра","багнокрай"},ang={["class:Hunter"]="Мисливці, що пробираються мокрими болотами, легко знайдуть спільну мову з Галлораном, чий хліб залежить від того, чи вдасться вистежити й обдерти лютих плазунів-хижаків Багнокраю.",["faction:Alliance"]="Торгівля Галлорана підтримує комерційну присутність Альянсу в суворому Багнокраї й постачає цінні шкіряні вироби до міст по всьому королівству."},sec={{t="Чинбар серед боліт",b="У своєму домі в Гавані Менетіл Джеймс Галлоран живе з боліт, що починаються просто за містечком. Як заповзятливий чинбар, Галлоран збагнув, що небезпечні трясовини пропонують вигідний товар — шкури кроколісків. Щоб перетворити грубу шкуру болотяних плазунів на якісну шкіру, потрібна рідкісна майстерність, і готові вироби Галлорана місцевими торговими шляхами розходяться до покупців по всьому Азероту."},{t="Шкури, учні й щоденна торгівля",b="Працювати так близько до боліт — постійна небезпека. Галлоран не може сам полювати на кожного звіра, доглядаючи водночас чани для вичинки й торгові справи. Він часто наймає витривалих мандрівників, щоб ті брали на себе грубішу роботу — білували молодих болотяних звірів і доставляли товар між його майстернею й довколишніми поселеннями, — аби його жвавий промисел ніколи не лишався без сировини."}},faq={{q="Хто такий Джеймс Галлоран?",a="Джеймс Галлоран — людина, чинбар із Гавані Менетіл у Багнокраї. Він полює на місцевих кроколісків і здирає з них шкури, а потім вичинює ці цупкі шкури на вироби, які розходяться по всьому світу.",al={"джеймс галлоран","галлоран","хто такий галлоран","шкіряр мокрих земель"}},{q="Де Джеймс Галлоран продає свою шкіру?",a="Галлоран вичинює сирі шкури кроколісків на добірну шкіру й відправляє її по всьому Азероту. Щоб розвозити свій товар морями, він здебільшого покладається на морську торгівлю через Гавань Менетіл.",al={"куди галлоран продає шкіру","торгівля шкірою галлорана","справи галлорана"}},{q="Навіщо Галлоранові шукачі пригод, щоб зібрати шкури молодих кроколісків?",a="Вичинка й дублення шкіри — праця довга й важка. Галлоран наймає мандрівних шукачів пригод проріджувати місцевих болотяних кроколісків і здирати з них шкури, щоб мати постійний запас сировини, не покидаючи майстерні.",al={"навіщо вбивати молодих кроколісків","завдання шкір молодих кроколісків","шкури кроколісків галлоран"}},{q="Що пов'язує Галлорана з Гаванню Менетіл?",a="Гавань Менетіл — головний торговий і постачальний осередок краю. Галлоран покладається на гавань і її морські шляхи, щоб відправляти вичинені шкури на далекі ринки й тримати свою чинбарню на плаву.",al={"галлоран менетіл","галлоран і гавань","чи галлоран живе в менетілі"}},{q="Де знайти Джеймса Галлорана?",a="Галлоран живе й працює в Гавані Менетіл — жвавому порту на західному узбережжі Багнокраю, а болота з кроколісками — одразу за містом.",al={"місце галлорана","де джеймс галлоран","знайти галлорана"}},{q="Чи є в Галлорана учень?",a="Так. Галлоран послав свого учня, якого вважає майже сином, у болота здирати шкури з велетенських кроколісків, але юнака покалічили, і він утратив ногу. Поки учень одужує, Галлоран покладається на загартованих мандрівників, які збирають шкури, без яких його ремеслу не обійтися.",al={"учень галлорана","обов'язки учня галлорана","хто працює на галлорана"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="Джаннок Бризсонг",s="Джаннок Бризсонг — наставник розбійників, нічний ельф, що перебуває в селі Доланаар на Тельдрассилі. Він навчає скрадання, хитрощів і володіння клинком молодих калдорейських розбійників, що виходять у віття Світового Дерева.",h="Джаннок Бризсонг — наставник розбійників, нічний ельф, що перебуває в селі Доланаар на Тельдрассилі.",kw={"джаннок бризсонг","розбійник","наставник","доланаар","тельдрассил","скрадання","дарнасус"},ang={["class:Rogue"]="Для молодих розбійників — нічних ельфів, що починають шлях на Тельдрассилі, Джаннок — ваш головний наставник у Доланаарі, перш ніж ви рушите до столиці.",["race:NightElf"]="Хоч калдорейська культура часто наголошує на вартових і друїдизмі, наставники на кшталт Джаннока готують тих, хто надає перевагу скраданню, отрутам і кинджалам."},sec={{t="Провідник у тінях",b="Джаннок Бризсонг, якого можна застати, як він ліниво сидить під віттям Доланаара, — головний наставник розбійників-новачків серед нічних ельфів. На відміну від статечних вартових чи відлюдних друїдів Тельдрассила, Джаннок веде тих, хто тихо діє на узбіччі суспільства, і вчить їх скрадатися в тінях, бити ззаду й виживати непоміченими серед віття. Щойно розбійник переросте перші уроки в Доланаарі, Джаннок спрямовує його далі, до досвідченіших майстрів у столиці — Дарнасусі."}},faq={{q="Хто такий Джаннок Бризсонг?",a="Джаннок Бризсонг — нічний ельф, наставник розбійників у Доланаарі на Тельдрассилі. Він навчає молодих калдореїв основних розбійницьких умінь і прийомів.",al={"хто такий джаннок","роль джаннока бризсонга","тренер розбійників доланаара"}},{q="Куди Джаннок посилає розбійників, які зростають?",a="Коли розбійник завершить перше навчання в Доланаарі, Джаннок радить йому вирушити до Дарнасуса й повчитися в Еріона Шейдвіспера — старшого наставника розбійників у Ценаріонському Анклаві міста.",al={"завдання джаннока","завдання еріона шейдвіспера","наступний крок розбійника доланаар"}},{q="Де знайти Джаннока в Доланаарі?",a="Джаннок у Доланаарі — головному поселенні Тельдрассила за межами Тінедолу, серед павільйонів, де стоять наставники.",al={"місце джаннока","де джаннок","знайти джаннока бризсонга"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="Джаспер Фел",s="Джаспер Фел — обачний постачальник, що працює у штабі SI:7 у Старому Місті Стормвінда. Він забезпечує агентів кинджалами й різними фіалами, пильно придивляється до відвідувачів і радить їм стежити за язиком. Його тиха торгівля підтримує таємне крило королівства за зачиненими дверима.",h="Джаспер Фел — обачний постачальник, що працює у штабі SI:7 у Старому Місті Стормвінда.",kw={"джаспер фел","si:7","старе місто","отрути","кинджали","розбійник"},ang={["class:Rogue"]="Джаспер Фел постачає необхідні фіали й запасні клинки таємним агентам, що вдосконалюють своє ремесло в Стормвінді.",["faction:Alliance"]="Працюючи у штабі SI:7, Фел дбає, щоб агенти, які з тіні захищають королівство, мали надійні припаси."},sec={{t="Припаси для тіней",b="Сховавшись у казармах SI:7 у Старому Місті, Джаспер Фел обслуговує дуже особливих клієнтів. Замість того щоб пропонувати звичайну зброю міській варті, він постачає найпотрібніше знаряддя ремесла: прості кинджали й тендітні фіали для варіння й нанесення отрут. Фел працює в суворій дисципліні розвідувального відділу Матіаса Шоу й сухо радить кожному, хто підходить, стежити за словами. У твердині, присвяченій шпигунству й тихим убивствам, зайва балаканина — легкий спосіб передчасно скінчити життя."}},faq={{q="Де знайти Джаспера Фела?",a="Джаспер Фел — у штабі SI:7, у східній частині Старого Міста Стормвінда.",al={"місце джаспера фела","де джаспер фел","джаспер фел стормвінд"}},{q="Що продає Джаспер Фел?",a="Він продає прості кинджали й порожні пляшечки різної якості, тож до нього варто зазирнути агентам, які запасаються складниками для отрут.",al={"торговець джаспер фел","що продає фел","товари джаспера фела"}},{q="Чи Джаспер Фел родич Морбента Фела?",a="У них одне прізвище, тож ходять чутки про родинний зв'язок із некромантом Морбентом Фелом із Сутінколісся, але сам Джаспер про особисте мовчить.",al={"джаспер фел морбент фел","чи джаспер родич морбента","рід фел сутінколісся"}},{q="Чому Джаспер Фел застерігає говорити тихо?",a="Він працює просто в SI:7 — серці шпигунської служби Стормвінда. У відомстві, повному вбивць і шпигунів, зайві балачки вважають небезпечними, тож Фел стежить, щоб відвідувачі поводилися в штабі з належною обережністю.",al={"чому говорити тихо","попередження джаспера фела","невдале слово перерізане горло"}}},fp="10,297,24.536.0,28.115.0,26.134.0,37.178.0,49.240.0"}
P.entries["npc:je-neu-sancrea"] = {n="Дже'ню Санкреа",s="Дже'ню Санкреа — троль із Темного Спису й член Земляного Кільця, що несе службу на Заставі Зорам'гар на узбережжі Ашенвалю. Відчуваючи темні збурення глибоко під берегом, він посилає шукачів пригод з Орди розслідувати скверну, що вразила давній затонулий храм Чорноглибинних Печер.",h="Дже'ню Санкреа — троль із Темного Спису й член Земляного Кільця, що несе службу на Заставі Зорам'гар на...",kw={"дже'ню санкреа","земляне кільце","темний спис","застава зорам'гар","чорноглибинні печери","шаман"},ang={["class:Shaman"]="Як знаний член Земляного Кільця з Темного Спису, Дже'ню втілює шаманський обов'язок урівноважувати осквернених елементалів і повертати рівновагу водам Калімдору.",["faction:Horde"]="Дже'ню — головний для Орди дороговказ і джерело завдань перед спуском з Ашенвалю в глибини Чорноглибинних Печер.",["race:Troll"]="Дже'ню показує, як тролі Темного Спису разом із союзниками-тауренами й орками прийняли духовний шлях Земляного Кільця."},sec={{t="Шаман на узмор'ї",b="Більшість членів Земляного Кільця дбає про гармонію стихій по всьому Калімдору, а Дже'ню Санкреа пильнує відлюдне й небезпечне Зорамське Узмор'я. Із Застави Зорам'гар він спостерігає за темними поштовхами й неприродними припливами біля зруйнованого храму Чорноглибинних Печер. Хоч його пов'язують шаманські обов'язки перед колом, міцна вірність племені Темного Спису й Орді Тралла змушує його працювати лише з героями Орди."},{t="Тіні глибин",b="Дже'ню прагне з'ясувати справжню причину скверни, що повзе узбережжям. Руками відважних шукачів пригод він збирає осквернені сапфірові ядра, досліджує мерзенні рештки водяних елементалів на кшталт Барона Аквеніса й викриває підступний вплив культу Молота Присмерку. Темні ритуали під хвилями загрожують не лише рівновазі місцевих стихій — вони віщують темне повернення сил, що присягли Древнім Богам."}},faq={{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — троль-шаман Темного Спису, пов'язаний із Земляним Кільцем. Він служить на Заставі Зорам'гар на узбережжі Ашенвалю й стежить за скверною, що дедалі дужче виплескується з Чорноглибинних Печер.",al={"хто такий дже'ню","лор дже'ню санкреа","що таке дже'ню"}},{q="Чому Дже'ню має справу лише з шукачами пригод Орди, якщо він із Земляного Кільця?",a="Хоча Земляне Кільце як спільнота прагне рівноваги стихій, а не війни фракцій, особисто Дже'ню міцно пов'язаний із племенем Темного Спису й Ордою. Оскільки він живе на прифронтовій військовій заставі Орди в Ашенвалі, мандрівникам Альянсу він не радий.",al={"чому лише орда","чи альянс може говорити з дже'ню","чи дже'ню нейтральний"}},{q="Що Дже'ню досліджує в Чорноглибинних Печерах?",a="Дже'ню досліджує неприродне збурення стихій і темну магію, що здіймаються з Чорноглибинних Печер. Він доручає поборникам добути зіпсовані водяні серцевини, знищити культистів Молота Присмерку й перевірити чутки, ніби давня гідра Аку'май служить стародавнім злим володарям під морем.",al={"цілі завдань дже'ню","чого хоче дже'ню","чому посилає у чорноглибинні печери"}},{q="Де знайти Дже'ню Санкреа?",a="Дже'ню на Заставі Зорам'гар — укріпленому поселенні Орди на далекому північно-західному узбережжі Ашенвалю, просто на Березі Зорам, трохи на південь від Чорноглибинних Печер.",al={"де дже'ню","місце дже'ню санкреа","знайти дже'ню"}},{q="Що таке Земляне Кільце?",a="Земляне Кільце — стародавнє коло шаманів, які прагнуть розуміти й заспокоювати духів стихій світу та втручаються щоразу, коли темні сили чи хаотичні створіння порушують природну гармонію стихій.",al={"лор земляного кільця","що таке земляне кільце","організація шаманів"}},{q="Чим загрожує Молот Присмерку в Печерах?",a="Культ Молота Присмерку проник до Чорноглибинних Печер, щоб поклонятися чудовиську Аку'май і проводити ритуали на честь Древніх Богів. Дже'ню доручає шукачам пригод Орди знищити їхніх ватажків, щоб зупинити цю темну справу.",al={"молот присмерку в чорноглибинних печерах","культ присмерку ясенлісся","хто культисти в чорноглибинних печерах"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="Джен'шан",s="Джен'шан — тролиця з джунглів Темного Списа і наставниця мисливців у Долині Випробувань у Дуроторі. Вона веде орків і тролів-стрільців-початківців, що роблять перші кроки в нетрях Орди. Молодих мисливців спрямовують до неї вчитися основ вистежування, дальнього бою й виживання.",h="Джен'шан — тролиця з джунглів Темного Списа і наставниця мисливців у Долині Випробувань у Дуроторі.",kw={"джен'шан","мисливець","наставниця","тролиця","долина випробувань","стрільба","дуротар"},ang={["class:Hunter"]="Для молодих орків і тролів-мисливців Джен'шан — найперша наставниця, яку ви зустрічаєте: вона навчає основ дальнього бою, перш ніж ви вирушите за червоні каньйони Лігва.",["race:Troll"]="Джен'шан утілює славетну вправність племені Темного Списа у вистежуванні й розвідці і дбає, щоб молоді тролі зберегли мисливські традиції предків у новому домі на материку."},sec={{t="Наставниця червоних пісків",b="Серед вивітрених таборів Долини Випробувань Джен'шан — головна наставниця мисливців для новобранців, що доводять свою цінність Орді. Молоді орки й тролі Темного Списа приходять до неї, стискаючи таблички з письменами й пергаменти, які вказують просто на неї. Гострим оком, вигостреним роками в дикій пустці, вона передає основи стрільби з лука, вогнепальної зброї та виживання в нетрях, щоб жоден новачок не став здобиччю скорпідів і вепрів, що нишпорять дном каньйону."}},faq={{q="Хто така Джен'шан?",a="Джен'шан — тролиця з джунглів, із племені Темного Спису, наставниця мисливців у Долині Випробувань у Дуротарі. Вона навчає мисливців-новачків Орди основ знання дикої природи, вистежування й стрільби.",al={"лор джен'шан","хто така джен'шан","тренер мисливців долини"}},{q="Які завдання пов'язані з Джен'шан?",a="Мисливців-новачків посилають до неї вступні навчальні завдання. Молоді орки-мисливці приходять до неї з Гравірованою Табличкою, а молоді тролі-мисливці — з Гравірованим Пергаментом.",al={"завдання джен'шан","витравлена скрижаль джен'шан","витравлений сувій джен'шан"}},{q="Чому тролиця навчає мисливців на орківському випробувальному полігоні?",a="Долина Випробувань — спільний випробувальний полігон і для орків-новобранців, і для тролів Темного Спису, які втратили домівку й тепер ділять Дуротар з орками. Як неперевершені розвідники й слідопити, тролі на кшталт Джен'шан відіграють важливу роль у підготовці нових воїнів і мисливців обох народів до служби Орді.",al={"чому тролиця навчає в долині випробувань","тролиця-тренер у дуротарі"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {n="Дженнея Кеннон",s="Дженнея Кеннон — шанована наставниця магів, людина, що мешкає у Святилищі Чародія в Кварталі магів Стормвінда. Вона опікується навчанням чарівників-початківців: веде їх крізь основи науки й досліджує збурення в потоках місцевої тайної енергії. Своїми завданнями вона перевіряє, чи досить учням дисципліни, щоб опанувати магію й не згоріти в ній.",h="Дженнея Кеннон — шанована наставниця магів, людина, що мешкає у Святилищі Чародія в Кварталі магів Стормвінда.",kw={"дженнея кеннон","наставниця магів","святилище чародія","квартал магів","стормвінд","тайна магія"},ang={["class:Mage"]="Дженнея — одна з перших і найважливіших наставниць для магів Альянсу: вона скеровує ваші перші польові дослідження й підводить вас до виготовлення справжньої чарівницької мантії та посоха.",["faction:Alliance"]="Дженнея працює в самому серці Кварталу магів Стормвінда й дбає, щоб нові чарівники королівства були дисциплінованими й могли безпечно служити Альянсу."},sec={{t="Провідниця у Святилищі",b="Дженнея Кеннон стоїть на вершині спіральної доріжки Святилища Чародія — вона одна з головних наставниць для адептів тайної магії, які прибувають до Стормвінда. Вона не просто втовкмачує учням заклинання, а насамперед вчить обережності й самовладання. Тим, хто не володіє магією й лише проходить вежею, вона кидає суворе застереження: неприборкана магія спалить невмілого. Цю істину чарівники-початківці під її опікою засвоюють дуже швидко."},{t="Польова практика й основи",b="Дженнея переконана, що магічну теорію треба перевіряти спостереженнями в реальному світі. Вона часто відсилає здібних учнів за міські мури — наприклад, до Дзеркального Озера в Лісі Елвінн, щоб ті збагнули, як природні водойми взаємодіють із тайним резонансом. Коли учні просуваються далі, вона випробовує їхню рішучість: доручає з'ясувати, що за негаразди коїться в таверні «Синій Відлюдник», або зібрати нестійкі реагенти для їхнього першого справжнього чарівницького знаряддя."},{t="Зв'язки з вищими майстрами",b="Дженнея опікується початковим навчанням і місцевими справами, але знає, коли учень переріс її науку. Щойно новачок виявить справжній хист, вона скеровує його вище щаблями Святилища — до Верховного Чаклуна Андромата — або навіть за межі королівства, до відлюдних чарівників на кшталт Табети, що живе в глибині Багна Пилоброду."}},faq={{q="Хто така Дженнея Кеннон?",a="Це людина, наставниця магів у Святилищі Чародія в Кварталі магів Стормвінда, яка навчає нових магів і спрямовує їхні перші магічні дослідження.",al={"дженнея кеннон","хто така дженнея","тренер магів стормвінда"}},{q="Де знайти Дженнею Кеннон?",a="Вона в Святилищі Чародія — спіральній чарівній вежі в центрі Кварталу магів Стормвінда.",al={"місце дженнеї кеннон","де дженнея","знайти дженнею"}},{q="Які завдання дає Дженнея Кеннон?",a="Вона дає класові завдання магам Альянсу: дослідити Дзеркальне Озеро в Лісі Елвінн, з'ясувати, що за дивні речі діються в таверні «Синій Відлюдник», і зібрати матеріали на спорядження для магів-новачків.",al={"завдання дженнеї","ланцюжок завдань дженнеї кеннон"}},{q="Навіщо вона посилає магів до Дзеркального Озера?",a="Вона доручає учням набрати пробу з Дзеркального Озера під водоспадами Елвінна, щоб навчити їх відчувати тонкі магічні потоки довкола й взаємодіяти з ними.",al={"чому дзеркальне озеро","завдання дзеркального озера дженнея"}},{q="Чи спілкується Дженнея Кеннон з тими, хто не маг?",a="Поговорити з нею можуть і не маги, але вона лише суворо порадить їм стерегтися магії, застерігаючи, що вона обпікає тих, хто не має належного вишколу.",al={"чи дженнея говорить з не магами","дженнея для інших класів"}},{q="Кому підпорядковується Дженнея Кеннон?",a="Вона працює в ієрархії Святилища Чародія й наставляє учнів, доки ті не будуть готові вчитися в старших магів, як-от Верховного Чаклуна Андромата.",al={"начальник дженнеї","керівники магічного святилища"}}},fp="13,395,22.415.0,24.475.0,23.342.0,21.174.0,31.132.0,37.210.0,39.175.0,50.162.0,33.156.0"}
P.entries["npc:jergosh-the-invoker"] = {n="Джерґош Призивач",s="Джерґош Призивач — віроломний орк-чорнокнижник, що ховається глибоко в Проваллі Лютого Вогню під Оргріммаром. Як один із вищих ватажків культистів Пекучого Клинка, він практикує демонічні мистецтва просто під носом у Вождя й плете змову проти Орди.",h="Джерґош Призивач — віроломний орк-чорнокнижник, що ховається глибоко в Проваллі Лютого Вогню під Оргріммаром.",kw={"джерґош призивач","провалля лютого вогню","пекучий клинок","рада тіней","чорнокнижник","оргріммар"},ang={["class:Warlock"]="Для чорнокнижників Джерґош — могутній знавець демонічних мистецтв, чиї задуми загрожують Орді.",["faction:Horde"]="Осередок Ради Тіней, що процвітає просто під тронною залою вождя, — нестерпна загроза безпеці, яку Орда не може собі дозволити ігнорувати.",["race:Orc"]="Джерґош уособлює отруту старої Орди, що досі не вивітрилася, — спокусу демонічною кров'ю й чаклунством, яку Тралл прагне вичистити з орківської культури."},sec={{t="Культ під містом",b="Поки Тралл невтомно веде орків шляхом честі й шаманізму, Джерґош відкинув ці ідеали заради сирої демонічної сили. Сховавшись у підземному лабіринті Провалля Лютого Вогню під Оргріммаром, він зібрав прихильників у Пекучий Клинок — підступну секту, пов'язану з рештками Ради Тіней. Діючи в тіні просто під столицею Орди, Джерґош намагається зруйнувати все, на чому стоїть нова Орда."},{t="Демонічні амбіції",b="Джерґош у проваллі не просто блукає без мети. Його темні ритуали й небезпечні задуми зрештою стали настільки зухвалими, що привернули пильну увагу самого Тралла. Джерґош — смертельна зараза в самому Дуротарі, що нагадує Орді про темні угоди, від яких вона так відчайдушно намагалася відмовитися."}},faq={{q="Хто такий Джерґош Призивач?",a="Джерґош Призивач — могутній орк-чорнокнижник і один з ватажків культистів Пекучого Клинка, що орудують у Проваллі Лютого Вогню. Замість іти шляхом честі, яким веде Тралл, він обрав демонічне чаклунство.",al={"хто такий джерґош","лор джерґоша","джерґош лютий вогонь"}},{q="Чому Джерґош ховається в Проваллі Лютого Вогню?",a="Провалля Лютого Вогню дає Пекучому Клинку відлюдну мережу вогняних печер просто під Оргріммаром. Звідти Джерґош і його культисти можуть непомітно практикувати заборонену темну магію й плести змови проти Орди.",al={"чому джерґош під оргріммаром","лор місця джерґоша"}},{q="До якої фракції належить Джерґош?",a="Джерґош — один з ватажків Пекучого Клинка, культу, пов'язаного з Радою Тіней, що служить демонічним силам на кшталт Палаючого Легіону.",al={"фракція джерґоша","чи джерґош тіньова рада","вожак палаючого клинка"}},{q="Чи знає Тралл, що Джерґош ховається під Оргріммаром?",a="Так. Змови Джерґоша стали такими небезпечними, що чутки дійшли до Тралла, і Вождь послав у провалля надійних шукачів пригод, щоб знищити загрозу від культистів.",al={"тралл джерґош","чи тралл знає про лютий вогонь"}},{q="Чому Джерґош практикує магію Скверни, а не шаманізм?",a="Джерґош свідомо відвернувся від духовного відродження свого народу: він відкинув шаманську гармонію й погнався за п'янкою силою, яку обіцяли Палаючий Легіон і темні мистецтва.",al={"чому чорнокнижник","джерґош магія скверни"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {n="Джерн Горнгелм",s="Джерн Горнгелм — дворф-рудокоп із Ліги Дослідників, що несе службу в містечку Телсамар. Він налагоджує важливе постачання й зв'язок між поселенням, Айронфорджем і місцем археологічних розкопок у глибині Лох Модану. Шукачі пригод часто допомагають йому перевозити гірниче спорядження й звіти про поступ робіт по всьому краю.",h="Джерн Горнгелм — дворф-рудокоп із Ліги Дослідників, що несе службу в містечку Телсамар.",kw={"джерн горнгелм","ліга дослідників","телсамар","розкопки айронбенда","рудокоп","лох модан"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що проходять Лох Моданом, Джерн — важлива особа, яка допомагає вберегти край і підтримувати дворфійське господарство.",["profession:Mining"]="Рудокопи оцінять ремісниче минуле Джерна й його практичне розуміння підземного постачання, підривних робіт і перевезення руди.",["race:Dwarf"]="Для дворфів допомога Джернові — прямий внесок у священні пошуки давньої спадщини Титанів, похованої глибоко в горах."},sec={{t="Постачання в Телсамарі",b="Джерн Горнгелм, що працює в затишному містечку Телсамар, відіграє ключову роль у постачанні дворфійських робіт по всьому Лох Модану. Поки дворфійські вчені й польові загони вирушають у нетрі, щоб відкопати минуле своїх предків, надійне постачання лишається конче потрібним. Джерн дбає, щоб важливі ресурси, інструменти й звістки безпечно діставалися діючих розкопок."},{t="На службі Ліги Дослідників",b="Як член Ліги Дослідників, Джерн поєднує польових археологів із проводом Ліги в Залі Дослідників в Айронфорджі. Такі розкопки, як Розкопки Айронбенда, дуже залежать від вибухового пороху, спорядження й регулярних донесень, щоб робота не стояла. Джерн залучає надійних мандрівників, щоб ті проходили дорогами, заполоненими трогами, й підтримували розкопки в повній готовності."}},faq={{q="Хто такий Джерн Горнгелм?",a="Джерн Горнгелм — дворф-гірник і відповідальний за постачання в Телсамарі, що в Лох Модані. Він працює на Лігу Дослідників і дбає, щоб місцеві розкопки йшли без перешкод.",al={"хто такий джерн","ідентичність джерна горнгелма","дворф джерн телсамар"}},{q="Де знайти Джерна Горнгелма?",a="Він стоїть надворі в містечку Телсамар, у центрі Лох Модану, при головній дорозі.",al={"місце джерна горнгелма","де джерн","карта джерна горнгелма"}},{q="До якої фракції належить Джерн Горнгелм?",a="Джерн — на боці Альянсу й, зокрема, представляє дворфійську Лігу Дослідників: керує переміщенням робітників і гірничого приладдя.",al={"фракція джерна горнгелма","на кого працює джерн","чи джерн ліга дослідників"}},{q="Навіщо Джернові відправляти вибуховий порох на розкопки?",a="Археологічні розкопки в гірській місцевості потребують керованих підривів, щоб пробиватися крізь тверді скелі. Джерн організовує доставку спеціального вибухового пороху на розкопки Шукача Айронбенда, щоб його люди могли безпечно відкопувати реліквії титанів і стародавні кам'яні зали.",al={"порох для айронбенду","навіщо розкопкам порох","вибуховий порох лох модан"}},{q="Що пов'язує Джерна Горнгелма з Айронфорджем?",a="Джерн — важлива ланка зв'язку між віддаленими розкопками в Лох Модані й верхівкою Ліги Дослідників у Залі Дослідників Айронфорджа: він раз у раз надсилає до столиці звіти про хід робіт.",al={"джерн горнгелм айронфордж","звіт в айронфордж джерн"}},{q="З якими труднощами стикаються розкопки в Лох Модані?",a="Раптова навала лютих трогів, витіснених з-під землі, поставила розкопки під серйозну загрозу й перекрила торгові шляхи, тож звичайні доставки без озброєних шукачів пригод у супроводі стали небезпечними.",al={"проблеми розкопок айронбенду","небезпеки розкопок лох модану","навіщо джернові допомога"}}},fp="13,350,22.390.0,29.391.0,21.187.0,31.113.0,42.148.0,58.279.0,48.234.0,53.223.0"}
P.entries["npc:jitters"] = {n="Тремтій",s="Тремтій — тремтливий чоловік-відлюдник, що ховається серед руїн Воронячого Пагорба на заході Сутінколісся. Охоплений постійною параноєю й страхом, він сам-один виживає на небезпечному західному краю лісу, сподіваючись на допомогу перехожих шукачів пригод і стежачи за тінями, що підступають.",h="Тремтій — тремтливий чоловік-відлюдник, що ховається серед руїн Воронячого Пагорба на заході Сутінколісся.",kw={"тремтій","воронячий пагорб","коса елуни","погибель роланда","воргени","сутінколісся"},ang={["class:Rogue"]="Тремтій має швидке чуття на небезпеку, та воно не вберегло його від жаху й самотності в Сутінколіссі.",["faction:Alliance"]="Тремтій — людське обличчя трагедії Сутінколісся: він живе в страху, поки Нічна Варта щосили намагається захистити своїх людей."},sec={{t="Наляканий відлюдник",b="Тремтія можна знайти серед напіврозвалених хат Воронячого Пагорба: він живе в постійному жаху перед хижаками, що никають західними стежками Сутінколісся. Він покладається на перехожих шукачів пригод, щоб роздобути бодай якусь їжу, і гарячково стежить за тінями, що підступають. Своє прізвисько він отримав давно — за полохливі манери й дивовижне чуття, що допомагає вчасно відскочити від раптової небезпеки, — та його нестямна параноя народилася з власної зустрічі з неймовірними жахами."},{t="Пробудження в Погибелі Роланда",b="Спершу Тремтій належав до Братства Дефіас, коли воно просувалося в Сутінколісся. Копаючи в шахті, відомій як Погибель Роланда, він натрапив на Косу Елуни, що стирчала зі скелі. Артефакт випустив у ліс лютих, кровожерливих воргенів. Тремтій з жахом дивився, як його товаришів розривають на шматки, і ледве врятувався з тієї різанини, вберігши власну шкуру."},{t="Утеча й хутір",b="Утікши з шахти, Тремтій подався до Даркшира, купив у Писаря Долтрі чисту книгу й гарячково описував той жах, ховаючись у Таверні «Багряний Крук». У паніці він знайшов прихисток у стодолі на Хуторі Йорґенів. Там він побачив, як Темні Вершники в чорних плащах різали родину Свена Йорґена, шукаючи Косу. Боячись, що його звинуватять чи знайдуть, Тремтій закопав сторінки свого щоденника в землю й утік до Воронячого Пагорба, переслідуваний нестерпною провиною й невщухним страхом."}},faq={{q="Хто такий Тремтій?",a="Тремтій — наляканий чоловік, що живе серед руїн Воронячого Пагорба. Він голодний, самотній і досі не може оговтатися від того, що пережив у Сутінколіссі.",al={"хто цей чолов'яга","лор тремтія","минуле тремтія"}},{q="Чому його звуть Тремтієм?",a="Прізвисько пішло від його обачної вдачі — від звички інстинктивно відсахуватися від ударів і відскакувати від раптових ям. Довга самотність і невимовний жах, пережитий у Сутінколіссі, лише посилили його нервовість.",al={"чому його звуть тремтій","звідки його ім'я","походження імені тремтія"}},{q="Чим загрожують воргени в Сутінколіссі?",a="Воргени нишпорять лісами й дорогами Сутінколісся й загрожують мандрівникам і відлюдним поселенням.",al={"загроза ворґенів сутінколісся","звірі біля тремтія","небезпека ворґенів сутінколісся"}},{q="Що сталося з родиною Свена Йорґена?",a="Родину Свена Йорґена вбили на їхньому хуторі, і тепер він сповнений рішучості з'ясувати, хто в цьому винен.",al={"різанина на фермі свена","хто вбив родину свена","вбивство на фермі йорґена"}},{q="Як Тремтій може допомогти розслідуванню Свена Йорґена?",a="У щоденнику Тремтія записано те, що він пережив у Сутінколіссі, і це може допомогти Свенові з'ясувати, що сталося з його родиною.",al={"тремтій і розслідування свена","як тремтій допоможе свенові","розповідь тремтія про сутінколісся"}},{q="Що за щоденник у Тремтія?",a="У його щоденнику записано те, що він пережив у Сутінколіссі, і він стає частиною розслідування довкола Воронячого Пагорба й родини Свена Йорґена.",al={"щоденник тремтія","завершений щоденник тремтія","книга далтрі"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="Джокасте",s="Джокасте — наставниця мисливців, нічна ельфійка, що мешкає в зеленому Ценаріонському Анклаві в Дарнасусі. Працюючи пліч-о-пліч із Колом Кенарія, вона наставляє молодих стрільців і повелителів звірів — нічних ельфів, які прибувають із нетрів Тельдрассила.",h="Джокасте — наставниця мисливців, нічна ельфійка, що мешкає в зеленому Ценаріонському Анклаві в Дарнасусі.",kw={"джокасте","мисливець","наставниця","ценаріонський анклав","дарнасус","коло кенарія","тельдрассил"},ang={["class:Hunter"]="Для мисливців — нічних ельфів, що вперше входять до Дарнасуса, Джокасте — важлива вчителька, яка відточує ваші бойові прийоми й допомагає зміцнити зв'язок із тваринними супутниками.",["race:NightElf"]="Укорінена в Ценаріонському Анклаві, Джокасте відбиває тісну злагоду між мандрівниками — нічними ельфами, дикими звірами Тельдрассила й наукою Кола Кенарія."},sec={{t="Наставниця в Анклаві",b="Перебуваючи серед тихих гаїв Ценаріонського Анклаву в Дарнасусі, Джокасте навчає мисливців — нічних ельфів. Коли молоді слідопити завершують перше навчання в Тінедолі й вирушають до столиці, Джокасте допомагає їм стати досвідченими знавцями виживання. Вона викладає мистецтво влучної стрільби, виживання в дикому краю і священний зв'язок між мисливцем і дикими звірами Калімдору."}},faq={{q="Хто така Джокасте?",a="Джокасте — нічна ельфійка, наставниця мисливців у Ценаріонському Анклаві столиці Дарнасус, яка навчає й наставляє тих, хто обрав шлях мисливця.",al={"лор джокасте","хто така джокасте","джокасте дарнас"}},{q="Де знайти Джокасте?",a="Вона серед дерев і павільйонів Ценаріонського Анклаву, у північно-західному районі Дарнасуса на гілках Тельдрассила.",al={"місце джокасте","де джокасте","точка джокасте"}},{q="Яку роль вона відіграє для молодих мисливців?",a="Мисливці, яких посилають до Дарнасуса, шукають її, щоб удосконалити своє ремесло через завдання на кшталт «Шлях мисливця» й навчитися як слід приручати диких звірів і командувати ними.",al={"завдання джокасте","шлях мисливця джокасте","приборкання звіра"}},{q="Чи Джокасте пов'язана з Колом Кенарія?",a="Так. Хоч вона й навчає мисливців, а не друїдів, служить вона в Ценаріонському Анклаві й щиро вітає мисливців, які прибувають до Кола Кенарія.",al={"чи джокасте з кола ценарія","фракція джокасте"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:jonathan-carevin"] = {n="Джонатан Каревін",s="Джонатан Каревін — рішучий мисливець-людина з Даркшира, що присвятив себе викоріненню темряви, яка гнітить Сутінколісся. На відміну від Нічної Варти, що лише обороняється, він і його родина самі полюють на нежить, воргенів і будь-які єретичні загрози, що чаяться під темними кронами.",h="Джонатан Каревін — рішучий мисливець-людина з Даркшира, що присвятив себе викоріненню темряви, яка гнітить...",kw={"джонатан каревін","мисливець","даркшир","воргени","сутінколісся","нежить"},ang={["class:Hunter"]="Мисливцям близький завзятий підхід Каревіна: він вистежує й методично винищує нічних хижаків Сутінколісся.",["class:Paladin"]="Завзяття Каревіна й те, як він закликає Світло проти демонічної та некромантської скверни, глибоко співзвучні зі священними обітницями паладина.",["faction:Alliance"]="Для поборників Альянсу, що намагаються втихомирити Сутінколісся, Джонатан Каревін завдає точних ударів по надприродних загрозах, які розплодилися через байдужість Стормвінда."},sec={{t="Хрестовий похід Каревінів",b="Даркшир покладається на Нічну Варту, яка патрулює дороги й охороняє містечко, але Джонатан Каревін переконаний, що самої лише оборони замало. Разом із родиною та союзниками на кшталт Калора Джонатан переходить у наступ. Він полює на нечестивих потвор, що блукають Сутінколіссям, і веде власний хрестовий похід, щоб із ласки Світла очистити край від усіх демонів, нежиті й єретиків."},{t="Тінь воргенів",b="Пильність Джонатана не обмежується шкандибаючими скелетами й гулями. Він уважно стежить за дикими вовкоподібними звірами — воргенами, — що никають лісовою гущавиною. Знаючи, яку небезпеку вони становлять для й так обложеного поселення, Джонатан організовує розслідування їхньої загадкової появи, прагнучи з'ясувати, звідки взялися ці нечестиві хижаки, і покласти край їхнім нічним полюванням."}},faq={{q="Хто такий Джонатан Каревін?",a="Джонатан Каревін — суворий мисливець, що живе в Даркширі в Сутінколіссі. Він веде родину Каревінів у справжню війну з мерзенними чудовиськами, що заполонили ліс.",al={"хто такий каревін","лор джонатана каревіна","каревін дарксір"}},{q="Чим він відрізняється від Нічної Варти?",a="Нічна Варта здебільшого стереже околиці Даркшира й дбає, щоб дороги лишалися прохідними, а Джонатан і його прибічники самі вистежують нежить та інших потвор, щоб знищити їх у самому корені.",al={"чи він нічна варта","каревін проти нічної варти"}},{q="З якими загрозами він бореться?",a="Джонатан полює на нежить, на зграї ненажерливих воргенів, на демонів і на всіх, хто дає притулок чи допомогу таким нечестивим потворам.",al={"що полює каревін","цілі каревіна"}},{q="Чи пов'язаний Джонатан із Багряним Хрестовим Походом?",a="Його різкі промови, палка відданість Світлу й непримиренність до будь-якої скверни нагадують переконання Багряного Хрестового Походу, але офіційно він діє сам, разом зі своєю родиною в Даркширі.",al={"каревін багряний хрестовий похід","чи каревін багряний"}},{q="Хто допомагає Джонатанові в його місії?",a="Окрім найближчої родини, Джонатанові безпосередньо допомагають бійці, що поділяють його погляди, як-от Калор, який допомагає йому вистежувати навали чудовиськ у лісі.",al={"союзники каревіна","хто допомагає каревіну"}},{q="Що пов'язує його з воргенами?",a="Джонатан вважає воргенів неприродною загрозою, що тероризує людей Сутінколісся, і доручає мандрівникам з'ясувати, звідки вони раптом узялися в цих нетрях.",al={"каревін воргени","чому каревін ненавидить воргенів"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jorah-annison"] = {n="Джора Аннісон",s="Джора Аннісон — картограф із Відступників, що працює в Магічному Кварталі Андерсіті. Хоч його фах — мапи й географія, його знання безцінні для мандрівних заклиначів, які шукають рідкісні, розпорошені знання по всьому Азероту.",h="Джора Аннісон — картограф із Відступників, що працює в Магічному Кварталі Андерсіті.",kw={"джора аннісон","картограф","магічний квартал","андерсіті","фоліант кабали","відступники"},ang={["class:Warlock"]="Джора — незамінний контакт для чорнокнижників Орди, які збирають Фоліант Кабали: він дає точні вказівки, де по світу шукати загублені сторінки.",["faction:Horde"]="Завдяки своєму картографічному хисту Джора допомагає шукачам пригод з Орди орієнтуватися на незнайомих континентах і віднаходити цінні реліквії.",["race:Undead"]="Мешканець Андерсіті, Джора показує, як інтелектуальні заняття Відступників, як-от картографія, служать ширшій меті — виживанню його народу."},sec={{t="Знавець потемнілих земель",b="Серед алхімічних випарів і магічних відлунь Магічного Кварталу Андерсіті Джора Аннісон займається картографією. Багато вчених-Відступників присвячують своє нежиття самій лише чумі чи руйнівній магії, а Джора зосереджується на точному нанесенні на мапу місцевості, кордонів і забутих місць на всіх континентах, даючи Орді цінні відомості для походів і постачання."},{t="Слід кабали",b="Знання Джори про землю сягають далеко за руїни Лордерону. Чорнокнижників, що шукають невловимий Фоліант Кабали, часто відсилають до нього, щоб дізнатися, де можна віднайти давні тексти й рештки темних сект, — так він поєднує історичні перекази з далекою географією."}},faq={{q="Хто такий Джора Аннісон?",a="Джора Аннісон — картограф-нежить, що живе в Магічному Кварталі Андерсіті й допомагає мандрівникам Орди знаннями про землі та історичні місця.",al={"хто такий джора аннісон","хто такий джора","картограф андерсіті"}},{q="Де знайти Джору Аннісона?",a="Він у Магічному Кварталі Андерсіті — підземної столиці Відступників під руїнами Лордерону.",al={"місце джори аннісона","де джора аннісон","знайти джору"}},{q="Навіщо чорнокнижникам з ним говорити?",a="Чорнокнижники, які шукають стародавній Фоліант Кабали, звертаються до Джори як до знавця картографії: він може вказати їм далекі місця, де можна відшукати розкидані уривки цього тексту.",al={"завдання чорнокнижника джори","том змовників джора","навіщо говорити з джорою"}},{q="До якої фракції належить Джора Аннісон?",a="Він із Відступників і вірний Орді, служить своїм побратимам у їхній столиці.",al={"фракція джори аннісона","чи джора з орди"}},{q="Чи продає Джора Аннісон мапи гравцям?",a="Джора здебільшого радник і той, до кого звертаються в завданнях про забуті місця, а не торговець.",al={"чи джора продає мапи","торговець джора"}},{q="Чи буває Джора Аннісон за межами Андерсіті?",a="Хоча його мапи й доручення стосуються далеких країв на кшталт Пусток, сам Джора не покидає Магічного Кварталу Андерсіті.",al={"джора в пустках","джора поза андерсіті"}}},fp="13,263,27.382.0,17.292.0,21.169.0,31.134.0,39.201.0,42.107.0,49.123.0,50.157.0"}
P.entries["npc:jordan-stilwell"] = {n="Джордан Стілвелл",s="Джордан Стілвелл — вправний зброяр-людина, що працює біля засніженої Брами Айронфорджа в Дун Мороґу. Хоча спершу йому судилося стати паладином Святого Світла, він пішов батьковим ремеслом і став майстром, чиї вироби служать паладинам по всьому Альянсу. Найбільше він відомий тим, що викував Кулак Верігана на честь свого давнього друга Боша Верігана.",h="Джордан Стілвелл — вправний зброяр-людина, що працює біля засніженої Брами Айронфорджа в Дун Мороґу.",kw={"джордан стілвелл","зброяр","кулак верігана","паладин","дун мороґ","айронфордж"},ang={["class:Paladin"]="Джордан Стілвелл — ключова постать у ранніх випробуваннях паладина: він доручає вам обнишпорити Азерот у пошуках рідкісних складників, щоб викувати ваш знаменитий бойовий молот — Кулак Верігана.",["faction:Alliance"]="Утікши від жахів, які Аруґал наслав на Срібнолісся разом із воргенами, Джордан знайшов прихисток у дворфів Дун Мороґа й тепер служить своїм ремеслом просто поборникам Альянсу.",["profession:Blacksmithing"]="Навчений дворфом Бейлором Стоунгендом, із зачарованим молотом, що дістався від батька, Джордан — вершина святого ковальства серед смертних."},sec={{t="Покликання біля ковадла",b="Від Джордана Стілвелла чекали, що він складе святі обітниці й стане паладином Церкви Святого Світла, але зрештою він обрав шлях горна. Він пішов батьковими слідами й узяв до рук батьків зачарований ковальський молот. Своє ремесло Джордан відточував під наглядом дворфа-коваля Бейлора Стоунгенда. Хоч він і відмовився від мантії помазаного святого воїна, Джордан лишається глибоко відданим Світлу й присвячує свою надзвичайну майстерність спорядженню поборників, що б'ються в його ім'я."},{t="Утеча зі Срібнолісся",b="Задовго до того, як відкрити кузню на пронизливому холоді Дун Мороґа, Джордан був ковалем у фортеці Барона Сільверлейна в Срібноліссі. Коли Архімаг Аруґал випустив на фортецю диких воргенів і перетворив її на прокляту твердиню, відому як Фортеця Шадовфенг, Джорданові вдалося вирватися з різанини. Змушений покинути свій горн і колишній дім, він зрештою знайшов притулок серед дворфів Дун Мороґа."},{t="Кування Кулака Верігана",b="Джордан тримає свою кузню просто неба біля брами Айронфорджа, віддаючи перевагу бадьорому гірському повітрю перед задушливим жаром Великої Кузні всередині гори. Коли Церква Святого Світла присилає до нього гідних паладинів, Джордан доручає їм добути рідкісні матеріали з усього світу, щоб викувати легендарний дворучний бойовий молот. Названа Кулаком Верігана на честь давнього друга Боша Верігана, ця зброя — свідчення нерозривного зв'язку щирої віри й майстерно викуваної сталі."}},faq={{q="Хто такий Джордан Стілвелл?",a="Джордан Стілвелл — людина, майстер-коваль, що працює під відкритим небом біля Брами Айронфорджа в Дун Мороґу. Він кує священну зброю для паладинів Церкви Святого Світла, і найвідоміша з неї — легендарний бойовий молот Кулак Верігана.",al={"хто такий джордан стілвелл","лор джордана стілвелла","коваль біля айронфорджа"}},{q="Чому Джордан Стілвелл працює надворі, на снігу, а не в Айронфорджі?",a="За словами Дуторіана Ралла зі Стормвінда, Джорданові більше до вподоби свіже, прохолодне гірське повітря Дун Мороґу, ніж задуха біля Великої Кузні в Айронфорджі.",al={"чому джордан надворі","чому працює в дун мороґу","чому на снігу"}},{q="Що пов'язує Джордана Стілвелла з Фортецею Шадовфенг?",a="Колись Джордан був зброярем і ковалем у маєтку Барона Сільверлейна в Срібноліссі. Йому вдалося втекти з фортеці перед катастрофою чи під час неї, коли Архімаг Аруґал і його дикі воргени вирізали гарнізон і захопили твердиню.",al={"джордан стілвелл шадовфенг","джордан стілвелл сільверпайн","чи жив у пайровуді"}},{q="Що таке Кулак Верігана?",a="Кулак Верігана — могутній дворучний святий молот, викуваний Джорданом Стілвеллом для паладинів Альянсу. Його названо на честь давнього Джорданового друга, Боша Верігана.",al={"кулак верігана","молот верігана","хто такий веріган"}},{q="Хто навчив Джордана Стілвелла ковальства?",a="Ремесло й зачарований ковальський молот Джордан успадкував від батька, а згодом відточив майстерність під проводом дворфа-коваля Бейлора Стоунгенда.",al={"хто навчав джордана стілвелла","учитель джордана стілвелла","де він вчився кувати"}},{q="Хто дружина Джордана Стілвелла?",a="Джордан одружений із Дафною Стілвелл. Подружжя впродовж багатьох років щедро допомагає Церкві Святого Світла, і обох шанують як глибоко побожних служителів віри.",al={"дружина джордана стілвелла","дафна стілвелл чоловік","дафна стілвелл"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {n="Йорґен",s="Йорґен — потайний інформатор-людина, що мешкає в Стормвінді: він сховався біля води одразу за входом до Долини Героїв. Попри скромне й відлюдне місце, він заплутаний у делікатних справах, пов'язаних із помітними особами столиці, зокрема з Еллінгом Тріасом та Єпископом ДеЛаве.",h="Йорґен — потайний інформатор-людина, що мешкає в Стормвінді: він сховався біля води одразу за входом до...",kw={"йорґен","інформатор","стормвінд","долина героїв","еллінг тріас","розвідка"},ang={["class:Rogue"]="Йорґен уособлює вуличну мережу шепотів, що процвітає під бездоганним мармуром Стормвінда й тісно пов'язана з таємними операціями, які ведуть через крамницю «Сири Тріаса».",["faction:Alliance"]="Коли офіційні канали Стормвінда впираються в бюрократичні мури, надійні вуличні інформатори на кшталт Йорґена стають незамінними, щоб вистежити загрози королівству."},sec={{t="Очі біля води",b="Йорґен тримається внизу біля води, одразу праворуч від величної брами Стормвінда, подалі від гамірних міських вулиць. Поки над мостом здіймаються статуї героїв, Йорґен із тіні стежить, хто приходить і хто йде, — тихий зв'язковий для тих, кому потрібні відомості поза будь-якими записами."},{t="Заплутане минуле",b="Потайна присутність Йорґена тут не випадкова. Його пов'язує непросте минуле з Еллінгом Тріасом — майстром-сироторговцем і збирачем розвідданих, — а також з Єпископом ДеЛаве із Собору Світла. Коли постають делікатні розслідування — як-от зникнення дипломата, посланого до Терамора, — Йорґен стає одним із небагатьох місцевих зв'язкових, здатних вказати слідчим правильний напрям. Якщо, звісно, вони знають, як до нього підступитися."}},faq={{q="Де знайти Йорґена?",a="Йорґен у Стормвінді, у Долині Героїв. Щойно ви ввійдете до міста через браму з боку Лісу Елвінн, спустіться до води праворуч від головного мосту.",al={"місце йорґена","де йорґен","знайти йорґена"}},{q="З ким пов'язаний Йорґен у Стормвінді?",a="Йорґена пов'язує довга історія з Еллінгом Тріасом, відомим торговцем сирами в Торговому Кварталі, що має таємні зв'язки, а також з Єпископом ДеЛаве із Собору Світла.",al={"зв'язки йорґена","стосунки йорґена","кого знає йорґен"}},{q="Яку роль Йорґен відіграє в розслідуванні зникнення дипломата?",a="Під час пошуків зниклого посланця Йорґен — ключовий інформатор. Тих, хто веде розслідування, посилають до нього, щоб з'ясувати, хто міг влаштовувати таємні зустрічі й потайні справи в королівстві.",al={"йорґен зниклий дипломат","завдання йорґена"}},{q="Чи пов'язаний Йорґен з Міськими Вартовими Стормвінда?",a="Ні. Йорґен діє сам по собі, тримаючись подалі від офіційних патрулів варти, внизу біля берегів каналу, де можна поговорити без зайвих вух.",al={"чи йорґен вартовий","фракція йорґена"}}},fp="6,292,17.374.0,17.434.1,24.180.0,40.174.0,72.198.0,51.161.0"}
P.entries["npc:josef-gregorian"] = {n="Йозеф Ґреґоріан",s="Йозеф Ґреґоріан — наставник кравців із Відступників, що працює в Магічному Кварталі Андерсіті. Він допомагає честолюбним кравцям Орди, які прагнуть ткати зачаровані тканини: ділиться досвідом і підказує, як шити особливе вбрання.",h="Йозеф Ґреґоріан — наставник кравців із Відступників, що працює в Магічному Кварталі Андерсіті.",kw={"йозеф ґреґоріан","кравецтво","наставник кравців","магічний квартал","мантії","андерсіті"},ang={["profession:Tailoring"]="Для кравців Орди Йозеф Ґреґоріан — головний знайомий у Лордероні: він навчає ремесла й шиє мантії молодим магам, які принесуть йому матеріали.",["race:Undead"]="Ґреґоріан доводить, що попри смерть і нежиття тонке людське кравецьке мистецтво пережило падіння Лордерона й тепер служить новій спільноті Відступників."},sec={{t="Ткач Магічного Кварталу",b="Серед тьмяних алхімічних ліхтарів і вогких склепінь Магічного Кварталу Йозеф Ґреґоріан береже тонке кравецьке ремесло для Відступників та їхніх союзників з Орди. Хоч життя в підземному королівстві вистигло, робота з тканиною лишається життєво важливою для чорнокнижників, магів і жерців, що спрямовують сиру енергію крізь сплетені волокна. Ґреґоріан — надійний наставник у столиці: він готовий навчити основних викрійок і пошити перші мантії молодим магам, які принесуть йому потрібні матеріали."}},faq={{q="Де знайти Йозефа Ґреґоріана?",a="Йозеф Ґреґоріан — у Магічному Кварталі Андерсіті: він займається кравецтвом і навчає цього ремесла серед міських заклиначів і вчених.",al={"місце йозефа ґреґоріана","де ґреґоріан","кравець андерсіті"}},{q="Яку роль Йозеф Ґреґоріан відіграє в Андерсіті?",a="Він наставник кравців, що навчає ремісників Орди викрійок і прийомів шиття. А ще він шиє перші мантії для молодих магів, яких до нього посилає Анастасія Гартвелл.",al={"що робить йозеф ґреґоріан","тренер йозеф ґреґоріан","кравецтво андерсіті"}},{q="Які завдання дає Йозеф Ґреґоріан?",a="Ґреґоріан бере участь у ланцюжку завдань для магів: Анастасія Гартвелл посилає до нього молодих магів із лляною тканиною й даларанськими самоцвітами мани, здобутими в Срібноліссі («Збір матеріалів»), і він шиє їм Робу Малого Чаровогню («Роба чаровогню»).",al={"завдання йозефа ґреґоріана","завдання на мантії андерсіті"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {n="Каал Соулріпер",s="Каал Соулріпер — оркський наставник чорнокнижників, що живе глибоко в Магічному Кварталі Андерсіті. Хоч він і мешкає серед Відступників, але підтримує тісні зв'язки з іншими знавцями темних мистецтв по всій Орді й часто скеровує учнів до наставників у далеких краях.",h="Каал Соулріпер — оркський наставник чорнокнижників, що живе глибоко в Магічному Кварталі Андерсіті.",kw={"каал соулріпер","чорнокнижник","магічний квартал","андерсіті","менара войдрендер","скакун скверни"},ang={["class:Warlock"]="Каал Соулріпер дає важливі уроки демонічних мистецтв і скеровує честолюбних чорнокнижників на шлях, що веде до створення Сфери Орагіла й підкорення скакуна Скверни.",["race:Orc"]="На відміну від прихованого кола в Тіньовій Розколині, Каал діє відкрито в столиці Відступників, далеко від пильних очей шаманського проводу Оргріммара."},sec={{t="Знавець у тіні",b="Орда Тралла суворо обмежує магію Скверни в Оргріммарі й пильно за нею стежить, тож знавці на кшталт Каала Соулріпера знаходять надійний притулок у підземних святилищах Лордерону. Живучи в Магічному Кварталі Андерсіті, Каал ділиться своєю владою над демонічними сутностями й прокльонами з чорнокнижниками Орди, які готові вчитися. Окрім звичайних уроків, він — важливий контакт для тих, хто прагне більшої сили: честолюбних учнів він відсилає за море до наставників на кшталт Менари Войдрендер у Пустках."}},faq={{q="Хто такий Каал Соулріпер?",a="Каал Соулріпер — орк, наставник чорнокнижників, що живе в Магічному Кварталі Андерсіті. Він навчає заклинань чорнокнижників і допомагає тим, хто шукає особливих темних артефактів і ритуалів.",al={"хто такий каал","лор каала соулріпера","каал андерсіті"}},{q="Чому орк-чорнокнижник живе в Андерсіті?",a="За Вождя Тралла чорнокнижники в орківському суспільстві перебувають під пильним наглядом і підозрою. В Андерсіті ж, поруч із Відступниками, вивчати магію тіней і демонологію можна значно вільніше.",al={"чому орк-чорнокнижник в андерсіті","чому каал в андерсіті"}},{q="Куди Каал Соулріпер посилає своїх учнів?",a="Коли учні досягають достатньої майстерності, Каал відправляє їх за Велике Море, до Пусток, учитися в Менари Войдрендер, або знайомить з іншими відомими чорнокнижниками Орди.",al={"завдання каала","до кого каал посилає"}}},fp="15,279,29.516.0,23.195.0,46.201.0,48.185.0"}
P.entries["npc:kaela-shadowspear"] = {n="Каела Шедовспір",s="Каела Шедовспір — вартова нічних ельфів, що несе службу на південний захід від Кручі Вітрорізу в Горах Кам'яного Кігтя. Зі своєї невеликої застави вона разом з іншими вартовими стежить за дедалі гострішою напругою й безладом у дикому краї. Вона покладається на відважних мандрівників, щоб розвідувати небезпечні місця й нести допомогу пораненим захисникам землі.",h="Каела Шедовспір — вартова нічних ельфів, що несе службу на південний захід від Кручі Вітрорізу в Горах...",kw={"каела шедовспір","вартова","круча вітрорізу","прадавні","гори кам'яного кігтя"},ang={["class:Druid"]="Друїди знайдуть спільну мову з Каелою, що виходжує поранених прадавніх і вгамовує біль стривожених духів природи.",["faction:Alliance"]="Каела Шедовспір — важлива ланка для шукачів пригод з Альянсу, що вирушають у спірні краї Гір Кам'яного Кігтя: вона координує розвідку між віддаленими заставами.",["race:NightElf"]="Для нічних ельфів Каела уособлює непохитну оборону священної землі: вона трудиться, щоб утихомирити розлючених духів і вберегти шанованих прадавніх Калімдору."},sec={{t="Розвідниця на прикордонні",b="Каела Шедовспір, що стоїть трохи на південний захід від промислового спустошення Кручі Вітрорізу, пильно стежить за довколишніми перевалами. Гори Кам'яного Кігтя сповнені небезпек: Орда наступає, а гоблінські промисли виснажують природні багатства краю. Разом із гномом Ґаксимом Растфіззлом Каела — важлива передова ланка зв'язку нічних ельфів, що відстежує загрози, які просуваються вглиб земель предків."},{t="Зцілення землі",b="Неспокій у Горах Кам'яного Кігтя сягає далеко за межі сутичок за землю. Жорстоке порушення природи розлютило елементалів і завдало шкоди давнім охоронцям лісу. Каела невтомно посилає шукачів пригод проти шалених духів стихій і доглядає поранених прадавніх, що потерпають у вогні тутешніх конфліктів, намагаючись повернути спокій, перш ніж земля назавжди лишиться пошрамованою."}},faq={{q="Хто така Каела Шедовспір?",a="Каела Шедовспір — нічна ельфійка, що дає завдання в прикордонному таборі на південний захід від Кручі Вітрорізу в Горах Кам'яного Кігтя. Вона керує розвідкою в краї й допомагає захищати місцевих тварин і духів.",al={"хто така каела","ідентичність каели шедовспір","каела нпс"}},{q="Де знайти Каелу Шедовспір?",a="Вона в невеликому таборі Альянсу на південний захід від Кручі Вітрорізу, при дорозі в Горах Кам'яного Кігтя, і ділить табір із гномом-інженером Ґаксимом Растфіззлом.",al={"місце каели шедовспір","де каела","табір каели в стоунталоні"}},{q="Кому звітує Каела?",a="Каела тісно співпрацює з Вартовою Тенісіль і постійно обмінюється з нею свіжими відомостями про пересування ворогів і місцеві загрози в Горах Кам'яного Кігтя.",al={"кому звітує каела","каела тенісіл","командир каели"}},{q="Чому Каелу тривожать елементалі?",a="Безжальна вирубка лісу, гірничі роботи й воєнне вторгнення в Гори Кам'яного Кігтя глибоко порушили природну рівновагу, і духи стихій шаленіють і нападають на всіх, хто опиниться поруч.",al={"завдання розлючених духів","чому духи сердяться","каела духи стихій"}},{q="Що відбувається з прадавніми біля Кручі Вітрорізу?",a="Через сутички в краї й стрімке знищення лісів прадавні захисники поранені й страждають. Каела просить мандрівників допомогти знайти й зцілити цих полеглих оборонців дикої природи.",al={"завдання поранених прадавніх","каела прадавні","поранені прадавні стоунталон"}},{q="Чому разом із Каелою стоїть гном?",a="Каела ділить табір із Ґаксимом Растфіззлом, гномом з Альянсу. Поки Каела дбає про духовну й тактичну рівновагу дикого краю, Ґаксим зайнятий протидією ворожим гоблінським машинам і їхнім задумам неподалік.",al={"ґаксим растфіззл каела","чому ґаксим із каелою","табір гнома й нічної ельфійки"}}},fp="17,351,23.446.0,16.414.0,25.216.0,37.179.0,25.158.0,44.178.0,54.185.0,36.230.0"}
P.entries["npc:kali-remik"] = {n="Калі Ремік",s="Калі Ремік — тролиця-мисливиця Темного Списа, яка наставляє мандрівників у серці земель Орди. Обізнана зі способами вистежування й виживання в Дуроторі, вона спрямовує молодих мисливців до Тотара в Гострий Пагорб, щоб ті вчилися приборкання звірів.",h="Калі Ремік — тролиця-мисливиця Темного Списа, яка наставляє мандрівників у серці земель Орди.",kw={"калі ремік","мисливиця","тролиця","тотар","гострий пагорб","сен'джин","дуротар"},ang={["class:Hunter"]="Для молодих орків і тролів-стрільців Калі — сходинка: вона розпізнає, коли ваші вміння переростають сільські вправи, і посилає вас далі, до Тотара в Гострий Пагорб.",["race:Troll"]="Теж із племені Темного Списа, Калі пильнує своїх родичів, що відбудовують життя на узбережжі Дуротару й осідають у Долині Духів Оргріммара."},sec={{t="Провідниця полювання",b="Калі Ремік — досвідчена тролиця-слідопитка з джунглів, добре обізнана з посушливими пустками Дуротару й гамірними осередками Орди. У прибережних поселеннях на кшталт Села Сен'джин вона наглядає за молодими розвідниками, що роблять перші кроки за межами Долини Випробувань. Знаючи, коли новачок переростає місцеві тренувальні землі, вона скеровує здібних стрільців до Тотара в Гострий Пагорб, щоб ті почали шлях володарів звірів, а прикордонні лави Орди лишалися гострими й дисциплінованими."}},faq={{q="Хто така Калі Ремік?",a="Калі Ремік — тролиця-розвідниця з племені Темного Спису, що дає завдання. Вона допомагає молодим шукачам пригод Орди, особливо мисливцям, які готові продовжити навчання за межами місцевих застав.",al={"лор калі реміка","хто така калі ремік","калі ремік нпс"}},{q="Де знайти Калі Ремік?",a="Вона допомагає своєму народові в Дуротарі, здебільшого поблизу Села Сен'джин.",al={"де калі ремік","місце калі реміка","знайти калі реміка"}},{q="Які поради вона дає мисливцям?",a="У завданні «Шлях мисливця» Калі посилає молодих мисливців-орків і тролів, що вже довели свої базові вміння, до Гострого Пагорба, де Тотар допоможе їм приручити власного звіра-супутника.",al={"завдання шлях мисливця","завдання мисливця калі реміка","чого навчає калі"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Калтунк",s="Калтунк — орк-наглядач у самому серці Долини Випробувань у Дуроторі. Він — найперший, кого зустрічають молоді орки, роблячи перші кроки у світ. Його обов'язок — вітати цих майбутніх чемпіонів і спрямовувати їх до перших обов'язків на службі Орді.",h="Калтунк — орк-наглядач у самому серці Долини Випробувань у Дуроторі.",kw={"калтунк","наглядач","долина випробувань","новобранці","ґорнек","дуротар"},ang={["faction:Horde"]="Калтунк допомагає підтримувати практичну дисципліну, потрібну для ладу на суворих тренувальних землях Дуротару.",["race:Orc"]="Для кожного орка, що виходить у Калімдор, грубуваті настанови Калтунка — перші слова, які він чує, починаючи здобувати свою честь."},sec={{t="Перший крок",b="Стоячи під суворим сонцем Долини Випробувань, Калтунк наглядає за новоприбулими, що прагнуть довести свою гідність Орді. Поки інші наставники й старійшини роздають виснажливі випробування й мисливські обряди, Калтунк дбає, щоб жоден новобранець не блукав безцільно в червоному пилу. Він віддає прості накази й указує новачкам просто на Ґорнека та шлях дисципліни."},{t="Хранитель долини",b="Долина Випробувань — не легке місце для гарту; її обрали саме для того, щоб кувати силу й стійкість у кожному юнакові, що ступає дном її каньйону. Калтунк утілює цю сувору практичність. Він не виголошує пишних промов і не панькається, чекаючи, що кожен орк швидко знайде своє місце у світі й тягтиме свою лямку задля вождя."}},faq={{q="Хто такий Калтунк?",a="Калтунк — орк-наглядач у Долині Випробувань. Його першим зустрічають новоприбулі орки-шукачі пригод: він вказує їм шлях до наставників і дає початок їхньому навчанню.",al={"роль калтунка","хто цей орк","калтунк нпс"}},{q="Що Калтунк робить для новачків?",a="Він дає новобранцям перше завдання — поговорити з Ґорнеком в іншій частині долини, щоб почалося справжнє навчання.",al={"завдання калтунка","чого хоче калтунк","перше завдання долини випробувань"}},{q="Де знайти Калтунка?",a="Він стоїть просто біля центрального тренувального намету й вогнища в Долині Випробувань — відлюдному стартовому краї на півдні Дуротару.",al={"місце калтунка","знайти калтунка","де калтунк"}},{q="Чому він служить у Долині Випробувань?",a="Він зустрічає новачків і стежить, щоб новоприбулі орки-новобранці були на обліку й не гаючись вирушали на службу Орді Тралла.",al={"чому калтунк тут","мета калтунка"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="Кам Діпф'юрі",s="Кам Діпф'юрі — сумнозвісний диверсант із дворфів Темного Заліза, ув'язнений у глибинах В'язниці Стормвінда. На відміну від більшості в'язнів, він не має жодного стосунку до Братства Дефіас: його схопили за влаштування нищівного вибуху на Мосту Тандол далеко на півночі.",h="Кам Діпф'юрі — сумнозвісний диверсант із дворфів Темного Заліза, ув'язнений у глибинах В'язниці Стормвінда.",kw={"кам діпф'юрі","темне залізо","диверсант","міст тандол","в'язниця стормвінда","дворфи"},ang={["faction:Alliance"]="Поки в Стормвінді всі дивляться на бунт Дефіас, Діпф'юрі нагадує про ширшу загрозу Темного Заліза, що нависає над північними рубежами Альянсу.",["race:Dwarf"]="Для дворфів Айронфорджа Кам Діпф'юрі — запеклий ворог, чия диверсія зруйнувала Міст Тандол і вбила родича Лонґбрейди Похмурого. Помститися за цю втрату — справа особистої честі."},sec={{t="Диверсант далеко від дому",b="В'язниця переповнена озлобленими каменярами й бунтарями Дефіас, але Кам Діпф'юрі стоїть осторонь. Підступного й жорстокого дворфа Темного Заліза схопили й привезли до Стормвінда після того, як він задумав операцію, що паралізувала важливі північні шляхи. Його замкнено глибоко в тюремних камерах, далеко від родичів під Горою Блекрок, але до Альянсу він такий самий ворожий, як і будь-який бунтар, що ділить із ним коридори."},{t="Диверсія на Мосту Тандол",b="Розвідка Альянсу в Дун Модрі, біля північного кордону Багнокраю, встановила, що саме Діпф'юрі задумав вибух, який зруйнував Міст Тандол. Вибух обірвав один із велетенських кам'яних мостів, що з'єднують Багнокрай з Аратійським нагір'ям. Диверсія не лише перерізала важливий торговий і воєнний шлях для Айронфорджа й Альянсу — вона забрала життя родича дворфійського командира, якого звуть Лонґбрейда Похмурий."},{t="Рахунки, які треба звести",b="Заколотникові Темного Заліза недовго вдавалося уникати відплати, хоча ув'язнення в Стормвінді й дало йому тимчасовий захист від родичів жертв. У Багнокраї Мотлі Ґармасон і зболений горем Лонґбрейда Похмурий шукають найманців, готових пробратися в охоплену бунтом в'язницю й відтяти Діпф'юрі голову, звівши криваві рахунки, що почалися за сотні миль на північ."}},faq={{q="Хто такий Кам Діпф'юрі?",a="Кам Діпф'юрі — особливо небезпечний в'язень, дворф Темного Заліза, якого тримають у В'язниці Стормвінда. Він відомий тим, що організував диверсію на Мосту Тандол на півночі, і не має нічого спільного з бунтівниками Дефіас, ув'язненими поруч із ним.",al={"хто такий діпф'юрі","лор кама діпф'юрі","хто дворф у в'язниці"}},{q="Чому дворф Темного Заліза сидить у В'язниці Стормвінда?",a="Діпф'юрі схопили після того, як він організував напад, у якому підірвали один із прогонів Мосту Тандол: загинули дворфи-захисники, а важливий суходільний шлях між Багнокраєм та Аратійським нагір'ям було перерізано. Його відправили до суворо охоронюваної в'язниці Стормвінда чекати на суд.",al={"чому він у в'язниці","що накоїв кам діпф'юрі","чому його ув'язнили"}},{q="Чи Кам Діпф'юрі член Братства Дефіас?",a="Ні. Хоча під час бунту у В'язниці він сидить поруч із Братством Дефіас, Діпф'юрі належить до ворожого клану Темного Заліза. Він діє виключно в інтересах свого клану, що вороже налаштований до Альянсу й Айронфорджа.",al={"чи він дефіас","кам діпф'юрі дефіас","чи діпф'юрі з венкліфом"}},{q="Хто хоче смерті Кама Діпф'юрі?",a="Його смерті хочуть Мотлі Ґармасон і дворфійські сили Айронфорджа, що стоять у Дун Модрі. Лонґбрейда Похмурий утратив родича, коли Діпф'юрі підірвав Міст Тандол, тож вони передали шукачам пригод у Стормвінді звістку, що чекають на його голову.",al={"хто дав завдання про діпф'юрі","хто хоче смерті діпф'юрі"}},{q="Де Кам Діпф'юрі скоїв свій злочин?",a="Діпф'юрі влаштував диверсію на Мосту Тандол — велетенській мостовій споруді, що з'єднує Багнокрай з Аратійським нагір'ям, далеко на північ від Стормвінда.",al={"де підірвали міст","діпф'юрі підрив мосту","напад на проліт тандола"}},{q="Де у В'язниці тримають Кама Діпф'юрі?",a="Кама Діпф'юрі тримають у камерах В'язниці Стормвінда, під Кварталом Каналів Стормвінда.",al={"де діпф'юрі у в'язниці","місце кама діпф'юрі"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {n="Канаті Ґрейклауд",s="Канаті Ґрейклауд — мисливець-таурен на Заставі Білого Рубежу в Тисячі Голок. Разом із товаришами-мисливцями він тримає оборону як може, раз у раз відбиваючись від місцевих кентаврів Ґалак.",h="Канаті Ґрейклауд — мисливець-таурен на Заставі Білого Рубежу в Тисячі Голок.",kw={"канаті ґрейклауд","застава білого рубежу","кентаври ґалак","мисливці","засідка","тисяча голок"},ang={["faction:Horde"]="Застава Білого Рубежу — важливий спостережний пункт над каньйонами Тисячі Голок; поки Канаті живий, розвідники Орди можуть стежити за пересуваннями загонів кентаврів.",["race:Tauren"]="Для тауренів, що мандрують Тисячею Голок, допомога Канаті на Заставі Білого Рубежу — важливий захист родичів від давніх лютих ворогів, кентаврів."},sec={{t="Хиткий прихисток",b="Канаті Ґрейклауд отаборився на Заставі Білого Рубежу, високо на пісковикових шпилях західної Тисячі Голок. Каньйон багатий на дичину й відкриває широкі краєвиди, та його затисли кентаври Ґалак, чиї бойові загони виборюють кожну п'ядь посушливих рівнин унизу. Разом з іншими мисливцями-тауренами Канаті пильнує дно каньйону, намагаючись уберегти заставу від жорстоких набігів грабіжників, що оточують її з усіх боків."},{t="Засідка кентаврів",b="Кентаври Ґалак прагнуть не лише відрізати Заставу Білого Рубежу — вони мають намір знищити її захисників до ноги. Гінці, що снують між таборами кентаврів, несуть чіткі накази вбити Канаті та його товаришів. Мандрівникам, які завітали на заставу, випадає перехопити ці накази й стати пліч-о-пліч із Канаті, коли загони Ґалаків спустяться на столову гору, щоб вирізати мисливців застави."}},faq={{q="Хто такий Канаті Ґрейклауд?",a="Канаті Ґрейклауд — таурен-мисливець із Застави Білого Рубежу в західній частині Тисячі Голок: він тримає там табір і боронить його від місцевих хижих загроз.",al={"хто такий канаті","лор канаті ґрейклауда","таурен біля уайтріч"}},{q="Де знайти Канаті Ґрейклауда?",a="Канаті на Заставі Білого Рубежу — тауренському таборі на узвишші, на північних кручах у західній частині Тисячі Голок.",al={"місце канаті","де канаті","де ґрейклауд"}},{q="Чому кентаври Ґалак намагаються його вбити?",a="Кентаври Ґалак прагнуть повністю панувати над каньйонами Тисячі Голок і нападають на застави Орди. Перехоплені накази викривають злагоджену змову кентаврів: убити Канаті й зламати оборону застави.",al={"чому кентаври нападають на канаті","змова ґалака","навіщо захищати канаті"}},{q="Чи Канаті родич інших Ґрейклаудів?",a="Він має те саме прізвище, що й Тор Ґрейклауд і Кар Ґрейклауд — двоє тауренів, яких можна зустріти деінде в диких краях Калімдору, хоча яке саме родинне коріння їх пов'язує, не сказано.",al={"рід ґрейклауд","тор ґрейклауд родич","кар ґрейклауд"}}},fp="16,218,18.433.0,14.426.1,24.160.0,34.146.0,45.224.0,38.175.0"}
P.entries["npc:kaplak"] = {n="Каплак",s="Каплак — орк, наставник розбійників у Гострому Пагорбі в центрі Дуротару. Він навчає юних орків і тролів мистецтва скрадатися, хитрувати й володіти клинком, готуючи їх до служби Орді, а потім посилає до Оргріммара.",h="Каплак — орк, наставник розбійників у Гострому Пагорбі в центрі Дуротару.",kw={"каплак","розбійник","гострий пагорб","дуротар","долина випробувань","наставник"},ang={["class:Rogue"]="Для юних розбійників-орків і тролів, що покидають Долину Випробувань, Каплак дає перший професійний вишкіл і скеровує їх до таємних мереж Оргріммара.",["faction:Horde"]="Каплак тихо дбає, щоб Орда мала вмілих розвідників, шпигунів і вбивць, здатних берегти Дуротар і діяти поза звичною лінією фронту."},sec={{t="Наставник у тіні",b="У поселенні Гострий Пагорб Каплак закладає основи для молодих розбійників Орди, що виходять із Долини Випробувань. Там, де традиційна оркська культура звеличує відкритий бій і ревучу атаку, Каплак навчає холодніших, тихіших умінь, без яких не вижити: непомітно підкрадатися, відмикати замки й завдавати смертельних ударів у спину. Коли учні переростають його науку в курних червоних ярах Дуротару, він посилає їх на північ, до столиці, Оргріммара, щоб удосконалювати ремесло серед старших агентів гільдії."}},faq={{q="Хто такий Каплак?",a="Каплак — орк, наставник розбійників на Гострому Пагорбі в Дуротарі. Він навчає розбійників-новачків — орків і тролів, які покинули Долину Випробувань, — перших розбійницьких умінь, а потім посилає їх до старших наставників в Оргріммарі.",al={"хто такий каплак","лор каплака","каплак гострий пагорб"}},{q="Де знайти Каплака?",a="Каплак на Гострому Пагорбі — головному поселенні Дуротару; зазвичай він відпочиває в казармах чи біля них разом з іншими наставниками класів.",al={"де каплак","місце каплака","знайти каплака"}},{q="Які завдання дає Каплак?",a="Каплак допомагає розбійникам-шукачам пригод зростати: направляє їх до досвідченіших наставників і на нові доручення — наприклад, посилає знайти Терзока в Оргріммарі.",al={"завдання каплака","завдання від каплака"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:kargal-battlescar"] = {n="Каргал Баттлскар",s="Каргал Баттлскар — оркський воїн-ветеран, що стоїть на Далекій Дозорній Заставі на східному кордоні Пусток. Він стереже переправу з Дуротару, оцінює новобранців і скеровує вправних бійців углиб краю, щоб посилити оборону Орди.",h="Каргал Баттлскар — оркський воїн-ветеран, що стоїть на Далекій Дозорній Заставі на східному кордоні Пусток.",kw={"каргал баттлскар","далека дозорна застава","дуротар","новобранці","воїн","пустки"},ang={["class:Warrior"]="Загартований у боях ветеран, увесь у слідах численних битв, Каргал втілює ту сувору стійкість, якої Орда чекає від своїх бійців на передовій у диких прикордонних землях.",["faction:Horde"]="Для молодих шукачів пригод з Орди, що покидають Дуротар, Каргал Баттлскар — перше знайомство з ширшою боротьбою за Калімдор: він збирає новобранців для сутичок, що назрівають у Пустках."},sec={{t="Вартовий кордону",b="Стоячи на варті Далекої Дозорної Застави, Каргал Баттлскар наглядає за стратегічним порогом, що відділяє суворі червоні рівнини Дуротару від неосяжної савани Пусток. Коли мандрівники й молоді шукачі пригод переходять міст через Річку Південної Люті, Каргал дає їм зрозуміти, що мирні дні навчання в Долині Випробувань минули. Пустки — спірний і небезпечний край, де лютують хижі звірі, загони кентаврів і племена шипогривів. Каргал оглядає кожного, хто проходить, набирає охочих на службу Орді й відсилає їх далі, до Перехрестя, щоб допомогти місцевим командирам утримати рубіж."}},faq={{q="Хто такий Каргал Баттлскар?",a="Каргал Баттлскар — орк-воїн і командир Далекої Дозорної Застави, що стоїть на східній дорозі з Дуротару до Пусток.",al={"каргал баттлскар","каргал","хто такий каргал"}},{q="Навіщо потрібна Далека Дозорна Застава?",a="Далека Дозорна Застава — пост раннього попередження й передова оборона Пусток від загроз, що з'являються біля кордону з Дуротаром і вздовж Річки Південної Люті.",al={"мета далекої дозорної застави","навіщо далека застава","що це за застава"}},{q="Куди Каргал посилає новобранців?",a="Каргал залучає до служби мандрівників, що проходять через заставу, і посилає їх на захід головною дорогою до Перехрестя — головного військового осередку Пусток.",al={"куди каргал посилає","куди йти після каргала","куди каргал відсилає новобранців"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="Карос Разок",s="Карос Разок — доглядач кажанів у Відступників, що служить у Гробниці в Срібноліссі. Він опікується сідалом крилатої нежиті, яка з'єднує цю заставу на спірному порубіжжі просто з Андерсіті та іншими твердинями Орди.",h="Карос Разок — доглядач кажанів у Відступників, що служить у Гробниці в Срібноліссі.",kw={"карос разок","доглядач кажанів","гробниця","срібнолісся","андерсіті","перельоти"},ang={["faction:Horde"]="Для мандрівників Орди, що пробиваються на південь до Передгір'я Гілсбреда, сідало кажанів Разока — незамінний перевалочний пункт на західному краю Лордерона.",["race:Undead"]="Карос Разок — ваша життєва ниточка до Андерсіті, завдяки якій зусилля на передовій у Срібноліссі міцно пов'язані зі столицею Леді Сильвани."},sec={{t="Хранитель крил Гробниці",b="Карос Разок на дерев'яному помості над склепами Гробниці доглядає кажанів-скелетів, без яких не обійтися зв'язку Відступників. Срібнолісся кишить воргенами Мунрейдж, свавільними магами Даларана й людськими рештками Амбермілла, тож подорож суходолом північною дорогою небезпечна. Разок дбає, щоб гінці, свіжі новобранці й важливі припаси могли перелітати над примарними кронами, тримаючи передову в зв'язку зі столицею в Галявинах Тірісфалю."}},faq={{q="Хто такий Карос Разок?",a="Карос Разок — Відступник, наглядач польотів у Гробниці в Срібноліссі. Він доглядає гніздовище навчених кажанів-вампірів, на яких шукачі пригод і посланці Орди перелітають Лордероном.",al={"роль кароса разока","хто майстер польотів у гробниці","кажан гробниці"}},{q="Куди Карос Разок може відправити мандрівників?",a="Разок пов'язує Гробницю просто з Андерсіті в Галявинах Тірісфалю й з Таррен Міллом у Передгір'ї Гілсбреда, тож північним Лордероном можна швидко пересуватися.",al={"маршрути з гробниці","куди летить кажан гробниці","польоти з гробниці"}},{q="За якими створіннями доглядає Карос?",a="Він доглядає великих кістяних їздових кажанів. Ці звірі-нежить — витривалі, невтомні літуни, пристосовані до отруєного неба Лордерону, і Відступники цінують їх за безшумність і витривалість.",al={"які їздові в разока","літаючі звірі відступників","літаючі істоти гробниці"}},{q="Чому наглядач польотів такий важливий у Гробниці?",a="Дороги Срібнолісся кишать ворогами — від проклятих воргенів Пайрвуда до людей-чарівників в Амбермілі. Разок забезпечує повітряний шлях, завдяки якому Відступники постачають цю передову базу, не наражаючись на засідки на дорогах.",al={"навіщо майстер польотів у гробниці","значення польотів гробниці"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="Кеті Гантер",s="Кеті Гантер — конярка при стайнях на сході Лісу Елвінн, де лежить Лісозаготівельний Табір Східної Долини. Вона постачає навчених верхових коней і скакунів громадянам Стормвінда й довіреним героям Альянсу. Разом із Рендалом Гантером вона дбає, щоб подорожні й солдати мали надійних верхових тварин для доріг королівства.",h="Кеті Гантер — конярка при стайнях на сході Лісу Елвінн, де лежить Лісозаготівельний Табір Східної Долини.",kw={"кеті гантер","коні","стайня","східна долина","верхова їзда","скакуни"},ang={["faction:Alliance"]="Союзні раси, що здобудуть високу повагу й шану при дворі Стормвінда, можуть заслужити привілей вести прекрасних скакунів Кеті в бій.",["race:Human"]="Для людей-мандрівників стайні Кеті — природний обряд посвяти: класичні стормвіндські коні, щойно ви опануєте основи верхової їзди."},sec={{t="Стайні Східної Долини",b="Усамітнена в тихих лісових галявинах Лісозаготівельного Табору Східної Долини, Кеті Гантер порядкує головним кінським поголів'ям королівства для майбутніх вершників Лісу Елвінн. Поки лісоруби заготовляють деревину для відбудови Стормвінда, Кеті доглядає стайню, вирощуючи різні надійні породи — пінто, кобил і прудких скакунів. Її поголів'я втілює класичну кінну традицію королівства: вірні супутники, здатні долати небезпечні дороги південного Азероту."}},faq={{q="Хто така Кеті Гантер?",a="Кеті Гантер — конярка й продавчиня їздових тварин королівства Стормвінд; вона працює при стайнях Лісозаготівельного Табору Східної Долини в Лісі Елвінн.",al={"кеті гантер елвінн","хто така кеті гантер","торговка кіньми кеті гантер"}},{q="Де знайти Кеті Гантер?",a="Вона в північній частині Лісозаготівельного Табору Східної Долини, доглядає загін і стайні неподалік від наставника верхової їзди Рендала Гантера на сході Лісу Елвінн.",al={"місце кеті гантер","де кеті гантер","знайти кеті гантер"}},{q="Чи можуть не люди купити в неї коней?",a="Так, але лише якщо здобули звеличення в королівстві Стормвінд. Люди-шукачі пригод можуть купити її коней без жодної особливої прихильності.",al={"чи дворф купить коня","кінь нічного ельфа","скакун за репутацію стормвінда"}},{q="Яких коней вона продає?",a="Кеті продає звичайних верхових коней — строкатих, гнідих і рудих, — а також прудких скакунів у броні, як-от Прудкого Паломіно, Прудкого Гнідого Скакуна й Прудкого Білого Скакуна.",al={"які коні продає кеті","види коней кеті гантер"}}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:katrana-prestor"] = {n="Леді Катрана Престор",s="Леді Катрана Престор — шляхтянка зі Стормвінда й один із найвпливовіших голосів при дворі. Поки король Варіан зник безвісти, вона стоїть у Фортеці Стормвінда поруч із юним королем Андуїном і Верховним Лордом Болваром Фордрагоном як довірена радниця.",h="Леді Катрана Престор — шляхтянка зі Стормвінда й один із найвпливовіших голосів при дворі.",kw={"катрана престор","леді престор","двір стормвінда","радниця","фортеця стормвінда","болвар фордрагон"},sec={{t="Голос двору",b="Леді Престор з'явилася при дворі кілька років тому й швидко стала однією з найдовіреніших його постатей. Вельможі Стормвінда шукають її прихильності, а її поради визначають чимало рішень, ухвалених від імені юного короля, поки Верховний Лорд Болвар Фордрагон править як регент. Прохачі, що приходять до Фортеці Стормвінда просити воїнів чи допомоги, нерідко переконуються: її думка важить не менше, ніж слово регента."}},faq={{q="Хто така Леді Катрана Престор?",a="Леді Катрана Престор — шляхетна пані зі Стормвінда й довірена радниця при дворі. Поки Король Варіан зник, вона стоїть поруч із юним королем Андуїном і Верховним Лордом Болваром Фордрагоном у Фортеці Стормвінда, і її слово має велику вагу серед вельмож.",al={"хто така катрана престор","хто така леді престор","лор катрани престор"}},{q="Чому вона радить королеві?",a="Після зникнення Короля Варіана на троні опинився його малий син Андуїн, а регентом став Верховний Лорд Болвар Фордрагон. Леді Престор сидить поруч із ними як радниця. Чимало рішень двору — зокрема й те, як Стормвінд відповідає на прохання про допомогу від віддалених земель, — ухвалюють з її поради.",al={"чому престор при дворі","що робить катрана"}},{q="Де знайти Леді Престор?",a="Зазвичай вона в тронній залі Фортеці Стормвінда, неподалік від Верховного Лорда Болвара Фордрагона й юного Короля Андуїна.",al={"де катрана престор","місце катрани престор"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="Кеймард Копперпінч",s="Кеймард Копперпінч — гоблін-торговець, що представляє Пасовища Димолісся в Оргріммарі під час Свята Зимової Завіси. Він стоїть у Долині Сили, нахвалює святкові товари й скеровує мандрівників до святкових веселощів і загублених святкових припасів. Його жвава торгівля приносить до столиці Орди сезонні веселощі — і гоблінську комерцію.",h="Кеймард Копперпінч — гоблін-торговець, що представляє Пасовища Димолісся в Оргріммарі під час Свята Зимової...",kw={"кеймард копперпінч","пасовища димолісся","зимова завіса","метцен олень","долина сили","гоблін"},ang={["faction:Horde"]="Для Орди Кеймард — комерційний бік Зимової Завіси в Оргріммарі, що поєднує традиційні зимові святкування з гоблінською підприємливістю.",["profession:Cooking"]="Кеймард і його колеги з Пасовищ Димолісся пропонують сезонні рецепти й особливі складники, без яких не спекти традиційних святкових ласощів."},sec={{t="Гоблінська Зимова Завіса",b="Коли настає Свято Зимової Завіси, Пасовища Димолісся відкривають крамницю просто в гамірній Долині Сили в Оргріммарі, а обличчям справи стає заповзятливий Кеймард Копперпінч. Поки Дід Зима приймає гостей поблизу, Кеймард дбає, щоб свято залишалося прибутковим. Продаючи дорожчі ласощі, святковий пакувальний папір і все потрібне до свята, він утілює гоблінський погляд: жодне велике культурне свято не обходиться без жвавого обігу монет."},{t="Святкові клопоти",b="Окрім торгівлі святковим крамом, Кеймард часто стає тим, до кого звертаються через сезонні негаразди, що спіткали Пасовища Димолісся. Від викрадених партій святкових ласощів до загадкового зникнення Метцена Оленя — Кеймард охоче залучає шукачів пригод Орди, щоб ті розв'язали проблеми серед снігів і свято йшло як слід."}},faq={{q="Хто такий Кеймард Копперпінч?",a="Кеймард Копперпінч — гоблін-торговець, пов'язаний із Пасовищами Димолісся. Під час Свята Зимової Завіси він торгує в Долині Сили Оргріммара добірними сезонними товарами й пропонує перехожим святкові доручення.",al={"хто такий кеймард","лор кеймарда копперпінча","що робить кеймард"}},{q="Що таке Пасовища Димолісся?",a="Пасовища Димолісся — торгова спілка, що відає їжею, ласощами й сезонними товарами Свята Зимової Завіси по всьому Азероту. Вона постачає святкові товари і Орді, і Альянсу, і має з того чималий зиск.",al={"що таке пасовища димолісся","на кого працює кеймард","лор пасовищ димолісся"}},{q="Де знайти Кеймарда Копперпінча?",a="Він стоїть у Долині Сили в Оргріммарі, біля головної святкової виставки, де під час Свята Зимової Завіси сидить Дід Зима.",al={"місце кеймарда","де кеймард копперпінч","де він в оргріммарі"}},{q="Чому він просить шукачів пригод про допомогу на свята?",a="Під час Зимової Завіси Пасовища Димолісся раз у раз потрапляють у халепи: то святкові солодощі вкрадуть, то викрадуть їхнього цінного північного оленя Метцена. Кеймард наймає охочих шукачів пригод, щоб повернути майно й уберегти святкові прибутки.",al={"завдання кеймарда","завдання частувань зимової завіси","завдання метцена орда"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="Хранитель Альбаґорм",s="Хранитель Альбаґорм — хранитель гаю, що перебуває в ідилічному святилищі на Піку Кам'яного Кігтя. Глибоко стривожений спустошенням, що псує південні околиці гір, він кличе мандрівників допомогти зцілити спалену природу Обвугленої Долини.",h="Хранитель Альбаґорм — хранитель гаю, що перебуває в ідилічному святилищі на Піку Кам'яного Кігтя.",kw={"хранитель альбаґорм","пік кам'яного кігтя","обвуглена долина","кенарій","гарпії","друїди"},ang={["class:Druid"]="Як хранитель гаю, Альбаґорм прямо пов'язаний із родом Кенарія, тож його зусилля очистити Обвуглену Долину — глибоко особиста справа для друїдів.",["faction:Alliance"]="Альбаґорм дає прихисток і настанови силам Альянсу, що проходять через святилище нічних ельфів на Піку Кам'яного Кігтя."},sec={{t="Охоронець на вершині",b="Серед мирного віття Піку Кам'яного Кігтя Хранитель Альбаґорм стереже один зі священних ельфійських притулків Калімдору. Як і багато синів Кенарія, він гостро відчуває біль світу природи. Його погляд прикутий на південь, до тліючих руїн Обвугленої Долини, яку підпалило жадібне механізоване військо промисловців і яку нині тримають гарпії Бладф'юрі, що не дають нічому відрости. Зі свого святилища Альбаґорм невтомно працює, щоб спинити поширення зіпсуття й повернути рівновагу пораненому лісові."}},faq={{q="Хто такий Хранитель Альбаґорм?",a="Це хранитель гаю — один із напівбогів, нащадків Кенарія, — що живе на Піку Кам'яного Кігтя в Горах Кам'яного Кігтя. Він союзник нічних ельфів і природних охоронців Калімдору.",al={"хранитель альбаґорм","хто такий альбаґорм","альбаґорм стоунталон"}},{q="Де знайти Хранителя Альбаґорма?",a="Він на Піку Кам'яного Кігтя — друїдському притулку, що підтримує Альянс, високо в північно-західному куточку Гір Кам'яного Кігтя.",al={"місце хранителя альбаґорма","де альбаґорм","координати альбаґорма"}},{q="З чим Хранителеві Альбаґорму потрібна допомога?",a="Альбаґорм прагне загоїти рани Обвугленої Долини. Він посилає вправних шукачів пригод у засипану попелом улоговину, щоб очистити спаплюжену землю й прогнати гарпій Кривавої Люті, які не дають природі відродитися.",al={"завдання хранителя альбаґорма","чого хоче альбаґорм","повернення обпаленої долини"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="Хранитель Бел'дуґур",s="Хранитель Бел'дуґур — учений-Відступник, що працює глибоко в Апотекаріумі Андерсіті. Він служить своєму народові, споряджаючи експедиції по темні фоліанти й магічні артефакти з усього Азероту.",h="Хранитель Бел'дуґур — учений-Відступник, що працює глибоко в Апотекаріумі Андерсіті.",kw={"хранитель бел'дуґур","апотекаріум","андерсіті","молот присмерку","книга ура","відступники"},ang={["class:Warlock"]="Чорнокнижники часто натрапляють на доручення Бел'дуґура, бо його інтереси тісно переплетені з небезпечними гримуарами, позаплощинними викликами й темним окультизмом.",["race:Undead"]="Бел'дуґур здається звичайним ученим-Відступником, що шукає заборонених знань, аби зміцнити ваше королівство, але його справжні прагнення лежать поза справою виживання, якій служить Королева Баньші."},sec={{t="Збирач темних реліквій",b="Хранитель Бел'дуґур, що працює серед чанів і дослідників Апотекаріуму, доручає шукачам пригод добувати небезпечні чарівні й окультні реліквії з усього Азероту. Серед його найпомітніших інтересів — Книга Ура, легендарний трактат про позавимірних істот, захований у Фортеці Шадовфенг. Чимало хто в Андерсіті шукає магічних знань, щоб вилікувати стан нежиті чи обернути його на зброю, але добірні здобутки Бел'дуґура, схоже, мають на меті відкопати давні, заборонені сили."},{t="Таємна вірність",b="За спокійною поставою дослідника з Андерсіті ховається таємна вірність апокаліптичному культові Молота Присмерку. Завдання й дослідницькі доручення, які дає Бел'дуґур, тихцем просувають езотеричні задуми культу: він збирає основоположні гримуари виклику й магії Порожнечі просто під носом у нічого не підозрюючих Королівського Аптекарського Товариства й Леді Сильвани."}},faq={{q="Де знайти Хранителя Бел'дуґура?",a="Хранитель Бел'дуґур — в Апотекаріумі, алхімічному кварталі на південній частині нижнього кільця Андерсіті.",al={"місце бел'дуґура","де бел'дуґур","карта бел'дуґура"}},{q="Навіщо Бел'дуґурові Книга Ура?",a="У Книзі Ура — основоположні дослідження даларанського мага Ура про інші виміри й диких воргенів. Бел'дуґур прагне скористатися цими забороненими принципами виклику заради темних задумів своїх справжніх володарів.",al={"навіщо книга ура","що бел'дуґур робить з книгою ура"}},{q="Чи вірний Хранитель Бел'дуґур Леді Сильвані?",a="На позір він архіваріус і дослідник на службі Відступників, але ледь помітні натяки в його пошуках підказують, що його вірність може належати комусь іншому.",al={"чи бел'дуґур злий","фракція бел'дуґура","кому служить бел'дуґур"}},{q="Які ще доручення він дає шукачам пригод?",a="Окрім Книги Ура з Фортеці Шадовфенг, Бел'дуґур спрямовує мандрівників на пошуки забутих переказів і заборонених фоліантів, зокрема темних трактатів, пов'язаних зі стародавніми ритуалами й забороненим знанням.",al={"завдання бел'дуґура","завдання хранителя бел'дуґура"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="Хранитель Бел'варіл",s="Хранитель Бел'варіл — доглядач і дослідник із Відступників, що служить у Таррен Міллі в Передгір'ї Гілсбреда. Працюючи пліч-о-пліч із Вордіном Войдґлером, він посилає шукачів пригод з Орди збирати магічні реліквії й речі для підкорення стихій у довколишніх землях, щоб просунути їхні окультні дослідження.",h="Хранитель Бел'варіл — доглядач і дослідник із Відступників, що служить у Таррен Міллі в Передгір'ї Гілсбреда.",kw={"хранитель бел'варіл","таррен мілл","войдґлер","стерті кам'яні жетони","елементалі","відступники"},ang={["faction:Horde"]="Для поборників Орди, що б'ються в Передгір'ї Гілсбреда, Бел'варіл пропонує відчутні нагороди за приборкання стихійних загроз і повернення чарів підкорення.",["race:Undead"]="Праця Бел'варіла відображає прагнення Відступників до таємної майстерності й винахідливості: ретельне вивчення місцевих реліквій дає їм перевагу в Лордероні."},sec={{t="Дослідження в Таррен Міллі",b="Серед обложеного селища Таррен Мілл Хранитель Бел'варіл тихо підтримує магічні й алхімічні дослідження Відступників. Поки королівські аптекарі й солдати зайняті гарнізоном Альянсу в Саутшорі, трохи далі дорогою, Бел'варіл зосереджується на практичному чаклунстві й посилає мандрівників добувати кам'яні жетони й наручі підкорення в довколишніх стихійних і зачарованих потвор."}},faq={{q="Хто такий Хранитель Бел'варіл?",a="Хранитель Бел'варіл — учений із Відступників у Таррен Міллі, що в Передгір'ї Гілсбреда. Він допомагає своєму колезі-дослідникові Вордіну Войдґлеру вивчати магічні артефакти й реагенти, знайдені на цих спірних землях.",al={"хранитель бел'варіл","хто такий бел'варіл","бел'варіл таррен мілл"}},{q="Де знайти Хранителя Бел'варіла?",a="Він у поселенні Відступників Таррен Мілл, на півночі Передгір'я Гілсбреда.",al={"місце бел'варіла","де хранитель бел'варіл","знайти хранителя бел'варіла"}},{q="Які завдання дає Хранитель Бел'варіл?",a="Він залучає шукачів пригод Орди збирати магічні рештки — кам'яні жетони й наручі зв'язування, — щоб його коло могло зрозуміти сили стихій і керувати ними.",al={"завдання бел'варіла","доручення хранителя бел'варіла"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="Келдран",s="Келдран — орк-агент, що діє трохи на північ від Долини Духів в Оргріммарі. Прагнучи прокласти шлях до майбутньої дипломатії з Альянсом, він організовує таємні удари по рештках демонічних сил, щоб довести: нова Орда справді зреклася Палаючого Легіону.",h="Келдран — орк-агент, що діє трохи на північ від Долини Духів в Оргріммарі.",kw={"келдран","дипломатія","пустограй","палаючий клинок","таката стілблейд","альянс"},ang={["class:Warlock"]="Таємна війна Келдрана з Палаючим Клинком показує, як сильно провід Орди прагне відмежуватися від неконтрольованої демонічної скверни.",["faction:Horde"]="Келдран представляє далекоглядну частину Орди, що розуміє: не позбувшись демонічної слави, тривалого миру в Калімдорі не досягти."},sec={{t="Дипломатичний похід",b="Поки Тралл править із Долини Мудрості, Келдран з червоних кам'яних терас міста намагається розв'язати давню дипломатичну біду. Альянс досі вважає всіх орків кровожерними маріонетками демонічних володарів — славу, що закріпилася за ними ще в перших війнах. Переконаний, що навіть Тралл утомився від нескінченних війн, Келдран вважає, що справжні мирні перемовини неможливі, доки в Калімдорі живуть культи демонопоклонників. Не маючи офіційного дозволу Вождя, він бере справу на себе й посилає довірених агентів назустріч далеким загрозам, щоб раз і назавжди змити демонічну пляму."},{t="Війна в Пустограї",b="Щоб мати що показати Альянсу, Келдран цілить у похмурі пустища Пустограю. Він відрядив Такату Стілблейд і Мауріна Боунспліттера очолити боротьбу з тамтешньою демонічною навалою, особливо наголошуючи на винищенні культистів Палаючого Клинка. Знищивши цих демонічних адептів і принісши до Оргріммара відчутні докази, Келдран сподівається незаперечно довести, що нова Орда — такий самий ворог Легіону, як люди й нічні ельфи."}},faq={{q="Хто такий Келдран?",a="Келдран — орк, що стоїть на північ від Долини Духів в Оргріммарі. Він організовує боротьбу з демонічним впливом, щоб прокласти шлях до дипломатичних стосунків з Альянсом.",al={"хто такий келдран","лор келдрана","келдран нпс"}},{q="Чому Келдрана хвилюють стосунки з Альянсом?",a="Келдран вважає, що Тралл утомився від нескінченної війни з Альянсом. Він знає: доки Альянс думає, що Орда досі в змові з Палаючим Легіоном, мирні перемовини неможливі.",al={"чому стосунки з альянсом","мотиви келдрана","чому він хоче миру"}},{q="Чи діє Келдран за офіційним наказом Тралла?",a="Ні. Келдран не має офіційного дозволу Вождя Тралла на свою справу: він вирішив діяти самостійно, щоб очистити ім'я Орди й закласти підґрунтя для майбутнього миру.",al={"чи тралл послав келдрана","накази тралла келдрану","чи келдран діє офіційно"}},{q="Що Келдран робить у Пустограї?",a="Він послав Такату Стілблейда й Мауріна Боунспліттера до Пустограю, щоб знищити місцеві демонічні сили й рішуче викорінити культ Палаючого Клинка.",al={"операція в пустограї","чому пустограй","келдран палаючий клинок"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="Келм Гарґунт",s="Келм Гарґунт — головний постачальник та інтендант Дозорців Пісні Війни, що стоїть у Базовому Таборі Мор'шан на північному кордоні Пусток. Він споряджає звитяжців Орди, які б'ються з нічними ельфами в спірних лісах Ущелини Бойової Пісні. Його посилки й харчі гарантують, що передова ніколи не лишиться без припасів.",h="Келм Гарґунт — головний постачальник та інтендант Дозорців Пісні Війни, що стоїть у Базовому Таборі Мор'шан...",kw={"келм гарґунт","інтендант","дозорці пісні війни","базовий табір мор'шан","ущелина бойової пісні","ашенваль"},ang={["class:Warrior"]="Воїни на передовій покладаються на міцні латні поножі, важкі клинки й бойові пайки Гарґунта, щоб тримати оборону проти Альянсу.",["faction:Horde"]="Келм Гарґунт дає знаряддя війни кожному бійцеві Орди, готовому взятися за зброю проти нічних ельфів в Ущелині Бойової Пісні.",["race:Orc"]="Для орків Гарґунт — той, хто дбає, щоб спадщина Ґрома Хеллскріма в Ашенвалі жила: він тримає клан Бойової Пісні озброєним і ситим."},sec={{t="Інтендант Мор'шану",b="На земляних валах над Ашенвалем Келм Гарґунт керує постачанням Дозорців Пісні Війни в Базовому Таборі Мор'шан. Поки розвідники й нападники б'ються за частоколом, Гарґунт стежить за потоком зброї, обладунків і харчів, без яких не витримати затяжної прикордонної війни. Для нього перемога над Вартовими Срібнокрилих залежить від надійного постачання так само, як і від чистої бойової люті."},{t="Постачання передової",b="Гарґунт роздає особливі припаси воїнам, які довели свою доблесть в ущелині. Від спеціальних посилок, напханих польовими перев'язками й сухими пайками, до майстерно викуваної зброї з багряними знаками клану Бойової Пісні — його запаси призначені тільки для тих, хто проливає кров за територіальні прагнення Орди в багатих на деревину лісах на півночі."}},faq={{q="Хто такий Келм Гарґунт?",a="Келм Гарґунт — орк, інтендант Дозорців Пісні Війни. Він служить у Базовому Таборі Мор'шан на півночі Пусток і роздає зброю, обладунки й бойові припаси воїнам Орди, що б'ються в Ущелині Бойової Пісні.",al={"келм гарґунт","хто такий келм","торговець мор'шан","торговець співу війни"}},{q="Де перебуває Келм Гарґунт?",a="Він у Базовому Таборі Мор'шан, на самому північному краю Пусток, просто біля валу, що відмежовує їх від Ашенвалю.",al={"місце келма","де келм гарґунт","офіцер постачання мор'шан"}},{q="Якій фракції служить Келм Гарґунт?",a="Він служить Дозорцям Пісні Війни — авангардові Орди, що добуває деревину й відвойовує в нічних ельфів землі на півдні Ашенвалю.",al={"фракція келма","інтендант розвідників співу війни","на кого працює келм"}},{q="Що за пакунки з припасами пропонує Келм?",a="Гарґунт роздає бійцям на передовій Базові, Стандартні й Поліпшені пакунки з припасами. У цих наборах — найпотрібніше для бою: дрібне спорядження, бинти й пайки, щоб воїни Орди трималися в ущелині.",al={"пакунок розвідника","пакунок келма","пакунок співу війни"}},{q="Чому Базовий Табір Мор'шан такий важливий для Пісні Війни?",a="Базовий Табір Мор'шан — укріплене місце збору й пропускний пункт між Пустками й Ашенвалем, завдяки якому клан Пісні Війни безпечно переправляє до земель Орди припаси, підкріплення й заготовлену деревину.",al={"чому базовий табір мор'шан","мета мор'шан","лор базового табору"}},{q="Яке спорядження дає Келм Гарґунт?",a="Він видає перевіреним бійцям бойові табарди Пісні Війни, особливу зброю на кшталт Клинка Розвідника й Меча Легіонера, комплекти обладунків, персні й бойові зілля для сутичок зблизька.",al={"спорядження келма для пвп","нагороди співу війни","що продає келм"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {n="Керлоніан Евершейд",s="Керлоніан Евершейд — нічний ельф, Друїд Пазура, що відпочиває в Гаю Прадавніх на Темному Узбережжі. Щойно прокинувшись після довгого перебування в Смарагдовому Сні, він потребує допомоги, щоб пробратися спотвореними нетрями до безпечного Посту Маестри.",h="Керлоніан Евершейд — нічний ельф, Друїд Пазура, що відпочиває в Гаю Прадавніх на Темному Узбережжі.",kw={"керлоніан евершейд","друїд пазура","гай прадавніх","смарагдовий сон","пост маестри","третя війна"},ang={["class:Druid"]="Друїди-шукачі пригод добре розуміють халепу Керлоніана, адже всім учням Кола Кенарія доводиться розплачуватися за глибоке єднання зі Смарагдовим Сном.",["race:NightElf"]="Для мандрівників із нічних ельфів супроводжувати Керлоніана — означає оберігати одного з давніх захисників свого народу, що щойно повернувся у світ, який так змінився після Третьої війни."},sec={{t="Пробудження на Темному Узбережжі",b="Kerlonian Evershade belongs to the Druids of the Claw, followers of the bear totem who spent centuries sleeping in barrows and communion with the Emerald Dream. The Druids of the Claw were called from their slumber during the Third War. Found resting beneath the ancient trees of the Grove of the Ancients, Kerlonian is still shaking off the supernatural grogginess of his prolonged rest. His immediate concern is traveling safely through the troubled forests of Darkshore toward Maestra's Post on the border of Ashenvale."},{t="Підступна дорога",b="Дорога з Гаю Прадавніх аж ніяк не безпечна. Пошесть, що шириться Темним Узбережжям, розлютила місцевих звірів і привела ворожих хижаків і греллів аж до священних галявин. Ослаблений сном і змагаючись із раптовими нападами втоми, Керлоніан покладається на співчутливих мандрівників Альянсу, які захистять його дорогою на південь, до побратимів — нічних ельфів."}},faq={{q="Хто такий Керлоніан Евершейд?",a="Керлоніан Евершейд — нічний ельф, Друїд Пазура, що перебуває біля Гаю Прадавніх на Темному Узбережжі. Він нещодавно прокинувся зі Смарагдового Сну, і йому потрібна допомога, щоб безпечно пройти лісом.",al={"хто такий керлоніан","лор керлоніана евершейда","друїд у гаю прадавніх"}},{q="Чому Керлоніан засинає просто на ходу?",a="Як і багато Друїдів Пазура, що століттями спали в курганних лігвах, Керлоніан досі не позбувся заціпеніння Смарагдового Сну. Його тіло й розум ще не цілком звикли до яви, тож його раз у раз раптово хилить на сон.",al={"чому керлоніан спить","завдання сплячий прокинувся друїд","керлоніан сонний"}},{q="Куди він намагається дістатися?",a="Він хоче безпечно дійти на південь до Посту Маестри — застави нічних ельфів на межі Темного Узбережжя й Ашенвалю, де зможе спокійно відновити сили.",al={"куди прямує керлоніан","де керлоніан йде","кінцева точка гаю прадавніх"}},{q="Хто такі Друїди Пазура?",a="Друїди Пазура — нічні ельфи-друїди, які шанують прадавнього ведмедя Урсока. Вони черпають силу, витривалість і звірину міць, здавна стережуть кургани й землі нічних ельфів і віками сплять у Смарагдовому Сні.",al={"що таке друїд пазура","лор друїдів пазура"}}},fp="19,262,22.522.0,21.395.0,27.204.0,45.243.0,25.154.0,28.229.0"}
P.entries["npc:kernobee"] = {n="Кернобі",s="Кернобі — гоблін-інженер, що застряг глибоко в зруйнованих залах Гномреґана. Натрапивши на небезпечні таємниці про диверсії дворфів Темного Заліза, він потрапив у полон, був побитий до непритомності й покинутий помирати серед трогів у житлових кварталах.",h="Кернобі — гоблін-інженер, що застряг глибоко в зруйнованих залах Гномреґана.",kw={"кернобі","гоблін","гномреґан","темне залізо","супербурова установка","тінкервіз","раджет"},ang={["profession:Engineering"]="Інженери розуміють, наскільки небезпечно нишпорити біля експериментальних підземних машин, як-от установки Темного Заліза, коли на кону креслення суперників.",["race:Gnome"]="Для гномів, що борються за повернення батьківщини, відомості Кернобі — тривожний доказ того, що дворфи Темного Заліза потай доклали руку до їхньої катастрофи."},sec={{t="Смертельне відкриття",b="Ведучи справи чи нишпорячи в полеглій гномській столиці, Кернобі розкрив страшну таємницю: дворфи Темного Заліза безпосередньо причетні до будівництва й роботи величезної супербурової установки, що вгризається під місто. Усвідомивши величезну цінність — і смертельну небезпеку — цих відомостей, він спробував негайно втекти до Раджета, щоб передати звістку своєму компаньйонові Тінкервізу. На жаль, дворфи Темного Заліза схопили його, перш ніж він устиг утекти."},{t="Покинутий трогам",b="Замість убити Кернобі на місці, кривдники побили гобліна до непритомності й кинули в маленьку кімнату в коридорі гуртожитку, навпроти Чистої Зони. Покинутий серед диких трогів і радіоактивних опадів, побитий гоблін цілком залежить від шукачів пригод, які приведуть його до тями й захищатимуть, доки він не дістанеться безпечного місця."}},faq={{q="Хто такий Кернобі?",a="Кернобі — гоблін-агент, якого знаходять непритомним у житловому секторі Гномреґана. Він тісно співпрацює з Тінкервізом із Раджета й вирушив до руїн, але потрапив у засідку.",al={"хто цей гоблін","лор кернобі","про кернобі"}},{q="Чому Кернобі опинився в полоні в Гномреґані?",a="Кернобі з'ясував, що клан Темного Заліза потай допомагає будувати в місті підземні супербурові машини. Щоб приховати свою присутність і диверсії, дворфи Темного Заліза знешкодили його й кинули в Гуртожитку на смерть.",al={"чому він тут","чому темне залізо схопило його","чому в гуртожитку"}},{q="Кому звітує Кернобі?",a="Він звітує Тінкервізові — гобліну-інженерові, що працює за морем, у нейтральному портовому містечку Раджет у Пустках.",al={"хто такий тінкервіз","куди він іде","зв'язок із раджетом"}},{q="Де саме в Гномреґані Кернобі?",a="Він лежить непритомний у невеликій бічній кімнаті на нижньому рівні Гуртожитку, із західного боку, просто навпроти Чистої Зони.",al={"місце кернобі","де кернобі","знайти кернобі"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="Керін Сильвій",s="Керін Сильвій — наставниця розбійників, людина, що мешкає на другому поверсі корчми «Лев'яча Гордість» у Ґолдширі. Усамітнившись у читальні корчми, вона навчає молодих шибеників основ скрадання й володіння клинком і водночас тихо підтримує зв'язок із розвідкою Стормвінда.",h="Керін Сильвій — наставниця розбійників, людина, що мешкає на другому поверсі корчми «Лев'яча Гордість» у...",kw={"керін сильвій","наставниця розбійників","ґолдшир","лев'яча гордість","si:7","ліс елвінн"},ang={["class:Rogue"]="Сильвій — головна наставниця для молодих розбійників, що мандрують Лісом Елвінн; згодом вона скеровує їх до штабу SI:7 у Стормвінді.",["faction:Alliance"]="Зі свого місця над ґолдширським перехрестям вона допомагає таємним очам Альянсу пильнувати головні шляхи Елвінна."},sec={{t="Тиха присутність у Ґолдширі",b="Поки на першому поверсі корчми «Лев'яча Гордість» вирує гамір галасливих мандрівників і втомлених міських вартових, Керін Сильвій тримається тихої читальні нагорі. Зовні непримітна, вона уважно слухає невпинний потік дорожніх пліток і наставляє розбійників, які роблять перші кроки в Лісі Елвінн. Коли здібні агенти переростають дрібні місцеві крадіжки й придорожні капості, Сильвій непомітно відсилає їх далі, до Стормвінда, щоб вони вийшли на зв'язок із SI:7."}},faq={{q="Де знайти Керін Сильвій?",a="Вона на другому поверсі корчми «Лев'яча Гордість» у Ґолдширі, у невеликій відлюдній читальні.",al={"місце керін","де керін","тренер розбійників ґолдшира"}},{q="Які послуги вона надає?",a="Керін Сильвій — наставниця розбійників: навчає нових умінь, скидає спеціалізацію талантів і дає поради розбійникам, які зростають.",al={"що робить керін","чи навчає вона мене","роль керін сильвій"}},{q="Що пов'язує її з SI:7?",a="Сильвій — одна з перших ланок таємної розвідувальної мережі Стормвінда: вправних агентів, які довели свої здібності, вона посилає до Майстра Матіаса Шоу й SI:7 у Старому Місті.",al={"керін таємна служба","чи вона таємна агентка","чи працює на стормвінд"}}},fp="13,279,29.470.0,31.108.0,29.135.0,38.201.0"}
P.entries["npc:khelden-bremen"] = {n="Келден Бремен",s="Келден Бремен — людський маг і наставник на верхньому поверсі Абатства Нортшира в Лісі Елвінн. Він наглядає за найпершим навчанням чарівників-новачків, що беруться за таємні мистецтва на службі Стормвінду.",h="Келден Бремен — людський маг і наставник на верхньому поверсі Абатства Нортшира в Лісі Елвінн.",kw={"келден бремен","маг","наставник","абатство нортшира","таємна магія","нортшир"},ang={["class:Mage"]="Для людей-магів Келден Бремен — перший офіційний крок у таємну науку перед поглибленим навчанням у вежах Стормвінда."},sec={{t="Учитель таємної магії",b="У спокійних кам'яних стінах Абатства Нортшира Келден Бремен — головний наставник людей-магів-початківців. Поки духівництво й захисники внизу дбають про військові й духовні справи, Бремен тримає тихий кабінет нагорі. Тут він знайомить новачків із дисципліною, зосередженістю й основними прийомами, потрібними, щоб безпечно ткати сиру магічну енергію, перш ніж вони вирушать у Ліс Елвінн і далі — до Кварталу магів Стормвінда."}},faq={{q="Хто такий Келден Бремен?",a="Келден Бремен — наставник магів в Абатстві Нортшира в Лісі Елвінн. Він проводить новоприбулих магів через їхні перші заклинання й основи тайної науки.",al={"хто такий келден","бремен","тренер магів нортшира"}},{q="Де знайти Келдена Бремена?",a="Він на другому поверсі Абатства Нортшира. Увійдіть до абатства й підніміться сходами з другої кімнати ліворуч.",al={"де келден","місце келдена бремена","тренер магів нортшира"}},{q="Яку роль він відіграє для новачків?",a="Майбутні маги-люди, прибувши до Нортшира, ідуть до Келдена, найчастіше з рекомендаційним Гліфічним Листом. Він навчає найпотрібніших перших заклинань і допомагає новачкам розвинути свій магічний хист.",al={"що робить келден","завдання бремена","одержувач літерного листа"}}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kil-hala"] = {n="Кіл'гала",s="Кіл'гала — троль із джунглів, наставник кравецтва на Перехресті в Пустках. Він уміє працювати і з буденною тканиною, і з екзотичними плетивами й навчає ремісників Орди, що прагнуть удосконалити своє шиття. А ще він посилає завзятих кравців на північ, до Ашенвалю, по рідкісні матеріали на кшталт мережива Нижнього Світу.",h="Кіл'гала — троль із джунглів, наставник кравецтва на Перехресті в Пустках.",kw={"кіл'гала","кравецтво","перехрестя","тролі","мереживо нижнього світу","пустки"},ang={["faction:Horde"]="Постачаючи тканини й навчаючи ремесла на Перехресті, Кіл'гала допомагає спорядити бойовий загін і мандрівників, що закріплюються в Пустках.",["profession:Tailoring"]="Кіл'гала — обов'язкова зупинка для досвідчених кравців Орди, що мандрують Калімдором: він навчає ремісничих прийомів і дає завдання пошити екзотичні чарівні мантії."},sec={{t="Кравець Пусток",b="Кіл'гала, що влаштувався в гамірному осередку Перехрестя, ділиться кравецьким умінням із перехожими мандрівниками й новобранцями Орди. Здебільшого його ремесло — це звичайні сувої тканини та одяг для життя на сухих рівнинах, але його знання сягають і рідкісних чарівних тканин. Щоб пошити справді видатні мантії, Кіл'гала кидає ткачам виклик: вирушити в дикі хащі Ашенвалю, де неземні матеріали, як-от мереживо Нижнього Світу, можна здобути в чарівних дріад."}},faq={{q="Хто такий Кіл'гала?",a="Кіл'гала — троль Темного Спису й наставник кравців на Перехресті в Пустках. Він допомагає ремісникам Орди опанувати основи ткацтва й шиття одягу.",al={"особа кіл'гали","хто такий кіл'гала","кравець перехрестя"}},{q="Де знайти Кіл'галу?",a="Він у Пустках, у головному поселенні Перехрестя, поруч з іншими наставниками ремесел Орди.",al={"місце кіл'гали","де кіл'гала","точка кіл'гали"}},{q="Які завдання Кіл'гала дає кравцям?",a="Ткачів, які прагнуть вищої майстерності, він посилає до Ашенвалю полювати на дріад, відомих як Сміхотливі Сестри. З їхніх ефірних кіс Кіл'гала творить неповторне Вбрання з мережива Нижнього Світу.",al={"завдання кіл'гали","завдання сміхотливих сестер","одяг із мережива пустоти"}}},fp="8,339,21.461.0,16.189.0,26.124.0,41.197.0"}
P.entries["npc:kin-weelay"] = {n="Кін'вілей",s="Кін'вілей — уславлений знахар із племені Темного Списа, що перебуває в Базовому Таборі Ґром'ґол у Долині Стренглторну. Його послали просто з Оргріммара, щоб він допомагав порадами й містичною силою передовому загону Орди в джунглях. Його духовне знання вкрай потрібне, щоб розплутати темне моджо й допомогти врятувати юного Єнніку.",h="Кін'вілей — уславлений знахар із племені Темного Списа, що перебуває в Базовому Таборі Ґром'ґол у Долині...",kw={"кін'вілей","знахар","темний спис","ґром'ґол","єнніку","моджо"},ang={["faction:Horde"]="Кін'вілей доводить, яку цінність має для воєнних зусиль Орди тролячий спіритуалізм: він дає магічну відповідь на загрози, яких не зламати самою силою.",["race:Troll"]="Для тролів Темного Списа Кін'вілей — один із найшанованіших духовних авторитетів племені, що присвятив себе зняттю жорстоких прокльонів, які насилають їхні родичі з джунглів."},sec={{t="Майстер моджо Темного Списа",b="Серед тролів Темного Списа Кін'вілея вважають одним із наймогутніших знавців традиційного чаклунства: він глибоко знається на духах, прокляттях і магії душ. Коли йдеться про духів предків чи ворожі тролячі чари, розвідники Орди в Долині Стренглторну звертаються саме до нього, щоб він прорвав магічну завісу."},{t="Доручення в Ґром'ґолі",b="Кін'вілея відрядили на південь із курних вулиць Оргріммара саме для того, щоб він підтримав Німбою в Базовому Таборі Ґром'ґол. Його мета — не лише військова допомога: він зосереджений на тому, щоб розірвати зловісні чари, накладені на Єнніку — викраденого сина з довіреного роду вождя Вол'джина. Щоб звести нанівець таке темне ремесло, Кін'вілей шукає могутніх реагентів — передусім Око Розуму, — аби створити камінь душ, здатний визволити полонених духів."}},faq={{q="Хто такий Кін'вілей?",a="Кін'вілей — шанований троль-знахар Темного Спису, що служить у Базовому Таборі Ґром'ґол на півночі Долини Стренглторну. Він славиться майстерністю в магії духів і душ, і його прислали сюди очільники Орди з Оргріммара.",al={"лор кін'вілей","хто такий кін'вілей","знахар громґол"}},{q="Чому Кін'вілей у Долині Стренглторну?",a="Його відрядили до Базового Базового Табору Ґром'ґол, щоб він допоміг своїм містичним хистом Німбої та місцевій експедиції Темного Спису, насамперед — знайти юного Єнніку й вирвати його з лап ворожих тролів джунглів.",al={"чому кін'вілей у долині стренглторну","мета кін'вілей"}},{q="Що намагається створити Кін'вілей?",a="Кін'вілей прагне здобути реліквію, відому як Око Розуму. Своїм чаклунством він хоче перетворити її на самоцвіт душі, що вловить і безпечно збереже душу Єнніку, розірвавши темні чари, які тримають хлопця.",al={"розум кін'вілей","що створює кін'вілей"}},{q="Звідки родом Кін'вілей?",a="Він прибув з Оргріммара, де плем'я Темного Спису має міцні зв'язки й вагу відтоді, як приєдналося до Орди й оселилося на Островах Відлуння.",al={"минуле кін'вілей","звідки кін'вілей"}},{q="Як він ставиться до інших тролячих племен Стренглторну?",a="Ворожі племена джунглів, як-от Кривавий Скальп і Череполоми, він вважає небезпечними суперниками, що погрузли в жорстоких, зіпсованих ритуалах. Він охоче використовує своє ремесло, щоб протидіяти їхнім чарам і повертати викрадену молодь Темного Спису.",al={"кін'вілей інші тролі","кін'вілей і кривавий скальп"}},{q="Які предмети вивчає Кін'вілей?",a="Кін'вілей досліджує місцеві дивовижі з природною чи наврочною силою — зокрема загадкові співучі кристали й кістяні намиста, які носять ворожі тролі джунглів, — і вивчає їхнє моджо, щоб знайти протидію.",al={"предмети кін'вілей","співочі кристали кін'вілей"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kindal-moonweaver"] = {n="Кіндал Мунвівер",s="Кіндал Мунвівер — нічна ельфійка, що сховалася в потаємному закутку серед скелястих гір Фераласу, трохи на північ від Поселення Ґрімтотем. Глибоко стривожена жорстоким поводженням зі звіриною в глушині, вона стежить за войовничим тауренським племенем унизу й шукає допомоги, щоб звільнити полонених звірів. Як і Джер'кай Мунвівер, з ким її пов'язує спорідненість, вона стала на захист невинних створінь лісу.",h="Кіндал Мунвівер — нічна ельфійка, що сховалася в потаємному закутку серед скелястих гір Фераласу, трохи на...",kw={"кіндал мунвівер","нічні ельфи","фералас","ґрімтотем","фея-стрілохвіст","звірі","джер'кай мунвівер"},ang={["class:Druid"]="Друїди знайдуть спільну мову з Кіндал: вона цілковито віддана збереженню лісового життя й визволенню полонених духів природи з жорстоких залізних кліток.",["class:Hunter"]="Мисливці, які відчувають звірів Калімдору, можуть поважати зусилля Кіндал: вона захищає диких малят і карає тих, хто ловить звірину заради розваги чи зі злоби.",["race:NightElf"]="Кіндал утілює традиційну відданість калдореїв природному світові: вона самотньо стоїть на сторожі звірів, яким загрожують чужі загарбники."},sec={{t="Спостерігачка на скелях",b="На вузькій звивистій гірській стежці, частково прихованій за деревами на схід від Лютопащу, Кіндал Мунвівер таємно пильнує долину внизу. Більшу частину Фераласу ділять між собою Орда, нічні ельфи з Твердині Перистого Місяця й мешканці давніх руїн Елдре'Таласу, але Кіндал зосереджена на ближчій і нагальнішій жорстокості. Унизу, в улоговині, плем'я Ґрімтотем тримає укріплене поселення, де ловить і замикає в загонах місцеву звірину, і мета в нього аж ніяк не добра. Зі свого прихованого оглядового місця Кіндал виглядає того, хто наважиться пробратися до ворожого табору й покласти край стражданням усередині."},{t="Співчуття до дикої природи",b="Найбільше Кіндал турбують священна рівновага й лагідні створіння Фераласу, які не можуть захиститися від брутальних ловців. Разом із Джер'каєм Мунвівером, з ким її пов'язує спорідненість, вона домагається звільнення звірів із кліток і дбає про молодняк, що лишився сам після жорстокого браконьєрства. Замість великої війни за землі вона обирає співчуття: звільняє ув'язнених фей і шукає дім для осиротілої феї-стрілохвоста."}},faq={{q="Де перебуває Кіндал Мунвівер?",a="Кіндал ховається на північних кручах Фераласу, трохи на схід від Лютопаща, над Поселенням Ґрімтотем. Дістатися до неї можна вузькою прихованою гірською стежкою, що в'ється вгору за купкою дерев.",al={"місце кіндал","як знайти кіндал","де кіндал"}},{q="Хто така Кіндал Мунвівер?",a="Це самітниця, нічна ельфійка, що присвятила себе захисту тварин і збереженню природи Фераласу. Вона стежить за Поселенням Ґрімтотем, щоб заважати їм ловити місцевих звірів.",al={"лор кіндал","хто така кіндал"}},{q="Яка мета Кіндал у Фераласі?",a="Кіндал хоче визволити звірів, замкнених у клітках у сусідньому Поселенні Ґрімтотем, і подбати, щоб осиротілих диких тварин урятували й дали їм безпечний прихисток.",al={"мета кіндал","чому кіндал тут"}},{q="Чи Кіндал Мунвівер родичка Джер'кая Мунвівера?",a="Так, Кіндал — родичка Джер'кая Мунвівера. Обоє носять родове ім'я Мунвіверів і разом рятують скривджених і вигнаних із рідних місць лісових створінь у центральному Калімдорі.",al={"зв'язок із джер'каєм мунвівером","кіндал і джер'кай"}},{q="Чому Кіндал протистоїть Ґрімтотемам?",a="Клан Ґрімтотем, що зайняв поселення під її гірським сховком, ловить і замикає в клітки диких звірів Фераласу. Кіндал прагне визволити цих тварин із неволі й покарати їхніх ловців.",al={"кіндал ґрімтотем","табір ґрімтотемів кіндал"}},{q="Чи дає Кіндал Мунвівер завдання обом фракціям?",a="Ні. Кіндал дає завдання лише Альянсу: його шукачів пригод вона просить визволити звірів із кліток Ґрімтотемів.",al={"чи кіндал дружня до орди","чи орда може говорити з кіндал"}}},fp="17,391,26.598.0,23.447.0,35.210.0,25.182.0,33.174.0,51.184.0,37.191.0,53.131.0"}
P.entries["npc:kirge-sternhorn"] = {n="Кірґе Стернгорн",s="Кірґе Стернгорн — таурен, що несе службу на суворому прикордонні Пусток. Для мандрівників, які перетинають центральний Калімдор, він — надійна опора: молодих шукачів пригод з Орди він скеровує на північ, до важливої застави Перехрестя.",h="Кірґе Стернгорн — таурен, що несе службу на суворому прикордонні Пусток.",kw={"кірґе стернгорн","таурени","перехрестя","провідник","пустки","калімдор"},ang={["faction:Horde"]="Для мандрівників, що виходять із південних околиць, Кірґе — один із перших дороговказів, що скеровує їх до великої громади Орди на Перехресті.",["race:Tauren"]="Кірґе уособлює врівноважений, гостинний дух шу'гало: він веде одноплемінників і союзників крізь суворе прикордоння їхньої нової батьківщини."},sec={{t="Мандрівник у Пустках",b="Неосяжні, випалені сонцем рівнини Пусток лякають новоприбулих мандрівників, і Кірґе Стернгорн стає їм у пригоді як провідник. Стоячи на південь від центральних стежок, він пильнує мандрівників, що прямують між південними таборами й серцем Калімдору. Знаючи, які небезпечні шипогриви-грабіжники й люті хижаки, що никають саваною, Кірґе допомагає молодим шукачам пригод стати на ноги й шукати більших сил Орди, що збираються на півночі."}},faq={{q="Хто такий Кірґе Стернгорн?",a="Кірґе Стернгорн — таурен-мандрівник і провідник на півдні Пусток, що допомагає мандрівникам Орди знаходити шлях запиленими рівнинами.",al={"лор кірґе стернгорна","хто такий кірґе","кірґе нпс"}},{q="Куди Кірґе посилає мандрівників?",a="Кірґе спрямовує мандрівників на північ, до Перехрестя — головного вузла Пусток, звідки сили Орди керують обороною й розвідкою в усьому краї.",al={"завдання кірґе","подорож до перехрестя кірґе","куди кірґе посилає"}},{q="Якій фракції служить Кірґе Стернгорн?",a="Кірґе вірний Орді й своїм одноплемінникам-тауренам і дає поради та допомогу всім членам фракції, що мандрують цими землями.",al={"чи кірґе з орди","вірність кірґе"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="Кланнок Маклауд",s="Кланнок Маклауд — суворий людський воїн, що живе на Острові Бійки біля східних берегів Пусток. Знаний як суддя бойової майстерності, він випробовує завзятих бійців і з Альянсу, і з Орди, які прагнуть опанувати бойові стійки. Тих, хто здобуде його повагу, він скеровує вглиб суходолу до ще суворіших випробувань сили.",h="Кланнок Маклауд — суворий людський воїн, що живе на Острові Бійки біля східних берегів Пусток.",kw={"кланнок маклауд","острів бійки","бійка","стійка берсерка","воїн","пустки"},ang={["class:Warrior"]="Кланнок Маклауд — ключова постать на шляху воїна: він випробовує вашу витривалість і лють у Бійці, а тоді веде вас до опанування Стійки берсерка.",["faction:Alliance"]="Воїнам Альянсу доведеться вирушити далеко у води Калімдору біля узбережжя Пусток, щоб знайти Кланнока й довести свою бойову готовність на Острові Бійки.",["faction:Horde"]="Хоч Кланнок і людина, суперництво фракцій йому байдуже: він радо приймає бійців Орди, що прибувають на його відлюдний острів по випробування й честь."},sec={{t="Господар Острова Бійки",b="На відлюдному Острові Бійки біля Узбережжя Крамарів Пусток Кланнок Маклауд наглядає за жорстоким полігоном для досвідчених бійців. Хоч Кланнок і людина, він тримається осторонь звичних політичних чвар Альянсу й Орди й судить суперників лише за їхньою витримкою, вправністю з клинком і рішучістю під ударами."},{t="Бійка",b="Воїнів, яких посилають на Острів Бійки, чекає випробування Маклауда — Бійка. Суперники стають на піднесену залізну решітку й витримують безупинні хвилі завзятих забіяк, поки Кланнок спостерігає. Ті, хто витримає натиск і здолає обраного ним поборника, здобувають його схвалення — доказ того, що вони мають вдачу, потрібну для навчання берсерка."}},faq={{q="Хто такий Кланнок Маклауд?",a="Кланнок Маклауд — бувалий воїн-людина, що живе на Острові Бійки біля узбережжя Пусток. Він наставник і суддя випробувань для воїнів, які прагнуть перевірити межі своїх сил і опанувати нові прийоми.",al={"хто такий кланнок","лор кланнока маклауда","чолов'яга з острова бійки"}},{q="Де знайти Кланнока Маклауда?",a="Кланнок на Острові Бійки — скелястому острові біля східного узбережжя Пусток, на південний схід від Узбережжя Крамарів й Раджета. Щоб дістатися до його табору, доведеться перепливти відкриту воду.",al={"місце кланнока","де острів бійки","як дістатися до кланнока"}},{q="Чому людина розмовляє з гравцями Орди на Острові Бійки?",a="Кланнок стоїть осторонь звичної ворожнечі Альянсу й Орди. Як незалежний майстер бою, він дбає лише про бойову дисципліну й кодекс воїна й охоче випробовує кожного претендента, який прибуде з належною рекомендацією.",al={"чи кланнок ворожий до орди","чому кланнок нейтральний","кланнок орда"}},{q="Що таке «Сутичка»?",a="«Сутичка» — випробування на витривалість, що відбувається на Острові Бійки. Воїн має стати на бойовий поміст Кланнока й здолати хвилі суперників, а наостанок — Здорованя Вілла, довівши, що має лють, потрібну для вищих прийомів воїна.",al={"завдання сутичка","випробування острова бійки","випробування кланнока"}},{q="Навіщо посилати воїнів до Кланнока Маклауда?",a="Наставники воїнів по всьому Азероту посилають своїх найперспективніших учнів до Кланнока пройти випробування бойової стійкості, без якого не опанувати шаленої зосередженості Стійки Берсерка.",al={"завдання воїна острів бійки","навіщо йти до кланнока","завдання стійки берсерка"}},{q="До кого Кланнок посилає після «Сутички»?",a="Коли воїн доведе свою вартість у «Сутичці», Кланнок посилає його на північ, у Гори Альтерак, неподалік від Таррен Мілла, щоб знайти Бат'ру Спостерігача Вітрів і отримати подальші настанови.",al={"після кланнока","завдання віндвотчера","хто такий віндвотчер"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="Кор'ґан",s="Кор'ґан — троль із джунглів Темного Списа, якого можна знайти в похмурих печерах Тіньової Розколини в Оргріммарі. Стоячи просто біля «Отрут Реккула», він шукає помічників для приготування ліків проти отруйних хижаків нетрів.",h="Кор'ґан — троль із джунглів Темного Списа, якого можна знайти в похмурих печерах Тіньової Розколини в...",kw={"кор'ґан","тіньова розколина","оргріммар","отрути","реккул","протиотрута","троль"},ang={["class:Rogue"]="Кор'ґан, що стоїть просто біля «Отрут Реккула» в Тіньовій Розколині, — звична постать для розбійників, які навідуються в підземелля Оргріммара по реагенти й отрути.",["race:Troll"]="Як і багато родичів із Темного Списа, що покинули Село Сен'джин, Кор'ґан застосовує практичні знання про дикі небезпеки Дуротару в укріпленій столиці Орди."},sec={{t="Троль у тіні",b="Стоячи перед «Отрутами Реккула» в печерних глибинах Тіньової Розколини, Кор'ґан пильно стежить і за ліками, і за отрутами. Зі столиці він посилає шукачів пригод через червоні каньйони збирати отруйні складники зі скорпідів Дуротару, щоб готувати життєво важливі протиотрути."}},faq={{q="Хто такий Кор'ґан?",a="Кор'ґан — троль Темного Спису, що стоїть у Тіньовій Розколині в Оргріммарі, біля крамниці отрут Реккула.",al={"кор'ґан","хто такий кор'ґан","кор'ґан нпс"}},{q="Де знайти Кор'ґана?",a="Він у підземній Тіньовій Розколині під центром Оргріммара, просто перед крамницею «Отрути Реккула».",al={"місце кор'ґана","де кор'ґан","знайти кор'ґана"}},{q="З чим Кор'ґанові потрібна допомога?",a="Він просить мандрівників зібрати отруйні залози скорпідів-отрутохвостів, що блукають біля входу до Оргріммара, щоб приготувати протиотрути.",al={"завдання кор'ґана","завдання пошуку протиотрути","отрута кор'ґана"}},{q="Чи можна було знайти Кор'ґана в Дуротарі?",a="Самого — ні. Кор'ґан тримається свого місця біля постачальників отрут в Оргріммарі, але посилає шукачів пригод до Дуротару по отруйні залози скорпідів-отрутохвостів біля входу до міста.",al={"кор'ґан сен'джин","старе місце кор'ґана"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="Корран",s="Корран — троль-дослідник із племені Темного Спису, що стоїть на Перехресті в Пустках. Служачи Белґромові Рокмолу в Оргріммарі, він стежить за дивними подіями в чагарникових степах і вивчає нову загрозу — комахоподібних силітидів.",h="Корран — троль-дослідник із племені Темного Спису, що стоїть на Перехресті в Пустках.",kw={"корран","силітиди","поле велетнів","белґром рокмол","темний спис","перехрестя"},ang={["faction:Horde"]="Корран — пильне око Орди на мінливу природу Калімдору: він дбає, щоб нові загрози, як-от силітиди, не заскочили Оргріммар зненацька, поки той зміцнює кордони.",["race:Troll"]="Як троль із Темного Спису, Корран приносить у посушливі Пустки гостре чуття розвідника й уміння виживати та з практичною хитрістю розбирається з дивними чужинськими звірами."},sec={{t="Розвідник на Перехресті",b="Більшість на Перехресті переймається войовничими шипогривами й місцевими кланами кентаврів, а Корран пильно стежить за тоншими, підступнішими загрозами. Опинившись тут за наказом Белґрома Рокмола з Оргріммара, троль-розвідник спостерігає за змінами в краї й керує збиранням відомостей для проводу Орди."},{t="Вторгнення силітидів",b="Головна тривога Коррана тепер на півдні, на Полі Велетнів, де дивні комахоподібні істоти, відомі як силітиди, почали вгризатися в землю. Стривожений їхньою агресивністю й стрімким наступом, він просить мандрівних шукачів пригод викопувати цілі яйця його кігтистим знаряддям, щоб з'ясувати, звідки взявся рій і яку небезпеку він становить для молодої Орди."}},faq={{q="Хто такий Корран?",a="Корран — троль Темного Спису, що служить на Перехресті в Пустках. Він спостерігач і дослідник, що звітує Белґромові Рокмолу в Оргріммарі.",al={"хто такий корран","троль корран","троль перехрестя"}},{q="Що Корран досліджує в Пустках?",a="Він досліджує дивних агресивних комахоподібних істот, відомих як силітиди, що з'явилися на півдні Пусток, на Полі Велетнів, а також схожі рої, які помітили ще південніше, у Тисячі Голок.",al={"що вивчає корран","дослідження коррана","поле велетнів комахи"}},{q="На кого працює Корран?",a="Корран служить Белґромові Рокмолу — досвідченому воїнові з Долини Честі в Оргріммарі, який стежить для Орди за новими загрозами в Калімдорі.",al={"хто послав коррана","начальник коррана","бельґром рокмаул"}},{q="Навіщо Корранові яйця силітидів?",a="Йому потрібні цілі яйця, щоб вивчити життєвий цикл і походження рою силітидів. Досліджуючи ранні зразки, Корран сподівається зрозуміти, що це за істоти й наскільки вони загрожують землям Орди.",al={"навіщо яйця силітидів","завдання полювання на яйця","кіготь коррана"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="Кравел Колбірд",s="Кравел Колбірд — підступний дворф-підприємець і шахрай, що отаборився на Перегонах Міражу в Мерехтливих Низинах. Уболіває він аж ніяк не з любові до спорту: запекле суперництво гномських і гоблінських гонщиків для нього — золота нагода напхати кишені. Від збирання загублених деталей до підлаштовування результатів заїздів шантажем і випивкою — Кравел завжди шукає наступну вигідну оборудку.",h="Кравел Колбірд — підступний дворф-підприємець і шахрай, що отаборився на Перегонах Міражу в Мерехтливих...",kw={"кравел колбірд","шахрай","перегони міражу","мерехтливі низини","шантаж","дворфи"},ang={["class:Rogue"]="Розбійникам ремесло Кравела видасться знайомим: крадіжки, диверсії, шантаж і маніпуляції жадібними жертвами з тіні.",["race:Dwarf"]="На відміну від чесних гірників, рудошукачів і горян Айронфорджа, Кравел — безсоромний пройдисвіт і ошуканець, що ганьбить традиційні дворфійські чесноти.",["race:Gnome"]="Гномам варто пильнувати свої кухлі й креслення поряд із Кравелом: він так само охоче приспить гномського пілота, як і зіпсує його машину."},sec={{t="Шахрай на солончаках",b="Поки більшість глядачів і механіків на Перегонах Міражу поглинені суперництвом машин і ревінням ракетних двигунів, Кравел Колбірд не зводить очей із чужих гаманців. Він пройдисвіт, що орудує в запилених закутках табору біля траси, і завжди готовий запропонувати угоду чи послугу з рідко чистими намірами. Гостре протистояння гномських і гоблінських інженерів, де на кону так багато, Кравел бачить не надихаючим змаганням, а родючим ґрунтом для вимагання, диверсій і крадіжок."},{t="Підлаштування перегонів",b="Оборудки Кравела не обмежуються збиранням викинутого брухту на солончаках. Щоб змінювати шанси й схиляти результати на свою користь, Кравел, як відомо, посилає охочих шукачів пригод із темними дорученнями — пускати чутки, прокручувати схеми шантажу й навіть напувати механіків просто перед вирішальним заїздом. Чи то пригощаючи гоблінських механіків міцними трунками, чи то підсовуючи гномським пілотам щось міцненьке, Кравел вдасться до будь-якої підлої витівки, аби в день перегонів набити кишені."}},faq={{q="Хто такий Кравел Колбірд?",a="Кравел Колбірд — дворф-інтриган і пройдисвіт, що крутиться біля Перегонів Міражу в Мерехтливих Низинах. Він наживається на суперництві гномів і гоблінів: перепродує уламки, підлаштовує перегони й вимагає гроші.",al={"хто такий кравел","особа кравела колбірда","дворф перегонів міражу"}},{q="Що Кравел Колбірд робить на Перегонах Міражу?",a="Кравел наймає мандрівників на темні справи довкола траси: збирати уламки ракетних автомобілів, шукати компромат і зривати виступи команд, напуваючи механіків і пілотів, щоб вплинути на результат перегонів.",al={"мета кравела","чого хоче кравел","задуми кравела"}},{q="Навіщо Кравел напуває команди перегонників?",a="Кравел робить великі ставки на перегони ракетних автомобілів. Напоївши перед стартом гномів чи гоблінів, він підлаштовує змагання під той результат, що принесе йому найбільший зиск.",al={"завдання напоїти гномів","напоїти гоблінів","саботаж кравела"}},{q="Де знайти Кравела Колбірда?",a="Він у Мерехтливих Низинах, що в Тисячі Голок, крутиться біля гамірних боксів Перегонів Міражу.",al={"місце кравела","де кравел","кравел тисяча голок"}},{q="Чи має Кравел зв'язки за межами Тисячі Голок?",a="Так. Його темні оборудки тягнуться до гоблінських портів Раджета й Буті Бею: тут і справи з Начальником Пристані Діззівігом із Раджета, і плітки, і екзотичні напої з Долини Стренглторну.",al={"кравел затока здобичі","зв'язки кравела"}},{q="Чи працюватиме Кравел і з Альянсом, і з Ордою?",a="Як і багатьох, хто орудує в нейтральних місцях на кшталт Перегонів Міражу, Кравела цікавить золото, а не вірність фракції. Він охоче найме для своїх оборудок шукачів пригод і з Альянсу, і з Орди.",al={"чи кравел лише для альянсу","чи орда може говорити з кравелом"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="Крелдіґ Унґор",s="Крелдіґ Унґор — заповзятливий дворфійський агент Компанії «Відновлювачі», що перебуває високо серед скель Мису Ніджела в Пустограї. Йому доручено керувати польовими справами в безплідній пустці, тож він наймає шукачів пригод Альянсу, щоб ті повертали втрачені вантажі й добували цінні місцеві реагенти. Завдяки угодам на рятування й повернення майна він — головна людина для мандрівників у цьому ворожому краї.",h="Крелдіґ Унґор — заповзятливий дворфійський агент Компанії «Відновлювачі», що перебуває високо серед скель...",kw={"крелдіґ унґор","компанія «відновлювачі»","мис ніджела","пустограй","карнітол","реагенти","рятування вантажу"},ang={["faction:Alliance"]="Крелдіґ, що перебуває на Мисі Ніджела, цілком покладається на мандрівників Альянсу, щоб його угоди на рятування майна не стояли на місці в цьому ворожому краї.",["race:Dwarf"]="Крелдіґ демонструє класичний дворфійський смак до суворих прикордонних мандрів і комерційних амбіцій: він відкрив справу далеко від гірських залів."},sec={{t="Польовий агент у пустках",b="Мис Ніджела — рідкісний прихисток Альянсу серед спотворених каньйонів Пустограю, тож це ідеальний плацдарм для таких комерційних шукачів нагоди, як Крелдіґ Унґор. Представляючи Компанію «Відновлювачі», Крелдіґ забрався далеко від безпечного Каз Модану — у пустельну глушину, за яку змагаються клани кентаврів, демони й Орда. Де інші бачать руїну й попіл, Крелдіґ бачить неторкані прибутки й утрачене майно, яке саме час повернути."},{t="Угода щодо Карнітола",b="Одна з головних справ, що привели Крелдіґа до Пустограю, — загублене судно Карнітола, що розбилося біля підступного західного узбережжя. У вантажі Карнітола були цінні товари, і Крелдіґ організовує пошуки уламків і розкиданого вантажу, перш ніж усе розтягнуть мародери чи прибережні морські велетні."},{t="Збір місцевих реагентів",b="Окрім рятування морських вантажів, Крелдіґ дбає, щоб Компанія «Відновлювачі» отримувала дивні біологічні й мінеральні скарби Пустограю. Суворе довкілля породжує незвичайних тварин і рослини, чиї частини високо цінують алхіміки й інженери у Східних Королівствах. Шукачі пригод, що не бояться хижаків пустки, мають у Крелдіґа сталий заробіток."}},faq={{q="Хто такий Крелдіґ Унґор?",a="Крелдіґ Унґор — дворф-агент Компанії «Відновлювачі», що працює із застави Альянсу на Мисі Ніджела в Пустограї. Він організовує пошук уламків і збір зразків по всьому краю.",al={"лор крелдіґа унґора","хто такий крелдіґ","крелдіґ унґор"}},{q="Що таке Компанія «Відновлювачі»?",a="Компанія «Відновлювачі» — підприємство, що заробляє на пошуках утраченого вантажу, підйомі уламків і збиранні рідкісних реагентів у небезпечних прикордонних краях.",al={"відновлювачі інкорпорейтед","хто такі відновлювачі","справи відновлювачів"}},{q="Де знайти Крелдіґа Унґора?",a="Він у поселенні Альянсу на Мисі Ніджела, що височіє серед скелястих гір на північному сході Пустограю.",al={"місце крелдіґа унґора","де крелдіґ","знайти крелдіґа унґора"}},{q="Що Крелдіґ хоче від корабельної аварії Карнітола?",a="Корабель із цінним вантажем, що належав Карнітолу, розбився біля узбережжя Пустограю. Крелдіґ наймає шукачів пригод, щоб знайти уламки й забрати втрачений вантаж, поки його не розтягли чи не знищили.",al={"аварія карнітола","крелдіґ карнітол","корабельна аварія пустограю"}},{q="Навіщо Крелдіґ збирає реагенти в Пустограї?",a="Суворий край Пустограю дає життя рідкісним істотам і незвичайним природним речовинам. Крелдіґ збирає ці зразки, щоб постачати їх алхімікам, майстрам-артефакторам і покупцям у великих містах Альянсу.",al={"реагенти для відновлювачів","реагенти пустограю","навіщо збирати реагенти"}},{q="Крелдіґ працює на Айронфордж чи на приватне підприємство?",a="Хоча він діє із застави Альянсу й наймає лише мандрівників Альянсу, Крелдіґ представляє Компанію «Відновлювачі» — комерційне підприємство, що займається пошуком уламків і торгівлею, а не виконує офіційних військових завдань корони.",al={"крелдіґ альянс чи приватник","відновлювачі айронфордж"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {n="Кролґ",s="Кролґ — незіпсований фурболг, що живе у відлюдній хатині на південь від Озера Містраль в Ашенвалі. Колись він належав до племені Гнилолісу, але відколовся від родичів, що впали в демонічне божевілля, і говорить лише з тими, хто постає перед ним у подобі фурболга.",h="Кролґ — незіпсований фурболг, що живе у відлюдній хатині на південь від Озера Містраль в Ашенвалі.",kw={"кролґ","фурболги","гнилоліс","жезл перетворення дартола","ран бладтус","озеро містраль"},ang={["class:Druid"]="Друїди, що прагнуть повернути рівновагу Ашенвалю, знаходять у Кролґові безцінний тверезий голос посеред краю, заполоненого зіпсованими звірами.",["faction:Alliance"]="Розвідники Альянсу, що допомагають Рейн Вульфраннер, покладаються на Кролґа, щоб знищити провід ворожих фурболгів Гнилолісу.",["race:NightElf"]="Для нічних ельфів Астранаару Кролґ — гірко-солодке нагадування про їхніх давніх союзників-фурболгів, якими ті були до того, як демонічна порча розбила племена."},sec={{t="Незламний розум",b="Більшість фурболгів Гнилолісу в Ашенвалі піддалися демонічній скверні, яку лишив по собі Палаючий Легіон, але Кролґ зберіг ясний розум, і божевілля його не торкнулося. Живучи у відлюдному притулку на південь від Озера Містраль, він обережно пильнує ліс. Бачивши, як його побратими трагічно скотилися до безглуздої жорстокості, він не довіряє чужинцям і розмовляє лише з тими, хто має вигляд родича."},{t="Спадщина Дартола",b="Завдяки чарам Жезла Перетворення Дартола мандрівники Альянсу можуть прибрати подобу фурболга. Побачивши, як йому здається, приязну рідну душу, Кролґ відкривається й ділиться важливими знаннями про те, як очистити землю. Він посилає героїв проти Рана Бладтуса та його охоронців, чия порча й ненависть загрожують лісові."}},faq={{q="Чому Кролґ не хоче зі мною говорити?",a="Кролґ глибоко не довіряє чужинцям і нажаханий шаленим хаосом, що поглинає ліс. Він цілковито ігноруватиме вас, якщо ви не прийняли подоби фурболга, яку дає Жезл Перетворення Дартола в ланцюжку завдань «Очищення Раене».",al={"кролґ не говоритиме","не можу говорити з кролґом","чому кролґ мовчить"}},{q="Де знайти Кролґа?",a="Він живе в невеликому притулку, відомому як Хижа Кролґа, трохи на південь від Озера Містраль у південно-центральному Ашенвалі.",al={"місце кролґа","де кролґ","хатина кролґа"}},{q="До якого племені належить Кролґ?",a="Колись Кролґ належав до племені Гнилого Гаю. На відміну від решти родичів, що піддалися скверні й демонічному шалу, він зберіг ясний розум і розірвав із ними зв'язки.",al={"плем'я кролґа","чи кролґ фаулвілд"}},{q="Чи ворожий Кролґ до гравців?",a="Кролґ нападає на чужинців, які наближаються до нього не в подобі фурболга. Шукачі пригод мають скористатися Жезлом Перетворення Дартола, перш ніж підходити до нього.",al={"чи кролґ нападає","чи кролґ ворог"}},{q="Чому Кролґ хоче смерті Рана Бладтуса?",a="Кролґ вважає Рана Бладтуса жадібним до влади й посиленим скверною. Хоча Кролґ звинувачує нічних ельфів у стражданнях своїх родичів, він не дозволить Ранові загрожувати їхнім дітям чи іншим створінням лісу.",al={"кролґ ран бладтус","чому вбивати рана бладтуса"}},{q="Хто такий Дартол, чий жезл дозволяє шукачам пригод говорити з Кролґом?",a="Дартол створив зачарований Жезл Перетворення, що дає своєму власникові подобу фурболга. Шукачі пригод користуються вже відновленим жезлом, щоб підійти до Кролґа під час «Очищення Раене».",al={"хто такий дартол","історія жезла дартола"}}},fp="5,261,15.439.0,15.374.1,27.256.0,25.113.0,32.173.0,28.158.0,40.214.1,60.177.0"}
P.entries["npc:krom-stoutarm"] = {n="Кром Стаутарм",s="Кром Стаутарм — дворфійський учений і чорнокнижник, якого можна знайти в глибині Бібліотеки Зали Дослідників в Айронфорджі. На відміну від більшості родичів, що занурюються лише в давній камінь і реліквії титанів, Кром вивчає темніші таємні тексти й демонічні обряди. Для чорнокнижників Альянсу, що шукають езотеричних знань у Калімдорі та Східних Королівствах, він — незамінний порадник.",h="Кром Стаутарм — дворфійський учений і чорнокнижник, якого можна знайти в глибині Бібліотеки Зали Дослідників...",kw={"кром стаутарм","чорнокнижник","зала дослідників","бібліотека","фоліант кабали","мисливець Скверни","айронфордж"},ang={["class:Warlock"]="Чорнокнижники Альянсу мусять радитися з Кромом, шукаючи темних обрядів підкорення, — зокрема коли беруться за небезпечну справу: зібрати докупи Фоліант Кабали.",["faction:Alliance"]="Кром дає таємним практикам Альянсу безпечний інтелектуальний прихисток у могутніх гірських твердинях Айронфорджа.",["race:Dwarf"]="Дворфи зазвичай зрікаються демонічних мистецтв, тож місце Крома серед шанованих полиць Зали Дослідників — цікава рідкість."},sec={{t="Темніший куток Зали",b="Зала Дослідників зазвичай славиться дворфійськими археологами, одержимими кайлами, лопатами й артефактами титанів. Кром Стаутарм серед них — постать незвичайна. Причаївшись у Бібліотеці серед величезних фоліантів, він вивчає окультні знання й обряди підкорення, якими користуються заклиначі демонів. Його присутність в Айронфорджі показує: хоч мистецтву чорнокнижників і не довіряють, учені, що досліджують заборонені знання, досі працюють у залах гірського міста."},{t="Фоліант Кабали",b="Коли чорнокнижники Альянсу прагнуть підкорити могутніх демонічних слуг на кшталт мисливця Скверни, їхній шлях неминуче перетинається з Кромовим. Знаючи про розпорошені окультні томи, він посилає молодих заклиначів далеко за моря — зокрема в небезпечні вилазки на ворожі землі, як-от Пустки, — щоб повернути вирвані сторінки й уривки сумнозвісного Фоліанта Кабали."}},faq={{q="Де знайти Крома Стаутарма?",a="Кром Стаутарм — у Бібліотеці, крилі Зали Дослідників у дворфійській столиці Айронфордж.",al={"місце крома стаутарма","де кром стаутарм","кром стаутарм айронфордж"}},{q="Яку роль Кром Стаутарм відіграє для гравців?",a="Кром — важлива постать у завданнях для чорнокнижників Альянсу, що проходять головні для свого класу демонічні ритуали: зокрема, він веде їх через пошуки Фоліанту Кабали.",al={"що робить кром","мета крома стаутарма","завдання крома стаутарма"}},{q="Чи Кром Стаутарм родич інших Стаутармів?",a="Прізвище Стаутарм носять кілька дворфів, але родинний зв'язок між Кромом та іншими не підтверджено.",al={"родичі крома","стен стаутарм родич"}},{q="Чому чорнокнижникові дозволено бути в Залі Дослідників?",a="Кром — і наставник чорнокнижників, і вчений, що працює в Залі Дослідників. На яких умовах йому дозволено цю роботу, джерело не пояснює.",al={"чому кром у залі дослідників","чорнокнижник в айронфорджі"}},{q="Що пов'язує Крома з Пустками?",a="Досліджуючи темні рукописи, Кром посилає чорнокнижників шукати втрачені частини Фоліанту Кабали, і одна з таких важливих частин захована в скрині глибоко в землях Пусток, де кишать шипогриви.",al={"кром стаутарм пустки","чому завдання пусток кром"}},{q="Чи навчає Кром Стаутарм заклинань?",a="Кром — учений, що дає завдання, а не звичайний наставник класу. Він веде чорнокнижників особливими обрядами посвяти, а не вчить буденних заклять із гримуарів.",al={"чи кром навчає","кром тренер чорнокнижників"}}},fp="13,374,27.471.0,21.373.0,31.110.0,46.181.0,44.113.0,56.145.0,37.214.0,32.162.0"}
P.entries["npc:krusk"] = {n="Краск",s="Краск — орк-розвідник, що служить у Таррен Міллі в Передгір'ї Гілсбреда. Відряджений безпосередньо за наказом Вождя Тралла розвідати Синдикат і повернути реліквії з руїн Твердині Дурнгольд, він тепер керує розвідкою й рятувальними діями після того, як його перша вилазка потрапила в засідку.",h="Краск — орк-розвідник, що служить у Таррен Міллі в Передгір'ї Гілсбреда.",kw={"краск","твердиня дурнгольд","синдикат","тралл","ґол'дір","таррен мілл","розвідники"},ang={["faction:Horde"]="Краск представляє безпосередні інтереси Вождя Тралла в Лордероні: він прагне вберегти історію Дурнгольда й не лишити жодного полоненого орка в руках Синдикату.",["race:Orc"]="Допомога Краскові в порятунку побратимів-розвідників торкається честі й болісної історії орочих таборів інтернування — і саме тієї фортеці, де Тралл розбив кайдани свого народу."},sec={{t="Невдала вилазка",b="Коли Вождь Тралл знову звернув погляд на руїни Твердині Дурнгольд, він відрядив Краска з невеликим ударним загоном розвідати діяльність Синдикату й повернути реліквії, пов'язані з похмурим минулим фортеці. Проте людські розбійники виявилися краще закріпленими й організованими, ніж очікували. У засідці серед напівзруйнованих мурів Дурнгольда загін орків-розвідників зазнав поразки. Краскові вдалося пробитися назовні, але трьох його товаришів — Ґол'діра, Друлла й Тоґ'тара — схопили й замкнули глибоко в руїнах. Перегрупувавшись у Таррен Міллі, Краск тепер посилає шукачів пригод з Орди прорватися до Дурнгольда, повернути втрачені речі й визволити його полонених побратимів."},{t="Око на Синдикат",b="Окрім порятунку своїх розвідників, Краск зосереджений на тому, щоб зламати владу Синдикату над Гілсбредом. Занепала знать Альтераку — непередбачувана загроза: вона діє з Твердині Дурнгольд і плете змови і проти застав Орди, і проти своїх колишніх побратимів з Альянсу. Працюючи з Таррен Мілла, Краск стежить за пересуваннями ватажків Синдикату, як-от Лорда Алідена Перенольда, сподіваючись обезголовити їхню верхівку, перш ніж вони загрожуватимуть хиткому плацдарму Орди в Лордероні."}},faq={{q="Хто такий Краск?",a="Краск — орк-розвідник, якого Вождь Тралл послав до Таррен Мілла. Йому доручили розвідати, що замишляє Синдикат довкола руїн Твердині Дурнгольд, і повернути історичні реліквії.",al={"краск","хто такий краск","краск таррен мілл"}},{q="Що сталося із загоном Краска?",a="Синдикат влаштував Краскові та його загонові засідку у Твердині Дурнгольд. Краск утік, а його товаришів — Ґол'діра, Друлла й Тоґ'тара — схопили й ув'язнили в зруйнованій фортеці.",al={"загін краска","що сталося з краском","засідка в дурнголді"}},{q="Чому Орду цікавить Твердиня Дурнгольд?",a="Дурнгольд має глибоке особисте й історичне значення для Вождя Тралла: там Еделас Блекмур виховував його як полоненого гладіатора, аж поки Тралл не очолив повстання орків, що зрівняло твердиню із землею.",al={"чому дурнголд","тралл дурнголд","реліквії дурнголда"}},{q="Де знайти Краска?",a="Краск стоїть надворі в поселенні Орди Таррен Мілл, на півночі Передгір'я Гілсбреда.",al={"місце краска","де краск"}}},fp="5,305,20.659.0,21.475.0,13.182.0,31.194.0,46.200.0,23.99.0"}
P.entries["npc:kuray-bin"] = {n="Курай'бін",s="Курай'бін — розвідник із тролів Темного Спису, що стоїть на сторожовому посту біля Застави Розщепленого Дерева в Ашенвалі. Він стежить за лісовими стежками, щоб не проґавити розвідників нічних ельфів, які підкрадаються до табору Орди.",h="Курай'бін — розвідник із тролів Темного Спису, що стоїть на сторожовому посту біля Застави Розщепленого...",kw={"курай'бін","тролі","застава розщепленого дерева","вартові срібнокрилих","розвідка","ашенваль"},ang={["faction:Horde"]="Курай'бін уособлює пильність передової, без якої Заставу Розщепленого Дерева швидко оточили б і захопили партизани нічних ельфів.",["race:Troll"]="Як і багато розвідників Темного Спису на службі Орди, Курай'бін покладається на чуття слідопита з джунглів і помічає лазутчиків нічних ельфів там, де інші бачать самі лише дерева."},sec={{t="Очі на узліссі",b="Курай'бін, що стоїть одразу за Заставою Розщепленого Дерева, пильнує, щоб Альянс не просочився в глибокі ліси Ашенвалю. Вартові Срібнокрилих безупинно патрулюють довколишні хащі й посилають через кордон спритних розвідниць, щоб вивідати все про лісозаготівлі й оборону Орди. Знаючи, що розвідники, за якими ніхто не стежить, швидко стають засідками, Курай'бін посилає вправних бійців Орди вполювати розвідниць, перш ніж ті доповідять у Притулок Срібнокрилих."}},faq={{q="Хто такий Курай'бін?",a="Курай'бін — троль-вартовий Темного Спису, що стоїть біля Застави Розщепленого Дерева в Ашенвалі. Він доручає шукачам пригод Орди винищувати ворожих розвідників нічних ельфів, що чатують у довколишньому лісі.",al={"курай'бін","хто такий курай'бін","тролячий розвідник сплінтертрі"}},{q="Де знайти Курай'біна?",a="Він просто за брамою частоколу Застави Розщепленого Дерева, стереже підступи до дороги в центрально-східному Ашенвалі.",al={"місце курай'біна","де курай'бін"}},{q="Чому Курай'бін хоче смерті Скороходів Срібнокрилих?",a="Скороходи — Вартові Срібнокрилих, що прокрадаються до самої Застави Розщепленого Дерева. Курай'бін хоче знищити їх, перш ніж вони зберуть відомості про позиції Орди чи влаштують раптові напади.",al={"чому вбивати скороходів","лор завдання скороходів ясенлісся"}},{q="Чи дає Курай'бін інші завдання?",a="Ні. Його єдиний обов'язок на околиці застави — боротьба з невловними розвідниками-скороходами нічних ельфів.",al={"завдання курай'біна","завдання курай бін"}}},fp="9,211,23.484.0,17.191.0,27.126.0,55.211.0,37.117.0"}
P.entries["npc:kzan-thornslash"] = {n="Кзан Торнслеш",s="Кзан Торнслеш — орк-торговець зброєю в Долині Випробувань у Дуроторі. Він постачає найнеобхіднішу початкову зброю та припаси новобранцям, що починають вишкіл в Орді.",h="Кзан Торнслеш — орк-торговець зброєю в Долині Випробувань у Дуроторі.",kw={"кзан торнслеш","зброя","торговець","долина випробувань","новобранці","дуротар"},ang={["class:Warrior"]="Для молодих воїнів, що починають зі щербатих клинків, Кзан пропонує добірку дробильної та клинкової зброї під різні бойові стилі.",["faction:Horde"]="Постачання молодих армій Тралла починається з самих низів, де торговці на кшталт Кзана дбають, щоб кожна здатна рука мала сталь для Орди."},sec={{t="Бронник для новобранців",b="Розташований у запорошеному червоному каньйоні Долини Випробувань, Кзан Торнслеш — головний продавець зброї для молодих орків і тролів Темного Списа, що роблять перші кроки як воїни Орди. Пропонуючи добірку простого озброєння — від грубих ручних сокир і коротких мечів до кийків і метальних ножів, — Кзан дбає, щоб новопробуджені кандидати були достатньо озброєні проти тутешньої звірини й місцевих небезпек."}},faq={{q="Хто такий Кзан Торнслеш?",a="Кзан Торнслеш — орк-торговець у Долині Випробувань. Він забезпечує новобранців Орди звичайною зброєю, придатною для перших бойових випробувань.",al={"кзан торнслеш","хто такий кзан","торговець зброєю долини випробувань"}},{q="Де знайти Кзана Торнслеша?",a="Він стоїть на відкритому тренувальному майданчику Долини Випробувань на південному заході Дуротару, серед шукачів пригод-новачків і наставників.",al={"місце кзана","де кзан торнслеш","карта кзана торнслеша"}},{q="Яке спорядження продає Кзан?",a="Кзан продає просту зброю для початківців — сокири, мечі, кинджали, палиці, кийки й метальну зброю — для новобранців, яким потрібне надійне залізо, доки вони не здобудуть кованого чи знайденого спорядження.",al={"що продає кзан","товари кзана","зброя кзана"}}},fp="15,199,23.433.0,23.172.0,33.161.0,38.192.0"}
P.entries["npc:lady-anacondra"] = {n="Леді Анакондра",s="Леді Анакондра — одна з Володарів іклів, що очолюють Друїдів Ікла в Печерах Стогонів. Колись вона була послушницею з нічних ельфів на ім'я Скарлетліф і першою зголосилася допомогти Наралексові в його сміливому задумі зцілити Пустки. Коли єднання її наставника зі Смарагдовим Сном обернулося жахіттям, її розум зламався, а відданість переродилася в отруйне прагнення побачити Калімдор, заполонений зміями.",h="Леді Анакондра — одна з Володарів іклів, що очолюють Друїдів Ікла в Печерах Стогонів.",kw={"леді анакондра","друїди ікла","печери стогонів","наралекс","жахіття","смарагдовий сон"},ang={["class:Druid"]="Анакондра — застережлива трагедія для друїдів Кола Кенарія: щира послушниця, чиє палке бажання зцілити землю зробило її беззахисною перед жахіттям, яке обернуло її єднання на божевілля.",["faction:Horde"]="Орда не може дозволити Анакондрі та Володарям іклів загрожувати тендітним джерелам життя Пусток, тож позбутися її вкрай необхідно, щоб уберегти Перехрестя й довколишні оази.",["race:NightElf"]="Бачити, як сестра калдорейського роду відкидає свою спадщину й подобу заради спотвореної зміїної мрії, — тверезе нагадування про небезпеки, що чатують у Смарагдовому Сні."},sec={{t="Від Скарлетліф до змії",b="Ще до того як узяти собі зміїне ім'я, Леді Анакондра звалася Скарлетліф. Коли старший друїд Наралекс задумав через Смарагдовий Сон дістатися підземних джерел Пусток, вона першою зголосилася йому допомагати. Та палка відданість її й згубила. Коли розумом Наралекса заволоділи темні видіння, жахіття просочилося зі світу снів і заразило його учнів: Скарлетліф утратила розум, а її мрійливе захоплення обернулося холодною, плазуючою одержимістю."},{t="Володарка іклів у глибинах",b="Тепер, звучи себе Леді Анакондрою, вона стоїть на варті в перших підземних залах Печер Стогонів. Як і решта Володарів іклів, вона відкинула споконвічні засади Кола Кенарія заради лютої вдачі гадюки. Скликаючи блискавки, магію природи й присипляючи ворогів, вона оберігає спотворений сон Наралекса й силкується поширити порчу жахіття на посушливу землю нагорі."}},faq={{q="Ким спершу була Леді Анакондра?",a="Спершу вона була молодою нічною ельфійкою-послушницею на ім'я Скарлетліф. Вона першою з учнів зголосилася супроводжувати друїда Наралекса в його місії до Пусток.",al={"справжнє ім'я анакондри","хто такий скарлетліф","минуле скарлетліф"}},{q="Чому вона обернулася проти Кола Кенарія?",a="Коли Наралекс спробував поєднатися зі Смарагдовим Сном під Пустками, його думки поглинув кошмар. Той самий кошмар уразив і розум його послушників: він зіпсував Скарлетліф, і вона відкинула колишнє життя, щоб служити спотвореному сну.",al={"чому анакондра зла","як вона стала друїдом ікла","чому скарлетліф впала"}},{q="Яка її роль у Печерах Стогонів?",a="Вона одна з чотирьох Повелителів Ікла, що очолюють Друїдів Ікла. Вона стереже верхні частини печер і стежить, щоб Наралекс лишався в полоні свого зіпсованого сну, де йому сниться світ, яким правлять рептилії.",al={"що робить анакондра","мета анакондри","чому вбивати анакондру"}},{q="Де її знайти в печерах?",a="Леді Анакондра блукає першою великою мережею печер біля входу до Печер Стогонів. Вона ходить серед печерних ящерів і змій, часто переходячи з одного місця відпочинку на інше.",al={"місце анакондри","де леді анакондра","поява анакондри"}},{q="Який предмет забирають у неї для Кола Кенарія?",a="При ній Самоцвіт Анакондри. Друїдка Нара Вайлдмейн із Тандер Блафа просить убити її й забрати самоцвіт, щоб зламати владу Повелителів Ікла над Пустками.",al={"самоцвіт анакондри","лідери ікла анакондра","предмет завдання анакондри"}},{q="Якою силою вона володіє в бою?",a="Вона черпає магію природи: здалеку разить ворогів пекучими блискавками й наводить чарівний сон, щоб знешкодити загарбників, поки на них нападають її союзники-рептилії.",al={"здібності анакондри","закляття анакондри","атаки анакондри"}}},fp="14,388,27.516.0,22.419.0,34.172.0,45.267.0,40.229.0,42.196.0,52.169.0,37.176.0"}
P.entries["npc:lady-sarevess"] = {n="Леді Саревесс",s="Леді Саревесс — спотворена нага-чаклунка, що живе в затоплених руїнах Чорноглибинних Печер і віддається темному чаклунству.",h="Леді Саревесс — спотворена нага-чаклунка, що живе в затоплених руїнах Чорноглибинних Печер і віддається...",kw={"леді саревесс","наги","чаклунка","ставок аск'ар","чорноглибинні печери"},ang={["class:Mage"]="Саревесс показує, як магічні практики Високородних за століття океанської скверни виродилися в сирі, хаотичні блискавки й чаклунство припливів.",["race:NightElf"]="Руїни, де живе леді Саревесс, колись були священним храмом Елуни. Бачити, як її спотворені родичі-наги оскверняють води Аск'ару, — гірке нагадування про Розкол."},sec={{t="Грот у глибинах",b="У Ставку Аск'ар леді Саревесс проводить свої ритуали в затопленому гроті зруйнованого храму. Украй спотворена чарівниця, вона віддається темній магії, тоді як культисти Молота Присмерку, що теж нишпорять затонулим храмом, правлять свої служби глибше в печері."},{t="Чаклунство припливів",b="Наче морська відьма глибоких океанів, Саревесс повеліває стихійними течіями й тріскучими дугами блискавок. Оточена вірними вартовими-нагами й викликаними водяними елементалями, вона люто боронить своє святилище від кожного, хто загрожує її темній справі."}},faq={{q="Хто така Леді Саревесс?",a="Леді Саревесс — нага-заклиначка, що оселилася в підземному Озері Аск'ар у Чорноглибинних Печерах. Це вкрай зіпсована заклиначка, що вдається до темної магії.",al={"хто така саревесс","лор саревесс","минуле леді саревесс"}},{q="Де знайти Леді Саревесс?",a="Її лігво — в Озері Аск'ар, затопленій залі на початку храмового комплексу Чорноглибинних Печер на узбережжі Ашенвалю.",al={"місце саревесс","де леді саревесс","ставок аск'ар"}},{q="Якими силами володіє Леді Саревесс?",a="Спираючись на традиції морських відьом наг, Саревесс володіє могутньою магією води й стихій, особливо лютими розгалуженими блискавками, якими разить кожного, хто ввійде до її затоки.",al={"магія саревесс","здібності саревесс"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="Лейрд",s="Лейрд — нічний ельф, торговець рибою в приморському заїзді Обердайна. Працюючи на оповитих імлою берегах Темного Узбережжя, він постачає товари й кулінарні рецепти мандрівникам і рибалкам, що не бояться скелястих берегів.",h="Лейрд — нічний ельф, торговець рибою в приморському заїзді Обердайна.",kw={"лейрд","обердайн","рибальство","несса шедовсонг","тельдрассил","кулінарія"},ang={["profession:Cooking"]="Кухарі-мандрівники на Темному Узбережжі часто шукають Лейрда заради його рецепта, як правильно філетувати й готувати лютих риб-шаленців із вод Калімдору.",["race:NightElf"]="Лейрд — звичайний ремісник із нічних ельфів, що влаштувався на материкових берегах, щоб підтримати дедалі ширшу прибережну мережу Калімдору."},sec={{t="Портовий торговець",b="Лейрд, що працює в гамірному заїзді Обердайна, продає свіжу рибу й припаси морякам, місцевим і мандрівним шукачам пригод. Води Темного Узбережжя славляться бурхливістю й небезпеками, не те що захищені береги Тельдрассилу, але Лейрд добре знає: ризик приносить винагороду. Сміливим рибалкам, що закидають вудки з імлистих пляжів, місцевий улов дає чималий зиск."},{t="Зв'язки через воду",b="Лейрд тісно пов'язаний із рибальством по той бік протоки, на Тельдрассилі. Він — важливий посередник для кур'єрських перевезень між острівним гіллям Селища Рут'теран і материковим портом: отримує вантажі від колеги-рибалки Несси Шедовсонг і стежить, щоб прибережна торгівля не спинялася."}},faq={{q="Де знайти Лейрда?",a="Лейрд — на першому поверсі корчми в Обердайні, головному поселенні Альянсу на узбережжі Темного Узбережжя.",al={"місце лейрда","де лейрд","лейрд оберін"}},{q="Що продає Лейрд?",a="Він продає різну рибу й кулінарні складники, а також рецепт Філе Шаленства.",al={"торговець лейрд","що продає лейрд","товари лейрда"}},{q="Які завдання пов'язані з Лейрдом?",a="Лейрд приймає посилку від Несси Шедовсонг із Селища Рут'теран у завданні «Політ до Обердайна», а потім просить шукачів пригод передати відповідь за море.",al={"завдання лейрда","завдання з рибою оберіна"}},{q="Чому Лейрд вважає, що рибалити біля Темного Узбережжя варто, попри небезпеку?",a="Лейрд зауважує, що оповите туманом узбережжя Темного Узбережжя приховує куди більше небезпек, ніж тихі води Тельдрассила, але завдяки рясному й незвичайному морському життю рибальство тут куди вигідніше для заповзятливих рибалок.",al={"плітки лейрда","чи варто рибалити на темному узбережжі"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="Лакота Віндсонг",s="Лакота Віндсонг — юна тауренка, яку тримають у полоні на кручах Шпиля Темної Хмари в Тисячі Голок. Коли вона відкинула небажане залицяння Арнака Ґрімтотема, її силоміць викрали, і тепер вона чекає, хто визволить її з лап племені Ґрімтотем.",h="Лакота Віндсонг — юна тауренка, яку тримають у полоні на кручах Шпиля Темної Хмари в Тисячі Голок.",kw={"лакота віндсонг","арнак ґрімтотем","шпиль темної хмари","застава вільного вітру","талія амбергайд","порятунок"},ang={["faction:Horde"]="Порятунок Лакоти — удар по пануванню Ґрімтотемів у Тисячі Голок, що робить безпечним шлях для мандрівників, які відпочивають на Заставі Вільного Вітру.",["race:Tauren"]="Випробування Лакоти — суворе нагадування про підступність, що гноїться серед Ґрімтотемів, чий непослух проводові Кайрна Бладгуфа раз у раз обертається насильством."},sec={{t="Смертельне залицяння",b="Невдовзі після Третьої війни до Лакоти Віндсонг почав залицятися Арнак Ґрімтотем. Не бажаючи ні пристати до його клану, ні приймати його залицяння, вона відмовила йому. Та Арнак не збирався чути «ні»: він повернувся під покровом ночі, вбив Лакотиного брата, коли той спробував заступитися, і забрав її в зубчасті висоти Тисячі Голок. Ув'язнена високо над дном каньйону на Шпилі Темної Хмари, вона й досі сидить під пильною охороною, а Арнак усе наполягає, що зробить її своєю нареченою."},{t="Спуск до безпеки",b="Оточена підступними розбійниками-Ґрімтотемами, Лакота не зможе сама пробитися вниз кручами. Лише відважний супровід проведе її підвісними мостами й звивистими стежками до дна каньйону. Вирвавшись зі Шпиля Темної Хмари, Лакота тікає до безпечної Застави Вільного Вітру й несе звістку про свій порятунок Талії Амбергайд і захисникам, що там стоять."}},faq={{q="Чому Лакоту Віндсонг тримають на Шпилі Темної Хмари?",a="Вона відмовилася вийти заміж за Арнака Ґрімтотема. Не змирившись із відмовою, Арнак убив її брата, викрав Лакоту й приволік до твердині Ґрімтотемів на Шпилі Темної Хмари, сподіваючись змусити її погодитися.",al={"чому лакоту схопили","хто викрав лакоту","чому лакота на шпилі темної хмари"}},{q="Куди йде Лакота, коли її врятовано?",a="Безпечно спустившись до підніжжя Шпиля Темної Хмари, Лакота вирушає на Заставу Вільного Вітру, де знаходить прихисток серед захисників Орди й розповідає про своє лихо Талії Амбергайд.",al={"куди тікає лакота","куди вона йде після супроводу","кінцева точка лакоти"}},{q="Хто такий Арнак Ґрімтотем?",a="Арнак — жорстокий воїн підступного клану Ґрімтотем, що вбив Лакотиного брата й викрав її, коли вона відмовилася стати його дружиною.",al={"хто такий арнак","хто її викрав","лор арнака"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="Ланка Фаршот",s="Ланка Фаршот — наставник мисливців із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари. Він веде мисливців-новачків із тауренів, коли ті роблять перші кроки у слідопитстві, влучній стрільбі й виживанні на рівнинах Малгору.",h="Ланка Фаршот — наставник мисливців із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"ланка фаршот","мисливець","наставник","табір нарачі","плато червоної хмари","малгор"},ang={["class:Hunter"]="Для мисливців-тауренів, що починають навчання в Малгорі, Ланка Фаршот — найперший наставник, який навчає основ влучної стрільби й виживання в дикій природі.",["race:Tauren"]="Ланка уособлює традиційну мисливську філософію тауренів, у якій влучність і слідопитство — життєво важливі обов'язки для захисту племені й життя в рівновазі з рівнинами."},sec={{t="Наставник Плато Червоної Хмари",b="Табір Нарачі — місце, де чатує Ланка Фаршот і вітає нових тауренів, покликаних на шлях мисливця. Свіжі новобранці приходять із гравірованою запискою, що велить їм шукати його поради. Під його твердим оком підмайстри вивчають основи далекого бою, вистежування здобичі й шани до диких звірів, що блукають трав'янистими рівнинами Малгору. Його наука дбає, щоб кожен молодий мисливець став умілим розвідником і годувальником племені."}},faq={{q="Хто такий Ланка Фаршот?",a="Ланка Фаршот — таурен, наставник мисливців у Таборі Нарачі на Плато Червоної Хмари в Малгорі. Він дає перші уроки й поради молодим мисливцям, які тільки починають свій шлях.",al={"хто такий ланка","ланка фаршот нпс","мисливець табору нараче"}},{q="Які завдання дає Ланка Фаршот?",a="Ланка приймає молодих тауренів-мисливців, яких посилають до нього з гравірованою запискою, коли вони прибувають до Табору Нарачі, і веде їх шляхом мисливця, поки вони опановують основи ремесла.",al={"завдання ланки фаршота","завдання мисливця табір нараче"}},{q="Чи Ланка Фаршот родич Міксі Фаршот?",a="Попри однакове прізвище, немає жодних свідчень, що Ланка Фаршот родич гоблінки Міксі Фаршот.",al={"чи ланка родич міксі","міксі фаршот родичка"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Лар Праултаск",s="Лар Праултаск — троль-вартовий Темного Списа на посту на південний захід від Села Сен'джин у Дуроторі. Зі свого прикордонного посту він пильнує загрози, що насуваються на молоде троляче поселення, і спрямовує шукачів пригод стримувати наступ ворогів поблизу.",h="Лар Праултаск — троль-вартовий Темного Списа на посту на південний захід від Села Сен'джин у Дуроторі.",kw={"лар праултаск","вартовий","сен'джин","кентаври","колкар","дуротар","темний спис"},ang={["faction:Horde"]="Лар Праултаск утілює боротьбу Орди за кордони Дуротару проти зовнішніх загроз просто на задвірках її молодої столиці.",["race:Troll"]="Для Темного Списа розвідники на кшталт Лара Праултаска життєво важливі, щоб уберегти крихкий новий дім племені в Дуроторі від агресивних кланів кентаврів і людських військ, що насуваються."},sec={{t="Вартовий на узбережжі",b="Лар Праултаск, що стоїть на південний захід від Села Сен'джин на суворому узбережжі Дуротару, — один із передових вартових племені Темного Списа. Поки тролі ще намагаються облаштувати постійний дім після втечі зі своїх затонулих островів, Село Сен'джин потерпає від постійних наскоків ворожих сусідів. Лар координує розвідників і воїнів, щоб стежити за рухом на узбережжі й стримувати агресію ворожих сил — надто кентаврів Колкар, — аби крихке поселення мало змогу перевести подих."}},faq={{q="Хто такий Лар Праултаск?",a="Лар Праултаск — троль Темного Спису, що дає завдання трохи на південний захід від Села Сен'джин у Дуротарі. Він допомагає стерегти околиці поселення, залучаючи вправних мандрівників Орди бити загрози в краї, перш ніж ті дістануться самого села.",al={"лар праултаск","хто такий лар праултаск","лар праултаск дуротар"}},{q="На яких загрозах зосереджується Лар Праултаск?",a="Лар зосереджується на прикордонних небезпеках, що загрожують південному Дуротару, насамперед на зграях кентаврів Колкар, які вдираються на тролячі землі.",al={"завдання лара праултаска","чого хоче лар праултаск"}},{q="Де знайти Лара Праултаска?",a="Він на півдні Дуротару, пильнує стежки на південний захід від Села Сен'джин.",al={"місце лара праултаска","де лар праултаск"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {n="Ларіс Ґірдавдл",s="Ларіс Ґірдавдл — дивакуватий гном-дослідник із Бібліотеки Зали Дослідників в Айронфорджі. Він присвятив своє наукове життя вивченню химерної природи й походження слизунів Азероту. Шукачі пригод, готові збирати смердючі зразки слизу, знаходять у ньому завзятого, хоч і трохи схибленого, покровителя.",h="Ларіс Ґірдавдл — дивакуватий гном-дослідник із Бібліотеки Зали Дослідників в Айронфорджі.",kw={"ларіс ґірдавдл","слиз","слизуни","зала дослідників","бібліотека","айронфордж","гном"},ang={["faction:Alliance"]="Працюючи в Залі Дослідників, Ларіс діє під широким крилом науки, яку підтримує Альянс, і доповнює історичні розкопки Ліги дивакуватим природознавством.",["race:Gnome"]="Ларіс — утілення суто гномського прагнення шукати знання там, куди ніхто інший не зазирає, навіть якщо для цього треба занурити руки в смердючий болотяний мул."},sec={{t="Знавець слизу",b="Захований серед високих книжкових полиць і давніх реліквій Зали Дослідників, Ларіс Ґірдавдл займається доволі непоказною галуззю натурфілософії — походженням слизунів. Поки його колеги-дворфи схиляються над табличками Титанів і давньою різьбою по каменю, Ларіс переконаний, що мерзенні драглисті страхіття Азероту приховують захопливі алхімічні й біологічні таємниці. Він доручає мандрівним дослідникам збирати їдкі зразки в далеких куточках світу, щоб перевірити свої дивні гіпотези про те, як ці безмозкі калюжі злоби оживають."}},faq={{q="Хто такий Ларіс Ґірдавдл?",a="Ларіс Ґірдавдл — гном-дослідник, що працює в Бібліотеці Зали Дослідників в Айронфорджі. Його незвичайні дослідження присвячено слизнякам, слизу й дивним законам їхнього самозародження.",al={"ларіс","ґірдавдл","хто такий ларіс"}},{q="Де знайти Ларіса Ґірдавдла?",a="Він у північному крилі Айронфорджа, у Залі Дослідників, а точніше — у тихих закутках Бібліотеки.",al={"місце ларіса","де ларіс","знайти ларіса ґірдавдла"}},{q="Чому він вивчає слизняків?",a="Ларіс має гострий, ексцентричний науковий розум і виробив власні теорії про природу й походження живого слизу. Він переконаний, що аналіз їдких решток різних слизняків допоможе глибше зрозуміти, як ці дивні організми з'являються й розмножуються.",al={"чому слизняки","дослідження слизу ларіса","вивчення слизняків"}},{q="Які завдання він дає шукачам пригод?",a="Ларіс наймає сміливих мандрівників вирушати в небезпечні краї по чисті зразки слизу. У завданні «Трохи слизу — і далеко зайдеш» він дає порожні банки й просить шукачів пригод набрати в живих слизняків густих решток.",al={"завдання ларіса","трохи слизу дуже допомагає"}}},fp="16,316,16.558.0,24.220.0,34.139.0,25.279.0,37.260.0"}
P.entries["npc:lars"] = {n="Ларс",s="Ларс — знесилений чоловік, що вцілів і тепер таборує в глушині Сутінколісся. Разом зі своїм товаришем Свеном Йорґеном він намагається втримати позиції на північному краю Притихлого Берега проти жахіть, що нишпорять лісом.",h="Ларс — знесилений чоловік, що вцілів і тепер таборує в глушині Сутінколісся.",kw={"ларс","свен йорґен","притихлий берег","вовки","табір","сутінколісся"},ang={["faction:Alliance"]="Ларс — знесилений мирний житель, що виживає поза досяжністю міської варти, і він радий захисникам Альянсу, готовим порубати вовків, що кружляють довкола його табору."},sec={{t="Хиткий прихисток",b="Ларс тримається в скромному таборі на північному краю Притихлого Берега, ледве виживаючи далеко від сумнівної безпеки Даркшира. Сутінколісся підступне й у найкращі часи, а тепер довколишні ліси кишать лютими звірами, невпинною нежиттю й воргенами, що скрадаються в тіні. Ларс тримається поряд зі Свеном Йорґеном і просто намагається вижити в дедалі ворожішій глушині."},{t="Загроза з глушини",b="Щоб вижити в таборі, треба постійно стерегтися місцевих хижаків. Ларсові дуже дошкуляють невгамовні зграї голодних лютих вовків, що чатують у темряві довкола їхнього вогнища. Не маючи змоги ні послабити пильність, ні відігнати їх самотужки, він покладається на вправних мандрівників, які проріджують голодних хижаків, доки ті не захопили його маленький табір."}},faq={{q="Хто такий Ларс?",a="Ларс — чоловік, що вцілів і тепер таборує в диких нетрях Сутінколісся. Він живе разом зі своїм другом і товаришем Свеном Йорґеном на північній межі Тихого Берега й робить усе, щоб пережити жахіття лісу.",al={"ларс сутінколісся","хто такий ларс","ларс нпс"}},{q="Де знайти Ларса?",a="Ларс — у невеликому таборі в нетрях на північному краю Тихого Берега, на заході Сутінколісся.",al={"де ларс","місце ларса","табір ларса"}},{q="З якою бідою стикається Ларс?",a="Ларсові й Свенові не дають спокою ненажерливі вовки й хижаки, що чатують у лісі поблизу. У завданні «Вовки на п'ятах» Ларс просить мандрівних шукачів пригод винищити хижаків, поки ті не рознесли його табір.",al={"завдання ларса","завдання вовки на п'ятах","чому ларсу потрібна допомога"}},{q="Що пов'язує Ларса зі Свеном Йорґеном?",a="Ларс і Свен Йорґен — товариші, що разом виживають у нетрях. Свен має власне темне минуле й рахунки в цьому краї, а Ларс допомагає підтримувати їхній убогий відлюдний табір.",al={"ларс і свен","хто свен ларсові"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="Лаурна Морнінґлайт",s="Лаурна Морнінґлайт — наставниця жерців нічних ельфів, що мешкає в тихому поселенні Доланаар на Тельдрассилі. Віддана Сестринству Елуни, вона веде послушників-початківців, що приходять із Тінедолу, через духовні обряди й цілющі дари Богині Місяця. Її наука готує молодих жерців нічних ельфів до загроз, що насуваються на гілля Світового Дерева.",h="Лаурна Морнінґлайт — наставниця жерців нічних ельфів, що мешкає в тихому поселенні Доланаар на Тельдрассилі.",kw={"лаурна морнінґлайт","жриця","наставниця","елуна","доланаар","тельдрассил","богиня місяця"},ang={["class:Priest"]="Для жерців нічних ельфів, що прибувають із Тінедолу, Лаурна Морнінґлайт — ваша перша велика наставниця за межами стартової долини: вона навчає основних заклять і скеровує вашу ранню відданість Елуні.",["race:NightElf"]="Лаурна втілює традиційну відданість калдореїв Богині Місяця й нагадує шукачам пригод, що жрецтво на Тельдрассилі черпає силу від Елуни, а не від Святого Світла."},sec={{t="Провідниця в Доланаарі",b="Серед гілля Доланаара Лаурна Морнінґлайт — одна з головних наставниць молодих жерців, що пройшли перші обряди в Тінедолі. Коли нові посвячені виходять у ширші простори Тельдрассила, вона вчить їх поглиблювати єднання з Елуною, урівноважуючи світло зцілення з оборонними обрядами, без яких не вижити в дедалі ворожіших хащах."},{t="Відданість Богині Місяця",b="Жрецтво калдореїв глибоко переплетене з поклонінням Елуні, а не абстрактному Святому Світлу, яке шанують люди та дворфи. Лаурна доручає учням духовні праці — отримати священні шати, зцілити поранену Вартову. Через ці традиції послушники пізнають, що їхні сили — прямий дар Матері-Місяця, призначений берегти й зцілювати народ калдореїв."}},faq={{q="Де знайти Лаурну Морнінґлайт?",a="Лаурна Морнінґлайт — у селищі Доланаар, у центральній частині Тельдрассила, недалеко по дорозі від Тінедолу.",al={"місце лаурни","де лаурна","тренер жерців доланаара"}},{q="Чим займається Лаурна Морнінґлайт?",a="Вона наставниця жерців для нічних ельфів. Вона навчає нових заклинань, підвищує ранги вже відомих умінь і проводить через перші класові обряди.",al={"що робить лаурна","роль лаурни","лаурна тренер жерців"}},{q="Які завдання вона дає?",a="Вона дає класові завдання молодим жерцям: посилає допомагати пораненим союзникам і шукати божественної прихильності Елуни через обрядове вбрання й молитви.",al={"завдання лаурни","завдання жерців доланаар"}},{q="Чи навчає вона інші народи?",a="Хоча її корені — у Сестринстві Елуни, наставники жерців Альянсу навчають кожного союзного жерця, що прийде по духовну науку.",al={"чи люди можуть тут навчатися","тренер жерців для будь-якої раси"}},{q="Чи пов'язана вона з Храмом Місяця?",a="Так, як калдорейська жриця, вона присвятила свої обітниці й магію Богині Елуні та ширшим традиціям, які береже Храм Місяця в Дарнасусі.",al={"чи вона із сестринства елуни","лаурна храм місяця"}},{q="Чи має вона спільне родове ім'я з іншими нічними ельфами?",a="Серед калдореїв Тельдрассила родичі Лаурни не відомі.",al={"рід морнінґлайт","родичі лаурни"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="Леланай",s="Леланай — доглядачка їздових звірів нічних ельфів у Ценаріонському Анклаві Дарнасуса. Вона довіряє гідним вершникам лютих котів-шаблезубів, на яких їздять нічні ельфи, — і звичайних нічних шаблезубів, і прудких бойових звірів — своїм родичам і довіреним союзникам Дарнасуса.",h="Леланай — доглядачка їздових звірів нічних ельфів у Ценаріонському Анклаві Дарнасуса.",kw={"леланай","шаблезуби","їздові звірі","ценаріонський анклав","джартсам","дарнасус","нічний шаблезуб"},ang={["faction:Alliance"]="Герої Альянсу, які здобули найвищу пошану Дарнасуса, можуть звернутися до Леланай, щоб вирушати в бій на славетних шаблезубах пліч-о-пліч із союзниками-калдореями.",["race:NightElf"]="Для нічних ельфів візит до Леланай — важливий обряд посвяти, коли настає час здобути традиційного котячого скакуна."},sec={{t="Доглядачка звірів Ценаріонського Анклаву",b="Леланай стоїть поруч із наставником верхової їзди Джартсамом серед велетенських дерев Ценаріонського Анклаву й доглядає одних із найкращих великих котів, виведених у Калімдорі. Нічні ельфи здавна мають глибокий зв'язок із лютими хижаками північних лісів: вони привчають нічних і морозних шаблезубів носити Вартових і розвідників пересіченою місцевістю з хижою грацією. Леланай — головна постачальниця цих шанованих їздових звірів у столиці."},{t="Узи поза родом",b="Їздових шаблезубів охоче дають будь-якому нічному ельфові з достатньою вправністю, але для чужинців поріг значно вищий. Через священну природу цих котів і вроджену відстороненість калдореїв Леланай не довірить звіра шукачеві пригод іншої раси, доки той не здобуде найвищої пошани й слави в Дарнасусі."}},faq={{q="Де знайти Леланай?",a="Леланай — у Ценаріонському Анклаві в Дарнасусі, просто поруч із наставником їзди на тиграх, Джартсамом.",al={"місце леланай","де леланай","карта леланай"}},{q="Що продає Леланай?",a="Вона продає повіддя для різних порід морозних і нічних шаблезубів, зокрема прудких броньованих — для досвідчених вершників.",al={"крам леланай","які їздові в неї","скакуни нічних ельфів"}},{q="Чи можуть не нічні ельфи купити їздових тварин у Леланай?",a="Так, але лише якщо довели виняткову вірність, здобувши звеличення в Дарнасусі. Інакше вона відмовиться продавати своїх звірів чужинцям.",al={"чи люди можуть купити шаблезубів","чи дворфи їздять на шаблезубах","репутація для шаблезубів"}},{q="Чи можуть гравці Орди спілкуватися з Леланай?",a="Ні. Леланай вірна фракції Дарнасуса з Альянсу. Вона й довколишні вартові анклаву вважатимуть членів Орди ворожими загарбниками.",al={"чи орда може купити шаблезубів","чи леланай дружня до орди"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="Лейтенант Фаррен Орінелль",s="Лейтенант Фаррен Орінелль — офіцер армії Стормвінда, що нині несе службу в корчмі Саутшора в Передгір'ї Гілсбреда. Глибоко незадоволений своїм прикордонним призначенням, він здебільшого пиячить, перекладаючи свої обов'язки на мандрівників. Його головне військове доручення — розібратися з мурлоками, що наступають на узбережжі, і цю морочливу справу він охоче доручає іншим, сподіваючись вибити собі переведення назад на південь.",h="Лейтенант Фаррен Орінелль — офіцер армії Стормвінда, що нині несе службу в корчмі Саутшора в Передгір'ї...",kw={"лейтенант фаррен орінелль","саутшор","стормвінд","мурлоки","маршал редпат","гілсбред"},ang={["faction:Alliance"]="Для героїв Альянсу Орінелль уособлює невдоволених вояків із Півдня, що тримають самотню північну заставу й готові платити грошима й похвалою кожному, хто виконає їхні обов'язки.",["race:Human"]="Як стормвіндський вояк, що застряг далеко від Лісу Елвінн, Орінелль своєю зневагою до північної прикордонної служби показує прірву між зручним життям у столиці й суворою службою за морем."},sec={{t="Вигнанець у Саутшорі",b="Лейтенант Фаррен Орінелль не обирав Саутшор. Посланий далеко від Стормвінда, лейтенант вважає вологі спірні береги Гілсбреда жалюгідним пониженням порівняно з цивілізованими вигодами столиці. Замість патрулювати поля чи узгоджувати оборону зі своїм командиром, Маршалом Редпатом, Орінелль практично оселився в корчмі Саутшора. Дні він проводить, дуючись, пиячачи й мріючи про офіційний наказ про переведення, що поверне його на південь."},{t="Чужими руками",b="Хоч Орінелль зручно влаштувався в корчмі, він досі підпорядковується Маршалові Редпату, який доручив лейтенантові вичистити мурлоків, що кишать на ближньому узбережжі. Не бажаючи бруднити чоботи в прибережному мулі, Орінелль покладається на мандрівних шукачів пригод: вони мають прорідити цих створінь і принести докази їхньої загибелі. Він сподівається, що відчутні результати переконають начальство, що обов'язок виконано, і пришвидшать його повернення до Стормвінда."}},faq={{q="Хто такий Лейтенант Фаррен Орінелль?",a="Це офіцер війська Стормвінда, що служить у Саутшорі — містечку в Передгір'ї Гілсбреда. Його можна знайти в корчмі Саутшора, де він випиває й бурчить на своє призначення.",al={"фаррен орінелль","хто такий орінелль","лейтенант саутшора"}},{q="Чому він у Саутшорі?",a="Його перевели на північ зі Стормвінда, щоб підсилити місцевий гарнізон і підтримати Маршала Редпата. Він терпіти не може цього призначення й мріє повернутися додому.",al={"чому фаррен у саутшорі","переведення орінелля"}},{q="Яке в нього офіційне доручення?",a="Маршал Редпат наказав йому впоратися з ворожими мурлоками, що заполонили узбережжя Гілсбреда, але Орінелль воліє платити мандрівним найманцям, щоб ті билися замість нього.",al={"обов'язок фаррена","місія орінелля","фаррен мурлоки"}},{q="Чи виходить він колись із корчми Саутшора?",a="Ні. Орінелль майже весь час проводить біля шинквасу, не маючи жодного бажання виходити на брудні пляжі чи стикатися з ворожими силами надворі.",al={"де фаррен","місце фаррена","корчма орінелля"}},{q="Яка кінцева мета Фаррена?",a="Найбільше він хоче домогтися офіційного переведення назад до Стормвінда, подалі від небезпек і похмурості узбережжя Лордерону.",al={"чого хоче фаррен","переведення"}},{q="Хто командир Орінелля?",a="Він звітує Маршалові Редпату, який командує загоном війська Альянсу, що боронить Саутшор.",al={"начальник фаррена","бос фаррена","хто командує фарреном"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="Лейтенант Гаґґердін",s="Лейтенант Гаґґердін — дворфійський офіцер, що служить на Виступі в Горах Альтерак. Стоячи на варті перед укріпленою брамою до Долини Альтерак, він є головним вербувальником і офіцером зв'язку Варти Стормпайків. Він оцінює поборників Альянсу, що прагнуть слави, і нагороджує тих, хто доведе свою відвагу в боротьбі з Кланом Морозного Вовка.",h="Лейтенант Гаґґердін — дворфійський офіцер, що служить на Виступі в Горах Альтерак.",kw={"лейтенант гаґґердін","варта стормпайків","долина альтерак","гори альтерак","клан морозного вовка","дворфи"},ang={["faction:Alliance"]="Лейтенант Гаґґердін — ваш головний зв'язковий біля Долини Альтерак: він видає повноваження й офіційні відзнаки, здобуті в боях із Кланом Морозного Вовка.",["faction:Horde"]="Непохитний вартовий, що стереже прохід Альянсу до Долини Альтерак, Гаґґердін скеровує підкріплення, послані розгромити орків клану Морозного Вовка.",["race:Dwarf"]="Гордий офіцер клану Стормпайк, Гаґґердін уособлює рішучість Айронфорджа відкрити свою спадщину титанів серед засніжених скель Альтераку."},sec={{t="Брамник Виступу",b="Із засніжених висот Виступу над Передгір'ям Гілсбреда Лейтенант Гаґґердін наглядає за місцем збору для безперервного походу Альянсу в Долині Альтерак. Біля величезної дерев'яної брами майорять дворфійські стяги, а новобранці й ветерани збираються під його пильним оком, готуючись поринути в крижану зону бойових дій."},{t="Голос Варти Стормпайків",b="Служачи Експедиції Стормпайків, Гаґґердін дбає, щоб у долині Айронфордж і Великий Альянс представляли лише перевірені воїни. Через випробування на кшталт завдання «Випробування» він доручає новобранцям повертати стяги й реліквії, а також вручає офіційні подяки, відзнаки й звання, коли солдати просуваються лавами Варти Стормпайків."}},faq={{q="Хто такий Лейтенант Гаґґердін?",a="Лейтенант Гаґґердін — дворф-офіцер Варти Стормпайків. Він стоїть біля входу до Долини Альтерак, на Мисі в Горах Альтерак, наглядає за набором до війська Альянсу й нагороджує за бойові заслуги.",al={"гаґґердін","хто такий гаґґердін","лейтенант гаґґердін альтерак"}},{q="Де знайти Лейтенанта Гаґґердіна?",a="Він на півночі Гір Альтерак, на Мисі, просто біля порталу й брами, що ведуть до Долини Альтерак.",al={"місце гаґґердіна","де лейтенант гаґґердін","вхід альянсу в долину альтерак"}},{q="Яку роль Гаґґердін відіграє у Варті Стормпайків?",a="Він польовий зв'язковий і офіцер-інтендант: проводить випробування для новобранців, як-от «Випробувальний полігон», і нагороджує бійців Альянсу вищими званнями й відзнаками в міру того, як зростає їхня прихильність Варти Стормпайків.",al={"що робить гаґґердін","завдання гаґґердіна","офіцер варти стормпайків"}},{q="Чому Альянс воює в Долині Альтерак?",a="The Stormpike Expedition journeyed into the valley to excavate ancient relics and dwarven history, but their arrival sparked a fierce territorial conflict with the resident Frostwolf orcs and their Horde allies.",al={"чому долина альтерак","мета експедиції стормпайків","конфлікт альтерака"}},{q="Чи можуть гравці Орди спілкуватися з Лейтенантом Гаґґердіном?",a="Ні. Лейтенант Гаґґердін — чинний офіцер Альянсу й нападе на кожного поборника Орди, що наблизиться до брами на Мисі.",al={"чи гаґґердін ворожий до орди","орда гаґґердін","чи орда може говорити з гаґґердіном"}},{q="Що таке випробування «Випробувальний полігон»?",a="«Випробувальний полігон» — вступне доручення, яке Гаґґердін дає майбутнім солдатам Альянсу, щоб перевірити їхню вправність і рішучість, перш ніж вони цілком присвятять себе війні в Долині Альтерак.",al={"завдання випробувального полігону","випробувальний полігон альтерак","гаґґердін полігон"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.211.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="Лейтенант Лісанде",s="Лейтенант Лісанде — посланниця Срібного світанку, що несе службу на високих столових горах Тандер Блафа. Людина, яка відкрито діє на землях тауренів, вона підтримує зв'язок між союзниками у боротьбі зі спільною загрозою, що ставить під питання саме існування світу, — Погибеллю.",h="Лейтенант Лісанде — посланниця Срібного світанку, що несе службу на високих столових горах Тандер Блафа.",kw={"лейтенант лісанде","срібний світанок","погибель","нежить","тандер блаф","король-ліч"},ang={["faction:Horde"]="Лісанде — нагадування, що війна з Погибеллю вимагає прагматизму й часом співпраці з нейтральними людськими орденами.",["race:Tauren"]="Хоч Лісанде й чужинка, таурени шанують відданість Срібного світанку справі очищення землі від мерзенної скверни нежиті."},sec={{t="Несподівана посланниця",b="Людські обличчя — рідкість на продуваних вітрами висотах Тандер Блафа, але Срібний світанок стоїть понад звичною ворожнечею фракцій. Лейтенант Лісанде служить святому орденові, вишукуючи ознаки скверни Короля-Ліча навіть у віддаленому Калімдорі. Коли на рівнинах унизу заворушиться нежить, вона скликає хоробрих чемпіонів Орди, щоб ті вирушили й розвідали загрозу, поки та не осквернила священну землю."}},faq={{q="Чому в Тандер Блафі стоїть людина?",a="Лісанде представляє Срібний світанок — нейтральну спілку, що прагне лише одного: знищити Погибель. Оскільки Світанок приймає до своїх лав народи і Альянсу, і Орди, його посланцям дозволено дипломатичний в'їзд до столиць, щоб спільно організовувати оборону від нежиті.",al={"людина в тандер блафі","чому лісанде тут","чи вона ворожа"}},{q="Що цікавить Срібний світанок у Малгорі?",a="Король-Ліч загрожує кожному куточкові Азероту, а не лише Східним Королівствам. Лісанде стежить за будь-якими ознаками некромантії чи вторгнення Погибелі, що загрожують спокою Малгору, і дбає, щоб місцеві захисники були напоготові.",al={"скурдж у малгорі","чому тандер блафф","нежить у землях тауренів"}},{q="Які завдання дає Лейтенант Лісанде?",a="Лісанде посилає шукачів пригод спуститися з плато й розвідати вторгнення Погибелі, помічені на довколишніх землях, а потім звітувати, щоб Світанок міг оцінити масштаби загрози.",al={"завдання лісанде","що робить лісанде","завдання розслідування"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="Лейтенант Невелл",s="Лейтенант Невелл — офіцер Срібного світанку, що стоїть під брамою Айронфорджа в Дун Мороґу. Він — заслін проти темряви Погибелі, що шириться: керує місцевими захисниками й попереджає шукачів пригод про нежить, яка навідується до кордонів дворфійського королівства.",h="Лейтенант Невелл — офіцер Срібного світанку, що стоїть під брамою Айронфорджа в Дун Мороґу.",kw={"лейтенант невелл","срібний світанок","погибель","дун мороґ","айронфордж","нежить"},ang={["faction:Alliance"]="Для звитяжців Альянсу, що прямують до Айронфорджа, Невелл — нагадування, що війна з Погибеллю не обмежується північчю.",["race:Dwarf"]="Дворфи цінують пильне око Срібного світанку під своїм гірським домом, бо знають: стерегтися некромантії треба навіть на холодних схилах Дун Мороґа."},sec={{t="Варта серед снігів",b="Срібний світанок найбільше славиться тим, що тримає оборону в спустошених Чумних Землях Лордерона, але його пильність сягає далеко на південь. Лейтенант Невелл, що несе службу на крижаних вітрах під Айронфорджем, уособлює рішучий захист ордену від некромантських вторгнень. Коли в гірських перевалах Дун Мороґа ворушиться Погибель, Невелл скеровує новобранців і вправних шукачів пригод на передову, щоб засніжений поріг Айронфорджа лишався безпечним."}},faq={{q="Хто такий Лейтенант Невелл?",a="Лейтенант Невелл — офіцер Срібного світанку, що служить біля Айронфорджа в Дун Мороґу. Його мета — згуртувати місцевих захисників і розвідати ознаки Погибелі, що підбирається до дворфійського королівства.",al={"роль невелла","хто такий невелл","лейтенант невелл"}},{q="Чому Срібний світанок стоїть під Айронфорджем?",a="Хоча Срібний світанок базується здебільшого в Лордероні, він стежить за вторгненнями нежиті на всьому континенті. Якщо Король-Ліч спробує вдарити вглиб союзних земель на кшталт Дун Мороґу, туди посилають офіцерів, як-от Невелла, щоб організувати оборону міст і розвідати пересування ворога.",al={"срібний світанок у дун мороґу","срібний світанок айронфордж"}},{q="Про що Лейтенант Невелл просить шукачів пригод?",a="Невелл доручає вправним героям вийти за браму Айронфорджа, розвідати й відкинути сили Погибелі поблизу, знешкодивши загрозу нежиті, перш ніж вона закріпиться в гірських проходах.",al={"завдання невелла","розслідуйте плеть"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="Лейтенант Оррін",s="Лейтенант Оррін — офіцер Срібного світанку, що стоїть на варті біля брами Стормвінда. З Долини Героїв він координує місцеву оборону від набігів Погибелі й відсилає новобранців розвідувати загрози нежиті за мурами столиці.",h="Лейтенант Оррін — офіцер Срібного світанку, що стоїть на варті біля брами Стормвінда.",kw={"лейтенант оррін","срібний світанок","погибель","долина героїв","нежить","стормвінд"},ang={["class:Paladin"]="Паладини, що служать Світлу, природно знаходять спільну мову зі Срібним світанком, який викорінює некромантію всюди, де вона гніздиться.",["faction:Alliance"]="Для героїв Альянсу, що повертаються до столиці, Оррін — суворе нагадування: навіть південні серцеві землі не цілком убезпечені від Короля-Ліча."},sec={{t="Вартовий біля брами",b="Срібний світанок відомий передусім тим, що тримає передову в зруйнованих північних землях, проте його присутність сягає й півдня — орден оберігає життєво важливі твердині на кшталт Стормвінда. Лейтенант Оррін стоїть біля височенних статуй Долини Героїв і стежить за дорогою, виглядаючи ознаки скверни. Коли за стінами столиці ворушиться некромантія, його обов'язок — здійняти тривогу й зібрати шукачів пригод, перш ніж мерзенні сили встигнуть загрожувати людям."},{t="Око на неживих",b="Оррін — один із головних зв'язкових між незалежним орденом і добровольцями південного королівства. Коли за міською брамою з'являються сліди Погибелі, він збирає дужих розвідників і відсилає їх здобувати відомості та прибирати небезпечні артефакти — як-от тріснуті некротичні кристали, — щоб краще зрозуміти загрозу нежиті й дати їй відсіч."}},faq={{q="Хто такий Лейтенант Оррін?",a="Лейтенант Оррін — людина, офіцер Срібного світанку. Він стоїть у Долині Героїв при вході до Стормвінда: організовує оборону й набирає розвідників щоразу, як Погибель загрожує довколишнім землям.",al={"хто такий оррін","лор лейтенанта оррін","хто офіцер срібного світанку"}},{q="Чому Срібний світанок є в Стормвінді?",a="Хоча Срібний світанок воює з Погибеллю здебільшого в Чумних Землях, він має застави й посланців у найбільших осередках Альянсу й Орди. Біля брами столиці офіцери на кшталт Орріна стежать за вторгненнями некромантів і набирають вправних бійців, щоб стримати поширення нежиті.",al={"чому срібний світанок у стормвінді","срібний світанок стормвінд","що робить срібний світанок тут"}},{q="Про що Лейтенант Оррін просить шукачів пригод?",a="Оррін посилає новобранців розвідати околиці Стормвінда, перевірити ознаки діяльності Погибелі й зібрати артефакти на кшталт тріснутих некротичних кристалів, щоб вивчити нечестиву магію, яка стоїть за цими вторгненнями.",al={"завдання оррін","розслідуйте плеть стормвінда","чого хоче оррін"}}},fp="16,276,23.446.0,20.352.0,24.244.0,41.313.0,49.210.0"}
P.entries["npc:loganaar"] = {n="Лоґанаар",s="Лоґанаар — нічний ельф, наставник друїдів, що живе в Нічному Притулку в Місячному Гаю. Він віддано веде новачків і з Альянсу, і з Орди: навчає молодих друїдів єднатися з дикою природою й готує їх до поклику Смарагдового Сну.",h="Лоґанаар — нічний ельф, наставник друїдів, що живе в Нічному Притулку в Місячному Гаю.",kw={"лоґанаар","нічний притулок","місячний гай","друїди","коло кенарія","смарагдовий сон"},ang={["class:Druid"]="Для друїдів і з Дарнасуса, і з Тандер Блафа Лоґанаар — один із перших наставників, яких ви зустрінете, телепортувавшись до Місячного Гаю: він дає поглиблене навчання й духовну пораду.",["race:NightElf"]="Лоґанаар продовжує прадавні традиції друїдів-калдореїв, які тисячоліттями єдналися з природою й поринали у Смарагдовий Сон під проводом Малфуріона Стормрейджа."},sec={{t="Хранитель священного мистецтва",b="Серед спокійного гілля Нічного Притулку Лоґанаар став одним із головних наставників для щойно посвячених друїдів, які прибувають до Місячного Гаю. Хоч би звідки прийшов новачок — із Дарнасуса чи з Тандер Блафа, — Лоґанаар навчає його рівноваги, зміни подоби й шанування природи. Він нагадує учням, що навіть серед холодного каменю й незнайомих земель справжній спокій треба знаходити в собі. А ще він радо скеровує тих, хто глибше поринає у справи Кола Кенарія: обдарованих учнів посилає до мандрівників на кшталт Торви Патфайндера в Кратері Ун'Ґоро або далі — до прадавніх лісових обрядів."},{t="Поклик Сну",b="Окрім основ чаротворства, Лоґанаар готує учнів до найвищого призначення, спільного для всіх споконвічних захисників Калімдора, — глибокого сну у Смарагдовому Сні. Він розповідає новачкам про священний зв'язок між первісним царством духу Азерота й світом наяву і нагадує, що справжня майстерність колись вимагатиме століттями спати, аби під проводом напівбогів ходити серед найчистіших, незаплямованих образів природи."}},faq={{q="Хто такий Лоґанаар?",a="Лоґанаар — нічний ельф, наставник друїдів у Нічному Притулку, головному поселенні Місячного Гаю. Він радо навчає друїдів будь-якого походження й знайомить їх із глибшими традиціями Кола Кенарія.",al={"нпс лоґанаар","хто такий лоґанаар","лор лоґанаара"}},{q="Чи навчає Лоґанаар друїдів Орди?",a="Так. Місячний Гай — священна нейтральна земля під опікою Кола Кенарія. Як член Кола, Лоґанаар відкладає ворожнечу Альянсу й Орди та навчає однаково і тауренів, і нічних ельфів-друїдів.",al={"чи таурени навчаються в лоґанаара","лоґанаар орда","тренер друїдів місячної поляни орда"}},{q="Чого Лоґанаар навчає про Смарагдовий Сон?",a="Лоґанаар навчає, що кожен справжній друїд рано чи пізно відчує поклик Смарагдового Сну. Він пояснює, що саме мандруючи серед його незіпсованих образів під час довгої, глибокої сплячки, друїд проходить найвище навчання.",al={"сон лоґанаара","смарагдовий сон цитата"}},{q="Куди Лоґанаар посилає досвідчених друїдів?",a="Коли друїди набираються досвіду, Лоґанаар посилає їх у світ спостерігати за первісною природою Азероту й зцілювати її. Серед іншого він посилає досвідчених учнів допомагати природознавцям, як-от Торві Патфайндеру, у диких нетрях Кратера Ун'Ґоро.",al={"завдання лоґанаара","завдання торви слідопита лоґанаар"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="Ломак Ґірстріп",s="Ломак Ґірстріп — честолюбний гном-винахідник із Містечка Майстрів в Айронфорджі. Славетний тим, що створив руйнівну вибухівку NG-5, він підтримує зв'язок з іншими гномськими дослідниками, що працюють у Калімдорі.",h="Ломак Ґірстріп — честолюбний гном-винахідник із Містечка Майстрів в Айронфорджі.",kw={"ломак ґірстріп","вибухівка ng-5","містечко майстрів","інженерія","гномреґан","айронфордж"},ang={["faction:Alliance"]="Агенти Альянсу, що мандрують між Айронфорджем і заставами експедицій у Калімдорі, часто перевозять для Ломака делікатні набої й нестійкі формули.",["profession:Engineering"]="Вибухівка NG-5 Ломака — вершина гномської піротехніки й натхнення для винахідників, яких цікавлять потужні вибухові суміші.",["race:Gnome"]="Ломак утілює незламний запал гномів Містечка Майстрів: навіть у вигнанні з Гномреґану він веде ризиковані технічні дослідження."},sec={{t="Іскра в Містечку Майстрів",b="Серед брязкоту шестерень і сичання труб Містечка Майстрів в Айронфорджі Ломак Ґірстріп удосконалює тонкощі гномської артилерійської справи. Як і чимало гномів-вигнанців, що втекли від трагедії Гномреґану, Ломак розгорнув свої винахідницькі справи просто в дворфійській столиці. Його майстерня зосереджена на нестійких хімічних сумішах і особливих набоях, створених, щоб долати добре укріплені ворожі твердині."},{t="Вибухівка NG-5",b="Найбільша гордість Ломака в сучасній бойовій інженерії — вибухівка NG-5. Ця суміш, створена для найбільшої руйнівної сили, потребує точного поводження й рідкісних хімічних реагентів. Щоб удосконалювати й застосовувати такі небезпечні винаходи в полі, Ломак тримає зв'язок зі старими колегами на далеких театрах бойових дій і пересилає через Велике Море технічні замовлення та небезпечні припаси."}},faq={{q="Де знайти Ломака Ґірстріпа?",a="Ломак Ґірстріп живе в Містечку Майстрів — гномському кварталі у східній частині гірського міста Айронфордж.",al={"місце ломака","де ломак","знайти ломака ґірстріпа"}},{q="Яким винаходом славиться Ломак Ґірстріп?",a="Ломака найкраще знають як творця вибухівки NG-5 — потужної суміші, що мала давати гномам нищівну вогневу міць у їхніх справах.",al={"що створив ломак","винахід ломака","творець вибухівки"}},{q="Чому Ломак має справу зі знайомими в Калімдорі?",a="Ломак підтримує зв'язок із колишніми колегами-дослідниками, що працюють у прикордонних краях на кшталт Гір Кам'яного Кігтя: разом вони роздобувають небезпечні хімічні складники й випробовують його потужну вибухівку в справжніх операціях.",al={"ломак стоунталон","чому завдання стоунталон","колеги ломака"}},{q="Які доручення Ломак дає шукачам пригод?",a="Ломак доручає надійним кур'єрам Альянсу перевозити замовлення й нестабільні хімічні реагенти між Айронфорджем і дослідниками за кордоном — найчастіше для його дослідів із вибухівкою NG-5.",al={"завдання ломака","хімікалії некомпетентності","завдання старий колега"}},{q="Що за Квитанція замовлення пов'язана з Ломаком?",a="Квитанцію замовлення склав сам Ломак: це накладна, за якою майстри впорядковують і обліковують поставки особливого обладнання й небезпечних нестабільних реагентів.",al={"квитанція замовлення","квитанція ломака"}},{q="Чи належить Ломак до біженців із Гномреґана?",a="Так. Як і решта мешканців Містечка Майстрів, Ломак — частина вигнаної громади Гномреґана, що живе під гостинним дахом дворфів Айронфорджа й далі займається інженерією.",al={"чи ломак із гномреґана","фракція ломака"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="Лонґбрейда Похмурий",s="Лонґбрейд Похмурий — дворф-командир з Айронфорджа, що стоїть табором біля самої зруйнованої фортеці Дун Модр на півночі Багнокраю. Оплакуючи загибель брата й захоплення Мосту Тандол, він згуртовує вцілілих дворфів проти загарбників із клану Темного Заліза.",h="Лонґбрейд Похмурий — дворф-командир з Айронфорджа, що стоїть табором біля самої зруйнованої фортеці Дун Модр...",kw={"лонґбрейд похмурий","дун модр","міст тандол","темне залізо","айронфордж","багнокрай"},ang={["faction:Alliance"]="Лонґбрейд тримає тонкий рубіж, що стереже північну браму Каз Модану, і бореться за те, щоб знову відкрити важливий суходільний шлях через Міст Тандол до Араті.",["race:Dwarf"]="Для дворфів Айронфорджа Лонґбрейд утілює люту, незгасну кровну ворожнечу з підступними родичами з Темного Заліза, які вдарили просто по їхній північній брамі."},sec={{t="Гірка варта",b="Стоячи на видноті мосту до Аратійського нагір'я, Лонґбрейд Похмурий згуртовує рештки дворфійського гарнізону після того, як клан Темного Заліза захопив Дун Модр. Раптовий напад розгромив місцевих захисників, і під час облоги Мосту Тандол загинув рідний брат Лонґбрейда. Обтяжений горем і ненавистю, Лонґбрейд не покидає північного рубежу: він спрямовує мандрівників і вцілілих горян у точні удари, щоб стримати наступ Темного Заліза."},{t="Тримати рубіж",b="Окрім оборони підступів до мосту, Лонґбрейд керує й ширшими діями дворфів по всьому Багнокраю. Він відрядив важливих вояків супроводжувати Шукача Велґара в болота й невтомно працює, щоб повернути втрачені укріплення Дун Модра, присягаючись помститися диверсантам Темного Заліза."}},faq={{q="Хто такий Лонґбрейда Похмурий?",a="Лонґбрейда Похмурий — дворф-командир, що стоїть біля Дун Модра на півночі Багнокраю. Він очолює місцевий опір Альянсу дворфам Темного Заліза, які захопили цей край.",al={"хто такий лонґбрейда","особа лонґбрейди","дворф дун модра"}},{q="Чому Лонґбрейду звуть Похмурим?",a="Похмурим він став, коли його брат загинув під час нищівного нападу Темного Заліза на Міст Тандол. Відтоді його поглинуло прагнення помститися за полеглого родича.",al={"чому він похмурий","брат лонґбрейди","минуле лонґбрейди"}},{q="Що сталося з Дун Модром?",a="Дун Модр захопив і окупував клан Темного Заліза: вони напали з засідки на дворфійський гарнізон і спробували зруйнувати Міст Тандол, щоб перерізати головний шлях між Багнокраєм та Аратійським нагір'ям.",al={"падіння дун модра","що сталося з мостом","напад на проліт тандола"}},{q="Що пов'язує Лонґбрейду з Шукачем Велґаром?",a="Лонґбрейда виділив зі своїх сил солдатів, щоб вони супроводжували й охороняли Шукача Велґара, поки дворфійські розкопувачі заглиблювалися в небезпечний Багнокрай.",al={"велґар лонґбрейда","лист мерріна"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:loramus-thalipedes"] = {n="Лорамус Таліпедес",s="Лорамус Таліпедес — відлюдний нічний ельф, мисливець на демонів, що усамітнився на віддаленому острові біля узбережжя Азшари. У супроводі вірних гончаків Скверни він присвятив своє існування знищенню Разеліха Осквернителя й веде досвідчених героїв крізь ритуали, щоб повалити цього жахолорда.",h="Лорамус Таліпедес — відлюдний нічний ельф, мисливець на демонів, що усамітнився на віддаленому острові біля...",kw={"лорамус таліпедес","мисливець на демонів","разеліх осквернитель","гончаки скверни","азшара","спустошені землі","жахолорд"},ang={["class:Warlock"]="Чорнокнижники розпізнають у його приборканих гончаках Скверни доказ виняткової влади над демонами, хоча Лорамус підкоряє демонів лише для того, щоб нищити їхніх же родичів.",["race:NightElf"]="Нічні ельфи здавна дивляться на мисливців на демонів із глибоким жахом і недовірою: їхнє ритуальне самокалічення й угоди з демонами здаються непрощенним шляхом, що повторює зраду іллідарі."},sec={{t="Сліпий Мисливець з островів",b="Лорамус Таліпедес живе на самотньому, збуреному бурями острові на південний схід від Кладки Гетери й тримається осторонь від решти свого народу. Він — мисливець на демонів, вигнанець, що під наглядом свого наставника пройшов болісний ритуал осліплення, аби здобути примарний зір. В оточенні трьох велетенських гончаків Скверни — Райтафа, Шагіара й Замана — Лорамус стежить за невидимими течіями демонічної порчі по всьому Азероту й пильно наглядає за розтрощеними руїнами Азшари."},{t="Помста через континенти",b="Одержимість Лорамуса лежить за морем, у Спустошених Землях: усі його думки — про жахолорда Разеліха Осквернителя. Знаючи, що звичайна сталь не здатна назавжди покінчити з підступним демоном, Лорамус веде мандрівників крізь прадавні ритуали: вони мусять зібрати зачарований азшарит і перекувати легендарну зброю — Згубу Скверни. Цими таємничими приготуваннями він прагне зірвати з Разеліха захисні чари, скувати справжнє ім'я демона й раз і назавжди звести з ним рахунки."}},faq={{q="Хто такий Лорамус Таліпедес?",a="Лорамус Таліпедес — нічний ельф, мисливець на демонів, що живе на відлюдному острові біля узбережжя Азшари. Він присвятив себе боротьбі з могутніми демонами, насамперед із жахолордом Разеліхом Осквернителем.",al={"особа лорамуса","мисливець на демонів в азшарі","хто такий лорамус"}},{q="Чому в Лорамуса пов'язка на очах?",a="Як і інші мисливці на демонів, Лорамус під проводом свого наставника позбувся власних очей. Натомість цей ритуал дав йому примарний зір, потрібний, щоб відчувати демонічну енергію.",al={"чому лорамус із пов'язкою","лорамус сліпий","пов'язка мисливця на демонів"}},{q="Чому його стережуть гончаки Скверни?",a="Лорамус підкорив і прив'язав до себе трьох могутніх гончаків Скверни — Райтафа, Шагіара й Замана, — спрямувавши їхні хижі інстинкти на службу своїм полюванням на демонів, а не Палаючому Легіонові.",al={"гончаки скверни лорамуса","чому в лорамуса демони","райтаф шахіар заман"}},{q="Що пов'язує його зі Спустошеними Землями?",a="Він веде боротьбу за знищення жахолорда Разеліха Осквернителя, що панує на висотах Спустошених Земель. Лорамус дає знання, обряди й зброю, без яких не пробити захисту Разеліха.",al={"лорамус спустошені землі","завдання разеліха","чому його цікавлять спустошені землі"}}},fp="18,274,29.484.0,28.473.1,26.193.0,27.208.0,37.189.0,44.216.0"}
P.entries["npc:lord-arkkoroc"] = {n="Лорд Арккорок",s="Лорд Арккорок — прадавній велетенський морський гігант, що живе в зруйнованому Храмі Арккорана на порізаному узбережжі Азшари. Мисливець на демонів Лорамус Таліпедес називає його нижчим божеством; Арккорок панує над довколишніми водами й повеліває меншими морськими гігантами — своїми синами.",h="Лорд Арккорок — прадавній велетенський морський гігант, що живе в зруйнованому Храмі Арккорана на порізаному...",kw={"лорд арккорок","храм арккорана","морський гігант","гетера","гідра","азшара"},ang={["race:NightElf"]="Руїни Храму Арккорана стоять на колишніх землях Високороджених, де тепер над занепалою величчю давнього Калімдору безроздільно панує прадавня морська істота."},sec={{t="Володар затонулого узбережжя",b="Лорд Арккорок, що спочиває серед укритих сольовою кіркою руїн Храму Арккорана, — далеко не звичайний морський гігант. Для відлюдників на кшталт Лорамуса Таліпедеса ця колосальна істота — нижче божество, чия воля править довколишніми водами. Його сини обходять скелі й мілини довкола святилища, утверджуючи його тихе панування над бурхливими берегами Азшари."},{t="Помста глибинам",b="Попри величезну божественну силу, Арккорок зазнає й особистих утрат під хвилями. Страхітлива багатоголова гідра на ім'я Гетера вистежила й пошматувала багатьох його синів біля скель. Не маючи змоги чи бажання сам полювати на звіра, Арккорок пропонує цінні знання й таємну допомогу кожному мандрівному шукачеві пригод, досить сильному, щоб принести йому голови вбивці його нащадків."}},faq={{q="Хто такий Лорд Арккорок?",a="Лорд Арккорок — величезний морський велетень, що живе в Храмі Арккорана в Азшарі. Його шанують як нижче божество морів, і він править виводком морських велетнів, яких вважає своїми синами.",al={"хто такий арккорок","лор арккорока","морський велетень храму"}},{q="Де знайти Лорда Арккорока?",a="Ви знайдете його серед руїн Храму Арккорана на східному узбережжі й скелястих рифах Азшари.",al={"місце арккорока","де арккорок","знайти арккорока"}},{q="Чому Лорамус Таліпедес посилає шукачів пригод до Арккорока?",a="Лорамус Таліпедес посилає мандрівників до Арккорока по таємні знання про одного могутнього демона. Як нижче морське божество, Арккорок береже давні знання, але, перш ніж поділитися таємницями, вимагає вбити гідру Гетеру.",al={"завдання лорамуса арккорок","ім'я звіра"}},{q="Чому Арккорок розгніваний на гідру Гетеру?",a="Люте морське чудовисько Гетера вбила кількох синів Арккорока, що обходили узбережжя дозором. Прагнучи помститися за загиблих, морський велетень вимагає її голови.",al={"чому вбивати гетеру","арккорок образа на гідру"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="Лорд Баурлес К. Вішок",s="Лорд Баурлес К. Вішок — вельможа, якого можна застати в Палаті Прохача у Фортеці Стормвінда. Серед шинкарів він відомий неоплаченими рахунками й пристрастю до міцних напоїв, та в міському підпіллі він натрапив на справи значно темніші за звичайне пияцтво.",h="Лорд Баурлес К.",kw={"баурлес вішок","вельможа","палата прохача","дім вельмож","зардет","чорнокнижники"},ang={["class:Warlock"]="Надокучливе розслідування Вішока щодо шинку «Зарізане Ягня» — пряма загроза для тіньового ковену Стормвінда, тож його тиха смерть стає першочерговою справою для чорнокнижників.",["race:Human"]="Його присутність у Палаті Прохача віддзеркалює репутацію Дому Вельмож — розбещеного й себелюбного — у перші роки правління юного короля Андуїна."},sec={{t="Небезпечна цікавість вельможі",b="Лорд Баурлес К. Вішок, член впливового Дому Вельмож, тримається серед прохачів і сановників у Фортеці Стормвінда. Попри високе становище, Вішок узяв звичку навідуватися до кублищ Кварталу магів — особливо до шинку «Зарізане Ягня», — де залишав чималі неоплачені рахунки. Та саме там, за чаркою, він прочув про ковен чорнокнижників, що практикує темні мистецтва в підвалах під підлогою. Вирішивши закрити шинок, Вішок почав домагатися від інших вельмож офіційного розслідування — не знаючи, що викриття демонічних змов у Стормвінді рідко минає безкарно."},{t="Отруєна чаша",b="Своїми клопотаннями Вішок потрапив просто на приціл прихованих чорнокнижників міста. Не бажаючи ризикувати королівською увагою чи слідством щодо свого підземного святилища, чорнокнижник Зардет із Чорного Кігтя влаштував тихе усунення вельможі. Скориставшись сумнозвісною пристрастю Вішока до вишуканих вин, ковен приготував смертельне зілля під виглядом доброго елю й домовився, щоб найманий шукач пригод доставив фатальний напій просто під носом у вартових Фортеці."}},faq={{q="Хто такий Лорд Баурлес К. Вішок?",a="Лорд Баурлес К. Вішок — аристократ, пов'язаний із Домом Вельмож. Він проводить дні в Палаті Прохача у Фортеці Стормвінда, хоча в Кварталі магів сумно відомий тим, що назбирав великі борги за випивку й не платить їх.",al={"баурлес вішок","хто такий вішок","шляхетний прохач"}},{q="Де знайти Лорда Вішока?",a="Він стоїть у Палаті Прохача на східному боці Фортеці Стормвінда, серед інших придворних, дипломатів і прохачів, що чекають уваги корони.",al={"місце вішока","де вішок","знайти лорда вішока"}},{q="Чому чорнокнижники з-під «Зарізаного Ягняти» хочуть його смерті?",a="Пиячачи допізна в «Зарізаному Ягняті», Вішок дізнався, що під таверною діє ковен чорнокнижників. Він почав наполягати, щоб Дім Вельмож розпочав офіційне розслідування й закрив заклад, — і цим погрожував викрити їхні таємні справи.",al={"чому вбивати вішока","зардет вішок","чому труїти вішока"}},{q="Як його вбивають?",a="Зардет із Чорного Кігтя варить смертельну отруту й видає її за вишуканий напій. Знаючи слабкість Вішока до доброго трунку й дармової випивки, агент доставляє отруєний бочонок просто йому до Фортеці Стормвінда.",al={"як вбивають вішока","отрута вішока","благородне варево"}}},fp="23,241,32.635.0,14.479.1,31.233.0,32.179.0,63.276.1,23.222.1"}
P.entries["npc:lord-cobrahn"] = {n="Лорд Кобран",s="Лорд Кобран, колись друїд із нічних ельфів на ім'я Джарлаксла, — один зі спотворених Друїдів Ікла, що чатують у глибинах Печер Стогонів. Колись він славився в Колі Кенарія майстерністю перевтілення, але піддався жахіттю, що заразило печерні джерела. Тепер, назвавшись на честь своєї нової смертоносної подоби, Кобран командує виводками девіантних змій і боронить спотворений лабіринт.",h="Лорд Кобран, колись друїд із нічних ельфів на ім'я Джарлаксла, — один зі спотворених Друїдів Ікла, що чатують...",kw={"лорд кобран","джарлаксла","друїди ікла","печери стогонів","жахіття","перевтілення"},ang={["class:Druid"]="Кобран — похмуре застереження про те, як можна спотворити друїдське перевтілення, коли воно живиться жахіттям, а не природною рівновагою.",["faction:Horde"]="Шукачі пригод Орди розшукують Кобрана, щоб покласти край мерзенній порчі, яка просочується в Пустки, і захистити тендітну природу рівнин Калімдору.",["race:NightElf"]="Для нічних ельфів падіння Кобрана — гірка трагедія: вправний брат із Кола Кенарія зрікся своєї спадщини, щоб вести чудовиськ у підземних глибинах."},sec={{t="Зіпсований майстер подоб",b="Перш ніж узяти собі прізвисько Лорд Кобран, Джарлаксла був шанованим членом Кола Кенарія, і друїди славили його за надзвичайну вправність у перевтіленні на звірів. Коли Наралекс спустився в Печери Стогонів під Пустками, сподіваючись дістатися підземних джерел і повернути посушливим пустищам буяння життя, Джарлаксла пішов із ним. Та коли єднання Наралекса зі Смарагдовим Сном переродилося в зловісне жахіття, розум Джарлаксли зламався разом із розумом його побратимів."},{t="Обійми змія",b="Замість звичних тотемних звірів кенарійської традиції жахіття спотворило хист Джарлаксли до перевтілень, зробивши його хижим і плазуючим. Узявши ім'я Лорд Кобран, він опанував смертоносну зміїну подобу, яку вивільняє в бою. Оточений отруйними девіантними пітонами, з лютою пазуристою правицею, він пильнує свою частину гротів і жорстоко знищує кожного, хто намагається зламати владу жахіття над печерами."}},faq={{q="Ким був Лорд Кобран, перш ніж став злим?",a="Спершу Лорда Кобрана звали Джарлаксла. Він був відомим нічним ельфом-друїдом у Колі Кенарія, якого всі шанували за рідкісний хист і глибоку спорідненість зі звіриними подобами.",al={"справжнє ім'я кобрана","хто такий кобран","джарлакса"}},{q="Чому його звуть Лордом Кобраном?",a="Ставши жертвою кошмару в Печерах Стогонів, Джарлаксла довів до досконалості смертоносну зміїну подобу. Він зрікся колишнього імені й узяв титул Лорда Кобрана, щоб показати свою нову небезпечну силу й владу над зміями.",al={"чому кобран","значення імені лорда кобрана"}},{q="Де знайти Лорда Кобрана?",a="Лорд Кобран живе глибоко в Печерах Стогонів — звивистій підземній мережі в центрі Пусток, серед девіантних пітонів та інших звірів, зіпсованих кошмаром.",al={"місце кобрана","де лорд кобран","кімната кобрана"}},{q="Навіщо шукачам пригод його перемагати?",a="Він один із головних Повелителів Ікла, що очолюють Друїдів Ікла. При ньому Самоцвіт Кобрана, який шукає друїдка Нара Вайлдмейн із Тандер Блафа, щоб зламати владу ватажків Ікла над Пустками.",al={"чому вбивати кобрана","лідери ікла кобран"}},{q="Які в нього незвичайні тілесні риси?",a="На відміну від звичайних нічних ельфів, Кобран помітно вищий і кремезніший, на правій руці має гострий пазур, а в бою може повністю перетворитися на величезну отруйну змію.",al={"як виглядає кобран","вигляд кобрана"}},{q="Що пов'язує його з іншими Друїдами Ікла?",a="Кобран — один із чотирьох головних Повелителів Ікла, разом із Леді Анакондрою та іншими. Усі вони колись були друїдами Кола Кенарія, що увійшли до печер разом із Наралексом і разом піддалися спотворювальній скверні кошмару.",al={"лідери друїдів ікла","кобран і анакондра"}}},fp="12,399,27.496.0,21.465.0,43.193.0,30.242.0,32.184.0,38.209.0,44.186.0,55.218.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="Лорд Елло Ебонлок",s="Лорд Елло Ебонлок — мер Даркшира й голова його ради, що засідає в Ратуші Даркшира. Оточений темрявою та повзучими жахами, він щодня бореться за порядок і захищає обложених містян, хоча зі Стормвінда допомоги майже не надходить.",h="Лорд Елло Ебонлок — мер Даркшира й голова його ради, що засідає в Ратуші Даркшира.",kw={"елло ебонлок","мер","даркшир","ратуша даркшира","сутінколісся","рада даркшира"},ang={["faction:Alliance"]="Лорд Ебонлок уособлює забуті околиці Альянсу, де відрізані від світу мери мусять вести свій народ крізь кошмар без допомоги корони.",["race:Human"]="Для людей, що прибули зі Стормвінда, розмова з Лордом Ебонлоком — тверезе нагадування про те, як глибоко занепали й наскільки покинутими опинилися південні провінції."},sec={{t="Знесилений мер",b="Сидячи в сутінках Ратуші Даркшира, Лорд Елло Ебонлок несе важкий тягар правління поселенням на межі загибелі. Колись Даркшир був частиною квітучого сільського краю, відомого як Велике Селище, а тепер його огорнула вічна тінь і обложили ненажерливі гулі, скелети-потвори та дикі звірі. Елло очолює Раду Даркшира й попри безнадійні обставини намагається підтримувати рештки цивілізованого життя, поки Стормвінд заплющує очі на їхню біду."},{t="Розірване прикордоння",b="Гарнізон Стормвінда відмовляється виділити солдатів для прикордонних земель, тож Даркшир майже повністю покладається на місцеві загони добровольців на кшталт Нічної Варти, якою командує його родичка Алтея Ебонлок. Коли сусідні очільники, як-от Магістрат Соломон із Лейкшира, благають підкріплення проти орків Блекрок, Лорд Ебонлок мусить ухвалювати болісні рішення. Як він стримано пояснює гінцям із Редріджа, Даркшир не може відрядити жодного клинка: щойно варта вийде за межі лісу, власні домівки миттю захоплять навколишні сили зла."},{t="Сліпий до задумів відлюдника",b="Крім патрулювання доріг, Лорд Ебонлок часто покладається на мандрівних шукачів пригод у дивних справах довкола лісу. Щиро прагнучи допомогти всім мешканцям Сутінколісся, він підтримує зв'язок із такими самітниками, як відлюдник Аберкромбі. На жаль, Ебонлок не розуміє справжнього змісту загадкових записок відлюдника, і тому не бачить жахливого зшитого кошмару, що визріває просто за межами міста, — аж доки не стає майже запізно."}},faq={{q="Хто такий Лорд Елло Ебонлок?",a="Лорд Елло Ебонлок — мер Даркшира й голова Ради Даркшира. Зі своєї ратуші він керує обороною, міськими справами й виживанням тих людей Сутінколісся, що ще лишилися.",al={"хто такий елло","мер сутінколісся","лор елло ебонлока"}},{q="Ким йому доводиться Командир Алтея Ебонлок?",a="Командир Алтея Ебонлок, незламна очільниця Нічної Варти, — близька родичка Лорда Елло. Поки він відає міськими й дипломатичними справами Даркшира, вона командує ополченням, що стереже поселення.",al={"алтея ебонлок родичка","чи алтея дочка елло"}},{q="Чому Лорд Ебонлок відмовляється надіслати війська до Лейкшира?",a="Коли Магістрат Соломон просить допомоги проти орків Блекрок у Редріджі, Лорд Ебонлок мусить відмовити. Нежить і чудовиська так насідають на Даркшир, що варто лише забрати з міста вартових — і його захоплять ще до того, як ополчення дійде до краю лісу.",al={"чому немає допомоги редріджу","посланець до сутінколісся","магістрат соломон елло ебонлок"}},{q="Де знайти Лорда Елло Ебонлока?",a="Він у Ратуші Даркшира, що стоїть у центрі Даркшира на сході Сутінколісся.",al={"місце елло ебонлока","де мер ебонлок"}},{q="Чому Стормвінд не надсилає війська на допомогу Лордові Ебонлоку?",a="Після зникнення Короля Варіана Рінна Стормвінд загруз у внутрішніх політичних чварах. Ресурси королівства обмежені, тож Дім Вельмож здебільшого покинув південні краї напризволяще, і місцеві очільники, як-от Лорд Ебонлок, мусять самі організовувати оборону.",al={"чому стормвінд не допомагає сутінколіссю","стормвінд занедбав"}},{q="Яку участь Лорд Ебонлок бере в справі з Аберкромбі?",a="Лорд Ебонлок допомагає підтримувати зв'язок із відлюдником Аберкромбі й домовлятися про переклад дивних записок.",al={"записка аберкромбі елло","переклад записки аберкромбі"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="Лорд Ґрейсон Шедовбрейкер",s="Лорд Ґрейсон Шедовбрейкер — досвідчений паладин-командир Лицарів Срібної Длані, що служить у Соборі Світла в Стормвінді. Його легко впізнати з могутньої статури й відсутнього правого ока; він навчає молодих звитяжців Світла й наглядає за священними, тяжкими випробуваннями, які мають пройти старші паладини, щоб здобути святих скакунів.",h="Лорд Ґрейсон Шедовбрейкер — досвідчений паладин-командир Лицарів Срібної Длані, що служить у Соборі Світла в...",kw={"лорд ґрейсон шедовбрейкер","срібна длань","собор світла","паладин","святий скакун","сколомансія","табір студеного вітру"},ang={["class:Paladin"]="Ґрейсон — один із ваших найвищих духовних наставників в Альянсі: він веде вас у боротьбі з Погибеллю в Лордероні й проводить суворі випробування, потрібні, щоб закликати справжнього скакуна.",["faction:Alliance"]="Незворушний ветеран Срібної Длані, Лорд Ґрейсон допомагає зміцнювати оборону Стормвінда й підтримує експедиції до спірних північних королівств."},sec={{t="Майстер Срібної Длані",b="Лорд Ґрейсон Шедовбрейкер — один із найвидатніших захисників Альянсу, опора ордену в Стормвінді. Досвідчений воїн, що віддав у бою праве око, Ґрейсон не просто навчає новобранців бойової майстерності — він випробовує їхню духовну переконаність. Коли обдаровані лицарі доводять свою готовність, Ґрейсон посилає їх на північ, на спірну передову Західних Чумних Земель, на допомогу Командирові Ашламу Валорфісту в Таборі Студеного Вітру."},{t="Випробування святого скакуна",b="Від паладинів, що прагнуть здобути священного бойового коня, Шедовбрейкер вимагає глибокої жертовності й бездоганної чесноти. Його випробування потребують смиренних вчинків милосердя — як-от допомоги бідакам Айронфорджа через Верховного Жерця Рогана, — а також небезпечних мандрів, щоб вигнати зло з Террордейла й очистити давніх духів у Лютопащі. Вершина випробування — темні глибини Сколомансії, де посвячуваний має зійтися з лицарем смерті Даркрівером і Світлом визволити нечестивого скакуна з неволі."}},faq={{q="Де знайти Лорда Ґрейсона Шедовбрейкера?",a="Лорд Ґрейсон Шедовбрейкер — у Соборі Світла на Соборній Площі Стормвінда. Він стоїть у головних залах і наглядає за паладинами Срібної Длані.",al={"де ґрейсон шедовбрейкер","місце шедовбрейкера","де лорд ґрейсон"}},{q="Яка роль Лорда Ґрейсона для паладинів?",a="Він високопоставлений наставник паладинів Альянсу. Окрім того, що він посилає молодих лицарів на передову боротьби з Погибеллю в Лордероні, він проводить священний ланцюжок завдань, потрібний, щоб викувати святу кінську броню й здобути бойового коня паладина.",al={"що робить ґрейсон","мета ґрейсона шедовбрейкера","навіщо йти до лорда ґрейсона"}},{q="Як Лорд Ґрейсон утратив праве око?",a="Ґрейсон утратив праве око на полі бою за свою довгу службу Альянсу й Орденові Срібної Длані й носить цей шрам як свідчення десятиліть війни.",al={"як ґрейсон втратив око","чому в ґрейсона немає ока","пов'язка ґрейсона"}},{q="Що пов'язує його з Відступниками?",a="Його сестра Джубека загинула, коли Погибель спустошувала Лордерон, і повстала як одна з Відступників. Коли згодом вона розшукала брата, сподіваючись на примирення, Ґрейсон відштовхнув її як нечестиву потвору, затято наполягаючи, що його справжня сестра загинула разом із Лордероном.",al={"сестра ґрейсона","джубека шедовбрейкер","чи є в ґрейсона родина серед нежиті"}},{q="Чому Ґрейсон посилає паладинів до Ґріманда Елмора?",a="Колись Ґріманд Елмор викував броню для власного коня Ґрейсона. Святий бойовий кінь потребує бездоганної роботи, що поєднує тілесну витривалість із духовною гармонією, тож Ґрейсон посилає всіх гідних послушників до Ґріманда по Арканітову Кінську Броню.",al={"ґрейсон і ґріманд елмор","хто робить обладунок для коня паладина","завдання аркани обладунку"}}},fp="26,338,25.479.0,30.494.1,44.193.0,41.263.0,40.179.0,39.260.0,49.261.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="Лорд Джорах Рейвенголдт",s="Лорд Джорах Рейвенголдт — господар Рейвенголдта, елітного братства розбійників і вбивць, що діє з відлюдного маєтку в Горах Альтерак. Він керує таємними операціями ліги, навчає здібних агентів і веде запеклу війну з місцевими бандитами Синдикату.",h="Лорд Джорах Рейвенголдт — господар Рейвенголдта, елітного братства розбійників і вбивць, що діє з відлюдного...",kw={"рейвенголдт","ліга вбивць","розбійники","синдикат","гори альтерак","вбивці"},ang={["class:Rogue"]="Лорд Рейвенголдт — найвизначніший покровитель майстрів-розбійників в Азероті: тим, хто здобуде його довіру, він пропонує елітне навчання, отрути й почесні замовлення."},sec={{t="Володар Ліги Вбивць",b="Лорд Джорах Рейвенголдт очолює Лігу Вбивць зі свого прихованого маєтку серед скель між Альтераком і Гілсбредом. Шляхтич таємничого походження, він відчиняє свої зали для вигнанців, кишенькових злодіїв і вбивць, байдуже, кому ті служать, — аби лише мали виняткову майстерність і шанували його владу. Під його орудою ліга водночас і братство майстрів-злодіїв, і незалежна спілка, що береться за мокрі справи й шпигунство. Рейвенголдт люто ненавидить Синдикат — зграю зганьблених альтерацьких вельмож, що подалися в розбійники, — і раз у раз посилає підлеглих і заїжджих найманців громити їхні табори та грабувати їхнє добро."},{t="Таємниці в тіні",b="Здається, ніби Лорд Рейвенголдт поглинений місцевими сутичками, та його операції сягають усього Азероту. Розбійників, що довели свою вірність, він залучає до заплутаних завдань через увесь континент — здобувати пильно стережені артефакти. Одним із них було повернення таємничої Запечатаної Блакитної Торби, яку в нього викрали й переправили фурболгам в Азшару: щоб її відкрити, знадобилися чари Архімага Ксилема й Лазуровий Ключ, здобутий у Затонулому Храмі. Ще Рейвенголдт наглядає за створенням нових смертельних зілль і розсилає розвідників по всьому світу збирати отруту прадавніх жахіть."}},faq={{q="Хто такий Лорд Джорах Рейвенголдт?",a="Він аристократ і очільник Ліги Вбивць — таємної спілки розбійників зі штабом у Маєтку Рейвенголдт у горах над Передгір'ям Гілсбреда. Він навчає майстрів потайних справ і керує непомітними вбивствами та збиранням відомостей.",al={"хто такий джорах","лідер рейвенголдта","лор джораха"}},{q="Чому Рейвенголдт ненавидить Синдикат?",a="Маєток Рейвенголдт стоїть просто на землях, за які змагається Синдикат — мережа колишніх альтеракських вельмож, що перетворилися на безжальних розбійників. Їхній грубий розбій він вважає заразою, що ширить нагір'ями, і посилає вбивць своєї гільдії вичищати їхні твердині.",al={"чому рейвенголдт ворогує з синдикатом","синдикат ворог","суперництво синдикату"}},{q="Рейвенголдт на боці Альянсу чи Орди?",a="Рейвенголдт — цілком незалежна спілка. Лорд Джорах приймає до свого маєтку розбійників і з Альянсу, і з Орди, бо зважає лише на фахову майстерність, дисципліну скритності й цілковиту розважливість, а не на расову політику.",al={"чи рейвенголдт альянсу","чи джорах з орди","фракція рейвенголдта"}},{q="Що в Запечатаній Блакитній Торбі, яку шукає Джорах?",a="Її вміст — суворо бережена таємниця. Коли Лордові Джораху принесли Лазуровий Ключ, щоб нарешті відімкнути зачаровану торбу, його залило моторошне золоте сяйво: він зазирнув усередину з подивом, а тоді швиденько сховав її.",al={"вміст запечатаної блакитної торби","таємниця блакитної торби","що отримав джорах"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="Лорд Максвелл Тіросус",s="Лорд Максвелл Тіросус — верховний командувач Срібного світанку, що перебуває в передовому редуті ордену, Каплиці Надії Світла у Східних Чумних землях. Ветеран-паладин Срібної Длані з часів Третьої війни, він спрямовує похід коаліції проти Погибелі й керує ударами по сплюндрованих твердинях на кшталт Стратгольма.",h="Лорд Максвелл Тіросус — верховний командувач Срібного світанку, що перебуває в передовому редуті ордену...",kw={"максвелл тіросус","срібний світанок","каплиця надії світла","срібна длань","паладин","стратгольм","погибель"},ang={["class:Paladin"]="Тіросус уособлює незламний дух Срібної Длані: він береже чесноти співчуття, єдності й дисципліни після смерті Утера та трагічного зіпсуття відколотих гілок ордену.",["faction:Alliance"]="Хоч Тіросус і народився шляхтичем Лордерону й став героєм Альянсу, тепер він віддає свої сили незалежному орденові, який приймає кожного, хто готовий битися з Погибеллю.",["faction:Horde"]="На відміну від фанатиків у Гартглені та Багряному Монастирі, Тіросус давно обстоює співпрацю з нелюдьми, тож воїнів і шаманів Орди в Каплиці Надії Світла приймають як рівних."},sec={{t="Ветеран Лордерону",b="Максвелл Тіросус бився пліч-о-пліч з Утером Світлоносцем під час катастрофічної Третьої війни, захищаючи виходи з Андоргала, коли Погибель пронеслася королівством. Після падіння Лордерону він приєднався до Верховного Лорда Александроса Моґрейна в Гартглені, щоб підтримувати опір нежиті. Уже тоді Тіросус обстоював єдність усіх рас і втрутився, коли фанатичні соратники, як-от Бриджит Аббендіс, спробували стратити чужинців — зокрема жерця-троля Забру Гекса. Коли Александроса зрадили, а рештки Срібної Длані виродилися у фанатичний Багряний Хрестовий Похід, Тіросус відмовився йти за ними шляхом ксенофобії, відколовся й допоміг заснувати Срібний світанок."},{t="Командувач Світанку",b="Після смерті лорда Реймонда Джорджа Тіросус очолив Срібний світанок. Він прийняв до ордену Даріона Моґрейна на Мисі Студеного Вітру, а згодом керував укріпленням Каплиці Надії Світла. Під час жорстокої Облоги Сангвіна Тіросус завдав нищівного удару Кіркессену Ревному, назавжди розтрощивши тілесну оболонку ліча. Зі свого командного пункту в каплиці він керує військовими операціями по всіх Чумних Землях, зокрема тактичними штурмами, які очолює Герцог Ніколас Зверенгофф проти Барона Рівендера в руїнах Стратгольма."}},faq={{q="Хто такий Лорд Максвелл Тіросус?",a="Лорд Максвелл Тіросус — бувалий паладин-людина й верховний очільник Срібного світанку. Він бився під проводом Утера Світлоносця й Александроса Моґрейна в Третю війну, а тепер командує обороною Каплиці Надії Світла й керує походом союзу за очищення Чумних Земель.",al={"хто такий максвелл тіросус","лор тіросуса","лідер срібного світанку","бос срібного світанку"}},{q="Чому Тіросус покинув Багряний Хрестовий Похід?",a="Після вбивства Александроса Моґрейна рештки Срібної Длані в Лордероні ставали дедалі радикальнішими й ворожішими до чужинців і винищували всіх, хто не був чистокровною людиною. Тіросус завжди вірив, що здолати Погибель можна лише разом з іншими народами, тож покинув фанатиків і приєднався до Срібного світанку.",al={"чому тіросус покинув багряний хрестовий похід","тіросус багряний хрестовий похід","чи тіросус із багряних"}},{q="Де знайти Максвелла Тіросуса?",a="Він у святилищі Каплиці Надії Світла — укріпленій твердині Срібного світанку на далекому сході Східних Чумних Земель.",al={"місце тіросуса","де максвелл тіросус","карта тіросуса"}},{q="Яка роль Тіросуса у війні за Стратгольм?",a="Тіросус разом із Герцогом Ніколасом Зверенгоффом виробляє загальну воєнну стратегію й доручає перевіреним шукачам пригод і ударним загонам прорватися до полеглого міста Стратгольм і знищити Барона Рівендера — командувача Короля-Ліча в цьому краї.",al={"тіросус стратгольм","тіросус рівендер"}},{q="Чи приймає Тіросус кожного охочого?",a="Тіросус рідко дає аудієнції стороннім: роками він не виходить із воєнних рад, керуючи боротьбою на передовій. Щоб привернути його увагу, шукачам пригод зазвичай треба здобути глибоку повагу Срібного світанку або принести важливі відомості.",al={"чи можна говорити з тіросусом","аудієнція тіросуса"}},{q="Яку роль Тіросус відіграв під час облоги Сангвіна?",a="У тій битві Тіросус зійшовся з Кіркессеном Завзятим, високопоставленим лічем на службі Короля-Ліча. Тіросус завдав вирішального удару, що назавжди позбавив Кіркессена тіла, тож цей чаклун-нежить уже ніколи не зможе знову набути тілесної подоби.",al={"тіросус кіркессен","облога сангвіна"}}},fp="20,330,22.695.0,21.592.0,28.295.0,42.313.0,35.161.0,53.230.0,43.245.0,53.273.0"}
P.entries["npc:lord-pythas"] = {n="Лорд Пайтас",s="Лорд Пайтас, колись воїн із нічних ельфів на ім'я Арін, — один із чотирьох спотворених ватажків Друїдів Ікла в Печерах Стогонів. Він був другом дитинства й присяжним охоронцем верховного друїда Наралекса, але став жертвою жахіття, що отруїло підземну оазу. Тепер він обертає і бойову міць, і спотворену зміїну магію проти кожного, хто намагається дістатися до його сплячого володаря.",h="Лорд Пайтас, колись воїн із нічних ельфів на ім'я Арін, — один із чотирьох спотворених ватажків Друїдів Ікла...",kw={"лорд пайтас","арін","друїди ікла","печери стогонів","наралекс","воїн"},ang={["class:Druid"]="Пайтас уособлює трагічну долю багатообіцяльного послушника, який із відданості прийняв магію природи, — а порча Смарагдового Сну спотворила його науку на гадюче єретицтво.",["class:Warrior"]="Ще до того як стати зміїним сектантом, Пайтас був дисциплінованим воїном із нічних ельфів та особистим охоронцем — похмуре нагадування про те, що сама лише бойова майстерність не вбереже від божевілля.",["race:NightElf"]="Бачити, як шанований захисник на кшталт Аріна підпадає під владу темного божевілля, — гірка скорбота для кожного нічного ельфа, який прагне повернути рівновагу пошрамованим землям Калімдору."},sec={{t="Падіння охоронця",b="Перш ніж узяти собі ім'я Пайтас, цей нічний ельф звався Арін. Досвідчений воїн і вірний товариш Наралекса з дитячих років, він був особистим охоронцем верховного друїда, коли експедиція вирушила в сухі пустища Пусток. Прагнучи краще служити сміливій мрії Наралекса — повернути посушливому краю буяння життя, — Арін узявся вивчати друїдство й виявився надзвичайно здібним учнем. Та тілесна дисципліна й бойова звитяга не вберегли його від підступної порчі, що чатувала глибоко в підземних розколинах."},{t="Смертоносний вартовий",b="Коли зв'язок Наралекса зі Смарагдовим Сном перехопили темні марення, розум Аріна не встояв так само, як і розум його побратимів-послушників. Зрікшись колишнього імені й вірності, він став Лордом Пайтасом, одним із ватажків Друїдів Ікла. Інші зміїні лорди віддають перевагу хитрим чарам чи звіриним подобам, а Пайтас бездоганно поєднує смертоносну бойову майстерність із магією природи. Тепер він никає звивистими тунелями печер, сповнений рішучості захищати спотворену владу жахіття над печерним джерелом."}},faq={{q="Хто такий Лорд Пайтас?",a="Спершу Лорд Пайтас був нічним ельфом-воїном на ім'я Арін. Він був другом дитинства й особистим охоронцем Архідруїда Наралекса й вивчав друїдство, щоб допомагати своєму наставникові в його справі в Пустках.",al={"хто такий пайтас","лор лорда пайтаса","хто був арін"}},{q="Чому він обернувся проти Наралекса?",a="Пайтас не зраджував Наралекса з власної волі. Коли Наралекс спробував черпнути силу Смарагдового Сну, щоб зцілити Пустки, думки архідруїда захопив кошмар. Цей зіпсований сон просочився в розум його послушників, позбавив Аріна глузду й перетворив його на повелителя змій.",al={"чому пайтас став злим","як пайтас збожеволів","чому він став друїдом ікла"}},{q="Чим Пайтас відрізняється від інших ватажків Ікла?",a="На відміну від інших ватажків, що покладаються лише на магію природи й звірині подоби, Пайтас був досвідченим воїном ще до того, як почав учитися друїдства. Він поєднує бойову майстерність із друїдською магією, тож він один із найгрізніших захисників печер.",al={"стиль бою пайтаса","пайтас проти інших лідерів"}},{q="Навіщо шукачам пригод його перемагати?",a="При Пайтасі один із чотирьох зачарованих самоцвітів, потрібних для завдання «Ватажки Ікла». Це завдання дає друїдка Нара Вайлдмейн із Тандер Блафа: їй потрібні самоцвіти всіх чотирьох ватажків Ікла, щоб звільнити Пустки від їхніх спотворених снів.",al={"завдання лідерів ікла","самоцвіт пайтаса"}},{q="Де знайти Лорда Пайтаса?",a="Лорд Пайтас чатує в глибоких внутрішніх залах Печер Стогонів, серед зіпсованих звірів і своїх побратимів-культистів Ікла.",al={"місце пайтаса","де пайтас"}},{q="Що стається з його самоцвітом?",a="Коли його переможено, з його тіла забирають Самоцвіт Пітаса. Шукачі пригод приносять його разом із самоцвітами трьох інших повелителів змій Нарі Вайлдмейн до Тандер Блафа як доказ, що владу ватажків Ікла зламано.",al={"застосування самоцвіту пайтаса","що таке самоцвіт пайтаса"}}},fp="11,387,16.558.0,19.501.0,19.193.0,32.286.0,56.259.0,38.253.0,31.132.0,24.228.0"}
P.entries["npc:lord-serpentis"] = {n="Лорд Серпентіс",s="Лорд Серпентіс — спотворений друїд із нічних ельфів, один із чотирьох ватажків свавільних Друїдів Ікла в Печерах Стогонів. Колись могутній і шанований друїд в ордені Наралекса, він збожеволів, коли сон Наралекса обернувся жахіттям у підземних джерелах. Тепер він допомагає керувати сектою зміїних поклонників глибоко в печерах, де спить зіпсований Наралекс.",h="Лорд Серпентіс — спотворений друїд із нічних ельфів, один із чотирьох ватажків свавільних Друїдів Ікла в...",kw={"лорд серпентіс","друїди ікла","печери стогонів","наралекс","смарагдовий сон","самоцвіт сну"},ang={["class:Druid"]="Серпентіс уособлює трагічну небезпеку, що чатує в Смарагдовому Сні: навіть могутнього друїда можна спотворити, коли шляхетне видіння обертається жахіттям.",["race:NightElf"]="Для нічних ельфів Серпентіс і його послідовники — болюча ганьба: славетні вчені-калдореї, що відкинули священний обов'язок перед природою й стали жахливими зміїними лордами.",["race:Tauren"]="Таурени вбачають у падінні Серпентіса мерзенне осквернення рівноваги Земної Матері, яке загрожує тендітній природі Пусток протиприродним божевіллям."},sec={{t="Від шляхетного друїда до зміїного лорда",b="До того як темрява поглинула печерні джерела, Серпентіс був могутнім і шанованим друїдом — членом шляхетного ордену на чолі з Наралексом, який сподівався за допомогою печерних джерел і Смарагдового Сну зцілити Пустки. Та коли видіння Наралекса обернулося згубним жахіттям, Серпентіс опинився серед тих друїдів, чий розум поглинуло божевілля, що тоді зароджувалося."},{t="Лорд Ікла",b="Цілком піддавшись порчі, що струменіла від спотворених снів Наралекса, Серпентіс і його побратими-друїди стали Друїдами Ікла. Зрікшись споконвічної кенарійської рівноваги й давніх тотемних звірів, вони тепер прагнуть не зцілити Пустки, а переробити їх на подобу власних спотворених снів. Серпентіс править сектою як один із чотирьох її ватажків — разом із Леді Анакондрою, Лордом Кобраном і Лордом Пайтасом."},{t="Остання перепона",b="Лорд Серпентіс засів глибоко у звивистих печерах; він — один із чотирьох ватажків свавільної секти, і кожен із них носить самоцвіт сну. Хто прагне розбудити ув'язненого володаря чи повернути води Оази, мусить здолати Серпентіса й забрати його самоцвіт, зламавши владу змія над лабіринтом."}},faq={{q="Хто такий Лорд Серпентіс?",a="Лорд Серпентіс — один із чотирьох ватажків Друїдів Ікла, що перебуває глибоко в Печерах Стогонів. Колись він був могутнім і шанованим нічним ельфом-друїдом в ордені Наралекса, але разом з іншими друїдами його зіпсував кошмар Наралекса.",al={"хто такий серпентіс","лор лорда серпентіса","минуле серпентіса"}},{q="Чому Серпентіс став злим?",a="Коли спроба Наралекса зцілити Пустки через Смарагдовий Сон обернулася кошмаром, його скверна перекинулася на друїдів, що йшли за ним, і схилила розум Серпентіса до божевілля й поклоніння зміям.",al={"чому серпентіс став злим","скверна серпентіса","чому серпентіс поганий"}},{q="Що пов'язує його з Наралексом?",a="Колись Серпентіс був одним із благородних друїдів, що пішли за Наралексом у печери. Замість допомогти наставникові одужати, він став ватажком Друїдів Ікла, які тепер прагнуть переробити Пустки на подобу своїх спотворених снів.",al={"серпентіс і наралекс","чи серпентіс родич наралекса","учень наралекса"}},{q="Навіщо гравцям його вбивати?",a="Серпентіс — один із чотирьох ватажків Друїдів Ікла. Без його знищення не зламати влади секти над Печерами Стогонів, не здобути його самоцвіт для завдання «Ватажки Ікла» й не прокласти шлях до пробудження Наралекса.",al={"навіщо вбивати серпентіса","лідери ікла серпентіс","самоцвіт серпентіса"}},{q="Хто такі Друїди Ікла?",a="Це відступницька громада нічних ельфів-друїдів, що пішли за Наралексом до Печер Стогонів. Зіпсовані Смарагдовим Жахіттям, вони відмовилися від звичних друїдських подоб і перейняли вигляд, отруту й поведінку змій під проводом Серпентіса та інших Повелителів Ікла.",al={"лор друїдів ікла","хто такі друїди ікла","друїди ікла"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="Лорд Шалзару",s="Лорд Шалзару — деспотичний ватажок наг Гребеня Ненависті, що діють з Острова Жаху біля узбережжя Фераласу. Він править своїми зміїними підданими з безмежною жорстокістю й наглядає за масштабними розкопками серед затонулих і зруйнованих ельфійських поселень. Нещодавно він знайшов дивну давню реліквію, і це привернуло увагу сторонніх дослідників, які прагнуть вирвати її з його рук.",h="Лорд Шалзару — деспотичний ватажок наг Гребеня Ненависті, що діють з Острова Жаху біля узбережжя Фераласу.",kw={"лорд шалзару","наги","злогребені","острів жаху","таємнича реліквія","фералас"},ang={["faction:Alliance"]="Здобувши реліквію Шалзару й знешкодивши воєначальника Гребеня Ненависті, можна вберегти віддалені застави Альянсу на дикому узбережжі Фераласу.",["faction:Horde"]="Розвідники Орди пильно стежать за загрозами на узбережжі Фераласу, і вбивство цього володаря наг усуває непередбачувану небезпеку неподалік сфери інтересів Табору Моджаче.",["race:NightElf"]="Наги Гребеня Ненависті плюндрують руїни прадавнього Калімдору. Відібрати реліквії в Шалзару означає не дати темній спадщині Високородних посилити його зміїних родичів."},sec={{t="Володар Гребеня Ненависті",b="Лорд Шалзару командує нагами Гребеня Ненависті й керує їхніми діями вздовж південного узбережжя Фераласу. Зі свого підземного лігва в печері на Острові Жаху він утверджує владу жорстокістю й безжальною силою. За його наказом Гребеня Ненависті нишпорять руїнами прадавнього Калімдору, шукаючи забуті скарби й могутні реліквії, що лишилися після Розколу."},{t="Таємнича Реліквія",b="Під час розкопок на південь від головних руїн Острова Жаху Шалзару власноруч відкопав дивну давню реліквію. Призначення й сила цього артефакту лишаються загадкою, але те, що він потрапив до рук такого могутнього наги-воєначальника, — очевидна загроза. Посланці на суходолі шукають відважних героїв, які вирушать у зміїне лігво, покладуть край владі Шалзару й заберуть дивну реліквію, перш ніж Гребеня Ненависті обернуть її на темніші цілі."}},faq={{q="Хто такий Лорд Шалзару?",a="Лорд Шалзару — жорстокий володар наг Ненависного Гребеня. Він керує силами наг і розкопками на Острові Жаху біля узбережжя Фераласу.",al={"лор лорда шалзару","шалзару","хто такий шалзару"}},{q="Де знайти Лорда Шалзару?",a="Його лігво — у печері на південь від головних ельфійських руїн на Острові Жаху, за протокою біля південно-західного узбережжя Фераласу.",al={"місце шалзару","де лорд шалзару","печера острова жаху"}},{q="Хто такі наги Ненависного Гребеня?",a="Наги Ненависного Гребеня — вороже плем'я, що захопило узбережжя й острови Фераласу. Під проводом Шалзару вони обшукують стародавні руїни й тероризують прибережні води.",al={"наги ненависного гребеня","плем'я ненависного гребеня"}},{q="Яка реліквія є в Лорда Шалзару?",a="Під час недавніх розкопок на Острові Жаху Шалзару відкопав загадкову стародавню реліквію невідомого походження й сили, тож фракції з материка посилають шукачів пригод, щоб її забрати.",al={"реліквія шалзару","таємнича реліквія фералас"}},{q="Чому треба перемогти Лорда Шалзару?",a="Знищивши Шалзару, шукачі пригод зламають владу Ненависного Гребеня на Острові Жаху й зможуть забрати загадкову реліквію, яку він нещодавно відкопав, перш ніж наги навчаться нею користуватися.",al={"проти лорда шалзару","вбити лорда шалзару"}},{q="Що наги Ненависного Гребеня шукають у Фераласі?",a="Наги Ненависного Гребеня розкопують руїни поселень нічних ельфів, зруйнованих під час Великого Розколу, шукаючи могутніх магічних реліквій і решток історії Високородних, прихованих під землею й хвилями.",al={"розкопки ненависного гребеня","чому наги у фераласі"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Хранитель Знань Рейнтотем",s="Хранитель Знань Рейнтотем — старійшина тауренів, що перебуває на півночі Малгору, одразу на південь від Червоних Скель. Він доглядає священні поховання й просить шукачів пригод прогнати шипогривів Щетиноспинних, які їх тривожать.",h="Хранитель Знань Рейнтотем — старійшина тауренів, що перебуває на півночі Малгору, одразу на південь від...",kw={"хранитель знань рейнтотем","червоні скелі","поховання","щетиноспинні","шипогриви","предки","малгор"},ang={["class:Shaman"]="Пильність Рейнтотема над неспокійними мертвими біля Червоних Скель прямо стосується шаманського обов'язку: дбати, щоб духи предків мали належний спокій і шану.",["race:Tauren"]="Допомогти Рейнтотему захистити Червоні Скелі — означає вшанувати предків і зберегти поховальні традиції вашого народу."},sec={{t="Сторож Червоних Скель",b="Хранитель Знань Рейнтотем, що стоїть біля священних круч Червоних Скель у Малгорі, дбає про духовні обов'язки свого народу. Він просить шукачів пригод прогнати зайд Щетиноспинних із поховань і повернути спокій місцю спочинку предків."},{t="Захисник прабатьківських земель",b="Окрім випробування героїв-початківців, Хранитель Знань Рейнтотем пильнує освячені поховання біля Червоних Скель. Коли зайди з шипогривів Щетиноспинних тривожать святі місця спочинку померлих вождів і шаманів тауренів, Рейнтотем залучає мандрівників, щоб повернути гідність і втихомирити стривожених мертвих."}},faq={{q="Де знайти Хранителя Знань Рейнтотема?",a="Хранитель Знань Рейнтотем стоїть на півночі Малгору, трохи на південь від Червоних Скель, при стежці, що веде до скель предків.",al={"місце рейнтотема","де хранитель знань рейнтотем","знайти рейнтотема в малгорі"}},{q="Чому Рейнтотем просить допомогти з кладовищем?",a="Він просить шукачів пригод прогнати з Червоних Скель загарбників-щетиноспинів: ці шипогриви плюндрують священне тауренське кладовище.",al={"священне поховання рейнтотема","чому допомагати рейнтотему","червоні скелі поховання"}},{q="Чому Рейнтотемові потрібна допомога в Червоних Скелях?",a="Червоні Скелі — священне тауренське кладовище, але шипогриви-щетиноспини, що вдерлися туди, плюндрують могили. Рейнтотем доручає вправним шукачам пригод навести лад на зганьблених землях предків.",al={"проблема червоних скель","чому завдання священного поховання"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="Лорґус Джетт",s="Лорґус Джетт — людина, член культу Молота Присмерку, що діє в затоплених коридорах Чорноглибинних Печер. Блукаючи Руїнами Місячної Святині, він слугує безжальним командиром культу, відданого Древнім Богам. Ватажки Орди визначили його однією з головних цілей, щоб зупинити поширення культу на узбережжі Ашенвалю.",h="Лорґус Джетт — людина, член культу Молота Присмерку, що діє в затоплених коридорах Чорноглибинних Печер.",ang={["class:Shaman"]="Джетт користується стихіями не в гармонії й шанобі, а спотвореними, жорстокими методами, яких навчає Молот Присмерку.",["faction:Horde"]="Убивши Лорґуса Джетта, ви виконаєте нагальне прохання — обезголовити Молот Присмерку, що визріває під узбережжям Ашенвалю.",["race:Human"]="Бачити людину так далеко на заході, на Калімдорі, на службі космічних жахів — моторошне нагадування про те, як далеко сягнула скверна Молота Присмерку."},sec={{t="Осквернитель у руїнах",b="Багато членів Молота Присмерку, що діють у Чорноглибинних Печерах, — орки чи таурени, але Лорґус Джетт вирізняється тим, що він людина, яка опинилася в глибинах давніх руїн нічних ельфів. Блукаючи будь-де між верхніми Руїнами Місячної Святині й печерними тунелями за лігвом мурлока-осквернителя Ґелігаста, Джетт керує темними ритуалами культу та його кривавими задумами."}},faq={{q="Хто такий Лорґус Джетт?",a="Лорґус Джетт — людина, агент культу Молота Присмерку в Чорноглибинних Печерах. Він керує діями культу в Руїнах Місячної Святині й служить Древнім Богам.",al={"лор лорґуса джетта","хто такий лорґус","минуле лорґуса джетта"}},{q="Де знайти Лорґуса Джетта в Чорноглибинних Печерах?",a="Лорґус Джетт ходить різними шляхами по Руїнах Місячної Святині. Його можна зустріти біля перших гуртів культистів Присмерку або далі, у затоплених переходах одразу за святинею Ґелігаста.",al={"місце лорґуса джетта","де лорґус джетт","знайти лорґуса джетта"}},{q="Чому Орда хоче смерті Лорґуса Джетта?",a="Орда прагне його смерті в завданні «Відданість Древнім Богам». Його присутність в Ашенвалі загрожує спокою в краї, адже він належить до підступного союзу, що прагне звільнити стародавні сутності, здатні знищити світ.",al={"чому вбити лорґуса","завдання вірності древнім богам"}},{q="Why does a human use shamanistic powers?",a="The Twilight's Hammer communes directly with chaotic elemental forces and Old Gods rather than traditional ancestral spirits, allowing non-traditional races like humans to wield elemental devastation.",al={"lorgus jett magic","human shaman lorgus"}},{q="What is Lorgus Jett's connection to Gelihast?",a="Both dwell in the Moonshrine Ruins of Blackfathom Deeps, united in their servitude to the dark powers sleeping beneath the sea, with Jett frequently patrolling the corridors beyond Gelihast's altar.",al={"lorgus and gelihast","gelihast connection"}}},fp="11,350,22.373.0,19.179.0,52.199.0,41.223.0,40.200.0,45.198.0"}
P.entries["npc:loslor-rudge"] = {n="Лослор Радж",s="Лослор Радж — заповзятливий дворфійський постачальник інженерного краму на Складі Стілґрила в Дун Мороґу. Він забезпечує механічними деталями, інструментами й боєприпасами майстрів по всіх засніжених гірських хребтах, підтримуючи важливі зв'язки зі зброярами на кшталт Геґнара Рамблшота.",h="Лослор Радж — заповзятливий дворфійський постачальник інженерного краму на Складі Стілґрила в Дун Мороґу.",kw={"лослор радж","постачальник","інженерія","склад стілґрила","геґнар рамблшот","вендиґо","боєприпаси"},ang={["profession:Engineering"]="Лослор тримає важливі початкові ремісничі припаси — флюси, вибуховий порох, трубки й набори майстра, — тож його пост на складі зручна зупинка для будь-якого інженера-початківця, що мандрує Дун Мороґом.",["race:Dwarf"]="Як і в багатьох ремісників Дун Мороґу, заробіток Лослора залежить від надійних в'ючних маршрутів між розкиданими дворфійськими таборами — і це показує, як навіть місцеві хижаки на кшталт вендиґо можуть зірвати гірську торгівлю."},sec={{t="Постачальник у снігах",b="Працюючи зі Складу Стілґрила трохи далі дорогою від Хараноса, Лослор Радж тримає сталий запас інженерних необхідностей — від мідних модуляторів і бронзових трубок до вибухового пороху й гайкових ключів. Сувора погода Дун Мороґу й розлогі майстерські роботи означають, що практичні деталі завжди в попиті, і Лослор пишається тим, що місцевим механікам усього вистачає. Проте пустка між заставами підступна: коли кур'єра, що зрізав шлях біля Сивого Лігва, прогнали вендиґо, важлива партія боєприпасів для його цінного клієнта, зброяра Геґнара Рамблшота, лишилася в снігу."}},faq={{q="Хто такий Лослор Радж?",a="Лослор Радж — дворф-постачальник інженерного приладдя, що тримає крамницю на Складі Стілґрила в Дун Мороґу. Він продає шукачам пригод і ремісникам усього краю інструменти, деталі й набої.",al={"лослор радж","хто такий радж","інженер складу стілґрила"}},{q="З якою бідою Лослорові потрібна допомога?",a="Нещодавно він послав кур'єра з партією набоїв до зброяра Геґнара Рамблшота. Кур'єр пішов навпростець повз Сиве Лігво, натрапив на диких вендіго й утік, покинувши ящик у снігу. Лослорові потрібен хтось, хто поверне вантаж, поки він не втратив цінного клієнта.",al={"набої для рамблшота","чого хоче радж","кур'єр раджа"}},{q="Де Склад Стілґрила?",a="Склад Стілґрила — гамірне дворфійське місце збору й механічна майстерня трохи на схід від Хараноса, при головній дорозі до Лох Модану.",al={"де склад стілґрила","місце стілґрила"}},{q="Хто такий Геґнар Рамблшот?",a="Геґнар Рамблшот — дворф-зброяр, що таборує в Дун Мороґу й залежить від свіжих поставок набоїв і механічних деталей від Лослора Раджа.",al={"хто такий геґнар","рамблшот"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="Лотвіл Веріатус",s="Лотвіл Веріатус — ексцентричний гномський учений, який ставить небезпечні досліди з елементалями серед курних пустирів Пустищ. Він отаборився на схід від Карґата разом із в'їдливим учнем Люсьєном Тоссельвренчем і механічним помічником на ім'я Серво та прагне поєднати таємну теорію, алхімію та інженерію в одну дисципліну.",h="Лотвіл Веріатус — ексцентричний гномський учений, який ставить небезпечні досліди з елементалями серед курних...",kw={"лотвіл","гноми","пустища","елементалі","кайдани","інженерія","алхімія","фам'ретор"},ang={["profession:Engineering"]="Інженери впізнають у Лотвілові прагнення вбудувати механічні гіроскопи й шестерні в таємні поля стримування — а також класичну інженерну пастку: раптову й бурхливу несправність.",["race:Gnome"]="Лотвіл — утілення гномських інтелектуальних амбіцій, доведених до безрозсудних крайнощів: він прагне поєднати інженерію й таємну магію, хоч би якими катастрофічними були ризики."},sec={{t="Єдине поле хаосу",b="Лотвіл, родом із Хараноса в Дун Мороґу, мріє про великий Університет для своєї Просвітленої Асамблеї Арканології, Алхімії та Інженерних Наук. Він переконаний, що ці три дисципліни треба не розвивати поодинці, а гармонійно поєднувати. Заради цієї мрії він обрав суворі Пустища своєю лабораторією: тут він вивчає місцевих кам'яних елементалів і конструює кайдани, здатні підкорити сили стихій. Дослідник він вправний — уже вивчав стихійні механізми й колись здолав конструкти Темного Заліза, — та одержимість метою часто не дає йому побачити, наскільки вибухонебезпечна його польова робота."},{t="Кайдани стихій",b="Головна мета Лотвіла в Пустищах — випробувати свої кайдани стихійного зв'язування. Він доручає шукачам пригод збирати ядра кам'яних елементалів, охолоджувач і гірохронатоми, щоб підготувати складний ритуал і підкорити собі слугу-елементаля. Проте коли пристрій нарешті вмикають, поєднання мінливої магії, непередбачуваної інженерії та нестабільних алхімічних реагентів дає катастрофічний збій: з'являється велетенське розлючене чудовисько-елементаль на ім'я Фам'ретор і кидається на свого творця."}},faq={{q="Хто такий Лотвіл Веріатус?",a="Лотвіл Веріатус — гном-учений, що живе у відлюдному таборі на схід від Карґата в Пустищах. Він один із засновників Просвіченої асамблеї арканології, алхімії та інженерних наук і прагне поєднати всі три галузі в одну науку.",al={"хто такий лотвіл","лор лотвіла веріатуса","гном у пустищах"}},{q="Що Лотвіл робить у Пустищах?",a="Лотвіл прибув до Пустищ вивчати тутешніх диких кам'яних елементалів, яких тут сила-силенна. Відкрита пустеля дає йому і сировину стихій, і досить простору для небезпечних дослідів із підкорення, не наражаючи на небезпеку великі поселення.",al={"чому лотвіл у пустищах","табір лотвіла в пустищах","що робить лотвіл"}},{q="Хто такий Люсьєн Тоссельвренч?",a="Люсьєн Тоссельвренч — багатостраждальний помічник-гном Лотвіла. Цинічний і геть виснажений ексцентричними балачками свого господаря, Люсьєн відає припасами, лагодить механічного слугу Серво й раз у раз застерігає перехожих від небезпечної недбалості Лотвіла.",al={"люсьєн тоссельвренч","помічник лотвіла","учень лотвіла"}},{q="Що стається, коли Лотвіл завершує свій дослід?",a="Лотвіл намагається власноруч виготовленими кайданами підкорення стихій поневолити створіння стихії. Цей гібрид технологій з тріском провалюється: з'являється величезний розлючений кам'яний елементаль на ім'я Фам'ретор, якого треба вбити, поки він не зруйнував табір.",al={"невдалий дослід лотвіла","кайдани стихійного зв'язування","фам'ретор"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="Луціус",s="Луціус — дворф-агент, якого можна знайти біля пристані Лейкширу в Горах Редріджу. Він працює під прикриттям як польовий зв'язковий розвідки Стормвінда, SI:7, і допомагає агентам у спеціальній розвідці та ремеслах.",h="Луціус — дворф-агент, якого можна знайти біля пристані Лейкширу в Горах Редріджу.",kw={"луціус","лейкшир","гори редріджу","si:7","агент","дворф"},ang={["class:Rogue"]="Для розбійників, яких відсилають зі Стормвінда в поле, Луціус — незамінний зв'язковий і наставник, що допомагає відшліфувати навички зламування замків і розвідки.",["race:Dwarf"]="Луціус нагадує, що таланти дворфів сягають далеко за межі кузні й передової — вони знаходять собі місце й у таємних операціях Стормвінда."},sec={{t="Очі в горах",b="Луціус невимушено походжає набережною Лейкширу, але насправді він — таємний агент, безпосередньо пов'язаний із розвідувальною службою Стормвінда, SI:7. Зі свого поста на пристані він стежить за торгівлею, незвичним рухом на дорогах і загрозами, що насуваються на Редрідж. Агентів, яких відсилають зі Стормвінда на схід, скеровують саме до нього: він координує таємні доручення й допомагає відточити практичні польові навички на кшталт зламування замків — аби Корона мала приховані руки далеко за межами Лісу Елвінн."}},faq={{q="Хто такий Луціус?",a="Луціус — дворф-агент у Лейкширі, що працює на SI:7, розвідувальну службу королівства Стормвінд.",al={"особа луціуса","хто дворф на причалі","луціус нпс"}},{q="Що Луціус робить у Лейкширі?",a="Він зв'язковий для таємних агентів у польових умовах: на місці навчає злодійського ремесла й відмикання замків і водночас стежить за всім, що відбувається в Горах Редріджу.",al={"що робить луціус","мета луціуса","чому луціус на причалі"}},{q="Які завдання пов'язані з Луціусом?",a="Луціус — зв'язковий у завданні SI:7 «Зустріч у Редріджі», а ще він посилає молодих розбійників відмикати скрині біля Млина Альтера, щоб здобути Сертифікат Злодійства.",al={"завдання луціуса","завдання зустріч в редріджі","млин альтера"}}},fp="6,244,21.490.0,14.127.0,33.178.0,28.171.0"}
P.entries["npc:lyria-du-lac"] = {n="Лірія Дю Лак",s="Лірія Дю Лак — людська наставниця воїнів у Ґолдширі в Лісі Елвінн. Усамітнившись одразу за сільською кузнею, вона муштрує бійців-новачків і веде молодих воїнів, що починають опановувати свої стійки та зброю.",h="Лірія Дю Лак — людська наставниця воїнів у Ґолдширі в Лісі Елвінн.",kw={"лірія дю лак","воїн","наставниця","ґолдшир","кузня","стійки"},ang={["class:Warrior"]="Для воїнів, щойно прибулих з Абатства Нортшира, Лірія Дю Лак — перша велика наставниця, яку ви зустрічаєте в Лісі Елвінн: вона допомагає відточити володіння стійками й тактику ближнього бою.",["faction:Alliance"]="Розташувавшись за кузнею Ґолдширу, Лірія дбає, щоб тутешні новобранці були здатні боронити серце Стормвінда від розбійників Дефіас і нападників-гнолів."},sec={{t="Наставниця воїнів Ґолдширу",b="Поки корчма «Лев'яча Гордість» у Ґолдширі гуде подорожніми, а коваль гатить по тутешніх виробах, Лірія Дю Лак тримається подвір'я за кузнею. Досвідчена у військовій дисципліні, вона служить Альянсу, навчаючи воїнів-початківців, щойно прибулих з Абатства Нортшира. Вона оцінює їхню готовність і знайомить з особливими бойовими прийомами, дбаючи, щоб ті, хто бере щит і клинок за Стормвінд, могли вистояти проти загроз, що насуваються на Ліс Елвінн."}},faq={{q="Де знайти Лірію Дю Лак?",a="Лірія Дю Лак стоїть надворі просто за кузнею в Ґолдширі, трохи на захід від корчми «Лев'яча Гордість» у Лісі Елвінн.",al={"місце лірії","де лірія","тренер воїнів ґолдшира"}},{q="Які послуги надає Лірія Дю Лак?",a="Вона наставниця воїнів. Вона навчає молодих воїнів найпотрібніших бойових прийомів, основ стійок і бойової дисципліни в міру того, як ті набираються майстерності.",al={"що робить лірія","роль лірії дю лак","чого навчає лірія"}},{q="Які завдання пов'язані з Лірією Дю Лак?",a="Лірія дає воїнам, що зростають, завдання «Вишкіл воїна» й посилає їх до ветерана Гаррі Барлґарда в таверну «Свиня і Свисток» у Старому Місті Стормвінда.",al={"завдання лірії дю лак","завдання воїна ґолдшир"}}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Ма Стоунфілд",s="Ма Стоунфілд — людська матріарх, що живе на Фермі Стоунфілдів у західному Лісі Елвінн. Стоячи просто перед родинною садибою поруч із Тітонькою Берніс, вона дає раду щоденним труднощам сільського життя серед сусідського суперництва й клопоту зі шкідниками.",h="Ма Стоунфілд — людська матріарх, що живе на Фермі Стоунфілдів у західному Лісі Елвінн.",kw={"ма стоунфілд","ферма стоунфілдів","принцеса","свиня","урожай","тітонька берніс"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що досліджують Ліс Елвінн, допомога працьовитим господарям на кшталт Ма Стоунфілд береже сільськогосподарський хребет Стормвінда."},sec={{t="Клопоти садиби",b="Стоячи біля родинної хатини в південно-західному Лісі Елвінн, Ма Стоунфілд наглядає за садибою разом із «Тітонькою» Берніс Стоунфілд. Життя між сусідньою садибою Маклурів і довколишніми гарбузовими ділянками рідко буває мирним. Тутешні дикі вепри постійно загрожують родинним посівам, і жоден із них не дошкуляє так, як Принцеса — величезна призова льоха, сумнозвісна тим, що толочить поля й пожирає тяжко зароблений урожай."}},faq={{q="Хто така Ма Стоунфілд?",a="Ма Стоунфілд — одна зі старших у родині Стоунфілдів, що живе на їхньому хуторі на південному заході Лісу Елвінн разом із родичами, як-от Тітонькою Берніс.",al={"хто така ма стоунфілд","ма стоунфілд","мати стоунфілд"}},{q="Де знайти Ма Стоунфілд?",a="Вона стоїть надворі просто перед головним будинком на Фермі Стоунфілдів, на захід від Ґолдшира в Лісі Елвінн.",al={"місце ма стоунфілд","де ма стоунфілд","ферма стоунфілдів"}},{q="Яку проблему треба розв'язати для Ма Стоунфілд?",a="Ма Стоунфілд шукає шукачів пригод, які покінчили б із Принцесою — величезною призовою свинею, що раз у раз шаленіє на довколишніх полях і пожирає врожай.",al={"завдання ма стоунфілд","завдання принцеси свині","принцеса мусить померти"}}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:mad-magus-tirth"] = {s="Магус Тірт — дивакуватий чарівник-людина, що мешкає на солончаках Перегонів Міражу в Тисячі Голок. Місцеві знають його як розводчика курей і мучителя власного учня, обернутого на курку, але водночас він — знавець грізної тайної науки, що програв цінні томи у ставках на перегонах.",h="Магус Тірт — дивакуватий чарівник-людина, що мешкає на солончаках Перегонів Міражу в Тисячі Голок.",kw={"магус тірт","ритуали сили","перегони міражу","маг","кури","багряний хрестовий похід"},ang={["class:Mage"]="Тірт — важлива постать для магів, які прагнуть глибше збагнути тайну силу, адже саме він написав ключовий трактат «Ритуали Сили»."},sec={{t="Чарівник у пилюці",b="Більшість магів його рівня вивчають науки в бібліотеках Даларана чи Стормвінда, а Магус Тірт оселився серед мастила й ревіння Мерехтливих Низин. Довкола мчать ракетні автомобілі, а Тірт продає перехожим курей і цілими днями гаркає накази на «Плакі» Джонсона — свого нещасного колишнього учня, якого тримає в подобі курки. Попри дивакувату вдачу, Тірт справді володіє тайною магією: він написав езотеричні праці про магічну силу, а тоді втратив їх через безрозсудні ставки на трасі."},{t="Ритуали й борги",b="Серед наукового спадку Тірта — «Ритуали Сили», тайний посібник, якого прагнуть маги-практики. На жаль для охочих чарівників, Тірт більше не володіє власною головною працею. Задавлений боргами за ставки на Перегонах Міражу, маг продав том агентові Багряного Хрестового Походу, щоб покрити програші, тож учням і шукачам знань доводиться вистежувати книгу на ворожій землі."}},faq={{q="Що Магус Тірт робить у пустелі?",a="Тірт живе в Мерехтливих Низинах біля Перегонів Міражу, куди його привабили видовища й азартні ігри. Замість учених занять у великому місті він дивиться перегони гномів і гоблінів, продає курей і потурає своїм вадам.",al={"чому тірт тут","магус тірт мерехтливі низини","місце тірта"}},{q="Що за курка поруч із ним?",a="Ця курка — «Сміливчик» Джонсон, колишній учень Магуса Тірта. Тірт чарами перетворив Джонсона на курку й чималу частину часу знущається з нього, змушуючи танцювати на соляних низинах.",al={"хто така пластівка","пластівка джонсон","курка-учень тірта"}},{q="Що за книга «Ритуали Сили»?",a="«Ритуали Сили» — поглиблений трактат про тайну енергію, написаний Магусом Тіртом. Це важливий текст для магів, які прагнуть удосконалити своє ремесло, але Тірт віддав його, щоб розплатитися з дедалі більшими боргами за перегони.",al={"ритуали сили","книга тірта","книга завдання мага"}},{q="Why is his book difficult to obtain?",a="Tirth no longer has his copy of Rituals of Power. Mages seeking it must follow up on his account of how he parted with the tome.",al={"хто має ритуали сили","борги тірта","книга багряного хрестового походу"}}},fp="11,290,20.541.0,17.418.1,37.236.0,31.207.0,34.214.0,36.128.0"}
P.entries["npc:madame-eva"] = {n="Мадам Єва",s="Мадам Єва — шанована ворожка й матріарх, що живе в Даркширі, посеред темного лісу Сутінколісся. Вона володіє давнім містичним мистецтвом віщування й ворожіння на картах і часто першою з містян відчуває неприродні збурення в лісі. Мандрівники нерідко шукають її, щоб розгадати похмурі таємниці чи роздобути чародійні обереги від темряви, що підкрадається.",h="Мадам Єва — шанована ворожка й матріарх, що живе в Даркширі, посеред темного лісу Сутінколісся.",kw={"мадам єва","ворожка","карти","даркшир","сутінколісся","пророцтво"},ang={["class:Priest"]="Святе Світло втішає живих, але жерцям ворожіння Єви на картах і її робота з рештками духів здасться цікавою, приземленою противагою звичній церковній літургії.",["faction:Alliance"]="Для поборників Альянсу, що ступають у гнітючу тінь Сутінколісся, Мадам Єва — незамінна провідниця, чиї передчуття прорізають смертельну плутанину лісу.",["profession:Tailoring"]="Кравці оцінять знання Єви про химерні ткацькі матеріали, а надто її вміння працювати з примарними нитками, висмикнутими просто з місцевих привидів."},sec={{t="Ворожка Даркшира",b="Тихо живучи серед мороку Даркшира, Мадам Єва ворожить на картах і проводить давні народні обряди, на які багато хто в соборі Стормвінда дивився б із підозрою. У покинутому краї, де лютують дикі звірі, нежить і ще темніші жахи, її моторошні прозріння терплять і шукають — і зневірені містяни, і заїжджі шукачі пригод."},{t="Кровні узи й пророцтва",b="Окрім ворожіння, Мадам Єва цілковито віддана родині: вона бабуся Алісси Еви й маленького Лоґана. Коли карти віщують темні знамення, що загрожують її онуці, Єва без вагань просить перехожих мандрівників обшукати ліс і розкрити давно поховані трагедії, доки історія не повторилася."},{t="Обереги проти ночі",b="Знання Єви не обмежуються картами — вона вміє творити обряди й захисні чари. Від надприродного вбрання, тканого з примарних ниток, до дивних народних реліквій на кшталт Тотема Покари — вона, як мало хто в місті, розуміє химерну сутінкову логіку, що керує неспокійними духами Сутінколісся."}},faq={{q="Хто така Мадам Єва?",a="Мадам Єва — літня ворожка й віщунка з Даркшира. Вона ворожить на картах і вдається до давніх народних ремесел, щоб угледіти невидимі небезпеки, що чатують у Сутінколіссі.",al={"мадам єва","хто така єва","ворожка даркшира"}},{q="Яка роль Мадам Єви в таємниці Сталвана?",a="Мадам Єва розкладає карти й відчуває, що над її онукою Аліссою нависла неминуча надприродна небезпека. Її ворожіння ведуть шукачів пригод до забутих документів і слідів, які розкривають похмуру історію Сталвана Містмантла.",al={"єва сталван","легенда сталвана єва","чому єву цікавить сталван"}},{q="Мадам Єва — відьма чи маг?",a="Єва насамперед віщунка, що володіє давнішими містичними мистецтвами: ворожінням на картах, тканням із духовних ниток і народними опудалами. Її магія ближча до звичайного ворожіння й окультних знань, ніж до впорядкованої тайної науки Даларану чи до Святого Світла.",al={"чи єва відьма","тип магії єви","яку магію використовує єва"}},{q="Хто в Даркширі родич Мадам Єви?",a="Вона бабуся Алісси Еви й Логана Еви. Є в міській Нічній Варті й Вартовий Ева, якого теж вважають членом її родини.",al={"родина єви","онуки мадам єви","аліса бабуся єва"}},{q="Навіщо потрібна Нитка з Примарного Волосся?",a="Мадам Єва збирає ефірні пасма Нитки з Примарного Волосся з неспокійних духів, щоб ткати особливо приготоване обрядове вбрання й забезпечувати потрібним союзників по всьому світу.",al={"нитка примарного волосся","завдання нитки єви"}},{q="Навіщо Мадам Єва виготовляє Тотем Покари?",a="Мадам Єва творить Тотем Покари як темне симпатичне опудало. Коли до нього прив'язують певні частини істот, тотем спрямовує прокляття й шкоду назад на лютих звірів, що тероризують ліс.",al={"тотем покари","тотем єви"}}},fp="10,372,31.351.0,26.353.0,36.319.0,18.177.0,52.237.0,32.252.0,42.149.0,35.178.0,50.201.0"}
P.entries["npc:magatha-grimtotem"] = {n="Маґата Ґрімтотем",s="Маґата Ґрімтотем — матріарх племені Ґрімтотем і Стара Відьма Тандер Блафа. Грізна шаманка й політична інтриганка, вона живе на Узвишші Старійшин і раз у раз кидає виклик баченню Кайрна Бладгуфа щодо майбутнього тауренського народу.",h="Маґата Ґрімтотем — матріарх племені Ґрімтотем і Стара Відьма Тандер Блафа.",kw={"маґата ґрімтотем","стара відьма","ґрімтотем","тандер блаф","узвишшя старійшин","шаманка"},ang={["class:Shaman"]="Маґата, безперечно, одна з наймогутніших шаманок Калімдору: вона повеліває первісними стихіями з такою владою, з якою мало хто з живих тауренів може зрівнятися.",["faction:Horde"]="Маґата надає цінну допомогу й поради проти місцевих загроз, та її запекла відданість кланові й відкрита зневага до інших рас роблять її ненадійною союзницею.",["race:Tauren"]="Кожен таурен знає про темну славу Ґрімтотемів, тож присутність Маґати на Узвишші Старійшин — тривожне нагадування про ідейний розкол, що загрожує вашим об'єднаним племенам.",["race:Undead"]="Мандрівники-Відступники знаходять напрочуд теплий прийом у Старої Відьми, яка постійно радиться з Королівським Аптекарським Товариством у Ставках Видінь."},sec={{t="Матріарх Узвишшя Старійшин",b="Маґата здобула абсолютну владу над Ґрімтотемами через шлюб за домовленістю, після якого її чоловік раптово загинув, зірвавшись зі скелі. Зі своїм почтом і охоронцями вона править з Узвишшя Старійшин як незаперечна політична й духовна провідниця свого відлюдного племені. На відміну від Кайрна Бладгуфа, Маґата проповідує панування тауренів і вважає інші смертні раси зайдами в Калімдорі, яких слід знищити чи відкинути геть."},{t="Дивний союз",b="Попри відкриту зневагу до всіх, хто не є тауреном, Маґата однією з перших обстоювала прийняття Відступників до Орди. Вона запевняє, що таурени можуть навчити нежить духовної рівноваги й допомогти їй повернути людяність. Насправді ж Маґата безпосередньо співпрацює з Королівським Аптекарським Товариством під Тандер Блафом і радиться з такими його членами, як Аптекарка Замах, щодо практичної алхімії й вивчення чародійних реліквій."},{t="Політичні інтриги",b="За маскою мудрої порадниці Маґата наполегливо підточує владу Кайрна й водночас промацує сили можливих загроз. Вона посилає шукачів пригод у найнебезпечніші місця — від розвідки сил трогів у Проваллі Лютого Вогню до полювання на мстивого духа Арікару. Кожне її доручення або зміцнює вплив Ґрімтотемів, або наближає день, коли вона зможе цілком витіснити династію Бладгуфів."}},faq={{q="Хто така Маґата Ґрімтотем?",a="Маґата — стара відьма й матріарх племені Ґрімтотем. Обдарована шаманка з дитинства, вона взяла повну владу над кланом, коли її чоловік загинув, зірвавшись зі скелі. Вона живе на Узвишші Старійшин у Тандер Блафі й є головною політичною суперницею Кайрна Бладгуфа.",al={"минуле маґати","хто стара ворожка","стара ворожка тандер блафф"}},{q="Чому Маґата підтримує Відступників?",a="На словах Маґата вірить, що тауренські традиції й шаманське розуміння можуть повернути Відступникам людяність. Проте багато хто підозрює, що за її дружбою з Королівським Аптекарським Товариством стоїть жадоба таємних алхімічних знань і союзників поза вірним Кайрнові близьким колом.",al={"чому маґата за відступників","маґата й нежить","маґата аптекар замах"}},{q="Які стосунки в Маґати з Кайрном Бладгуфом?",a="Маґата вважає Кайрна м'якотілим, наївним і негідним вести об'єднаних тауренів. Кайрн обстоює співжиття в Орді й мир у Калімдорі, а Маґата переконана, що Ґрімтотеми мають силою повернути землі предків і знищити чужинців.",al={"маґата проти кайрна","чи маґата ненавидить кайрна","кайрн і маґата"}},{q="Що за місія була в Проваллі Лютого Вогню?",a="Маґата послала посланця на ім'я Маур до Провалля Лютого Вогню під Оргріммаром на перемовини з місцевими трогами. Але троги вбили Маура, і Маґата відрядила шукачів пригод Орди в печеру забрати Маурову торбу й на відплату вирізати трогів.",al={"завдання маґати лютий вогонь","чому маґата послала маура","загублена торба маґати"}},{q="Хто така Арікара?",a="Арікара — мстивий дух вітряної змії, що, як кажуть, прагне помсти тауренам. Маґата стверджує, що Арікара жадає помститися саме Кайрнові Бладгуфу, і доручає вправним поборникам викликати чудовисько зачарованою агавою й убити його.",al={"змія помсти","завдання арікари","маґата арікара"}},{q="Де знайти Маґату Ґрімтотем?",a="Маґата живе у великому головному наметі на Узвишші Старійшин у Тандер Блафі, де їй прислуговує слуга Рагауро й стоять двоє незворушних вартових-ґрімтотемів.",al={"місце маґати","де маґата","підвищення старійшин маґата"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:maggran-earthbinder"] = {n="Маґґран Ертбайндер",s="Маґґран Ертбайндер — сивий таурен-ветеран, якого Верховний Вождь Кайрн Бладгуф призначив очолити табір Орди в Притулку Сонячної Скелі. Загартований життям, сповненим жорстоких боїв, він керує обороною скелястих долин Гір Кам'яного Кігтя від ненажерливих звірів і агресивних зграй гарпій. Хоч він утомився від незліченних битв, він лишається непохитним охоронцем поселення.",h="Маґґран Ертбайндер — сивий таурен-ветеран, якого Верховний Вождь Кайрн Бладгуф призначив очолити табір Орди в...",kw={"маґґран ертбайндер","притулок сонячної скелі","таурен","гарпії","бесселет","гори кам'яного кігтя"},ang={["faction:Horde"]="Для мандрівників, що долають круті підйоми Гір Кам'яного Кігтя, Маґґран — головна влада, що керує місцевими патрулями Орди й тримає шляхи постачання вільними від звірів і гарпій.",["race:Tauren"]="Маґґран утілює тяжку ціну, яку війна бере з духу шу'гало, нагадуючи, як конфлікт може загартувати навіть найврівноваженіших дітей Земної Матері."},sec={{t="Прихисток ветерана",b="Маґґрана Ертбайндера послав у Гори Кам'яного Кігтя сам Верховний Вождь Кайрн Бладгуф. Ветеран незліченних сутичок і кривавих походів, Маґґран визнає, що вік і насильство зробили його серце жорстким, позбавивши природної лагідності, властивої його народові. Притулок Сонячної Скелі мав стати і заставою під його твердою рукою, і місцем перепочинку, де теплі вітри й гірське сонце могли б заспокоїти його втомлений боями дух."},{t="Загрози серед скель",b="Навіть у Горах Кам'яного Кігтя Маґґран не знаходить спокою. Як очільник Притулку Сонячної Скелі, він організовує оборону від гарпій Бладф'юрі, що гніздяться на вершинах, і збирає бійців, щоб протистояти хижим небезпекам серед скель. Колись він пережив засідку самої велетенської павучихи Бесселет, тож не має жодних ілюзій щодо смертельно небезпечної дикої природи довкола й часто залучає мандрівників, щоб знищити смертоносних хижаків краю, перш ніж вони заполонять заставу."}},faq={{q="Хто такий Маґґран Ертбайндер?",a="Маґґран Ертбайндер — тауренський старійшина й командир Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Загартований незліченними битвами, він поставлений сюди Кайрном Бладгуфом пильнувати поселення й берегти його шляхи постачання та кордони.",al={"маґґран","хто такий маґґран","керівник притулку сонячної скелі"}},{q="Чому Маґґрана послали до Притулку Сонячної Скелі?",a="Кайрн Бладгуф поставив його очолити Притулок Сонячної Скелі почасти через досвід воєначальника, а почасти — щоб дати йому перепочинок. Ціле життя в боях тяжко виснажило тіло й душу Маґґрана, а тихе гірське сонце дарує йому хоч трохи зцілення.",al={"чому маґґрана послали сюди","минуле маґґрана","кайрн і маґґран"}},{q="З якими загрозами Маґґран просить упоратися шукачів пригод?",a="Маґґран організовує оборону від лютих гарпій Кривавої Люті, що заполонили гори, і посилає воїнів знищити велетенську павучиху-матріарх Бесселет — жахливу хижачку, від якої він сам ледве врятувався колись у мандрах.",al={"завдання маґґрана","чого хоче маґґран","гарпії стоунталон"}},{q="Що сталося між Маґґраном і Бесселет?",a="Колись Маґґрана вкусила велетенська павучиха Бесселет. Хоча йому вдалося відбитися й урятуватися, він посилає вправних шукачів пригод убити чудовисько, щоб ніхто більше не загинув у її тенетах.",al={"маґґран бесселет","завдання про павуків маґґрана","лор арахнофобії"}},{q="Чи має Маґґран вагу в Тандер Блафі?",a="Маґґран служить безпосередньо за велінням Верховного Вождя Тандер Блафа, Кайрна Бладгуфа. Хоч він і перебуває в польових умовах, у Притулку Сонячної Скелі, його влада й накази йдуть просто зі столиці.",al={"маґґран тандер блафф","маґґран кайрн"}},{q="Чи привітний Маґґран Ертбайндер до гравців Альянсу?",a="Ні. Маґґран — непохитний очільник Орди й цілком ворожий до будь-яких шукачів пригод Альянсу, що забредуть до Притулку Сонячної Скелі.",al={"чи маґґран до альянсу дружній","маґґран ворожий"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="Маґіс Спаркмантл",s="Маґіс Спаркмантл — гном, наставник магів, що служить у Ґуральні Тандербрю в Хараносі. Він дає настанови й навчає заклиначів-початківців, які виходять із Долини Холодного Хребта в серце Дун Мороґу.",h="Маґіс Спаркмантл — гном, наставник магів, що служить у Ґуральні Тандербрю в Хараносі.",kw={"маґіс спаркмантл","маг","наставник","гном","ґуральня тандербрю","харанос","бінк"},ang={["class:Mage"]="Для магів Альянсу, що мандрують Дун Мороґом, Спаркмантл — важливий місцевий контакт для навчання заклять і скерування до ширших таємних мереж.",["race:Gnome"]="Гноми, вигнані з Гномреґану, часто покладаються на наставників на кшталт Спаркмантла, щоб їхні наукові й таємні традиції квітли й у житті серед дворфів."},sec={{t="Заклинач у ґуральні",b="Поки дворфи збираються в Ґуральні Тандербрю по ситний ель, Маґіс Спаркмантл забезпечує таємну присутність серед діжок і барил Хараноса. Гноми-маги часто тісно вливаються в життя своїх дворфійських союзників по всьому Дун Мороґу, і Спаркмантл — ключовий наставник для заклиначів-новачків, готових розширити теоретичне й практичне розуміння таємних мистецтв."},{t="Скеровуючи молодих чародіїв",b="Окрім навчання новачків базових заклять, Маґіс дбає, щоб перспективні учні зв'язалися з ширшими магічними колами. Коли маги переростають раннє місцеве навчання чи потребують особливих настанов, Спаркмантл скеровує їх далі — до колег на кшталт Бінк або наставників у головних осередках Альянсу."}},faq={{q="Хто такий Маґіс Спаркмантл?",a="Маґіс Спаркмантл — гном, наставник магів, що живе в Хараносі, у Дун Мороґу. Він навчає заклиначів-новачків основ тайної магії.",al={"маґіс спаркмантл","хто такий маґіс","тренер магів харанос"}},{q="Де знайти Маґіса Спаркмантла?",a="Він у Ґуральні Тандербрю — головній корчмі й місці зборів у містечку Харанос.",al={"місце маґіса","де маґіс","знайти спаркмантла"}},{q="Чому гном-наставник магів живе в дворфійській ґуральні?",a="Після падіння Гномреґана чимало гномів оселилися серед своїх родичів-дворфів у Дун Мороґу. Ґуральня Тандербрю — серце Хараноса, тож це ідеальне місце, щоб наставляти мандрівних заклиначів.",al={"чому в ґуральні","гном у ґуральні","чому ґуральня тандербрю"}},{q="Чи дає Маґіс Спаркмантл якісь завдання?",a="У міру того, як маги зростають, Маґіс спрямовує їх до інших наставників тайної магії — зокрема посилає поговорити з Бінком чи звітувати наставникам у людських землях.",al={"завдання спаркмантла","завдання маґіса"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="Магістрат Генрі Малеб",s="Магістрат Генрі Малеб керує міським управлінням у портовому містечку Саутшор — головному прибережному оплоті Альянсу в Передгір'ї Гілсбреда. Покликаний підтримувати лад серед постійних загроз, він спрямовує більшу частину своєї влади на викриття змовників Синдикату, що мають на прицілі очільників міста.",h="Магістрат Генрі Малеб керує міським управлінням у портовому містечку Саутшор — головному прибережному оплоті...",kw={"магістрат генрі малеб","саутшор","синдикат","убивці","передгір'я гілсбреда","альтерак"},ang={["class:Rogue"]="Розбійники побачать, що Малеба глибоко турбують мистецтва потайності й убивства: він покладається на пильних агентів, щоб перехитрити прихованих убивць Синдикату.",["faction:Alliance"]="Для поборників Альянсу, що прибувають до Гілсбреда, Магістрат Малеб — законна цивільна влада в беззаконному прикордонні: він оголошує нагороди за голови головорізів Синдикату, що розхитують місто."},sec={{t="Охоронець порядку Саутшора",b="З міської ратуші в Саутшорі Магістрат Генрі Малеб здійснює цивільне врядування в одному з останніх справжніх поселень Альянсу в Лордероні. Містечко перебуває в постійній облозі Відступників із півночі й заходу, а передгір'ям нишпорять безжальні грабіжники з великої дороги. Малеб обійняв свою посаду після таємничого вбивства попереднього магістрата, яке він приписує безпосередньо Синдикатові. Сповнений рішучості не повторити його долі, він керує розслідуваннями, щоб викрити прихованих убивць, зруйнувати мережі постачання Синдикату й зірвати маски зі знаті-зрадників, що смикає за ниточки з руїн Альтераку."},{t="Павутиння шляхетної зради",b="Розслідування Малеба щодо Синдикату відкривають запеклий місцевий конфлікт. Убивці, що скрадаються садами за Саутшором, — не прості розбійники, а платні агенти, які беруть замовлення від занепалої альтерацької знаті. Малеб посилає надійних розвідників Альянсу перехоплювати їхні зашифровані плани й усувати ватажків і невпинно працює, щоб зламати владу Синдикату, перш ніж його змови остаточно підірвуть оборону містечка."}},faq={{q="Хто такий Магістрат Генрі Малеб?",a="Він головний міський магістрат Саутшора в Передгір'ї Гілсбреда: стежить за громадським порядком і захищає цей прибережний притулок Альянсу від загроз зсередини.",al={"генрі малеб","магістрат саутшора","хто такий малеб"}},{q="Чому Малеб розслідує справи Синдикату?",a="Малеб посів свою посаду після того, як попереднього магістрата Саутшора вбили. Його розслідування вказує на найманих убивць Синдикату, яких послали занепалі вельможі Альтераку, тож він наймає шукачів пригод Альянсу, щоб запобігти новому замахові на його життя.",al={"чому синдикат","малеб синдикат","вбивці саутшора"}},{q="Де знайти Магістрата Малеба?",a="Він у ратуші Саутшора, на півдні Передгір'я Гілсбреда.",al={"місце малеба","де генрі малеб","знайти магістрата малеба"}},{q="Які загрози Малеб має в Гілсбреді?",a="Окрім постійної загрози від Відступників, що просуваються з півночі й заходу, Малебові загрожують таємничі вбивці Синдикату, що нишпорять околицями міста й замишляють повалити владу Саутшора.",al={"загрози саутшора","вороги малеба"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="Магістрат Севрен",s="Магістрат Севрен — головний управитель поселення Брілл у Галявинах Тірісфалю. Стоячи в ратуші, він організовує ранню оборону Відступників й скеровує прибулих звитяжців зміцнювати землі довкола Андерсіті.",h="Магістрат Севрен — головний управитель поселення Брілл у Галявинах Тірісфалю.",kw={"магістрат севрен","брілл","ратуша","відступники","андерсіті","могили","аґаманди"},ang={["faction:Horde"]="Союзники Орди, прибувши в Тірісфаль, побачать, як Севрен керує передовим упокоренням Галявин Тірісфалю від розбійників, решток Погибелі та бунтівних угруповань.",["race:Undead"]="Для щойно звільнених Відступників, що залишають Похоронний Подзвін, Магістрат Севрен — цивільне обличчя держави Сильвани; він дає вам перші великі доручення на захист батьківщини."},sec={{t="Магістрат Брілла",b="З ратуші Брілла Магістрат Севрен координує цивільну владу й стратегічні зусилля на землях одразу на північ від Андерсіті. Коли нові Відступники виходять у Галявини Тірісфалю, Севрен оцінює місцеві негаразди й висилає шукачів пригод відновлювати лад, убезпечувати зруйноване господарство та придушувати невідступні загрози, що чаяться в довколишніх пагорбах."},{t="Охорона могил",b="Головні турботи Севрена — збереження й повернення мертвих Тірісфалю. Місцеві грабіжники могил, гнилошкірі гноли й свавільна нежить порушують поховання, загрожуючи владі Сильвани Віндраннер, що лише утверджується. Севрен дбає, щоб прабатьківські гробниці — як-от Родинний Склеп Аґамандів — було повернуто, а дезертири чи непокірні сили не підривали владу Відступників в краї."}},faq={{q="Хто такий Магістрат Севрен?",a="Магістрат Севрен — голова управи Брілла, що сидить у ратуші. Він відає землями Відступників у цьому краї й дає завдання шукачам пригод, які прибувають із Похоронного Подзвону на допомогу молодій державі.",al={"магістрат севрен","хто такий севрен","магістрат брилла"}},{q="Де знайти Магістрата Севрена?",a="Він у Ратуші в центрі Брілла, у Галявинах Тірісфалю.",al={"місце севрена","де магістрат севрен","знайти севрена"}},{q="З якими загрозами має справу Магістрат Севрен?",a="Sevren contends with local threats to Tirisfal Glades, including Scourge-aligned Rot Hide gnolls robbing graves, Scourge remnants desecrating local crypts, and rogue undead figures who refuse allegiance to Lady Sylvanas.",al={"завдання севрена","чого хоче севрен","проблеми брилла"}},{q="Кому вірний Магістрат Севрен?",a="Він вірний Відступникам і править Бріллом від імені Леді Сильвани Віндраннер та Андерсіті.",al={"фракція севрена","кому служить севрен"}},{q="Чому Севрен посилає шукачів пригод до родинного склепу?",a="Склепи давнього роду Аґамандів кишать нежиттю й мародерами. Севрен вимагає, щоб шукачі пригод очистили ці місця спочинку предків, аби вороги не могли ними скористатися.",al={"склеп агамонда","завдання склепу севрена"}},{q="Чи пов'язаний Севрен з очільниками Андерсіті?",a="Так. Як місцевий магістрат, він постійно спілкується з агентами й посадовцями з Андерсіті, відправляє посланців і направляє шукачів пригод углиб столиці, щойно ті доведуть свою вправність у Бріллі.",al={"севрен андерсіті","севрен релі"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.220.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {n="Магістрат Соломон",s="Магістрат Соломон — обраний правитель і головний магістрат Лейкшира, що вершить місцеві справи з ратуші. Обложений орками Блекрок і невгамовними кланами гнолів, він днями гарячково благає про воєнну допомогу байдужий і зайнятий іншим Стормвінд.",h="Магістрат Соломон — обраний правитель і головний магістрат Лейкшира, що вершить місцеві справи з ратуші.",kw={"магістрат соломон","лейкшир","гори редріджу","облога","орки блекрок","болвар фордрагон"},ang={["faction:Alliance"]="Політична покинутість Соломона показує глибокі тріщини в Альянсі Стормвінда: віддалені провінції змушені покладатися лише на вільних героїв.",["race:Dwarf"]="Дворфи можуть побачити в історії Соломона трагічний зв'язок зі своїм народом: спроба Айронфорджа відгукнутися на його заклик про допомогу закінчилася засідкою й полоном Принцеси Мойри Бронзбірд.",["race:Human"]="Для людей розмова з Соломоном відкриває, в якому похмурому стані перебуває королівство поза безпечними внутрішніми кордонами Лісу Елвінн."},sec={{t="Місто в облозі",b="Магістрат Соломон править Лейкширом у найтемнішу годину його новітньої історії. Мирне поселення над озером оточене ворогами: пагорбами довкола никають гноли Редріджу й гноли Тіньової Шкури, а з півночі організованими загонами спускаються орки Блекрок. Соломон разом із Маршалом Маррісом підтримує лад і збирає оборону, але місцева варта й ополчення Лейкшира вже на межі сил."},{t="Благання, яких не чують",b="Відчайдушно шукаючи підкріплення, Соломон розіслав гінців по всьому королівству — благати про допомогу Вестфол, Даркшир і саму столицю, Стормвінд. Його прохання принесли лише гірке розчарування. Вестфол стогне під п'ятою Братства Дефіас, Сутінколісся поглинають власні повзучі жахи, а Стормвінд відмовляється посилати війська на східне прикордоння, лишаючи Лейкшир цілком напризволяще."},{t="Відмова двору",b="Коли з'являються докази, що орки Блекрок уклали союз із чорними драконами, Соломон пересилає попередження просто Верховному Лордові Болвару Фордрагону. Попри масштаб загрози, королівська радниця Леді Катрана Престор відкидає благання Соломона як нестямне перебільшення. Скутий її порадами й розпорошеними силами Стормвінда, Болвар відмовляється кинути в бій армію Стормвінда й дає Соломонові лише королівський дозвіл наймати вільних найманців."}},faq={{q="Хто такий Магістрат Соломон?",a="Магістрат Соломон — обраний очільник Лейкшира й головний суддя Суду Лейкшира. Із ратуші він керує місцевими справами й організовує відчайдушну оборону міста від гнолів та орків, що вдерлися в край.",al={"лор магістрата соломона","хто такий соломон","лідер лейкшира"}},{q="Чому Стормвінд не може надіслати йому війська?",a="Військо Стормвінда й так розпорошене по кількох неспокійних краях. Коли Соломон просить допомоги, на Верховного Лорда Болвара Фордрагона сильно впливає королівська радниця Леді Катрана Престор: вона ставить під сумнів донесення Соломона й усіляко відраджує відправляти регулярні королівські війська до Редріджу.",al={"чому немає армії стормвінда","чому стормвінд не допомагає лейкширу","больвар допомога редріджу"}},{q="Чи намагався Айронфордж надіслати допомогу?",a="Так. На прохання Соломона Король Маґні Бронзбірд вислав загін допомоги на чолі з Принцесою Мойрою Бронзбірд. Але експедиція так і не дісталася Редріджу: у Палаючих Степах на неї напали з засідки й узяли в полон.",al={"дворфійські підкріплення лейкшир","допомога айронфорджа редріджу","мойра бронзбірд лейкшир"}},{q="Які загрози непокоять Лейкшир?",a="На Лейкшир тиснуть одночасно гноли Редріджу й Тіньової Шкури, що тероризують пагорби й дороги, і люті орки Блекрок, які роблять набіги на південь із Фортеці Кам'яної Варти й Палаючих Степів.",al={"що нападає на лейкшир","вороги редріджу","чому соломон стурбований"}},{q="Хто разом із Соломоном боронить місто?",a="Соломон здебільшого співпрацює з Маршалом Маррісом, що командує місцевою вартою. Оскільки регулярні підкріплення так і не приходять, обидва очільники мусять залучати мандрівних шукачів пригод і наділяти їх повноваженнями, щоб відкинути загрози.",al={"захисники лейкшира","маршал марріс і соломон"}},{q="Чому Соломон посилає гінців до Даркшира й Вестфолу?",a="Знаючи, що двір Стормвінда зволікає, Соломон намагається укласти угоди про взаємодопомогу із сусідніми поселеннями Альянсу. На жаль, Вестфол скований Братством Дефіас, а Даркшир задихається від нежиті й лютих звірів, тож жодне з них не може виділити бодай одного захисника.",al={"гінці в даркшир","гінці у вестфол","соломон допомога іншим містам"}}},fp="18,281,18.445.0,20.447.0,19.458.1,26.257.0,44.300.1,31.224.1,37.213.0,42.241.0,57.292.0"}
P.entries["npc:magni-bronzebeard"] = {n="Маґні Бронзбірд",s="Маґні Бронзбірд — Володар Айронфорджа, тан клану Бронзбірдів і правитель Каз Модану. Неперевершений коваль і бувалий полководець Другої війни, він веде своє гірське королівство крізь горе й політичну напругу, водночас підтримуючи дворфську археологію по всьому Азероту.",h="Маґні Бронзбірд — Володар Айронфорджа, тан клану Бронзбірдів і правитель Каз Модану.",kw={"маґні бронзбірд","король","айронфордж","хаз модан","ешбрінґер","ліга дослідників","дворфи"},ang={["faction:Alliance"]="Непохитний засновник Великого Альянсу разом із Лордероном і Стормвіндом, Маґні дає коаліції військову міць, інженерну майстерність і незламну вірність.",["profession:Blacksmithing"]="Маґні вважають одним із найвидатніших живих ковалів Азероту: саме він викував легендарний Ешбрінгер із потойбічного кристала біля Великого Ковадла Айронфорджа.",["race:Dwarf"]="Маґні — ваш беззаперечний володар і захисник Каз Модану, який веде клан Бронзбірдів крізь зовнішні війни та внутрішні пошуки земляної спадщини вашого народу.",["race:Gnome"]="Король Маґні відкрив своє місто як прихисток для вцілілих із Гномреґану й підтримує тісну дружбу та технологічний союз із Великим Тінкером Меккаторком."},sec={{t="Володар Гори",b="Найстарший із трьох братів, Маґні змалку добре усвідомлював тягар, що чекав на нього під горою. Коли під час Другої війни вторглася Орда, він утримав Айронфордж за його неприступною брамою, а щойно облогу було знято, вийшов і присягнув Каз Моданом Альянсу Лордерону. У мирні роки, що настали потім, Маґні прийняв у місто гномських союзників після падіння Гномреґану, давши прихисток під горою Великому Тінкеру Ґелбіну Меккаторку та його біженцям. Щоб об'єднати роз'єднані південне й північне королівства, Маґні попросив Меккаторка створити нечуване підземне диво — Глибинний трамвай, що сполучив Айронфордж просто зі Стормвіндом."},{t="Молот Помсти",b="За королівською поставою Маґні ховається глибока особиста трагедія. Під час Третьої війни з Нортренду надійшла звістка, що принц Артас Менетіл зрадив і вбив улюбленого молодшого брата Маґні — Мурадіна. Охоплений горем і гнівом, Маґні взявся за молот біля Великого Ковадла, коли верховний інквізитор Фербенкс та Александрос Моґрейн принесли йому кристал чистого осяйного Світла. Три дні без спочинку дворфський король вкладав у метал усе своє горе, лють і жагу помсти. Виготовлений клинок — Ешбрінгер — став найбільшим шедевром його життя, викуваним, щоб принести погибель Артасу й Погибелі."},{t="Розкопуючи минуле",b="За наказом Маґні дворфське суспільство здебільшого відвернулося від звичного промислового видобутку й зосередилося на розкопках давньої історії. Під враженням від дивних реліквій титанів, знайдених глибоко під землею, Маґні разом зі своїм братом Бранном Бронзбірдом заснував Лігу Дослідників. Нині дворфські розкопки всіяли континенти від Дун Мороґу до Калімдору, прагнучи розгадати таємницю того, як земляни стали сучасними дворфами. Та спокій удома лишається крихким: донька Маґні, принцеса Мойра, зникла — вважають, що її викрав ненависний клан Темного Заліза."}},faq={{q="Хто такий Маґні Бронзбірд?",a="Маґні Бронзбірд — Король Каз Модану, Тан Айронфорджа й вождь клану Бронзбірдів. Він править гірським королівством із Високого Трону в Айронфорджі й є однією з непохитних опор Великого Альянсу.",al={"король айронфорджа","король дворфів","хто такий маґні"}},{q="Хто викував Ешбрінгер?",a="Король Маґні сам викував цей легендарний меч на Великому Ковадлі в Айронфорджі. Александрос Моґрейн і Верховний Інквізитор Фербенкс принесли йому загадковий кристал живого Світла, і Маґні три доби без упину кував клинок, вкладаючи в нього своє горе й лють через звістку про смерть Мурадіна.",al={"чи маґні викував ешбрінгер","творець ешбрінгера","хто створив ешбрінгер"}},{q="Що сталося з братами Маґні?",a="Маґні — найстарший із трьох братів. Його брат Мурадін був посланцем Альянсу в Лордероні; прийшла звістка, що його вбив принц Артас у Нортренді. Наймолодший брат, Бранн, — знаменитий дослідник, що мандрує найвіддаленішими куточками світу й очолює Лігу Дослідників.",al={"мурадін і бранн","брати маґні","доля мурадіна бронзбірда"}},{q="Де Принцеса Мойра?",a="Принцеса Мойра Бронзбірд, єдина дитина Маґні, зникла з Айронфорджа. За офіційними донесеннями в горі, її викрали ворожі дворфи Темного Заліза й тримають у полоні глибоко в Горі Блекрок.",al={"де мойра","дочка маґні","що сталося з мойрою бронзбірд"}},{q="Чому в Айронфорджі живуть гноми?",a="Після навали трогів і жахливого радіоактивного зараження Гномреґана Король Маґні відчинив браму Айронфорджа перед Великим Тінкером Ґелбіном Меккаторком і гномами, що вціліли. Маґні віддав їм цілий район міста, тепер відомий як Містечко Майстрів.",al={"містечко тінкерів","чому гноми в місті дворфів","гномі біженці в айронфорджі"}},{q="Що таке Ліга Дослідників?",a="Ліга Дослідників — археологічна спілка, яку заснували Король Маґні та його брат Бранн. Відкривши стародавні руїни титанів, Маґні спрямував сили дворфійських ремесел на пошуки правди про походження свого народу й розіслав дослідницькі загони по всьому Азероту.",al={"ліга дослідників","дворфи археологи","чому дворфи копають"}}},fp="17,280,20.683.0,21.631.0,19.597.0,25.222.0,26.296.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:magus-rimtori"] = {n="Магус Рімторі",s="Магус Рімторі — свавільна чародійка з ельфів крові, що веде експедицію серед прадавніх руїн Азшари. Відома безжальним підступом, вона ошукала Орду, щоб та провела її через Калімдор, а потім вирізала свій орківський супровід.",h="Магус Рімторі — свавільна чародійка з ельфів крові, що веде експедицію серед прадавніх руїн Азшари.",kw={"магус рімторі","ельфи крові","белґром","талассійський базовий табір","кім'джаель","азшара","зрада"},ang={["class:Mage"]="Рімторі показує, на що здатні талассійські маги у відчайдушній гонитві за тайною силою: вони перериють і руїни Калімдору, і демонічні реліквії.",["faction:Horde"]="Рімторі ошукала Белґрома й вирізала орківську варту, приставлену її супроводжувати, тож її смерть — першочергова справа для воїнів Орди, що прагнуть помститися за полеглих родичів."},sec={{t="Смертельний обман",b="Магус Рімторі привела через море до прадавніх берегів Азшари експедицію шляхетних ельфів крові. Щоб її загін пережив небезпеки Калімдору, вона маніпулювала орком Белґромом — чарувала його й водила за ніс, доки він не погодився дати їй озброєний супровід. Щойно вояки безпечно доправили її на місце, Рімторі показала своє справжнє обличчя: вона обернулася проти захисників і вирізала всю залогу. Розмістивши свої сили в Талассійському Базовому Таборі, вона подалася в дикі прибережні краї з добірними охоронцями шукати забуті магічні артефакти."},{t="Таємниці руїн",b="Справжня мета експедиції Рімторі досі оповита таємницею, хоча безжальні методи принесли їй безліч ворогів. Крім Орди, вона ошукала й місцевих найманців, зокрема гобліна-землеміра Кім'джаеля, який стверджує, що вона була одержима пошуками прадавньої руни. Серед реліквій, що лишилися в її таборі, є й фоліант для викликання демонів, а її гонитва за силою накликала люту відплату Орди, яку вона так безсоромно зрадила."}},faq={{q="Чому Орда хоче смерті Рімторі?",a="Рімторі зачарувала орка Белґрома й маніпулювала ним, щоб той дав її експедиції військовий супровід через Калімдор. А щойно вони безпечно дісталися Азшари, вона зрадила й перебила всіх до одного орків-воїнів під командуванням Белґрома.",al={"чому вбивати рімторі","бельґром рімторі лор","що рімторі зробила орді"}},{q="Де знайти Магуса Рімторі?",a="Поки її експедиція облаштовувала Талассійський Базовий Табір, сама Рімторі блукає нетрями Азшари з особистими охоронцями — ельфами крові, шукаючи стародавні реліквії.",al={"місце рімторі","де магус рімторі","рімторі азшара"}},{q="Що Рімторі шукала в Азшарі?",a="За словами гобліна Кім'джаеля, якого вона найняла, а потім зрадила, Рімторі одержимо полювала на загадкову стародавню руну, а також на інші могутні реліквії, як-от калдорейський фоліант виклику.",al={"чого хоче рімторі","мета рімторі в азшарі","руна рімторі"}},{q="Хто такий Магістр Гокгелм?",a="Магістр Гокгелм — офіцер ельфів крові, якому Магус Рімторі доручила командувати Талассійським Базовим Табором і наглядати за ним, поки вона досліджує довколишні руїни.",al={"хто такий гокгелм","вожак таласійського табору","магістр гокгелм рімторі"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="Май'а",s="Май'а — тролиця з джунглів, наставниця магів у випаленому сонцем басейні Долини Випробувань у Дуроторі. Вона наставляє чародіїв-початківців серед тролів Темного Списа, які приходять у червоні каньйони відточувати владу над таємною магією. Молодим тролям, що ступають на шлях чародійства, вона дає перші настанови й уроки основ магії.",h="Май'а — тролиця з джунглів, наставниця магів у випаленому сонцем басейні Долини Випробувань у Дуроторі.",kw={"май'а","маг","наставниця","тролиця","долина випробувань","магія","дуротар"},ang={["class:Mage"]="Для чародіїв Темного Списа Май'а — початок магічного шляху: вона вчить дисципліни, потрібної, щоб плести вогонь, лід і таємну енергію під суворим сонцем Дуротару.",["race:Troll"]="Май'а дає молоді Темного Списа в Долині Випробувань культурне наставництво в мистецтві, яке рідко практикують їхні союзники-орки."},sec={{t="Наставниця таємної магії Лігва",b="Поки орки переважно віддають перевагу первісному поклику стихій або фізичній перевазі воїна, тролі Темного Списа мають рідкісний хист до вивчення таємної магії. Стоячи в Долині Випробувань, Май'а навчає молодих тролів-магів, що прибувають пройти обряди дорослішання. Вона приймає кандидатів із гліфічними письменами й починає надавати їхній хаотичній сирій силі форму дисциплінованих заклять, щоб вони здобули самовладання, потрібне, аби пережити небезпеки Дуротару."}},faq={{q="Хто така Май'а?",a="Май'а — тролиця Темного Спису, наставниця магів у Долині Випробувань у Дуротарі. Вона дає першу науку, вишкіл і базові заклинання тролям-заклиначам, які щойно прибули, перш ніж ті вирушать у широкі землі Орди.",al={"хто така май'а","лор май'ї","тролиця тренер магів"}},{q="Чому в стартовому краї орків є тролиця — наставниця магів?",a="Відтоді як Темний Спис утік зі свого острова, що поринав у море, й оселився в Дуротарі поруч з орками Тралла, молоді тролі проходять випробування дорослості разом з орківською молоддю. Оскільки орки через колишню демонічну скверну здебільшого цураються тайної магії, тролі-маги на кшталт Май'а самі наставляють своїх.",al={"чому тролиця тут","тролиця-тренер долини випробувань","тролиця-маг дуротар"}},{q="Яку роль вона відіграє в навчанні нових магів?",a="Май'а вітає нових тролів-магів, що приходять із письмовими настановами на кшталт гліфічних пергаментів. Вона розпочинає їхнє справжнє навчання й навчає основ чаклування, щоб вони могли боронити Долину Випробувань від місцевих звірів і лазутчиків-відступників Палаючого Клинка.",al={"що робить май'а","сувій з гліфами май'ї","завдання май'ї"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="Майор Меттінґлі",s="Майор Меттінґлі — досвідчений офіцер армії Стормвінда, що несе службу біля великої брами в Долині Героїв. Під командою Генерала Маркуса Джонатана він допомагає стерегти головний вхід до столиці й радить вправним ремісникам, як захистити героїв від драконів.",h="Майор Меттінґлі — досвідчений офіцер армії Стормвінда, що несе службу біля великої брами в Долині Героїв.",kw={"майор меттінґлі","армія стормвінда","долина героїв","оніксія","драконяча луска","маркус джонатан"},ang={["class:Warrior"]="Дисциплінований ветеран із довгим мечем біля міської брами, Меттінґлі уособлює непохитну рішучість піхотних офіцерів армії Стормвінда.",["faction:Alliance"]="Героям Альянсу, які наважуються кинути виклик великим драконам на кшталт Оніксії, Майор Меттінґлі дає вирішальні настанови, як виготовити захисні плащі з драконячої луски."},sec={{t="Вартовий столичної брами",b="Майор Меттінґлі несе варту в Долині Героїв — він один із високопоставлених офіцерів, які безпосередньо відповідають за головну сухопутну оборону Стормвінда. Сивий ветеран, чиє обличчя позначене тяжко здобутим досвідом, служить під командою Генерала Маркуса Джонатана разом із постійним гарнізоном міста. Окрім щоденних обов'язків — нагляду за патрулями біля брами й за подорожніми, — Меттінґлі має особливі тактичні знання про смертоносну природу драконів. Бувалі шукачі пригод знають його як цінного порадника для тих, хто вчиться виготовляти захисне спорядження з драконячої луски, без якого не вистояти в найнебезпечніших лігвах світу."}},faq={{q="Де знайти Майора Меттінґлі?",a="Майор Меттінґлі стоїть біля входу до Стормвінда в Долині Героїв і несе варту разом з іншими вояками гарнізону одразу за головною брамою.",al={"місце меттінґлі","де майор меттінґлі","знайти майора меттінґлі"}},{q="Яке звання й роль Майора Меттінґлі в Стормвінді?",a="Він офіцер армії Стормвінда під командуванням Генерала Маркуса Джонатана. Він допомагає керувати обороною міської брами й дає шукачам пригод воєнні поради.",al={"хто такий меттінґлі","робота меттінґлі","що робить меттінґлі"}},{q="Чому кожум'яки шукають Майора Меттінґлі?",a="Меттінґлі знає, як обробляти шкуру чорного дракона й шити з неї лускаті плащі, і наставляє вправних ремісників, що хочуть захистити союзників від драконячого полум'я.",al={"плащ з луски оніксії меттінґлі","завдання меттінґлі","подорож лише почалась меттінґлі"}},{q="Чи бере Майор Меттінґлі участь у ширших війнах?",a="Він загартований у боях ветеран королівства Стормвінд, що присвятив себе обороні держави, поки Король Варіан Рінн зник, а королівство бореться із загрозами, що досі не минули.",al={"минуле меттінґлі","лор меттінґлі"}}},fp="15,284,29.642.0,35.165.0,53.173.0,47.173.0,53.187.0"}
P.entries["npc:major-samuelson"] = {n="Майор Семюелсон",s="Майор Семюелсон — високопоставлений офіцер Міської варти Стормвінда, що несе службу в тронній залі Фортеці Стормвінда. Досвідчений військовий командир, він відає важливими кадровими справами, а колись був наставником молодших офіцерів, як-от Лейтенанта Фаррена Орінелля.",h="Майор Семюелсон — високопоставлений офіцер Міської варти Стормвінда, що несе службу в тронній залі Фортеці...",kw={"майор семюелсон","варта стормвінда","фортеця стормвінда","фаррен орінелль","саутшор","офіцер"},ang={["faction:Alliance"]="Майор Семюелсон, що служить у королівській тронній залі, уособлює адміністративний хребет війська Стормвінда: він розподіляє людей по спірних землях на кшталт Гілсбреда."},sec={{t="Опора варти Стормвінда",b="Майор Семюелсон стоїть у Фортеці Стормвінда перед королівським двором і представляє керівництво Міської варти Стормвінда. Він відає призначеннями офіцерів і військовими розпорядженнями по всьому королівству. Зокрема, він був наставником Лейтенанта Фаррена Орінелля — офіцера, що служить далеко на півночі, в Саутшорі в Передгір'ї Гілсбреда. Коли молодші командири в далеких прикордонних гарнізонах не дають ради або просять про переведення, їхні прохання й офіційні рапорти мандрують через усе королівство просто на стіл Майора Семюелсона в столиці."}},faq={{q="Хто такий Майор Семюелсон?",a="Майор Семюелсон — офіцер Міської Варти Стормвінда, що служить у тронній залі Фортеці Стормвінда. Він командир-адміністратор, який відає призначеннями офіцерів і особовим складом.",al={"семюелсон","особа майора семюелсона","хто майор у фортеці"}},{q="Де знайти Майора Семюелсона?",a="Він у Фортеці Стормвінда, у тронній залі, неподалік від юного короля Андуїна Рінна й Верховного Лорда Болвара Фордрагона.",al={"місце семюелсона","де майор семюелсон","знайти семюелсона"}},{q="Що пов'язує його із Саутшором?",a="Майор Семюелсон був наставником Лейтенанта Фаррена Орінелля — офіцера, що служить у Саутшорі в Передгір'ї Гілсбреда. Через Семюелсона Орінелль намагається домогтися переведення з виснажливої північної служби.",al={"семюелсон саутшор","наставник лейтенанта орінелля","семюелсон гілсбрад"}},{q="Навіщо шукачі пригод шукають його?",a="Шукачі пригод, що прибувають із північного фронту в Гілсбреді, приносять Майорові Семюелсону до Фортеці Стормвінда офіційне прохання Лейтенанта Фаррена Орінелля про переведення.",al={"здача завдання в стормвінді","завдання переведення","навіщо говорити з семюелсоном"}}},fp="15,271,29.546.0,23.190.0,35.148.0,37.215.0,32.165.0"}
P.entries["npc:makaba-flathoof"] = {n="Макаба Флетгуф",s="Макаба Флетгуф — таурен, що вцілів у Таборі Апараже в Горах Кам'яного Кігтя. Ставши свідком спустошення своєї домівки й народу від рук клану Ґрімтотем, він шукає відважних героїв Орди, щоб помститися нападникам і вберегти свою родину.",h="Макаба Флетгуф — таурен, що вцілів у Таборі Апараже в Горах Кам'яного Кігтя.",kw={"макаба флетгуф","табір апараже","ґрімтотем","ґрундіґ дарклауд","кая","гори кам'яного кігтя"},ang={["faction:Horde"]="Прохання Макаби про допомогу дають героям Орди змогу довести вірність союзникам-тауренам, покаравши тих, хто вирізає мирні табори.",["race:Tauren"]="Для героїв-тауренів біда Макаби показує гірке віроломство Ґрімтотемів і нагадує, що не всі їхні родичі шанують шлях миру й єдності."},sec={{t="Трагедія Табору Апараже",b="Макаба Флетгуф уособлює трагічну ціну внутрішніх чвар серед тауренів. Його домівка, Табір Апараже в Горах Кам'яного Кігтя, стала жертвою безжального раптового нападу клану Ґрімтотем. Поки багато тауренів прагнуть миру й єдності під проводом Кайрна Бладгуфа, віроломні Ґрімтотеми раз у раз сіють розбрат і насильство, лишаючи таких, як Макаба, без домівки й у жалобі."},{t="Благання про помсту",b="Unable to retake his fallen settlement alone, Makaba calls upon travelers of the Horde to strike back. He directs fierce retaliation against the Grimtotem renegades who overran his home, demanding justice for the slaughter of his kin. His most urgent concerns center on confronting the warlord responsible, Grundig Darkcloud, and finding word of his missing daughter, Kaya."}},faq={{q="Хто такий Макаба Флетгуф?",a="Макаба Флетгуф — таурен-біженець із Табору Апараже в Горах Кам'яного Кігтя. Клан Ґрімтотем захопив і сплюндрував його село, тож він шукає допомоги в шукачів пригод Орди.",al={"макаба","хто такий макаба флетгуф","лор макаби флетгуфа"}},{q="Звідки родом Макаба?",a="Макаба родом із Табору Апараже — невеликого тауренського поселення в Горах Кам'яного Кігтя, на яке напали й яке спустошили Ґрімтотеми.",al={"походження макаби","звідки макаба","табір апараже макаба"}},{q="Хто напав на село Макаби?",a="Табір Апараже сплюндрував клан Ґрімтотем — агресивна й підступна громада тауренів, яку в цих краях очолюють такі ватажки, як Ґрундіґ Дарклауд.",al={"хто напав на табір апараже","вороги макаби","хто розграбував апараже"}},{q="Про що Макаба просить шукачів пригод Орди?",a="Макаба прагне помститися за свою зруйновану домівку: він просить вправних воїнів знищити сили Ґрімтотемів у Таборі Апараже, убити їхнього ватажка Ґрундіґа Дарклауда й з'ясувати, що сталося з Каєю Флетгуф.",al={"завдання макаби","чого просить макаба","доручення макаби"}},{q="Ким Кая доводиться Макабі?",a="Kaya Flathoof is Makaba's daughter who went missing during the attack on Camp Aparaje. Makaba desperately hopes to learn if she survived the assault.",al={"кая флетгуф","хто така кая","кая родичка макаби"}},{q="Чи Макаба родич Діма Флетгуфа?",a="Makaba and Dim share the Flathoof surname, but a family relationship between them is unconfirmed.",al={"дім флетгуф","макаба і дім","рід флетгуф"}}},fp="15,291,23.401.0,20.373.1,23.189.0,27.144.0,30.141.0,46.199.0,22.149.0,34.97.0"}
P.entries["npc:malfurion-stormrage"] = {n="Малфуріон Стормрейдж",s="Малфуріон Стормрейдж — перший смертний друїд і шанований провідник нічних ельфів, що веде їх пліч-о-пліч із Верховною Жрицею Тірандою Віспервінд. Він уславився тим, що здолав Палаючий Легіон і у Війні Прадавніх, і в Третій війні, тож його вшановують як Шан'до — «шанованого вчителя». Нині ж його дух загубився у Смарагдовому Сні, тіло лежить у глибокому заціпенінні, і калдореї лишилися без його живих настанов.",h="Малфуріон Стормрейдж — перший смертний друїд і шанований провідник нічних ельфів, що веде їх пліч-о-пліч із...",kw={"малфуріон","стормрейдж","друїд","нічні ельфи","смарагдовий сон","війна древніх","тіранда"},ang={["class:Druid"]="Усі друїди ведуть свою науку від Малфуріона, який навчався в самого Кенарія. Його відсутність, поки він блукає Смарагдовим Сном, кидає важку тінь на Коло Кенарія.",["class:Priest"]="Малфуріон — коханий супутник Верховної Жриці Тіранди Віспервінд; їхній союз поєднує духовну відданість Елуні зі священною опікою над природою.",["race:NightElf"]="Малфуріона шанують як давнього захисника й рятівника вашого народу, та поки він спить, уся влада лежить на Тіранді й Архідруїді Фандралі Стаґгелмі."},sec={{t="Перший друїд",b="Десять тисяч років тому, ще до того, як Великий Розкол розтрощив прадавній Калімдор, Малфуріон навчався в напівбога Кенарія. Поки королева Азшара та її каста Високородних небезпечно заглиблювалися в чародійну міць Колодязя Вічності, Малфуріон звернувся до первісних сил природи й став першим смертним друїдом Азерота. Його підозри щодо Високородних, на лихо, справдилися: безрозсудне чаклунство Азшари прорвало завісу між світами й прикликало до Азерота Саргераса та Палаючий Легіон. Так спалахнула нищівна Війна Прадавніх."},{t="Рятівник Калімдору",b="Разом із Кенарієм, Тірандою Віспервінд і своїм братом-близнюком Ілліданом Малфуріон очолив опір, що зупинив навалу демонів і закрив портал над Колодязем Вічності. Коли світ розколовся, Малфуріон віддав друїдів служінню Смарагдовому Сну, щоб відновлювати й берегти живе мереживо Азерота. Через десять тисячоліть Тіранда пробудила його від довгого сну в курганах, аби разом протистояти Архімонду в Третій війні. Тоді Малфуріон скликав лісових духів на Горі Гіджал і вдруге розбив Палаючий Легіон."},{t="Загублений у Сні",b="Після Третьої війни Малфуріон знову поринув у сон у Місячному Гаю, щоб єднатися зі Смарагдовим Сном і відновити витрачені сили. Та його дух так і не повернувся до тіла, і друїд застиг у неприродному, схожому на кому заціпенінні. У Дарнасусі повсякденний провід Колом Кенарія перебрав на себе Архідруїд Фандрал Стаґгелм, а Тіранда й сестринство з тривогою виглядають бодай найменшого знаку, що їхній великий Шан'до прокидається."}},faq={{q="Де зараз Малфуріон Стормрейдж?",a="Тіло Малфуріона спить у курганних лігвах Місячного Гаю, а його свідомість ув'язнена глибоко в духовному царстві Смарагдового Сну. Його не можна відвідати в Дарнасусі як звичайного персонажа: його тіло лежить у непробудному сні, і більшості шукачів пригод до нього не дістатися.",al={"де зараз малфуріон","де знайти малфуріона","місце малфуріона","чи малфуріон у грі"}},{q="Чому Малфуріон спить?",a="Друїди час від часу поринають у сплячку в Смарагдовому Сні, щоб єднатися з природою, підтримувати рослинний і тваринний світ і відновлювати духовні сили. Після величезного магічного напруження в битві з Архімондом біля Гори Гіджал Малфуріон увійшов у Сон, щоб відновитися, але неприродна недуга відірвала його дух від тіла.",al={"чому малфуріон спить","чому він у комі","що сталося з малфуріоном"}},{q="Хто править нічними ельфами, поки Малфуріон спить?",a="Верховна Жриця Тіранда Віспервінд править калдорейським народом із Храму Місяця в Дарнасусі, очолюючи Вартових і Сестринство Елуни. А Колом Кенарія й друїдськими справами тим часом відає Архідруїд Фандрал Стаґгелм.",al={"хто править нічними ельфами","хто лідер нічних ельфів","правитель нічних ельфів"}},{q="Що означає «Шан'до»?",a="Дарнаською «Шан'до» означає «шанований учителю». Це титул найвищої пошани, яким звертаються до майстрів-друїдів, насамперед до Малфуріона Стормрейджа, що першим приніс друїдство смертним народам під проводом Кенарія.",al={"значення шан'до","що таке шан'до","шан'до"}},{q="Хто брат Малфуріона?",a="Брат-близнюк Малфуріона — Іллідан Стормрейдж. Хоча юність вони провели разом у Сурамарі, одержимість Іллідана тайною магією й безрозсудна гонитва за демонічною силою під час Війни Прадавніх глибоко розсварили братів, і Малфуріон ув'язнив його на тисячоліття.",al={"брат малфуріона","ілідан для малфуріона","брати стормрейдж"}},{q="Що Малфуріон зробив у битві за Гору Гіджал?",a="У вирішальну мить Третьої війни Малфуріон засурмив у Ріг Кенарія біля Світового Дерева Нордрассил і покликав тисячі духів лісу — вогників. Ці духи обліпили володаря демонів Архімонда й вибухнули, знищивши демона й спопеливши Світове Дерево, щоб урятувати Калімдор.",al={"малфуріон гора хіджал","битва за гору хіджал малфуріон","як малфуріон переміг арчімонда"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="Понівечозуб",s="Понівечозуб — ув'язнений шипогрив із Гостроманів, якого Орда тримає в полоні в Таборі Тауражо. Чекаючи на страту, він виміняє стратегічні відомості про своїх суперників і давні перекази про Аґамаґґана на послуги тих шукачів пригод, які готові виконати його волю.",h="Понівечозуб — ув'язнений шипогрив із Гостроманів, якого Орда тримає в полоні в Таборі Тауражо.",kw={"понівечозуб","шипогриви","гостромани","табір тауражо","аґамаґґан","криваві скалки"},ang={["faction:Horde"]="Вартові Табору Тауражо пильно стережуть Понівечозуба в клітці, проте Орда охоче використовує гірку образу бранця, щоб розгромити твердині шипогривів по всіх Пустках.",["race:Tauren"]="Таурени-мисливці постійно воюють із шипогривами за землі на рівнинах, тож готовність Понівечозуба обернутися проти своїх — цінна, хоч і тривожна, військова перевага."},sec={{t="Бранець у кайданах",b="Понівечозуб — полонений шипогрив із Гостроманів, якого таурени-мисливці та орки-вартові тримають у клітці в Таборі Тауражо в очікуванні страти. Він не змирився зі смертю, а намагається маніпулювати своїми наглядачами й шукачами пригод з Орди, щоб ті розправилися з ворогами його племені: сподівається, що хитрість доведе його цінність або допоможе вибратися на волю."},{t="Зрада зсередини",b="Спершу Понівечозуб намагається заслужити вдячність свого клану, спрямовуючи силу Орди проти суперників — племені Щетиноспинів. Проте невдовзі він розуміє, що ватажки Гостроманів — Нак, Куз і Лок Оркбейн — цілком покинули його гнити в клітці. Розлючений їхньою зрадою, полонений шипогрив обертає помсту проти власних родичів і посилає шукачів пригод стратити своїх колишніх союзників."},{t="Сила Кривавих скалок",b="Понівечозуб добре знає релігійну історію свого народу: велетенські терни по всіх Пустках виросли з пролитої крові Аґамаґґана під час давньої Війни Прадавніх. Збираючи червоні кристалічні Криваві скалки з полеглих Щетиноспинів, Понівечозуб черпає залишкову божественну силу полеглого бога-вепра й дарує тим, хто йому допомагає, могутні давні благословення."}},faq={{q="Хто такий Понівечозуб?",a="Понівечозуб — полонений шипогрив із племені Гостроманів, якого тримають у клітці в Таборі Тауражо. Чекаючи страти від рук Орди, він торгується з шукачами пригод: пропонує поради й стародавні благословення в обмін на знищення своїх суперників.",al={"понівечозуб","хто такий понівечозуб","понівечозуб у клітці таурахо"}},{q="Чому Понівечозуб у клітці?",a="Його схопили під час сутичок Орди з шипогривами на півдні Пусток. Таурени й орки в Таборі Тауражо тримають його в клітці до страти.",al={"чому понівечозуб у полоні","чому в клітці","чому в таурахо в'язень"}},{q="Чому Понівечозуб просить нападати на інших Гостроманів?",a="Понівечозуб зрозумів, що його одноплемінники — Нак, Куз і Лок Оркбейн — залишили його помирати, навіть не спробувавши врятувати. Розлючений цією зрадою, він доручає мандрівникам стратити їх — з чистої злоби.",al={"чому нападати на гостроманів","зрада зсередини лор","чому вбивати нак'куза"}},{q="Що таке Кривавні Уламки?",a="Кривавні Уламки — кристалічні мінерали, що утворилися там, де кров Великого Вепра Прадавнього, Аґамаґґана, просочилася в землю, коли він загинув під час Війни Прадавніх. Їх часто носять при собі шипогриви-щетиноспини.",al={"кривавні уламки","лор кривавних уламків","кров аґамаґґана"}},{q="Що можна зробити з Кривавними Уламками в Понівечозуба?",a="Якщо принести Понівечозубові Кривавні Уламки, він спрямує священну силу Аґамаґґана в тимчасові благословення, що посилюють силу, спритність, витривалість, дух чи швидкість.",al={"бонуси кривавних уламків","здача кривавних уламків","що дає понівечозуб"}},{q="Де, за словами Понівечозуба, загинув Аґамаґґан?",a="Понівечозуб розповідає, що Аґамаґґан поліг у бою під час Війни Прадавніх. З його пролитої крові виросли величезні тернові шпилі, а його велетенський череп лежить на півдні, над печерою-святилищем.",al={"лор аґамаґґана","де загинув аґамаґґан","череп бога вепрів"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="Манкрік",s="Манкрік — убитий горем оркський воїн на Перехресті в Пустках. Після жорстокої засідки шипогривів, що розлучила його з дружиною Олґрою, він присвятив життя помсті за неї й нищенню кожної щетинистої тварюки, яку тільки зможе знайти.",h="Манкрік — убитий горем оркський воїн на Перехресті в Пустках.",kw={"манкрік","олґра","шипогриви","помста","перехрестя","торк"},ang={["faction:Horde"]="Для мандрівників, що прибувають на Перехрестя, біда Манкріка — суворе знайомство з невпинною загрозою щетинистих зграй шипогривів у Пустках.",["race:Orc"]="Манкрік уособлює страшну ціну освоєння диких рубежів Калімдору, де сім'я й честь раз у раз проходять випробування жорстокими загрозами цих земель."},sec={{t="Засідка в пилу",b="Подорожуючи чагарниками Пусток, Манкрік і його дружина Олґра потрапили під навалу шипогривів під час сутички біля невеликого тауренського поселення. У хаосі шаленого бою їх розлучило, і Манкрік бачив, як Олґра зникла під хвилею іклів і зброї, сплетеної з колючок. Охоплений люттю, він бився нестямно, доки не впав непритомний. Вижив він лише тому, що мандрівний тауренський друїд знайшов його, коли той спливав кров'ю біля Золотого Шляху, і перев'язав рани."},{t="Поглинутий помстою",b="Одужуючи на Перехресті, Манкрік опинився в лещатах горя й усепоглинної жаги крові. Хоч місцеві очільники, як-от Торк, застерігають, що сліпа ненависть затьмарює йому розум, і відмовляються збирати офіційні бойові загони, Манкрік не може жити далі, наче нічого не сталося. Не знаючи, що спіткало Олґру, він просить будь-яких охочих мандрівників з Орди прочесати Пустки в пошуках слідів його втраченої дружини й вирізати кожного шипогрива, що трапиться на шляху."}},faq={{q="Хто такий Манкрік?",a="Манкрік — орк-воїн, що живе на Перехресті в Пустках. Він пережив жорстоку засідку шипогривів, через яку розлучився з дружиною, і тепер його поглинає лють і жага помститися за неї.",al={"лор манкріка","хто такий манкрік","історія манкріка"}},{q="Що сталося з дружиною Манкріка?",a="Під час сутички біля тауренського поселення переважні сили шипогривів відрізали Манкріка й Олґру одне від одного. Манкріка в метушні збили з ніг, а Олґра загубилася серед бою.",al={"дружина манкріка","де дружина манкріка","що сталося з олґрою","доля олґри"}},{q="Як Манкрік вижив у битві?",a="Знепритомнівши під навалою шипогривів, Манкрік лежав на Золотому Шляху, де його знайшов мандрівний таурен-друїд: той доглянув його тяжкі рани й відніс у безпечне місце.",al={"як манкрік вижив","хто врятував манкріка"}},{q="Чому Торк відмовляється допомогти Манкрікові?",a="Торк, очільник Перехрестя, вважає, що шалена лють і жага помсти цілком затьмарили Манкрікові розум і не дають йому діяти розважливо.",al={"чому торк не допомагає","торк і манкрік"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {n="Маркус Редпат",s="Маршал Маркус Редпат — найвища військова влада, що захищає містечко Альянсу Саутшор у Передгір'ї Гілсбреда. Він служить містечку ще з часів до Другої війни, а нині організовує патрулі й оголошує нагороди, щоб стримувати огрів, мурлоків і наг довкола. Його провід конче потрібен, щоб утримати останній південний оплот Лордерону на узбережжі.",h="Маршал Маркус Редпат — найвища військова влада, що захищає містечко Альянсу Саутшор у Передгір'ї Гілсбреда.",kw={"маркус редпат","маршал редпат","саутшор","передгір'я гілсбреда","андуїн лотар","огри","наги"},ang={["faction:Alliance"]="Маршал Редпат дає поборникам Альянсу важливі доручення, щоб убезпечити Гілсбред від огрів і прибережних небезпек.",["race:Human"]="Редпат — живий зв'язок із першими днями Великого Альянсу: саме він зустрів Андуїна Лотара й біженців зі Стормвінда, коли ті вперше втекли на північ."},sec={{t="Вартовий Саутшора",b="Служба Маркуса Редпата Саутшорові триває десятиліттями. Багато років тому, ще до того як Друга війна охопила північ, він був сільським старостою, що зустрів лорда Андуїна Лотара, юного мага Хадґара й тисячі виснажених біженців, які тікали від сплюндрованого Стормвінда. Усвідомивши всю вагу їхнього становища, він відрядив свого найпрудкішого гінця на північ попередити короля Теренаса Менетіла II — і тим відіграв ранню роль у створенні Великого Альянсу Лордерону. Крізь падіння столиці й нищівне вторгнення Погибелі Редпат лишався на своєму посту, перейшовши від цивільного управителя до військового маршала, щоб берегти обложених уцілілих порту."},{t="Утримати узбережжя",b="Після Третьої війни Саутшор стоїть майже сам проти ворожих сил, що тиснуть з усіх боків. Маршал Редпат керує обороною по всьому Передгір'ю Гілсбреда, залучаючи досвідчених шукачів пригод, щоб відкинути огрів Трощихребтів, які спускаються з Альтераку, і знищити небезпечні табори наг і мурлоків уздовж узбережжя. Поки Відступники займають північ, а неподалік стоїть сильно укріплений Таррен Мілл, пильність Редпата — одна з небагатьох перепон, що не дають присутності Альянсу в краї остаточно розвалитися."}},faq={{q="Хто такий Маркус Редпат?",a="Маркус Редпат — маршал і воєначальник Саутшора в Передгір'ї Гілсбреда. Під час Другої війни він був старостою міста, а тепер керує місцевою обороною від загроз із диких країв і ворожих сусідів.",al={"лор маркуса редпата","хто маршал у саутшорі","про маркуса редпата"}},{q="Яку роль він відіграв у Другій війні?",a="Коли королівство Стормвінд упало під натиском Орківської Орди, біженці на чолі з Андуїном Лотаром і Хадґаром висадилися в Саутшорі. Редпат зустрів їх на березі й одразу послав свого вершника Віллема сповістити Короля Теренаса Менетіла Другого в Столиці.",al={"маркус у другій війні","чи маркус зустрічав лотара"}},{q="Із якими загрозами він бореться передусім?",a="Редпат організовує військові дії проти місцевих хижаків і загарбників, що підбираються до Саутшора. Він оголошує винагороди й дає доручення проти огрів-трощихребтів у передгір'ях Альтераку, прибережних мурлоків і наг-грабіжників.",al={"завдання маркуса редпата","кого вбивати за редпатом"}},{q="Чи він родич Редпатів із Дарроушира?",a="У нього те саме прізвище Редпат, яке прославив Капітан Джозеф Редпат із Дарроушира в Східних Чумних Землях, але жодної прямої спорідненості, крім спільного коріння в королівстві Лордерон, офіційно не встановлено.",al={"рід редпат","чи маркус родич джозефа редпата","родичі редпата"}},{q="Де знайти Маркуса Редпата?",a="Маршал Редпат стоїть у центрі Саутшора — притулку Альянсу на південному узбережжі Передгір'я Гілсбреда.",al={"де маркус редпат","місце маркуса редпата"}}},fp="14,364,24.648.0,17.550.0,22.246.0,40.247.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="Мардант Стронґоук",s="Мардант Стронґоук — наставник друїдів, нічний ельф, що мешкає в Алдрассилі в серці Тельдрассила. Він веде молодих друїдів у єднанні з духами природи й знайомить їх із таємницями Смарагдового Сну.",h="Мардант Стронґоук — наставник друїдів, нічний ельф, що мешкає в Алдрассилі в серці Тельдрассила.",kw={"мардант стронґоук","друїд","наставник","алдрассил","тельдрассил","смарагдовий сон","духи природи"},ang={["class:Druid"]="Для молодих друїдів — нічних ельфів Мардант Стронґоук — перший міст між буденним життям і священними обов'язками Кола Кенарія.",["race:NightElf"]="Перебуваючи в осерді Алдрассила, Мардант уособлює калдорейську відданість злагоді зі зростаючим живим світом Тельдрассила."},sec={{t="Учитель дикого краю",b="У вітті Алдрассила молоді нічні ельфи, що відчувають поклик дикої природи, звертаються до Марданта Стронґоука. Його головна справа — навчати новачків відкривати чуття духам природи, тлумачити їхнє бурмотіння й спрямовувати відновлювальну магію. Для тих, хто робить перші кроки як захисники дикого краю, він часто перший майстер, що відкриває неосяжну складність і прадавні небезпеки Смарагдового Сну."}},faq={{q="Хто такий Мардант Стронґоук?",a="Мардант Стронґоук — нічний ельф, наставник друїдів у Тінедолі, в Алдрассилі. Він навчає щойно пробуджених друїдів Тельдрассила основ спілкування з природою й чаклування.",al={"лор марданта стронґоука","хто такий мардант","мардант алдрассіл"}},{q="Чого він навчає нових друїдів?",a="Він навчає послушників розуміти послання диких духів, творити найпростіші заклинання на кшталт Місячного Вогню й цілющих чарів і пізнавати природу Смарагдового Сну.",al={"чого навчає мардант","вміння марданта","тренер друїдів тінеділ"}},{q="Де знайти Марданта Стронґоука?",a="Він в Алдрассилі чи поруч із ним, у Тінедолі — стартовій долині нічних ельфів-шукачів пригод на Тельдрассилі.",al={"місце марданта","де мардант стронґоук"}},{q="Що таке Зелений Сигіл?",a="Зелений Сигіл — знак-настанова, який дають молодим нічним ельфам-друїдам у Тінедолі, щоб вони розшукали Марданта Стронґоука для першого навчання.",al={"завдання зеленого сигіла","сигіл для марданта"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="Марек Айронгарт",s="Марек Айронгарт — бувалий дворфійський мисливець із Хутора Далекоходів у південно-східному Лох Модані. Відданий звичаям дикої природи, він випробовує мандрівників і стрільців, перш ніж прийняти їх до лав шанованих мисливців хутора.",h="Марек Айронгарт — бувалий дворфійський мисливець із Хутора Далекоходів у південно-східному Лох Модані.",kw={"марек айронгарт","хутір далекоходів","мисливець","лох модан","полювання","дворфи"},ang={["class:Hunter"]="Для слідопитів і мисливців на звіра Марек Айронгарт уособлює суворі традиції Хутора Далекоходів: він кидає мисливцям виклик довести свою влучність і вміння читати сліди в полюванні на місцеву звірину.",["race:Dwarf"]="Марек — приклад тієї культури життя на природі, яку шанують чимало дворфів Каз Модану: тиху варту в горах він обрав замість гамірних кузень Айронфорджа."},sec={{t="Майстер полювання",b="Хутір Далекоходів, що стоїть на мальовничому кряжі над озером, — застава найкращих стрільців і слідопитів дворфійських земель. Марек Айронгарт — живе втілення цього порубіжного духу. Його не вражають ні титули, ні балачки: кожен, хто хоче здобути повагу хутора, мусить на ділі показати свою вправність у полюванні на різноманітних звірів Лох Модану й довести, що має терпіння й витримку справжнього мисливця дикої місцини."}},faq={{q="Хто такий Марек Айронгарт?",a="Марек Айронгарт — дворф-мисливець, що живе на Хуторі Далекоходів у Лох Модані. Він випробовує тих, хто прагне визнання серед тутешньої громади слідопитів і знавців дикої природи.",al={"марек айронгарт","хто такий марек"}},{q="Де знайти Марека Айронгарта?",a="Він на Хуторі Далекоходів, що сховався серед пагорбів на південно-східному березі Лох Модану.",al={"місце марека айронгарта","де марек"}},{q="Які доручення дає Марек?",a="Марек посилає мисливців вистежувати й проріджувати різних тварин довкола озера, перевіряючи їхні навички виживання в сутичках із небезпечними кроколісками.",al={"завдання марека айронгарта","завдання марека"}},{q="Чи Марек родич інших відомих дворфів?",a="Він носить відоме дворфійське прізвище, тож може бути родичем Археолога Адаманта Айронгарта й Імме Айронгарт, хоча Марек присвятив життя полюванню, а не розкопкам реліквій.",al={"рід айронгарт","родичі марека"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="Маріса дю'Пейдж",s="Маріса дю'Пейдж — рідкісна людська чаклунка-ізгойка, що ховається в розгалуженій мережі печер біля входу до Мертвих Копалень на південному заході Вестфолу. Вона на боці розбійників, які діють під Мунбруком, і володіє арканною магією поруч із робітниками й грабіжниками, що стережуть тунелі.",h="Маріса дю'Пейдж — рідкісна людська чаклунка-ізгойка, що ховається в розгалуженій мережі печер біля входу до...",kw={"маріса дю'пейдж","мертві копальні","мунбрук","маг","розбійники","вестфол"},ang={["class:Mage"]="Маріса дю'Пейдж нагадує, що арканна наука в королівстві не обмежується вежами Кірін-Тору чи святилищем чародіїв Стормвінда: чаклуни-ізгої охоче продають свій хист злочинним мережам.",["faction:Alliance"]="Шукачам пригод з Альянсу, що розвідують тунелі під Мунбруком, варто пильнувати дю'Пейдж: несподівана чаклунка серед юрми злодюжок може швидко перетворити сутичку на смертельну."},sec={{t="Арканний хист у тунелях",b="Глибоко у звивистих печерах, що ведуть до Мертвих Копалень під Мунбруком, більшість захисників — грубі злодюжки, шахтарі-бунтарі й головорізи. Маріса дю'Пейдж вирізняється серед них як вправна людська чарівниця. Більшість чарівників королівства навчаються в дозволених залах Кварталу магів Стормвінда або служать Кірін-Тору, а дю'Пейдж пов'язала свою долю з розбійниками й грабіжниками, що ховаються в підземних глибинах Вестфолу."}},faq={{q="Хто така Маріса дю'Пейдж?",a="Маріса дю'Пейдж — рідкісна людина-магиня, що ховається в зовнішніх печерах на підступах до Мертвих Копалень. На відміну від звичайних злодіїв і робітників, що патрулюють ці ходи, вона боронить підземну мережу тайними заклинаннями.",al={"маріса дюпейдж","хто така маріса","рідкісна в мертвих копальнях"}},{q="Де її знайти?",a="Вона зрідка з'являється в загальнодоступних печерах під Мунбруком у Вестфолі, у тунелях просто перед порогом порталу до підземелля Мертві Копальні.",al={"місце маріси дюпейдж","де маріса","поява маріси"}},{q="Чому людина-магиня ховається в печерах Мертвих Копалень?",a="Не всі, хто володіє тайною магією, лишаються вірними високим вежам Стормвінда. Дезертири, відступники й співчутливі простолюдини стікаються до справи розбійників по всьому Вестфолу, і додають до їхніх укріплень під Мунбруком і сталь, і чари.",al={"чому вона тут","лор маріси","фракція маріси дюпейдж"}}},fp="15,299,28.436.0,23.241.0,23.162.0,50.248.0"}
P.entries["npc:marleth-barleybrew"] = {n="Марлет Барліб'ю",s="Марлет Барліб'ю — амбітна дворфійська броварка, що працює в Селі Брюнолл. Роздратована пануванням клану Тандербрю на місцевому пивному ринку, вона невпинно плете плани, щоб довести: вариво її родини краще за уславлений Громовий Ель Хараноса.",h="Марлет Барліб'ю — амбітна дворфійська броварка, що працює в Селі Брюнолл.",kw={"марлет барліб'ю","броварка","село брюнолл","барліброю","тандербрю","громовий ель","суперництво"},ang={["race:Dwarf"]="Для дворфів броварство — мистецтво, тісно пов'язане з престижем клану, тож ворожнеча Марлет із Тандербрю — справа запеклої родинної гордості."},sec={{t="Броварське суперництво",b="У Дун Мороґу до хмільного ставляться так само серйозно, як до сталі, а суперництво між родинами Барліброю й Тандербрю — легендарне. Марлет Барліб'ю обурює майже цілковита монополія, яку Раґнар Тандербрю та його рідня тримають із Ґуральні Тандербрю в Хараносі. Переконана, що її власне ремесло нітрохи не гірше, вона шукає хитрих способів передати барила Барліброю до рук корчемних відвідувачів. Замість відкритого конфлікту вона обирає дрібний підступ, наймаючи подорожніх, щоб ті потай підмінили цінні діжки елю Хараноса на її власні."}},faq={{q="Хто така Марлет Барліб'ю?",a="Марлет — дворфійка-пивоварка, що живе в Селі Брюнолл на заході Дун Мороґу. Вона представляє родину Барліб'ю й завзято намагається похитнути владу суперників-Тандербрю над місцевими шинками.",al={"хто така марлет","лор марлет","марлет барліб'ю"}},{q="Де знайти Марлет Барліб'ю?",a="Вона в Селі Брюнолл, на заході Дун Мороґу, неподалік від Озера Крижаного Потоку.",al={"місце марлет","де марлет","знайти марлет"}},{q="Навіщо Марлет хоче підмінити пиво Тандербрю?",a="Марлет вважає, що ель її родини не гірший, а то й кращий за Громовий Ель. Оскільки Тандербрю панують у торгівлі в Хараносі, вона наймає шукачів пригод, щоб ті потай замінили барильця в таверні на пиво Барліб'ю й відвідувачі скуштували її товар, а заодно принесли їй зразок Громового Елю для аналізу.",al={"чому підмінити пиво","причина завдання гірких суперників","чому ненавидіти тандербрю"}},{q="Хто ще належить до родини Барліб'ю?",a="До її великого роду належать інші знані пивовари й торговці — Малґін, Реджолд, Велларт і Йорус Барліброу, — і всі вони віддані ремеслу традиційного дворфійського пивоваріння.",al={"рід барліб'ю","родичі марлет"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Маррік Нуррібіт",s="Маррік Нуррібіт — гном, наставник магів, що служить в Анвілмарі в Долині Холодного Хребта. Трохи більше прихильний до місцевого пива, ніж до суворої педагогіки, він знайомить гномських чародіїв-початківців з їхнім ремеслом, раз у раз випрошуючи зайву монету на випивку.",h="Маррік Нуррібіт — гном, наставник магів, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"маррік нуррібіт","маг","наставник","гном","анвілмар","ель","гліфічний меморандум"},ang={["class:Mage"]="Для гномів-магів-початківців, що розпочинають шлях у Долині Холодного Хребта, Маррік — перший учитель, до якого ви звертаєтеся по основні закляття й ваш Гліфічний Меморандум.",["race:Gnome"]="Біженці, що знайшли прихисток у Дун Мороґу, знають Марріка як приклад гномського вченого, який надто вже добре пристосувався до дворфійської корчемної гостинності."},sec={{t="Таємні студії та ель",b="У теплі біля вогнища Анвілмара Маррік Нуррібіт дає таємні настанови молодим гномам, що роблять найперші кроки в магії. Хоч він і знається на таємних мистецтвах, поводиться він украй невимушено — часто здається, що його куди більше цікавить кухоль дворфійського елю й випрошування дрібних грошей у нових учнів, ніж муштра зі складними теоремами. Попри свої вади, Маррік гостро усвідомлює небезпеки за межами Долини Холодного Хребта й регулярно застерігає майбутніх заклиначів щодо радіоактивних і кишачих трогами жахіть полеглого Гномреґану."}},faq={{q="Хто такий Маррік Нуррібіт?",a="Маррік Нуррібіт — гном, наставник магів в Анвілмарі в Долині Холодного Хребта, що в Дун Мороґу. Він навчає новоприбулих гномів-магів основ тайної магії.",al={"маррік нуррібіт","хто такий маррік","тренер магів ковадлограду"}},{q="Чому Маррік постійно просить грошей на пиво?",a="Маррік відомий тим, що місцеві трунки любить куди більше, ніж сувору професійну пристойність. Він раз у раз випрошує в учнів дрібняки, щоб оплатити свою звичку до таверни.",al={"маррік п'є","маррік пиво","чому він просить монети"}},{q="Що Маррік каже про Гномреґан?",a="Попри легковажне ставлення до навчання, Маррік добре розуміє, що таке справжня небезпека, і не раз застерігає молодих магів не недооцінювати загроз, які чатують у заражених руїнах Гномреґана.",al={"маррік гномреґан","попередження про гномреґан"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="Маршал Дуґан",s="Маршал Дуґан — командир загону армії Стормвінда, розквартированого в Ґолдширі. Йому доручено захищати серце Лісу Елвінн, та його місцевий гарнізон розтягнутий до краю перед дедалі більшими вторгненнями кобольдів, гнолів і розбійників. Щоб убезпечити містечко на перехресті й навколишні ферми, він чимало покладається на вільних шукачів пригод.",h="Маршал Дуґан — командир загону армії Стормвінда, розквартированого в Ґолдширі.",kw={"маршал дуґан","маршал","ґолдшир","армія стормвінда","кобольди","гноли","ліс елвінн"},ang={["class:Warrior"]="Для бійців Дуґан утілює звичну дисципліну й логістичне напруження піхоти Стормвінда, що тримає лінію оборони попри нерівні сили.",["faction:Alliance"]="Маршал Дуґан — передова адміністративна влада Альянсу в Елвінні: він дає новоприбулим новобранцям перші військові доручення від імені Стормвінда."},sec={{t="Командир Перехрестя",b="Маршал Дуґан, що стоїть на видноті в Ґолдширі біля корчми «Лев'яча Гордість», несе важкий тягар: тримати Ліс Елвінн у безпеці, поки військові сили Стормвінда зайняті деінде. Навколишні ліси неухильно занепадають: копальні кишать поганню, гноли збираються на берегах річок, а розбійники дошкуляють мандрівникам на Королівському шляху. Маючи замало піхотинців під прямим командуванням, Дуґан організовує місцеву оборону, спрямовуючи новобранців зміцнювати застави й розвідувати спірні землі."},{t="Загрози на кожному кордоні",b="Найближчі клопоти Дуґана — навали кобольдів, що заполонили Копальню Фарґодіп і Яшмову копальню, загрожуючи важливому видобутку Ґолдшира. На заході гноли Річколапи на чолі з горезвісним Гоґґером тиснуть на Гарнізон Вестбрук. На сході Дуґанові доводиться розбиратися з донесеннями Вартового Томаса про лютих мурлоків, що вирізають патрулі вздовж річки. Даючи раду цим численним кризам із обмеженими силами, маршал повсякчас потребує здібних найманців."}},faq={{q="Хто такий Маршал Дуґан?",a="Маршал Дуґан — офіцер армії Стормвінда, що служить у Ґолдширі. Він відповідає за військову безпеку в центрі Лісу Елвінн і організовує оборону від місцевих загроз — злодіїв, гнолів і кобольдів.",al={"дуґан","лор маршала дуґана","маршал ґолдшира"}},{q="Чому Дуґан не надсилає більше вартових на допомогу Гарнізону Вестбрук чи на схід?",a="Армія Стормвінда розпорошена, і Дуґанові ледве вистачає вартових, щоб тримати лад у самому Ґолдширі. Постійних сил, щоб розставити гарнізони на кожному віддаленому хуторі й прикордонному посту, у нього немає, тож він покладається на мандрівних шукачів пригод: вони розвідують гарячі точки, доставляють донесення й усувають загрози в краї.",al={"чому немає вартових","сила гарнізону ґолдшира","війська дуґана"}},{q="Як Дуґан ставиться до загрози від мурлоків в Елвінні?",a="Спершу Дуґан відмахувався від попереджень Ремі «Двічі», що мурлоки серйозно загрожують краю. Справжню небезпеку він визнав лише тоді, коли Вартовий Томас надіслав сумні звістки про загибель вартових Рольфа Гартфорда й Малакая Стоуна на східних річках.",al={"дуґан мурлоки","реміш двічі мурлок","дуґан рибоподібні"}},{q="Як Дуґан дає раду місцевим злочинцям і буянам?",a="Дуґан суворо стоїть на сторожі закону, але чесно попереджає, перш ніж кинути когось за ґрати. Коли місцеві чи мандрівники чинять у Ґолдширі бешкет, він застерігає: хто й далі лізтиме в бійки, потрапить просто до В'язниці Стормвінда, а за вбивство він особисто вистежить винного.",al={"дуґан злочини","закон ґолдшира","загроза в'язниці"}},{q="Чому Дуґана непокоять копальні?",a="Копальня Фарґодіп і Яшмова копальня — важливі джерела золота й руди для Стормвінда. Кобольди захопили обидві підземні копальні, вигнали гірників і погрожують прокопати тунелі просто під поселеннями Елвінна.",al={"дуґан копальня фарґодіп","копальня джаспелоуд дуґан","напад кобольдів"}},{q="Чи співпрацює Маршал Дуґан із Вестфолом?",a="Так. Щойно шукач пригод доведе свою вправність у Лісі Елвінн, Маршал Дуґан посилає його до Вестфолу, до Ґраяна Стаутмантла в Сентінел Гілл, де Народне ополчення відчайдушно потребує допомоги досвідчених бійців проти Братства Дефіас.",al={"дуґан ґраян","звіт у вестфол","дуґан сентінел гілл"}}},fp="14,358,27.516.0,23.494.0,22.220.0,75.308.0,53.277.1,55.311.0,40.237.0,45.244.0"}
P.entries["npc:marshal-marris"] = {n="Маршал Марріс",s="Маршал Марріс — знесилений офіцер, що командує міською вартою Лейкшира. Стоячи біля міського мосту, він керує обороною проти величезного вторгнення орків Блекрок, які насуваються з висот Гір Редріджу. Армії Стормвінда тут немає, тож він покладається на заїжджих шукачів пригод, щоб стримати наступ орди.",h="Маршал Марріс — знесилений офіцер, що командує міською вартою Лейкшира.",kw={"маршал марріс","лейкшир","варта","орки блекрок","кам'яна варта","гори редріджу"},ang={["class:Warrior"]="Марріс цінує пряму бойову дисципліну й посилає вправних бійців передової просто в пащу Кам'яної Варти, щоб помірятися силами з бувалими ветеранами Блекрок.",["faction:Alliance"]="Маршал Марріс уособлює долю сільських земель Альянсу, які політичний параліч Стормвінда лишив беззахисними й змусив боротися за виживання самотужки.",["race:Human"]="Для людей королівства Марріс — утілення стійкої, виснаженої прикордонної варти, що тримає лінію проти решток Старої Орди."},sec={{t="Місто в облозі",b="Лейкшир на межі загибелі: на заході — гноли, на сході — страхітлива воєнна міць клану Блекрок. Маршал Марріс тримає лінію варти біля головного мосту міста, але його запаси вичерпано, а солдати розпорошені до неможливого. Королівство Стормвінд не дає підкріплень, тож саме на Маррісі лежить важкий тягар — не дати грубій силі розчавити містечко."},{t="Розбити авангард Блекрок",b="Розуміючи, що сама лише оборона Редрідж не врятує, Марріс готує рішучі удари по таборах орків. Він посилає найманців винищувати воїнів Блекрок, знешкоджувати їхніх тіньових чаклунів і зрештою вистежити Таріл'зуна — грізного командира, що засів у руїнах Фортеці Кам'яної Варти. Його накази мають зламати командування орків, перш ніж повномасштабний наступ остаточно розчавить Лейкшир."}},faq={{q="Хто такий Маршал Марріс?",a="Маршал Марріс — старший воєначальник, що відповідає за оборону Лейкшира. Він вартує біля західного краю міського мосту й намагається вберегти поселення від ворожих набігів.",al={"марріс","лор маршала марріса","хто вартовий на мосту лейкшира"}},{q="Чому Маршал Марріс наймає незалежних шукачів пригод?",a="Королівство Стормвінд так і не надіслало до Гір Редріджу достатніх підкріплень, і місцева варта Лейкшира безнадійно поступається ворогам числом. Маючи справу з бойовими загонами гнолів і орками Блекрок, що міцно закріпилися в краї, Марріс мусить наймати героїв-найманців для вирішальних ударів.",al={"чому марріс потребує допомоги","чому немає армії стормвінда"}},{q="З якими загрозами бореться Маршал Марріс?",a="Поки гноли докучають околицям, Марріс насамперед зосереджений на орках Блекрок, що захопили Фортецю Кам'яної Варти. Ці орки, якими командує Таріл'зун і яких підсилює магія тіней, — безпосередня смертельна загроза для Лейкшира й усього королівства.",al={"вороги марріса","хто нападає на лейкшир"}},{q="Чи Маршал Марріс родич Натаноса Марріса?",a="У них прізвище, поширене в людських королівствах Лордерону й Стормвінда, але жоден офіційний запис не підтверджує прямої спорідненості між Маршалом Маррісом із Редріджу й прославленим рейнджером Натаносом Маррісом із півночі.",al={"чи марріс родич натаноса","рід марріс"}},{q="Як Марріс збирається здолати клан Блекрок?",a="Марріс веде війну на виснаження й обезголовлення. Він посилає бійців проріджувати піхоту Блекрок, збирати магічні складники в їхніх заклиначів тіней і прорватися до Фортеці Кам'яної Варти, щоб стратити їхнього ватажка, Таріл'зуна.",al={"план марріса","як перемогти орків блекрок"}},{q="Де знайти Маршала Марріса?",a="Марріс стоїть у Лейкширі в Горах Редріджу, на видноті біля мосту в центрі міста.",al={"місце марріса","де маршал марріс"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Маршал Максвелл",s="Маршал Максвелл — високопоставлений офіцер війська Стормвінда, що служить у Дозорі Морґана в Палаючих Степах. Йому доручено утримувати найпівнічніший укріплений хребет Альянсу над Горами Редріджу проти клану Блекрок і дворфів Темного Заліза, і він керує розвідницькими вилазками у ворожі скелі внизу. Крім того, він відіграє ключову роль у з'ясуванні долі свого полоненого товариша — Маршала Реджинальда Віндзора.",h="Маршал Максвелл — високопоставлений офіцер війська Стормвінда, що служить у Дозорі Морґана в Палаючих Степах.",kw={"максвелл","маршал","дозор морґана","палаючі степи","блекрок","віндзор","стормвінд"},ang={["class:Warrior"]="Максвелл утілює дисципліну передового війська Стормвінда: він стоїть непохитно серед вулканічного попелу й координує глибокі удари в тил ворога.",["faction:Alliance"]="Для звитяжців Альянсу, що терплять пекучу спеку Палаючих Степів, Маршал Максвелл уособлює владу Стормвінда й вістря походу проти Гори Блекрок."},sec={{t="Самотній пост у Пустках",b="Дозор Морґана — хиткий форпост на південному краю Палаючих Степів, над пустирем, що задихається від попелу, драконородів і орків Блекрок. Маршал Максвелл командує загоном війська Стормвінда, що стоїть тут, і для мандрівників, які наважуються пройти вогняними скелями, він — рідкісне дружнє обличчя. З цього скелястого бастіону він керує обороною, щоб стримати ворожі сили гори, перш ніж ті ринуть на південь — до Редріджу й Елвінна."},{t="Правда в надрах гори",b="Окрім звичайного стримування, Максвелл — головний польовий зв'язковий для операцій, спрямованих у саме серце Шпиля Блекрок і Глибин Блекрок. Коли з'являються чутки, що полонений Маршал Реджинальд Віндзор, можливо, ще живий у підземеллях дворфів Темного Заліза, саме Максвелл отримує розвіддані, перебирає донесення й посилає надійних звитяжців на порятунок. Його форпост — вирішальний місток між прикордонною розвідкою та політичним бурлінням, що назріває за брамою Стормвінда."}},faq={{q="Хто такий Маршал Максвелл?",a="Маршал Максвелл — командир армії Стормвінда, що служить у Дозорі Морґана в Палаючих Степах. Він очолює місцеві сили Альянсу, які стежать за орками Блекрок, чорними драконами й дворфами Темного Заліза.",al={"лор маршала максвелла","хто такий максвелл"}},{q="Чому Маршал Максвелл служить у Дозорі Морґана?",a="Дозір Морґана — прифронтовий табір Альянсу на межі Палаючих Степів. Максвелла поставили тут, щоб утримувати гірський перевал, що веде вниз до Гір Редріджу, і стежити за загрозами, які сунуть із Гори Блекрок.",al={"чому максвелл у палаючих степах","командир дозору морґана"}},{q="Що пов'язує Максвелла з Маршалом Віндзором?",a="Максвелл — головний командир, що допомагає шукати Маршала Реджинальда Віндзора, якого взяли в полон і приволокли до Глибин Блекрок. Максвелл допомагає організувати порятунок і передає до Стормвінда важливі відомості про Віндзора.",al={"максвелл і віндзор","лор завдання покинутої надії"}},{q="Чи допомагає Маршал Максвелл організовувати удари по Шпилю Блекрок?",a="Так. Максвелл посилає досвідчених поборників Альянсу знищувати верхівку клану Блекрок і дає накази проти генерала Драккісата та його сил, що тримають висоти Шпиля Блекрок.",al={"максвелл дракісат","місія максвелла"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Маршал Макбрайд",s="Маршал Дуглас Макбрайд — командир гарнізону Стормвінда при Абатстві Нортшира. Йому доручено оборону Долини Нортширу, і він кидає новоприбулих рекрутів проти навали кобольдів, що загрожує місцевим фермам і шахтам. Для новачків, які починають службу королівству Стормвінд, він — головна військова влада.",h="Маршал Дуглас Макбрайд — командир гарнізону Стормвінда при Абатстві Нортшира.",kw={"макбрайд","маршал макбрайд","нортшир","абатство нортшира","кобольди","шахта ехо-рідж"},ang={["class:Warrior"]="Макбрайд шукає міцних бійців на службу королівству й покладається на воїнів передової, щоб очистити тунелі Шахти Ехо-Рідж.",["faction:Alliance"]="Макбрайд стоїть на першому рубежі Великого Альянсу в самому серці людських земель і приймає новобранців на службу Короні.",["race:Human"]="Для людей, що починають свої пригоди в Нортширі, Маршал Макбрайд — перший представник королівської влади Стормвінда, якого вони зустрічають."},sec={{t="Командир Нортшира",b="Маршал Дуглас Макбрайд стоїть просто біля Абатства Нортшира й уособлює пряму владу армії Стормвінда в цій тихій долині. Саме абатство — острівець віри й знань, але неспокій, що шириться королівством, розтягнув військові гарнізони до краю. Макбрайд мусить берегти мир і забезпечувати долину харчами та ресурсами, маючи лише жменьку присяжних вартових і потік зелених рекрутів, які приходять навчатися в майстрів абатства."},{t="Навала кобольдів",b="Найбільший клопіт Макбрайда — раптова зухвалість місцевої наволочі. Кобольди, що колись лише дошкуляли, заполонили довколишні ліси й захопили Шахту Ехо-Рідж — важливий для округи скарб. Регулярних солдатів, щоб їх вигнати, бракує, тож Макбрайд збирає паладинів, воїнів та інших новачків, щоб відтіснити підземних шкідників і з'ясувати масштаби навали, перш ніж вони геть задушать долину."}},faq={{q="Хто такий Маршал Макбрайд?",a="Маршал Дуглас Макбрайд — офіцер армії Стормвінда, командир гарнізону в Абатстві Нортшира. Він відповідає за оборону Долини Нортширу й призначає новобранців на службу.",al={"маршал макбрайд","хто такий макбрайд","командир нортшира"}},{q="Чому Макбрайд посилає новобранців битися з кобольдами?",a="Кобольди заполонили ліси довкола Нортшира й захопили Шахту Ехо-Рідж. Оскільки військо Стормвінда розпорошене, Макбрайд покладається на новоприбулих шукачів пригод, щоб очистити край від цієї наволочі.",al={"чому вбивати кобольдів","проблема кобольдів","проблема ехо-рідж"}},{q="Куди Макбрайд посилає новобранців далі?",a="Коли новобранець доведе свою вправність, упоравшись із загрозами в Долині Нортширу, Макбрайд посилає його південною дорогою до Ґолдшира на допомогу Маршалові Дуґану.",al={"куди йти після макбрайда","після нортшира","наступне місто"}},{q="Що таке Шахта Ехо-Рідж?",a="Шахта Ехо-Рідж — багата на руду печера на північному краю Долини Нортширу. Нещодавно її захопили кобольди-землекопи, і Макбрайд наказав провести кілька операцій, щоб її відвоювати.",al={"ехо-рідж","шахта нортшира"}},{q="Чи командує Макбрайд самим абатством?",a="Ні. Абатство Нортшира утримують святі ордени й жерці Світла. Макбрайд командує військовим гарнізоном, що має боронити абатство й довколишню долину.",al={"чи макбрайд керує абатством","хто керує абатством"}},{q="Чи тривожать Макбрайда загрози, окрім кобольдів?",a="Кобольди — найнагальніша морока, але Макбрайд пильнує й глибших негараздів. На околицях долини крутяться бандити й розбійники — ознака ширшого неспокою, що назріває по всьому Лісу Елвінн.",al={"дефіас у нортширі","чи нортшир безпечний"}}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:martie-jainrose"] = {n="Марті Джейнроуз",s="Марті Джейнроуз — травниця Лейкширу, що доглядає свій сад на березі Озера Незрушного в Горах Редріджу. Вона вирощує цілющі трави й квіти для змученого містечка, відганяє диких звірів, що топчуть її грядки, і потай плекає ніжні почуття до Вартового Паркера.",h="Марті Джейнроуз — травниця Лейкширу, що доглядає свій сад на березі Озера Незрушного в Горах Редріджу.",kw={"марті джейнроуз","травниця","пузонабивач","вартовий паркер","озеро незрушне","лейкшир"},ang={["faction:Alliance"]="Наполегливість Марті віддзеркалює стійкість людей Редріджу, які намагаються жити звичайним життям, навіть коли Стормвінд здебільшого лишає містечко напризволяще.",["profession:Herbalism"]="Для травників, що мандрують Редріджем, Марті — споріднена душа: вона плекає тендітні рослини, попри набіги диких кабанів і ворогів, що підступають усе ближче."},sec={{t="Сад біля озера",b="Марті Джейнроуз живе в Лейкширі й старанно працює місцевою травницею. Хоч краю загрожують орки Блекрок, гноли й місцеві розбійники, Марті дбає про те, щоб містечко мало свіжі трави й букети. Її щоденну працю часто порушують дикі звірі — передусім велетенський кабан Пузонабивач, який раз у раз плюндрує її найцінніші грядки. Окрім трав, Марті, як відомо, потай симпатизує Вартовому Паркеру й іноді надсилає йому букети власноруч зібраних нарцисів, щоб скрасити його пильну варту над містечком."}},faq={{q="Хто така Марті Джейнроуз?",a="Марті Джейнроуз — травниця, що живе в Лейкширі в Горах Редріджу. Вона доглядає сад біля Озера Незрушне, вирощує рослини й готує трав'яні ліки для місцевих мешканців.",al={"марті джейнроуз","хто така марті","травниця лейкшира"}},{q="Що за клопіт у Марті з місцевими тваринами?",a="Величезний і сумно відомий своєю впертістю дикий вепр на прізвисько Пузонабивач повадився плюндрувати її грядки: топче ніжні саджанці й поїдає трави, перш ніж вона встигає їх зібрати.",al={"проблема марті з вепрами","город беллігруба","хто нищить її город"}},{q="Хто подобається Марті в Лейкширі?",a="Марті закохана у Вартового Паркера, одного з міських вартових, що несе службу неподалік. Вона часто передає йому букетики свіжих нарцисів, поки він на варті.",al={"симпатія марті","марті вартовий паркер","романтика доставки нарцисів"}}},fp="15,293,20.588.0,23.202.0,54.182.0,35.184.0"}
P.entries["npc:marukai"] = {n="Марукай",s="Марукай — тролиця з джунглів із племені Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі північно-західного Ашенвалю. Віддана справі утримання цього віддаленого плацдарму Орди, вона керує винищенням наг Гнівохвостих, що підступають до застави й загрожують їй.",h="Марукай — тролиця з джунглів із племені Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі...",kw={"марукай","тролі","застава зорам'гар","наги","гнівохвості","зорамське узмор'я"},ang={["faction:Horde"]="Марукай тримає один із найхиткіших прибережних таборів Орди на землях нічних ельфів і покладається на звитяжців-союзників, щоб місцеві наги не захопили позицію.",["race:Troll"]="Далеко від теплого гомону Села Сен'джин Марукай уособлює стійкість племені Темного Спису, що вибудовує для Орди укріплені опори по всьому Калімдору."},sec={{t="Утримати узбережжя",b="Застава Зорам'гар стоїть відокремлено на північному краю Зорамського Узмор'я, оточена прадавніми руїнами, ворожими землями нічних ельфів і неспокійним морем. Коли наги Гнівохвості великими силами виходять із вод і прадавніх ельфійських руїн, щоб захопити узбережжя, Марукай робить усе, щоб табір не впав. Вона посилає звитяжців Орди відкинути змієлюдей назад у прибій і принести їхні голови — тільки так застава лишиться надійною прибережною твердинею."}},faq={{q="Хто така Марукай?",a="Марукай — тролиця з джунглів, що дає завдання й боронить Заставу Зорам'гар — відлюдний прибережний табір Орди на північно-західному узбережжі Ашенвалю.",al={"лор марукай","хто така марукай","марукай нпс"}},{q="Чому Марукай воює з нагами?",a="Наги Гнівохвости заполонили сусідній Берег Зорам і довколишні руїни. Щоб убезпечити кордони застави й забезпечити виживання Орди на узбережжі, Марукай наймає шукачів пригод, щоб ті прорідили їхні лави.",al={"чому вбивати наг","завдання марукай про наг","наги узбережжя зорам"}},{q="Де знайти Марукай?",a="Вона стоїть поруч зі своїми родичами на Заставі Зорам'гар, біля початку Берега Зорам на північному заході Ашенвалю, трохи на південь від затоплених руїн Чорноглибинних Печер.",al={"де марукай","місце марукай","знайти марукай"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Головний Аптекар Фаранелл",s="Головний Аптекар Фаранелл — очільник Королівського Аптекарського Товариства, що працює в глибинах Апотекаріуму в Андерсіті. За життя шанований учений Даларана, у нежитті він керує пошуками нищівної Нової Чуми, яка має знищити і Погибель, і живих.",h="Головний Аптекар Фаранелл — очільник Королівського Аптекарського Товариства, що працює в глибинах...",kw={"фаранелл","аптекар","андерсіті","апотекаріум","нова чума","королівське аптекарське товариство"},ang={["faction:Horde"]="Союзників — орків, тролів і тауренів — може непокоїти зелений слиз і замкнені в клітках піддослідні Апотекаріуму, та дослідження Фаранелла терплять як важливу зброю проти спільної загрози — Погибелі.",["profession:Herbalism"]="Чани Фаранелла поглинають незліченні запаси рідкісних рослин, мохів і грибних витяжок — похмуре свідчення того, як ботаніку можна обернути на зброю нищення.",["race:Undead"]="Для Відступників Фаранелл — авангард біологічної незалежності: він трудиться в темряві, щоб його народ мав зброю, здатну зламати Короля-Ліча."},sec={{t="Розум, зламаний смертю",b="До Третьої війни Фаранелл був шанованим алхіміком, що десятиліттями навчався поруч із ученими магами Даларана. Свої смертні дні він присвятив пошукам ліків, засобів і зілль, що поліпшували б здоров'я смертних. Коли чума Погибелі забрала його життя і він повстав як Відступник із вільною волею, колишня наукова цікавість обернулася на жорстокість. Зберігши енциклопедичний розум, він проміняв цілющі мазі на згубні реагенти й швидко став одним із найцінніших дослідників Королеви Сильвани Віндраннер у надрах занепалої столиці Лордерона."},{t="Господар Апотекаріуму",b="Зі смердючих лабораторій Апотекаріуму Фаранелл координує далекосяжні дослідження Королівського Аптекарського Товариства. Він наглядає за створенням незграбних гидот і керує підлеглими аптекарями по всьому Лордерона й поза ним. Кожна партія дивних отрут, зіпсованої крові й проклятих рослин, яку польові дослідники збирають на різних континентах, зрештою проходить крізь його чани для перегонки й очищення."},{t="Виготовлення Нової Чуми",b="Єдина нав'язлива мета Фаранелла — виконати наказ Темної Леді: відкрити Нову Чуму. Щоб зварити заразу, здатну знищити Артаса та його бездумні легіони Погибелі, Фаранелл організовує масштабний збір реагентів. Він посилає шукачів пригод забрати дослідницькі нотатки свого загиблого колеги, Аптекаря Берарда, із Села Пайрвуд, роздобуває кажанячий послід у глибоких лігвах Рейзорфен Краула й випробовує кислотні колоїди на органах фанатиків із Багряного Монастиря."}},faq={{q="Хто такий Головний Аптекар Фаранелл?",a="Фаранелл — очільник Королівського Аптекарського Товариства, алхімічної гільдії на службі Леді Сильвани Віндраннер в Андерсіті. Він керує всіма дослідженнями отрут, зшитих гидот і створенням Нової Чуми.",al={"хто такий фаранелл","лор фаранелла","голова аптекарів"}},{q="Де знайти Фаранелла?",a="Він в Апотекаріумі — алхімічному кварталі в західній частині Андерсіті, серед вируючих казанів, кліток для дослідів і своїх підлеглих-аптекарів.",al={"місце фаранелла","де головний аптекар фаранелл","знайти фаранелла"}},{q="Ким був Фаранелл до смерті?",a="За життя Фаранелл був знаним алхіміком і лікарем, що вчився в чарівників Даларану. Усе своє життя він винаходив ліки від хвороб, аж поки чума не вбила його й не спрямувала його допитливість на смертельні отрути.",al={"історія фаранелла","чи фаранелл був у даларані","смертне життя фаранелла"}},{q="Що намагається створити Королівське Аптекарське Товариство?",a="З веління Королеви Сильвани товариство виготовляє Нову Чуму. Їхня мета — створити зброю, досить смертоносну, щоб знищити Погибель і помститися Королеві-Лічу, а заразом захистити Відступників від смертних ворогів.",al={"нова чума","що роблять аптекарі","цілі аптекарів"}},{q="Чому Фаранелл посилає шукачів пригод до Села Пайрвуд?",a="Він шукає дослідницький журнал свого колишнього колеги, Аптекаря Берарда, який збожеволів і піддався прокляттю воргенів у Пайрвуді. Польові записи Берарда містять важливі дані про отруйні речовини, потрібні, щоб удосконалити їхні досліди з чумою.",al={"завдання рецепт смерті фаранелл","чому село пайрвуд","щоденник аптекаря берара"}},{q="Навіщо йому реагенти з Рейзорфен Краулу й Багряного Монастиря?",a="Фаранелл перевіряє, як взаємодіють протилежні нестабільні речовини. Він бере гуано з лігв шипогривів Рейзорфен Краулу й свіжовирізані серця фанатиків Багряного Хрестового Походу, щоб випробовувати їдкі колоїди й біологічне зараження.",al={"гуано краулів фаранелл","серця запалу","серця багряного монастиря"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-gadrin"] = {n="Майстер Ґадрін",s="Майстер Ґадрін — старий троль із джунглів і шанований знахар племені Темного Списа, що нині живе в Селі Сен'джин. Колись він разом із відступником-знахарем Залазаном навчав жерців і магів племені, а тепер очолює зусилля, щоб допомогти своєму вигнаному народові й зняти темне прокляття з їхнього вкраденого дому на Островах Відлуння.",h="Майстер Ґадрін — старий троль із джунглів і шанований знахар племені Темного Списа, що нині живе в Селі...",kw={"майстер ґадрін","знахар","троль","село сен'джин","темний спис","залазан","лоа","острови відлуння"},ang={["class:Mage"]="Ґадрін став першопрохідцем, навчаючи тролів Темного Списа таємних мистецтв після Третьої війни й доводячи, що троляча магія може сягати далеко за межі сирого обрядового моджо.",["class:Priest"]="Як старійшина, що навчав жерців Темного Списа спілкуватися з духами й лоа, Ґадрін утілює традиції тіні та віри тролів із джунглів.",["faction:Horde"]="Майстер Ґадрін — один із найдовіреніших радників Вол'джина: він пильно стежить за узбережжям Дуротару й попереджає Гострий Пагорб, коли темні культи загрожують молодій державі Дуротар.",["race:Troll"]="Для тролів Темного Списа Майстер Ґадрін — живий зв'язок із домом ваших предків і традиціями Сен'джина. Він поколіннями формував духовний провід вашого племені й по-батьківськи тужить через трагедію Островів Відлуння."},sec={{t="Наставник Темного Списа",b="Задовго до того, як Темний Спис прибув на Калімдор, Майстер Ґадрін був знахарем свого племені на прадавніх островах Південних Морів, де керував містичним навчанням цілих поколінь тролів Темного Списа."},{t="Зрада Залазана",b="Коли Темний Спис разом з Ордою оселився на Островах Відлуння, Ґадрін і молодий знахар Залазан разом керували містичним навчанням жерців і магів племені. На жаль, Залазан піддався божевіллю, сп'янілий від темних сил вуду, якими прагнув володіти. Відступник поневолив розум своїх одноплемінників і вигнав Вол'джина та непідкорених тролів Темного Списа на материк, у Дуротар. Нині Ґадрін живе в Селі Сен'джин і носить у серці скорботу від того, що колишній товариш став тиранічним чудовиськом; він невтомно працює, щоб упокоїти вбитих одноплемінників і покласти край пануванню Залазана."},{t="Хранитель прадавніх знань",b="Окрім кризи на Островах Відлуння, Ґадрін є одним із найбільших живих знавців тролячої духовності та знань про лоа в усій Орді. Учені, шамани й навіть Королівське Аптекарське Товариство шукають його поради щодо таємниць магії та алхімії. Коли дивні загрози на кшталт Палаючого Клинка торкаються Дуротару або далеким дослідникам потрібні забуті обряди — скажімо, розшифрувати прадавні таблички в Зул'Фарраку, щоб прикликати павучу лоа Шадру, — саме Ґадрін володіє знаннями, щоб створити потрібні зв'язування."}},faq={{q="Хто такий Майстер Ґадрін?",a="Майстер Ґадрін — знахар і старійшина, духовний провідник тролів Темного Спису. Він живе в Селі Сен'джин на узбережжі Дуротару й є старшим радником вождя Вол'джина.",al={"лор майстра ґадріна","хто такий ґадрін","ґадрін нпс"}},{q="Що пов'язує Ґадріна із Залазаном?",a="На Островах Відлуння Ґадрін і молодий знахар Залазан разом навчали жерців і магів Темного Спису містичних мистецтв, але згодом Ґадрін нажахано дивився, як Залазан піддався темній магії, збожеволів і вигнав Темний Спис із рідного острова.",al={"ґадрін і залазан","звідки ґадрін знає залазана","наставник залазана"}},{q="Чому Ґадрін залишається в Селі Сен'джин?",a="Коли прокляття Залазана вигнало Темний Спис з Островів Відлуння, ті, хто вцілів, заснували Село Сен'джин на південному узбережжі Дуротару як притулок. Ґадрін лишається в селі, щоб радити біженцям, стежити за місцевими загрозами й спрямовувати удари проти сил Залазана.",al={"чому ґадрін у селі","що робить ґадрін у селі сен'джин"}},{q="Хто такий Міншина?",a="Міншина — брат Майстра Ґадріна. Він загинув у колотнечі на Островах Відлуння, і його неспокійний дух почав кликати Ґадріна уві сні. Ґадрін просить надійних шукачів пригод повернути череп брата, щоб його душа нарешті знайшла спокій.",al={"брат міншини","лор черепа міншини","хто була міншина"}},{q="Чи допомагає Ґадрін у боротьбі з культом Палаючого Клинка?",a="Так. Отримавши від Зуріти Фарґейз звістку, що Палаючий Клинок проник до Долини Випробувань, Ґадрін стежить за присутністю культу біля Села Сен'джин. Бачачи ширшу загрозу для Дуротару, він посилає новобранців на північ доповісти Орґнілу Соулскару на Гострому Пагорбі.",al={"палаючий клинок дуротар ґадрін","оргніл соулскар ґадрін"}},{q="Що Ґадрін знає про лоа Шадру?",a="Ґадрін — знавець стародавньої тролячої віри. Коли Аптекар Лайдон із Відступників шукає сильну отруту, якою користуються тролі Сухокорі з Пригір'я, Ґадрін упізнає в ній дар Шадри, лоа-павучихи, і посилає шукачів пригод до Зул'Фаррака прочитати табличку з її справжнім ім'ям — воно потрібне йому, щоб скласти закляття виклику.",al={"лоа шадра ґадрін","павучий бог ґадрін"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="Майстер Ворнал",s="Майстер Ворнал — літній троль із джунглів Темного Списа, що мешкає в Селі Сен'джин на південному узбережжі Дуротару. Попри похилий вік і великі знання алхімічних варив, він уперто відмовляється брати учнів.",h="Майстер Ворнал — літній троль із джунглів Темного Списа, що мешкає в Селі Сен'джин на південному узбережжі...",kw={"майстер ворнал","алхімія","сен'джин","розчинник","троль","дуротар"},ang={["profession:Herbalism"]="Ті, хто вправний із сирими травами, впізнають гостре око Ворнала на рідкісні каталізатори та їдкі природні реагенти, потрібні для його розчинників.",["race:Troll"]="Для тролів Темного Списа Майстер Ворнал утілює впертих літніх майстрів, які допомогли заснувати Село Сен'джин після того, як плем'я втекло зі свого острівного дому."},sec={{t="Упертий бровар Сен'джину",b="Майстер Ворнал — невід'ємна частина Села Сен'джин, відомий тим, що варить міцні напої та трунки для своїх побратимів із Темного Списа. Хоч вік помітно наздоганяє його, Ворнал лишається вкрай незалежним і вперто відмовляється навчати будь-яких учнів, воліючи змішувати свої ліки й леткі суміші лише власноруч."},{t="Розчинний дух",b="Ворнал час від часу доручає молодим шукачам пригод збирати їдкі чи незвичні складники з довколишніх земель, як-от сильнодійні матеріали для розчинників і сумішей. Хоч він радо винагороджує тих, хто йому допомагає, свої точні методи й рецепти він тримає під замком, маючи ремесло за справу самотню."}},faq={{q="Хто такий Майстер Ворнал?",a="Майстер Ворнал — літній троль із джунглів, із Темного Спису, що живе в Селі Сен'джин. Він варить для племені міцні настої й ліки, але наполягає, що працюватиме без учня.",al={"майстер ворнал","ворнал","майстер ворнал сен'джин","хто такий ворнал"}},{q="Де знайти Майстра Ворнала?",a="Він стоїть серед хиж у Селі Сен'джин, на південному узбережжі Дуротару, трохи на північ від Островів Відлуння.",al={"місце ворнала","де майстер ворнал","знайти майстра ворнала"}},{q="Чому Майстер Ворнал не бере учнів?",a="Ворнал славиться своєю впертістю. Попри поважний вік і те, що громада потребує його ремесла, він воліє сам порядкувати своїми зіллями, ніж передавати таємниці свавільним новачкам.",al={"чому ворнал без учнів","немає учня ворнала","учні ворнала"}},{q="Які доручення він дає шукачам пригод?",a="Ворнал посилає мандрівників по всьому краю збирати сировину для його розчинників: матеріали він бере в мандрівників, але саме варіння тримає суто при собі.",al={"завдання ворнала","розчинний дух","завдання майстра ворнала"}}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.193.0,37.181.0"}
P.entries["npc:mastok-wrilehiss"] = {n="Масток Врайлгісс",s="Масток Врайлгісс — орківський офіцер на Заставі Розщепленого Дерева на сході Ашенвалю. Як один із головних організаторів оборони Орди в спірному лісі, він посилає розвідників і воїнів захищати довколишні кордони й давати раду загрозам зіпсованих стихій. Без нього Орді важко було б утримати свою хитку опору посеред безупинної ворожнечі нічних ельфів.",h="Масток Врайлгісс — орківський офіцер на Заставі Розщепленого Дерева на сході Ашенвалю.",kw={"масток врайлгісс","застава розщепленого дерева","орда","земляне кільце","дже'ню санкреа","ашенваль"},ang={["class:Shaman"]="Через тривогу Мастока за зіпсованих елементалів лісу шукачі пригод часто вирушають по пораду до Земляного Кільця на узбережжі Зорам'гар.",["faction:Alliance"]="Масток Врайлгісс уособлює орківську військову присутність, що міцно окопалася в Ашенвалі й боронить укріплене поселення Розщепленого Дерева від вартових нічних ельфів.",["faction:Horde"]="Для звитяжців Орди, що борються за прикордонну опору в Ашенвалі, Масток — важливий командир, який підкаже вам найнагальніші справи в краї."},sec={{t="Оплот у прадавніх лісах",b="Застава Розщепленого Дерева стоїть глибоко в тіні височенного лісового покрову Ашенвалю, з усіх боків оточена ворожими землями нічних ельфів. Масток Врайлгісс — один із головних захисників застави: він стежить за шляхами постачання й тим, що діється в лісі. Становище небезпечне: будь-яка ознака слабкості накликає стрімкі удари вартових, які бачать у поселенні загарбницьке вторгнення, що нищить ліс."},{t="Керівництво фронтом",b="Зі свого місця за частоколом Масток доручає перехожим шукачам пригод важливі стратегічні справи. Він пильно стежить за кордонами з сусідніми землями, як-от Горами Кам'яного Кігтя, і посилає розвідників радитися з шаманами на кшталт Дже'ню Санкреа із Земляного Кільця на узбережжі Зорам'гар. Його обов'язки поєднують військову оборону зі стеженням за дивними силами, що псують місцевих елементалів."}},faq={{q="Хто такий Масток Врайлгісс?",a="Масток Врайлгісс — вправний орк-воїн на Заставі Розщепленого Дерева в Ашенвалі. Він офіцер, що дає завдання: має втримати заставу від нападів нічних ельфів і розвідувати загрози в краї.",al={"хто такий масток","роль мастока врайлгісса","хто цей орк"}},{q="Де знайти Мастока Врайлгісса?",a="Він на Заставі Розщепленого Дерева — укріпленій заставі Орди у східно-центральному Ашенвалі, при головній лісовій дорозі.",al={"місце мастока","де масток врайлгісс","карта мастока"}},{q="Які доручення Масток дає шукачам пригод?",a="Масток доручає шукачам пригод Орди стратегічні справи: розвідати загрози від зіпсованих елементалів у лісі, убезпечити проходи до Гір Кам'яного Кігтя й відрядити посланців до Дже'ню Санкреа із Земляного Кільця.",al={"завдання мастока","доручення від мастока"}},{q="Чому на Заставу Розщепленого Дерева постійно тиснуть?",a="Застава — головний осередок лісозаготівлі й твердиня Орди в Ашенвалі. Місцеві нічні ельфи вважають присутність орків і вирубку лісу тяжким оскверненням священних земель, тож сутички не вщухають.",al={"чому нічні ельфи нападають на сплінтертрі","конфлікт застави розщепленого дерева"}},{q="Чому Масток посилає мандрівників до Дже'ню Санкреа?",a="Шамани Земляного Кільця, як-от Дже'ню на Березі Зорам'гар, вивчають і зцілюють нестабільність стихій, що роздирає Ашенваль. Масток зводить бійців із передової з їхнім духовним досвідом, щоб упоратися зі зіпсованими водяними елементалями й дивними збуреннями.",al={"чому звертатися до земляного кільця","масток і дже'ню"}},{q="Чи ворожий Масток Врайлгісс до гравців Альянсу?",a="Так. Масток — відданий член Орди й вправний захисник Застави Розщепленого Дерева, тож нападе на гравців Альянсу, щойно ті наблизяться до табору.",al={"чи альянс може говорити з мастоком","чи можна вбити мастока"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Матіас Шоу",s="Майстер Матіас Шоу — очільник SI:7, таємної розвідувальної служби Королівства Стормвінд. Діючи з тіней Старого Міста, він керує шпигунами й розвідниками, щоб захистити королівство і від внутрішніх змов, і від зовнішніх жахіть.",h="Майстер Матіас Шоу — очільник SI:7, таємної розвідувальної служби Королівства Стормвінд.",kw={"матіас шоу","si:7","шпигун","розвідка","венкліф","стормвінд"},ang={["class:Rogue"]="Матіас Шоу — абсолютна вершина розбійницького мистецтва людей. Розбійників Альянсу часто посилають до нього по складні тактичні доручення й особливі отрути.",["faction:Alliance"]="Як головний шпигун королівства, Шоу — перша лінія оборони від підривної діяльності: він збирає важливі воєнні відомості для Верховного Лорда Болвара Фордрагона й короля-хлопчика Андуїна.",["race:Human"]="Трагічний розрив Шоу з другом дитинства Едвіном Венкліфом відбиває ширший гіркий розкол, що стався в Королівстві Стормвінд після його відбудови."},sec={{t="Майстер SI:7",b="Матіас Шоу — головний шпигун і вбивця Стормвінда. Зі скромного штабу SI:7, захованого за казармами в Старому Місті, Шоу керує таємною мережею, що охоплює Східні Королівства й не тільки. Прагматичний, розважливий і безмежно відданий дому Ріннів, він дотримується переконання, що безпека Стормвінда так само залежить від невидимих кинджалів і викрадених листів, як і від блискучих обладунків та палацових гарнізонів."},{t="Тінь Венкліфа",b="Шоу пов'язує з Едвіном Венкліфом, ватажком бунтівного Братства Дефіас, глибоко особиста історія. Вони дружили з дитинства, і Шоу сам навчав Венкліфа мистецтва скрадання й убивства, сподіваючись, що обдарований каменяр колись служитиме королівству поряд із ним. Натомість, коли після відбудови Стормвінда Гільдію Каменярів вигнали, Венкліф обернув ті смертоносні уроки проти корони. Нині Шоу керує операціями зі стеження й проникнення, щоб зламати повстання свого давнього друга у Вестфолі."},{t="Очі в усіх королівствах",b="Поки Вестфол і Елвінн поглинає внутрішній заколот, увагу Шоу постійно привертають смертельно небезпечні загадки ззовні. Коли до нього дійшли донесення про дивні дії Відступників у Східних Чумних землях, він послав туди п'ятьох своїх найкращих агентів. Живим повернувся лише один — він нажахано белькотів про «Натаноса» й «Блайткаллера», а потім помер уві сні. Шоу покладається на перевірених вільних поборників, які йдуть туди, де зникають його розвідники, щоб розвіяти морок, що згущується на кордонах королівства."}},faq={{q="Хто такий Матіас Шоу?",a="Матіас Шоу — очільник SI:7, розвідувальної служби Стормвінда й гільдії вбивць. Діючи зі Старого Міста, він керує шпигунством і таємною обороною королівства від імені трону.",al={"хто такий шоу","лідер таємної служби","лор матіаса шоу","шпигунський майстер стормвінда"}},{q="Де знайти Матіаса Шоу?",a="Він у штабі SI:7 у районі Старе Місто в Стормвінді, захованому за військовими казармами.",al={"місце шоу","де матіас шоу","знайти матіаса шоу"}},{q="Що пов'язує його з Едвіном Венкліфом?",a="Шоу й Едвін Венкліф дружили з дитинства. Шоу особисто навчав Венкліфа розбійницького ремесла й шпигунства, сподіваючись, що вони працюватимуть разом. Коли суперечка з Гільдією Каменярів переросла в насильство, Венкліф скористався саме цими вміннями, щоб створити Братство Дефіас.",al={"шоу і венкліф","друг венкліфа","матіас і едвін"}},{q="Що таке SI:7?",a="SI:7 — головна розвідувальна служба Стормвінда, що спеціалізується на стеженні, розвідці, шпигунстві й таємних убивствах заради захисту королівства та інтересів Альянсу.",al={"що таке таємна служба стормвінда","що означає ця служба","розвідка стормвінда"}},{q="Чому Матіаса Шоу цікавить Вестфол?",a="Вестфол — твердиня Братства Дефіас. Шоу тримає в краї діючих агентів, щоб шпигувати за бунтівниками й зривати їхні змови проти Стормвінда.",al={"шоу вестфол","таємна служба вестфол","вежа кларена"}},{q="Що сталося з агентами, яких Шоу послав до Чумних Земель?",a="Шоу відрядив п'ятьох агентів розвідати підозрілі пересування Відступників у Східних Чумних Землях. Четверо так і не повернулися, а єдиний, хто вцілів, повернувся, белькочучи про «Натаноса» й «Блайткаллера», і за кілька днів помер уві сні.",al={"завдання шоу чумні землі","п'ять розвідників шоу","розвідники ферми марріса"}}},fp="12,246,14.449.0,18.587.1,24.517.0,20.212.0,32.125.0,41.254.0,25.191.0,43.166.0,57.235.0"}
P.entries["npc:mathredis-firestar"] = {n="Матредіс Фаєрстар",s="Матредіс Фаєрстар — ексцентричний маг з ельфів крові, що живе на Полум'яному Гребені в Палаючих Степах. Він творить могутні зачарування, відомі як Малі Аркануми, спираючись на таємні дослідження свого покійного наставника. Заразом він живиться залишковою енергією, що вивільняється під час зв'язування, — так він стримує свою залежність від магії.",h="Матредіс Фаєрстар — ексцентричний маг з ельфів крові, що живе на Полум'яному Гребені в Палаючих Степах.",kw={"матредіс","аркануми","лібрами","ельфи крові","полум'яний гребінь","палаючі степи","зачарування"},ang={["class:Mage"]="Маги впізнають у тому, як Матредіс створює аркануми, відчайдушний і непевний спосіб черпати сиру магічну поживу із самого процесу зв'язування предметів."},sec={{t="Спадок наставника й магічна залежність",b="Ремесла створювати аркануми — зосереджені самоцвіти таємного посилення — Матредіс Фаєрстар навчився у свого наставника Телміуса Дрімсікера. Телміус зустрів страшну смерть у прадавніх руїнах Лютопащу, намагаючись вирвати магічні таємниці в Шен'дралар. Телміус винайшов ці магічні зв'язування, але Матредісу бракує майстерності, щоб творити найвеличніші з них, тож він спеціалізується на Малих Арканумах. Для Матредіса ця робота — далеко не наукова вправа: як і всі ельфи крові після падіння Сонячного Колодязя, він страждає від гризького голоду за таємною силою. Коли матеріали зв'язуються з прадавніми лібрамами, вивільняються бурхливі розряди магічної енергії, і Матредіс поглинає їх, щоб підтримати себе."},{t="Мистецтво арканума",b="Шукачі пригод, які приносять Матредісові потрібні фоліанти — скажімо, Лібрами Статури, Стійкості, Роздумів, Завзяття чи Ненажерливості — разом із рідкісними реагентами, побачать, що він охоче ділиться своїм ремеслом. Під час процесу мінливі магічні реагенти зв'язуються безпосередньо з текстом, і їхня сутність зосереджується в арканумі, що здатен назавжди зачарувати головний убір чи обладунок для ніг. Доки шукачі пригод постачають складники, Матредіс отримує і плату, і розлиту в повітрі таємну поживу, якої так відчайдушно прагне."}},faq={{q="Хто такий Матредіс Фаєрстар?",a="Матредіс Фаєрстар — ельф крові, маг на нейтральній заставі Полум'яний Гребінь у Палаючих Степах. Він знавець тайної магії, що вміє творити Малі Аркануми для зачарування обладунків.",al={"лор матредіса","хто такий матредіс фаєрстар","фаєрстар кривавий ельф"}},{q="Навіщо Матредіс творить аркануми?",a="Після знищення Сонячного Колодязя ельфи крові потерпають від тяжкої магічної спраги. Матредіс живиться сирою залишковою магічною енергією, що вивільняється, коли арканум створюють і прив'язують, і так угамовує залежність свого народу.",al={"навіщо матредіс творить аркануми","мотивація матредіса","навіщо лібрами"}},{q="Хто такий Телміус Дрімсікер?",a="Телміус Дрімсікер — покійний наставник Матредіса й винахідник арканумів. Телміус вирушив до руїн Лютопаща, щоб почерпнути знань у Шен'дралар, але його там убили, перш ніж він устиг передати всю свою майстерність.",al={"телміус","учитель матредіса","хто був його вчитель"}},{q="Які аркануми вміє творити Матредіс?",a="Матредіс уміє творити Малі Аркануми Статури, Стійкості, Роздумів, Завзятості й Ненажерливості. Найсильніші аркануми знав лише його наставник Телміус, і Матредісові вони досі не до снаги.",al={"які аркануми","менші аркануми","список лібрамів"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="Матренґіл Берволкер",s="Матренґіл Берволкер — досвідчений наставник друїдів і шанований старійшина Кола Кенарія, що живе в Ценаріонському Анклаві Дарнасуса. Колись він був безпосереднім помічником Архідруїда Фандрала Стаґгелма, а нині веде молодих друїдів Альянсу крізь духовні випробування, обряди перевтілення й доручення по всьому Калімдору.",h="Матренґіл Берволкер — досвідчений наставник друїдів і шанований старійшина Кола Кенарія, що живе в...",kw={"матренґіл","берволкер","друїд","наставник","коло кенарія","ценаріонський анклав","дарнасус"},ang={["class:Druid"]="Для друїдів Альянсу Матренґіл — незамінний наставник, що поєднує Дарнасус із Місячним Гаєм і відкриває таємниці ведмежої та водної подоби, а також трав'яних ліків від смертельних отрут.",["faction:Alliance"]="Матренґіл уособлює виважений, традиційний провід Кола Кенарія в Дарнасусі — стриману противагу войовничим замашкам Фандрала Стаґгелма.",["race:NightElf"]="Матренґіл — взірець калдорейського друїдства: він уособлює відданість природі й рівновазі в добу після Третьої війни, коли постає Тельдрассил."},sec={{t="Наставник Ценаріонського Анклаву",b="Серед зелених крон Ценаріонського Анклаву в Дарнасусі Матренґіл Берволкер вважається одним із наймудріших і найврівноваженіших друїдів Тельдрассила. Він — головний провідник для недосвідчених друїдів Альянсу: стежить за їхнім єднанням із Місячним Гаєм і перевіряє, чи готові вони опанувати первісні звірині подоби. Замолоду Матренґіл і сам пройшов крізь виснажливе, приголомшливе єднання з Великим Духом Ведмедя, тож добре розуміє вагу цих обрядів. Він особисто велить новачкам випробувати силу свого духу в поєдинку зі священним місячником Лунакло, перш ніж вони ступлять на шлях Друїда Пазура."},{t="На службі в архідруїда",b="Матренґіл давно став правою рукою Фандрала Стаґгелма: веде щоденні справи кола й набирає охочих для честолюбних задумів архідруїда. Коли Фандрал зажадав величезних запасів ранкозерна, саме Матренґіл налагодив його збір із рук шукачів пригод, хоч наодинці й зізнавався, що неприродна суть цієї дивної рослини його непокоїть. Він також скеровує відповіді Альянсу на заклики з Місячного Гаю й обережно лавірує в тонкій політиці Кола Кенарія, поки Фандрал звертає погляд на південь Калімдору й до Чумних Земель."},{t="Ширший погляд",b="Стаґгелм славиться лютою гордістю й зневагою до інших рас, тоді як Матренґіл часто виявляє вдумливість і відкритість. Коли до Дарнасуса надійшли реліквії загиблого друїда Малґріса Діпрівера, що поліг у боях із Погибеллю в Західних Чумних Землях, Матренґіл був глибоко зворушений, дізнавшись, що цей дослідник був тауреном. Розмірковуючи про спільну місію Кола Кенарія, він тихо зауважив, що таурени, можливо, відійшли від учення Кенарія зовсім не так далеко, як запевняє архідруїд."}},faq={{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — досвідчений нічний ельф, наставник друїдів у Ценаріонському Анклаві в Дарнасусі. Його шанують як одного з найврівноваженіших мудреців Тельдрассила; він навчає послушників зміни подоби, очищення від отрут і обов'язків на службі Колові Кенарія.",al={"хто такий матренґіл","роль матренґіла","берволкер"}},{q="Які в нього стосунки з Фандралом Стаґгелмом?",a="Матренґіл — безпосередній помічник і заступник Архідруїда Фандрала Стаґгелма. Сумлінно виконуючи Фандралові доручення — збираючи ранкозерно й розподіляючи завдання, — Матренґіл потай сумнівається в деяких суворих поглядах і дивних задумах Фандрала.",al={"помічник фандрала","стаґгелм і матренґіл"}},{q="Яких подоб Матренґіл допомагає навчитися друїдам?",a="Матренґіл наставляє молодих друїдів після їхніх духовних паломництв до Місячного Гаю: наглядає за їхнім спілкуванням із Лунакло, щоб здобути Ведмежу подобу, а також завершує їхні випробування на Темному Узбережжі й у Вестфолі, щоб опанувати Водну подобу.",al={"завдання форми ведмедя дарнас","завдання водяної форми дарнас","форми друїдів матренґіл"}},{q="Навіщо Матренґіл збирає ранкозерно?",a="Він допомагає Архідруїдові Фандралу Стаґгелму в ботанічних дослідженнях на Тельдрассилі, збираючи ранкозерно, яке вирощують шукачі пригод. Утім, Матренґіл зізнавався, що щоразу, коли він поруч із цією рослиною, йому стає глибоко неспокійно.",al={"завдання ранкозерна","навіщо ранкозерно дарнас"}},{q="Як Матренґіл ставиться до тауренів-друїдів?",a="На відміну від Фандрала Стаґгелма, що відкрито скептично ставиться до тауренів-друїдів, Матренґіл розважливіший. Дізнавшись про самопожертву тауренського друїда, що боровся з Погибеллю в Західних Чумних Землях, він визнав, що таурени, можливо, ближчі до науки Кенарія, ніж готовий визнати Фандрал.",al={"таурени друїди","матренґіл таурени"}},{q="Що він робить зі Скалкою Жаху?",a="Коли шукачі пригод приносять зіпсовану Скалку Жаху Фаллі Сейджвінд, вона посилає їх до Матренґіла, а той оглядає її з великою тривогою, відчуваючи, як скверна підкрадається до Смарагдового Сну.",al={"скалка жаху матренґіл","завдання в кошмарах"}}},fp="21,314,30.623.0,24.566.0,21.521.0,29.262.0,47.285.0,45.226.0,40.234.0,45.289.0,41.199.0"}
P.entries["npc:maur-raincaller"] = {n="Маур Рейнколлер",s="Маур Рейнколлер — таурен, що живе в Селі Бладгуф у Малгорі. Пов'язаний із природним і духовним життям рівнин, він допомагає старійшинам села й наглядає за місцевими справами, що стосуються стад і диких звірів.",h="Маур Рейнколлер — таурен, що живе в Селі Бладгуф у Малгорі.",kw={"маур рейнколлер","село бладгуф","маззранаш","малгор","ліки","мисливець"},ang={["class:Hunter"]="Маур пропонує вам одне з перших мисливських випробувань: відсилає вас на вовків, кугуарів, степових довгоступів і стрімкокрилів відкритих рівнин по частини, потрібні, щоб вилікувати отруйний укус Маззранаша.",["race:Tauren"]="Для юних тауренів, що виходять із Табору Нарачі, Маур — нагода захистити землі ваших предків від мандрівних хижаків і буйних звірів."},sec={{t="Мешканець Села Бладгуф",b="Маур Рейнколлер живе біля самого серця Села Бладгуф, на березі Озера Кам'яного Бика, і служить громаді, дбаючи про справи природи та звірів у цьому краї. Як і багато хто з тих, хто носить ім'я Рейнколлер, він пильно стежить за рівновагою стихій і живої природи на родючих рівнинах Малгору. Після того як укус страхітливого довгоступа Маззранаша загноївся, Маур звертається до вправних молодих мандрівників, щоб вони зібрали частини звірів, потрібні йому для ліків."}},faq={{q="Хто такий Маур Рейнколлер?",a="Маур Рейнколлер — таурен, що живе в Селі Бладгуф серед зелених степів Малгору. Він дає місцеві завдання й просить шукачів пригод утихомирити неслухняних тварин у околицях.",al={"роль маура рейнколлера","хто такий маур","лор маура рейнколлера"}},{q="Де знайти Маура Рейнколлера?",a="Він стоїть надворі серед наметів і вогнищ Села Бладгуф, трохи на південь від Тандер Блафа, на східному березі Озера Кам'яного Бика.",al={"місце маура рейнколлера","де маур","координати маура"}},{q="З якою бідою має справу Маур?",a="Маура вкусив Маззранаш — грізний довгоступ із дідових переказів, — і рана загноїлася. Він просить шукачів пригод принести йому частини вовків, пум, рівнинних довгоступів і стрімкокрилів Малгору, щоб приготувати ліки.",al={"завдання маура рейнколлера","проблема мазраначе","чого хоче маур"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maurin-bonesplitter"] = {n="Маурін Боунспліттер",s="Маурін Боунспліттер — учений і заклинатель із Відступників, що несе службу на Заставі Духоходів у Пустограї. Келдран доручив йому стежити за демонічними культами, і Маурін використовує глибоке знання давніх переказів, щоб розбити Палаючий Клинок. До культистів він ставиться з неприхованою зневагою: для нього це дурні, які не бачать темних сутностей, що смикають їх за ниточки.",h="Маурін Боунспліттер — учений і заклинатель із Відступників, що несе службу на Заставі Духоходів у Пустограї.",kw={"маурін боунспліттер","застава духоходів","пустограй","відступники","палаючий клинок","келдран","культисти"},ang={["class:Mage"]="Маги, що завітають на Заставу Духоходів, оцінять виважений, інтелектуальний підхід Мауріна: темні ритуали він розплутує, добираючи до кожного особливу протидію.",["class:Warlock"]="Чорнокнижники впізнають у Мауріні глибоке розуміння демонічних угод, хоча його зневага гостро нагадує, як небезпечно служити могутнішим демонам.",["faction:Horde"]="Маурін уособлює особливу підтримку, яку Андерсіті надає західним форпостам Орди: його темні наукові знання допомагають союзникам-тауренам протистояти демонічній скверні.",["race:Undead"]="Маурін доводить, що сила Відступників тримається не лише на некромантській могуті, а й на хитрих магічних дослідженнях і вмінні скористатися слабкістю ворога."},sec={{t="Учений серед вигнанців",b="Застава Духоходів серед посушливих пустирів Пустограю — передусім форпост тауренів і Орди, і Маурін Боунспліттер вирізняється тут як один з небагатьох мешканців-нежиті. Він не грубий вояк, а вчений заклинатель із глибокими знаннями забороненої історії та окультних сил. Його хист до таємної магії й гострий розум помітив Келдран і відрядив його в цей край — стежити за дедалі сильнішою присутністю демонів і координувати прицільні удари по ній."},{t="Зневага до Палаючого Клинка",b="Найбільше злоби Маурін вкладає в боротьбу з культом Палаючого Клинка, що окопався по всьому Пустограю. Безрозсудні амбіції культистів викликають у нього щиру огиду: він глузує з них за те, що вони не розуміють простого — позичена сила лише робить їх рабами демонічних господарів. За допомогою чарів провидіння й знання ритуалів Маурін залучає шукачів пригод з Орди, щоб планомірно зривати призови культу й підривати його діяльність по всьому цьому безплідному краю."}},faq={{q="Хто такий Маурін Боунспліттер?",a="Маурін Боунспліттер — маг і вчений із Відступників, що живе на Заставі Духоходів у Пустограї. Його призначив Келдран, і він використовує свої знання давніх переказів і темної магії, щоб викорінити культ Палаючого Клинка, який діє в цьому краї.",al={"лор мауріна боунспліттера","хто такий маурін","маурін пустограй"}},{q="Чому нежить живе на тауренській заставі?",a="Застава Духоходів — важливе поселення Орди в Пустограї. Келдран поставив туди Мауріна саме тому, що з цієї застави найзручніше стежити за культистами Палаючого Клинка, які заполонили довколишні пустища, і боротися з ними.",al={"чому нежить на тауренській заставі","нежить у пустограї"}},{q="Що Маурін думає про Палаючий Клинок?",a="Маурін глибоко зневажає Палаючий Клинок. Він вважає їх жалюгідними, темними пішаками, які в маренні вірять, що мають справжню силу, і геть не тямлять, що вони лише маріонетки демонічних володарів.",al={"маурін палаючий клинок","чому маурін ненавидить палаючий клинок"}},{q="Хто послав Мауріна Боунспліттера до Пустограю?",a="На посаду в Пустограї Мауріна призначив Келдран. Цінуючи глибокі знання Мауріна про культові обряди й давні перекази, Келдран доручив йому заважати Палаючому Клинку, а згодом і вигнати його з краю.",al={"хто послав мауріна","маурін келдран","начальник мауріна"}},{q="Які доручення Маурін дає шукачам пригод?",a="Маурін просить шукачів пригод розвідати справи Палаючого Клинка й принести скальп Тіньового Скрадача Ненависної Люті та Кристал Оракула наг. З цих реагентів він ламає захисні чари від споглядання й знаходить володаря демонів, що стоїть за культом.",al={"завдання мауріна","чого хоче маурін"}},{q="Маурін пов'язаний із Колом Кенарія чи з Ордою?",a="Маурін — вірний член Відступників і служить Орді. Він діє лише з табору Орди на Заставі Духоходів і допомагає поборникам Орди очищати пустища від культистів.",al={"чи маурін з орди","фракція мауріна"}}},fp="19,361,24.495.0,30.459.0,27.228.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="Максан Анвол",s="Максан Анвол — дворфійський наставник жерців, що служить у Ґуральні Тандербрю в Хараносі. Відданий Святому Світлу, він веде дворфійських жерців-початківців, поки ті вчаться спрямовувати божественну силу серед морозного клімату Дун Мороґу. Він випробовує молодих послушників, щоб переконатися, що вони гідні носити церковне облачення.",h="Максан Анвол — дворфійський наставник жерців, що служить у Ґуральні Тандербрю в Хараносі.",kw={"максан анвол","жрець","наставник","святе світло","ґуральня тандербрю","харанос","облачення"},ang={["class:Priest"]="Максан — ваш ранній провідник у Дун Мороґу: він відкриває вам основи святої дисципліни, навчає расових молитов на кшталт Відчайдушної Молитви й вручає ваше перше офіційне церковне вбрання.",["faction:Alliance"]="Максан дбає про фізичну й духовну готовність горян і розвідників Альянсу, які стережуть Дун Мороґ від трогів, крижаних тролів і диких звірів.",["race:Dwarf"]="Утілюючи практичну побожність Айронфорджа, Максан укорінює дворфійську віру там, де люди справді збираються, — просто біля пивних барил Хараноса."},sec={{t="Жрець у шинку",b="Хоч може здатися дивним знайти висвяченого служителя Святого Світла в Ґуральні Тандербрю, дворфійській культурі це цілком пасує. Харанос — головний вузол між Долиною Холодного Хребта й Айронфорджем, і саме в місцевій корчмі природно збираються мандрівники, горяни й послушники. Максан дбає про духовний добробут селища поруч із кухлями стауту, пропонуючи молитви й пораду кожному, хто переступить поріг."},{t="Випробування вірних",b="Максан Анвол відповідає за перевірку жерців-новачків, перш ніж ті вирушать у широкий світ. Він доручає послушникам показати володіння основними цілющими молитвами на поранених захисниках Дун Мороґу. Тим, хто доводить свою відданість і практичну вправність, вручають перше справжнє жрецьке облачення, офіційно засвідчуючи їхнє визнане становище в Церкві Святого Світла."}},faq={{q="Де знайти Максана Анвола?",a="Максан Анвол — у Ґуральні Тандербрю, головній корчмі й місці зборів у містечку Харанос, що загубилося серед снігових заметів у центрі Дун Мороґу.",al={"місце максана анвола","де максан","тренер жерців харанос"}},{q="Чого навчає Максан Анвол?",a="Він наставник жерців, що навчає новачків і досвідченіших жерців святого зцілення, керування тінями й божественного захисту. Також він навчає дворфів-жерців особливих молитов, як-от Відчайдушної Молитви.",al={"чого він навчає","закляття максана анвола"}},{q="Що святий жрець робить у ґуральні?",a="У дворфійському суспільстві життя, спілкування й свята обертаються довкола пивоваріння й таверн. Ґуральня Тандербрю для Хараноса — і майдан, і ратуша, і прихисток для мандрівників. Максан там, де може дістатися простих людей, вартових і перехожих, яким потрібна духовна розрада.",al={"чому ґуральня","жрець у шинку"}},{q="Чи дає Максан Анвол якісь особливі доручення?",a="Так. Він випробовує майбутніх жерців завданнями на кшталт «У ласці Світла» й «Шати Світла»: посилає їх зцілювати поранених горян у снігах. За успішне виконання послушник отримує офіційну мантію служителя.",al={"завдання максана","шати світла"}},{q="Що він каже тим, хто не жрець?",a="Він застерігає інших шукачів пригод ніколи не відвертатися від Святого Світла, нагадуючи, що одного дня в бою саме божественна благодать може врятувати їм життя.",al={"діалог максана","цитата максана"}},{q="Чи можуть гноми вчитися в Максана Анвола?",a="Хоча серед гномів жерців зазвичай не буває, Максан радо приймає кожного члена Альянсу, що прагне мудрості, і навчає будь-якого жерця, який присвятив себе Світлу.",al={"чи гноми навчаються в нього","тренер жерців-гномів"}}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.188.0"}
P.entries["npc:maybell-maclure"] = {n="Мейбелл Маклур",s="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн. Попри гірку, давню ворожнечу між її родиною та сусідами Стоунфілдами, вона потай закохалася в Томмі Джо Стоунфілда.",h="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн.",kw={"мейбелл маклур","томмі джо","виноградники маклюрів","кохання","лікер невидимості","ворожнеча"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що проходять Лісом Елвінн, роман Мейбелл — нагадування, що особисті біди й давні образи живуть навіть у серці королівства."},sec={{t="Нещасливе кохання на виноградниках",b="Життя на Виноградниках Маклюрів — це нескінченна праця й незгасна образа на сусідню родину Стоунфілдів. Між двома вогнями опинилася Мейбелл Маклур, яка глибоко закохалася в Томмі Джо Стоунфілда, молодого спадкоємця ворожої садиби. Розлучена з ним пильною ріднею й давньою родинною неприязню, Мейбелл відчайдушно шукає будь-якої нагоди передати Томмі Джо хоч слово подалі від цікавих очей своїх рідних."},{t="Зілля для справжнього кохання",b="Не маючи змоги відкрито перетнути межу між фермами, Мейбелл покладається на співчутливих подорожніх і настанови Бабусі Стоунфілд. З допомогою ґолдширського алхіміка Вільяма Пестла вариться лікер невидимості. Випивши цей заборонений трунок, Мейбелл може непомітно вислизнути із садиби Маклурів і вкрасти дорогоцінні хвилини з Томмі Джо на березі річки."}},faq={{q="Чому Мейбелл і Томмі Джо не можуть бачитися?",a="Родини Маклурів і Стоунфілдів уже багато років запекло ворогують. Оскільки обидві родини забороняють будь-які стосунки між собою, Мейбелл і Томмі Джо мусять тримати своє кохання в цілковитій таємниці, інакше на них упаде гнів рідні.",al={"чому ворожнеча родин","ворожнеча маклурів і стоунфілдів","чому вони не можуть бути разом"}},{q="What prevents Maybell from leaving the vineyard?",a="Her family watches her closely because of the feud with the Stonefields. She needs help finding a way to meet Tommy Joe without attracting their attention.",al={"як мейбелл утікає","зілля невидимості елвінн","як вона зустрічає томмі"}},{q="Де Мейбелл зустрічається з Томмі Джо?",a="Томмі Джо чекає на березі річки на межі між Виноградниками Маклюрів і Фермою Стоунфілдів, де їх не видно з жодного хутора.",al={"місце зустрічі","де вони зустрічаються","де томмі джо"}},{q="Хто допомагає Мейбелл у її коханні?",a="Бабуся Стоунфілд співчуває закоханим і посилає охочих шукачів пригод до Вільяма Пестла, алхіміка з Ґолдшира, який дає їм змогу таємно зустрітися.",al={"хто допомагає мейбелл","помічники стоунфілдів"}}},fp="15,230,29.425.0,26.383.1,47.236.0,48.155.1,34.152.0,35.189.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Мебок Міззірікс",s="Мебок Міззірікс — заповзятливий гоблін-ділок, що живе в портовому містечку Раджет. Завжди готовий перетворити дивовижні дикі інгредієнти на прибуток, він наймає мандрівних шукачів пригод збирати незвичайні рослини й тварин по всіх Пустках і далі. Найславетніший його задум — комерційний напій для поліпшення розуму з рогів рапторів.",h="Мебок Міззірікс — заповзятливий гоблін-ділок, що живе в портовому містечку Раджет.",kw={"мебок міззірікс","гоблін","раджет","розумні напої","роги рапторів","синьолисті бульби"},ang={["faction:Alliance"]="Зійшовши з корабля з Буті Бей у нейтральному Раджеті, мандрівники Альянсу можуть братися за доручення Мебока, не боячись ворожої варти.",["faction:Horde"]="Для мандрівників Орди, що проходять Раджетом на шляху через Пустки, Мебок — легкий заробіток на винищенні небезпечних звірів поблизу.",["profession:Cooking"]="Кулінари вважатимуть рецепти страв і напоїв Мебока щонайменше сумнівними, адже він наполягає на товченому розі раптора.",["profession:Herbalism"]="Захоплення Мебока дивними зразками на кшталт Синьолистих бульб показує дикішу, комерційну сторону збирання унікальних рослин Калімдору."},sec={{t="Заповзятливий алхімік",b="Мебок Міззірікс, що веде справи в гамірному нейтральному порту Раджет, утілює класичний дух картелю Стімвідл — невтомне вміння скористатися будь-якою нагодою. Раджет обслуговує моряків, піратів і торговців усіх мастей, а Мебок пильно придивляється до дикої природи Калімдору. Замість добувати звичайну руду чи торгувати буденним полотном, він шукає рідкісні біологічні дивовижі, з яких, на його думку, можна виготовити дуже прибуткові зілля й товари."},{t="У пошуках розумних напоїв",b="Головний комерційний задум Мебока — власний «розумний напій», що мав би штучно підсилювати розум того, хто його вип'є. Переконаний, що природна хитрість і лютість місцевих рапторів походять від рогів на їхніх мордах, Мебок наймає мисливців добувати цілі роги по всіх Пустках. Для нього етика й смак відходять на задній план перед ринковими можливостями — аби тільки платні покупці вірили, що напій діє."},{t="Екзотичні інгредієнти й рослини",b="Окрім еліксирів із рапторів, Мебокові постійно потрібні й інші дивовижні зразки. Від збирання неспокійних яєць глибокомохових павуків до пошуків рідкісних Синьолистих бульб, захованих глибоко в терновиках Рейзорфен Краула, — його забаганки раз у раз заводять відчайдушних найманців у небезпечні краї. Якщо в якоїсь істоти є дивні властивості, Мебок певен: її можна розлити в пляшки й продати."}},faq={{q="Хто такий Мебок Міззірікс?",a="Мебок Міззірікс — гоблін-торговець і алхімічний пройдисвіт із нейтрального портового містечка Раджет у Пустках. Він наймає шукачів пригод збирати дивних тварин і частини рослин для своїх торгових задумів.",al={"хто такий мебок","лор мебока міззірікса","гоблін раджета мебок"}},{q="Що таке «Розумні напої»?",a="«Розумні напої» — дослідні тоніки для гостроти розуму, які Мебок Міззірікс сподівається зварити й продавати. Він вірить, що розтерті роги кмітливих ящерів Пусток передадуть тому, хто їх вип'є, їхні гострі інстинкти й хитрість.",al={"розумні напої","завдання розумних напоїв","зілля з рога раптора"}},{q="Де знайти Мебока Міззірікса?",a="Він стоїть серед будівель портового міста Раджет на східному узбережжі Пусток, куди можуть приходити мандрівники і з Орди, і з Альянсу.",al={"місце мебока","де мебок","знайти мебока міззірікса"}},{q="Навіщо Мебокові роги ящерів?",a="Мебок припускає, що хитрий розум ящерів, які блукають Пустками, зосереджений у їхніх рогах. Він збирається розтерти їх на порошок як головну діючу речовину своїх напоїв для розуму.",al={"навіщо роги раптора","призначення рогів раптора","що мебок робить із рогами"}},{q="Чому Мебок посилає людей до Рейзорфен Краулу?",a="Він наймає шукачів пригод спуститися до Рейзорфен Краулу й за допомогою навченого нюхача викопати бульби синьолисту — рідкісної рослини з цінними й незвичайними властивостями.",al={"чому рейзорфен краул","мебок завдання краул","бульби синьолисту краул"}},{q="Мебок працює на Орду чи на Альянс?",a="Мебок — незалежний член картелю Стімвідл у нейтральному Раджеті. Він вірний лише монеті й охоче торгує та укладає угоди з членами обох фракцій.",al={"чи мебок з орди","чи мебок з альянсу","фракція мебока"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="Мелітар Стаґгелм",s="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила. Він допомагає молодим нічним ельфам — шукачам пригод на початку навчання, посилаючи їх до поблизьких учителів і залагоджуючи дрібні місцеві негаразди. Хоч він носить відоме прізвище Стаґгелм, як і Архідруїд Фандрал Стаґгелм, його точний зв'язок із провідним друїдом лишається непідтвердженим.",h="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила.",kw={"мелітар стаґгелм","стаґгелм","алдрассил","тінедол","тельдрассил","фандрал стаґгелм","провідник"},ang={["race:NightElf"]="Для нічних ельфів, що починають подорож у Тінедолі, Мелітар — одна з найперших постатей, яких вони зустрічають, покинувши прихисток Алдрассила."},sec={{t="Провідник біля Алдрассила",b="Стоячи просто перед входом до великої гілки Алдрассила, Мелітар — одна з перших постатей, з якими стикаються нічні ельфи, виходячи у світ. Він спрямовує щойно пробуджену молодь із різними сигілами до відповідних класових наставників, щоб ті дістали належну науку бойових і містичних мистецтв. Окрім розпорядчих настанов, Мелітар пильнує найближчі угіддя Тінедолу і шукає помічників, щоб упоратися з бешкетливою тутешньою звіриною й дрібними бісуватими вторгненнями, що загрожують спокою святилища."},{t="Ім'я Стаґгелмів",b="Прізвище Стаґгелм неминуче привертає увагу, адже Архідруїд Фандрал Стаґгелм нині очолює Коло Кенарія в Дарнасусі після зникнення Малфуріона Стормрейджа у Смарагдовому Сні. Та Мелітар не вихваляється величним походженням і не говорить про свій рід. Чи він далекий родич шанованої родини Архідруїда, чи просто носить прадавнє калдорейське родове ім'я, Мелітар задовольняється скромними обов'язками біля коріння Алдрассила."}},faq={{q="Хто такий Мелітар Стаґгелм?",a="Мелітар Стаґгелм — нічний ельф, що дає завдання на стежці біля гілки Алдрассила в Тінедолі. Він допомагає новоприбулим нічним ельфам-шукачам пригод зорієнтуватися й направляє їх до наставників.",al={"мелітар","хто такий мелітар","мелітар тінеділ"}},{q="Чи Мелітар родич Архідруїда Фандрала Стаґгелма?",a="Точна спорідненість невідома. Хоча вони носять одне ім'я Стаґгелм, Мелітар ніколи не згадує про родинний зв'язок з Архідруїдом Фандралом Стаґгелмом чи його покійним сином Валстанном. Незрозуміло, чи він далекий родич, чи просто має поширене калдорейське прізвище.",al={"рідня фандрала","брат фандрала","рід стаґгелм"}},{q="Яку роль Мелітар відіграє для новачків?",a="Нічних ельфів-новачків посилають до Мелітара з їхніми вступними знаками. Мелітар приймає ці знаки й вказує кожному новачкові на потрібного наставника в Алдрассилі, щоб той почав справжнє навчання свого класу.",al={"завдання мелітара","завдання сигілів","що робить мелітар"}},{q="Де знайти Мелітара Стаґгелма?",a="Він стоїть просто на дерев'яному пандусі біля входу до Алдрассила, у центрі Тінедолу на Тельдрассилі.",al={"місце мелітара","де мелітар","знайти мелітара стаґгелма"}}},fp="17,406,20.531.0,17.508.0,25.218.0,50.260.0,49.215.0,35.115.0"}
P.entries["npc:melor-stonehoof"] = {n="Мелор Стоунгуф",s="Мелор Стоунгуф — бувалий тауренський мисливець, що несе службу на Узвишші Мисливців у Тандер Блафі. Як наставник у мисливському мистецтві, він перевіряє, як мисливці Орди вміють вистежувати здобич і чи вистачає їм мужності, посилаючи їх за найнебезпечнішими хижаками Пусток і Тисячі Голок.",h="Мелор Стоунгуф — бувалий тауренський мисливець, що несе службу на Узвишші Мисливців у Тандер Блафі.",kw={"мелор стоунгуф","мисливець","узвишшя мисливців","тандер блаф","полювання","мертвобагно"},ang={["class:Hunter"]="Мелор — один із головних провідників, що дають завдання мисливцям Орди: він веде вас крізь обряди вистежування, які втілюють священний шлях мисливця.",["faction:Horde"]="Мелор дбає, щоб воїни й слідопити всієї Орди були загартовані проти диких звірів, що загрожують поселенням від Малгору до Тисячі Голок.",["race:Tauren"]="Мелор, що несе службу високо на Узвишші Мисливців, утілює глибоку шану вашого народу до полювання — і як до випробування сили, і як до рівноваги із Земною Матір'ю."},sec={{t="Наставник дикої природи",b="Зі свого місця на вітряних просторах Узвишшя Мисливців Мелор Стоунгуф досвідченим оком оглядає рівнини внизу. Для тауренів полювання священне: воно переплетене з виживанням, духовною рівновагою й шаною до найбільших хижаків природи. Мелор дбає, щоб ті, хто носить лук і клинок в ім'я Орди, розуміли цю рівновагу, і посилає здібних слідопитів відточувати майстерність у випробуваннях із легендарними звірами."},{t="Мисливські випробування",b="Мелор кидає мисливцям виклик: вистежити легендарних і невловних звірів, що тероризують дикі краї. Він посилає слідопитів рівнинами Пусток — від допомоги мисливиці Серґрі Даркторн на Перехресті до погоні за Стілснепом, хитрою й лютою гієною в Тисячі Голок. У цих випробуваннях мисливці доводять, що здатні перехитрити й здолати найсмертоносніших істот центрального Калімдору."},{t="Чудовиська далеких земель",b="Тим, чия майстерність переросла Пустки, Мелор вказує на далекі краї. Він доручає бувалим мисливцям здолати звірів жахливої сили — серед них Мертвобагно, прадавнього кроколіска, що причаївся в болотах Багна Пилоброду, і лютого єті Морозопащу з Гір Альтерак. Кожне полювання перевіряє, чи справді слідопит опанував Шлях Мисливця."}},faq={{q="Де знайти Мелора Стоунгуфа?",a="Мелор Стоунгуф — на Узвишші Мисливців у місті Тандер Блаф. Узвишшя Мисливців — найсхідніше плато тауренської столиці, куди можна дістатися мотузяними мостами з центрального плато з тотемом.",al={"місце мелора стоунгуфа","де мелор","координати мелора"}},{q="Які завдання дає Мелор Стоунгуф?",a="Мелор пропонує низку мисливських випробувань для шукачів пригод середнього рівня: посилає гравців до Серґри Даркторн у Пустках, на полювання на люту гієну Стілснеп і на вистежування грізних звірів далі від дому — кроколіска Мертвобагно в Багні Пилоброду та єті Морозопащу в Горах Альтерак.",al={"завдання мелора","що робить мелор","ланцюжок завдань мелора"}},{q="Чому Мелор посилає мисливців на Стілснеп?",a="Стілснеп — сумно відома лютістю й хитрістю гієна, що нишпорить Тисячею Голок. Мелор посилає вправних мисливців вистежити й убити її як перевірку майстерності, витривалості й відваги в дикій природі.",al={"чому вбивати стілснепа","лор завдання стілснепа"}},{q="Хто такий Мертвобагно?",a="Мертвобагно — незвично великий і лютий кроколіск, що нишпорить болотами Багна Пилоброду. Мелор кидає мисливцям виклик: убити його, щоб довести свою майстерність.",al={"хто такий мертвобагно","лор мертвобагна","звір мертвобагно"}},{q="Чи треба бути мисливцем за класом, щоб узяти його завдання?",a="Ні. Хоча його випробування втілюють мисливський шлях і пасують саме мисливцям, Мелор пропонує свої мисливські доручення кожному вправному шукачеві пригод, що бореться за Орду.",al={"чи лише мисливець бере завдання мелора","чи інші класи беруть завдання мелора"}},{q="Хто така Серґра Даркторн і чому Мелор посилає до неї?",a="Серґра Даркторн — орчиха-мисливиця на Перехресті в Пустках. Мелор посилає до неї обіцяльних мисливців, щоб ті допомогли приборкати неслухняних хижаків рівнин і повчилися в іще одного ветерана дикої природи.",al={"серґра мелор","завдання серґри даркторн"}}},fp="15,283,21.435.0,18.388.0,29.374.0,33.196.0,39.333.0,44.185.0,17.157.0,52.189.0,60.225.0"}
P.entries["npc:menara-voidrender"] = {n="Менара Войдрендер",s="Менара Войдрендер — чорнокнижниця-людина, що живе в гоблінському порту Раджет. Вона наставляє честолюбних адептів темних мистецтв і з Альянсу, і з Орди, ділячись глибокими знаннями про артефакти для зв'язування демонів і таємне ремесло. Відлюдне життя на Калімдорі тримає її далеко від пильного ока правовірної влади.",h="Менара Войдрендер — чорнокнижниця-людина, що живе в гоблінському порту Раджет.",kw={"менара войдрендер","чорнокнижниця","раджет","зв'язування демонів","табета","сфера орагіла"},ang={["class:Warlock"]="Менара — важлива наставниця на Калімдорі: вона вчить адептів обох фракцій виготовляти їхні особливі зачаровані мантії й ув'язнювати демонів у сферах-фокусах.",["profession:Tailoring"]="Менара поєднує складні кравецькі матеріали з інгредієнтами скверни, щоб ткати міцні, просякнуті чарами шати, здатні спрямовувати демонічну силу.",["race:Human"]="Далеко від катакомб Стормвінда Менара уособлює чорнокнижників-людей, що відкинули вірність королівству, аби безперешкодно займатися темними мистецтвами на нейтральних землях."},sec={{t="Прихисток у Раджеті",b="Більшість чорнокнижників у Східних Королівствах практикують у вогких підвалах чи відлюдних бойнях під рідними містами, але Менара Войдрендер обрала нейтральний гоблінський порт Раджет у Пустках. Далеко від прискіпливого ока Кірін-Тору, варти Стормвінда чи наглядачів Оргріммара, вона вільно віддається своїм окультним студіям у всіх на виду. Готовність працювати з будь-яким здібним учнем, незалежно від фракції, робить її рідкісною спільною точкою для адептів темних мистецтв."},{t="Майстриня зв'язування",b="Серед досвідчених заклиначів Менара відома як знавчиня сфер, що ув'язнюють демонічних духів і підкоряють їхню силу. Вона працює з вигадливими інгредієнтами, проводячи учнів крізь складні ритуали, щоб виготовити зачаровані шати й знаряддя для зв'язування. Слава про її майстерність сягає Айронфорджа й Андерсіті, тож старші чорнокнижники по всьому Азероту посилають своїх найздібніших учнів за море по її пораду."},{t="Зв'язки з болотами",b="Серед давніх знайомих Менари — відлюдна чарівниця Табета, що живе в глибокій самоті серед боліт Багна Пилоброду. Хоч Табета віддається таємній магії, а Менара заглиблюється в зв'язування скверною та демонологію, двох жінок поєднує давня історія. Коли могутні реліквії на кшталт Сфери Орагіла потребують відновлення чи особливих знань, їхнє спільне минуле стає несподіваним містком через нетрі Калімдору."}},faq={{q="Хто така Менара Войдрендер?",a="Менара Войдрендер — людина-чорнокнижниця в нейтральному портовому містечку Раджет у Пустках. Вона наставниця й майстриня артефактів для чорнокнижників, що зростають: проводить їх через ремісничі ритуали й чаклунство з підкорення демонів.",al={"хто така менара","лор менари войдрендер","чорнокнижниця раджета"}},{q="Чому людина-чорнокнижниця живе в Пустках?",a="Раджет дає нейтральність і відстань від пильних очей великих держав. Оселившись у гоблінському порту, Менара може займатися забороненими мистецтвами й навчати учнів і з Альянсу, і з Орди без утручання паладинів, магів чи міської варти.",al={"чому менара в раджеті","чому вона в пустках","чорнокнижниця раджета"}},{q="На якій магії спеціалізується Менара?",a="Менара спеціалізується на демонології, зачаруванні темних тканин і виготовленні посудин, у які можна ув'язнити демонічних істот. Особливо вона славиться майстерністю у створенні й відновленні сфер, що зв'язують демонів, як-от Сфери Орагіла.",al={"чого навчає менара","сили менари войдрендер","у чому менара сильна"}},{q="Що пов'язує Менару з Табетою?",a="Менару й відлюдну чарівницю Табету пов'язує спільне минуле. Хоча Табета живе осторонь, у Багні Пилоброду, і займається звичайним чарівництвом, чорнокнижники, які шукають знань про Сферу Орагіла, дізнаються, що ці дві жінки добре знають хист одна одної.",al={"менара й табета","звідки вона знає табету","зв'язок із табетою"}},{q="Менара на боці Альянсу чи Орди?",a="Менара діє з Раджета нейтрально. Вона пропонує науку й ремісничі завдання кожному чорнокнижникові, що доведе свою вправність і досить честолюбства, щоб упоратися з енергією Скверни, і радо приймає учнів і з Альянсу, і з Орди.",al={"менара альянс чи орда","фракція менари","на кого працює менара"}},{q="Які великі артефакти вона допомагає створити?",a="Менара вчить учнів ткати Зачаровану Золоту Криваву Робу — вбрання, просякнуте демонічною силою, — а досвідченішим допомагає знаходити й збирати складники для Сфери Орагіла.",al={"завдання менари","що вона створює","зачароване золото кривава мантія менари"}}},fp="17,347,19.503.0,19.441.0,17.416.1,25.230.0,45.276.0,45.232.0,39.275.0,44.214.0,42.202.0"}
P.entries["npc:merissa-stilwell"] = {n="Мерісса Стілвелл",s="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн. Стоячи біля абатства, вона привітно зустрічає новачків, що навчаються в Долині Нортширу, і простягає їм руку допомоги.",h="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн.",kw={"мерісса стілвелл","нортшир","абатство нортшира","гостинність","новобранці","стілвелли"},ang={["faction:Alliance"]="Для новобранців Альянсу, що покидають затишну обитель Нортширу, Мерісса втілює теплу гостинність Елвінну, перш ніж дасться взнаки сувора дійсність загрози Дефіас."},sec={{t="Привітне обличчя в Нортширі",b="Стоячи біля Абатства Нортшира, Мерісса Стілвелл вітає новобранців, що прибувають у Долину Нортширу. Мандрівним новачкам вона пропонує просту гостинність і практичні поради щодо відпочинку й того, як тут усе влаштовано. Носячи прізвище, спільне з відомими ремісниками й господарями по всьому королівству — як-от коваль Джордан Стілвелл і захисниця Вестфолу Дафна Стілвелл, — вона лишається мирним тутешнім обличчям серед дедалі більшої напруги в королівстві."}},faq={{q="Хто така Мерісса Стілвелл?",a="Мерісса — привітна мешканка Абатства Нортшира в Лісі Елвінн, що дає поради й тепло зустрічає мандрівників, які туди прибувають.",al={"мерісса стілвелл","хто така мерісса","дівчина стілвелл нортшир"}},{q="Де знайти Меріссу Стілвелл?",a="Вона в Абатстві Нортшира в Долині Нортширу, у Лісі Елвінн.",al={"місце мерісси стілвелл","де мерісса","знайти меріссу"}},{q="Чи Мерісса родичка інших Стілвеллів королівства?",a="Хоча вона має те саме прізвище, що й відомі люди на кшталт коваля Джордана Стілвелла чи Дафни Стілвелл із Вестфолу, вона тихо живе в Абатстві Нортшира й вітає мандрівників, а не воює з бандитами чи кує клинки.",al={"рід стілвелл","дафна стілвелл родичка","джордан стілвелл родич"}},{q="Чи дає Мерісса Стілвелл якісь завдання?",a="Ні. Власних доручень для мандрівників у неї немає: вона просто вітає новачків, що проходять через Нортшир.",al={"завдання мерісси","завдання мерісси стілвелл"}}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:merrin-rockweaver"] = {n="Меррін Роквівер",s="Меррін Роквівер — дворфійська дослідниця від Ліги Дослідників у Багнокраї. Після того як люта навала рапторів заполонила Місце Розкопок Велґара, вона сховалася разом із Шукачем Велґаром на гребені над розкопом.",h="Меррін Роквівер — дворфійська дослідниця від Ліги Дослідників у Багнокраї.",kw={"меррін роквівер","ліга дослідників","місце розкопок велґара","шукач велґар","таррел роквівер","раптори"},ang={["faction:Alliance"]="Меррін представляє наукову присутність Айронфорджа в Багнокраї, і збереження її досліджень допомагає Альянсу втримувати хиткий плацдарм у диких болотах.",["race:Dwarf"]="Для дворфів-шукачів пригод допомога Меррін — справа національної спадщини: збереження дорогоцінних реліквій титанів та історичних записів, заради яких Ліга Дослідників ризикувала життям."},sec={{t="Вигнані з розкопу",b="Меррін Роквівер прибула в Багнокрай від імені Ліги Дослідників Айронфорджа, щоб відкопати прадавні таємниці титанів, поховані під багнюкою. Експедиція скінчилася катастрофою, коли великі кістки, які вони відкопали, привабили до розкопу рапторів. Люті доісторичні звірі заполонили траншеї, змусивши Меррін і вцілілих робітників покинути спорядження, нотатки й усе, чого досягли. Тепер вона з кількома вцілілими застрягла на кручі над заполоненими руїнами."},{t="Порятунок справи",b="Застрягнувши на кручі, вцілілі не дають експедиції обернутися на цілковитий провал. Поки Ормер Айронбрейд плекає помсту звірам, а Шукач Велґар шукає уламки таблички, що лишилися в траншеях серед рапторів, думки Меррін линуть до чоловіка, Таррела, який тижнями не має від неї звісток. Вона покладається на розвідника, якого Лонґбрейд послав розшукати загін, — щоб той переказав чоловікові про їхню скруту."}},faq={{q="Хто така Меррін Роквівер?",a="Меррін Роквівер — дворфійка-археологиня з Ліги Дослідників Айронфорджа. Вона працювала на Місці Розкопок Велґара в Багнокраї, доки ящери не захопили розкопки.",al={"лор меррін роквівер","хто така меррін","дворфійка мокрих земель"}},{q="Чому вона застрягла над розкопками?",a="Плямисті ящери, яких привабили великі кістки, відкопані дослідниками, захопили розкопки внизу, і чимало дворфів загинуло. Ормер Айронбрейд прикривав Меррін і Шукача Велґара, поки вони втікали на сусідню кручу, де й досі сидять у пастці.",al={"чому вона на сховищі","притулок велґара меррін","що сталося з її табором"}},{q="З чим Меррін потрібна допомога?",a="Меррін потрібен хтось, хто віднесе листа з розповіддю про лихо її чоловікові Таррелу, який місця собі не знаходить, відколи від неї перестали приходити листи.",al={"завдання меррін","доручення меррін роквівер","лор роботи з інструментами"}},{q="Що намагалася знайти експедиція?",a="Як і більшість справ Ліги Дослідників, розкопки в Багнокраї мали знайти стародавні артефакти, пов'язані з походженням дворфів, і загадкові реліквії титанів, приховані по всьому Каз Модану.",al={"навіщо копають","мета розкопок"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {n="Майлз Велш",s="Майлз Велш — наставник жерців із Відступників, що мешкає глибоко в Ставках Видінь під Тандер Блафом. Він дає духовні настанови й навчає дисципліни тіні жерців, які проходять крізь столицю тауренів.",h="Майлз Велш — наставник жерців із Відступників, що мешкає глибоко в Ставках Видінь під Тандер Блафом.",kw={"майлз велш","жрець","відступники","озера видінь","тандер блаф","тінь"},ang={["class:Priest"]="Для жерців, що мандрують Калімдором, Майлз Велш — одна з небагатьох нагод у центральних володіннях Орди вивчити нові заклинання й просунутися в духовному навчанні.",["race:Undead"]="Майлз — знайоме холодне обличчя з Лордерона в землистій, залитій сонцем столиці тауренів."},sec={{t="Тінь у печерах",b="Майлз Велш перебуває далеко від сплюндрованих чумою руїн Лордерона: його домівка — волога, сповнена духів печера під Тандер Блафом, відома як Ставки Видінь. Як жрець-Відступник, він навчає мандрівників, що спрямовують божественну й тіньову енергію. Його присутність у серці Малгору віддзеркалює хиткі дипломатичні узи, що поєднують Відступників з Ордою: він ділить прихисток із містиками й шаманами тауренів, навчаючи послушників мистецтв тіні й віри."}},faq={{q="Хто такий Майлз Велш?",a="Майлз Велш — нежить, наставник жерців в Ставках Видінь під Тандер Блафом, що допомагає жерцям Орди навчатися й опановувати особливі вміння.",al={"роль майлза велша","хто такий майлз велш","тренер жерців майлз велш"}},{q="Де знайти Майлза Велша?",a="Він в Ставках Видінь — системі підземних печер під Узвишшям Духів у Тандер Блафі, куди веде вхід у печеру на плато.",al={"місце майлза велша","де майлз велш","як знайти майлза велша"}},{q="Чому в Тандер Блафі є наставник жерців — нежить?",a="Відступники й таурени — союзники в Орді. Таурени, особливо Маґата Ґрімтотем, обстоювали прийняття Відступників до фракції, тож посланці й наставники на кшталт Майлза Велша можуть пропонувати свої послуги в Малгорі.",al={"чому нежить у тандер блафі","жрець нежить у місті тауренів"}},{q="Яких умінь він навчає?",a="Майлз Велш навчає загальних жрецьких заклинань і допомагає послушникам-Відступникам і тролям, які шукають особливих расових умінь, як-от Пожирної Чуми, Дотику Слабкості чи Тіньової Варти.",al={"закляття жерців тандер блафф","чого навчає майлз велш"}}},fp="11,200,23.469.0,19.166.0,29.154.0,49.236.0,29.179.0"}
P.entries["npc:milli-featherwhistle"] = {n="Міллі Фезервісл",s="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу. Після падіння Гномреґану вона ретельно виготовляє власноруч і обслуговує механічних їздових птахів, яких так полюбляють її родичі. Свої дорогоцінні механічні творіння вона продає гномам і довіреним союзникам вигнанців Гномреґану.",h="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу.",kw={"міллі фезервісл","механоступ","інженерка","гномка","склад стілґрила","меккаторк","вигнанці гномреґану"},ang={["faction:Alliance"]="Герої Альянсу, що здобули найвищу повагу Вигнанців Гномреґану, можуть звернутися до Міллі, щоб осідлати одного з найшвидших механічних скакунів Азероту.",["profession:Engineering"]="Механоступи Міллі — вершина великомасштабного гномського пересування, що поєднує гіроскопічні балансувальні блоки з потужними механічними кінцівками.",["race:Gnome"]="Міллі Фезервісл — провідна інженерка їздових механізмів вашого народу, яка несе далі технологічний геній Великого Тінкера Меккаторка навіть у вигнанні з вашого підземного дому."},sec={{t="Майстриня механоступів",b="Працюючи просто неба на пронизливому холоді Складу Стілґрила на схід від Хараноса, Міллі Фезервісл відповідає за постачання механічних скакунів переселеному люду Гномреґану. На відміну від живих звірів, яких воліють дворфи й нічні ельфи, Міллі збирає весь свій товар сама, особисто калібруючи шестерні, поршні й балансувальні гіроскопи, щоб кожен механічний птах бігав на повну потужність засніженими скелями Дун Мороґу."},{t="Спадок Меккаторка",b="Кожна рама й пружина в майстерні Міллі походить від креслень, які спершу накреслив Великий Тінкер Ґелбін Меккаторк. Хоча з роками Міллі додала сучасні поліпшення — полегшила шасі й удосконалила вихлопні отвори, — вона вірно дотримується основних схем Великого Тінкера. Її механічні дива доводять: навіть у вигнанні гномське технологічне честолюбство лишається геть незламним."}},faq={{q="Хто така Міллі Фезервісл?",a="Міллі Фезервісл — головна творчиня механоступів та інженерка гномів Гномреґана. Вона працює на Складі Стілґрила в Дун Мороґу, власноруч будує й продає механічних механоступів вершникам, які мають на них право.",al={"міллі фезервісл","хто така міллі","торговка механоступами"}},{q="Де знайти Міллі Фезервісл?",a="Вона на Складі Стілґрила — інженерній заставі за кілька кроків на схід по дорозі від містечка Харанос у Дун Мороґу.",al={"місце міллі","де міллі фезервісл","знайти міллі"}},{q="Кому дозволено купувати в неї їздових тварин?",a="Від початку лише гноми-шукачі пригод мають і дозвіл, і хист, щоб купити її витвори. Члени інших народів Альянсу мусять здобути найвищу довіру — звеличення у Вигнанців Гномреґану, — перш ніж вона довірить їм механоступа.",al={"чи можна купити механоступа","вимоги до механоступа","хто їздить на механоступах"}},{q="Як роблять механоступів?",a="Міллі Фезервісл сама збирає кожного механоступа за знаменитими кресленнями Великого Тінкера Ґелбіна Меккаторка, додаючи власні вдосконалення двигуна й рівноваги.",al={"як будують механоступів","хто робить механоступів","походження механоступів"}},{q="Які моделі вона пропонує?",a="Вона пропонує кілька налаштованих моделей — від звичайних нефарбованих, синіх, зелених і червоних корпусів до тонко відлагоджених прудких варіантів у білому, зеленому й жовтому покритті.",al={"кольори їздових міллі","моделі механоступів","які їздові продає міллі"}},{q="Чому вона працює серед снігів на Складі Стілґрила?",a="Коли радіоактивна катастрофа й навала трогів вигнали гномів із Гномреґана, біженці збиралися, де тільки могли. Склад Стілґрила біля Хараноса — природне місце для випробувань машин і механічного обслуговування разом із дворфами-інженерами.",al={"чому міллі в дун мороґу","чому склад стілґрила"}}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:milton-sheaf"] = {n="Мілтон Шіф",s="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда. Відданий справі збереження історії королівства, він опікується зібранням давніх фоліантів та історичних хронік. Він часто залучає мандрівників Альянсу, щоб ті розшукали загублені томи, зібрали розпорошені записи й відновили занедбані рукописи.",h="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда.",kw={"мілтон шіф","королівська бібліотека","бібліотекар","фортеця стормвінда","історія","рукописи"},ang={["faction:Alliance"]="Як головний бібліотекар королівства, Мілтон Шіф допомагає зберегти писану спадщину людських королівств і всього Альянсу.",["race:Human"]="Мілтон оберігає століття людської історії — хроніки, що пережили падіння й відбудову Стормвінда."},sec={{t="Хранитель історії Стормвінда",b="У тихих залах Королівської Бібліотеки, що сховалася у Фортеці Стормвінда, Мілтон Шіф доглядає спільну пам'ять королівства. Поки нагорі двір вирує політикою, сварками вельмож і військовими турботами, Шіф дбає про збереження писаного слова. Вести правдиві літописи Альянсу й Східних Королівств він вважає священним обов'язком — надто в часи, сповнені війн, утрат і непевності."},{t="Пошуки загублених томів",b="Зберегти бібліотечне зібрання — справа нескінченна. Книжки зношуються, а цінні записи часто розкидані по всьому королівству — в монастирських архівах, на далеких заставах чи в забутих руїнах. Мілтон раз у раз відсилає шукачів пригод у мандри — від Абатства Нортшира до далекого північного поселення Саутшор, — щоб ті повернули загублені томи, дослідили давні тексти й подбали, аби рідкісні рукописи безпечно повернулися на полиці фортеці."}},faq={{q="Хто такий Мілтон Шіф?",a="Мілтон Шіф — учений і головний доглядач Королівської Бібліотеки у Фортеці Стормвінда. Він опікується книжковими зібраннями й літописами королівства.",al={"хто такий мілтон шіф","роль мілтона шіфа","бібліотекар стормвінда"}},{q="Де знайти Мілтона Шіфа?",a="Ви знайдете Мілтона Шіфа в крилі Королівської Бібліотеки у Фортеці Стормвінда, просто біля головних палацових коридорів.",al={"місце мілтона шіфа","де мілтон шіф","бібліотека стормвінда"}},{q="Навіщо Мілтонові Шіфу шукачі пригод?",a="Мілтон часто покладається на мандрівних шукачів пригод Альянсу: вони розшукують історичні рукописи, замінюють пошкоджені книги й зв'язуються з ученими та жерцями по всьому королівству, щоб поповнити архіви Королівської Бібліотеки.",al={"завдання мілтона шіфа","чого хоче мілтон","навіщо дає завдання"}},{q="Чи спілкується Мілтон Шіф з іншими вченими королівства?",a="Так. Він підтримує зв'язки з монастирськими архіваріусами й релігійними вченими, зокрема з Братом Пакстоном у Долині Нортширу, щоб зберігати священні вчення й історичні записи.",al={"мілтон нортшир","мілтон брат пакстон","зв'язки мілтона"}}},fp="12,335,36.437.0,21.461.0,20.184.0,30.119.0,39.214.0,62.171.0"}
P.entries["npc:miner-johnson"] = {n="Шахтар Джонсон",s="Шахтар Джонсон — невловимий бувалий гірник Братства Дефіас, що працює глибоко в Мертвих Копальнях. Сховавшись у бічній ніші поруч зі звичайними робітниками, цей небезпечний рудошукач наглядає за розкопками попереду важких машин, що стоять глибше під землею. Він блукає підземними тунелями без жодного ладу, тож шукачі пригод лише зрідка натрапляють на нього.",h="Шахтар Джонсон — невловимий бувалий гірник Братства Дефіас, що працює глибоко в Мертвих Копальнях.",kw={"шахтар джонсон","гірник","руда","мертві копальні","дефіас"},ang={["faction:Alliance"]="Убивши Джонсона, ви перервете рівний потік руди, що живить воєнну машину Дефіас, приховану під Мунбруком.",["profession:Mining"]="Для рудошукачів Джонсон — суворий і беззаконний бік підземної праці: багаті поклади глибоко під Вестфолом він стереже кров'ю й кайлом."},sec={{t="Рідкісне обличчя в глибинах",b="Поки сотні робітників довбають підземні жили Мертвих Копалень, постачаючи потаємну фортецю Едвіна Венкліфа, Шахтар Джонсон помітно вирізняється серед них грізною вдачею. Він причаївся в затіненій ніші ліворуч, перед незграбними потрощувачами Щоглової Кімнати, і значно міцніший та зліший за звичайних робітників. З'являється він непередбачувано, тож для дослідників тунелів Дефіас Джонсон став легендарною здобиччю."},{t="Паливо для воєнної машини Дефіас",b="Таємна справа Братства Дефіас під Мунбруком потребує безлічі руди, щоб кувати зброю, кріпити шахти й збирати механізми. Гірники на кшталт Джонсона — це м'язи за металом: вони рубають багаті рудні пласти під Вестфолом. Кожен, хто забреде до Джонсонового вибою, швидко переконається, що свою ділянку він обороняє зі смертельним завзяттям."}},faq={{q="Хто такий Шахтар Джонсон?",a="Шахтар Джонсон — рідкісний і особливо небезпечний шахтар-людина, союзник Братства Дефіас. Він працює глибоко в Мертвих Копальнях, у бічній ніші з іншими робітниками, перед гоблінським потрощувачем.",al={"лор шахтаря джонсона","хто такий шахтар джонсон","шахтар джонсон мертві копальні"}},{q="Де саме Шахтар Джонсон?",a="Він у верхніх штольнях Мертвих Копалень, перед залою, де стоїть Снід зі своїм потрощувачем. Шукайте невелику нішу для розкопок ліворуч, де гурт шахтарів завзято довбає скелю.",al={"місце шахтаря джонсона","де шахтар джонсон","як знайти шахтаря джонсона"}},{q="Чому Шахтаря Джонсона не завжди можна знайти?",a="Шахтар Джонсон з'являється рідко, тобто лише час від часу, коли експедиція заходить до Мертвих Копалень. Більшість загонів, що проходять штольнями, натрапить на його місці на звичайного шахтаря.",al={"шахтар джонсон не з'являється","чи шахтар джонсон рідкісний","поява шахтаря джонсона"}},{q="Чи пов'язаний Шахтар Джонсон з якимсь завданням?",a="Шахтар Джонсон не пов'язаний із жодною офіційною винагородою. Це просто щаслива зустріч для загонів, яким пощастить застати його за роботою в жилі.",al={"завдання шахтаря джонсона","чи є в нього завдання"}},{q="Яка роль Шахтаря Джонсона в Мертвих Копальнях?",a="Він досвідчений десятник чи майстер-копач, що допомагає Братству Дефіас добувати дорогоцінний метал, камінь і все потрібне, щоб звести величезну підземну базу й прихований броненосець.",al={"що робить шахтар джонсон","роль шахтаря джонсона"}},{q="Чи Шахтар Джонсон небезпечніший за інших шахтарів?",a="Так. Звичайні копачі в Мертвих Копальнях доволі вразливі, а Шахтар Джонсон — вправний боєць, що має значно більше життєвої сили й б'є значно сильніше, тож здолати його без ризику може лише злагоджений загін.",al={"наскільки складний шахтар джонсон","чи шахтар джонсон елітний"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Малий Прояв Землі",s="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі. Невидимий для звичайного зору, він відкривається лише шаманам-початківцям, що випили священну Земляну Сапту, і дає грубий кварц, потрібний, щоб вирізьбити їхній найперший тотем землі.",h="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі.",kw={"малий прояв землі","дух землі","земляна сапта","камінь кодо","камінь духів","тотем землі","шаман"},ang={["class:Shaman"]="Кожен молодий шаман Орди мусить поєднатися з Малим Проявом Землі під дією Земляної Сапти, щоб здобути свій найперший тотем.",["race:Tauren"]="Молоді таурени йдуть на схід через Малгор до Каменя Кодо, щоб шукати єднання з цим проявом як частину своїх прабатьківських духовних випробувань."},sec={{t="Голос каменю",b="Духи землі живуть усюди під ґрунтом і камінням, та щоб говорити з ними, потрібен свідомий ритуал. Біля священних місць на кшталт Каменя Кодо в Малгорі й Каменя Духів у Дуротарі Малі Прояви Землі перебувають у незримому світі в оточенні ще менших стихійних присутностей. Лише посвячені, що випили Земляну Сапту — ритуальний напій, зварений шаманськими наставниками, — здатні підняти завісу між тілесним світом і стихіями. Коли його визнано, дух дарує благословення землі та шматок грубого кварцу — духовне осердя, потрібне новачкові, щоб виготовити Тотем Землі."}},faq={{q="Чому я не бачу Малого Прояву Землі?",a="Прояв існує в царстві стихій і неозброєному оку невидимий. Треба випити Земляну Сапту, яку дає ваш наставник шаманів, щоб увійти в змінений стан сприйняття, потрібний, аби бачити духів стихій і говорити з ними.",al={"не бачу прояву","де дух землі","невидимий прояв землі"}},{q="Де шукати цих духів землі?",a="Вони з'являються біля Каменя Кодо на хвилястих рівнинах Малгору й біля Каменя Духів у посушливих каньйонах Дуротару. Обидва місця здавна служать випробувальними полігонами для молодих шаманів — тауренів, орків і тролів.",al={"місце малого прояву землі","де шукати прояв землі"}},{q="Яка мета духа під час обряду?",a="Прояв випробовує й урочисто визнає зв'язок послушника зі стихією землі. Поговоривши із шаманом, він дарує шматок необробленого кварцу, який несуть назад до наставника шаманів, щоб виготовити Тотем Землі.",al={"що робить прояв","мета завдання прояву"}},{q="Що за менші створіння довкола нього?",a="Довкола головного духа — менші прояви землі. Це слабкі відгомони стихії, яких притягли священні місця: вони існують лише як частина природного єднання, і взаємодіяти з ними напряму не можна.",al={"менші прояви","маленькі елементалі землі довкола"}}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="Малий Прояв Води",s="Малий Прояв Води — дух стихії, який можна знайти біля Потоку Північного Припливу на узбережжі Срібнолісся. Для шаманів Орди, що прагнуть порозумітися зі стихією води й опанувати її, це важливе випробування. Перш ніж звернутися до цього мирного духа, учні мають очистити його зіпсованого двійника.",h="Малий Прояв Води — дух стихії, який можна знайти біля Потоку Північного Припливу на узбережжі Срібнолісся.",kw={"малий прояв води","потік північного припливу","шамани","тотем води","елементалі","срібнолісся"},ang={["class:Shaman"]="Очистити цього елементаля від скверни й отримати його благословення — останній рубіж на шляху до злагоди з припливами й створення вашого Тотема Води.",["faction:Horde"]="Шамани-тролі, орки й таурени долають шлях аж із Калімдору до берегів Лордерона, щоб поспілкуватися з цим духом."},sec={{t="Дух західних припливів",b="Малий Прояв Води, що перебуває на оповитих туманом берегах Потоку Північного Припливу на захід від Гробниці в Срібноліссі, — важливий обряд посвяти для шаманів, які набираються досвіду. Водяні елементалі втілюють життя, оновлення й плинність, але легко стають жертвами злісної скверни. Учень мусить зійтися з зіпсованим проявом цього елементаля й здолати його, перш ніж чистий Малий Прояв Води зможе показатися. Очищений дух дає настанови шаманам, що завершують свою священну мандрівку, аби створити Тотем Води."}},faq={{q="Де знайти Малий Прояв Води?",a="Малий Прояв Води з'являється біля Потоку Північного Припливу, на західному узбережжі Срібнолісся, трохи на захід від Гробниці.",al={"місце малого прояву води","де прояв води","елементаль північного припливу"}},{q="Чому елементаль ворожий, коли я вперше підходжу?",a="Шаман мусить спершу викликати й знищити Зіпсований Малий Прояв Води. Лише після того, як зіпсовану сутність переможено, з'являється мирний прояв, щоб поговорити з вами.",al={"зіпсований малий прояв","чому прояв води сердитий","прояв води нападає на мене"}},{q="Яке завдання пов'язане з цим елементалем?",a="Цей дух — важлива ланка в ланцюжку завдань шаманів «Поклик Води», у якому шамани зрештою здобувають уміння ставити Тотем Води.",al={"завдання поклик води","завдання тотема води сільверпайн","для якого це завдання"}},{q="Чи можуть з цим духом спілкуватися ті, хто не шаман?",a="Малий Прояв Води існує саме для того, щоб наставляти шаманів, які проходять духовні випробування. Іншим шукачам пригод немає особливих причин із ним спілкуватися.",al={"чи це лише для шамана","чи хтось може говорити з проявом","хто говорить із малим проявом"}}},fp="28,323,29.559.0,50.134.0,51.182.0,35.152.0,42.167.0"}
P.entries["npc:misha"] = {n="Міша",s="Міша — вірна ведмедиця-супутниця Рекссара, Чемпіона Орди. Він урятував її ще осиротілим ведмежам, і відтоді вона невідступно мандрує Калімдором поруч із цим повелителем звірів з народу мок'натал.",h="Міша — вірна ведмедиця-супутниця Рекссара, Чемпіона Орди.",kw={"міша","рекссар","ведмідь","чемпіон орди","мок'натал","пустограй","фералас"},ang={["class:Hunter"]="Для мисливців Міша — найвищий ідеал тварини-супутника: нерозривне, довічне партнерство, що тримається на взаємній повазі, а не на самому лише пануванні.",["faction:Horde"]="Міша билася поруч із Рекссаром за свободу молодої Орди на Острові Терамор і заслужила мовчазну повагу ветеранів по всьому Дуротару."},sec={{t="Нерозривні узи",b="Рекссар знайшов Мішу осиротілим ведмежам біля тіла вбитої матері в Руїнах Рейвенвінду у Фераласі. Упізнавши в ній таку саму самотню душу, мандрівний мок'натал прихистив її й дав їй ім'я. Разом вони рушили на північ, у посушливу глушину Пустограю, і стали відданими захисниками одне одного — цей союз пережив незліченні дикі краї та криваві битви."},{t="Захисниця Дуротару",b="Міша — аж ніяк не ручна тваринка, а досвідчена воїтелька. Вона билася пліч-о-пліч з Рекссаром у жорстокій війні проти великого адмірала Дейліна Праудмура на Острові Терамор і допомогла молодій Орді вижити. Поза боєм її гострі чуття й сила стають продовженням Рекссарової волі: вона навіть приносила до Оргріммара полеглих союзників, як-от орка Байрока."},{t="Дикі простори Калімдору",b="Нині мандрівники, що йдуть довгими стежками через Гори Кам'яного Кігтя, Пустограй і Фералас, можуть побачити Мішу, яка тихо ступає поруч із Рекссаром. Вона досить люта, щоб розірвати будь-якого хижака, якому стане дурості їм загрожувати, — та для Рекссара вона лишається надійною опорою у світі, якому більше ні в чому не можна довіряти."}},faq={{q="Хто така Міша?",a="Міша — люта бура ведмедиця й незмінна супутниця Рекссара, Чемпіона Орди. Вона мандрує дикими краями центрального Калімдору разом із ним.",al={"ведмідь рекссара","хто ведмідь із рекссаром","ведмідь міша"}},{q="Де Рекссар знайшов Мішу?",a="Рекссар знайшов Мішу ще маленьким ведмежам у Руїнах Рейвенвінду у Фераласі, біля мертвої матері. Побачивши, що вони обоє самотні в дикій природі, Рекссар узяв її до себе.",al={"де рекссар узяв мішу","минуле міші","як рекссар зустрів мішу"}},{q="Де зараз можна знайти Мішу?",a="Міша ходить довгими стежками Гір Кам'яного Кігтя, Пустограю й Фераласу, вірно супроводжуючи Рекссара в його нескінченних мандрах.",al={"місце міші","де міша","знайти мішу"}},{q="Чи брала Міша участь у заснуванні Дуротару?",a="Так. Після Третьої війни Міша разом із Рекссаром билася з військами Великого Адмірала Дейліна Праудмура на Острові Терамор, захищаючи молоду Орду.",al={"міша терамор","чи міша воювала з даеліном","міша третя війна"}},{q="Чи ворожа Міша до гравців Альянсу?",a="Так. Як супутниця Чемпіона Орди, Міша люто захищатиме Рекссара й нападе на кожного чужинця з Альянсу, що підійде надто близько.",al={"чи можна нападати на мішу","чи міша агресивна"}},{q="Чому Рекссар воліє товаришувати зі звірами на кшталт Міші, а не з людьми?",a="Розчарувавшись в обмані й війнах людиноподібних народів, Рекссар обрав самотність дикої природи. Він вірить, що звірі прямі й чесні, і знайшов у Міші супутницю, яка ніколи не зрадить.",al={"чому рекссар тримає звірів","ведмідь-супутник рекссара"}}},fp="5,169,16.366.0,19.372.0,17.310.0,13.157.0,28.170.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="Міша Тор'крен",s="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від Громового Хребта. Змучена тривогою за зниклого сина Крона, вона просить перехожих мандрівників допомогти дізнатися його долю.",h="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від...",kw={"міша тор'крен","крон","ферма тор'крена","кроколіски","південна лють","мати","дуротар"},ang={["class:Hunter"]="Доля сина Міші показує, як небезпечно недооцінювати річкових хижаків, доки мисливець по-справжньому не опанував дику природу.",["race:Orc"]="Безрозсудне бажання Крона довести свою воїнську вправність на звірині Дуротару — сумне нагадування про високу ціну юнацької гордості."},sec={{t="Материнське чекання",b="Сховавшись край Громового Хребта, Міша Тор'крен порається на відлюдному хуторі й переживає найгірший страх кожного з батьків. Її син Крон подався на захід, до Річки Південної Люті, полювати на кроколісків і довести свою вправність — та так і не повернувся. Поки небезпеки прикордоння Дуротару розтягують сторожові вежі орків до межі, Міша лишається сама з надією на звістку про нього й відчайдушно шукає будь-кого, хто погодиться обшукати береги річки в пошуках слідів її хлопчика."},{t="Похмурий знак",b="Річка Південної Люті безжальна до молодих мисливців. Ті, хто прочісує її багнисті береги, неминуче дізнаються, що Крон став жертвою лютих річкових кроколісків. Повернення його врятованого амулета — єдине заспокоєння, яке може отримати Міша: гірке нагадування про жорстокі випробування, через які молоді орки доводять свою силу в суворих нетрях Калімдору."}},faq={{q="Хто така Міша Тор'крен?",a="Міша Тор'крен — орчиха-поселенка, що живе на Фермі Тор'крена на заході Дуротару, трохи на південний схід від Громового Хребта.",al={"міша тор'крен","хто така міша","власниця ферми тор'крен"}},{q="Куди подівся її син Крон?",a="Крон вирушив на захід, до Річки Південної Люті, полювати на річкових кроколісків, прагнучи довести, що він вправний мисливець, але додому не повернувся.",al={"де крон","що сталося з кроном","син міші"}},{q="Що відбувається, коли шукаєш Крона?",a="Міша посилає шукачів пригод шукати Крона вздовж річки. Його зникнення тяжко гнітить її, і їй потрібен хтось, хто обшукає ті місця.",al={"чи крон мертвий","знайти крона","загублений, але не забутий"}},{q="Чи вона пов'язана з Мішею, ведмедицею Рекссара?",a="Ні. Хоча обидві звуться Мішами, вона — орчиха-фермерка з Дуротару, ніяк не пов'язана з вірною супутницею-ведмедицею Рекссара.",al={"ведмідь міша","міша рекссара","чи вона ведмедиця"}}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:mitsuwa"] = {n="Міцува",s="Міцува — троль Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі Ашенвалю. Глибоко вражений засідкою на своїх родичів-мандрівників, він кличе звитяжців Орди помститися за полеглих і повернути викрадені духовні талісмани.",h="Міцува — троль Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі Ашенвалю.",kw={"міцува","тролі","темний спис","тролячі обереги","фурболги","застава зорам'гар"},ang={["faction:Horde"]="Застава Зорам'гар — відрізаний і обложений гарнізон; допомагаючи Міцуві, ви зміцнюєте хитку присутність Орди проти диких звірів і розвідників Альянсу на західних околицях Калімдору.",["race:Troll"]="Заклик Міцуви до зброї глибоко зачіпає серце кожного шукача пригод із Темного Спису: повернувши священні обереги предків від брутальних фурболгів-грабіжників, ви даруєте спокій убитим братам і сестрам."},sec={{t="Помста за полеглих родичів",b="Міцува служить Орді на віддаленій Заставі Зорам'гар на Зорамському Узмор'ї разом зі своєю товаришкою Марукай. Коли загін тролів, що йшов до табору, потрапив у засідку й загинув від рук агресивних фурболгів Будякохутрих на півночі Ашенвалю, Міцува сприйняв цю втрату як тяжку образу. Ведений обов'язком і гнівом, він посилає здатних воїнів до лігв Будякохутрих, щоб повернути викрадені тролячі обереги, — аби вшанувати духів родичів і вирвати їхні священні речі з лап звірів."}},faq={{q="Хто такий Міцува?",a="Міцува — троль із джунглів, із Темного Спису, що живе на Заставі Зорам'гар на північному заході Ашенвалю. Він пильнує цю прикордонну заставу разом зі своєю товаришкою Марукай і організовує відплату ворожим загрозам у краї.",al={"міцува","хто такий міцува","лор міцуви"}},{q="Що сталося з тролями, які прямували до Зорам'гару?",a="Загін тролів, що йшов через Ашенваль підсилити Заставу Зорам'гар чи навідатися туди, потрапив у засідку місцевих фурболгів-будякошерстих: ті перебили мандрівників і забрали їхні особисті речі.",al={"мертві тролі ясенлісся","напад тістлфур на тролів"}},{q="Чому тролячі амулети такі важливі для Міцуви?",a="Амулети мають духовне й культурне значення для племені Темного Спису. Залишити священні реліквії в лапах будякошерстих після жорстокої різанини — тяжка образа для духів загиблих.",al={"чому тролячі амулети","причина завдання амулетів"}},{q="Де шукати амулети?",a="Будякохутрі фурболги віднесли амулети до свого селища й смердючого лігва на півночі Ашенвалю, на схід від Берега Зорам.",al={"де тролячі амулети","село тістлфур"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {n="Монте Ґазлоу",s="Монте Ґазлоу — практичний гоблінський інженер і очільник, який заснував портове містечко Раджет і править ним. Відслуживши головним інженером Орди, коли засновували Дуротар і Оргріммар, він вклав чималі заробітки в гамірний нейтральний торговий вузол картелю Стімвідл.",h="Монте Ґазлоу — практичний гоблінський інженер і очільник, який заснував портове містечко Раджет і править ним.",kw={"монте ґазлоу","раджет","картель стімвідл","гобліни","інженер","оргріммар"},ang={["faction:Alliance"]="Ґазлоу байдуже, хто сидить на троні Стормвінда і які чвари ви привезли зі Східних Королівств: поки ваше золото справжнє, а клинок у піхвах, Раджет радий вас бачити.",["faction:Horde"]="Хоч він, як і кожен порядний гоблін, вимагає з вас монету, Ґазлоу — вірний союзник Тралла відтоді, як вляглася курява Третьої війни: він допомагав закладати саме підмурівки вашої столиці.",["profession:Engineering"]="Ґазлоу — один із найкращих умів гоблінської інженерії в Калімдорі: він опікується всім, від міських водогонів до швидкісних перегонових машин на Перегонах Міражу.",["race:Orc"]="Воду в Оргріммарі орки мають саме завдяки саперам Ґазлоу, і він досі тримає своїх гоблінських механіків у Дуротарі, щоб допомагати з важкими будівництвами."},sec={{t="Мозок Раджета",b="Ґазлоу родом із гоблінського мегаполіса Андермайн — міста, яке він зрештою зненавидів, бо там кожну тяжко зароблену монету крали, а кожну творчу ідею душили суперники. Утікши разом з іншими честолюбними гоблінами за Велике море до Калімдору, він збудував собі зовсім нове життя. Отримавши щедру платню за інженерну роботу для нової Орди, Ґазлоу вклав гроші просто в голе узбережжя й заснував порт Раджет. Працюючи під крилом картелю Стімвідл, він тримає це припортове містечко суворо нейтральним: тут Орда, Альянс і вільні торговці можуть спокійно торгувати — аби лиш зброя лишалася в піхвах, а гаманці були повні."},{t="Інженер Орди",b="Після Третьої війни Вождь Тралл найняв Ґазлоу головним інженером Дуротару, щоб розв'язати нагальні проблеми з облаштуванням молодої оркської столиці. Ґазлоу взявся за небезпечну роботу — забезпечити Оргріммар прісною водою — і прокопав довгі тунелі, що ненароком прорвалися в підземні нори кобольдів. Завдяки вчасній допомозі мандрівного володаря звірів Рекссара Ґазлоу зумів підірвати й завалити печери та завершити роботу. Він і досі улюблений підрядник і друг Тралла й навіть відрядив свого виконроба Резлака, щоб той допомагав оркам на будівництвах по всьому Дуротару."},{t="Клопоти на Узбережжі Крамарів",b="Хоч справи в Раджеті й прибуткові, Ґазлоу постійно має головний біль через морських конкурентів і злодіїв. Флібустьєри Південних морів облаштували табори на сусідньому Узбережжі Крамарів й перехоплюють вантажі для Раджета, крадучи все — від сирої руди до замовлених Ґазлоу чобіт. Щоб захистити свої прибутки, господар порту раз у раз наймає мандрівних найманців будь-якої приналежності: вичищати піратські табори, повертати вкрадені вантажі й зводити рахунки з портовими бешкетниками."}},faq={{q="Хто такий Ґазлоу?",a="Ґазлоу — гоблін-бос і господар Раджета, головного торгового порту на узбережжі Пусток. Родом з Андермайну, він розбагатів як головний інженер, що керував будівництвом Оргріммара, а потім заснував Раджет як відкриту нейтральну гавань під орудою картелю Стімвідл.",al={"хто такий ґазлоу","лор ґазлоу","бос раджета"}},{q="Ґазлоу вірний Орді чи Альянсу?",a="Офіційно Ґазлоу цілком нейтральний: він керує Раджетом під орудою картелю Стімвідл і відкриває пристань для мандрівників і з Альянсу, і з Орди. Утім, його пов'язують із Вождем Траллом близькі особисті стосунки й вигідна спільна історія, адже він сам спроєктував важливі частини поселень Дуротару.",al={"чи ґазлоу з орди","чи раджет нейтральний","фракція ґазлоу"}},{q="Що Ґазлоу збудував у Дуротарі?",a="Коли засновували Дуротар, Вождь Тралл найняв Ґазлоу головним інженером. Ґазлоу керував прокладанням тунелів, щоб знайти підземне водосховище для Оргріммара. Коли гірники ненароком випустили рій ворожих кобольдів, Ґазлоу найняв Рекссара, щоб той допоміг саперам запечатати тунелі.",al={"ґазлоу оргріммар","ґазлоу тал","водопостачання ґазлоу"}},{q="Навіщо Ґазлоу наймає шукачів пригод у Раджеті?",a="Ґазлоу постійно потребує найманих бійців проти Флібустьєрів Південних морів, що отаборилися на Узбережжі Крамарів й раз у раз грабують вантажі, призначені для пристані Раджета. Він платить мисливцям за головами, щоб ті знищували піратів, повертали викрадені накладні й розшукували зниклі вантажі.",al={"завдання ґазлоу","вільні торговці південних морів раджет","проблеми ґазлоу"}},{q="Що пов'язує Ґазлоу з Перегонами Міражу?",a="Ґазлоу — палкий шанувальник інженерії й швидкості. Він спонсорує гоблінські команди, що змагаються з гномами в Мерехтливих Низинах у Тисячі Голок: допомагав будувати їхню перегонову машину й намагається роздобути дослідні регулятори пального.",al={"ґазлоу мерехтливі низини","ґазлоу тисяча голок","ґазлоу перегони"}},{q="Чому Ґазлоу покинув Андермайн?",a="Ґазлоу ненавидів Андермайн, бо чесне підприємництво й кмітлива інженерія там щоразу наражалися на вимагання, крадіжки й диверсії конкурентів. Переконаний, що в цьому місті немає майбутнього для того, хто хоче зберегти власний заробіток, він перебрався зі своїм хистом до Калімдору й поклявся ніколи не озиратися назад.",al={"андермайн ґазлоу","минуле ґазлоу"}}},fp="13,304,25.665.0,22.613.0,29.508.0,15.302.0,46.298.0,34.309.0,45.286.0,51.236.0,32.289.0"}
P.entries["npc:moon-priestess-amara"] = {n="Місячна Жриця Амара",s="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в Тельдрассилі. Оточена вірними охоронницями-мисливицями, вона пильнує лісові шляхи, що з'єднують серце гілки зі столицею — Дарнасусом.",h="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в...",kw={"місячна жриця амара","жриця","сестринство елуни","доланаар","дарнасус","дорога","тельдрассил"},ang={["class:Priest"]="Як членкиня Сестринства Елуни Жриця Амара втілює нічноельфійську відданість Місячній Богині й слугує душпастиркою та духовною провідницею молодих послушників, що вирушають із Тінедолу.",["race:NightElf"]="Амара позначає важливу віху на вашому шляху від Доланаара, даючи настанови й доручення, що ведуть до великого міста Дарнасус."},sec={{t="Охоронниця лісових шляхів",b="Перебуваючи на тихому придорожньому посту на захід від Доланаара, Місячна Жриця Амара уособлює і духовну владу Сестринства Елуни, і практичну пильність, потрібну, щоб дороги Тельдрассила були безпечними. Вона подорожує й пильнує з двома супутницями-мисливицями, Нгемай і Яеліурою. Для подорожніх, що прямують на захід, Амара — провідна рука: вона спрямовує шукачів пригод дорогою до Дарнасуса, а тим, чий дух обтяжений, доручає шукати шляхів спокути."}},faq={{q="Хто така Місячна Жриця Амара?",a="Місячна Жриця Амара, відома у варті як Амара Найтволкер, — жриця Сестринства Елуни, що несе службу на дорозі між Доланааром і Дарнасусом на Тельдрассилі. Вона дбає про безпеку й духовне здоров'я мандрівників, що проходять гілкою.",al={"хто така амара","жриця амара","вартова амара"}},{q="Де знайти Місячну Жрицю Амару?",a="Вона на мощеному шляху трохи на захід від Доланаара на Тельдрассилі, вартує поруч із двома мисливицями з Вартових.",al={"місце амари","де амара","карта жриці амари"}},{q="Хто ці мисливиці, що стоять поруч із нею?",a="Її охороняють і супроводжують Мисливиця Немай і Мисливиця Яеліура — дві нічні ельфійки з Вартових, що допомагають боронити шлях від звірів і ворожої скверни.",al={"супутниці амари","нхемай і яеліура","охорона амари"}}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:mor-rogal"] = {n="Мор'роґал",s="Мор'роґал — таурен, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він радник і провідник для мандрівників, які шукають слави й небезпеки в суворих підземних закутках скель.",h="Мор'роґал — таурен, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",kw={"мор'роґал","притулок сонячної скелі","яр кам'яного зсуву","таурени","печери","гори кам'яного кігтя"},ang={["faction:Horde"]="Для мандрівників, що дісталися Притулку Сонячної Скелі, Мор'роґал — джерело важливих відомостей про загрози, що чатують серед скель за межами поселення.",["race:Tauren"]="Мор'роґал утілює тауренську шану до випробувань тіла й духу: глибокі кам'яні порожнини Калімдору для нього — священна земля, де можна довести свою гідність."},sec={{t="Спостерігач серед скель",b="Мор'роґал, що живе в Притулку Сонячної Скелі, пильно цікавиться глибокими розколинами й печерами, що прорізають Гори Кам'яного Кігтя. Розуміючи, що звивисті підземні ходи краю ховають і великі багатства, і смертельну небезпеку, він посилає сміливих мандрівників з Орди розвідати неспокійні місця на кшталт Яру Кам'яного Зсуву. Для Мор'роґала спуститися в ці підступні глибини — не лише справа виживання, а й випробування духу для тих, хто йде за серцем і душею в пошуках слави."}},faq={{q="Хто такий Мор'роґал?",a="Мор'роґал — таурен, що дає завдання в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він місцевий провідник, що закликає шукачів пригод Орди випробувати себе в небезпечних печерах і ярах, розкиданих по цьому скелястому кряжу.",al={"морроґал","хто такий мор'роґал","лор мор'роґала"}},{q="Де знайти Мор'роґала?",a="Він стоїть у Притулку Сонячної Скелі — головній заставі Орди, захованій серед вершин центральної частини Гір Кам'яного Кігтя.",al={"місце мор'роґала","де мор'роґал","точка мор'роґала"}},{q="Які доручення дає Мор'роґал?",a="Мор'роґал залучає вправних поборників спуститися до печери в Яру Кам'яного Зсуву, де кобольди гарячково видобувають кристали резоніту, а потім убити Ґоґґерока — сплячого землянина, якого відкопали кобольди.",al={"завдання мор'роґала","чого хоче мор'роґал"}},{q="Чому Мор'роґал зосереджений на печерах і ярах?",a="Мор'роґал вважає, що в небезпечних підземних печерах Гір Кам'яного Кігтя чекають справжні пригоди й випробування духу, які приносять славу й багатство тим, хто готовий ризикнути життям.",al={"чому печери","мор'роґал печери"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.0,46.188.0"}
P.entries["npc:morgan-pestle"] = {n="Морґан Пестл",s="Морґан Пестл — алхімік-людина й крамар, що тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда. Він тісно співпрацює зі своїм братом Вільямом Пестлом із Ґолдширу й відає постачанням та алхімічними дослідженнями для столиці.",h="Морґан Пестл — алхімік-людина й крамар, що тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда.",kw={"морґан пестл","аптека пестла","алхімік","торговий квартал","вільям пестл","стормвінд"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що прибувають до Стормвінда з Елвінна, крамниця Морґана — неминуча зупинка: тут знайдеться потрібне з алхімії, а ще можна взяти місцеві доручення з доставки містом.",["profession:Herbalism"]="Морґан значною мірою покладається на свіжі трави, зібрані в Лісі Елвінн і далі, щоб постачати свою аптеку в Торговому Кварталі."},sec={{t="Міська аптека",b="Зі своєї «Аптеки Пестла» на жвавих вулицях Торгового Кварталу Стормвінда Морґан Пестл постачає алхімічні товари, реагенти й перевірені ліки містянам і подорожнім. Поки його брат Вільям тримає майстерню в корчмі «Лев'яча Гордість» у Ґолдширі, Морґан береже родинне ремесло в самому серці столиці королівства й налагоджує перевезення трав і сумішей між містом і сільськими серцевими землями."}},faq={{q="Де знайти Морґана Пестла?",a="Морґан Пестл — в «Аптеці Пестла», крамниці в Торговому Кварталі Стормвінда.",al={"місце морґана пестла","де морґан пестл","аптека пестла стормвінд"}},{q="Ким Морґан Пестл доводиться Вільямові Пестлу?",a="Морґан і Вільям Пестли — брати. Обидва алхіміки в Елвінні: Морґан тримає їхню крамницю в Стормвінді, а Вільям працює в Ґолдширі.",al={"брат вільяма пестла","чи вільям і морґан родичі","брати пестл"}},{q="Яку роль він відіграє в завданнях Елвінна?",a="Морґан приймає вантажі й алхімічні припаси, які його брат Вільям надсилає на північ із Ґолдшира, пов'язуючи збирання місцевих трав із міською торгівлею.",al={"доставка до стормвінда морґан","завдання морґана пестла"}}},fp="13,242,19.456.0,31.100.0,47.156.0,40.175.0"}
P.entries["npc:morgan-the-collector"] = {n="Морґан Збирач",s="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі Елвінн. Отаборившись на захопленій Гарбузовій Ділянці Брекуеллів, він координує місцеве злодійство просто під носом у варти Ґолдширу.",h="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі...",kw={"морґан збирач","дефіас","гарбузова ділянка","перстень","гільдія каменярів","здирництво"},ang={["class:Rogue"]="Морґан показує, як організована злочинна дисципліна перетворює розрізнених злодіїв на дієвий підпільний синдикат, здатний фінансувати заколот.",["race:Human"]="Знищення Морґана — удар у відповідь зрадникам, що перетворили мирні ферми Стормвінда на укріплені бандитські лігва."},sec={{t="Данина Елвінну",b="Морґан заслужив своє прізвисько, витискаючи соки з віддалених ферм Лісу Елвінн від імені Братства Дефіас. Поки звичайні бандити чіпляються до подорожніх на дорогах, Морґан керує організованими здирствами й збирає крадену монету та припаси, щоб спрямувати їх углиб мережі Братства. Свій штаб він улаштував у будинку на Гарбузовій Ділянці Брекуеллів, оточивши себе вірними посіпаками, серед яких Сурена Каледон і Ерлан Драджмур."},{t="Перстень минулого",b="Справи Морґана — не прості вуличні злочини: він носить особливий перстень-печатку, що позначає його владу. Для слідчих у Ґолдширі цей перстень — твердий доказ, що пов'язує замаскованих злодіїв, які тероризують серце королівства, зі зганьбленою Гільдією Каменярів, що відбудувала Стормвінд після Другої війни. Здобутий перстень пробиває завісу таємниці над тим, хто насправді керує бандитами в лісах."}},faq={{q="Хто такий Морґан Збирач?",a="Це офіцер Братства Дефіас, що відповідає за вимагання грошей і припасів у хуторян Лісу Елвінн і керує бандитськими справами в краї.",al={"хто такий морґан","лор морґана","збирач в елвінні"}},{q="Де знайти Морґана?",a="Він ховає награбоване в покинутій хаті на Гарбузовій Ділянці Брекуеллів на сході Лісу Елвінн.",al={"місце морґана","де морґан збирач","будинок на гарбузовому полі бракуелла"}},{q="Чому Стормвінд полює на нього?",a="Маршал Дуґан і місцева влада хочуть позбутися Морґана, щоб обезголовити Дефіас в Елвінні й здобути докази того, хто організовує заворушення по селах.",al={"чому вбивати морґана","ціль полювання"}},{q="Що особливого в персні, який він носить?",a="Морґан носить перстень-печатку, що слугує доказом для влади, яка розслідує його справи в Лісі Елвінн.",al={"перстень збирача","печатка збирача","лор персня морґана"}}},fp="20,262,19.448.0,20.411.1,28.163.0,22.123.0,29.156.0,42.119.1"}
P.entries["npc:morin-cloudstalker"] = {n="Морін Клаудсталкер",s="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток у Малгорі. Пильнуючи рівнини, він стежить за місцевими торговими шляхами й розслідує загрози, що насуваються на тауренських мандрівників.",h="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток...",kw={"морін клаудсталкер","розвідник","село бладгуф","малгор","венчурна компанія","караван"},ang={["faction:Horde"]="Морін дає звитяжцям Орди першу нагоду захистити припаси й священні землі своїх нових тауренських союзників.",["race:Tauren"]="Для тауренів, що вирушають із Села Бладгуф у великий світ, Морін уособлює пильну оборону вашої батьківщини — і від зухвалих розбійників, і від корпоративних осквернителів."},sec={{t="Вартовий південного шляху",b="Ставши край ґрунтової дороги, що в'ється на схід до Пусток, Морін Клаудсталкер водночас розвідник і охоронець для подорожніх Малгору. Трав'янисті рівнини тут зазвичай мирні, але відкриття торгових шляхів і зрушення кордонів привабили пройдисвітів і розбійників небезпечно близько до серця тауренської батьківщини."},{t="Розслідування каравану",b="Розвідники Моріна нещодавно напали на караван Венчурної Компанії на північному березі Озера Кам'яного Бика й спалили його. Коли поблизу обгорілих возів помітили гоблінів-збирачів, він послав шукачів пригод оглянути вцілілі ящики з припасами й дізнатися, що саме везла Венчурна Компанія."},{t="Оборона від Венчурної Компанії",b="Окрім звичайних грабіжників, Моріна глибоко турбує промислова присутність Венчурної Компанії, що розгортає діяльність у Малгорі. Він спрямовує шукачів пригод з Орди, які проходять повз, на їхні лісозаготівлі та шахтарські застави й вказує на ключових ватажків — таких як Наглядач Фіззпрокет, — щоб зупинити спустошення природи, яке загрожує священним рівнинам."}},faq={{q="Де знайти Моріна Клаудсталкера?",a="Морін Клаудсталкер стоїть біля ґрунтової стежки на схід від Села Бладгуф у Малгорі, при дорозі, що веде до Пусток.",al={"місце моріна","де морін","карта моріна клаудсталкера"}},{q="Яка роль Моріна в Малгорі?",a="Він пильний тауренський розвідник, що стежить за мандрівниками на півдні Малгору й організовує оборону від бандитів і непроханих гостей-ділків.",al={"хто такий морін клаудсталкер","роль моріна"}},{q="Чому Морін досліджує розгромлений караван?",a="Розвідники Моріна напали на караван Венчурної Компанії біля Озера Кам'яного Бика й спалили його. Коли біля уламків помітили гоблінів-мародерів, він попросив шукачів пригод оглянути вцілілі ящики з припасами, щоб з'ясувати, що перевозила Венчурна Компанія.",al={"завдання розгромленого каравану","напад на караван малгор"}},{q="Чому Морін хоче зупинити Венчурну Компанію?",a="Венчурна Компанія машинами й вирубкою лісів виснажує природні багатства Малгору. Морін прагне зірвати їхню руйнівну справу, знищивши їхніх наглядачів, зокрема Наглядача Фіззпрокета.",al={"венчурна компанія малгор","чому вбивати фізспрокета"}},{q="Кому звітує Морін?",a="Морін діє від імені старійшин і вождів Села Бладгуф та ширшої тауренської верхівки Малгору.",al={"вірність моріна","хто послав моріна"}},{q="Чи дає Морін завдання гравцям Альянсу?",a="Ні. Морін вірний лише Орді й спілкується тільки з шукачами пригод Орди.",al={"чи альянс може говорити з моріном","фракція моріна"}}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:motega-firemane"] = {n="Мотеґа Фаєрмейн",s="Мотеґа Фаєрмейн — тауренський учений із Застави Білого Рубежу в Тисячі Голок. Він присвятив себе описуванню небезпечних звірів каньйону, проте його дослідження раз у раз перериває мстивий дух вітряного змія та безрозсудні пригоди його юного помічника.",h="Мотеґа Фаєрмейн — тауренський учений із Застави Білого Рубежу в Тисячі Голок.",kw={"мотеґа фаєрмейн","застава білого рубежу","арікара","пао'ка","тисяча голок","вітряний змій"},ang={["class:Hunter"]="Мисливці легко знаходять спільну мову з Мотеґою, бо він покладається на вправних слідопитів: вони збирають рослини каньйону, вистежують віверн у Високосіді й полюють на могутнього духа Арікару.",["faction:Horde"]="Мотеґа уособлює поступ Орди в неприборкані краї Калімдору: він тримає хитку дослідницьку заставу й водночас оберігає Верховного Вождя Кайрна Бладгуфа від загроз світу духів.",["race:Tauren"]="Шануючи природу й віддано служачи Кайрнові Бладгуфу, Мотеґа втілює тауренський ідеал: вивчати створіння Земної Матері й захищати плем'я від прадавніх духів."},sec={{t="Учений каньйонів",b="Через чотири роки після Третьої війни Мотеґа Фаєрмейн вирушив на південь, у Тисячу Голок, щоб спостерігати й описувати незвичних звірів, які виживають серед височенних столових гір. Разом зі своїм юним помічником Пао'кою Свіфтмаунтіном — чий надміру дбайливий батько неохоче відпустив сина з Малгору — Мотеґа розбив табір поряд із Канаті Ґрейклаудом на Заставі Білого Рубежу. Він прийшов сюди заради тихих спостережень за природою, але суворі небезпеки на дні каньйону раз у раз вимагають від нього радше бойового підходу до виживання."},{t="Гнів Арікари",b="Мирні дослідження Мотеґи урвалися, коли із Застави Вільного Вітру надійшла звістка: в каньйони повернувся Арікара — лютий легендарний дух крилатого змія, що жадає помсти Кайрнові Бладгуфу. Мотеґа так і не збагнув, чому ця істота має зуб на Верховного Вождя, але діяв швидко, щоб захистити Орду. Він доручив розвідникам зібрати в улоговині каньйону агаву інсендію й віднести її старійшині Маґаті Ґрімтотем у Тандер Блаф, щоб та зачарувала її на священний порошок. За допомогою цього зілля мисливці викликали й убили духа змія, а його шкуру принесли на Заставу Білого Рубежу на доказ того, що Кайрн у безпеці."},{t="Охоронець Білого Рубежу",b="Арікара був не єдиною небезпекою, що загрожувала Мотеґі на Заставі Білого Рубежу. Місцеві кентаври Ґалак раз у раз прощупували табір і навіть замишляли вбити Канаті Ґрейклауда та його послідовників. На додачу юний Пао'ка відійшов від безпечного вогнища й зник у Високосіді, де аж кишать віверни. Хоч Мотеґа й сердився на легковажність молодого сміливця, він відчув величезне полегшення, коли мандрівники з Орди привели юнака назад живим."}},faq={{q="Хто такий Мотеґа Фаєрмейн?",a="Мотеґа Фаєрмейн — таурен-дослідник на Заставі Білого Рубежу в Тисячі Голок. Він прибув до каньйонів вивчати місцевих тварин разом з іншими воїнами й своїм помічником Пао'кою Свіфтмаунтіном.",al={"лор мотеґи фаєрмейна","хто такий мотеґа","мотеґа біла застава"}},{q="Де знайти Мотеґу Фаєрмейна?",a="Він на Заставі Білого Рубежу — невеликому таборі Орди на дні каньйону в Тисячі Голок, на північ від мерехтливих соляних низин.",al={"місце мотеґи","де мотеґа фаєрмейн","карта мотеґи"}},{q="Чому Мотеґу тривожить Арікара?",a="Арікара — мстивий дух змія, що з'явився в Тисячі Голок і полює на Кайрна Бладгуфа. Хоча Мотеґа не розуміє, чим Верховний Вождь заслужив злобу духа, він сприймає загрозу всерйоз і посилає мисливців викликати й знищити цю істоту.",al={"хто така арікара","чому вбивати арікару","арікара кайрн"}},{q="Яку роль у задумах Мотеґи відіграє Маґата Ґрімтотем?",a="Мотеґа доручає шукачам пригод зібрати агаву Інсендія й віднести її Маґаті Ґрімтотем на Узвишшя Старійшин у Тандер Блафі. Маґата завдяки своїм шаманським знанням зачаровує рослину й перетворює її на священний порошок, яким можна викликати невловну Арікару.",al={"порошок підпалу маґати","мотеґа й маґата","лор священного вогню"}},{q="Що сталося з супутником Мотеґи, Пао'кою?",a="Пао'ка Свіфтмаунтін забрів до небезпечних гнізд віверн на Високосіді й заблукав. Мотеґа тривожився за долю юнака, тим паче що батько Пао'ки неохоче відпустив його в мандри, але мандрівникам вдалося благополучно провести його назад до Застави Білого Рубежу.",al={"пао'ка свіфтмаунтін","зниклий таурен","завдання шлях додому"}},{q="Які ще небезпеки загрожують Заставі Білого Рубежу?",a="Окрім свавільних духів і хижаків, на табір постійно полюють кентаври Ґалак із околиць: вони влаштовують засідки й замишляють убити Канаті Ґрейклауда та інших тауренів застави.",al={"загрози заставі білого рубежу","кентаври біля білого рубежу","змова ґалака"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.153.0,38.275.1,56.248.1,44.276.1,45.212.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="Горянин Барліброу",s="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу. Стережучи перевал, що веде на схід до Лох Модану, він покладається на ситне дворфійське вариво, щоб вартові лишалися пильними на лютому холоді.",h="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу.",kw={"горянин барліброу","горянин","застава південної брами","лох модан","варта","мерехтливий стаут","дун мороґ"},ang={["race:Dwarf"]="Для дворфів Барліброу втілює необхідну рівновагу між прикордонним обов'язком і міцним трунком, що тримає Каз Модан у безпеці."},sec={{t="Варта на східному перевалі",b="На Заставі Південної Брами, що стереже засніжену дорогу до Лох Модану, горянин Велларт Барліброу несе службу в прикордонній варті Айронфорджа. Як і багато горян, що служать на лютих вітрах Дун Мороґу, він цінує зміцнювальні властивості доброго дворфійського трунку. Носячи ім'я уславленого клану Барліброю, він допомагає доправляти партії міцного Мерехтливого Стауту до побратимів-вартових, яким потрібні тепло й витривалість під час довгих змін на гірських перевалах."}},faq={{q="Де знайти Горянина Барліброу?",a="Горянин Барліброу несе службу на Заставі Південної Брами — дворфійському укріпленні, що стереже східний перевал між Дун Мороґом і Лох Моданом.",al={"місце барліброу","де горянин барліброу","барліброу нпс"}},{q="Які в нього обов'язки на Заставі Південної Брами?",a="Він гірський вартовий, що охороняє дорогу й допомагає з постачанням, зокрема Мерехтливого стауту для інших горян, які несуть службу на перевалах.",al={"обов'язки барліброу","що робить барліброу"}},{q="Чи він родич інших Барліброу?",a="Так. Його брат — пивовар Реджолд Барліброю, а ще він може бути родичем Марлет, Малґіна й Йоруса Барліброу.",al={"рід барліброу","йорус барліброу родич"}}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Горянин Кадрелл",s="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі. Як ключова сполучна ланка серед горян Лох Модану, він координує розвідку, доставку припасів і оборону кордонів по всьому краю.",h="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі.",kw={"горянин кадрелл","горянин","телсамар","лох модан","корчма міцний лагер","вартовий","розвідка"},ang={["faction:Alliance"]="Кадрелл покладається на мандрівників Альянсу, що проходять через Телсамар, щоб ті носили послання й допомагали далеким заставам горян, які борються з загрозами краю.",["race:Dwarf"]="Як член уславленого корпусу горян, Кадрелл утілює передову варту, що береже східні землі Айронфорджа від небезпек дикої природи."},sec={{t="Вартовий Телсамара",b="Стоячи на варті в людному поселенні Телсамар, Горянин Кадрелл — опора дворфійської оборони по всьому Лох Модану. Поки застави на околицях долини зносять невпинний тиск трогів, гнолів і тутешніх звірів, Кадрелл лишається в центрі містечка, щоб організовувати підкріплення, передавати накази й оцінювати польові звіти, які приносять мандрівні розвідники."},{t="Тримати зв'язок",b="Обов'язки Кадрелла часто передбачають підтримувати зв'язок між Телсамаром і віддаленими передовими позиціями. Чи то узгоджуючи дії з Горянином Стормпайком, чи то посилаючи шукачів пригод доповісти вартовим на кшталт Горянина Рокґара, Кадрелл дбає, щоб відокремлені застави, які стережуть гірські перевали, отримували життєво важливі припаси, підкріплення й оборонні відомості."}},faq={{q="Де знайти Горянина Кадрелла?",a="Кадрелл стоїть просто через дорогу від корчми «Міцний Лагер» у містечку Телсамар, серед хвилястих пагорбів Лох Модану.",al={"місце кадрелла","де кадрелл","знайти кадрелла"}},{q="Яка роль Кадрелла в Лох Модані?",a="Він із дворфійських горян і відповідає за зв'язок між місцевою владою Телсамара й віддаленими вартовими постами по всьому краю: узгоджує патрулі, постачання й донесення з кордону.",al={"що робить кадрелл","мета кадрелла","робота кадрелла"}},{q="Чому інші горяни посилають гінців до Кадрелла?",a="Оскільки він стоїть у самому центрі, біля корчми й головної дороги Телсамара, до Кадрелла сходяться всі польові донесення: він стежить, щоб термінові звіти від далеких розвідників доходили до оборони поселення.",al={"звіт кадреллу","чому звітувати кадреллу"}},{q="З ким співпрацює Кадрелл?",a="Кадрелл часто працює з іншими горянами на місцях, зокрема з Горянином Стормпайком і Горянином Рокґаром: збирає свіжі розвідувальні дані й розподіляє доручення з оборони від місцевих загроз.",al={"контакти кадрелла","кого знає кадрелл"}}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="Горянин Стормпайк",s="Горянин Стормпайк — горянин з Айронфорджа, що стоїть на варті на Станції Алґаз у північному Лох Модані. Наглядаючи за гірським перевалом до Багнокраю, він невтомно береже важливі шляхи постачання від трогів і кобольдів, що чатують довкола. Як гордий член клану Стормпайк, він вірний Айронфорджу й безпеці дворфійських земель.",h="Горянин Стормпайк — горянин з Айронфорджа, що стоїть на варті на Станції Алґаз у північному Лох Модані.",kw={"горянин стормпайк","станція алґаз","лох модан","кобольди","троги","дун алґаз","багнокрай"},ang={["faction:Alliance"]="Станція Алґаз тримає ключовий суходільний шлях, що з'єднує Айронфордж із Гаванню Менетіл у Багнокраї, тож пильність Стормпайка вкрай важлива для постачання Альянсу.",["race:Dwarf"]="Для дворфа з Айронфорджа допомогти товаришеві-горянину на кшталт Стормпайка — почесний обов'язок захищати внутрішні кордони Каз Модану від злодійкуватої напасті."},sec={{t="Охоронець Станції Алґаз",b="Станція Алґаз на північному кордоні Лох Модану — важливий пункт перед небезпечним спуском до Багнокраю. Горянин Стормпайк служить тут серед скелястих кряжів і постійних загроз дикої місцини. Його головний обов'язок — підтримувати зв'язок і тримати дороги відкритими для мандрівників і валок із припасами, що проходять через Дун Алґаз."},{t="Боротьба з місцевою напастю",b="Північні околиці Лох Модану потерпають від невгамовної напасті — від кобольдів, що кишать на сусідніх копальнях, до підземних трогів. Стормпайк раз у раз залучає перехожих шукачів пригод, щоб приборкати ці загрози, — передусім кобольдів, які вселилися в Шахту Срібного Потоку й поклали брудні лапи на дворфійські інструменти, що їх зберігала там Ліга Шахтарів."}},faq={{q="Де знайти Горянина Стормпайка?",a="Він несе службу на Станції Алґаз, на півночі Лох Модану, при гірській дорозі, що веде на північ, у прохід Дун Алґаз, до Багнокраю.",al={"місце стормпайка","де стормпайк","де горянин стормпайк"}},{q="Хто такий Горянин Стормпайк?",a="Він горянин з Айронфорджа зі славетного клану Стормпайків. Він вартовий і розвідник застави, що має берегти північний перевал Лох Модану від небезпек диких країв.",al={"хто такий стормпайк","лор горянина стормпайка","хто горянин стормпайк"}},{q="З якими загрозами він має справу на Станції Алґаз?",a="Заставі постійно докучають навали трогів і кобольдів, що заполонили схили й каменоломні. Стормпайк знищує ці загрози, щоб кур'єри й каравани могли безпечно проходити.",al={"небезпеки станції алґаз","що нападає на станцію алґаз","загрози півночі лох модану"}},{q="Навіщо потрібна Станція Алґаз?",a="Станція Алґаз — застава Айронфорджа, що стежить за межею між Лох Моданом і суворими тунелями Дун Алґазу. Це перевалочний пункт для горян, які патрулюють прикордоння й стежать, щоб торговий шлях був вільний.",al={"що таке станція алґаз","лор станції алґаз","мета станції алґаз"}},{q="Чи він пов'язаний із Вартою Стормпайків у Долині Альтерак?",a="Він носить ім'я славетного клану Стормпайків — дворфійського роду, відомого в Айронфорджі своїми запеклими воїнами й старателями, хоча нинішні накази тримають його на перевалах Лох Модану.",al={"стормпайк альтерак","клан стормпайк зв'язок","чи він варта стормпайків"}},{q="Які завдання Горянин Стормпайк дає шукачам пригод?",a="Він посилає шукачів пригод забрати спорядження Ліги Шахтарів із Шахти Срібного Потоку, яку заполонили кобольди, і віднести його замовлення на новий щит аж до Стормвінда, дворфові-зброярю Фуренові Лонґбірду.",al={"завдання стормпайка","доручення горянина стормпайка","завдання брудні лапи"}}},fp="21,362,25.379.0,29.350.0,39.151.0,29.207.0,48.204.0,32.221.0,55.217.0,58.211.0"}
P.entries["npc:mountaineer-thalos"] = {n="Горянин Талос",s="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного Кряжа. Йому доручено стерегти шлях, і він попереджає подорожніх про раптову навалу трогів, що забила тунель. Шукачі пригод із нагальними звітами з долини покладаються на нього, щоб безпечно дістатися Хараноса.",h="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного...",kw={"горянин талос","горянин","перевал холодного кряжа","троги","вартовий","харанос","долина холодного хребта"},ang={["faction:Alliance"]="Талос підтримує зв'язок уздовж життєво важливого гірського коридору, що з'єднує оборонні сили долини з центральним командуванням Айронфорджа.",["race:Dwarf"]="Для молодих дворфів, що залишають колиску батьківщини, Талос — суворе нагадування: загроза трогів — не навчальна вправа, а облога, що тисне на самі пороги Айронфорджа.",["race:Gnome"]="Гноми, що вирушають із притулків біженців Гномреґану, бачать Талоса на варті біля головного наземного шляху, що спускається до Хараноса й Айронфорджа."},sec={{t="Вартовий Перевалу Холодного Кряжа",b="На засніженій межі, де Долина Холодного Хребта переходить у глибші скелі Дун Мороґу, Горянин Талос — перша лінія оборони для мандрівників, що залишають дворфійські навчальні угіддя. Перевал Холодного Кряжа став підступною тісниною, яку захопили ворожі троги, що вирили собі шлях з підземних глибин. Талос несе варту на холоді, застерігаючи неготових повернути назад і оцінюючи, чи досить у витривалих кур'єрів твердості, щоб пробитися до ширшого королівства."},{t="Контрольний пункт кур'єра",b="Коли Ґрелін Вайтбірд завершує свій звіт про пересування тролів Морозогривів у відлюдній долині, кур'єрові, що несе його до брата Сеніра в Харанос, кажуть поговорити з Горянином Талосом, перш ніж заходити до тунелю. Переконавшись, що шукач пригод здатен подолати заражений прохід, Талос скеровує його далі до Хараноса, де командири краю координують оборону Дун Мороґу. Його пильна присутність гарантує, що важливі відомості дійдуть до військових очільників Айронфорджа, а не згинуть у снігу."}},faq={{q="Хто такий Горянин Талос?",a="Горянин Талос — горянин з Айронфорджа, що стоїть біля південного входу на Перевал Холодного Кряжа. Його пост стереже межу між Долиною Холодного Хребта й широкими просторами Дун Мороґу.",al={"лор талоса","хто такий талос","горянин талос"}},{q="Чому Горянин Талос відраджує мандрівників іти далі?",a="Перевал Холодного Кряжа заполонили люті троги Кам'янощелепих. Талос застерігає мирних людей і бійців-новачків від спроб перейти, пропускаючи всередину лише вправних кур'єрів і загартованих воїнів.",al={"чому перевал закритий","троги в перевалі","небезпека перевалу колдрідж"}},{q="Куди Горянин Талос посилає шукачів пригод?",a="Переглянувши термінові польові донесення з Долини Холодного Хребта, Талос спрямовує мандрівників через перевал до Хараноса — найближчого поселення на шляху до Айронфорджа.",al={"куди йти після талоса","призначення талоса","наступне місто"}},{q="Яке донесення Талос отримує від Сеніра Вайтбірдого?",a="Від самого Сеніра — жодного. Повз Талоса проходить донесення Ґреліна Вайтбірда про загрозу від тролів Морозогривів у Долині Холодного Хребта: його несе кур'єр до Ґрелінового брата Сеніра в Хараносі. Талос застерігає гінця про трогів і пропускає його далі тунелем.",al={"донесення сеніра","депеша сеніра","що читає талос"}},{q="До якої фракції належить Горянин Талос?",a="Талос — присяглий член горян Айронфорджа, загартованих прикордонних слідопитів, які патрулюють для Альянсу кордони, тунелі й засніжені гірські стежки Дун Мороґу.",al={"фракція талоса","чи талос з айронфорджа","горяни альянсу"}},{q="Чи можна пройти Перевал Холодного Кряжа, не поговоривши з Талосом?",a="Перевал відкритий для кожного, хто наважиться в нього увійти, але розмова з Талосом гарантує, що шукач пригод доставить до Хараноса важливі розвідувальні дані й дізнається про небезпеки, які чекають попереду.",al={"чи треба говорити з талосом","обійти талоса"}}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mr-smite"] = {n="Пан Кара",s="Пан Кара — могутній таурен, старший помічник на флагмані Братства Дефіас глибоко в Мертвих Копальнях. Вправний майстер зброї на службі в капітана Ґрінскіна, він із нещадною дисципліною стереже підступи до потаємного броненосця з боку доків. Кожен, хто стане проти нього, муситиме протистояти його змінному арсеналу й нищівній силі.",h="Пан Кара — могутній таурен, старший помічник на флагмані Братства Дефіас глибоко в Мертвих Копальнях.",kw={"пан кара","таурен","старший помічник","майстер зброї","мертві копальні","бухта айронклад"},ang={["class:Warrior"]="Кара демонструє дивовижну бойову виучку, плавно переходячи від швидких ударів однією рукою до двох сокир і нищівних ударів дворучного молота.",["faction:Alliance"]="Кара — головна перепона, що не дає агентам Альянсу прорватися трапом до капітана Ґрінскіна й Едвіна Венкліфа.",["race:Tauren"]="Побачити родича-таурена старшим помічником серед морських розбійників у Східних Королівствах — неабияке потрясіння для будь-якого мандрівника з Малгору."},sec={{t="Старший помічник бухти",b="Пан Кара стереже доки Бухти Айронклад і служить старшим помічником гобліна, капітана Ґрінскіна. Братство Дефіас складається здебільшого зі знедолених людей і союзних гоблінів-майстрів, тож Кара тут — разюча дивина: велетенський, загартований у боях таурен, далеко від рівнин Калімдору. Йому доручено тримати в суворому порядку галасливу піратську команду, і він стежить, щоб оснащення таємного броненосця Едвіна Венкліфа йшло без перешкод."},{t="Смертоносний майстер зброї",b="Кара — не просто грубий наглядач, а театральний і різнобічний майстер зброї. Йому подобається гратися з горе-героями: він навмисно затягує бій, щоб подарувати супротивникам оманливу надію. Коли ж на нього насідають, він так тупає, що здригається земля, приголомшуючи ворогів, а сам тим часом нишпорить у скрині зі зброєю. Бій він починає зі спритним дуельним клинком, далі береться за дві сокири, а коли його остаточно розлютять — за свій величезний дворучний бойовий молот."}},faq={{q="Чому таурен працює з людьми-бандитами у Вестфолі?",a="Хоча переважна більшість тауренів живе в Калімдорі разом із союзниками з Орди, вигнанці-найманці й мандрівники часом добираються на схід. Кара — піратський офіцер, а не ідейний прибічник Братства Дефіас: його найняли разом із командою капітана Ґрінскіна наглядати за бухтою й готувати броненосець до виходу в море.",al={"чому таурен у мертвих копальнях","лор пана кари","таурен пірат"}},{q="Хто начальник Пана Кари?",a="Кара підпорядковується безпосередньо капітанові Ґрінскіну — гобліну, господареві піратського корабля, що стоїть на якорі в Бухті Айронклад. А над ними обома в усій цій змові стоїть Едвін Венкліф, верховний очільник Братства Дефіас.",al={"чий бос пан кара","на кого працює пан кара"}},{q="Якою зброєю б'ється Пан Кара?",a="Кара починає бій зі Злодійським Клинком. Коли бій обертається не на його користь, він відступає до своєї скрині й бере пару Різаків Кари, а коли його притиснуть до краю — виймає Могутній Молот Кари.",al={"яку зброю використовує пан кара","яку зброю дістає кара зі скрині"}},{q="Де знайти Пана Кару?",a="Пан Кара вартує на дерев'яних причалах Бухти Айронклад — останньої печери в Мертвих Копальнях — і стереже трап, що веде на величезний броненосець Дефіас.",al={"місце пана кари","де пан кара"}},{q="Чи б'ється Пан Кара сам?",a="Кара тримає поруч двох прихованих розбійників Дефіас, готових напасти з засідки на кожного чужинця, що просуватиметься причалом до корабля.",al={"чи кара б'ється сам","охорона кари"}},{q="Чому Пан Кара такий небезпечний у ближньому бою?",a="Його фірмовий тауренський Бойовий Тупіт пускає по дерев'яному причалу ударну хвилю, що приголомшує цілі загони шукачів пригод — якраз на стільки, щоб він устиг узяти зі скрині нову зброю й відновити напад іще важчим озброєнням.",al={"приголомшення кари","бойовий тупіт кари"}}},fp="9,349,22.480.0,21.512.0,55.342.0,28.219.0,49.205.0,29.166.0,27.133.0,52.214.0"}
P.entries["npc:mull-thunderhorn"] = {n="Малл Тандергорн",s="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі. Глибоко відданий Земній Матері та рівновазі землі, він наглядає за священними водяними криницями, розкиданими по рівнинах. Коли чужинці-визискувачі загрожують життєдайним водам краю, Малл проводить молодих тауренів через обряди очищення прабатьківських джерел.",h="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі.",kw={"малл тандергорн","старійшина","криниці","очищення","тотем","село бладгуф","малгор"},ang={["class:Druid"]="Друїди поділяють тривогу Малла, бо на власні очі бачать, як отруєні криниці руйнують рівновагу живого світу Малгору.",["class:Shaman"]="Шамани впізнають у Маллі опору на гармонію стихій: його тотеми очищення закликають духів предків, щоб зцілити води, роз'ятрені механічною жадобою.",["faction:Horde"]="Боротьба Малла підкреслює тертя Орди з такими незалежними хижими організаціями, як Венчурна Компанія, що без дозволу вигрібають багатства Калімдору.",["race:Tauren"]="Для тауренів Малл Тандергорн — це пам'ять племені та обов'язок перед предками; він веде молодих сміливців, що захищають священні рівнини від жадібних чужинців."},sec={{t="Хранитель священних вод",b="Стоячи на варті в Селі Бладгуф, Малл Тандергорн несе на собі тягар духовного добробуту Малгору. Кочові племена зібралися під рукою Верховного Вождя Кайрна Бладгуфа, щоб звести собі постійну домівку, та їхні землі вже в облозі жадібності й нерозважливого загарбання. Малл — духовна опора для молодих сміливців, що виходять із Табору Нарачі; він кличе їх берегти життєво важливі скарби предків."},{t="Отруєні криниці й Венчурна Компанія",b="Головна біда Малла — раптова хвороба, що шириться водами Малгору: криницями Вінтергуфів, Тандергорнів і Вайлдмейнів. Сліди цієї скверни ведуть до гоблінів Венчурної Компанії — безсовісного торгового підприємства, що вгризається в довколишні пагорби й зливає отруту в місцеві ґрунтові води. Малл доручає молодим тауренам виготовити особливі тотеми очищення й провести обряд біля кожної прабатьківської криниці, перш ніж зараза безповоротно просякне землю та її живність."}},faq={{q="Хто такий Малл Тандергорн?",a="Малл Тандергорн — таурен, що дає завдання в Селі Бладгуф у Малгорі. Він охоронець священних криниць краю й проводить обряди та ритуали, щоб земля і її води лишалися чистими від зовнішнього зараження.",al={"лор малла тандергорна","хто такий малл","малл село кривавого копита"}},{q="Чому Малла Тандергорна непокоять криниці?",a="Криниці предків — Вінтергуфів, Тандергорнів і Вайлдмейнів — дають життя племенам і тваринам Малгору. Непрохані промисли неподалік отруїли ці священні джерела смердючими стоками й брудом, що загрожує природній рівновазі рівнин.",al={"чому отруєні криниці","криниці малгору","отруєна криниця вінтерхуф"}},{q="Хто забруднює криниці Малгору?",a="Бруд спричиняє Венчурна Компанія — безрозсудне гоблінське підприємство, що закріплюється на околицях Малгору з копальнями й лісорубством. Їхні промисли не зважають на священну землю й зливають промислові отрути в місцеві підземні води.",al={"хто отруїв воду","венчурна компанія в малгорі","хто забруднив криниці"}},{q="Чому завдання Малла з очищення стосуються лише тауренів?",a="Криниці мають глибоке родове й духовне значення, пов'язане з родами-засновниками тауренських племен — Тандергорнами, Вінтергуфами й Вайлдмейнами. Їхнє очищення вважають священним обрядом посвяти й культурним обов'язком тауренів, що дорослішають.",al={"завдання лише для тауренів","чому тільки таурени","вимоги малла тандергорна"}},{q="Як очищають криниці?",a="Малл навчає мандрівників збирати особливо освячені тотеми, наповнені силою місцевих природних реагентів — пазурів і шкур. Освячені тотеми несуть просто до забруднених криниць, щоб спрямувати духовне очищення й змити неприродні отрути.",al={"як очистити криниці","очисні тотеми","очищення води"}},{q="Що таке Обряд Видіння?",a="Обряд Видіння — основна духовна мандрівка, яку здійснюють молоді таурени, щоб поспілкуватися з предками й духами тварин. Послушників посилають до Зарлмана Ту-Мунса в Селі Бладгуф пройти це випробування видінням як один з Обрядів Земної Матері.",al={"обряд видіння","що таке обряд видіння"}}},fp="16,359,29.438.0,37.540.1,24.237.0,54.293.0,44.271.0,54.266.0,33.268.0,27.268.0"}
P.entries["npc:mupsi-shacklefridd"] = {n="Мупсі Шеклфрідд",s="Мупсі Шеклфрідд — гоблінка, що мешкає під самим Раджетом у Пустках. Вона — місцевий контакт для мандрівників, які хочуть залагодити зіпсовані стосунки з картелем Стімвідл.",h="Мупсі Шеклфрідд — гоблінка, що мешкає під самим Раджетом у Пустках.",kw={"мупсі шеклфрідд","раджет","картель стімвідл","гобліни","репутація","пустки"},sec={{t="На околиці Раджета",b="Мупсі Шеклфрідд веде свої справи неподалік від Раджета, на запорошених прибережних дорогах Пусток. Біля портового містечка життя завжди вирує: периметром ходять вартові Стімвідлу, приходять і йдуть купці. Тим, хто опинився в немилості в гоблінів, Мупсі пропонує шлях до примирення — якщо мандрівники готові дати картелеві припаси й працю, яких той вимагає."}},faq={{q="Хто така Мупсі Шеклфрідд?",a="Це гоблінка, що стоїть просто за межами Раджета в Пустках і допомагає мандрівникам, які хочуть відновити свою репутацію в картелі Стімвідл.",al={"мупсі","хто така мупсі","мупсі раджет"}},{q="Де її знайти?",a="Мупсі стоїть одразу за Раджетом у Пустках, так близько до поселення, що портова варта й патрулі час від часу проходять повз неї.",al={"місце мупсі","де мупсі шеклфрідд","знайти мупсі"}},{q="Навіщо комусь говорити з Мупсі Шеклфрідд?",a="Мандрівники, що розгнівали картель Стімвідл — найчастіше сутичками з гоблінами чи підтримкою піратів, — можуть відновити свою репутацію, жертвуючи Мупсі припаси.",al={"загоєння старих ран раджет","здача репутації раджета","завдання мупсі"}}},fp="18,219,27.406.0,26.165.0,21.158.0,45.185.0"}
P.entries["npc:mutanus-the-devourer"] = {n="Мутанус Пожирач",s="Мутанус Пожирач — жахливий блідий мурлок, що постав просто зі Смарагдового Жахіття. Він чатує в найтемніших закутках розуму сплячого друїда Наралекса й виринає, щоб пожерти кожного, хто намагається зламати владу Жахіття над Печерами Стогонів. Убити цю спотворену потвору — останній крок до того, щоб звільнити Наралекса з його болісного сну.",h="Мутанус Пожирач — жахливий блідий мурлок, що постав просто зі Смарагдового Жахіття.",kw={"мутанус пожирач","мурлок","наралекс","смарагдове жахіття","печери стогонів","учень наралекса"},ang={["class:Druid"]="Мутанус показує, які страшні небезпеки чатують на тих, хто без запобіжників занурюється надто глибоко в Смарагдовий Сон, — адже розум побратима-друїда цілком поглинула порча.",["faction:Horde"]="Орда не може дозволити Мутанусові та Жахіттю отруїти серце Пусток, бо це загрожує життєдайним водам оаз, без яких не вижити Дуротару й Малгору.",["race:NightElf"]="Для калдореїв Мутанус — трагедія, що ожила: він втілює те, як шляхетне прагнення Наралекса зцілити Пустки обернулося жахливим маренням."},sec={{t="Найбільший страх сновидця",b="Коли друїд із нічних ельфів Наралекс дістався підземних джерел під Пустками, він хотів повернути життя посушливим пустищам, поєднавши їх зі Смарагдовим Сном. Натомість у його думки вдерлася прадавня порча, відома як Смарагдове Жахіття. Ув'язнений у болісному видінні, Наралекс побачив, як його потаємні страхи набувають плоті. Порча вчепилася в дивну, первісну відразу в душі друїда — його глибоко вкорінений жах перед мурлоками — і роздула її до велетенського хижака-альбіноса."},{t="Жахіття наяву",b="Темна сила, що заполонила розум Наралекса, послала Мутануса у світ наяву, щоб друїд ніколи не прокинувся. Коли Учень Наралекса проводить обряд, щоб пробудити свого наставника, Мутанус проривається крізь межу між сном і дійсністю. Разом зі своєю протиприродною подобою він приносить із краю снів чужинські реліквії — як-от таємничий Перстень Морських Глибин. Доки Мутанус не загине, Наралекс лишається в'язнем власної спотвореної уяви."}},faq={{q="Що таке Мутанус Пожирач?",a="Мутанус Пожирач — величезна бліда потвора, схожа на мурлока, породжена Смарагдовим Жахіттям. Це не звичайний мешканець Азероту, а живий кошмар, викликаний у дійсність зі зіпсованого розуму сплячого друїда Наралекса.",al={"хто такий мутанус","що за істота мутанус","чи мутанус мурлок"}},{q="Чому Мутанус схожий на велетенського мурлока?",a="Жахіття спотворило підсвідомі думки Наралекса й витягло з них його найгіршого особистого ворога — мурлоків. Скверна обернула цей глибоко вкорінений страх на зброю, втіливши його у величезній потворі-альбіносі.",al={"чому мурлок","чому мутанус мурлок","страх наралекса перед мурлоком"}},{q="Чому Мутанус з'являється наприкінці ритуалу?",a="Темна сила, що псує Смарагдовий Сон, наказала Мутанусу не дати нікому перервати сон Наралекса. Коли учні Наралекса починають ритуал пробудження, Мутанус переходить у справжню печеру, щоб пожерти рятівників.",al={"коли з'являється мутанус","чому викликають мутануса","бос ритуалу наралекса"}},{q="Звідки взявся Мутанус?",a="Мутанус походить зі Смарагдового Жахіття — зіпсованого царства, що полонило Наралекса. Переходячи зі світу снів до Азероту, він навіть приніс із собою дивні реліквії на кшталт Персня Глибин.",al={"походження мутануса","чи мутанус із кошмару","смарагдовий кошмар мутанус"}},{q="Чи вбивство Мутануса рятує Наралекса?",a="Так. Щойно Мутануса вбито, безпосередня влада кошмару над розумом Наралекса розбивається, і його учні можуть пробудити друїда й розвіяти темний транс печери.",al={"чи врятований наралекс","що буде після смерті мутануса","пробудження наралекса"}},{q="Чому Мутанус не боїться магії тіней?",a="Мутанус — потвора, сплетена з темних енергій кошмару, тож від природи стійкий до некротичних і тіньових заклинань, що вразили б звичайних звірів.",al={"імунітет мутануса до тіні","закляття тіні мутанус","чи мутанус імунний до тіні"}}},fp="20,358,22.505.0,20.460.1,29.236.0,42.199.0,49.236.0,29.205.0,34.184.1,38.158.0"}
P.entries["npc:mux-manascrambler"] = {n="Мукс Манаскремблер",s="Мукс Манаскремблер — дивакуватий гоблін-інженер, що мешкає в пустельному поселенні Ґаджетзан. На відміну від багатьох своїх колег, які думають лише про вибухівку чи гірниче обладнання, Мукс має дивне захоплення надприродним і окультними енергіями.",h="Мукс Манаскремблер — дивакуватий гоблін-інженер, що мешкає в пустельному поселенні Ґаджетзан.",kw={"мукс манаскремблер","гоблін","інженерія","ґаджетзан","привиди","надприродне"},ang={["profession:Engineering"]="Мукс — диво серед гоблінських майстрів: він застосовує шестерні й енергоелементи, щоб ловити й переганяти незримі надприродні сили, а не просто все підривати."},sec={{t="Майстер незримого",b="У будівлі в центрі Ґаджетзана, позаду Дріза Планкбоу та його брязкітливих ботів-м'ясників, сидить Мукс Манаскремблер. Поки картель Стімвідл жваво торгує нафтою, зброєю й брухтом, Мукс спрямовує свою винахідливість на таємничіші заняття — світ духів і надприродні аномалії. Свої технічні знання він вкладає в химерні пристрої, здатні виявляти й переганяти рештки привидів та взаємодіяти з ними, і так поєднує грубе гоблінське ремесло з незримими світами мертвих."}},faq={{q="Де знайти Мукса Манаскремблера?",a="Мукс живе в Ґаджетзані на півночі Танарісу. Ви знайдете його в будівлі неподалік від центру цього пустельного торгового осередку, просто за Дрізом Планкбоу й ботами-м'ясниками, що розбирають туші.",al={"місце мукса","де мукс","карта мукса манаскремблера"}},{q="Якою роботою займається Мукс?",a="Мукс — інженер, одержимий примарними й невидимими силами. Замість звичайних підривів чи транспорту він будує особливі пристрої, що здатні виявляти духів, переганяти ектоплазму й приборкувати тайну надприродну силу.",al={"робота мукса","що продає мукс","дослідження мукса"}},{q="Чи належить Мукс до якоїсь фракції?",a="Мукс належить до картелю Стімвідл у Ґаджетзані. Як незалежний гоблінський ділок, він суворо дотримується торговельного нейтралітету й охоче допомагає шукачам пригод і з Орди, і з Альянсу.",al={"чи мукс з орди","чи мукс нейтральний","мукс альянс"}}},fp="17,249,24.504.0,35.208.0,30.236.0,29.215.0"}
P.entries["npc:mydrannul"] = {n="Мідраннул",s="Мідраннул — крамар нічних ельфів, що продає всяку всячину на Терасі Воїна в Дарнасусі. Він обслуговує Вартових, солдатів і гостей столиці, тримаючи під рукою найпотрібніше: припаси, набої й провіант.",h="Мідраннул — крамар нічних ельфів, що продає всяку всячину на Терасі Воїна в Дарнасусі.",kw={"мідраннул","крамар","тераса воїна","дарнасус","припаси","набої"},ang={["faction:Alliance"]="Мандрівники Альянсу, що прибувають на Тельдрассил, можуть покластися на торговців на кшталт Мідраннула на Терасі Воїна: у нього є прості торби, набої й похідні харчі.",["race:NightElf"]="Для нічних ельфів, що навчаються в Дарнасусі, Мідраннул — постачальник щоденного спорядження та стріл, завдяки якому Вартові завжди мають усе потрібне."},sec={{t="Припаси Тераси Воїна",b="Серед військових наметів і тренувальних майданчиків Тераси Воїна Мідраннул продає необхідне спорядження і захисникам Дарнасуса, і мандрівним шукачам пригод. У нього є все, що знадобиться в поході: стріли для лучників і кулі для стрільців, метальні ножі, кремінь, торбинки й прості харчі. Порядкуючи своєю яткою в бойовому кварталі міста, він дбає, щоб Вартові й новобранці, які готуються до служби на Тельдрассилі, не потерпали від браку дрібниць першої потреби."}},faq={{q="Де знайти Мідраннула?",a="Мідраннул — на Терасі Воїна, південно-східному бойовому районі Дарнасуса у верхівці Тельдрассила.",al={"місце мідраннула","де мідраннул","карта мідраннула"}},{q="Що продає Мідраннул?",a="Він торгує всякою всячиною: торбами, простою їжею, напоями й табірним приладдям на кшталт кресала й трута, а ще метальною зброєю й набоями — стрілами та кулями.",al={"крам мідраннула","що продає мідраннул","товари мідраннула"}},{q="Чи дає Мідраннул якісь завдання?",a="Так. Окрім торгівлі припасами, Мідраннул посилає шукачів пригод до своєї подруги Несси Шедовсонг — торговки рибою в Селищі Рут'теран, якій треба переправити посилку на Темне Узбережжя.",al={"завдання мідраннула","доручення від мідраннула"}}},fp="9,224,33.502.0,29.134.0,31.190.0,32.172.0"}
P.entries["npc:nalpak"] = {n="Налпак",s="Налпак — учень-друїд, таурен, що пильнує неспокійні Печери Стогонів у Пустках. Зі своєї високої печери в скелі над входом він кличе мандрівних шукачів пригод допомогти стримати жахіття, що спотворює підземну природу.",h="Налпак — учень-друїд, таурен, що пильнує неспокійні Печери Стогонів у Пустках.",kw={"налпак","печери стогонів","наралекс","девіантні шкури","друїди","смарагдовий сон"},ang={["class:Druid"]="Для побратимів-друїдів Налпак — похмуре нагадування про те, яким небезпечним буває дотик до Смарагдового Сну, коли в обряді, що мав зцілювати, пускає коріння темрява.",["race:Tauren"]="Налпак уособлює відданість тауренів зціленню спраглих земель Калімдору: він не кидає місії навіть тоді, коли лихо спіткало самих сновидців."},sec={{t="Вартовий над печерами",b="Сховавшись у потаємній печері просто над входом до Печер Стогонів, Налпак лишається вірним задуму архідруїда Наралекса. Поки його наставник лежить глибоко внизу в полоні спотвореного сну, Налпак намагається стримати скверну, що ширшає. Він просить шукачів пригод збирати девіантні шкури, з яких можна вичинити шкіру."}},faq={{q="Де перебуває Налпак?",a="Налпак — у печері високо на скелі просто над природною кам'яною аркою, що веде до Печер Стогонів у центрі Пусток.",al={"місце налпака","де налпак","знайти налпака"}},{q="Хто такий Налпак?",a="Він таурен-друїд, один з Учнів Наралекса. Він має стежити за спотвореними створіннями, що виповзають із Печер Стогонів, поки його наставник намагається відродити Пустки через Смарагдовий Сон.",al={"хто такий налпак","лор налпака"}},{q="Навіщо Налпакові шкури девіантів?",a="Налпак хоче дослідити шкури девіантних створінь, що заполонили Печери Стогонів. Попри їхню злу природу, він вірить, що їхні незвичайні шкури можна з користю застосувати в шкірництві.",al={"навіщо шкури девіантів","завдання шкур девіантів"}},{q="Що пов'язує Налпака з Наралексом?",a="Налпак — вірний учень і послідовник Архідруїда Наралекса, один з учнів, яких послали підтримати сміливу спробу знову пробудити джерела Пусток.",al={"чи налпак учень наралекса","налпак і наралекс"}}},fp="6,259,25.319.0,24.154.0,14.216.0,35.190.0,41.173.0"}
P.entries["npc:nara-meideros"] = {n="Нара Мейдерос",s="Нара Мейдерос — нічна ельфійка, жриця, що мешкає серед мирної зелені Парку в Стормвінді. Наставниця послушників, вона несе вчення Елуни в серці людської столиці.",h="Нара Мейдерос — нічна ельфійка, жриця, що мешкає серед мирної зелені Парку в Стормвінді.",kw={"нара мейдерос","жриця елуни","нічні ельфи","парк","стормвінд","елуна"},ang={["class:Priest"]="Для жерців із нічних ельфів, що мандрують Східними Королівствами, Нара — наставниця в найважливіших расових обрядах, до якої не треба вертатися аж у Калімдор.",["race:NightElf"]="Далеко від лісів Ашенвалю й Тельдрассила Нара Мейдерос і Парк дарують затишну частку дому серед гамірних кам'яних мурів людської столиці."},sec={{t="Жриця у Стормвінді",b="Більшість жриць Елуни лишається в Калімдорі під гіллям Тельдрассила, та Нара Мейдерос живе далеко за Великим Морем, у Стормвінді. Її можна знайти в Парку — притулку, який плекають нічні ельфи-друїди й жерці, що навідуються до міста. Тут вона веде молодих шукачів духовного шляху стежкою божественної відданості. Поруч із людськими служителями Святого Світла з Соборної Площі Нара дає нічним ельфам, що гостюють чи живуть у Східних Королівствах, знайомий зв'язок із благодаттю Богині Місяця."}},faq={{q="Де знайти Нару Мейдерос?",a="Нара Мейдерос — у Парку Стормвінда, серед місячних колодязів і високих дерев, що нагадують нічним ельфам-мандрівникам про дім.",al={"місце нари мейдерос","де нара мейдерос","тренер жерців парку"}},{q="Яку роль відіграє Нара Мейдерос?",a="Вона наставниця жерців, що допомагає послушникам і жерцям, які зростають, а людей-жерців посилає до Собору Світла вивчати молитви на кшталт Відчайдушної Молитви.",al={"що робить нара","роль нари мейдерос","хто така нара мейдерос"}},{q="Чому жриця нічних ельфів живе в Стормвінді?",a="Що міцнішими стають зв'язки між нічними ельфами Дарнасуса й Великим Альянсом, то активніше посланці, друїди й жерці нічних ельфів присутні в Парку, допомагаючи родичам і представляючи свої духовні традиції.",al={"чому жриця нічних ельфів у стормвінді","нічна ельфійка в стормвінді"}}},fp="13,205,24.491.0,31.148.0,35.176.0,51.220.0"}
P.entries["npc:narain-soothfancy"] = {n="Нарейн Сутфенсі",s="Нарейн Сутфенсі — дивакуватий гном, що мешкає у відлюдній хатині на пляжі трохи на північ від Порту Стімвідла в Танарісі. Він гучно рекламує себе як великого віщуна, що вміє передбачати майбутнє, але ті, хто його знає, вважають його ясновидіння суцільним фарсом — на відміну від справжнього інженерного генія.",h="Нарейн Сутфенсі — дивакуватий гном, що мешкає у відлюдній хатині на пляжі трохи на північ від Порту Стімвідла...",kw={"нарейн сутфенсі","гном","віщун","інженерія","порт стімвідла","танаріс"},ang={["profession:Engineering"]="Інженерам шалені винаходи Нарейна видадуться захопливими, хай навіть він волів би вдавати, що його механічні тріумфи — насправді містичні видіння.",["race:Gnome"]="Нарейн — гномівська винахідливість у найдивакуватішому її прояві: він поєднує блискуче вміння розв'язувати технічні задачі з химерними, нав'язливими захопленнями."},sec={{t="Видіння ясновидця й практична механіка",b="Perched on the eastern coast of Tanaris just north of the goblin docks, Narain Soothfancy lives as a retired engineer turned self-proclaimed master fortune teller. He routinely greets visitors by pressing unopened envelopes against his forehead or making wildly inaccurate guesses about their business, such as wondering if they have arrived seeking the legendary Ashbringer. Despite his theatrical charade, Narain possesses deep technical knowledge. Even ancient beings like the blue dragon Azuregos note that while Narain is a terrible psychic, his engineering aptitude is undeniably brilliant. A handbook titled 'Soothsaying for Dummies' rests nearby."},{t="Аварія на узбережжі",b="Перш ніж оселитися біля Порту Стімвідла, Нарейн розбився на літальній машині далеко на півдні, на Пляжі Край Землі. Він вижив після аварії завдяки несподіваному порятунку, проте дивацтва й химерні нав'язливі ідеї тримають його на самоті на пустельному березі, де він майструє пристрої, що межують із тайною магією, і продає сумнівні пророцтва кожному перехожому."}},faq={{q="Хто такий Нарейн Сутфенсі?",a="Нарейн Сутфенсі — гном-інженер на спочинку, що живе в Танарісі на північ від Порту Стімвідла. Він рекламує себе як майстра-віщуна, хоча його пророцтва славляться своєю неточністю.",al={"лор нарейна сутфенсі","хто такий нарейн","ясновидець гном танаріс"}},{q="Чи справді Нарейн ясновидець?",a="Ні. Могутні знайомі, як-от дракон Азурегос, відкрито називають його жахливим ясновидцем. Справжній його хист — майстерна інженерія й механіка, хоч би як театрально він удавав, що читає думки.",al={"чи бачить нарейн майбутнє","чи нарейн ясновидець","ворожка сутфенсі"}},{q="Що за книга «Віщування для чайників» лежить біля нього?",a="It is a handbook kept in Narain's hut, associated with specialized trades. Narain points travelers seeking such knowledge toward the book.",al={"віщування для чайників","книга нарейна"}},{q="Звідки Нарейн знає Азурегоса?",a="Нарейн — давній знайомий синього дракона Азурегоса, що мандрує Азшарою. Попри дивні претензії Нарейна, дракон поважає його неперевершений хист до інженерії й ремесла.",al={"нарейн і азурегос","синій дракон нарейн"}}},fp="17,315,37.654.0,17.384.0,25.187.0,29.209.0,54.138.0,30.187.0"}
P.entries["npc:naralex"] = {n="Наралекс",s="Наралекс — друїд із нічних ельфів, який прагнув силами Смарагдового Сну перетворити спраглі Пустки на пишний ліс. Натомість його сон поглинуло темне жахіття, що спотворило Печери Стогонів під землею й обернуло його послідовників на отруйних потвор.",h="Наралекс — друїд із нічних ельфів, який прагнув силами Смарагдового Сну перетворити спраглі Пустки на пишний...",kw={"наралекс","печери стогонів","смарагдовий сон","смарагдове жахіття","друїди ікла","пустки"},ang={["class:Druid"]="Наралекс — похмура пересторога для друїдів: якщо наосліп утручатися в первісні стани природи чи необачно занурюватися надто глибоко в Сон, можна вивільнити катастрофічні збочення дикої природи.",["faction:Horde"]="Невдалий містичний дослід нічного ельфа отруїв серце Пусток, і тепер силам Орди з Перехрестя доводиться давати раду звірам, що шаленіють і лізуть із печер.",["race:NightElf"]="Наралекс хотів зцілити Калімдор, але його неприборкані амбіції глибоко на землях Орди принесли ганьбу Колу Кенарія й породили віроломних Друїдів Ікла.",["race:Tauren"]="Спотворені води під Пустками — пряма загроза оазам і звірині, які годують племена Малгору й савани."},sec={{t="Видіння зелені",b="Задовго до Великого Розколу випалені сонцем рівнини Пусток були буйним лісом. Вважаючи цю втрату трагедією, Наралекс вирушив із Дарнасуса на південь разом із гуртом відданих учнів, щоб здолати посуху. Глибоко під саваною він відкрив хитромудру мережу підземних джерел і бурхливих гейзерів і назвав її Печерами Стогонів — через виття вітру й пари, що стогнали в скелі. Він вірив, що коли зануриться в глибокий транс і спрямує чисту енергію Смарагдового Сну в ці підземні води, життєдайна течія дійде до поверхні, і вся пустка розквітне."},{t="Жахіття наяву",b="Наралекс поринув у глибоку медитацію в надрах підземних печер, але його шляхетний задум завалився тієї ж миті, коли його свідомість торкнулася царини Сну. Замість мирних джерел дикої природи його розум обплела зловісна, всепроникна порча — Смарагдове Жахіття. Гнилісна порча захопила тіло сплячого друїда й зробила його відчиненою брамою, крізь яку темні сили просочувалися в живий світ. Чисті джерела зіпсувалися, на них проросли мутовані грибні нарости, а тутешні печерні звірі перетворилися на ненажерливих девіантних страховиськ."},{t="Занепалі учні",b="Жахіття не обмежилося звірами. Власні учні Наралекса, цілком збожеволівши від психічної віддачі, що сочилася з трансу їхнього наставника, відкинули традиції Кола Кенарія. Зрікшись шанування рівноваги, вони прибрали зміїної подоби й назвалися Друїдами Ікла. Вірячи, що їхнє спотворене буяння має поширитися всім Калімдором, вони тепер стережуть сплячого Наралекса, щоб той ніколи не прокинувся. Лише кілька вірних учнів, як-от Муйо, шукають союзників, досить сміливих, щоб перервати транс."}},faq={{q="Хто такий Наралекс?",a="Наралекс — нічний ельф, друїд Кола Кенарія. Він повів експедицію до Печер Стогонів, щоб черпнути сили Смарагдового Сну й знову перетворити посушливі Пустки на буйний ліс, яким вони були до Розколу.",al={"лор наралекса","хто сплячий ельф","сплячий у печерах стогонів"}},{q="Чому Наралекс спить у Печерах Стогонів?",a="Він увійшов у медитативний транс, щоб спрямувати енергію Смарагдового Сну просто в підземні водоносні шари під Пустками. Але його розум поглинув нездоланний кошмар, і тепер він ув'язнений у гарячковому сні, з якого сам не може прокинутися.",al={"чому наралекс спить","що робить наралекс","транс наралекса"}},{q="Звідки взялися Друїди Ікла?",a="Спершу це були вірні учні Наралекса. Коли Смарагдове Жахіття зіпсувало зв'язок Наралекса зі Сном, злоба, що просочувалася назовні, звела його послідовників з розуму. Вони покинули Коло Кенарія, прийняли зміїні тотеми й тепер стережуть його сон, щоб скверна й далі ширилася.",al={"походження друїдів ікла","хто такі друїди ікла","учні наралекса"}},{q="Що спричинило мутації в Печерах Стогонів?",a="Спляче тіло Наралекса стало відкритим проходом для Смарагдового Жахіття. Мерзенна енергія сну просочилася просто в підземні річки й перетворила рослини, крокодилів, ящерів і змій печер на агресивних мутантів-девіантів.",al={"чому печери стогонів зіпсовані","походження девіантів","гриб печер стогонів"}},{q="Чи можна пробудити Наралекса?",a="Так, але лише з допомогою ззовні. Його вірний учень, що лишився, Муйо, працює з шукачами пригод, готовими спуститися в глибини, знищити спотворених Друїдів Ікла й провести ритуал, щоб зламати владу кошмару над розумом Наралекса.",al={"як врятувати наралекса","пробудження наралекса","завдання наралекса"}},{q="Чому Наралекс хотів змінити Пустки?",a="Наралекс дізнався, що колись Пустки були квітучим лісом, доки Великий Розкол не розтрощив Калімдор. Він бачив у їхній нинішній посушливості рану природи й прагнув відродити давній зелений покрив.",al={"навіщо відновлювати пустки","мета наралекса в пустках","чому пустки"}}},fp="7,277,17.662.0,20.602.0,16.560.1,15.231.0,49.256.0,36.285.0,42.245.0,24.224.1,43.216.0"}
P.entries["npc:nat-pagle"] = {n="Нат Паґл",s="Ната Паґла повсюдно вважають найславетнішим рибалкою всього Азероту, хоч сам він стверджує, що рибалить лише як привід добряче випити. Він живе на відлюдній затоці в Багні Пилоброду й навчає найкращих рибалок і з Альянсу, і з Орди — тих, кому вдається довести своє терпіння.",h="Ната Паґла повсюдно вважають найславетнішим рибалкою всього Азероту, хоч сам він стверджує, що рибалить лише...",kw={"нат паґл","рибальство","рибалка","багно пилоброду","ґаз'ранка","зул'ґуруб"},ang={["faction:Alliance"]="Дворфійські майстри-рибалки, як-от Ґрімнур Стоунбренд в Айронфорджі, дуже шанують Ната й посилають досвідчених рибалок Альянсу до Багна Пилоброду, щоб ті вивідали останні таємниці ремесла.",["faction:Horde"]="Лумак, наставник рибалок у Долині Честі в Оргріммарі, вважає Ната Паґла вірним другом і посилає до нього на південь обдарованих рибалок Орди."},sec={{t="Майстер-рибалка",b="Хоч його ім'я по всьому відомому світу стало синонімом рибальської майстерності, Нат Паґл напрочуд невимушено ставиться до свого ремесла. Закидаючи вудку вже кілька десятиліть, він часто зізнається, що не має особливого пієтету до самого рибальства, і славетно називає його просто зручним приводом сидіти собі й добряче пити. Попри цю грубувату безтурботність, Нат розуміє водне життя й мистецтво рибальства краще за будь-кого з живих: він навіть написав власний посібник і дав своє ім'я рибальському спорядженню, на яке полюють професіонали."},{t="Болотяний відлюдник",b="Паґл отаборився на невеликій косі на східному узбережжі Багна Пилоброду, далеко від гамірних таверн Східних Королівств. Він палко незалежний і байдужий до політики фракцій: радо приймає і мандрівників Альянсу, яких посилають наставники на кшталт Ґрімнура Стоунбренда, і прибічників Орди, яких спрямовує до нього Лумак з Оргріммара. Для Ната кожен, хто готовий обнишпорити закутки світу заради рідкісних уловів, заслуговує на урок справжнього рибальства."},{t="Давні байки й морські чудовиська",b="Паґл бував і в небезпечних водах — зокрема ходив у руїни Зул'Ґуруба, де загубив свою улюблену мірну стрічку й скриньку зі снастями біля вод, якими нишпорить жахлива гідра Ґаз'ранка."}},faq={{q="Хто такий Нат Паґл?",a="Нат Паґл — найвідоміший рибалка Азероту. Десятиліттями закидаючи вудку, він тепер тихо живе на узбережжі Багна Пилоброду й навчає досвідчених рибалок, яким уже замало звичайних наставників.",al={"хто такий нат","лор ната паґла","хто рибалка"}},{q="Де знайти Ната Паґла?",a="Він живе на невеликій косі на східному узбережжі Багна Пилоброду в Калімдорі, на південний захід від Острова Терамор.",al={"де нат паґл","місце ната паґла","знайти ната паґла"}},{q="Навіщо Нат Паґл рибалить, якщо каже, що цього не любить?",a="Паґл відверто зізнався, що рибальство для нього — насамперед поважна відмовка, щоб годинами спокійно сидіти біля води й добряче випивати.",al={"чи нат любить рибалити","навіщо нат рибалить","нат паґл п'є"}},{q="Чи навчає Нат Паґл членів Орди?",a="Так. Нат цілком байдужий до ворожнечі фракцій. Рибалок Орди, які досягли межі звичайної майстерності, просто до нього посилає його друг Лумак з Оргріммара.",al={"чи нат лише для альянсу","нат паґл орда","чи орда може говорити з натом"}},{q="Що пов'язує Ната Паґла із Зул'Ґурубом?",a="Колись Нат рибалив у стародавньому тролячому місті Зул'Ґуруб і залишив там свою скриньку зі снастями й цінну рулетку біля вод, де живе велика гідра Ґаз'ранка.",al={"нат у зг","скринька снастей ната паґла","нат паґл зул'ґуруб"}}},fp="9,298,17.508.0,18.473.0,26.212.0,17.202.0,29.115.0,50.156.0,42.172.0,49.169.0"}
P.entries["npc:natalia-mar-alith"] = {n="Наталія Мар'аліт",s="Господиня Наталія Мар'аліт — жриця з нічних ельфів і дослідниця Кола Кенарія, що зникла глибоко в гніздах силітидів у Вулик'Реґалі. Вона прибула в пустелі Силітусу разом зі своїм чоловіком, Командиром Мар'алітом, а згодом вирушила з експедицією у вулики.",h="Господиня Наталія Мар'аліт — жриця з нічних ельфів і дослідниця Кола Кенарія, що зникла глибоко в гніздах...",kw={"наталія мар'аліт","жриця","вулик'реґал","к'тун","силітус","нічні ельфи"},ang={["faction:Alliance"]="Рутґар Ґліфшейпер і Франкал Стоунбридж у Таборі Бронзоборода розповідають похмурі подробиці її падіння дослідникам Альянсу, які йдуть слідами експедиції Бранна.",["race:NightElf"]="Трагічне падіння Наталії — сумне нагадування калдореям, що навіть найвідданіші їхні жриці беззахисні перед прадавніми жахіттями, похованими під пісками Силітусу."},sec={{t="Трагічне падіння",b="Коли Коло Кенарія заснувало Цитадель Кенаріуса, щоб стежити за пробудженням пісків, Наталія вирушила в пустелю разом із чоловіком, Командиром Мар'алітом. Прагнучи розгадати, чому знову ожили силітиди й що криють прадавні руїни кіражів, вона приєдналася до розвідувального загону славетного дослідника Бранна Бронзбірда, у якому були також дворфи-дослідники Рутґар Ґліфшейпер і Франкал Стоунбридж."},{t="Кристал Вулик'Реґала",b="Експедиція пішла слідом за дивними випромінюваннями в південні глибини Вулик'Реґала. У самому серці вулика дослідники натрапили на величезний кристал, укритий прадавніми гліфами кіражів. Приваблена його шепітливим відлунням, Наталія схилилася, щоб роздивитися письмена ближче. Темна магія всередині за мить здолала її розум, розколола свідомість і прикувала її волю до К'Туна. Супутники-дворфи винесли її до Цитаделі Кенаріуса, де друїди привели її до тями, та за кілька тижнів вона, одержима, увірвалася до їхнього табору з вимогою повернути її у вулик — і від неї довелося відбиватися. Нині вона — затята охоронниця жахливого володаря вулика."},{t="Розпач командира",b="У Цитаделі Кенаріуса Командир Мар'аліт відчайдушно тримається надії, що дружину ще можна врятувати, і не хоче визнати, що її розум зламано безповоротно. Та кожен, хто наважиться піти у Вулик'Реґал, знайде не бранку, яка чекає порятунку, а безжальну служницю божевілля, що володіє священною магією жриці, спотвореною злобою Древнього Бога."}},faq={{q="Хто така Наталія Мар'аліт?",a="Наталія Мар'аліт — нічна ельфійка, жриця Кола Кенарія й дружина Командира Мар'аліта. Вона приєдналася до розвідувальної експедиції Бранна Бронзбірда до Вулик'Реґалу, щоб вивчити відродження силітидів, і там стала жертвою темної стародавньої магії.",al={"хто така наталія","наталія мар'аліт","дружина командира мар'аліта"}},{q="Де знайти Наталію Мар'аліт?",a="Вона глибоко в тунелях комах Вулик'Реґалу на півдні Силітусу, стоїть на варті перед сяйливим кристалом, вкритим гліфами.",al={"місце наталії","де наталія","жриця вулика регал"}},{q="Чому Наталія ворожа до шукачів пригод?",a="Досліджуючи кристал кіраджі, Наталія була цілковито зіпсована й зламана шепотом Древнього Бога К'Туна. Тепер вона фанатично боронить кристал від кожного, хто входить до вулика.",al={"чому наталія напала на мене","чому наталія божевільна","наталію зомбовано"}},{q="Хто був із Наталією, коли вона зникла?",a="Вона вирушила до Вулик'Реґалу із Бранном Бронзбірдом, Рутґаром Ґліфшейпером і Франкалом Стоунбриджем. Рутґар і Франкал пережили це випробування й відступили до Табору Бронзоборода на півдні Силітусу, щоб розповісти про те, що сталося.",al={"експедиція наталії","хто був із наталією","бранн і наталія"}},{q="Чому вона така небезпечна в бою?",a="Наталія зберегла свою грізну жрецьку силу: вона раз у раз розганяє нападників Психічним Криком і відновлює сили майже дармовим Великим Зціленням, тож здолати її без постійного переривання заклинань дуже важко.",al={"бій з наталією","як перемогти наталію","лікування наталії"}}},fp="17,280,16.427.0,25.634.1,23.333.1,25.255.1,35.139.0,38.198.1,43.219.0,34.232.0"}
P.entries["npc:nathanos-blightcaller"] = {n="Натанос Блайткаллер",s="Натанос Блайткаллер, колись Натанос Марріс, стоїть на своєму зруйнованому обійсті у Східних Чумних землях як смертоносний чемпіон королеви Сильвани Віндраннер. За життя він був першим і єдиним серед людей Лордом-рейнджером Кель'Таласу, а в нежитті навчає мисливців-Відступників і стереже східне порубіжжя, зустрічаючи кожного, хто наблизиться, їдкою зневагою.",h="Натанос Блайткаллер, колись Натанос Марріс, стоїть на своєму зруйнованому обійсті у Східних Чумних землях як...",kw={"натанос блайткаллер","натанос марріс","сильвана","відступники","далекоходи","садиба марріса","мисливці"},ang={["class:Hunter"]="Натанос — найвищий за рангом наставник мисливців у Відступників: він приносить нежиті Лордерону суворе, легендарне стрілецьке мистецтво далекоходів Кель'Таласу.",["faction:Alliance"]="Бачити, як прославлений герой Лордерону й шанований далекохід б'ється під прапором Відступників, — болюча образа і смертельно небезпечна тактична проблема для Стормвінда.",["faction:Horde"]="Натанос дає Орді в Чумних Землях важливі тактичні поради й навчає мисливців, хоча до відвідувачів ставиться з уїдливою зневагою.",["race:Undead"]="Як чемпіон Темної Леді, Натанос втілює гірку стійкість Відступників, хоча до некомпетентності серед своїх у нього терпіння мало."},sec={{t="Єдиний далекохід серед людей",b="До Третьої війни Натанос Марріс був надзвичайним стрільцем і тактичним генієм із сільських околиць Лордерону. Його навчали високі ельфи Кель'Таласу, він був близький до Сильвани Віндраннер і став єдиною людиною, що будь-коли здобула престижне звання Лорда-рейнджера. Його домом лишався родинний маєток у Лордероні — Садиба Марріса."},{t="Загибель і відродження",b="Коли принц Артас і Погибель пронеслися Лордероном після очищення Стратгольма, чума поглинула королівство. Натанос відчайдушно оборонявся у своєму маєтку, але загинув від потворної гидоти Рамштайна Жеруна. Піднятий як бездумний раб-нежить, він блукав сплюндрованими полями, вбиваючи в ім'я Короля-Ліча. Коли Сильвана зламала владу Погибелі над розумом і заснувала Відступників в Андерсіті, вона прийшла по нього — як він якимось чином і знав — і вирвала його свідомість з-під волі Короля-Ліча, повернувши собі його тактичний хист і палку відданість."},{t="Чемпіон Королеви Баньші",b="Узявши прізвисько Блайткаллер, Натанос назавжди оселився в занедбаній Садибі Марріса. Він — чемпіон Сильвани, наставник мисливців і головний шпигун у спірних Східних Чумних землях, а охороняють його мерзенні чумні пси. Розвідка Альянсу з глибокою тривогою встановила, що він уцілів: Верховний Лорд Болвар Фордрагон вважає, що майстер тактики такого рівня на чолі сил нежиті — нестерпна загроза виживанню людства, і посилає ударні загони, щоб убити полеглого Лорда-рейнджера."}},faq={{q="Хто такий Натанос Блайткаллер?",a="Натанос Блайткаллер — колишній Натанос Марріс, знаменитий стрілець-людина й єдиний не ельф, якого будь-коли робили Лордом-Рейнджером Кель'Таласу. Після смерті й воскресіння під час Третьої війни Сильвана звільнила його розум від Погибелі. Тепер він її поборник і наставник мисливців у своєму родовому гнізді в Східних Чумних Землях.",al={"хто такий натанос","лор натаноса","хто біля хутора маррісів"}},{q="Чому Натанос на Хуторі Маррісів?",a="Хутір Маррісів був домом Натаноса за життя, і саме там він загинув, захищаючи Лордерон. Ставши нежиттю, він вирішив повернутися до свого зруйнованого маєтку й перетворив його на заставу, де навчає мисливців-Відступників і стежить за пересуваннями Альянсу й Погибелі.",al={"де натанос","чому натанос у чумних землях","хутір маррісів натанос"}},{q="Як Натанос став нежиттю?",a="Натаноса вбила на його хуторі під час Третьої війни гидота Погибелі Рамштайн Жерун. Він повстав як слухняний безвольний раб Короля-Ліча, аж поки по нього не прийшла Сильвана й не звільнила його розум, щоб він приєднався до Відступників.",al={"як натанос помер","хто вбив натаноса","смерть натаноса"}},{q="Чому Альянс хоче його вбити?",a="Очільники Альянсу в Стормвінді дізналися, що Натанос Марріс — один із найкращих воєнних умів і тактичних геніїв Альянсу — не загинув назавжди, а приєднався до Відступників. Вважаючи його тактичний хист величезною небезпекою, Верховний Лорд Болвар Фордрагон наказує його знищити.",al={"чому вбивати натаноса","завдання альянсу натанос","порядок має бути відновлений"}},{q="Які в нього стосунки із Сильваною?",a="Натанос був близький до Сильвани ще за життя, коли ельфи Кель'Таласу зробили його своїм єдиним Лордом-Рейнджером із людей, а тепер він її поборник. У нежитті його вірність Королеві Баньші лишається абсолютною й непохитною.",al={"сильвана й натанос","чи сильвана кохала натаноса","роман сильвани й натаноса"}},{q="Що за пси стоять біля нього?",a="Це люті чумні гончаки, яких Натанос вишколив сам. Він тримає їх поруч, щоб стерегли руїни Хутора Маррісів, і вони нападають на кожного, хто необачно вдереться на його землі.",al={"пси натаноса","хорти хутора маррісів","улюбленці блайткаллера"}}},fp="21,344,25.354.0,20.606.0,29.515.1,29.329.0,36.251.0,34.244.0,39.301.0,39.214.0,37.188.0"}
P.entries["npc:nida"] = {n="Гілері",s="Гілері — маленька дівчинка, що живе в прибережному містечку Лейкшир у Горах Редріджу. Упустивши в озеро дорогий подарунок від батька, вона з розпачу плаче на міській пристані.",h="Гілері — маленька дівчинка, що живе в прибережному містечку Лейкшир у Горах Редріджу.",kw={"гілері","намисто гілері","озеро незрушне","пристань","лейкшир","редрідж"},ang={["faction:Alliance"]="Хоч Гори Редріджу потерпають від куди більших бід, допомога Гілері повертає стривоженим мешканцям Лейкширу трішки тепла й безтурботності."},sec={{t="Загублена дитяча пам'ятка",b="Попри дедалі більшу загрозу навали гнолів і загонів орків Блекрок, що насідають на Лейкшир, діти містечка й досі мають свої дитячі клопоти. Гілері ненароком упустила в каламутні води Озера Незрушного намисто, яке подарував їй батько. Боячись, що тато на неї гніватиметься, засмучена дівчинка в сльозах чекає на міській пристані й сподівається, що знайдеться хтось досить сміливий, щоб пірнути в озеро й дістати його."}},faq={{q="Хто така Гілері?",a="Гілері — маленька дівчинка, що живе в Лейкширі в Горах Редріджу; її часто можна побачити заплаканою біля пристані.",al={"хто така гілері","гілері лейкшир","дівчинка що плаче лейкшир"}},{q="Чому Гілері плаче?",a="Гілері загубила дорогоцінне намисто, яке купив їй батько. Воно впало у води Озера Незрушне, і вона страшенно боїться батькового гніву, коли той помітить, що намиста немає.",al={"чому гілері плаче","чому вона сумна","плач гілері"}},{q="Хто намагається допомогти їй знайти намисто?",a="Її товариш з ігор Шон помічає, як вона засмучена, і просить перехожих шукачів пригод пірнути в Озеро Незрушне й дістати для неї затонуле намисто.",al={"хто допомагає гілері","друг гілері","хто дає завдання гілері"}},{q="Де лежить загублене намисто?",a="Намисто лежить під водою Озера Незрушне, біля міської пристані, де його впустила Гілері.",al={"місце намиста","намисто озеро незрушне"}}},fp="6,221,23.444.0,14.126.0,21.185.0,44.137.0,35.114.0"}
P.entries["npc:nikova-raskol"] = {n="Нікова Раскол",s="Нікова Раскол — літня містянка, людина, що блукає бруківкою Старого Міста в Стормвінді. Оплакуючи онука, якого вбило Братство Дефіас, вона прагне справедливої відплати злочинцям, які збунтувалися за ґратами В'язниці.",h="Нікова Раскол — літня містянка, людина, що блукає бруківкою Старого Міста в Стормвінді.",kw={"нікова раскол","старе місто","братство дефіас","в'язниця","помста","стормвінд"},ang={["faction:Alliance"]="Для героїв Альянсу, що навідуються до Стормвінда, допомога Нікові нагадує: захищати королівство — означає берегти й простих містян, чиї родини розірвали внутрішні негаразди."},sec={{t="Бабусине горе",b="Нікова блукає Старим Містом, несучи тягар недавньої страшної трагедії. Її улюбленого онука Мака вбили розбійники з Братства Дефіас. Поки королівство бореться зі зрадою на рівні високої політики, Нікова уособлює ту людську ціну, яку беззаконна навала Братства стягує зі звичайних містян."},{t="Помста у В'язниці",b="Хоча чимало злочинців, що сіяли хаос, спіймали й кинули до В'язниці, тепер ґрати мало тішать: жорстокий бунт в'язнів захопив тюрму. Розчарована тим, що вартові не можуть навести лад, Нікова звертається просто до відважних шукачів пригод, які прямують до в'язниці, й просить принести червоні пов'язки Дефіас — доказ, що вбивці її онука нарешті поплатилися."}},faq={{q="Хто така Нікова Раскол?",a="Нікова Раскол — літня мешканка Стормвінда, що ходить овальною вулицею Старого Міста. Вона оплакує онука Мака, якого вбили головорізи Дефіас.",al={"хто така нікова","роль нікови раскол","лор нікови раскол"}},{q="Що сталося з її онуком Маком?",a="Мака холоднокровно вбили члени Братства Дефіас. Чимало винних опинилися у В'язниці Стормвінда, де згодом підняли бунт.",al={"що сталося з маком","хто такий мак","як помер мак"}},{q="Навіщо їй червоні пов'язки з В'язниці?",a="Червона пов'язка — розпізнавальний знак Братства Дефіас. Нікова просить бійців, що йдуть до охопленої бунтом В'язниці, принести ці хустки як доказ, що злочинців, які забирали невинні життя, покарано.",al={"колір крові","навіщо червоні пов'язки","пов'язки дефіас"}},{q="Де знайти Нікову Раскол?",a="Нікова без упину ходить по колу головною вулицею Старого Міста, неподалік від таверни «Свиня і Свисток» і тренувального майданчика в Стормвінді.",al={"де нікова","місце нікови","шлях нікови раскол"}}},fp="13,262,21.350.0,25.419.0,21.155.0,34.166.0,49.246.0,33.154.0"}
P.entries["npc:nissa-firestone"] = {n="Нісса Файрстоун",s="Нісса Файрстоун — дворфійська лікарка, що працює над гамором Великої Кузні в Айронфорджі. Вона навчає польової медицини, показуючи мандрівникам і солдатам, як перев'язувати рани й допомагати при травмах.",h="Нісса Файрстоун — дворфійська лікарка, що працює над гамором Великої Кузні в Айронфорджі.",kw={"нісса файрстоун","перша допомога","лікарка","бинти","велике горно","айронфордж"},ang={["faction:Alliance"]="Кожен шукач пригод Альянсу, що проходить через Каз Модан, покладається на наставників на кшталт Нісси, щоб опанувати важливі навички виживання без божественної чи арканної магії.",["race:Dwarf"]="Для дворфів, що повертаються із сутичок із трогами чи морозними тролями, Нісса уособлює практичний, тверезий підхід медичної традиції Айронфорджа."},sec={{t="Цілителька над ковадлами",b="Серед брязкоту металу й пекучого жару Великої Кузні Нісса Файрстоун лікує на верхньому поверсі крамниці «Лікар Айронфорджа». Дворфійські воїни славляться витривалістю, але навіть тверда, мов камінь, шкіра розходиться під клинком і пазуром. Нісса дбає, щоб ті, хто вирушає в сніги Дун Мороґа чи далі, вміли зберегти життя собі й союзникам простими перев'язками й польовими пов'язками."},{t="Сортування поранених і складні травми",b="Нісса бачить, коли польовий медик, що опанував основи роботи з тканиною й корпією, переростає її лікарню. Коли учні доходять межі того, чого вона може навчити, вона скеровує їх до фахівців із сортування поранених на далеких заставах — туди, де Альянс зазнає найбільших утрат."}},faq={{q="Хто така Нісса Файрстоун?",a="Нісса Файрстоун — дворфійка, наставниця першої допомоги, що працює в крамниці «Лікар Айронфорджа» на південному краю Великої Кузні.",al={"хто така нісса файрстоун","роль нісси файрстоун","тренер першої допомоги айронфорджа"}},{q="Де знайти Ніссу Файрстоун?",a="Вона на верхньому поверсі крамниці «Лікар Айронфорджа», що стоїть на південному краю кільця Великої Кузні в Айронфорджі.",al={"місце нісси файрстоун","де нісса","лікарка айронфорджа"}},{q="Чого навчає Нісса Файрстоун?",a="Вона навчає шукачів пригод Альянсу ремесла першої допомоги — як готувати бинти й протиотрути, щоб лікувати рани, отримані в польових умовах.",al={"чого навчає нісса","перша допомога айронфордж","вивчити бинти айронфордж"}},{q="Чи може Нісса навчити майстерного сортування поранених?",a="Ні. Коли лікар досягає високої майстерності, Нісса посилає його далі із завданням «Травми Альянсу» — до досвідчених польових хірургів, що працюють біля гарячих точок війни.",al={"завдання травми альянсу","майстерна перша допомога айронфордж","перша допомога понад 225"}}},fp="15,214,25.427.0,26.329.0,23.148.0,33.138.0,32.156.0,36.184.0"}
P.entries["npc:nogg"] = {n="Ноґґ",s="Ноґґ — гоблін-інженер, що має майстерню в Долині Честі в Оргріммарі. Він пропонує Орді свої знання й особливу майстерність, зокрема розбирається з дивними механічними знахідками, винесеними з глибин Гномреґана.",h="Ноґґ — гоблін-інженер, що має майстерню в Долині Честі в Оргріммарі.",kw={"ноґґ","гоблін","інженер","долина честі","оргріммар","гномреґан"},ang={["faction:Horde"]="Для воїнів Орди, що повертаються з небезпечних походів до Східних Королівств, Ноґґ перетворює грубі знахідки на точно налаштоване бойове спорядження.",["profession:Engineering"]="Колеги-інженери часто заходять до майстерні Ноґґа в Долині Честі по деталі, поговорити про ремесло й подивуватися, як легко гоблінські руки переробляють хитромудру гномську техніку."},sec={{t="Майстерня Ноґґа",b="У затишному куточку Долини Честі в Оргріммарі Ноґґ тримає незалежну інженерну майстерню, де раді і шукачам пригод, і ремісникам. Хоча місто довкола покладається переважно на традиційну орочу сталь і грубу силу, Ноґґ пропонує ту особливу механічну тонкість, на яку здатен лише гоблін. Він жваво цікавиться чужоземними пристроями й технікою та охоче оглядає дивні дрібнички й механічні дивовижі, принесені з земель Альянсу чи з підземних руїн."},{t="Гномські пристрої й знахідки",b="Особливо Ноґґа цікавлять речі з полеглої гномської столиці Гномреґана. Коли агенти Орди приносять хитромудрі персні чи рештки техніки з опромінених сховищ за морем, Ноґґ — один із небагатьох у Дуротарі, хто здатен розібрати, розгадати й переробити такі химерні годинникові механізми для потреб Орди."}},faq={{q="Де знайти Ноґґа?",a="Ноґґ — у Долині Честі в Оргріммарі, де він тримає власну інженерну майстерню.",al={"місце ноґґа","де ноґґ","майстерня ноґґа"}},{q="Що пов'язує Ноґґа з Гномреґаном?",a="Коли шукачі пригод Орди спускаються в заражені тунелі Гномреґана в Каз Модані, вони можуть добути там хитромудрі технологічні дрібнички. Ноґґ — місцевий знавець в Оргріммарі, який оглядає й переналаштовує ці чужі гномські персні.",al={"чому ноґґ гномреґан","перстень ноґґа","повернення персня"}},{q="Чи належить Ноґґ до Орди?",a="Ноґґ — незалежний гоблін-майстер, що працює просто в Оргріммарі, охоче служить шукачам пригод Орди й віддає свій технічний хист їхній воєнній справі.",al={"чи ноґґ з орди","фракція ноґґа"}},{q="Чи може Ноґґ змінити чи перекувати персні?",a="Так. Якщо шукач пригод принесе йому перстень, здобутий зі Спарклматика в Гномреґані, і захоче інших чар чи механічних властивостей, Ноґґ знає, як розібрати й перезібрати виріб, щоб той краще пасував власникові.",al={"перекувати перстень","змінити перстень гномреґана"}}},fp="4,248,15.481.0,27.354.0,22.100.0,40.235.0,26.163.0,32.217.0"}
P.entries["npc:nori-pridedrift"] = {n="Норі Прайддріфт",s="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною Холодного Хребта. Він заробляє на життя, кидаючи виклик холоду, щоб постачати змерзлим горянам їхню ранкову підбадьорливу порцію, і часто наймає прудких новобранців розносити напій, поки той ще парує.",h="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною...",kw={"норі прайддріфт","ранковий узвар","дворф","кухоль","доставка","долина холодного хребта","гарячий напій"},ang={["profession:Cooking"]="Кулінари-мандрівники в Дун Мороґу цінують відданість Норі, який подає свій фірмовий напій обпікаюче гарячим попри крижане повітря довкола.",["race:Dwarf"]="Кожен дворф розуміє життєво важливу втіху від міцного напою на морозі, тож гарячий Ранковий Узвар Норі — жаданий гість на гірських постах варти."},sec={{t="Паруючий кухоль у снігу",b="Життя в Долині Холодного Хребта суворе й люто холодне, і ніщо не пробиває мороз так, як ковток Гарячого Ранкового Узвару. Норі Прайддріфт заробляє на життя тим, що варить і розносить цей гарячий, схожий на каву ранковий напій замерзлими заметами. Оскільки узвар треба пити ще обпікаючим, щоб повністю його оцінити, доставка — це перегони зі стихією. Норі часто наймає прудких кур'єрів бігти зі свіжими порціями до змерзлих вартових, перш ніж гірське повітря забере в напою тепло. Не менш важливий за сам узвар і його обмежений запас міцних кухлів, які він вимагає від своїх гінців повертати негайно."}},faq={{q="Хто такий Норі Прайддріфт?",a="Норі Прайддріфт — заповзятливий дворф-рознощик із Долини Холодного Хребта. Він варить і продає Пекучий Ранковий Відвар — гарячий напій на кшталт кави, що зігріває місцевих вартових і гірників.",al={"хто такий норі","лор норі прайддріфта","торговець пекучим ранковим відваром"}},{q="Що таке Пекучий Ранковий Відвар?",a="Пекучий Ранковий Відвар — особливий гарячий напій, який варить Норі Прайддріфт. Схожий на окріп-каву чи пряний ранковий ель, він дуже до вподоби мешканцям долини, бо проганяє лютий холод Дун Мороґу.",al={"пекучий ранковий відвар","який напій продає норі","ранковий відвар"}},{q="Чому доставки такі термінові?",a="Уся принадність напою в тому, що він гарячий. На морозних гірських вітрах Долини Холодного Хребта кухоль швидко холоне, тож гінці Норі мусять щодуху бігти до спраглих покупців.",al={"чому доставки термінові","поспіх доставки відвару","чому напій холоне"}},{q="Чому Норі так переймається поверненням кухлів?",a="У Норі в долині обмежений запас кухлів. Якщо покупці розходяться з ними чи розбивають їх у заметах, його ранкова торгівля швидко зупиняється.",al={"чому повертати кухлі","кухлі норі","повернення кухлів"}}},fp="15,301,26.649.0,23.186.0,26.211.0,29.207.0,48.181.0"}
P.entries["npc:oben-rageclaw"] = {n="Обен Рейджклов",s="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва Бан'етіл у Тельдрассилі. Поки його дух тиняється в пастці курганного лігва, його сплячу тілесну оболонку підкорила огидна магія фурболгів.",h="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва...",kw={"обен рейджклов","друїд","дух","курганне лігво бан'етіл","вузлошкіри","фурболги","смарагдовий сон"},ang={["class:Druid"]="Доля Обена — болісне нагадування про вразливість друїдів під час трансу єднання зі Смарагдовим Сном, коли священні курганні лігва лишаються без захисту.",["race:NightElf"]="Споганення Обена Рейджклова фурболгами Вузлошкірів показує, як глибоко скверна вразила корінних мешканців і священні святилища Тельдрассила."},sec={{t="Споганений сон",b="Як і багато Друїдів Пазура, Обен Рейджклов усамітнився в підземному святилищі Курганного Лігва Бан'етіл, щоб єднатися з природою й блукати Смарагдовим Сном. Та коли тутешні фурболги Вузлошкірів піддалися скверні й заполонили кургани, Обен, занурений у транс, виявився цілком беззахисним. Замість просто вбити його, споганений шаман Вузлошкірів темними обрядами захопив владу над його непритомним смертним тілом, і витіснений дух лишився тинятися змученим привидом, нездатним ні відійти, ні прокинутися."},{t="Розрив із посудиною",b="Не маючи змоги відвоювати власну плоть із поневолення шамана, Обен покладається на мандрівників, що прокладають шлях небезпечними тунелями, аби ті поклали край його мукам. Лише знайшовши й знищивши його тіло-маріонетку, можна розірвати його смертні пута. Щойно викрадену посудину повалено, замучений привид Обена нарешті звільняється з підземної пітьми, щоб знайти вічний спокій у Смарагдовому Сні."}},faq={{q="Хто такий Обен Рейджклов?",a="Обен Рейджклов — нічний ельф, Друїд Пазура, чий привид блукає Курганним Лігвом Бан'етіл на Тельдрассилі, відколи зіпсовані фурболги відірвали його від тіла.",al={"хто такий обен","лор обена рейджклова","дух у барлозі"}},{q="Чому Обен Рейджклов став привидом?",a="Поки Обен спав у глибокому друїдському трансі, спілкуючись зі Смарагдовим Сном, шамани фурболгів-вузлошкірів пробралися до лігва й наклали на його тіло мерзенні чари: заволоділи ним, а його дух лишили назовні примарою.",al={"чому обен привид","чому обен мертвий","як обен помер"}},{q="Де тіло Обена?",a="Його тіло лежить глибше у звивистих коридорах Курганного Лігва Бан'етіл, під охороною й владою шаманів-вузлошкірів, що осквернили лігво.",al={"знайти тіло обена","де тіло обена","місце сплячого друїда"}},{q="Що стається, коли тіло Обена знищено?",a="Знищення тіла-маріонетки зламує темну владу шаманів-вузлошкірів над ним, і його дух може спокійно покинути Тельдрассил і навіки спочити в Смарагдовому Сні.",al={"доля обена","що буде з духом обена","порятунок обена"}}},fp="13,260,20.516.0,19.384.1,21.166.0,29.225.0,30.155.0,44.169.1"}
P.entries["npc:oggleflint"] = {n="Оґґлфлінт",s="Оґґлфлінт — ватажок племені трогів, що живе у вулканічних глибинах Провалля Лютого Вогню просто під Оргріммаром. Колись володар усієї підземної печери, він і його родичі були відтиснуті до верхніх тунелів культистами Пекучого Клинка, що прийшли сюди. Тепер він окопався біля входу, керує своєю дикою зграєю й становить безпосередню загрозу для столиці Орди нагорі.",h="Оґґлфлінт — ватажок племені трогів, що живе у вулканічних глибинах Провалля Лютого Вогню просто під...",kw={"оґґлфлінт","троги","провалля лютого вогню","оргріммар","ватажок"},ang={["class:Warrior"]="Вийти проти Оґґлфлінта — означає зійтися з важким громилом, що покладається лише на м'язи й первісну лють, а не на обладунки чи дисципліну.",["faction:Horde"]="Троги Оґґлфлінта, що живуть просто під фортецею Тралла, — дика, непередбачувана загроза безпеці в самому серці Дуротара.",["race:Orc"]="Для молодих орків, що доводять свою силу у випробуванні зброєю, вбивство ватажка, який чатує просто під Проходом, — одне з перших випробувань бойової дисципліни."},sec={{t="Ватажок глибин",b="Доки культисти тіні не проникли в провалля під Оргріммаром, Оґґлфлінт і його троги безроздільно панували у вогняних підземних тунелях. Жорстокі й ревниві до своєї території, вони вирізали собі примітивне володіння серед розпеченого каміння. Хоч троги майже не знають цивілізації, Оґґлфлінт тримав над зграєю цілковиту владу самою лише грубою силою."},{t="Витіснені культом",b="Рівновага сил під містом розбилася, коли Пекучий Клинок оселився в найглибших залах Провалля Лютого Вогню. Не в змозі протистояти темній магії й злагодженим фанатикам культу, Оґґлфлінт змушений був поступитися нижніми тунелями. Відступивши нагору, ватажок трогів тепер чатує біля входу в печеру, нападаючи на будь-яких чужинців і плекаючи образу на зайд унизу."},{t="Загроза під Оргріммаром",b="Витіснені троги просто під столицею Тралла — небезпека, якої Орда не може терпіти. Відтиснуте ближче до поверхні плем'я Оґґлфлінта надто непередбачуване, щоб лишати його без нагляду: воно загрожує вихлюпнутися в Прохід і Тіньову Розколину, якщо його не зупинити."}},faq={{q="Хто такий Оґґлфлінт?",a="Оґґлфлінт — могутній вождь трогів, що очолює зграю, яка живе в Проваллі Лютого Вогню під містом Оргріммар.",al={"оґґлфлінт","хто такий оґґлфлінт","бос трогів лютого вогню"}},{q="Де знайти Оґґлфлінта?",a="Він у верхніх печерах Провалля Лютого Вогню, неподалік від вхідного тунелю, де його вцілілий клан отаборився, коли його витіснили з глибин.",al={"де оґґлфлінт","місце оґґлфлінта","знайти оґґлфлінта"}},{q="Що троги роблять у Проваллі Лютого Вогню?",a="Троги від природи живуть глибоко під землею, у підземних вулканічних мережах. Зграя Оґґлфлінта зайняла вогняні печери під Дуротаром задовго до того, як прийшов культ Пекучого Клинка.",al={"чому троги під оргріммаром","лор трогів лютого вогню"}},{q="Чому Оґґлфлінт ворожий до Орди?",a="Троги від природи люті й ревно бережуть свої землі. Витіснені культистами ближче до поверхні, Оґґлфлінт і його поплічники становлять безпосередню загрозу для тунелів Орди й міста вгорі.",al={"чому вбивати оґґлфлінта","чому воювати з оґґлфлінтом"}},{q="Які в Оґґлфлінта стосунки з Пекучим Клинком?",a="Вони запеклі вороги. Культисти Пекучого Клинка вдерлися до Провалля Лютого Вогню й здолали трогів Оґґлфлінта, витіснивши тих, хто вцілів, у верхні печери.",al={"пекучий клинок і оґґлфлінт","чи троги з культом"}}},fp="10,398,21.372.0,21.392.0,28.262.0,18.116.0,30.168.0,37.178.0,39.194.0,57.155.0"}
P.entries["npc:ogtinc"] = {n="Оґтінк",s="Оґтінк — незалежний мисливець-фурболг, що отаборився на високому гребені над Руїнами Елдарата в Азшарі. Розійшовшись зі своїм племенем, щоб служити рівновазі природи, він став надійним союзником і наставником для Кола Кенарія. Досвідчені мисливці, які хочуть випробувати своє вміння на найлютіших звірах Калімдору, часто шукають його порад.",h="Оґтінк — незалежний мисливець-фурболг, що отаборився на високому гребені над Руїнами Елдарата в Азшарі.",kw={"оґтінк","фурболг","коло кенарія","мисливці","руїни елдарата","азшара","трофеї"},ang={["class:Druid"]="Як вірний партнер Кола Кенарія, Оґтінк — рідкісний міст між дикою мудрістю фурболгів, не зачеплених порчею, і турботою друїдів про природу.",["class:Hunter"]="Оґтінк пропонує досвідченим мисливцям глибокі духовні й практичні випробування, перевіряючи їхню влучність і вміння виживати в боротьбі з найнебезпечнішими істотами Калімдору."},sec={{t="Фурболг-одинак",b="Більшість фурболгів Калімдору й досі тісно пов'язані зі своїми племенами — або піддалися порчі після Третьої війни, — та Оґтінк обрав інший шлях. Покинувши родичів, він присвятив свій лук і знання про виживання допомозі Колу Кенарія. Його табір стоїть високо на кручі на південний схід від Твердині Деревопащих, звідки він пильно наглядає за прадавніми розтрощеними землями Азшари."},{t="Майстер полювання",b="Серед досвідчених слідопитів Оґтінк славиться глибоким знанням дикої природи Калімдору. Він випробовує мисливців, що відточили майстерність на різних континентах, посилаючи їх по рідкісні трофеї — роги прудконогих звірів, луску морських змій із бурхливих хвиль і частини тіл зелених драконів. Цими випробуваннями він учить, що справжнє полювання шанує природу й береже рівновагу, а не забирає життя бездумно."}},faq={{q="Хто такий Оґтінк?",a="Оґтінк — вправний фурболг-мисливець, що отаборився на кручах Азшари. На відміну від більшості своїх відлюдних чи зіпсованих побратимів, він покинув рідне плем'я, щоб служити своїм мисливським хистом і мудрістю друїдам Кола Кенарія.",al={"хто такий оґтінк","лор оґтінка","фурболґ в азшарі"}},{q="Де знайти Оґтінка?",a="Він в Азшарі, у таборі на кручі над стародавніми Руїнами Елдарата, трохи на південний схід від Твердині Деревопащих.",al={"де оґтінк","місце оґтінка","як знайти оґтінка"}},{q="Чому Оґтінк покинув своє плем'я?",a="Оґтінк покинув родичів саме для того, щоб допомагати Колу Кенарія берегти природу. Хоча з якого він племені, точно не сказано, його ясний розум і мирна вдача різко відрізняють його від зіпсованих племен в інших куточках північного Калімдору.",al={"чому оґтінк покинув плем'я","плем'я оґтінка","чи оґтінк деревопад"}},{q="Яку роль Оґтінк відіграє для мисливців?",a="Оґтінк — наставник для досвідчених мисливців, що дійшли до вершини свого навчання. Він доручає їм вистежувати грізних звірів по всьому Калімдору — від прудких скакунів до виводку зеленого драконячого роду, — щоб довести своє панування над дикою природою.",al={"завдання мисливців оґтінка","тренер мисливців оґтінк","навіщо йти до оґтінка"}},{q="Чи пов'язаний Оґтінк із Твердинею Деревопащих?",a="Хоча він таборує біля Твердині Деревопащих, Оґтінк діє незалежно, у прямому союзі з Колом Кенарія. Він привітний до мандрівників, що приходять із миром, хоч би якою була їхня репутація в племені Деревопащих.",al={"оґтінк деревопади","репутація деревопадів оґтінк","чи оґтінк дружній"}},{q="Чому Оґтінк стежить за Руїнами Елдарата?",a="З його місця високо над руїнами добре видно неспокійні нетрі внизу, де наги, елементалі й відлуння давньої магії загрожують хиткій рівновазі прибережного лісу.",al={"чому оґтінк в азшарі","елдарат оґтінк","скеля оґтінка"}}},fp="6,350,15.381.0,18.456.0,14.243.0,26.137.0,31.267.0,39.257.0,41.231.0,49.209.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="Оґунаро Вульфраннер",s="Оґунаро Вульфраннер — найкращий заводчик вовків Орди й доглядач псарні в Оргріммарі; його місце — біля Зали Мисливця в Долині Честі. Він доглядає лютих вовків, обраних нести в бій оркських поборників і їхніх вірних союзників. Досвідченим вершникам, що прагнуть порозумітися з верховними хижаками Дуротару, варто йти саме до Оґунаро.",h="Оґунаро Вульфраннер — найкращий заводчик вовків Орди й доглядач псарні в Оргріммарі; його місце — біля Зали...",kw={"оґунаро вульфраннер","вовки","верховий звір","зала мисливця","долина честі","дренор"},ang={["faction:Horde"]="Тролі, таурени й Відступники мусять довести Оргріммару свою відданість і честь, перш ніж Оґунаро довірить їм бойового вовка.",["race:Orc"]="Для орків їзда на вовках — родова традиція, що сягає кланів Дренору; Оґунаро — охоронець цього священного бойового зв'язку."},sec={{t="Ватажок зграї",b="Біля Зали Мисливця в Долині Честі Оґунаро Вульфраннер керує розведенням і вишколом бойових вовків Оргріммара. Зв'язок між орком і вовком тягнеться поколіннями — з рівнин Дренору до диких нетрів Дуротару — і це союз взаємної поваги, а не просте приручення. Оґунаро стежить, щоб найвитриваліших і найлютіших звірів — від грізних велетенських вовків до моторних лісових — довіряли лише воїнам, що довели свою силу й гідність перед вождем."}},faq={{q="Хто такий Оґунаро Вульфраннер?",a="Оґунаро Вульфраннер — головний розводчик вовків і продавець їздових тварин Орди; його можна знайти біля Зали Мисливця в Долині Честі Оргріммара.",al={"оґунаро","торговець вовками оргріммар","торговець орківськими їздовими"}},{q="Чи кожен може купити в нього вовка?",a="За правом походження орки можуть вільно придбати вовків, щойно навчаться їзди. Іншим членам Орди треба здобути звеличення й найвищу довіру Оргріммара, перш ніж Оґунаро віддасть їм одного зі своїх цінних звірів.",al={"чи не орки можуть купити вовка","вимоги репутації для вовка"}},{q="Яких вовків він пропонує?",a="Оґунаро тримає різноманітну псарню загартованих у боях їздових вовків — чорних, бурих, лютововків і лісових вовків, — а також прудких броньованих порід для ветеранів війни.",al={"види вовків-їздових","яких вовків продає оґунаро"}}},fp="18,331,18.525.0,26.142.0,36.212.0,37.167.0"}
P.entries["npc:old-murk-eye"] = {n="Старий Мутноокий",s="Старий Мутноокий — сумнозвісний, загартований у боях мурлок, що нишпорить південним узбережжям Вестфолу. Шанований серед своїх і страшний для прибережних моряків, він становить смертельну загрозу для кожного, хто забреде до Маяка Вестфолу.",h="Старий Мутноокий — сумнозвісний, загартований у боях мурлок, що нишпорить південним узбережжям Вестфолу.",kw={"старий мутноокий","мурлок","маяк вестфолу","капітан ґрейсон","луска","вестфол"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, які очищають Вестфол, знищення Старого Мутноокого позбавляє край сумнозвісного хижака, що полює на корабельні команди й мандрівників, які застрягли на березі."},sec={{t="Жах узбережжя",b="Мурлоки на берегах Вестфолу — звична напасть, але Старий Мутноокий вирізняється з-поміж дрібніших падальників. Значно міцніший і набагато агресивніший за родичів, цей посивілий звір нишпорить у прибої довкола Маяка Вестфолу. Він завдав стільки горя місцевим морякам, що примарний Капітан Ґрейсон прагне його смерті й обіцяє винагороду за бездоганну луску потвори, щоб звільнити мілини від її влади."}},faq={{q="Де блукає Старий Мутноокий?",a="Він обходить піщані береги й мілини на південному заході Вестфолу, просто вздовж узбережжя біля Маяка Вестфолу.",al={"місце старого мутноокого","де знайти старого мутноокого","де мутноокий"}},{q="Чому Капітан Ґрейсон хоче смерті Старого Мутноокого?",a="Капітан Ґрейсон вважає Старого Мутноокого постійною загрозою для прибережних вод. Щоб приборкати насильство на пляжі, він оголошує нагороду за цього легендарного мурлока й вимагає луску як доказ.",al={"ґрейсон мутноокий","чому вбивати старого мутноокого"}},{q="Чи Старий Мутноокий відрізняється від звичайних мурлоків?",a="Так. Він помітно сильніший, витриваліший і лютіший за підручних Берегоходів і Мисливців Припливу довкола нього й верховодить серед місцевих прибережних зграй.",al={"наскільки міцний мутноокий","чи мутноокий елітний"}}},fp="12,229,23.451.0,31.127.0,48.203.0,48.184.0"}
P.entries["npc:old-serra-kis"] = {n="Старий Серра'кіс",s="Старий Серра'кіс — давній велетенський трешадон, що живе в затоплених підземних водах Чорноглибинних Печер. Культисти Молота Присмерку, що вторглися сюди, винищили на харч більшість водних мешканців храму, але полювання на цього велетенського звіра виявилося смертельно небезпечним.",h="Старий Серра'кіс — давній велетенський трешадон, що живе в затоплених підземних водах Чорноглибинних Печер.",kw={"старий серра'кіс","трешадон","чорноглибинні печери","підводна печера","молот присмерку"},ang={["class:Druid"]="Друїдам дикої природи Водяна форма стане незамінною, коли доведеться пірнати в непроглядний ставок, щоб зійтися з цим доісторичним хижаком.",["class:Shaman"]="Закляття «Підводне дихання», дароване духовним єднанням зі стихіями, не дасть вашим супутникам потонути, поки ви боретеся з давнім хижаком.",["class:Warlock"]="Чорнокнижникове закляття «Нескінченний подих» перетворює смертельну безповітряну підземну засідку на цілком подоланний бій."},sec={{t="Нескорений у глибинах",b="Коли культисти Молота Присмерку спустилися до затонулих Руїн Місячної Святині, вони перебили місцевих підводних звірів собі на поживу. Та під Святилищем Місячної Святині одна первісна істота не захотіла ставати здобиччю. Старий Серра'кіс, найбільший трешадон затонулого храму, швидко розправлявся з кожним культистом, що мав зухвалість націлити на нього спис. Зрештою мисливці відступилися, і давній хижак лишився у своїх водяних володіннях сам."},{t="Прихована загроза",b="Щоб дістатися Старого Серра'кіса, треба пірнути глибоко під підлогу храму, у затоплену печеру під руїнами. Повітряних кишень там немає, тож сама печера не менш смертоносна, ніж звір у ній. Ті, хто заганяє його в кут, дізнаються, що Серра'кіс має неприродну тіньову живучість: він висмоктує життя з нападників, підтримуючи власні сили в каламутній темряві."}},faq={{q="Що за створіння Старий Серра'кіс?",a="Старий Серра'кіс — величезний стародавній трешадон, довгошия водяна рептилія, що водиться в озерах і прибережних водах Азероту.",al={"що таке серра'кіс","чи серра'кіс гідра","вид серра'кіса"}},{q="Чому Молот Присмерку його не вбив?",a="Культ вибив більшість водяних створінь під Руїнами Місячної Святині на їжу, але Серра'кіс виявився надто сильним і хитрим. Культисти, які вперто намагалися на нього полювати, неминуче самі ставали його обідом, тож культ узагалі обходить його печеру стороною.",al={"чому серра'кіс живий","молот присмерку серра'кіс"}},{q="Де перебуває Старий Серра'кіс?",a="Він чатує в затопленій печері під водою довкола Святилища Місячної Святині в Чорноглибинних Печерах. Щоб зустрітися з ним, плавцям доводиться пірнути під руїни, у водойму без повітря.",al={"як знайти серра'кіса","місце серра'кіса","де старий серра'кіс"}},{q="Чим небезпечний бій із ним?",a="Мало того, що битися доводиться цілком під водою, де немає повітряних кишень, — Старий Серра'кіс ще й висмоктує тіньову енергію з усіх ворогів поблизу, щоб загоювати власні рани впродовж бою.",al={"здібності серра'кіса","як перемогти серра'кіса"}},{q="Чи служить Серра'кіс Молотові Присмерку?",a="Ні. На відміну від інших звірів, яких культ зіпсував чи вишколив, Старий Серра'кіс лишається цілком диким хижаком, що боронить своє підводне лігво.",al={"чи серра'кіс улюбленець культистів","хто керує серра'кісом"}},{q="Чи можна дихати під час бою із Серра'кісом?",a="У його замкненій печері під склепінням немає повітряних кишень, тож підводним бійцям доводиться або берегти подих, або вдаватися до магічного дихання під водою, або виманювати звіра на відкриту воду.",al={"тонути серра'кіс","дихання під водою серра'кіс"}}},fp="13,285,25.465.0,15.368.0,39.130.0,42.257.0,31.183.0,34.166.0,43.147.0,49.181.0"}
P.entries["npc:onyxia"] = {n="Оніксія",s="Оніксія — матір виводку чорних драконів і підступна донька Детвінга. Причаївшись у своєму драконячому лігві в Багні Пилоброду, вона доглядає свій зростаючий виводок і разом зі своєю зловісною зграєю прагне панувати над світами смертних.",h="Оніксія — матір виводку чорних драконів і підступна донька Детвінга.",kw={"оніксія","чорні дракони","катрана престор","багно пилоброду","стормвінд","детвінг"},sec={{t="Матір виводку при дворі",b="Поки її брат Нефаріан збирає армії в Шпилі Блекрок, Оніксія йде до влади хитрістю. Прибравши личину Леді Катрани Престор, вона пролізла в найвищі кола знаті Стормвінда. Удаючи довірену радницю Дому Вельмож, вона планомірно підточує воєнні зусилля королівства, навмисно не даючи солдатів і припасів заставам у Вестфолі, Редріджі та Палаючих Степах, щоб лишити світи смертних беззахисними."},{t="Архітекторка руїни",b="За намальованими усмішками Леді Престор ховається хижий розум, що стоїть за найболючішими трагедіями Стормвінда. Саме Оніксія розпалила запеклу суперечку між Гільдією Каменярів і Домом Вельмож, що призвела до смертельного бунту, у якому загинула королева Тіффін Рінн. Тепер, коли короля Варіана викрали дорогою на мирну зустріч у Тераморі, Престор має глибокий вплив на юного короля-хлопчика Андуїна й обплутала своїми тенетами Верховного Лорда Болвара Фордрагона, і трон уже хитається в її пазурах."}},faq={{q="Хто така Леді Катрана Престор?",a="Леді Катрана Престор — шляхетна пані зі Стормвінда й довірена радниця при дворі. Поки Король Варіан зник, вона стоїть поруч із юним королем Андуїном і Верховним Лордом Болваром Фордрагоном у Фортеці Стормвінда, і її поради мають велику вагу в Домі Вельмож.",al={"особа престор","хто така престор","справжня особа катрани престор"}},{q="Чому Оніксія обрала своєю ціллю Стормвінд?",a="Оніксія вважає людей тим смертним народом, що найкраще здатен кинути виклик драконам. Вона прагне підкорити королівство Стормвінд владі чорного драконячого роду, знешкодити його військову силу й допомогти своєму братові Нефаріану панувати в цьому краї.",al={"мета оніксії","чому напад на стормвінд","мотив престор"}},{q="Де живе Оніксія?",a="Домівка Оніксії — підземне лігво серед боліт Багна Пилоброду, де вона доглядає кладки яєць чорного драконячого роду.",al={"де оніксія","місце оніксії","лігво оніксії"}},{q="Що пов'язує її з Нефаріаном і Детвінгом?",a="Оніксія — донька Аспекта Детвінга та його подруги Сінтарії. Вона також молодша сестра-близнючка Нефаріана й тісно співпрацює з ним, щоб відновити панування чорного драконячого роду в Азероті.",al={"брат оніксії","батько оніксії","родина оніксії"}}},fp="6,267,28.488.1,17.522.2,28.254.2,33.250.2,23.138.2,49.209.0"}
